QustCN_Data_CN = {
[1] = {"坎瑞萨德的任务","与坎瑞萨德交谈，回复你的天赋、武器、与坐骑。","欢迎你从死亡的世界归来。在过去的时代你骄傲的挺立，是你族人之中的英雄。而现在你既堕落又破碎不过是个过去的遗物。站到我面前吧，我将唤醒你过去的荣光。我会回复你失去的力量，让你再次完整归一。","小武哥儿"},
[2] = {"沙普塔隆的爪子","将沙普塔隆的爪子交给灰谷碎木哨岗的塞娜尼·雷心。","强大的角鹰兽沙普塔隆已经被你杀死了，它的爪子将成为你胜利的象征。碎木哨岗的塞娜尼·雷心一定会对你的战利品感兴趣的。","小武哥儿"},
[5] = {"饥肠辘辘的基特斯","和厨师格鲁奥谈一谈。","我已经困在这个鬼镇里好几个星期了，除了虫子和野草之外什么吃的都没有！我想吃点正常的食物，即使要多花点钱也无所谓。给我找点美食来，我就给你大笔的奖赏。听说夜色镇血鸦旅店的厨师格鲁奥做的黑蟹蛋糕很不错……","小武哥儿"},
[6] = {"加瑞克·护足的赏金","杀死加瑞克·护足，带着他的头到北郡修道院去找维里副队长。","加瑞克·护足，几周以来这个恶棍一直让我们的农民和商人心惊胆颤，前几天有人在农场附近的小屋里看到了他的身影，就是在修道院东边过了桥以后的那块地方。提着他的头回来领取赏金吧！不过你要小心一点，。加瑞克身边总是有一帮暴徒，他可不是那么容易搞定的家伙。","小武哥儿"},
[7] = {"剿灭狗头人","杀死8只狗头人歹徒，然后向治安官玛克布莱德复命。","你的第一个任务是清剿工作，。一个狗头人氏族占据了北边的森林。到那儿去，把你能看到的狗头人歹徒都杀掉。尽量减少他们的数量，好让我们有一天能把他们从北郡彻底赶出去。","小武哥儿"},
[8] = {"盗贼的交易","把笔迹潦草的信件送给布瑞尔的旅店老板瑞尼。","嘿，伙计！帮我一个忙如何？大堆僵尸和蜘蛛实在让我应接不暇。现在我手里有一封要送到布瑞尔的信……送给一个名叫瑞尼的还是别的什么的旅店老板，别管她姓什么啦。总之，那里是一个舒适而温暖的小地方，里面都是些希望重返真实自我的瘟疫受害者，当然那里也是你休息的好去处。你应该自己去看看……如果你愿意跑一趟，我会给你不错的报酬的。","小武哥儿"},
[9] = {"清理荒野","农夫萨丁要求你破坏掉20台看守傀儡。","看看这片土地上都发生了些什么吧！这片土地曾为一群善良老实的农民们所有。但如今，一群该死的小贼把农民们全部赶走了。当然，除了老子我！但有些看守傀儡一直霸占着我的田地。如果你觉着自己能够胜任这份工作的话，我希望你能帮忙清除掉20台傀儡。完成了任务之后，记得回来拿酬劳。如果你把我这片田地上的傀儡清光了的话，就去清除旁边田上的傀儡吧。","小武哥儿"},
[10] = {"谢申克的救赎","寻找初级勘探员谢申克的下落，把他或者他的勘探设备交给加基森的高级勘探员菲兹杜瑟。","啊，这真是太糟糕了！我派我手下最得力的助手，初级勘探员谢申克去沙漠东南面的那个叫做大裂口的地方进行探查。但是现在他失踪了，而他最后一份报告中显示大裂口到处都充斥着那些怪异的虫子。我现在已经派不出足够的人力来同时探查这片沙漠上的两大块重要的地区了。我想派你去大裂口找谢申克，求求你了！也许他已经……但至少请帮我拿回他的勘探设备来。我恐怕那是可怜的谢申克最后的遗产了。","小武哥儿"},
[11] = {"河爪豺狼人的悬赏", "将8个彩色豺狼人臂章交给兵营的莱尼雷副官", "最近在艾尔文森林边界出现了豺狼人的踪迹——那些野蛮的生物根本不该出现在这片土地上。我们发现南边哨塔附近的森林里盘踞着一大群豺狼人，数量远超我们警备队的应对能力。另外还有一伙在东部石冢湖附近安营扎寨。暴风城军队将为协助清剿的人员颁发嘉奖。带上它们彩绘的臂章回来，作为你英勇行为的证明。", "小武哥儿"},
[12] = {"西部荒野人民军","哨兵岭的格里安·斯托曼要求你杀死15名迪菲亚捕兽者和15名迪菲亚走私者，然后回去向他报告。","人民军只一个目标：保护西部荒野的安宁，并将和平带回到这片土地上来。不幸的是，和平总是以鲜血的代价来换取的。我手下的一个斥候报告说，有一群迪菲亚捕兽者正在附近到处流窜并大肆破坏。最新的报告说他们出现在了西北方的詹戈洛德矿洞中，如果你想加入我们人民军的话，那么就先杀死15名迪菲亚捕兽者和15名迪菲亚走私者，然后回来向我复命。","小武哥儿"},
[13] = {"西部荒野人民军","哨兵岭的格里安·斯托曼要求你杀死15名迪菲亚抢劫者和15名迪菲亚强夺者，然后回去向他报告。","有人看见一群凶残的迪菲亚抢劫者洗劫了金海岸矿洞和月溪镇，我们人民军绝不能对这样的事袖手旁观。马上就出发吧，，让圣光重新照耀西部荒野。金海岸矿洞就在哨塔西边的海岸附近，作为训练的第二部分，我希望你能杀死15名迪菲亚抢劫者和15名迪菲亚强夺者。","小武哥儿"},
[14] = {"西部荒野人民军","哨兵岭的格里安·斯托曼要求你杀死15个迪菲亚路霸、5个迪菲亚巡路者和5个迪菲亚拳匪，然后回去向他报告。","一些迪菲亚路霸最近一直在避开我们，到处作恶。根据我手下最可靠的探子们的线报，这些迪菲亚路霸通常沿着从这里到西部荒野南部的道路打家劫舍。我们觉得他们现在应该就躲在南部的山丘那边，计划着下一步的行动。以人民军的名义，去杀死那些家伙。","小武哥儿"},
[15] = {"回音山调查行动","杀死8只狗头人劳工，然后向治安官玛克布莱德复命。","，我的探子告诉我说，狗头人群落的规模远远大于我们的估计，一群狗头人劳工刚刚入侵了北边的回音山矿洞。到矿洞里去，把他们都除掉。那里至少有10个狗头人劳工，杀光他们，如果你发现他们的数量远不止这么多的话，就赶快回报给我。","小武哥儿"},
[16] = {"葛拉德的饮料","","","小武哥儿"},
[17] = {"奥达曼的蘑菇","收集12颗紫色蘑菇，把它们交给塞尔萨玛的加克。","，我听说有一种紫色蘑菇刚刚被发现，它们似乎只在奥达曼挖掘场里生长。我需要十二个这样的蘑菇来进行炼金术的研究。你要多加小心，这种蘑菇会喷射出有毒的孢子。帮我这个忙吧，我会给你丰厚的报酬，另外还可以让你尝尝我收藏多年的好酒！","小武哥儿"},
[18] = {"盗贼兄弟会","给北郡的维里副队长带回12个红色粗麻面罩。","最近, 一伙新来的流寇停留在北郡一带，为祸四方。他们自称为迪菲亚兄弟会，向东过了河之后就能找到他们。我不知道他们聚在一起到底想要干什么，但我确信他们不是什么好东西。给我带回一些他们的红色粗麻面罩，我就送你一把武器作为奖励。","小武哥儿"},
[19] = {"萨瑞尔祖恩","将萨瑞尔祖恩的头颅带给湖畔镇的治安官马瑞斯。","黑石前锋和黑石叛节者经常在这里和石堡要塞之间伏击我们，这群前锋的指挥官是个名叫萨瑞尔祖恩的兽人。把他的头给我带来。","小武哥儿"},
[20] = {"黑石氏族的威胁","给湖畔镇的治安官马瑞斯带回10把破斧。","黑石氏族穿越了燃烧平原并攻下了北方的石堡要塞。他们以那座要塞为据点，劫掠湖畔镇北边的人们，吓得全镇的居民都不敢外出，只能躲在镇子里瑟瑟发抖。帮湖畔镇解决掉这个威胁吧。杀死黑石氏族的兽人，并带回来十把他们所用的破斧作为证明。尽管黑石氏族是在北方威胁着我们，但我们也收到了他们在赤脊山脉东南部出现的报告。你可以在那里找到他们，然后猎杀他们。","小武哥儿"},
[21] = {"回音山清剿行动","杀死12只狗头人苦力，然后向北郡修道院里的治安官玛克布莱德复命。","你上次的调查证实，回音山矿洞需要一次清剿行动。回到矿洞那边，帮我们清除那里所有的狗头人吧。抓紧时间，。狗头人无所顾忌地盘踞在矿洞里的时间越长，它们在北郡的据点也就越稳固。","小武哥儿"},
[22] = {"猪肝馅饼","萨尔玛·萨丁需要8片血牙野猪的肝来烹制猪肝馅饼。","削两个洋葱，剥一个大蒜，烤三片面包，剁半两香菜，切几块萝卜，熬一锅肉酱。现在……我还需要8个猪肝来完成我的绝世美味馅饼！","小武哥儿"},
[23] = {"乌萨茍斯的爪子","将乌萨茍斯的爪子交给灰谷碎木哨岗的塞娜尼·雷心。","强大的熊怪乌萨茍斯被你杀死了，它的爪子是你灰谷狩猎之行的战利品。爪上有一小块新月形的印记，这个印记的意义对你来说还是一个谜。你应该把这只爪子交给碎木哨岗的塞娜尼·雷心，以此证明你已经杀死了这只强大的猛兽。","小武哥儿"},
[24] = {"萨杜布拉的头颅","将萨杜布拉的头颅交给灰谷碎木哨岗的塞娜尼·雷心。","敏捷而强大的萨杜布拉静静地躺在地上，你取得了最后的胜利。它的头颅是一件非常合适的战利品，碎木哨岗的塞娜尼·雷心肯定会想要看看这件战利品，然后对你在灰谷狩猎中取得的成绩予以嘉奖。","小武哥儿"},
[25] = {"石爪山的困境","清除位于碎木哨岗西南和石爪小径正东的密斯特拉湖一带的12个污浊的水元素。在密斯特拉湖上的眺望台中侦查联盟的前哨站。返回灰谷慰藉之林的碎木哨岗，向马斯托克·维尔西斯报告。","如果你想做个有用的<职业>，那为什么不帮我们解决石爪山那边的困境呢？灰谷和石爪山脉之间的交通中断了，因为湖水中的生物突然开始攻击任何过路的旅行者……一个都不放过。你要做的并不仅仅是杀死那些水元素，你还要到密斯特拉湖中的眺望台上去一趟——在那里可以看到联盟前哨站的情况。你准备好了吗？","小武哥儿"},
[26] = {"必修的课程","与月光林地永夜港的德迪利特·星焰谈一谈。","，看到你进展顺利，我非常高兴。你正在不断地努力成为自然界的守护者，这是莫大的荣耀。现在是你深入学习更高级的变身技能的时候了，塞纳留斯赋予我们特殊的能力，让我们可以变身成为在水中行动自如的动物。所以，你必须到月光林地的永夜港去，跟塞纳里奥议会的德迪利特·星焰谈一谈。他将进一步指引你。","小武哥儿"},
[27] = {"必修的课程","与月光林地永夜港的德迪利特·星焰谈一谈。","，看到你进展顺利，我非常高兴。你正在不断地努力成为自然界的守护者，这是莫大的荣耀。现在是你深入学习更高级的变身技能的时候了，塞纳留斯赋予我们特殊的能力，让我们可以变身成为在水中行动自如的动物。所以，你必须到月光林地的永夜港去，跟塞纳里奥议会的德迪利特·星焰谈一谈。他将进一步指引你。","小武哥儿"},
[28] = {"湖中试炼","在月神湖寻找神殿灵珠，把它带到月光林地西北部的雷姆洛斯神殿去。在神殿中使用神殿灵珠，然后与神殿中的塔加里谈话来完成试炼。","第一个试炼是要搜寻月神湖底的神殿灵珠。它会很快地腐烂，因此你要在找到它后立即把它拿到雷姆洛斯神殿去。在神殿里使用它，然后跟塔加里谈谈，她是月光林地里最值得信赖的守卫之一。你的时间非常紧迫，而且还要与其他寻找灵珠的德鲁伊竞争，灵敏和智慧是你取胜的关键。祝你好运，。","小武哥儿"},
[29] = {"湖中试炼","在月神湖寻找神殿灵珠，把它带到月光林地西北部的雷姆洛斯神殿去。在神殿中使用神殿灵珠，然后与神殿中的塔加里谈话来完成试炼。","第一个试炼是要搜寻月神湖底的神殿灵珠。它会很快地腐烂，因此你要在找到它后立即把它拿到雷姆洛斯神殿去。在神殿里使用它，然后跟塔加里谈谈，她是月光林地里最值得信赖的守卫之一。你的时间非常紧迫，而且还要与其他寻找灵珠的德鲁伊竞争，灵敏和智慧是你取胜的关键。祝你好运，。","小武哥儿"},
[30] = {"海狮试炼","寻找水兽耐力坠饰和水兽敏捷坠饰。与月光林地的居民谈一谈，找出这些东西可能被放在哪里。在雷姆洛斯神殿附近将海狮坠饰的两部分合而为一。将合并好的坠饰交给月光林地永夜港中的德迪利特·星焰。","第二个试炼是要寻找组成海狮坠饰的两个部分。其中的一半蕴含着海狮的敏捷天性，另一半蕴含着海狮那令人难以置信的耐力。德鲁伊汲取这两种特性，将它们运用到自己的水栖形态中。与月光林地中的居民谈一谈，找到这两个部分，并将它们合并起来。最后把合并好的坠饰交给德迪利特·星焰。","小武哥儿"},
[31] = {"水栖形态","回到雷霆崖，让图拉克·符文图腾看看你的海狮坠饰。","你已经学完了掌握水栖形态所必须具备的所有知识，现在回到雷霆崖的图拉克·符文图腾那儿去吧。把坠饰拿给他看看，以此证明你已准备好接受新的知识。他会让你掌握变化为水栖形态的诀窍，让你在水中灵活自如。再见，年轻的德鲁伊。我们会再见面的。","小武哥儿"},
[32] = {"异种蝎的威胁","把报告带给奥格瑞玛的基尔兹宾·鼓眼。","这是我要你去递送的报告，马上把它送到能够对其内容有深入了解的那些人的手中。我知道一个名叫基尔兹宾·鼓眼的巨魔学者，他致力于研究卡利姆多大陆上的那些与艾泽拉斯生态格格不入的生物形态；他简直是一本活的生物书！如果你想要知道我们面临的是怎样的威胁，以及如何解决这个威胁，那就把这份报告交给他吧，我们现在需要一切可以得到的帮助。基尔兹宾应该住在奥格瑞玛暗巷区的第二层。","小武哥儿"},
[33] = {"林中的群狼","给北郡修道院外的伊根·派特斯金纳带回8块硬狼肉。","我最讨厌那些肮脏狡猾的森林狼了！但我一直都很爱吃狼肉排……给我带几块硬狼肉来，我会拿一些对你有用的东西来交换。你可以在北郡的郊外找到森林狼和幼狼，杀掉它们就可以得到硬狼肉了。","小武哥儿"},
[34] = {"不速之客","湖畔镇的玛蒂·詹罗斯要求你杀死贝利格拉布，并带回它的獠牙作为证明。","前几天我的花园又被搞得一塌糊涂，不过现在我已经知道是哪个混蛋干的了。就是那只被治安官马瑞斯先生称作“贝利格拉布”的野猪。你瞧，我在下一季来临之前都没法种我的水仙花了。全毁了！一切都被那只混蛋野猪给毁了！把那祸害给我干掉！把它的獠牙给我带回来，我会付给你酬劳的。它一般就在湖畔镇西南的田边闲逛，但有时候也会跑进我的花园里来。","小武哥儿"},
[35] = {"卫兵托马斯","治安官杜汉要你和卫兵托马斯谈一谈。","如果你担心关于鱼人的传言可能属实的话，就去一趟艾尔文森林东部的桥边和卫兵托马斯谈谈吧。他最近一个星期都驻扎在那里，应该很了解那个地区的情况。搞清楚事态之后，把他的报告带给我。","小武哥儿"},
[36] = {"杂味炖肉","弗娜·法布隆要求你将她的杂味炖肉食谱交给萨尔玛·萨丁。","我从来没有想过有一天会被迫离开我的农庄。但是现在，那些满是小贼和强盗的田地对我们来说已经是太过危险了。等法布隆修好他的车之后，我们就要逃离这里了。或许你能帮我一个小忙？先让我把我的独家绝活杂味炖肉的食谱给抄下来，然后你帮我把它交给萨尔玛·萨丁。萨丁农场就在路口的另一边。","小武哥儿"},
[37] = {"失踪的卫兵","卫兵托马斯要你沿着河岸向北走，寻找两个失踪的卫兵罗尔夫和马拉凯。","几天前，我派了卫兵罗尔夫和马拉凯沿着河岸去侦查这一代的情况，但他们到现在还没回来。我得先搞清楚这两个人发生什么事情才能完成报告。沿着河岸往北走，找到他们……或是他们的尸体。","小武哥儿"},
[38] = {"杂味炖肉","萨尔玛·萨丁需要3块秃鹫肉条、3只血牙野猪的头、3颗鱼人的眼睛和3棵秋葵。","来帮我完成这道最华丽的西部荒野杂味炖肉吧！拜托啦，帮我找到以下这些材料：3块秃鹫肉条\n3只血牙野猪的头\n3只鱼人的眼睛\n3棵秋葵","小武哥儿"},
[39] = {"托马斯的报告","到闪金镇去向治安官杜汉报告。","把罗尔夫和马拉凯的死讯告知治安官杜汉，向他报告说，靠我们现在的部队根本无法遏制住这些在艾尔文森林东部繁衍的鱼人。我知道我们的兵力很短缺，但是杜汉应该可以为我们提供人手。","小武哥儿"},
[40] = {"鱼人的威胁","雷米要你去和闪金镇的治安官杜汉谈一谈。","，艾尔文森林又遇到新的威胁了！鱼人正陆续从艾尔文森林东部的河流里游过来，把鱼都给吓跑了，而且它们还攻击平民！我已经向治安官杜汉发出过警告，不过他显然更担心那些豺狼人和强盗，而且他不相信鱼人能对我们构成威胁。请你和杜汉谈谈吧，最好能说服他向东部派遣更多部队！","小武哥儿"},
[45] = {"罗尔夫的下落","到鱼人村去寻找罗尔夫，或是他死亡的消息。","进一步检查这个地区之后，你发现有蹼状的脚印沿着石碑湖岸一直向北延伸。在东边远处，你隐隐约约看见有一个鱼人的村落。也许罗尔夫就在那儿丧了命……","小武哥儿"},
[46] = {"悬赏鱼人","给艾尔文森林东部的桥边的卫兵托马斯带去8个破损的鱼人鳞片。","暴风城军队悬赏清除那些艾尔文森林内的鱼人潜伏者和鱼人强盗。杀了它们，把它们破损的鱼人鳞片给我带回来，暴风城军队会奖励你的。鱼人在北面的石碑湖附近建造了一座村庄，另外在南面的溪流分叉处还有一座村庄。","小武哥儿"},
[47] = {"金砂交易","为闪金镇的雷米收集10袋金砂，这种东西可以从艾尔文森林的狗头人身上找到。","这一带的狗头人有时会带着金砂出来活动。我真的很需要这些金砂……给我找一些来，我会以镇子里最高的收购价格买下来——最高的价格！","小武哥儿"},
[48] = {"琥珀酒","把圣泉之水带给葛瑞姆·雷酒。","高高的葡萄树生长在南方\n蜿蜒的清泉流过树根旁\n纯净宛如女神的眼泪\n你快点去给我弄来圣泉水！","小武哥儿"},
[49] = {"琥珀酒","葛瑞姆·雷酒需要大麦、黑麦和玉米各一袋。","琥珀的颜色是我毕生之爱\n就像西山夕阳下的云彩\n为了它的诞生呀，勇敢的少年我召唤你\n我要黑麦、大麦和玉米！","小武哥儿"},
[50] = {"琥珀酒","葛瑞姆·雷酒需要一些真银。","我捣！我搅！我捣！我搅！\n少了玩意就没法搞好\n我要一种够硬的金属来当罐儿\n给我弄些真银来，我就唱完歌儿！","小武哥儿"},
[51] = {"琥珀酒","带给葛瑞姆·雷酒一枝枫树枝。","还没过滤但是刚刚蒸馏\n就像是新皮甲还没上油\n然后得烧它七八斤炭呀\n我说你赶紧动身去办呀！","小武哥儿"},
[52] = {"保卫边境","杀掉8只觅食的灰狼和5只森林熊幼崽，然后回到艾尔文森林东部的桥边去见卫兵托马斯。","你好，。我们离开闪金镇越远，在森林里遇到的野生动物就越凶猛。东谷伐木场几乎每天都要受到狼和熊的攻击！我们需要你的帮助。","小武哥儿"},
[53] = {"琥珀酒","给葛瑞姆·雷酒带去一捆烧焦的橡木。","甜美的液体清澈如婴儿泪\n百年的陈酿色深如琥珀\n但在把它放进地窖存着前\n造个橡木大桶来盛着先！","小武哥儿"},
[54] = {"去闪金镇报到","将治安官玛克布莱德的文件带给闪金镇的治安官杜汉。","，如今你已经被证实是一位非常关心北郡的安全的<职业>了。现在我要派遣你去保卫艾尔文森林的周边地区。如果你接下了这个任务，就把这些文件送到闪金镇的治安官杜汉手里。沿着向南的大道走，穿过北郡的关卡就能看到闪金镇了。","小武哥儿"},
[55] = {"摩本特·费尔","对摩本特·费尔使用摩本特的克星，杀掉他，然后把摩本特的克星交给斯温。","摩本特·费尔的老巢就在一个可以俯视乌鸦岭墓地的山顶上。他的日子就快要到头了……杀掉他，让我们不被他的邪恶所侵害。为我复仇吧，也为了夜色镇的人民！","小武哥儿"},
[56] = {"守夜人","夜色镇的指挥官指挥官阿尔泰娅·埃伯洛克要你去杀掉8个骷髅战士和6个骷髅法师。","作为守夜人的指挥官，我发过誓要保卫夜色镇人民的安全。暴风城已经把他们驻守在这里的部队撤了回去，现在我们只能依靠自己了。如果你觉得可以胜任，就请帮助我们吧！到夜色镇南部的静谧花园去，杀掉8个骷髅战士和6个骷髅法师。我们必须尽量减轻亡灵所能够带来的压力！","小武哥儿"},
[57] = {"守夜人","指挥官阿尔泰娅·埃伯洛克要你去杀掉15个骸骨魔和15个恐怖骸骨。","，我收到报告说有亡灵在森林里出没！如果你能应付的话，就到乌鸦岭的大墓地去杀15个骸骨魔和15个恐怖骸骨。另外，在夜色镇南部的静谧花园一带也都发现有骷髅在出没。我们一定要把这些亡灵驱逐出暮色森林！","小武哥儿"},
[58] = {"守夜人","夜色镇的指挥官阿尔泰娅·埃伯洛克要你到乌鸦岭的东部陵墓去杀20个瘟疫食尸鬼。","乌鸦岭的形势仍然十分严峻，。但是我们没有足够的人手来保卫夜色镇的安全，对于乌鸦岭更是一筹莫展。你必须迅速赶到乌鸦岭去，在东部的陵墓里除掉20个瘟疫食尸鬼。","小武哥儿"},
[59] = {"布甲和皮甲","把暴风城护甲标记交给萨拉·迪博雷恩。","为了表彰你的智慧和勇敢，我把这个标记给你，用在护甲上应该很不错。你把它交给东谷伐木场的萨拉·迪博雷恩，她会为你做件合适的护甲。这件护甲在你为保卫艾尔文森林作战时应该用得到。东谷伐木场就在卫兵托马斯所在的哨所的东面。","小武哥儿"},
[60] = {"狗头人的蜡烛","为闪金镇的威廉·匹斯特收集8支大蜡烛。","你好，$g亲爱的先生:尊贵的女士;！你有时间吗？我和我兄弟在暴风城开了个药店，而我现在正要在这一带找些大蜡烛，以便提取其中的蜡。你能帮助我吗？你可以在狗头人身上找到大蜡烛，我听说在艾尔文森林的矿洞一带有很多狗头人……在南边的法戈第矿洞和东边的玉石矿洞里都有不少。我建议你去这两个矿洞里看看。","小武哥儿"},
[61] = {"送往暴风城的货物","把威廉的货物交给暴风城贸易区的摩根·匹斯特。","我兄弟莫根正在暴风城等我送蜡烛过去，但我自己实在忙得抽不开身。如果你愿意把这批货物送过去的话，他会重金酬谢你的。我已经把蜡烛装好了，莫根在我们的店里——匹斯特的药剂店，就在暴风城的贸易区。","小武哥儿"},
[62] = {"法戈第矿洞","调查法戈第矿洞，然后回到闪金镇去见治安官杜汉。","出问题的还不止北郡的矿洞！我接到报告说艾尔文森林的法戈第矿洞已经成了狗头人的天堂。去那里查看一下这些报告是否属实，然后回来告诉我。法戈第矿洞就在闪金镇的正南方，斯通菲尔德农场和马科伦农场之间。","小武哥儿"},
[63] = {"水之召唤","击败堕落的水之魂，把堕落水之魂的护腕和剩余的最纯净的水放在银松森林的圣泉火盆上。","沿着银松森林海岸前行，在瑟伯切尔的西边有一处被瘟疫玷污过的神殿。那里的水灵不再和我们交谈，你的任务就是消灭那个污染源并净化那个水池。将元素护腕和剩余的泉水放置在火盆上，就可以进行召唤水灵的仪式了。把能够证明你完成了任务的证据带回来给我，然后我就会给你图腾。","小武哥儿"},
[64] = {"遗失的怀表","农夫法布隆希望你能帮他找回他的怀表。怀表在西边南瓜田旁边的农舍的衣柜里。","太可怕了呀！弗娜一听到田里的骚动就把我叫醒了。你猜怎么着，田里全是小流氓。我们只能连夜逃出来，结果我就把我的怀表给忘在家里了。那块怀表是弗娜的爸爸在我们结婚的那天送给我的，我可不想让它落在那些盗贼手里。我应该是把那块表放在小农舍的衣柜里了，就在西边的那片南瓜田边上——你应该不会错过的。如果你能把它拿回来给我的话，我肯定会对你感激不尽的！","小武哥儿"},
[65] = {"迪菲亚兄弟会","格里安·斯托曼要求你去和湖畔镇的威利谈一谈。","那群自称为迪菲亚兄弟会的流寇贼子将我们这些善良的平民赶离西部荒野，他们一定要为自己的罪行负责！我要求你去打探一下，我们必须知道到底谁是他们的头儿，还有他们都藏在哪儿。在湖畔镇的旅馆里有个叫威利的小贼以前欠了我一个人情，你可以找他帮忙。到艾尔文森林东边的赤脊山去吧，湖畔镇就那座山的脚下，到那里去碰碰运气。","小武哥儿"},
[66] = {"斯塔文的传说","去夜色镇大厅找到书记员达尔塔。","昨夜，一阵突如其来的不安掠过我的全身，令我感到我的孙女奥利萨正处在巨大的危机中。我用纸牌进行了占卜，“死神”在桌上凝视着我。在长时间的沉思之后，我找到了这个可怕而神秘的事情的一点线索，有一个名字进入了我的脑中，那就是“斯塔文”。到城镇大厅里去找书记员达尔塔吧，看看你能否得到更多关于这个斯塔文的信息……我担心包括你我在内的所有人都有危险。","小武哥儿"},
[67] = {"斯塔文的传说","到月溪镇的学校去寻找关于斯塔文的新信息，回来告诉书记员达尔塔。","斯塔文？让我查查镇里的档案。斯塔文…斯塔文…让我找找……啊，找到了！这里有斯塔文·密斯特曼托的档案。最后一次记录的地址是在月溪镇的学校里。哎呀，都是过时的东西了！朋友，你能帮我个忙吗？如果你碰巧路过月溪镇的话，也许能找到一些有关这个家伙的新消息，别忘了告诉我一声，好让我更新档案。","小武哥儿"},
[68] = {"斯塔文的传说","把覆满灰尘的信交给书记员达尔塔。","你在旧提箱里找到了一封覆满灰尘的信。","小武哥儿"},
[69] = {"斯塔文的传说","到狮王之傲旅店去问问那里的人，看看他们是否听说过斯塔文这个人。","哎呀！我上次肯定漏掉这个了。斯塔文的档案中的第一个地址下面还有另一个地址，这个地址被擦掉了一点。看起来好像他还去过闪金镇的狮王之傲旅店。你愿意的话就去那里查查看吧，。","小武哥儿"},
[70] = {"斯塔文的传说","从箱子中拿出斯塔文的未寄出的信，把它送到暴风城的运河区。","斯塔文的名字让我想起点什么…哦，想起来了！很多年前的一个雷雨交加的夜晚，有个信差到这儿来过夜避雨。快到午夜12点的时候，他一边尖叫着一边从楼上跑下来，苍白的脸上满是惶恐的神色，最后他穿着睡衣逃进了瓢泼的大雨中。由于走得太匆忙，他忘了拿走楼上箱子里的信，不过后来也没有再回来取过。喏，这一封是写给斯塔文的一个住在暴风城运河区的朋友的，你自己拿去看吧。","小武哥儿"},
[71] = {"回复托马斯","把罗尔夫和马拉凯的铭牌交给艾尔文森林东部桥边的卫兵托马斯。","把你找到的两块铭牌交给桥边的卫兵托马斯，让他知道两个卫兵的死讯。","小武哥儿"},
[72] = {"斯塔文的传说","在打包的东西里寻找线索。","我父亲从前是这幢宅子的管家，在那场大屠杀之后，他费了好大的工夫才把地上的血迹拖干净，不过这跟我们要谈的事情没什么关系。弗林特雷家的基金早已经用光，现在家里最后的财产都已经准备要拍卖掉了，那些像秃鹫一样贪婪的征税官！你要是真想找些什么资料，不妨在这堆垃圾里找找看，天知道你能找到什么。","小武哥儿"},
[73] = {"<TXT> No Reward","","","小武哥儿"},
[74] = {"斯塔文的传说","你找到的这张被撕破的日记书页给你提供了又一个线索。","你在箱子里找到了几样东西：一些有霉味的、看上去像是传家宝的东西，一副家庭肖像画，一些打猎所得的战利品和几本旧书。在箱子底部的一个花瓶下面，你找到了一张被撕破的日记书页。","小武哥儿"},
[75] = {"斯塔文的传说","治安官哈迦德要你从楼上的箱子里找出一张褪色的日记书页。","我刚刚搬进来住的时候发现楼上的箱子里有一捆羊皮纸，我想看看那些羊皮纸上写了什么，但是迷雾却让我根本看不清楚。给我这个快瞎了的老人帮个忙吧，去检查一下楼上箱子里的东西，看看有没有什么有关斯塔文的信息。我记得有一张褪色的日记书页，你肯定会对它感兴趣的。把它拿过来，我会尽力帮助你的。","小武哥儿"},
[76] = {"贾森矿洞的异动", "杀死10名狗头人矿工、5名狗头人地占师并探索贾森矿洞。完成任务后回到闪金镇的杜汉复命。", "多亏你的调查，我们已经知道法戈第矿洞已经被狗头人占据。现在需要派人去更远的贾森矿洞侦查。探索矿洞并确认狗头人的活动迹象。如果遇到任何狗头人——你知道该怎么做。沿着大路向东行进直到阿祖拉之塔，再从塔楼向北就能在山脚找到矿洞入口。", "小武哥儿"},
[77] = {"收集蜜糖","从隐匿石一带被部落废弃的基地中的箱子里找到10瓶辛特兰蜜糖。","我这里有德兰·杜佛斯需要的包装材料。我会帮助你为玛尔顿那烦人的老爸包装他要的蜜糖……不过你得给我多带几瓶蜜糖回来。它们就在靠近隐匿石一带，在那座荒废掉的部落村庄的箱子里，可恶的泥浆怪和软泥怪霸占了那块地方，有传言说它们是由一些大型软泥怪领导着的。但不管怎么样，你必须找到蜜糖并把它们带回来让我进行包装。","小武哥儿"},
[78] = {"斯塔文的传说","把褪色的日记书页带给旅店老板斯密茨。","我知道有人可以帮你。我以前领导暴风城卫队的时候，经常去夜色镇的血鸦旅店喝酒。那儿的老板斯密茨对当地的情况了如指掌。把这张东西给他，看看他对此有什么说法。","小武哥儿"},
[79] = {"斯塔文的传说","把沾满泥污的日记书页交给指挥官阿尔泰娅·埃伯洛克。","多年来我一直在追寻这个斯塔文的消息。几年前那些来访的贵族被杀之后，我曾和哈迦德一起去调查。我发现了这些沾满泥污的纸，但是一直没有都想到把这上面的笔迹和树林里的那个疯子联系在一起。你提供的线索证明了他的罪行。赶快把这个交给指挥官阿尔泰娅·埃伯洛克，告诉她你所发现的一切。","小武哥儿"},
[80] = {"斯塔文的传说","把染血的日记书页交给书记员达尔塔。","有一段时间我一直注意着斯塔文这个讨厌的家伙。如果这些东西都是他写的，那就足以给他定罪了。书记员达尔塔多年以来一直负责着镇里的档案，他很擅长辨认笔迹。把这张纸给他，看看是否和档案里面斯塔文的签名笔迹相吻合。","小武哥儿"},
[81] = {"送回蜜酒","把桶交给奥格瑞玛的德兰·杜佛斯。","我在德兰要的东西上花了好大的工夫，因为除了额定装进桶里的蜜酒之外，他还要求额外再加几瓶！虽然我对德兰这个家伙的评价并不是很高，但是这世上没有比往酒桶里死命塞瓶子更糟的事情了……你来得正是时候。现在把这个桶送到德兰·杜佛斯那里去，他在奥格瑞玛那里自己开了一家店。顺便代我向玛尔顿问好，我很希望能有机会再和他畅饮几杯。","小武哥儿"},
[82] = {"腐化之巢","从腐化之巢找5个森提帕尔昆虫肢体，把它们交给加基森的炼金师匹斯特苏格。","好吧，你的报告中提到了虫子……我们现在知道的是……它们正使得原本是腐化之巢所在区域的水池变得干涸，其它方面我们一无所知。首先我们要搞清楚敌人到底是谁！你得去腐化之巢那里，把那些虫子的肢体带回来给炼金师匹斯特苏格研究，这样我们就可以确定到底是谁在那里搞鬼了！","小武哥儿"},
[83] = {"红色亚麻布","给东谷伐木场的萨拉·迪博雷恩带去6块红色亚麻布面罩。","北郡的迪菲亚盗贼戴粗麻布面罩，而艾尔文森林的迪菲亚盗贼戴的是亚麻布的，我可以用这些好的亚麻布做些东西。给我找些亚麻布面罩，我可以用来给你做点什么。有人在西南部的布莱克威尔南瓜田外看见过迪菲亚盗贼出没。","小武哥儿"},
[84] = {"比利的馅饼","把猪肉馅饼带给马科伦农场的比利·马科伦。","这是你要的馅饼。把这东西交给那个比利的时候，别忘了告诉他我希望他吃了噎死！","小武哥儿"},
[85] = {"丢失的项链","和比利·马科伦谈一谈。","我的项链丢了，一定是那个讨厌鬼比利·马科伦偷走的！他总是像只老鼠一样在东边的马科伦农场里窜来窜去。请把我的项链拿回来给我，让我这可怜的寡妇得到一些安慰吧。","小武哥儿"},
[86] = {"比利的馅饼","给斯通菲尔德农场的波尼斯·斯通菲尔德带去4块野猪肉。","给我吃点馅饼，也许我就能想起来是谁拿着项链了。我知道另一个农场里的波尼斯老太太做的猪肉馅饼很棒……我们的农场周围有野猪，如果你能给她找几块野猪肉，她就应该会给你烤一块馅饼。","小武哥儿"},
[87] = {"金牙","把波尼斯的项链带给斯通菲尔德农场的波尼斯·斯通菲尔德。","我在法戈第矿洞旁边玩的时候，不小心掉了那根，呃……我是说我看见了那个老太太的项链。别问我它怎么会在那儿……和我没有关系！不管怎样，我看到一个很壮实的镶着金牙的狗头人……他把项链捡起来跑到矿洞里了。你去找那个狗头人吧，我发誓，你肯定能在他身上找到项链的！","小武哥儿"},
[88] = {"公主必须死！","杀掉公主，把它的项圈带给斯通菲尔德农场的斯通菲尔德妈妈。","布拉克威尔一家有一头得过奖的猪，它名叫“公主”。这头母猪巨大无比，还经常偷偷溜到我的农场里偷吃我的蔬菜！在它再次糟蹋了我的农场之前……必须把它给宰了！把它的项圈带回来证明你杀了它，我会给你一些奖赏的！公主一般在布莱克威尔南瓜田出没，那个南瓜田就在东边，比马科伦农场还要往东。在它肚子饿了之前杀死她，然后再回来告诉我！","小武哥儿"},
[89] = {"止水湖上的桥","给湖畔镇的工头奥斯洛带回5根铁矛和5个铁铆钉。","上次兽人入侵的时候，我们被迫把所有能找到的铁都熔了来制造子弹、刀剑和盔甲。万不得已，我们向暴风城请求援助，让他们运一船金属材料过来。谁料一群赤脊山豺狼人劫持了运送金属的船只，并逃进了湖畔镇后的山中。这样一来，我们这座桥的重修工程马上就要面临缺少材料的困境了。如果你能给我带回5根铁矛和5个铁铆钉，我一定会奖励你的。快点去吧！","小武哥儿"},
[90] = {"干烤狼肉串","收集10块狼肋排和1份暴风城特产调料，再回夜色镇去找厨师格鲁奥。","干烤狼肉串是有口皆碑的美食！你想吃吗？我当然可以为你做一些，不过得先给我找点材料。给我找些暴风城特产调料外加10块狼肋排来就可以了。这儿的森林里遍地都是狼，想找点肋排肯定不是问题。至于调料，你得到暴风城运河区的花店里去找菲利希亚·加姆。","小武哥儿"},
[91] = {"所罗门的律法","给湖畔镇大厅的拜里弗·科纳彻尔带回10个暗皮坠饰。","暴风城的一群死敌在赤脊山的东侧的山脚下建立起一片营地，这些邪恶的暴徒一直在我们的小镇中传播着恐惧。莫甘斯是这群恶徒的头领。他已经控制了暗皮豺狼人氏族，让那些邪恶的野兽为他卖力。根据湖畔镇的法律规定，协犯最高可以被判处死刑。这些肮脏的豺狼人一定要被处死！给我带回10个暗皮坠饰来，你就可以得到我们的奖励。","小武哥儿"},
[92] = {"赤脊山炖肉","湖畔镇的厨师布雷纳想要5块硬秃鹫肉，5个巨型血牙野猪头和5份香脆蜘蛛肉。","没什么能比烹制赤脊山炖肉更让我高兴的事了，但是现在有个小问题。自从兽人们出现之后，我就得没日没夜地忙着给暴风城军队的整整一个旅供应食物，我的食品柜早已是空空如也了。如果你能给我找来一些材料的话，我很乐意给你做点好吃的。只要给我带来5块硬秃鹫肉，5个巨型血牙野猪头和5份香脆蜘蛛肉就行了。","小武哥儿"},
[93] = {"黑蟹蛋糕","收集6条粘糊的蜘蛛腿，把它们交给夜色镇的厨师格鲁奥。","我可以告诉你个秘密——黑“蟹”蛋糕实际上是用蜘蛛腿做的！听起来是有点恶心，不过这种蛋糕的味道绝对一流！给我找点粘糊的蜘蛛腿来，我很快就能给你做好。听说结网毒蜘蛛身上很容易拿到这种东西——它们的巢穴就在东北部的丘陵和小河之间，暮色森林里的其它蜘蛛身上也有这东西。","小武哥儿"},
[94] = {"法师的眼线","把阿祖拉的铭文饰品放置到赤脊山伊尔加拉之塔旁边的狮子雕像身上。","我的对手莫甘斯是个强大而邪恶的法师，他就住在赤脊山的伊尔加拉之塔里。我已经找到了一种监视他的方法，只要通过阿祖拉之眼，就可以在很远的地方看到他的一举一动。不过要研究他的思想……我还需要进一步的帮助。如果你愿意的话，就带着这个铭文饰品到伊尔加拉之塔去，把它放置在塔旁边的狮子雕像身上。完成之后，阿祖拉的铭文饰品就会告诉我们，莫甘斯又在准备什么邪恶的计划。","小武哥儿"},
[95] = {"斯温的复仇","到斯温的农场去找出埋在老树桩后面的是什么东西。","我原来在东南部的一座农场里工作……直到有一天，从逆风小径来的黑暗强盗洗劫了我的农场，趁我不在的时候杀了我的全家！我回来时发现有个模糊的人影在我家的谷仓附近埋了一件什么东西，可惜我没能抓住他。我也不敢在这里继续逗留，因为我害怕会有黑暗强盗追踪我。直到现在，我都都不知道那人到底藏了什么。如果你能去找出真相，我一定会感激你的。那人埋东西的地方就在我的谷仓附近的一个老树桩后面。","小武哥儿"},
[96] = {"水之召唤","把水灵碎片交给贫瘠之地的水之先知伊斯伦。","拿着碎片，拿着碎片……赋予生命。赋予生命……理解生命，理解水就是生命本身……而堕落则会扼杀生命。你保护了生命，并将水的力量赋予了生命……","小武哥儿"},
[97] = {"斯塔文的传说","把这个消息告诉指挥官阿尔泰娅·埃伯洛克。","，你赶快去告诉指挥官阿尔泰娅·埃伯洛克，这两个笔迹完全符合！她的怀疑是正确的！","小武哥儿"},
[98] = {"斯塔文的传说","干掉斯塔文·密斯特曼托，把他的家族戒指带给伊瓦夫人看看。","斯塔文·密斯特曼托是个恶贯满盈的罪犯，很多无辜的人都死在他手中。毫无疑问，他犯下了无数宗罪案，给夜色镇带来了又一个威胁。天知道这个恶棍又在策划什么邪恶的行动。斯塔文的家就在小镇北边，，你去把他就地处死吧。完事以后把他的家族戒指带给伊瓦夫人作为证明，毕竟是她的预感导致我们揭露了这个可怕的凶手，她为夜色镇立了一功。","小武哥儿"},
[99] = {"阿鲁高的愚行","给瑟伯切尔的达拉尔·道恩维沃尔带回6副焚木镣铐。","在我对阿鲁高的魔法的越来越了解的同时，我对这个蠢货的鄙视与轻蔑也日益加深。我基本上完成了我对他所谓“拯救”的研究。在我了解到是什么样的巫术导致了焚木村的奇怪现象之后，我也就算是了解透彻了。白天，那些农夫们都是好端端的人。但太阳一落山，他们就变成了月怒狼人。我需要从阿鲁高给他们戴上的镣铐提取出一些能量来。带给我6副焚木镣铐，。","小武哥儿"},
[100] = {"水之召唤","和银松森林的水之魂谈一谈。","你吟诵完了咒语，瞬时间火盆便放出了万丈光芒。水滴和火焰接触时的辟啪声越来越弱，你可以感觉到笼罩在周围的堕落气息已经被消灭了。","小武哥儿"},
[101] = {"惩罚图腾","收集10颗食尸鬼的牙齿、10根骷髅的手指和5瓶蜘蛛毒液，把它们交给夜色镇的伊瓦夫人。","有一股神秘而邪恶的势力在森林里蔓延，我们必须更加小心地保护自己，。林中的夜风悄声告诉我，你很快就会遭遇巨大的危机。尊贵的<职业>，如果你想保护自己，就请给我找来10颗食尸鬼的牙齿、10根骷髅的手指和5瓶蜘蛛毒液。我会为你制作一个惩罚图腾，让那些企图伤害你的敌人自食其果。","小武哥儿"},
[102] = {"西部荒野的豺狼人","给哨兵岭的丹努文队长带回8只豺狼人的爪子。","暴风城已经把我们给遗弃了。一股腐朽与堕落的狂风正肆虐在西部荒野的平原之上。这里是我的故乡，我绝对不会背叛那些和我一样坚持留在这里的民众们。我们这些农夫必须站出来，为自己赢得生存的空间。若你愿意接受我们派给你的任务，就去巡视西部荒野的草原吧。找到那些可恶的豺狼人，把它们干掉，似乎这些家伙与死亡矿井里的小贼们有些联系。给我带回八只豺狼人的爪子来，我会奖励你的英勇行为的。","小武哥儿"},
[103] = {"长明的灯塔","给西部荒野灯塔中的葛瑞森船长带回5瓶灯油。","灯塔管理员一家被杀的那一个晚上实在是太可怕啦！我就那样无助地看着老瞎眼带着那群鱼人毁了他们全家。但过去的事就让它过去吧，我现在关心的是无尽之海中那些正把船只驶近暗礁的水手们的生命。如今，维持着灯塔上火炬不至熄灭的任务就落在我一个人身上了。从那些收割机器人身上找来5瓶灯油吧，这样我才能保住火炬上的火种。","小武哥儿"},
[104] = {"海岸上的威胁","将老瞎眼的鳞片交给西部荒野灯塔旁的葛瑞森船长。","当我的生命终结在了那片岩石上之后，我根本不知道死后的世界会是怎样的。那天晚上的灯塔一片漆黑，因为老瞎眼吓跑了管理员全家。他们本已经逃跑了，但那天晚上他们又回来想要点亮灯塔，结果老瞎眼带着一群野蛮的鱼人突袭了灯塔。这一次，管理员的全家都在我面前无助地死去了……如果你在海岸边看到老瞎眼的话，就杀死它，把它的鳞片给我带回来，我会奖励你的。","小武哥儿"},
[105] = {"啊，安多哈尔！","把阿拉基的护符匣碎片交给西瘟疫之地亡灵壁垒的高级执行官德灵顿。","啊，进攻安多哈尔并彻底击败那个巫妖的时刻终于来临了！召唤者阿拉基就盘踞在安多哈尔的废墟中，他的贴身卫队无时无刻不在他的身边保护着他。你需要召集强大的盟友才能击败他。消灭巫妖，，从它的护符匣里拿出一块碎片来，作为你获胜的证据！","小武哥儿"},
[106] = {"年轻的恋人","把梅贝尔的情书带给托米·乔·斯通菲尔德。","天哪，我太痛苦了！我爱上了托米·乔·斯通菲尔德，但我们两家却有着不共戴天的仇恨。所以我不能去见他，可我无时无刻不在怀念那张英俊的面庞啊！请你把这封信带给托米·乔，他一般会在斯通菲尔德农场西边的河流附近，他们的农场就在这里的正西方。","小武哥儿"},
[107] = {"给威廉·匹斯特的信","把斯通菲尔德老奶奶的便笺交给威廉·匹斯特。","威廉·匹斯特肯定有能让这两个年轻人见面的办法！把这个便笺拿去交给威廉，他现在正住在闪金镇的狮王之傲旅店。","小武哥儿"},
[108] = {"<TXT> Mystery Reward","","","小武哥儿"},
[109] = {"向格里安·斯托曼报到", "与哨兵岭石塔中的格里安·斯托曼对话，该地点位于西部荒野中部道路旁。", "看来你也是经历过恶战的冒险者。如果你还没去过，应该向格里安·斯托曼报到。他领导的人民军正致力于保卫西部荒野的农田，肯定会需要你的帮助。通常他都会在哨兵岭的石塔里——就在西部荒野正中的大路旁。", "小武哥儿"},
[111] = {"托米的祖母","和斯通菲尔德农场的米斯通菲尔德老奶奶谈一谈。","求求你，，去和我的奶奶谈一谈吧。如果有人能想办法让我和梅贝尔在一起的话，那个人一定是奶奶。她就在我们家的屋子里。","小武哥儿"},
[112] = {"收集海藻","收集4片水晶藻叶，把它们带给闪金镇的威廉·匹斯特。","我可以为梅贝尔配制一种隐形水，这样她就可以悄悄溜出马科伦农场去见托米·乔。不过我需要一些水晶海藻来配制这种药水。水晶海藻一般生长在海里……不过有时候鱼人会收集它们。去看看水晶湖附近的鱼人身上有没有海藻，水晶湖就在闪金镇的东边。","小武哥儿"},
[113] = {"昆虫研究","把这份报告带给加基森的高级勘探员菲兹杜瑟，让他按照炼金师匹斯特苏格的要求为你复制一份报告。","高级勘探员菲兹杜瑟必须尽快看到这份报告。实际上……每个人应该知道这件事的重要性：我们正面临着一个巨大的威胁，这个威胁不仅仅涉及到塔纳利斯和加基森，如果不及时控制的话，整个卡利姆多大陆的南部地区都会有麻烦！而且这个威胁显然已经迫在眉睫了。让菲兹杜瑟把这份报告给你复制几份，然后你去把它广为传播。一定要让所有人都知道这个威胁的存在！","小武哥儿"},
[114] = {"梅贝尔的隐形水","把隐形水带给梅贝尔·马科伦。","把隐形水带给梅贝尔·马科伦。它的隐形效果应该可以持续到她见到托米·乔的时候。","小武哥儿"},
[115] = {"暗影魔法","给湖畔镇的治安官马瑞斯带回3颗午夜宝珠。","黑石氏族的兽人在赤脊山脉的侵略行动得到了暗影法师的支援，他们带来了一种具有强大黑暗力量的器具——午夜宝珠。这些宝珠给赤脊山脉的保卫者们造成了巨大的伤亡，并迫使我们放弃所有在战斗中被这种宝珠污染了的器物,因为它们已经沾染了恶魔的力量。猎杀这些黑石暗影法师，并给我带回他们的午夜宝珠来。我将会把这些东西妥善地处理掉，还这世界一片清净！","小武哥儿"},
[116] = {"旱季","湖畔镇的酒吧老板丹尼尔需要一桶雷霆啤酒，一桶葡萄酒，一瓶月光酒，还有一袋蜂蜜酒。","我最近真是感觉有点没劲，。这些酒瓶子都快空了，运酒的船也很久没来了，这都怪那些该死的兽人。也许你帮我一个小忙？我希望你能从住在西部荒野的葛瑞姆·雷酒那里搞一桶雷霆啤酒，从暴风城搞一桶葡萄酒，从夜色镇搞一瓶月光酒，还有还有，再从闪金镇搞一袋蜂蜜酒来。把这些好酒都给我弄来，我会重重谢你的。","小武哥儿"},
[117] = {"雷霆啤酒","给葛瑞姆·雷酒带去5捆蛇麻草以完成他的特酿。","快点，朋友，动作要快\n要酿更多的酒来卖\n有人要酒呀没人要菜 \n一捆蛇麻草，就够酿酒来","小武哥儿"},
[118] = {"马掌","把弗纳的便笺交给闪金镇的铁匠阿古斯。","我把所有的铁都用来打造暴风城卫兵的装备，结果没有剩余的铁来打马掌了！把这封信带给闪金镇的铁匠阿古斯，信上说明了我现在的情况并要求他运一批马掌过来。","小武哥儿"},
[119] = {"回复弗纳","回去找赤脊山的弗纳·奥斯古，把铁匠阿古斯的一箱马掌交给他。","好的，我会给他送去50套马掌……就是这些，你看，全部都打包好了，随时可以出发！告诉弗纳，我很高兴和他做生意，哦，对了，提醒他看清楚箱子上的标签！","小武哥儿"},
[120] = {"送往暴风城的信","所罗门镇长要求你给暴风城的马库斯·乔纳森将军送一封信，并且在完成任务之后尽快回报。","这真是段难熬的日子呀，<职业>。兽人的攻势没完没了，如果援军还不来的话，湖畔镇就要保不住了！我现在委托给你的这封信是非常重要的。立刻将这份报告送给暴风城的马库斯·乔纳森将军。你把信送到了那边之后，就马上带着那边回复的消息回来，无论是好消息还是坏消息，我都要尽快知道。现在就出发吧，快去快回！","小武哥儿"},
[121] = {"送往暴风城的信","将暴风城的马库斯·乔纳森将军的回信带给湖畔镇的所罗门镇长。","在我等待着国王陛下的回应时，希望你能把这封信交给所罗门镇长。快去吧，<职业>！","小武哥儿"},
[122] = {"雏龙的鳞片","从黑龙雏龙身上收集6片雏龙的腹鳞，把它们交给赤脊山的弗纳·奥斯古。","我需要一些黑龙雏龙腹部的鳞片来支付从阿古斯那里买马掌的钱。如果你能帮我搞到6块鳞片的话，在付给阿古斯一些以后……我还能用剩下的给你做点好装备。黑龙雏龙经常在湖畔镇南方游荡，猎杀它们的时候要多加小心。","小武哥儿"},
[123] = {"收货人","去闪金镇找治安官杜汉，把收货人的交易日程表交给他。","这是一张日程表，记录了某个人被称作“收货人”的人在某天某时会收到从艾尔文森林的矿洞运来的一车黄金。根据日程表所述，这个收货人好像就住在艾尔文森林东部的布莱克威尔南瓜田附近。这件事非常重要，你必须向闪金镇的治安官杜汉报告。","小武哥儿"},
[124] = {"豺狼人的乱吠","杀掉10只赤脊山蛮兵和8只赤脊山秘法师，然后向弗纳·奥斯古复命。","似乎有这些整天攻城的兽人还不够乱！我发现最近老有一些混蛋豺狼人鬼鬼祟祟地沿着山脊在我的马场北面游荡，而且还偷我的马……如果你能把这些豺狼人都干掉的话，我，还有我的马都会感谢你的。","小武哥儿"},
[125] = {"丢失的工具","湖畔镇的工头奥斯洛希望你帮他找回沉入止水湖底的工具箱。","我本来可以在这儿大干一场的, 。可是，我的工具还没到货，由于镇子被包围了，我们很难得到外面来的补给。我本来托人从闪金镇把工具用马车运过来，可是桥被砸断了，他们只好改用船运，结果那船又被兽人的投石车给打沉了。不过，算是不幸中的万幸吧，我的工具箱没坏，它只是沉进了湖底。帮我把工具箱找回来吧，，我会付给你不错的酬劳的。","小武哥儿"},
[126] = {"群山中的嚎叫","将犹勒的爪子带回给湖畔镇的弗纳·奥斯古。","，那些豺狼人居然还没死绝！我还能听见他们在湖畔镇周围的山区里打猎时发出的嚎叫声。其中有一个声音喊得最响——那是犹勒，他们的头儿。干掉犹勒，把他的手下都给轰走！把这个混蛋的爪子给我带回来。不过你得小心点，这家伙能当上他们的头儿自然是有两把刷子的。犹勒可不是个低能的混血豺狼人，他是纯种的……","小武哥儿"},
[127] = {"卖鱼","给湖畔镇的码头管理员巴伦带去10条斑点太阳鱼。","止水湖的斑点太阳鱼是天下闻名的美味。它们总是供不应求……可我这里的存货已经不够了！给我带回10条鱼来，我会好好酬谢你的。哦，如果你不会捕鱼的话……可以从鱼人那里抢来！","小武哥儿"},
[128] = {"悬赏：黑石氏族","杀死15名黑石勇士，并向湖畔镇的卫兵豪维复命。","我们一定得清剿黑石氏族。这群强盗入侵了我们的国家，占据了本应属于暴风王国的群山。根据线报说，在他们的氏族中，每支分队的领袖都被称为“勇士”，你很容易就能找到他们。他们的营地大致在北方，就在通向燃烧平原的道路西边。所罗门镇长希望有人能把这群卑鄙邪恶的家伙都消灭光。如果你有意帮助我们的话，杀死15名黑石勇士，然后向我复命。","小武哥儿"},
[129] = {"免费的午餐","将卫兵帕克的午餐带给他，他就在通向夜色镇的路上巡逻。","你能帮我一个小忙吗？我给卫兵帕克准备好了午饭，可他正在值勤……他是一个又高又壮的暴风城卫兵。他在外面是能自己保护自己的，可我们这样的寻常市民可不行，所以我没法去给他送饭……所以呢，如果你能帮我把他的午餐带给他的话，我也会给你提供一份免费的午餐！帕克就在通往暮色森林的路上巡逻。","小武哥儿"},
[130] = {"寻访草药师","找到草药师玛蒂·詹罗斯，和她谈一谈。","你回到达希那边的时候，能替我捎几朵花给她吗？你可以在湖畔镇西边的草药店里买到花。不过，你去买花的时候……千万别告诉药草师玛蒂这花是谁买的，也别说是要送给谁的……","小武哥儿"},
[131] = {"水仙诉衷情","将水仙花送给达希。","这是你要的花。我为你选了水仙，这是我最喜欢的花儿！","小武哥儿"},
[132] = {"迪菲亚兄弟会","将威利的便笺交给西部荒野的格里安·斯托曼。","我现在可是冒着生命危险在和你说话。迪菲亚那帮人也是听命于某个神秘人士的，我上次听说他们与许多种族都有过合作，豺狼人，狗头人，甚至还有地精。把这张便笺交给斯托曼。上面写着我所知道的关于迪菲亚兄弟会的一切。","小武哥儿"},
[133] = {"食尸鬼假人","收集7个食尸鬼的肋骨，然后把它们交给亚伯克隆比。","我住得离镇子太远了，根本得不到保护。那些食尸鬼和行尸走肉还没有把我吃掉简直是个奇迹！其实昨天还有一群噬骨者来敲击我房子四周的墙！我得做个假人，一个用来吓唬食尸鬼的“稻草人”。我需要食尸鬼的肋骨来制作这个假人。你可以从食腐者、噬骨者、食脑者、腐烂者和瘟疫食尸鬼身上拿到这东西。给我带足够的肋骨来，我就会给你一些奖赏。","小武哥儿"},
[134] = {"食人魔盗贼","把亚伯克隆比的箱子拿回来交给他。","几个星期前，我离开家去远处采草药，有一群食人魔袭击了我！我落荒而逃的时候丢了一箱工具和草药。这些食人魔在把我赶跑之后大摇大摆地回到了暮色森林南边的食人魔山上，我的箱子肯定就在那一带。请帮帮我吧，，我很需要这个箱子，请你一定要帮我拿回来。","小武哥儿"},
[135] = {"迪菲亚兄弟会","将威利的便笺交给暴风城的马迪亚斯·肖尔。","我现在很想知道威利所提到的“石匠”是个什么意思，或许这只是一个口误？石匠公会跟迪菲亚真的有联系吗？或许暴风城军情七处的首领马迪亚斯·肖尔会知道真相。把威利的便笺拿给他，看看他对这个越来越大的谜团有什么想法吧。他就在旧城区的兵营里。","小武哥儿"},
[136] = {"杉德尔船长的宝藏","找到杉德尔船长的手提箱，在箱子中寻找下一条线索。","如果你读到这封信的话，那就意味着我，杉德尔船长，已经长眠在深深的水底了。所以，只要你按我的提示去做，我的宝藏就是你的了。首先你要找到一只小提箱，它应该就在西部荒野西海岸的某处船只残骸旁，如今八成已经快被沙子埋起来了。海岸边有许多处船只的残骸，但只有一只沉船旁有个锈掉的锚。箱子就在锚的旁边！在箱子里面，你可以找到下一条线索。","小武哥儿"},
[137] = {"暴风城奖状","将从艾尔文森林得到的奖状交给暴风城的马库斯·乔纳森将军，就可以在他那里挑选一件防具。","如果你从我们的治安官手中得到了奖状，就把它带给我。你可以因此而得到狮徽手套。","小武哥儿"},
[138] = {"杉德尔船长的宝藏","找到废弃烟囱旁的老木桶，在桶里寻找下一条线索。","你开始读小条上的字：干得好，哥们！现在你可以开始向东走，到悬崖边的路旁好好找找，看有没有一处破烟囱，你可以在那旁边的木桶中找到下一条线索。","小武哥儿"},
[139] = {"杉德尔船长的宝藏","在风车旁的一个空水罐里寻找下一条线索。","仔细搜索了木桶了之后，你发现了一小片羊皮纸。上面写着：现在，从桶这里转向北，像乌鸦飞翔一般绝不回头，一直走到你看见了海边悬崖上的风车为止。找到那风车旁的一个空水罐。仔细检查那个水罐，你就可以找到你要找的东西了。","小武哥儿"},
[140] = {"杉德尔船长的宝藏","找到杉德尔船长的箱子并打开它，取得你的奖励。","显然，在这只旧罐子中藏着另一条有关杉德尔的宝藏的线索。纸上有几处墨水已经化开变得模糊不清，而且泛着一股威士忌的味道，不过你还是能从中辨认出这样的字迹：看来你找到我的威士忌罐子了，你离我的财宝已经很近啦！只要向西走到海边，然后一直向西游，你就可以游到放着小宝箱的岛上啦！","小武哥儿"},
[141] = {"迪菲亚兄弟会","将肖尔的报告交给西部荒野的格里安·斯托曼。","过去的石匠公会是由一个名叫艾德温·范克里夫的人运营着的。第一次兽人战争结束后，范克里夫承接下了在兽人们留下的废墟上重建暴风城的重任。很显然，范克里夫对国王陛下在重建工程完成之后给予他们的待遇非常不满意。总之，解释这一大堆具体的事情要花些时间。我这里有一份详细的说明，让你拿到西部荒野去交给你的雇主。你得马上把这个给他带去！","小武哥儿"},
[142] = {"迪菲亚兄弟会","追捕西部荒野的迪菲亚信使，并将他身上携带着的信件交给斯托曼。","我们必须得找到迪菲亚兄弟会藏身的地方。，我的探子报告说，迪菲亚帮的信使们经常出现在月溪镇、金海岸矿洞和詹戈洛德矿洞之间的路上。我希望你能抓住一个信使，要是他试图反抗，就干脆把他干掉，然后把他身上所有的东西带回来。","小武哥儿"},
[143] = {"送往西部荒野的信","所罗门镇长要求你给西部荒野的格里安·斯托曼送一封信。","暴风城的军队似乎遇到了些麻烦事，他们早就该到这里增援了，但直到现在还连个人影都没有。我们没多少时间可供浪费了！我不能再这样坐视人民继续无谓地牺牲而不去要求更多的增援。我听说西部荒野组建了一支民兵部队。把这封信带给他们的领袖格里安·斯托曼。或许斯托曼的人在国王陛下的部队到达之前能来帮忙抵挡上一阵。","小武哥儿"},
[144] = {"送往西部荒野的信","将格里安·斯托曼的回信带给所罗门镇长。","所罗门镇长的信让我感到心痛。但显然他并不知道西部荒野的战事也很吃紧——或者他知道，但不得不抱着一丝希望来寻求我们的帮助。如果不是暴风城对西部荒野的人民不闻不问的话，我们也不会需要建立民兵组织的。将这封回信带给你在赤脊山的主人吧，<职业>。请转告他，我的心情也因为那么多勇士的牺牲而变得十分沉重。","小武哥儿"},
[145] = {"送往夜色镇的信","所罗门镇长要求你给夜色镇的艾尔罗·埃伯洛克公爵送一封信。","看来我又得有事麻烦你了。我写一了封信给艾尔罗·埃伯洛克公爵，请求他从他的精锐部队——暮色森林守夜人——中抽出一些人来协助湖畔镇的防务。这封信必须马上呈送给他，而且你在旅途中要多加小心。埃伯洛克公爵是夜色镇的行政官，那座小镇就在暮色森林中，小心不要迷路了。","小武哥儿"},
[146] = {"送往夜色镇的信","将埃伯洛克公爵的回信带给所罗门镇长。","如果我不是和所罗门镇长私交甚密的话，我一定会以为他是个疯子的。因为暴风城拒绝出兵援助，就让我们把守夜人部队派去湖畔镇？守夜人部队就是因为这里被邪恶的魔法所影响才建立起来的。如果我把他们派离这里的话，恐怕还没等到他们走出森林，这里就会被邪恶的势力彻底吞没。把这封回信带给你在湖畔镇的主人吧。","小武哥儿"},
[147] = {"猎杀收货人","找到“收货人”并将他杀掉，然后带着收货人的戒指回来见治安官杜汉。","如果这个“收货人”是私自从我们的矿洞里开采黄金的话，那么他就是在偷窃王国的金库！把他就地正法，然后把他的交易日程表上提到的戒指带给我。也许这枚戒指能告诉我们这个“收货人”是在为谁工作……那张交易日程表上说“收货人”就藏在布莱克威尔南瓜田里，你应该到那儿去找他。","小武哥儿"},
[148] = {"来自夜色镇的货物","去和伊瓦夫人谈一谈。","哦，一个可怜的老人家还能做点什么呢？我需要从夜色镇拿点东西过来，不过路途太遥远，我又太老了……实在是走不动啊。你能去夜色镇给我拿点幽灵的发丝回来吗？你可以向伊瓦夫人要这东西，她的家就在夜色镇的广场旁。","小武哥儿"},
[149] = {"幽灵的发丝","把鬼梳带给盲眼玛丽。","有个可怜的亡魂叫盲眼玛丽，她总是在夜色镇南部小山上的农宅里出没。拿着这把鬼梳，让盲眼玛丽用它梳头。然后再把梳子拿回来，我可以从上面收集到需要的幽灵的头发。小心点，那个屋子里潜伏着一些可怕的东西……","小武哥儿"},
[150] = {"鱼人偷猎者","给湖畔镇的码头管理员巴伦带回8片鱼人的鳍。","鱼人们如今也成了一个问题。大群的鱼人渔民在止水湖沿岸下锚撒网，都快把湖里的鱼捞光了！我们得在他们把湖里的鱼都吃光之前把他们赶走！去猎杀那些鱼人！给我带回8片鱼人的鳍来，我会奖励你的。","小武哥儿"},
[151] = {"老马布兰契","西部荒野的弗娜·法布隆要求你带给她8捧燕麦。","可怜的老马布兰契呀！我们让它干的活儿实在是太多了，看来它已经要累垮了。虽然我在离开农场以前就喂过了它，可谁会料到马车会在半路上坏掉呢？如果你能从田里替它取来几捧燕麦的话，我会对你感激不尽的。我想，你可以在田边找到足够的燕麦，不过你首先要将周围那些可怕的机器人先干掉。","小武哥儿"},
[152] = {"清理海岸","杀死7只鱼人潮行者、7只鱼人战士、7只鱼人智者，还有7只鱼人滩行者，然后向西部荒野灯塔中的葛瑞森船长复命。","你或许已经注意到了，海岸线上有许多船只的残骸。无尽之海确实是非常凶险，我们必须确保西部荒野海岸线上没有那些该死的鱼人到处徘徊，只有这样水手们才能安全地找到靠港的路线。去杀死7只鱼人潮行者、7只鱼人战士、7只鱼人智者，还有7只鱼人滩行者，完成任务之后到我这里来领取奖赏。","小武哥儿"},
[153] = {"红色皮质面罩","给哨兵岭的哨兵加里安带回15条红色皮质面罩。","我们与迪菲亚兄弟会的战局总是瞬息万变。最近我一直在监视着他们的活动，根据长期观察的结果，我发现他们的成员都戴着一种特殊的红色皮质面罩。给我带15条这种面罩回来吧，我会给你奖励的。","小武哥儿"},
[154] = {"归还梳子","把幽灵的梳子拿回去交给夜色镇的伊瓦夫人。","不！！！！！快把这个梳子拿走！我是个怪物，不会再有人说我好看了！","小武哥儿"},
[155] = {"迪菲亚兄弟会","护送迪菲亚叛徒前往迪菲亚兄弟会的秘密藏身处。迪菲亚叛徒把你带到范克里夫和他的手下的巢穴之后，尽快回去向格里安·斯托曼汇报相关信息。","这么说，斯托曼就派了你这么一个芦柴棒一样的家伙来保护我？希望你能行，当然如果你再叫上几个朋友帮忙就好了。你知道你要做些什么吧？我会把你带到迪菲亚盗贼的巢穴去，而你呢，就得保护好我。当然，你最好离我近点，越近越好。现在全迪菲亚兄弟会的人都想要我的脑袋呢。要是他们看见我和你在一起，一定会来把咱们都宰了的。等你和你的朋友准备好之后，就来跟我说一声吧。","小武哥儿"},
[156] = {"收集腐败之花","收集8个腐败之花，交给夜色镇的旅店店主斯密茨。","如果你能给我找些腐败之花来，我就可以酿造很多僵尸酒。这种花很难找到，听说在恐怖骸骨和骸骨魔的头骨里可以找到这种花……不过至今我还没有亲眼见过！乌鸦岭墓地和静谧花园里都有很多这样的骷髅，你可以在寻找腐败之花的时候顺便把他们干掉，夜色镇的人民会感激你的。","小武哥儿"},
[157] = {"幽灵的发丝","把幽灵的发丝交给亚伯克隆比，他住在乌鸦岭墓地北边的房子里。","这是你要的线，。它有很多种用途，比如用来束缚邪恶的亡魂，或者给没有生命的东西注入生命。","小武哥儿"},
[158] = {"僵尸","去和旅店店主斯密茨谈一谈。","我需要一瓶叫做僵尸酒的饮料。夜色镇血鸦旅店的店主斯密茨应该有些存货。最近晚上寒风刺骨，我得来点僵尸酒，好让我的血液重新沸腾起来。","小武哥儿"},
[159] = {"僵尸酒","把僵尸酒交给乌鸦岭墓地北方小屋里的亚伯克隆比。","这是你要的僵尸酒……不过要小心一点，这酒烈得足以把死人给呛活过来。","小武哥儿"},
[160] = {"给镇长的信","把亚伯克隆比的信交给夜色镇的艾尔罗·埃伯洛克镇长。","请把这封信交给夜色镇的艾尔罗·埃伯洛克镇长。我和他是老朋友了……我敢说，当他读完信，并且知道了你为我做的事情……他一定会和我一样高兴的！哈哈哈哈！","小武哥儿"},
[161] = {"水坝危机","主工程师辛德维尔七世要你把怪味粉末交给丹莫德的炸药专家阿什兰·暗石。","如果我的猜测没错的话，这是某种火药粉末。应该找个爆破专家来分析一下这到底是什么东西。阿什兰·暗石就在丹莫德和萨多尔大桥一带负责那里的警戒工作，我需要你尽快去找他，这是一段重要而危险的旅程，。走过奥加兹大门，沿着穿过湿地的大路一直到丹莫德去找爆破专家阿什兰·暗石。留心我的建议：沿着大路走，不要停留！","小武哥儿"},
[162] = {"异种蝎的威胁","把报告带给达纳苏斯的格拉希娜·灵风。","我希望你尽快把这份报告送到对处理此类事件有经验的人手里。我知道有一位名叫格拉希娜·灵风的暗夜精灵学者，她致力于研究卡利姆多大陆上那些与艾泽拉斯的普通生物截然不同的生物形态，她简直就是一本活的生物书！如果你想要知道我们面临的是怎样的威胁，以及如何解决这个威胁，那就把这份报告交给她吧，我们现在急需她的帮助。我听说她住在达纳苏斯的月亮神庙里。","小武哥儿"},
[163] = {"乌鸦岭","查出是什么东西在乌鸦岭神出鬼没。","乌鸦岭出了点问题，$n。卡洛尔说那边的房子里有什么人——或者怪物——出没。有两个晚上，他发现有个身影在活动，第三天晚上，某扇窗户里还射出了灯光。你如果真的关心暮色森林的安危，就去查一查，看看是什么样的怪物在乌鸦岭出没。","小武哥儿"},
[164] = {"斯温的货物","把补给物资带给斯温。","你认识斯温吗？谢天谢地，终于有人能帮我了！斯温和他的同伴在暮色森林的西北边有个营地。不幸的是，他们的人手太少了，少到派不出人回镇里来取一些必需的补给品。你能把这些物资带给斯温吗？","小武哥儿"},
[165] = {"隐士","去乌鸦岭墓地附近的小屋查看老人的情况。","有个老人经常到镇里来买东西，不过我已经有些日子没见过他了。如果我没记错的话，他就住在一个可以俯视乌鸦岭墓地的小屋里。你能不能去看一看出什么事了？","小武哥儿"},
[166] = {"迪菲亚兄弟会","杀死艾德温·范克里夫，把他的头交给格里安·斯托曼。","这里恐怕还有最后一个任务需要你来完成。我们必须派人去除掉艾德温·范克里夫。说实话，就这样对一个活生生的人宣判死刑，这实在令我非常痛心，但为了西部荒野人民的利益，我不得不让范克里夫永远安息。把范克里夫干掉之后，提他的头来见我。","小武哥儿"},
[167] = {"我的兄弟……","将工头希斯耐特的探险者协会徽章交给暴风城的维尔德·蓟草。","那时我们正在一个大矿洞中工作，就是那个隐藏在西部荒野月溪镇中的谷仓下面的矿洞……没人知道当时到底是怎么回事，总之矿道突然坍塌了，我逃了出来……可其他人就没那么好运了……我是说，从那以后我就再没听到过其他人的消息了。看上去你的运气可能会比我们好一点。如果你能帮我找到弟弟的话，我会非常感谢你的。他总是戴着一块探险者协会徽章，所以如果你找不到他的话，至少那块徽章能给我带来一些安慰……","小武哥儿"},
[168] = {"收集记忆","给暴风城的维尔德·蓟草带回4张矿业工会会员卡。","在那个可怕的日子，我的许多朋友都被埋在了矿洞里。如果你在冒险中正好路过月溪镇的那处矿洞的话，请帮忙留意一下有没有什么可以辨认他们身份的标志物品。如果你能找到他们的矿业工会会员卡的话，请一定要带给我，我好知道他们的结局，并与他们的家人谈谈如何为这次恐怖的事故善后。","小武哥儿"},
[169] = {"通缉：加塞尔佐格","杀死加塞尔佐格并把他的头颅割下，向湖畔镇的所罗门镇长复命。","悬赏！加塞尔佐格是黑石氏族袭击石堡和多次劫掠湖畔镇等行动的领导者。他是个十分危险的家伙。根据线报，他最近就躲藏在刚刚被他们攻陷的要塞中，谋划着黑石氏族的下一次劫掠行动。我们必须不惜一切代价把这些在我们的国土上横行的兽人镇压下去。如果谁能把加塞尔佐格的头带到所罗门镇长面前的话，他将会得到重赏。","小武哥儿"},
[170] = {"新的威胁","巴尔林·霜锤让你去杀死6个石颚穴居人和6个壮实的石颚怪。","我希望你能帮我们一把，<职业>。在上一次穴居人袭击之后，我们的人手就明显不够了。我听说他们现在已经遍布我们的国土，看来寒脊山谷也不能避免。东南部的山区和湖畔已经到处都是穴居人的身影了。糟糕的事情还不仅仅是这些，几天前，他们袭击并占领了我们西边的营地！我们这儿有些人手不足，$g孩子:姑娘;，我们需要强大的军队帮助我们赶走这些家伙。","小武哥儿"},
[171] = {"联盟孤儿的看护者","去暴风城的教堂广场见孤儿监护员奈丁加尔并带上这个人类孤儿哨. ","你的心肠真好啊，。我做梦都没想到我在儿童周会这么开心。谢谢你，我不想伤心因为发生在自己和他人身上的事，我的父辈告诉我忘记任何令人伤感的事。你知道吗？当我长大了，我想成为向你一样的英雄非常抱歉，是我回家的时候了，让我们回去吧，我要告诉监护人。你是一个多么伟大的人！ ","小武哥儿"},
[172] = {"儿童周","使用兽人孤儿哨与你即将在儿童周期间照顾的孩子进行对话。","你愿意帮助我们的孤儿院？太感谢你了，我的朋友。感谢你愿意在儿童周的这段时间内为我们提供帮助。拿着这只哨子，你只能在儿童周的这7天内使用它。当你使用它的时候，就可以和那些由你负责照看的孩子进行对话，再次使用就可以解散那个孩子。不管怎么样，——使用这个口哨，见一见你的小朋友！我相信孩子们一定很想见到你。","小武哥儿"},
[173] = {"森林里的狼人","为夜色镇的卡洛尔杀掉6个夜行织影狼人。","黑暗的势力正在笼罩暮色森林，而卡尔文主人正在努力驱除邪恶，保护夜色镇人民的安全是我们的职责。你觉得自己有能力加入我们吗？我以前也跟你想的一样，因为对哨所的安逸悠闲感到绝望，我投靠了卡尔文主人。如果你想要证明自己的实力，不是只靠嘴皮子说说就可以的。去找夜行织影狼人较量较量吧，他们经常在阳光树林——阳光，哈！——和烂果园出没。","小武哥儿"},
[174] = {"仰望星空","夜色镇的维克托·安特拉斯要你给他找一根青铜管。","我的侏儒朋友考格说过要帮我制造一个可以用来观察星空的装置。我相信除了魔法之外，还有别的理由可以解释发生在这片森林中的奇怪变化。根据考格的设计图，首先要去找一个手艺高超的技师，让他帮忙造一根青铜管。","小武哥儿"},
[175] = {"仰望星空","找到玛丽，说服她借给你一个反光镜，用于维克托的计划。","根据考格的设计图，现在我还需要一个东西来反射光线。我记得有个叫玛丽的女人因为总是戴着一副眼镜而在这一带人人皆知，你可以去找找她，向她借一个反光镜。我记得她曾经住在暮色森林南部……","小武哥儿"},
[176] = {"通缉：霍格","杀死豺狼人霍格，把他那巨大的豺狼人爪带给治安官杜汉。","通缉：霍格巨型豺狼人霍格，现正在艾尔文森林西南部的树林里游荡。他成功地对抗了目前为止所有追捕他的行动。暴风城已经为除去这只豺狼人设下了酬金，想得到酬金的猎手必须向闪金镇的治安官杜汉提供杀死霍格的证据。","小武哥儿"},
[177] = {"仰望星空","从疯狂的食尸鬼那里拿回盲眼玛丽的眼镜，把它交给夜色镇的维克托。","那副眼镜是我最珍贵的宝物，不过在发生了一件事情之后……我就把它丢在谷仓后面了。有个疯狂的食尸鬼曾经在那一带徘徊，可能是它把东西给捡走了。有人说那个邪恶的家伙住在静谧花园墓场出现。","小武哥儿"},
[178] = {"塞欧克瑞图斯的坠饰","将不再发光的暗皮坠饰带给法师塞欧克瑞图斯。","<你听到了某种飘渺的声音>可别被吓着。我是塞欧克瑞图斯，艾尔文森林的阿祖拉之塔里的高阶法师。你手上拿着的饰物是暗皮豺狼人和他们的主子莫甘斯用来联络的工具。根据这几个月的研究，我也已经掌握了使用这些饰物进行通信的方法。如果你能听到我所说的话，就证明我的法术成功了。把这个饰物带给我，我会给你酬劳的。","小武哥儿"},
[179] = {"矮人的交易","斯登·粗臂想要8块硬狼肉。","嘿，你是新来的吧？看来你需要些暖手的东西，对吗？我想你应该想要一副保暖的手套。我是个热心肠，很愿意给你一副手套，不过我有个条件。你帮我弄些狼肉来，我保证你不会被冻掉手指头。你觉得怎么样？","小武哥儿"},
[180] = {"通缉：范高雷中尉","杀死范高雷并将他的手掌割下，向湖畔镇的所罗门镇长复命。","悬赏：范高雷恶行累累的豺狼人头目范高雷在湖畔镇及王国的敌人莫甘斯的指使下，带着暗皮豺狼人氏族到处为非作歹。镇长所罗门下了命令，悬赏杀死这个万恶的东西。将他的手掌割下来拿给镇长，以此证明他的死亡。","小武哥儿"},
[181] = {"仰望星空","在暮色森林南部的食人魔土丘上找到扎克乌尔，把他的单片眼镜带回夜色镇交给维克托。","根据考格的设计图，现在我们还需要一种透镜来完成整个装置。我知道什么地方有合适的透镜，不过很难拿到。有个叫扎克乌尔的食人魔住在暮色森林南部的土丘上，如果可以的话，你去把他的单片眼镜拿来吧，我可以用它做透镜。","小武哥儿"},
[182] = {"巨魔洞穴","格瑞林·白须要你去杀掉14个霜鬃巨魔幼崽。","我和我的兄弟森内尔被派来调查丹莫罗各个地区的巨魔活动情况。参议院正在忙着对付那些不知道从哪里冒出来的穴居人，已经没工夫再关心巨魔了。据我所知，在寒脊山谷南部山洞里生活的巨魔们日子并不好过，所以我觉得派大批军队去围剿它们是杀鸡用牛刀，只要一两支训练有素的小分队就已经绰绰有余了。你也许能给我们提供些帮助吧？当然，我会对你的帮助给予一定的报酬。","小武哥儿"},
[183] = {"猎杀野猪","塔林·锐眼让你去杀掉12只小型峭壁野猪。","没什么能比得上用一整天的时间去打野猪更让人愉快的了，对吧？不过，寒脊山谷里的野猪太多了，你几乎已经不可能在那里再感受到狩猎的乐趣。你根本不需要去激怒它们，因为它们早就是怒气冲天，随时准备用獠牙把你拱上天了！事实上，这些过剩的野猪已经对我的日常狩猎形成了威胁。长话短说吧，如果你能帮我杀掉些野猪，我真的会非常感激你的。","小武哥儿"},
[184] = {"法布隆的地契","把法布隆的地契交给农夫法布隆。","这是西部荒野一片农田的地契，由西奥多·法布隆和他的妻子弗娜·法布隆联名签署。地契背面还有潦草的字样：“我们到法布隆家里走了一遭，弄到了他的地契。我们觉得你可以很轻易地照着这张样本给自己也造出几份地契来。法布隆家的人不会找我们的麻烦，我最后一次看到他们的时候，他们的四轮货车坏在了路上。”你认为法布隆夫妻俩可能正在到处找这张地契……","小武哥儿"},
[185] = {"猎虎","奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只荆棘谷猛虎幼崽。","当我还只是个小女孩的时候，我的父亲就开始训练我捕猎老虎。一般来说，你会发现虎崽是非常容易追踪和猎杀的。因此，要猎杀它们根本不是什么麻烦的事情，你在探险队的营地附近很容易就能找到虎崽。让我们来测试一下你的追踪技巧，看看你是否能猎杀这些野兽。","小武哥儿"},
[186] = {"猎虎","奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只荆棘谷猛虎。","你学得很快，<职业>。让我们来测试一下你是否能杀死成年的猛虎，这次你的任务是去杀死十只荆棘谷猛虎。","小武哥儿"},
[187] = {"猎虎","奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只老年荆棘谷猛虎。","现在我要教你些更高深的东西，然后测试一下你的技巧。去杀死十只老年荆棘谷猛虎以证明你的能力吧。如果你能做到这些的话，你就可以去面对最后的挑战了，最终，我会在奈辛瓦里大人的面前授予你猎虎大师的称号。老年荆棘谷猛虎不但非常难找，而且也是最难以对付的。","小武哥儿"},
[188] = {"猎虎","奈辛瓦里远征队的艾耶克·罗欧克要求你杀死辛达尔并带回它的爪子。","现在你要面对的将是最后的挑战。我们这几周来一直在追踪一只神秘的老虎，我们称它为辛达尔。现在让我们来看看你能不能做到一件以前从来没有任何<种族>可以做到的事吧：去猎杀辛达尔，把它的爪子带回来以证明你完成了任务。追踪它可不是一件简单的任务。","小武哥儿"},
[189] = {"血顶巨魔的耳朵","给藏宝海湾的科博克带回15只血顶巨魔的耳朵。","该死的巨魔！他们杀死了我们派到丛林里去的人！我已经在和他们的冲突中损失太多优秀的护卫了。血债必须血来偿！这让我怎么向大财主里维加兹解释呀？是该做决定的时候了……想想看，科博克……你可不是被派到这里来整日无所事事的……啊，有啦！你……你就是$n，是不是？你是来帮助我的，是不是？这份工作的奖励可是很丰厚的哦！嗯嗯，给我带15只血顶巨魔的耳朵来，我就重重地酬谢你，如何？","小武哥儿"},
[190] = {"猎豹","奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只猎豹幼崽。","如果你也想加入这个由赫米特先生组建的最强狩猎队，就必须先证明自己是一个能干的猎豹高手。放心，一开始不会太难的，千万别轻言放弃。你先去猎杀10只猎豹幼崽热热身吧。当然，这只是让你热热身而已……","小武哥儿"},
[191] = {"猎豹","奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只黑豹。","现在你已经可以更进一步了。如果你想继续证明自己有资格和我们这些优秀的狩猎能手合作的话，就去猎杀十只黑豹。这些大家伙们都很强壮，它们可不比之前的猎豹幼崽那么好杀。","小武哥儿"},
[192] = {"猎豹","奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只深喉猎豹。","接下来的部分可就比较困难了。一个真正的猎豹能手必须要有能力杀死深喉猎豹这种荆棘谷中最危险的生物。去杀死十只深喉猎豹，向我们证明你的猎豹能力吧！如果你很难找到它们的踪迹的话，就埋伏起来等它们出现……","小武哥儿"},
[193] = {"猎豹","奈辛瓦里远征队的埃尔加丁爵士要求你杀死巴尔瑟拉，并带回它的牙。","你几乎已经证明自己是一位优秀的猎豹能手了。有一只名叫巴尔瑟拉的豹子目前正潜伏在这片森林里，我们一直都没能找到它。去试试猎杀巴尔瑟拉吧，记得用上你所掌握的全部技巧。将巴尔瑟拉的牙齿带回来给我，如果你成功了，你就将赢得我的尊敬！","小武哥儿"},
[194] = {"猎龙","赫米特·奈辛瓦里二世要求你杀死10只荆棘谷迅猛龙。","你觉得你的狩猎技术是最顶尖的？我马上就检验一下，看看你是不是在骗人。到丛林里去杀几只荆棘谷迅猛龙，这样一来我们就知道你是不是所谓的王牌猎人了。当然，我是绝对不会告诉你在哪里才能找到它们的！追踪野兽本身就是挑战的一部分。","小武哥儿"},
[195] = {"猎龙","赫米特·奈辛瓦里二世要求你杀死10只鞭尾迅猛龙。","现在让我们来看看你能不能应付更大的挑战吧。杀进丛林里去，给我干掉十只残暴的鞭尾迅猛龙。可别说你不行啊！","小武哥儿"},
[196] = {"猎龙","赫米特·奈辛瓦里二世要求你杀死10只丛林捕猎者。","让我们来看看你能不能对付下一个挑战吧。这附近栖息着一种非常狡猾的迅猛龙，我们叫它丛林捕猎者。它们远比你之前捕猎的目标更难追踪和猎杀。猎杀十只丛林捕猎者，然后我就会告诉你这里最惹眼的目标是什么。","小武哥儿"},
[197] = {"猎龙","赫米特·奈辛瓦里二世要求你杀死荆棘谷中最危险最狡猾的迅猛龙泰希斯。","你已经证明了自己在这片丛林里的每次捕猎都不会空手而归，总能带回我们要求的猎物，因此我决定告诉你有关那只我从来也没能猎到的、最凶暴最残忍的迅猛龙的事情，艾耶克把那只迅猛龙叫作泰希斯。如果你想证明自己真的是个捕猎专家的话，就把泰希斯杀掉，把它的爪子给我带回来，这可是其他王牌猎人都从没完成过的壮举。","小武哥儿"},
[198] = {"列兵萨尔森的补给物资","将杂七杂八的地精补给物资带给列兵萨尔森。","嗯。没错，我这里确实有些适合你做的事。目前部署在荆棘谷北部的多伦上尉和他的部下需要我们的定期补给。不过由于巨魔的伏击，他们一直没能得到补给，所以我得找人来帮我处理这件事。多伦的营地就在从暮色森林进入荆棘谷的道路的西北方，你只要把补给品交给列兵萨尔森就行了，相信他会处理好的。你要记住，如果你失败了的话，就得赔偿我们的损失。当然，你也可能会死在路上……","小武哥儿"},
[199] = {"水坝危机","回去见主工程师辛德维尔七世，把你找到的线索交给他。","你取了些怪味粉末的样品。","小武哥儿"},
[200] = {"书呆子赫罗德","找到书呆子赫罗德的档案。","既然连库尔森都知道了这个秘密，那么他们一定也在我们这边安插了一个卧底。我们必须得搞明白这些机密内容是怎么泄露出去的！萨尔森在那边的线人是书呆子赫罗德，他是库尔森的后勤官，了解库尔森的营地里的一切事务。如果你能搞到他的笔记或者档案什么的话，或许我们能分析出萨尔森到底是怎么被发现的。当初，我们还跟库尔森一起共事的时候，书呆子的办公室是在营地里唯一一座两层房屋的二楼，他的档案应该还在那里。","小武哥儿"},
[201] = {"调查营地","找到猎人营地并向藏宝海湾的克拉兹克报告这个营地的位置。","我收到一条报告说，有一群猎人在风险投资公司营地所在的纳菲瑞提湖的上游建立了一片营地。通常我根本不会在意这件事，但当我听说赫米特·奈辛瓦里二世也是那群猎人中的一员时，我改变了想法。那家伙可是个名声显赫的人物，如果你了解我的意思的话，就会不像现在这样无动于衷了。你为什么不去那片营地里侦察一下呢，$n？去看看他们到底想干点什么吧。","小武哥儿"},
[202] = {"库尔森上校","杀掉6名库尔森精英和4名库尔森副首领，并将库尔森的头颅交给反抗军营地里的多伦上尉。","你一次又一次地证明了自己的能力，而你的足智多谋略似乎甚至能与库尔森媲美。如果……如果你愿意彻底投身到与库尔森斗争的事业中去的话……也许你将成为我们反抗军的救星！他就躲在那个名叫“储藏室”的洞穴深处发号施令。你必须进入那个洞穴，干掉他身边的保镖，最终把库尔森和他的副官们都给除掉。出发吧，。我们的生命与希望，如今都已经全部掌握在你的手中了。","小武哥儿"},
[203] = {"以彼之道还施彼身","杀死15名库尔森丛林战士，然后向反抗军营地的尤瓦中士复命。","我们正在与库尔森进行一场艰难的战斗。他是个非常优秀的战术大师，而且他的手下士兵的数量是我们的十倍！如果我们想要胜利的话，就必须使用他擅长的战术来对付他。到他在东边设立的营地里去，杀掉他的士兵，越多越好，然后在增援赶来之前撤退。","小武哥儿"},
[204] = {"库尔森的药物","给反抗军营地里的尤瓦中士带回7份密林药剂和1份毒草汁液。","要想和库尔森搏上一搏，我们就必须削弱他们的医疗队伍。他在那里聚集了大批医疗人员，他们能用密林药剂治疗自己的部队，并用毒草汁液对我们的人下毒。我们要用这些药物来治疗我们自己的战士，同时我们也需要一份毒液的样本来研制解药。到库尔森的营地去把这两样东西找来吧，药品应该就在那些医疗人员和战士的身上，而毒草汁液大概是保存在营地中的一些物资箱里的。","小武哥儿"},
[205] = {"巨魔巫术","给叛军营地的尼麦兹修士带回4只劈颅巨魔的神像。","在我研究这些巨魔传说的时候，我希望你能帮我收集一些巨魔们施展邪恶魔法时必备的法器。到南边的那个劈颅巨魔氏族的地盘上去，从他们的巫医和秘法师那里弄一些劈颅巨魔的神像回来吧。","小武哥儿"},
[206] = {"麦佐斯","将心灵之眼交给反抗军营地里的尼麦兹修士。","库尔森的确是该死，不过……到底是谁将他带上了这条邪恶的道路呢？通过研究，我已经找到了真相：是一个名叫麦佐斯的食人魔法师干的。他住在荆棘谷东部的食人魔山中，据说他擅长心灵控制魔法，我也确信正是他使得库尔森上校堕落的。如果麦佐斯继续活在这世上，他的邪恶法术就有可能影响到更多人，或许又会出现另一个库尔森上校。杀死他，把他的心灵之眼带回来，这正是他用来诱惑他人堕落的物品。","小武哥儿"},
[207] = {"库尔森的秘密","找到4块石板并将上面的内容带回去交给尼麦兹修士。","库尔森上校曾是个伟大而高贵的人，我必须得找到让他堕落至此的原因！他一定是被巨魔的魔法给控制了。要想搞清楚这一点的话，我们就得先研究一下巨魔的传说故事。据说荆棘谷中的巨魔遗迹中隐藏着四块石板，我必须得看看这些石板上到底记述了些什么东西！你去给我拓一份这些石板上的文字来，把拓片都交给我。第一块石板在巴拉尔废墟里，第二块石板在暗礁海的海底，第三块和第四块应该都在祖昆达废墟里。","小武哥儿"},
[208] = {"王牌猎人","赫米特·奈辛瓦里二世要求你将虎王邦加拉什的头带回来给他。","，你现在已经成为了一位够格进入我们狩猎队的猎手了。无论是洛丹伦的战场还是危机四伏的丛林，我在哪里都没有见过有谁能像你这样拥有如此强大的战斗能力。你成功地杀死了凶残的辛达尔，狡猾的巴尔瑟拉和强悍的泰希斯。但对于这片丛林中的猎人们来说，虎王邦加拉什的头才代表着至高无上的荣耀。这只白虎正是我来这里的原因，我注意它已经很久了。如果你能杀死虎王邦加拉什，那么你无疑是这里最优秀的猎人。","小武哥儿"},
[209] = {"劈颅巨魔的獠牙","给藏宝海湾的科博克带回18根劈颅巨魔的獠牙。","靠不停地猎杀老虎来保证对南海岛屿的虎牙出口实在是苦差事，不仅难度高，而且花费也也高。幸亏我们找到了一种替代品，就是这些劈颅氏族的巨魔的獠牙。嘿，只要你不说，买家就不会知道，对吧？给我搞一批巨魔獠牙来吧，这样我们就能应付每月一次的供货啦！","小武哥儿"},
[210] = {"克拉兹克的烹调锅","把克拉兹克的烹调锅带给藏宝海湾的地精克拉兹克。","在营地里，我是专门负责伙食的。过去的活真的很多，让我每天都要忙到死，直到我从藏宝海湾的地精商人那里买了台多功能机械烹调锅才有所改观。这锅实在是太棒了！它节省了我许多的时间……我是说，在它坏掉之前！你能帮我把这锅带到那个地精商人那里去，让他给我修理一下吗？他的名字叫克拉兹克。","小武哥儿"},
[211] = {"啊，安多哈尔！","把阿拉基的护符匣碎片交给西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特。","啊，进攻安多哈尔并彻底击败那个巫妖的时刻终于来临了！召唤者阿拉基就盘踞在安多哈尔的废墟中，他的贴身卫队无时无刻不在他的身边保护着他。你需要召集强大的盟友才能击败他。消灭巫妖，，从它的护符匣里拿出一块碎片来，作为你获胜的证据！","小武哥儿"},
[212] = {"冷餐会","杀死一只冷眼蜥蜴，取一块冷蜥蜴肉并把它带给“蓝色隐士”旅店里的安古斯·斯特恩。<如果你在任务过程中死亡则任务失败>","我的拿手菜之一就是橙味冻蜥肉，但现在的问题是……这种肉很容易变质，而且我今天晚上必须得在一位贵族的生日晚宴上做这道菜！救场如救火，如果你能马上从刚被宰掉的冷眼蜥蜴身上割块冷蜥蜴肉给我的话，我就给你做顿堪比国宴的美味尝尝！冷眼蜥蜴一般会在荆棘谷西北海岸的沙滩上晒太阳，离这里有点远，不是么？所以你得赶紧行动啦！","小武哥儿"},
[213] = {"恶性竞争","给藏宝海湾的科博克带回8块打磨过的水晶。","太猖狂了！吉尔里兹把贸易亲王们指定的要员们都从这里赶了出去，这件事已经够糟的了，现在他居然还和那些声名狼籍的海盗们往来！里维加兹不会坐视不理的，他允许我按自己的方式来解决这些问题。我的方式是什么？偷！最近，风险投资公司的地质学家们正在研究他们从矿里挖出的一种奇怪的蓝色水晶，从那群地质学家手里搞些样本回来给我，当然，我不关心你用怎样的手段去搞。","小武哥儿"},
[214] = {"红色丝质面罩","给哨兵岭哨塔的哨兵瑞尔带回10条红色丝质面罩。","迪菲亚兄弟会的人都会戴着一种红色的面罩，这显然已经是个尽人皆知的秘密了。但我们又了解到，这个面罩的材料是他们的成员在帮会内部地位的象征。既然如此，那么我希望你出马杀死一些兄弟会的高阶成员。他们的最高阶成员无疑都躲在范克里夫的秘密藏身处附近。作为证据，你要给我带回10条红色丝质面罩来，这样我才能给你奖励。祝你好运，。","小武哥儿"},
[215] = {"丛林中的秘密","与反抗军营地里的多伦上尉谈一谈。","谢谢你救了我的命，。我知道这听起来有点奇怪，但……请听我解释。多伦上尉让我和库尔森的手下一起重新回到军队里，让我扮演卧底的角色，为我们反抗军搞一些有用的情报。我原本以为这里很适合我渗透入库尔森的营地，但我错了。再次感谢你救了我一命。这是个机密任务，所以你千万不能把它告诉任何人。但如果你去和多伦上尉谈谈的话，他会给你一个解释的。","小武哥儿"},
[216] = {"蓟皮熊怪的麻烦","杀死8个蓟皮复仇者和8个蓟皮萨满祭司。他们大部分都位于佐拉姆海岸东部的蓟皮村里。任务完成后回到灰谷佐拉姆加前哨站的卡拉恩·阿玛卡那里复命。","蓟皮熊怪在威胁我们的扩张！我们东面的蓟皮村挡住了从这里通往碎木哨岗的道路，这是一条可以包围阿斯特兰纳的道路，没有它，我们就会让联盟得到一条额外的扩张路线。我们决不允许有这样的缺口存在！进入蓟皮村，尽量减少那些熊怪的数量。你会为这项任务得到补偿的，但更重要的是，你会为部落尽到你的职责！","小武哥儿"},
[217] = {"保卫国王的领土","杀掉穴居人首领格劳姆格及他的两个护卫，纳什尔和布劳勒尔。然后回到南部警戒塔向拉格弗斯上尉报告。","，我的侦察兵已经找到了最近一段时间来频频组织穴居人对我们发动袭击的首领。这帮洛克莫丹的怪物好像是由一个叫格劳姆格的酋长领导的，不过格劳姆格身边守卫森严，有两个精英护卫纳什尔和布劳勒尔从不离他左右。如果你想证明自己的价值的话，，我希望你能接下杀掉格劳姆格和他那两个手下的任务。一旦穴居人失去了领导，我们就有机会把这些怪物重新赶回地下。","小武哥儿"},
[218] = {"被窃取的日记","格瑞林·白须要你去杀掉冷酷的格瑞克尼尔，并取回他的日记。","我的日记！那帮巨魔把它拿到洞穴里去了。拿着日记的那个家伙……他是一个皮肤和面颊上都涂着奇特印记的青面獠牙的家伙，我打从娘胎里出来后还没见过像他那样丑的。你应该能对付那些巨魔，帮我把我的日记拿回来怎么样？","小武哥儿"},
[219] = {"失踪人员","保护基沙恩下士回到赤脊。","终于…有人来了……来自联盟的朋友！救救我…求你了…我只记得…一群邪恶的兽人让我们团全军覆没……大多数人都被杀了，我的头被狠狠地打了一下，眼前一黑就倒下去了。现在我被关在这个洞里，奄奄一息……我必须得回到镇上去…拜托了…你是我最后的希望了……","小武哥儿"},
[220] = {"水之召唤","把最纯净的水交给贫瘠之地的伊斯伦。","在给你图腾之前，伊斯伦还会有一个任务让你去完成。我给你的那瓶水在任何情况下都会很有用。去吧，去找伊斯伦。我们会再见的。","小武哥儿"},
[221] = {"森林里的狼人","为夜色镇的卡洛尔杀掉12个夜行黑暗狼人。","你可能已经注意到了，在树林周围有些个头较大的狼人和那些夜行织影狼人一起游荡。据我们所知，大多数狼人都是这类夜行黑暗狼人。我还发现在小镇西南的烂果园里已经到处都是他们的身影了，这些狼人比你之前遇到的那些更难对付。小心点。","小武哥儿"},
[222] = {"森林里的狼人","为夜色镇的卡洛尔杀掉8个夜行邪齿狼人和8个夜行堕落狼人。","你之前的功绩使我确信，你已经可以去对付森林里最凶猛的狼人了。在这一带所有的狼人中，夜行邪齿狼人和夜行堕落狼人是最危险的。他们就住在南边的洞穴和矿井里。你甚至能从很远的地方看见他们的篝火。","小武哥儿"},
[223] = {"森林里的狼人","把卡洛尔的便笺交给乔纳森·卡尔文。","拿着这个，$n。把这个带给卡尔文主人。<他取出一张褪色的羊皮纸交给你>如果再多些像你这样的力量加入，我们就能让守夜人相形见绌！也许到那个时候，我们就能够彻底解决这些现在令我们疲惫不堪的危机。","小武哥儿"},
[224] = {"保卫国王的领土","南部警戒塔的巡山人库伯弗林特要你杀掉10个碎石穴居人和10个碎石怪斥候。","我们要保卫洛克莫丹，！国王的士兵都在遥远的战场上英勇作战，但我们的家园却危机丛生。每个裂缝里都有穴居人在不断冒出来！四处横行的穴居人已经成了铁炉堡最大的威胁，我们一定要消灭这些恶心的怪物！我们需要像你这样勇敢的冒险家来帮忙消除穴居人的威胁。杀掉10个碎石穴居人和10个碎石怪斥候，然后回来向我汇报。","小武哥儿"},
[225] = {"饱经风霜的墓碑","去和夜色镇的希拉·沃宁迪谈一谈。","这座饱经风霜的墓碑上仅仅写着几个字：摩根·拉迪莫尔<经过仔细的观察，你发现墓穴的泥土最近被人动过，很多泥土好像都翻开了……>","小武哥儿"},
[226] = {"恶狼成群","杀掉12只饥饿的恐狼和8只疯狂的恐狼，然后到斯温的营地中向拉尔斯交差。","我和斯温的处境越发危险了，这儿就我们俩，要吃饭就得打猎捕鱼。但是每次我们带着肉和鱼回营地的时候，那些从森林跑出来的恐狼都好像要扑上来咬一口似的。别提有多危险了！如果你能替我们除掉这些狼，也许我们就能过得轻松些。它们经常在北边和东边的小河周围出没。","小武哥儿"},
[227] = {"摩根·拉迪莫尔","去和夜色镇的指挥官阿尔泰娅·埃伯洛克谈一谈。","<他从架子上翻出一本皮质封面的书。>如果你想知道更多，就去问阿尔泰娅，她最近正在为摩根·拉迪莫尔的事情头疼……","小武哥儿"},
[228] = {"摩拉迪姆","杀掉摩拉迪姆，把他的头骨交给夜色镇的指挥官阿尔泰娅·埃伯洛克。","我的探子说摩拉迪姆沿着一条穿过墓地的弯曲怪异的小路，在暮色森林中四处游荡。我们曾把他的尸体埋在山上那座小屋的后面，你知道在哪儿吧？除了祝你好运之外，我没什么能帮你的了。","小武哥儿"},
[229] = {"幸存的女儿","去和夜色镇的守夜人莎拉·拉迪莫尔谈一谈。","我应该早点告诉你的……该怎么说呢……摩根可能以为他的家人都死了，不过实际上他的女儿莎拉·拉迪莫尔还活着，她现在也是个守夜人。她一直在因为她父亲死了以后所发生的……那些事情而苦恼。我想，你可以把关于她父亲的最新消息带给她。","小武哥儿"},
[230] = {"斯温的营地","把你从斯温的农场找到的书交给他。","挖开土堆之后，你发现了一本不大的书，上面沾满了泥土。书上没有写标题，不过……书里写着一些斯温想要知道的东西。","小武哥儿"},
[231] = {"女儿的爱","把莎拉·拉迪莫尔的戒指拿到摩根·拉迪莫尔的坟墓上去。","拿着这个，请把这个放到他的坟墓上。也许…也许这样他就可以知道我现在过得很好，而且我们也不会因为他所做的事责怪他。<她含着眼泪，把戴在右手上的一只戒指摘下放在你手里>还有……谢谢你，$n。","小武哥儿"},
[232] = {"金格的货物","把订货单交给幽暗城的奥雷萨多·卢卡。","皇家药剂师学会需要你的帮助。仔细听好了，这个行动对你我都有好处。隔壁的药剂师基佛看上去有些……疯疯癫癫的，但如果他的研究项目能早点找到一个有眼光的买家的话，早就已经得到丰厚的成果了。幸运的是，现在我已经把这个研究项目买了过来。我要你把这份订货单交给蓝月杂货店的店主奥雷萨多·卢卡那里，他会给你一只实验工具包。当你拿到工具包之后就尽快回来向我报告，我会告诉你下一步任务的详细情况。","小武哥儿"},
[233] = {"寒脊山谷的送信任务","把这一摞信件送给塔林·锐眼。","嗯，$g小子:姑娘;，我想也许你不会帮我这个忙的。今天从隧道那边来了一大堆信，我想我没时间把它们都给发出去了。这些信都是寄给塔林·锐眼的。沿着这条路向西走就能找到他，就在结冰的湖泊附近。你能帮我这个忙么？","小武哥儿"},
[234] = {"寒脊山谷的送信任务","把这封信送给格瑞林·白须。","如果我没记错的话，格瑞林的营地就在这条路的尽头，沿着路往东南方走就是了，他一定正在等着这封信呢。","小武哥儿"},
[235] = {"灰谷狩猎","与灰谷碎木哨岗的塞娜尼·雷心谈一谈。","年轻的冒险者们，注意了！灰谷的野兽正在等着你们！部落在贫瘠之地以北的区域建立了强大的基地。我们的两个前哨站——碎木哨岗和佐拉姆海岸哨岗——正在努力地为部落的荣耀而战！想要证明自己能力的勇士就到那儿去吧。碎木岗哨位于贫瘠之地的正北方，塞娜尼·雷心正在那里招募愿意参与灰谷狩猎中的冒险者！","小武哥儿"},
[236] = {"战车的燃料","冬握堡垒的攻城大师斯托哈德要你前往火焰熔炉，从部落玩家身上取回10个永恒余烬。","！你也差不多该出现了。战斗也许已经结束了，但我们还得准备下一场战斗。前往冬拥湖东南的火焰熔炉，然后取回几个永恒余烬。我们把这些余烬和煤炭混合，用来驱动攻城车和攻城机具。喔，如果你碰巧在那里碰上了部落的家伙，不要犹豫，杀了他们并夺取他们的余烬。我们可不能让他们在下一场战斗占上优势。","小武哥儿"},
[237] = {"保卫国王的领土","南部警戒塔的巡山人格拉维戈要你杀掉10个碎石怪击颅者和10个碎石怪先知，然后回去向他汇报。","巡山人库伯弗林特总是在我面前称赞你，<职业>。因此现在我要交给你一个极其重要的任务，你必须不断给那些入侵的穴居人施加压力，直到我们的兄弟们从联盟前线回来。到南部的丘陵去，杀掉10个碎石怪击颅者和10个碎石怪先知。你的行动可以为我们赢得一点时间，完成任务后就回来向我报告。","小武哥儿"},
[238] = {"金格的货物","把采样工具包交给幽暗城的药剂师金格。","东西都准备好了，$n。毫无疑问，药剂师金格正在等着这批货。马上把这些东西送到她那里去，告诉她我已经把价钱记在学会的帐上了。另外，请代我向她致以最高的敬意。好了，不要再站在这里了，快点出发吧！","小武哥儿"},
[239] = {"西泉要塞","到西泉要塞去和瑞尼尔副队长谈一谈。","我们位于西部边界的要塞报告说，那里的豺狼人和迪菲亚盗贼最近越来越猖獗了。他们要求我从暴风城派更多士兵过去……但是我们已经没有多余的人可派了！如果你愿意帮忙的话，就去和西泉要塞的瑞尼尔副队长谈一谈，看看他需要你做些什么。沿着这条路往西走，过了桥之后向右转就是要塞。","小武哥儿"},
[240] = {"基特斯的美餐","把黑蟹蛋糕拿回去交给基特斯。","完成了——格鲁奥烹制的黑“蟹”蛋糕！","小武哥儿"},
[241] = {"<TEST> HEY MISTER WILSON！","Log","Description","小武哥儿"},
[242] = {"<UNUSED>","Kill 8 Dragonmaw Raiders, 3 Dragonmaw Bonewarders, and a Dragonmaw Battlemaster.","Throm-ka, <职业>. There is no time to waste. Orcs of the Dragonmaw clan have fortified themselves in the valley to the south of here. They have denied the Warchief's mandate, leaving us only one course of action. We will eliminate them so that they will n","小武哥儿"},
[243] = {"进入沙漠","和加基森的首席工程师沙克斯·比格维兹谈一谈，请他为实验工具包提供能量源。","你现在得去一趟塔纳利斯沙漠，在那里对当地的蜥蜴、蝎子和土狼进行一些组织测试，并搜集一些组织样品放进实验工具包里。当然，你有可能得花不少工夫才能找到合适的样品，这一点是可以预料的。每种生物的样本都要十份。另外，加基森的地精拥有这类工具包所需的能量源，去和那里的首席工程师沙克斯·比格维兹谈谈，或许能得到一些必要的帮助。此行只许成功不许失败，否则就不要回来见我。","小武哥儿"},
[244] = {"豺狼人的入侵","找到菲尔顿副队长。","你好，<职业>。我是负责这段道路巡逻任务的卫兵。虽然这条道路现在是安全的，但我曾经在这附近的东北方看见过豺狼人的宿营地。湖畔镇必须得提防着这群豺狼人才行。请你把这条消息报告给湖畔镇的菲尔顿副队长,我想他一定会非常乐意给你的侦察行动付上一笔酬劳的。菲尔顿一般在湖畔镇桥南的地区执行警戒任务。","小武哥儿"},
[245] = {"蜘蛛的威胁","守夜人道茨要你杀15只小型结网毒蜘蛛。","你好啊，<职业>。你有没有看到过在西边出没的那些蜘蛛？这些八条腿的东西实在是太多了，多到我们没法应付，指挥官又没有多余的人力可以从夜色镇派来协助我们。我实在是不好意思向你开口，不过……看样子你好像能对付它们。我不能承诺给你什么贵重的宝贝，不过如果你帮助我们除掉这些肮脏的臭虫，我肯定会奖赏你的。哦，对了，给你个忠告：尽量别碰到它们的毒液。","小武哥儿"},
[246] = {"审时度势","杀死10个混血赤脊山豺狼人和6个赤脊山偷猎者，然后向湖畔镇的菲尔顿副队长复命。","我们实在是没有多余的人手了，但我们也不能对你报告中提到的那些豺狼人不闻不问。侦察南赤脊山附近豺狼人的动向,并尽可能地杀掉足够多的豺狼人,然后向我回报他们的数量，好让我们对他们的威胁大小有个正确的认识。暴风城军方需要你的帮助，，你会得到奖赏的。","小武哥儿"},
[247] = {"完成狩猎","","","小武哥儿"},
[248] = {"监视","爬上石堡要塞一旁的哨塔。为阿祖拉的铭文饰品找一个合适的容器。","我监视伊尔加拉之塔已经很久了，并且我发现，莫甘斯与占据了石堡要塞的兽人之间起了矛盾。我不知道他们之前产生纷争的原因是什么，但你可以帮我揭开谜底。带上阿祖拉的铭文饰品，然后到那个能监视石堡要塞的岗哨顶部去。找一个合适的地方，把铭文饰品放进去，一个盒子或者罐子之类的东西都可以，只要铭文饰品不会被注意到就行，那样我的目的就达到了。","小武哥儿"},
[249] = {"莫甘斯","击败莫甘斯。将他的阴影坠饰带给塞欧克瑞图斯，他就在艾尔文森林内的阿祖拉之塔中。","在长期的侦察监视之后，我终于发现了莫甘斯的计划。他正在寻找月神镰刀……而且，他甚至可能已经找到了。如果他有了那东西，整个赤脊山脉地区，甚至是整个暴风王国都会被他的黑暗力量所征服。我还没有想到对付莫甘斯的办法，但我怕如果现在不行动的话，也许以后就没有机会了。所以我希望你能杀进伊尔加拉之塔与莫甘斯交战。战胜他，然后把他的暗影坠饰带回来给我。如果你成功了的话，整个王国都将以你为傲。","小武哥儿"},
[250] = {"水坝危机","查看水坝东边斜坡附近的区域，调查一下黑铁矮人准备做什么，然后把线索带给主工程师辛德维尔七世．","老天保佑，现在终于有人关心水坝的安全了。先是有人摧毁了萨多尔大桥，然后又有人抢劫丹莫德！我敢说这座大坝肯定会是黑铁组织下一次袭击的目标。这里的驻军——包括我的长官在内——大部分都开到了联盟前线。这就是我需要你的原因，。我看见有几个黑铁工兵在水坝东边的斜坡下转悠。去那里查看一下，带回点线索给我。","小武哥儿"},
[251] = {"翻译亚伯克隆比的信","把写给艾尔罗的信拿给希拉·沃宁迪。","请把你给我的这封信拿给希拉·沃宁迪看看。他对语言和古代艺术很有研究——我看也只有他能翻译这封信了。","小武哥儿"},
[252] = {"翻译好的信件","把翻好的信带给艾尔罗·埃伯洛克公爵。","天哪！如果信上所写的内容都是真的，那亚伯克隆比所做的事情……太可怕了！你最好还是把翻好的信拿回去给艾尔罗看看。快一点，我感觉到这座小镇的末日就要到了……","小武哥儿"},
[253] = {"藏尸者的妻子","找到伊莉莎的坟墓，从她的身上取回藏尸者的心脏，把它交给艾尔罗·埃伯洛克。","藏尸者是个我们经常用来吓唬孩子的故事里的人物。他曾是个善良的炼金师，但因为妻子伊莉莎的死而变得疯狂。为了让妻子复活，藏尸者用黑暗的魔法将自己的心脏放入了亡妻的胸膛里。伊莉莎复活了……不过她也受到了诅咒，开始疯狂地吞食人类的血肉，藏尸者不得不将他的妻子埋了起来。他的心脏就是他全部的力量，找到他妻子的坟墓，把他那颗仍在跳动着的心脏拿回来，就可以打破他的力量。","小武哥儿"},
[254] = {"掘墓","","","小武哥儿"},
[255] = {"雇佣兵","塞尔萨玛的镇长埃罗恩·钝鼻雇你去杀掉4个莫格罗什食人魔、4个莫格罗什蛮兵和4个莫格罗什执行者。","我等了两个月才得到了从铁炉堡传来的消息，说是会有少量士兵来帮助我们防守塞尔萨玛，不过他们还得再等两个月才能到这儿来！我们的镇子没人守卫已经够糟了，但是我们的挖掘场和水坝——这些地方都随时面临着被袭击的危险！看来我已经没有选择了，必须临时征召一点士兵才行。你怎么样？你看上去挺合适的，<职业>。有一群食人魔在洛克湖的东北方安营扎寨，你能不能帮忙再召集点人，去把那些家伙赶走？","小武哥儿"},
[256] = {"通缉令：卓克苏尔","杀了卓克苏尔，把他的头颅带给塞尔萨玛的镇长埃罗恩·钝鼻。","以塞尔萨玛镇长之令：卓克苏尔，袭击塞尔萨玛镇、巨石水坝及挖掘场的食人魔的领导者和组织者。现要求不惜采用一切手段杀死卓克苏尔。若有人呈上杀死卓克苏尔的证明，镇长将给予巨额奖金。卓克苏尔最后一次出现是在洛克莫丹东北部的食人魔营地里。","小武哥儿"},
[257] = {"自豪的猎人","杀死6只山鹫，然后回到旅行者营地见年轻的达瑞尔，时限为15分钟。","你觉得自己可以和勇敢的达瑞尔相提并论？我可不这么认为，当然咯，如果你不服气的话，完全可以试试看。我会让你去做一件非常困难的事情，困难到以你的能力恐怕根本没法摆平，所以就算你完成不了也用不着气馁。有一群秃鹰在这一带筑巢，你去试试能不能把它们解决掉？告诉你吧，如果你能在十五分钟里完成这个任务，我就把我的弓剑或是火枪送给你。<他轻蔑地上下打量着你>看上去你也没什么可以输掉的东西。","小武哥儿"},
[258] = {"猎人的挑战","杀掉5只老山猪，然后回到旅行者营地去见年轻的达瑞尔，时限为12分钟。","你叫$n，对吧？看得出来，完成第一个考验之后，你已经被骄傲冲昏了头脑，不是吗？我跟你说过的，那没什么了不起。你应该再试试去捕杀野猪。相信我，这和捕杀寒脊山谷里那些野猪可不一样，所以你最好当心点。这次我只给你十二分钟。失败了也别难过。不过如果你成功了，我就把我的衬衣脱下来给你！我有没有跟你说过我这个著名的伤疤是怎么来的？没有？好吧，两年前的一天……","小武哥儿"},
[259] = {"<UNUSED>","Talk to Kelt Thomasin.","Hello there, $n. I've heard much about your exploits, and must say I'm honored to meet you. I don't suppose you've heard the story of Ol' Kelt？ Ah, well, Ol' Kelt--Kelt Thomasin, that is--was once considered one of the finest hunters in all the realm. The","小武哥儿"},
[260] = {"<UNUSED>","Collect 5 Threshadon Teeth and 5 Threshadon Claws, then bring them to Kelt Thomasin.","Now, this will no doubt convince you that I am, as they say--and don't deny it, I know what they say--of an addled mind, obsessed with an impossible legend. An old dwarven legend, it is, of an enormous monster that lives in the depths of the Loch. I spent","小武哥儿"},
[261] = {"血色之路","杀掉30个亡灵劫掠者，然后向尼耶尔前哨站的安东修士复命。","坦率地说，我们现在正在与天灾军团交战。他们是一群致力于腐化我们的人民、污染我们的土地的恶魔。我们一定要在他们将我们最后的堡垒彻底血洗、将我们的世界彻底拖入黑暗之前阻止他们。我们血色十字军发誓要奉献出全部身心，与天灾军团斗争到底。如果你也如此宣誓了的话，鼓起你的勇气并证明你的忠诚——去与凄凉之地的亡灵劫掠者们作战吧，它们都聚集在那个地区南部的白骨之谷里。只有这样，十字军才会接纳你。","小武哥儿"},
[262] = {"模糊的人影","带着你从斯温的农场找到的书，把它拿给夜色镇上的人看看。","我一定要搞清楚那个躲在暗处目睹我全家被杀的人到底是谁！求求你了，，你已经表现出了你的足智多谋，请你帮我找出那个模糊的人影到底是谁，我一定要知道他到底是谁！我没法再给你提供更多线索了，不过……拿着这本你在农场里找到的书，也许镇上有人能够帮助我们找到它的主人。","小武哥儿"},
[263] = {"保卫国王的领土","南部警戒塔的巡山人沃尔班要你杀掉10个碎石怪萨满祭司和10个碎石怪断骨者。","巡山人告诉我你很勇敢也很能干，。我们这儿就需要像你这样的<种族>。穴居人的问题一点也没有好转，预备军都被派到前线去了，我们在这儿孤立无援。不过现在我们有你这样一个经验丰富的<职业>，事情就好办一些了。去杀掉10个碎石怪萨满祭司和10个碎石怪断骨者，让我们瞧瞧你是不是名副其实的穴居人杀手。","小武哥儿"},
[264] = {"至死方休","把克拉莉斯的坠饰放在银松森林尤瑞夫的坟墓上。","太过分了！他因为那该死的十字军离开了我，说什么“圣光是我们用来与亡灵抗争的最重要的东西。”那么，他的孩子呢？我呢？我日复一日地等他……一直在默默地支持着他那该死的职责！看看“公正”带给你的一切，！他已经死了，而我却成了他曾经想要消灭的东西！把这个垃圾放到他那修在瑟伯切尔的坟墓上吧。我不想再跟他有任何联系了！","小武哥儿"},
[265] = {"继续搜寻","看看其他的镇民有没有关于模糊的人影的线索。","拿回你的书吧，，祝你好运。你可以去问问镇上的其他人，他们也许还能给你提供更多的线索。对了，我还有个线索可以提供给你——这本书的作者不是夜色镇的人，不过书却是在镇里买来的。","小武哥儿"},
[266] = {"调查旅店","到旅店去查一查关于模糊人影的线索。","这是你的书，祝你好运。你不妨去旅店里查查看，如果你要找的那个人在镇上待过的话，那么很可能有人在旅店里见过他。","小武哥儿"},
[267] = {"穴居人的威胁","给南部警戒塔的拉格弗斯上尉带去8颗穴居人的石牙。","，你可能不知道矮人的领地正在面临着穴居人的威胁。铁炉堡的预备部队已经被派到联盟前线去了，只有很少一部分被留下来负责保卫这里的安全。我的部队负责看守这里的大门，提防随时可能到来的攻击，我们绝不能因为害怕而离开这里。不过我们得给山里的那些穴居人施加点压力。如果你能胜任这个工作，就去干掉这些穴居人，然后带8颗穴居人的石牙回来作为胜利的证明。","小武哥儿"},
[268] = {"回复斯温","把基特斯的日记交给斯温。","你找到的那本书……我还没有写完。我从斯文的农场里逃走的时候，不得不把书留在那儿……拿着这个，把这本完整的日记带给斯温。这一本对在他的农场上所发生的事情描述得更完整。这几个星期以来，我一直把这本日记放在身边，不过如果把它交出来之后我就不用面对斯温和他的愤怒的话，我宁愿把这东西交给他。","小武哥儿"},
[269] = {"寻求指引","把基特斯的日记交给暴风城的主教法席恩。","到暴风城去找光明大教堂的主教法席恩，把基特斯的日记给他看一看，告诉他你决心要和摩本特·费尔进行面对面的较量。虽然暴风城抛弃了夜色镇，但是法席恩主教是个善良而又睿智的人，也许他能给你一些帮助。你的使命非常危险，不过请动作快点，。笼罩夜色镇的黑暗力量无时无刻不在变得更加强大。","小武哥儿"},
[270] = {"被诅咒的舰队","到湿地的米奈希尔港去，找戈罗林·钢眉谈一谈。","几年前，库尔提拉斯的第三舰队在湿地的海岸线附近全军覆没，对，就是丹莫罗北方的那块湿地。其中一条船上满载着光铸铁。这种金属对我们来说相当珍贵，它们可以用来制造出附有神圣力量的武器。如果你要去与摩本特·费尔作战的话，应该会需要这样一把武器。去米奈希尔港找我的矮人同事戈罗林·钢眉谈谈吧，如果你可以找到那些丢失了的金属，他应该会知道该到哪里去找。","小武哥儿"},
[271] = {"维林的报复","杀掉奥尔苏迪，把它的头颅带给旅行者营地里的达瑞尔。","你没被达瑞尔气得昏头昏脑吧？虽然我不愿意承认，但达瑞尔还是有点能耐的。一年前，整个旅行者营地里的猎人都在捕猎一只巨熊，不过没有一个人能解决掉它。后来，达瑞尔也去试了试，结果他的脸上就留下一道了丑陋的伤疤。如果你能杀了那只熊，就算是达瑞尔也会哑口无言的。那只名叫奥尔苏迪的熊就住在塞尔萨玛附近的山上。","小武哥儿"},
[272] = {"海狮试炼","寻找水兽耐力坠饰和水兽敏捷坠饰。与月光林地的居民谈一谈，找出这些东西可能被放在哪里。在雷姆洛斯神殿附近将海狮坠饰的两部分合而为一。将合并好的坠饰交给月光林地永夜港中的德迪利特·星焰。","第二个试炼是要寻找组成海狮坠饰的两个部分。其中的一半蕴含着海狮的敏捷天性，另一半蕴含着海狮那令人难以置信的耐力。德鲁伊汲取这两种特性，将它们运用到自己的水栖形态中。与月光林地中的居民谈一谈，找到这两个部分，并将它们合并起来。最后把合并好的坠饰交给德迪利特·星焰。","小武哥儿"},
[273] = {"挖掘场的补给品","和胡达尔谈一谈。","现在还不算太晚，你还可以去找胡达尔。他不大可能走得太远，尽管米兰和赛恩都很壮实，但是他们带着几只大桶是没法走太快的。他们走的是补给车队常走的路线，从镇子出发，沿着洛克湖的边缘往南走。只要他们还没走到挖掘场，你就应该可以在路上找到他们。","小武哥儿"},
[274] = {"水坝危机","阿什兰·暗石要你回去见主工程师辛德维尔七世，把有关这种炸药的新发现告诉他。","这不是一般的炸药粉末。看看这些银色的小晶体。还有这股特别的味道！不用说这就是爆盐粉末了！爆盐本身没什么危害，不过一旦它沾上水，那威力，啧啧！足够把整个铁炉堡给炸上天！要想阻止这种东西爆炸就需要四种东西：潜伏者的毒液，莫格罗什水晶，一滴鳄鱼的眼泪和一些拆弹胶质。现在你得赶紧把我的话告诉辛德维尔，否则就来不及了！","小武哥儿"},
[275] = {"大地上的脓疱","杀死8只沼泽爬行者，然后向湿地的绿色守卫者雷希耶尔复命。","我不知道是怎么回事，但是堕落正在湿地上蔓延。沼泽爬行者出现了，他们就像是腐烂而危险的脓疱。要制止这些脓疱，就必须把他们驱散开，把它们赶回沼泽。这些沼泽爬行者一般都在湿地的水道里活动。","小武哥儿"},
[276] = {"践踏之爪","杀死15名藓皮豺狼人和10名混血藓皮豺狼人，然后向湿地的绿色守卫者雷希耶尔复命。","藓皮豺狼人在湿地平静地生活了许多年，但如今他们的数量却膨胀了不少。他们的脚正践踏着沼泽地中的灌木与花朵，他们污浊的斧子也砍伐了太多的树木。他们已经令这里的自然失去了平衡。为了湿地的安宁，必须削减这些豺狼人的数量。去杀死15名藓皮豺狼人和10名混血藓皮豺狼人，他们就在南边的奥加兹大门附近活动。完成任务之后再回来向我复命。","小武哥儿"},
[277] = {"火焰管制","给绿色守卫者雷希耶尔带回9块粗制打火石。","藓皮豺狼人们正在大量地砍伐湿地的树木，用树干和树枝当柴火来烧。我不能再容忍这样的行为了！把藓皮豺狼人生火用的打火石都给我抢过来。除了年幼的藓皮豺狼人和混血藓皮豺狼人以外，其它所有的藓皮豺狼人身上都会带着打火石。","小武哥儿"},
[278] = {"水坝危机","主工程师辛德维尔七世要你收集一份潜伏者的毒液，一块莫格罗什水晶和一滴鳄鱼的眼泪。","你必须立刻去收集拆弹用的原料，。潜伏者的毒液在洛克莫丹的蜘蛛身上可以找到，鳄鱼的眼泪在洛克湖一带的鳄鱼身上也有。不过莫格罗什水晶很难找到。东北边矿井里的食人魔开采这种水晶，不过即使在那里，莫格罗什水晶也不常见。我们必须要作好准备才能粉碎黑铁矮人的计划！你找齐了这些材料之后就立刻回来找我，我会把它们做成拆弹剂。","小武哥儿"},
[279] = {"海中的鱼人","杀掉12个蓝腮鱼人。杀掉高布勒尔并砍下它的头。将高布勒尔的头颅交给米奈希尔港的卡尔·波兰。","可恶的鱼人正在从深海里源源不断地爬出来，它们沿着海岸线建立自己的村庄和定居点。这些家伙给我们的渔民和商人带来了极大的困扰，我们必须要阻止这种行为。它们当中有一个叫高布勒尔的头目最近一直带着一群蓝腮鱼人埋伏在道路旁，抢劫过往的商旅，得手之后又马上撤回它们的村子。现在我们的通商道路非常危险，所以我们想要通过悬赏来解决这个问题。高布勒尔和它的跟班们就躲在北边的河口附近。找到它，把它干掉，然后把它的头给我带回来。","小武哥儿"},
[280] = {"水坝危机","主工程师辛德维尔七世要你游到水坝底部，找到装着炸药的木桶，然后把拆弹剂放进去，阻止将要发生的爆炸。","今天早些时候我发现有一些黑铁矮人背着一只大木桶向水坝游去，糟糕的是那一带没有巡山人可以拦住他们！我怀疑他们已经把爆盐炸药放到了水坝下面，随时都有可能爆炸！我马上就把这些成分混合在一起制成拆弹剂。完成了！现在我要你把这个混合剂拿去，和木桶里的炸药搅拌在一起！快一点！我们没时间了！","小武哥儿"},
[281] = {"夺回雕像","搜索海边鱼人村落中的木箱和木桶。","不久之前，有一艘名叫“盲眼公主”的商船遭到了一群鱼人的袭击。尽管这艘船完完整整地逃了出来，但船甲板上放着的货物都被那些该死的鱼人给拖下水抢走了，其中甚至包括一座十分宝贵的泰瑞纳斯·米奈希尔的雕像。我们希望有人能把这座雕塑给抢回来。到海岸边的鱼人村落里去，仔细找找看有没有木箱、木桶，或者其他丢失货物的踪迹。在那里找到米奈希尔雕像，然后回来向我复命。","小武哥儿"},
[282] = {"森内尔的观察站","和巡山人萨鲁斯谈一谈。","我原打算让我的学徒帮我把报告带给我的兄弟森内尔。但是，你看他那德性……我想如果有一个更可靠的人替我去送的话就更好了。如果你不介意的话，可以去一趟吗？嗯……你要穿越隧道，一路走到卡拉诺斯。在穿越隧道前，别忘了去和巡山人萨鲁斯聊聊，那里的穴居人简直成灾了。顺着这条路回到安威玛尔，然后向东就能到隧道了，萨鲁斯就在附近。","小武哥儿"},
[283] = {"水坝危机","拆弹剂看来已经产生了效果。你可以回去向主工程师辛德维尔七世汇报这个好消息了。","木桶发出了轻微的嘶嘶声。","小武哥儿"},
[284] = {"继续搜寻","搜索米奈希尔雕塑。","你继续在鱼人的村庄中仔细搜索着，但没有找到任何关于米奈希尔雕像的蛛丝马迹。也许北边和东北边的另两处鱼人村落那会有些什么线索。","小武哥儿"},
[285] = {"搜寻雕像","继续在鱼人村落中搜寻米奈希尔雕像的踪迹。","你仔细地搜索了这几处鱼人村落，但却没什么有价值的发现。……但你有一种直觉，就是你在下次搜索中一定能找出一些很有价值的线索。北边的最后几处村落里一定会有米奈希尔雕像！","小武哥儿"},
[286] = {"归还雕像","将米奈希尔雕像还给卡尔·波兰。","你把这个木桶从垃圾里拖了出来，刚一打开它，一尊精心包裹在稻草中的银制小雕像就掉了出来。这是一个头发很长的年轻圣骑士高举战锤的样子。这一定就是米奈希尔雕像了！你必须马上把它交还给米奈希尔港的卡尔·波兰。","小武哥儿"},
[287] = {"霜鬃巨魔要塞","侦查霜鬃巨魔要塞，替卡拉诺斯的森内尔·白须杀掉5个霜鬃猎头者。","我快要来不及提交报告了，你能帮我一下吗，$n？我只想知道这些巨魔躲在什么地方，不过我看见这么多的巨魔就怕得不敢进去了。你要做的是……进到山洞里，在里面到处走走，干掉一些巨魔，然后再回来。顺着向北的路离开卡拉诺斯，当你走到一座桥前的时候，再沿着冰冻的河流向西一直走到涌冰湖。你会发现烈酒村就在湖的西岸，而巨魔要塞就在村庄的西南边。","小武哥儿"},
[288] = {"第三舰队","为大副菲兹莫斯买一份壶装蜜酒。","我曾经是浪花女神号上的大副——浪花女神是库尔提拉斯第三舰队的主力战舰。这是一支多灾多难的舰队，说它多灾多难是因为……它在最后一次出航中遇到了红龙的袭击。这些龙是被兽人控制的！红龙喷出的火焰对我们的战舰来说简直是毁灭性的……我们的舰队在这片海域被烧得一干二净，全军覆没。我是那次灾难的唯一幸存者…………哦，我的头疼得像鼓槌在敲！我需要一些让我头脑清醒的东西，好让我继续讲述我的故事。","小武哥儿"},
[289] = {"被诅咒的船员","杀死13个被诅咒的水手、5个被诅咒的水兵和大副斯涅利格。把斯涅利格的鼻烟盒交给米奈希尔的大副菲兹莫斯。","<缓过气来的菲兹莫斯继续讲述他的故事……>我是这支倒霉的库尔提拉斯第三舰队中唯一的幸存者，整支舰队都在北方的海岸附近覆灭了。不过，虽然我是舰队中唯一活着的人，却不是唯一一个依然在这里出现的人！因为，在一条已经沉没的船里，藏有巨大的、可怕的宝藏，它所拥有的可怕魔力将我的弟兄们的灵魂束缚在被海水侵蚀的船体里。如果你能超度我的那些被诅咒的弟兄们，也许你就能破除那个诅咒。","小武哥儿"},
[290] = {"解除诅咒","从哈林多尔船长那里拿到无畏号的保险箱钥匙。用钥匙打开无畏号上的保险箱。","为了破除诅咒，解救我所有的兄弟，就必须要把装在我船上的那个鬼东西拿回来进行净化！我不知道它是什么，但我知道它被存放在船上的保险箱里，而保险箱的钥匙一向是由哈林多尔船长保管的。我的老船长仍时常出现我的梦里，在我的那艘已毁灭了的无畏号的甲板上走来走去……去找到钥匙，用它打开无畏号上的保险箱。然后，在你获得那件被诅咒的东西以后，把它交给镇上的牧师，戈罗林·钢眉。","小武哥儿"},
[291] = {"森内尔的报告","把森内尔的报告交给铁炉堡的参议员巴林·红石。","好极了！把我的报告交给参议员巴林·红石。他是个酸溜溜的家伙，你可别在意。他在铁炉堡，麦格尼陛下的宫殿里。你不知道去铁炉堡的路？顺着这条路向北走出卡拉诺斯，穿过一座桥，然后沿着路向东走——在路边山上应该有个很大的路标。顺便说一句，你最好不要提及你是如何帮助我的，不要让他们以为我在这里没有好好工作，好吗？","小武哥儿"},
[292] = {"帕雷斯之眼","把被诅咒的帕雷斯之眼交给戈罗林·钢眉。","打开箱子之后，你看到了一颗发黑的宝珠，它还在闪烁着可怕的光芒。这就是菲兹莫斯所说的宝藏：一颗被诅咒的帕雷斯之眼。把被诅咒的帕雷斯之眼交给住在米奈希尔港的矮人牧师戈罗林·钢眉，请他驱除附着在它上面的诅咒。","小武哥儿"},
[293] = {"净化帕雷斯之眼","把被诅咒的帕雷斯之眼交给大主教本尼迪塔斯，他就在暴风城的光明大教堂里。","我无法驱散帕雷斯之眼上的诅咒。它是由人类牧师手工制造的，所以你最好去暴风城寻找帮助。去和大主教本尼迪塔斯谈谈吧，他是暴风城光明大教堂的领导者，他能帮你解决问题。我希望如此。","小武哥儿"},
[294] = {"奥莫尔的复仇","维尔加挖掘场的奥莫尔·铁衣要求你杀死10只杂斑迅猛龙和10只杂斑尖啸龙。","目前我们所面临的形势十分严峻，这已经是众所周知的事了。我们刚挖出这些骨头，它们就招来了一大群迅猛龙。这些凶残的野兽杀光了我的弟兄们，并把我、麦琳和可怜的勘察员困在了这上面。帮我把湿地里的这些迅猛龙都给杀光，。杂斑迅猛龙和杂斑尖啸龙就在山崖的西边，要是你有能力对付它们的话，每种都给我杀上十只。这只不过是我对它们的复仇计划的开始而已！","小武哥儿"},
[295] = {"奥莫尔的复仇","奥莫尔·铁衣要求你杀死10只杂斑刺喉龙和10只杂斑锯齿龙，然后回到维尔加挖掘场向他复命。","现在是时候让这些该死的迅猛龙为它们的嗜血而后悔了。在悬崖下面还有一些杂斑刺喉龙和杂斑锯齿龙，每种都给我杀10只，它们要为自己的所作所为付出代价！","小武哥儿"},
[296] = {"奥莫尔的复仇","维尔加挖掘场的奥莫尔·铁衣要求你杀死萨尔图斯，并在任务完成之后带着它的一只爪子向他复命。","在你下到悬崖底部的时候，我碰巧发现了有一只很特别的迅猛龙在那边站着休息。它比一般的迅猛龙的体形要大得多，看上去也特别凶猛。我敢打赌它就是那群迅猛龙的首领，就是它带着手下来这里毁了整个挖掘场。我现在交给你最后一个任务，。以正义的名义，审判萨尔图斯！当然，考虑到它所犯下的重罪，它唯一能得到的判决就是死刑！把它的一只爪子给我带回来作为它已死的证据。","小武哥儿"},
[297] = {"收集石像","收集8个小石像，把它们交给麦格玛尔·落斧。","不久前，就在那些穴居人像雨后的蜗牛一样冒出来之前，我们发现了一大批奇特的小石像。但是还等我们开始着手研究它们，穴居人就把我们从废墟里赶了出来！这些石像有种奇特的效力，它可以让那些穴居人变得更加疯狂！给我拿几个石像回来——我想研究研究，所以你得把它们从穴居人手上给我抢过来！你可以在挖掘场里到处都是的穴居人身上拿到这些石像。","小武哥儿"},
[298] = {"挖掘进度报告","把铁环挖掘场的进度报告带给塞尔萨玛的吉恩·角盔。","我这里有一份报告要赶快送到塞尔萨玛去——这是一份挖掘进度报告，还有一份再次重申我们需要更多的火药粉的报告！你把它带给吉恩·角盔，他是我们在塞尔萨玛的联系人。这个任务没什么麻烦的，但你一定要完成它。","小武哥儿"},
[299] = {"发现历史","勘察员维尔加要求你在挖掘场中搜索4块石板的碎片，它们是阿度斯碎片、莫德尔碎片、高尔姆碎片和奈尔鲁碎片。","在迅猛龙大举入侵之前，我找到了一块名叫戈奥兹之石的巨大石碑。我翻译好的文字被分成了四部分，散落在挖掘场中的四个不同的地方。这些文字描述的是一个“神圣的计划”和一个“注定的命运”。我们应该马上把它们都收集起来，而不是继续在这里浪费时间。但是我已经很老了，恐怕没办法再杀出去跟那些凶猛的野兽作战了。但是你不同，你年轻而强壮。到挖掘场里去搜索这四片失落的石板：阿度斯石板、莫德尔石板、高尔姆石板和奈尔鲁石板。它们应该被藏在某些古董器物里，另外你也得留意土壤松动的地方。把它们拿回来给我，这样我才能揭开","小武哥儿"},
[301] = {"向铁炉堡报告","把铁环挖掘场的进度报告交给勘察员塔伯斯·雷矛。","我们必须得到上级的批准才能给铁环挖掘场送去更多的火药粉。把他的报告带到铁炉堡的探险者协会总部去，交给勘察员塔伯斯·雷矛。他可是个急性子的家伙，如果听说铁环挖掘场的进展如此缓慢，他一定会暴跳如雷的。你可以在探险者大厅里找到他。","小武哥儿"},
[302] = {"铁环的火药","和塞尔萨玛的吉恩·角盔谈一谈。","如果铁环还需要火药粉的话，以麦格尼的名义，就再给他送一批过去！我已经派了一个信差把我的许可交给塞尔萨玛的吉恩·角盔，让他负责准备火药和其它物资。还有一件事情：我要你保证亲自把这批火药送达目的地。上一批没有送到，中间也许出了什么岔子，所以这次你得仔细提防着点。","小武哥儿"},
[303] = {"黑铁战争","丹莫德的莫特雷·加玛森要求你杀死10名黑铁矮人、5名黑铁隧道工、5名黑铁破坏者和5名黑铁爆破手。","战火席卷了整个世界。当许多精锐的矮人士兵们为了联盟而牺牲在前线时，我们自己的土地却沦为了这群邪恶的黑铁矮人觊觎的目标。他们已经攻陷了萨多尔大桥，丹莫德也岌岌可危。我们要你去聚集起一股力量，并将战线推回去。如果你能杀死十五名黑铁矮人、五名黑铁隧道工、五名黑铁破坏者和五名黑铁爆破手的话，就能为我们组织反击争取到宝贵的时间。兵贵神速，快出发吧！","小武哥儿"},
[304] = {"艰巨的任务","杀死邪恶的巴尔加拉斯，把他的耳朵带给丹莫德外的布莱德·长须。","我手下的大部分士兵都在丹莫德的战役中死去了，我的亲兄弟也在萨多尔峡谷上的西桥被毁的时候不幸牺牲。唉，黑铁矮人真是个像恶魔一般邪恶的族群。根据罗戈收集到的情报，这群在湿地四处肆虐的暴徒的领袖是一个名叫巴尔加拉斯的术士。他是个十分胆小谨慎的家伙，在把手下的士兵送上战场执行命令的时候，他自己往往却躲藏在某个不为人知的地方，躲避着任何可能面临的危险。如果你能找到这个懦夫，杀了他，把他的耳朵拿来给我，我会给你支付可观的酬劳的，<职业>。","小武哥儿"},
[305] = {"寻找挖掘队","塔雷尔·石纹要求你到挖掘场里去找到麦琳·石纹。","啊，天呀，你一定就是长须派来的帮手！你真是不知道我有多担心。我的老婆麦琳上个月的时候每礼拜都会给我写一封信的。她是维尔加挖掘队的成员，她最后一次写信过来是两周前的事了。一定是出了什么事！长须说，要是我们一直都没有收到挖掘队那边送来的信，那么他就会派出一名探子去看看情况。我猜那个探子应该就是你吧，。快去东边的挖掘场里找到麦琳！","小武哥儿"},
[306] = {"寻找挖掘队","把麦琳的信件交给塔雷尔·石纹复命。","这太恐怖啦！我们刚刚发现了一些十分稀有的古物，而且正在把这些巨大的骸骨挖掘出来，这个时候，可怕的事就发生了，在我们反应过来之前，多到数不清的杂斑迅猛龙冲进了挖掘场，咬死了许多人！勇敢非凡的奥莫尔救下了我和勘察员，并一直把我们护送到了一处藏身之所。现在我们被彻底困在这里了，逃也逃不出去，我们努力工作的成果也全毁了。给，把这封信带回去交给我亲爱的塔雷尔，我已经在信里把事情跟他解释清楚了。","小武哥儿"},
[307] = {"肮脏的爪子","到银泉矿洞去收集4套矿工装备，然后向巡山人卡尔·雷矛复命。","东边的银泉矿洞很久以前就枯竭了。矿工联盟把它改造成了储藏库，不过现在狗头人占据了那里，把他们肮脏的爪子放在了我们矮人制造的工具上！我们很快就能把这些害人虫赶走，但是矿工联盟要求我们在冲进去大开杀戒之前，先把洞里的矿工装备拿出来。这是个艰难的任务——你也许需要几个帮手。他们的装备就在矿工联盟的储物箱里，祝你好运。","小武哥儿"},
[308] = {"加文的爱好","","","小武哥儿"},
[309] = {"护送货物","确保把米兰和货物送到挖掘场，然后通知勘察员基恩萨·铁环。","准备出发了吗，$n？首先，我们得把炸药粉送到铁环挖掘场。要我一个人运这么多炸药太困难了，这些东西又很危险——而且谁知道那帮黑铁矮人打算对我做什么？有你跟我一起走，我感觉就好多了。","小武哥儿"},
[310] = {"针锋相对","到卡拉诺斯的雷酒酿造厂酒窖里去，把一桶雷霆啤酒换成热麦酒。","我不得不承认，雷酒家族的那帮家伙酿酒水平还真不赖。但是他们应该知道他们的酒并不是世界上最好的！也许你能帮我让他们了解这一点……给，带上这桶热麦酒，想办法潜入卡拉诺斯的雷酒酿造厂的酒窖，把他们的雷霆啤酒和我们的换一下。然后，我们就等着看好戏吧，顾客们肯定会更喜欢我的酒！如果有人看着酒桶的话，你就得想办法转移他的视线……","小武哥儿"},
[311] = {"向马莱斯回报","把雷霆麦酒交给烈酒村的马莱斯·麦酒。","把一桶马莱斯的热酒放进了卡拉诺斯酿酒间的地窖里之后，你取回一桶雷霆麦酒作为行动成功的证明。","小武哥儿"},
[312] = {"马克格拉恩的干肉","从冰须的洞穴里拿回装有马克格拉恩的干肉的储藏柜。","我原本储备了一个月的干腌肉准备过冬，为了防止野熊把肉衔走，我把它们锁在了储藏柜里。但是在我外出打猎的时候，一个叫做冰须的野兽偷走了我的储藏柜！可笑的是那个蠢货撬不开这只用瑟银铸成的柜子。但是如果拿不回这些肉，我就会饿死的。你的身手看来不错，也许你能帮我取回储藏柜？你瞧我拖着这条废腿也没办法把那只柜子抢回来……","小武哥儿"},
[313] = {"灰色洞穴","收集8束雪怪的鬃毛，把它们交给驾驶员迪恩·石轮。","不是每个人都能驾驶攻城坦克的，你必须要有强壮的身体和钢铁般的神经……幸运的是，这两个条件我都有！你呢？你有足够的勇气吗？想不想证明给我看？啊……我想把我的“巨魔碾压者”号坦克改造得更舒适些，你去帮我在卡拉诺斯西边的灰色洞穴里弄一堆雪怪的鬃毛来吧，我要用那些鬃毛做一张大毯子来装饰我那“巨魔碾压者”的驾驶舱。","小武哥儿"},
[314] = {"保护牲畜","山羊农场的鲁德拉·冻石要你杀了瓦加什，并且把它的牙齿给她带回去。","午夜的时候，我们听到了吵闹的声音。今天早上我才发现羊圈里少了两只羊，那头名叫瓦加什的野兽袭击了我们的牲畜。由于国王麦格尼的军队大都在遥远的战场上与联盟其他的种族并肩作战，所以没有人能对付得了瓦加什。也许你有勇气找到这只猛兽并杀了它。把它的一颗牙齿交给我作为证明，我会奖赏你的。瓦加什就躲在这里的农场附近，小心点，它非常凶残。","小武哥儿"},
[315] = {"完美烈酒","收集6束微光草，把它们交给烈酒村的雷杰德·麦酒。","我正在寻求可以酿制出完美的酒的方法。我知道我能酿造出来，我缺的只是一份正确的酿酒配方……霜鬃巨魔在东边的山坡上种植了一种叫做微光草的植物，他们通常在奇怪的氏族仪式上用到它。我们矮人还没有发现这种草有什么用途，不过它的口味非常特别……我要把这种植物用在我的酒里！从霜鬃先知那里给我弄一些微光草来，或者你也可以从巨魔用来装微光草的篮子里偷一些。","小武哥儿"},
[316] = {"<UNUSED 1>","","","小武哥儿"},
[317] = {"贝尔丁的补给","收集4大块野猪肉和2张厚熊皮，把它们交给钢架补给站的驾驶员贝隆·风箱。","我正在准备为攻城坦克旅执行一项任务。这次任务会持续很长时间，所以我得预先收集能够维持一个月的物资。贝尔丁正忙着修理我的坦克，你能帮我去弄一些东西来吗？我需要一些毛皮来做床垫，还要一些野猪肉作为食品储备。猪肉当然是从野猪身上割下来的，最好的毛皮是熊皮……在灰色洞穴南部的雪地上到处都是这两种动物的踪迹。","小武哥儿"},
[318] = {"艾沃沙酒","从烈酒村的雷杰德·麦酒那里弄到一桶艾沃沙酒。","雷杰德·麦酒一直以来都亲口试验他自己酿制的酒。有的好喝，有的难喝，还有的连酒量最好的矮人都能轻松放倒。他住在烈酒村，那地方就在卡拉诺斯的西边。我需要一些他酿造的那种叫作艾沃沙的酒，在寒冷的旅程中，喝这种酒能帮我暖暖身子。还有……这种酒实在是太烈了，在紧要关头还可以当燃料使，只要把它注入我那坦克车的油箱里，整辆坦克都会爆发出无穷的力量！这个小诀窍让我不止一次地化险为夷。","小武哥儿"},
[319] = {"艾沃沙酒","杀掉6头冰爪熊、8只老峭壁野猪和8只雪豹，然后回到烈酒村的雷杰德·麦酒那里。","我有一桶酿制好的艾沃沙酒，不过……你能帮我个忙吗？烈酒村急需人手去对付在村子附近溜跶的野兽。有时它们离我们非常近，那真是太危险了。我们并不害怕这些熊啊，豹啊，野猪啊——任何一个有自尊的矮人都不会害怕——不过，如果你能替我把它们搞定的话，我就能腾出更多的时间来酿酒了。","小武哥儿"},
[320] = {"艾沃沙酒","把这桶艾沃沙酒交给钢架补给站的驾驶员贝隆·风箱。","这是你要的艾沃沙酒，。再次感谢你给予我们的帮助。","小武哥儿"},
[321] = {"光铸铁","搜索飞翔鱼鹰号的残骸。","这附近的海滩上的船只残骸大多是属于库尔提拉斯第三舰队的，在上一次大战中，那支舰队曾与红龙们在此激战，不幸全军覆没了。那支舰队里的船大多是洛丹伦的战舰，但有一艘船却不是，那是一艘名叫“飞翔鱼鹰”的精灵驱逐舰。它运着满满一船的光铸铁加入了第三舰队的船队中，本以为这样就足够安全了，结果却讽刺性地落得个被红龙击沉的厄运……故事就讲到这儿吧，飞翔鱼鹰的残骸就在米奈希尔港的南边。如果你能在那里找到光铸铁的话，就把它给我带回来吧。","小武哥儿"},
[322] = {"格瑞曼德·艾尔默","将这箱光铸铁锭交给格瑞曼德·艾尔默。","暴风城矮人区有一个名叫格瑞曼德·艾尔默的矮人武器匠会用这种光铸铁来打造武器。我已经把你找到的这些铁锭用木箱装好了。把这个箱子交给格瑞曼德，再把你的事情告诉他。我敢打赌他一定会义愤填膺地马上着手为你打造武器的，嘿嘿，那肯定是把就连摩本特·费尔看到了也会心惊胆颤的武器！","小武哥儿"},
[323] = {"证明你的实力","杀掉15个骷髅袭击者、3个骷髅医师和3个骷髅看守，然后回来见斯温。","摩本特·费尔是个亡灵巫师，也是黑暗强盗的帮凶。我希望你能去除掉摩本特·费尔，不过在了解你真正的实力之前，我还不能贸然拿你的生命开玩笑。你已经证明了你的勇气，不过如果你想要面对面地和这个巫师作战，首先得证明你能应付得了他的爪牙。","小武哥儿"},
[324] = {"丢失的铁锭","收集5块光铸铁锭，把它们交给湿地的戈罗林·钢眉。","你好不容易把那块光铸铁锭从泡在水里的箱子中拿了出来，显然，是鱼人偷走了其余的铁锭。猎杀飞翔鱼鹰号残骸周围的鱼人，拿到它们身上带着的光铸铁锭。","小武哥儿"},
[325] = {"整装待发","现在你已经得到了强大的武器，去向暮色森林的斯温复命吧。","你已经准备好了吗，？祝你好运！我期待着你凯旋归来！","小武哥儿"},
[326] = {"<UNUSED>","x","x","小武哥儿"},
[327] = {"<UNUSED>","","","小武哥儿"},
[328] = {"隐藏的钥匙","使用黄铜钥匙打开书呆子赫罗德的保险箱。","尽管在这些档案文件里都没有提到列兵萨尔森，但你发现在赫罗德的一本帐薄后面绑着一只小小的黄铜钥匙。你还在研究他的其它笔记时发现了其中有一小部分提到，在一个“安全的保险箱”中装有大量的文件。这个保险箱应该在库尔森营地后山的某处洞穴之中，他们管那里叫“储藏室”。如果你能找到这个保险箱并用这把黄铜钥匙打开它的话，或许里面的文件有助于找到导致萨尔森身份暴露的内鬼。","小武哥儿"},
[329] = {"找出内鬼！","将沾泥的便笺交给叛军营地里的多伦上尉。","在箱子里的这些贵重物品之中，还有一张满是灰尘且写得十分潦草的便笺。尽管几乎已经没法辨认了，但你能看出来这便笺上面似乎描述了列兵萨尔森所走的路线。这应该是他的巡逻路线，以及反抗军方面与他接头的人员与时间。签名只有一个字母：M。毫无疑问，这应该是萨尔森身边的人写下的便笺，而且这个人就是反抗军营地中的卧底。","小武哥儿"},
[330] = {"巡逻时间表","与塞斯曼下士谈一谈。","你给我的便笺上的签名只有一个字母“M”……我也不知道这代表谁。但是……这便笺同时也告诉我们，这个人应该是上周与萨尔森一同巡逻的同伴。所以，只要知道上周谁和萨尔森一起巡逻过，那他就应该是内鬼没错了！去找塞斯曼下士问一问，他是负责制订巡逻时间表的人，可以告诉你那个时候萨尔森和谁在一起。","小武哥儿"},
[331] = {"向多伦报告","与多伦上尉谈一谈。","多伦上尉不是说要你向他回报关于巡逻时间安排的情况吗？","小武哥儿"},
[332] = {"酒店的广告","到加林纳酒店去, 将酒票交给苏泽塔·加林纳以换一瓶免费的酒。","无论你跟任何人谈起酒，大家都会告诉你加林纳家卖的酒是全暴风城最好的。而且那里离我们这儿并不远，就在贸易区中，运河的边上。给，拿着这张酒票。把这个拿到店里去，交给我的姐姐苏泽塔，她会送你一瓶我们酿造的最有名的黑葡萄酒。你绝对不会后悔的！","小武哥儿"},
[333] = {"哈兰需要供货","找到运河裁缝店，并将哈兰·巴格雷的布料订单带给雷玛·施涅德。","我们过几天肯定会有大单的生意。现在似乎每个人都在购买盔甲和结实的衣服，好像他们都以为明天就会变得天寒地冻一样……但那是以后的事了。我现在最担心的是我已经卖完了全部库存的针织布，需要一次大批量的供货。如果你能把我的这个要求带给运河裁缝店的雷玛·施涅德的话，我会非常感谢你的。","小武哥儿"},
[334] = {"萨尔曼的针线包","到暴风城法师区的拉尔森服装店去，将针线包带给萨尔曼·斯涅德。","我的儿子萨尔曼在法师区的拉尔森服装店里当学徒。他今天早上走得太着急了，忘了他的剪子和针线。我知道你这样伟大的一般都会有些重要的事要做，可要是没了工具的话，萨尔曼可没办法做他的工作呀！拜托了，。你能帮我把他的针线包拿去给他吗？拉尔森服装店是法师区里的两家裁缝店之一，在比较靠里面的地方，也就是靠近法师塔的地方。","小武哥儿"},
[335] = {"名酿","黑爪加尔德斯要求你从夜色镇给他摘1朵蒂罗亚之泪，再从湿地给他采一块麝鼠根。","维沙克公爵最近正在贵族议会中兴风作浪，他似乎知道一些我们的事情，而且还游说其他议员们，要他们通过他提出的对这里进行一次全面调查的提案。我有一个计划，能让维沙克迷上些别的什么东西……但我需要你的帮助。在夜色镇郊区的斯塔文的花园里生长着一种名叫蒂罗亚之泪的白色小花，去给我弄一朵来。另外我还需要一些麝鼠根，那种东西只生长在湿地，就在巨石水坝下的瀑布底部。","小武哥儿"},
[336] = {"名酿","将黑爪烈酒带给祈愿厅里的维沙克公爵。","维沙克公爵与所有人一样有自己的弱点，他对酒的爱好胜过一切。更可恶的是，这个蠢货整天想着把我们这个小小的酒馆给弄关门了，而他自己却呆在楼上整夜整夜地喝个不停，至于那些像滚雪球一样越攒越多的账单，他是肯定不会付的。好吧，让我们看看维沙克会有多喜欢我们给他准备的这种特制佳酿：黑爪烈酒。这一定会很有意思的，$n。把这个带给他，看看他的反应如何，我觉得这傻瓜可能会在祈愿厅里当场开喝。","小武哥儿"},
[337] = {"一本破旧的历史书","把《暴风城的历史》这本书还给暴风城图书馆。","这本书的封面已经有被刮坏的痕迹，还沾上了泥污，但是书脊上“暴风城的历史”的字样仍然清晰可见。打开书的第一页，可以看到上面盖着暴风城图书馆的印章。看起来似乎有人从图书馆借出了这本书却从来没有归还……","小武哥儿"},
[338] = {"荆棘谷的青山","收集《荆棘谷的青山》的手稿中丢失的页面。在集齐四章书之后，将它们还给巴尼尔·石罐。","如果奈辛瓦里知道了这一切，他一定会很生气的！出于对我的信任，他让我来校对他的小说《荆棘谷的青山》的手稿。一开始事情进行得非常顺利，但昨天一阵大风吹过了营地，结果把手稿吹得满天都是！我已经很努力地找回了大部分的书页，但还是有几页被吹进了丛林中。请你帮我把这四章里的掉落的那几页书都给收集起来吧。等这四章手稿都搜集齐了以后，把它们还给我。","小武哥儿"},
[339] = {"荆棘谷的青山 - 第一章","将奈辛瓦里的小说《荆棘谷的青山》的第1页，第4页，第6页和第8页带给巴尼尔·石罐以凑齐第一章。","第一章实在是太精彩了，令人欲罢不能！奈辛瓦里设定了小说的背景，而且在小说里提到了他的同伴们，甚至包括我！不过，糟糕的是……有几页好像弄丢了。似乎第1页，第4页，第6页和第8页落在丛林中的什么地方了！","小武哥儿"},
[340] = {"荆棘谷的青山 - 第二章","将奈辛瓦里的小说《荆棘谷的青山》的第10页，第11页，第14页和第16页带给巴尼尔·石罐以凑齐第二章。","第二章是整个激动人心的狩猎故事的楔子。可里面也有几页找不到了，我真想踢自己几脚！看来我必须得找到第10页，第11页，第14页和第16页才能凑出完整的第二章。","小武哥儿"},
[341] = {"荆棘谷的青山 - 第三章","将奈辛瓦里的小说《荆棘谷的青山》的第18页，第20页，第21页和第24页带给巴尼尔·石罐以凑齐第三章。","第三章是我最喜爱的部分。里面详细讲述了埃尔加丁爵士和罗欧克女士使用矮人步枪完成的第一次狩猎。而且第三章的结尾也写得极好，为什么？因为实在是太扣人心弦了！不过，让我看看，似乎我们仍然要需要找回第18页，第20页，第21页和第24页来凑齐这一章。这些书页不知被风吹到哪里去了……","小武哥儿"},
[342] = {"荆棘谷的青山 - 第四章","将奈辛瓦里的小说《荆棘谷的青山》的第25页，第26页和第27页带给巴尼尔·石罐以凑齐第四章。","啊，第四章，大结局！多么精彩的结局啊！第四章里我们只丢了3页，也就是第25页，第26页和第27页。","小武哥儿"},
[343] = {"关于坚韧的演讲","到暴风城堡的皇家图书馆去与米尔顿·西弗交谈，他将会为你找到克里斯托弗修士所需要的关于冶金学的书。","我正要作一次关于“坚韧的灵魂”的演讲，我想引用一本关于金属学的著作《金属的延展性》里的一些段落。暴风城堡里的皇家图书馆里应该有这本书的副本。你能把它拿来给我吗？如果可以的话，圣光定会保佑你的！皇家图书馆很大，但首席管理员米尔顿·西弗对每一个书架上有些什么书都了如指掌。告诉他我需要什么，他就会把书找给你的。","小武哥儿"},
[344] = {"帕克斯顿修士","与北郡修道院的帕克斯顿修士谈一谈。","《金属的延展性》？是的，我知道这本书。那是本非常好的书，是十几年前一位矮人矿工马戈尔夫·布拉贡写的。他的一生似乎都奉献给了卡兹莫丹的群山，整日在那里挖矿。他是个很聪明的家伙！但这书在哪来着？哦，对了，《金属的延展性》！这本书被我送到北郡修道院去了。那里的管理员帕克斯顿修士想为他那里的图书馆抄写一份留作副本。但这是几个月前的事了，我不知道他为什么会花这么长的时间……","小武哥儿"},
[345] = {"墨水短缺","与湖畔镇的工头奥斯洛交谈，并向他要一些瑞斯班矿石。","我也想把《金属的延展性》这本书尽快抄完，但是……你看看，我只用自己的墨水抄写书籍。这墨水是用我自己的配方制作的，它不容易化开，也不容易弄脏纸，唯一的缺点就是它干得太快了！我的最后一瓶墨水在我抄完之前就用光了，而且我也没法去做新的墨水！要想再配点墨水的话，我就得先弄到一些赤脊山的瑞斯班矿石，一直以来，这种矿石都是由湖畔镇的工头奥斯洛为我提供的。","小武哥儿"},
[346] = {"克里斯托弗的书","回到教堂广场，将《金属的延展性》交给克里斯托弗修士。","现在我已经把这本书抄完了，这里是《金属的延展性》的原本。感谢你的耐心，还有，如果你见到米尔顿的话，请替我向他道歉，我拖了那么长时间真有些不好意思。","小武哥儿"},
[347] = {"瑞斯班矿石","收集5袋瑞斯班矿石，把它们带给北郡图书馆的帕克斯顿修士。","瑞斯班矿石是根据第一个发现他的人——巴尔特·瑞斯班——的名字来命名的。这种矿石在冶炼之后虽然没有铁那么坚硬，但它有一种纯正的黑色，许多抄写员都用它来制作墨水或染料。在北边的瑞斯班矿洞里就可以找到这种矿石。我们通常会有一些存货，但最近大家都忙于抵抗兽人的进攻，没空去采集这种矿石。此外……这段时间以来，赤脊豺狼人占据了瑞斯班矿洞，而且他们的苦工也正在采集这些矿石。所以如果你需要的话，就得自己去那里找了。","小武哥儿"},
[348] = {"荆棘谷热疫","找到巫医安巴格瓦并要求他召唤出野人莫克，然后将野人莫克的心脏交给芬·菲兹拉克。","我病了…病得……非常厉害……我…染上了…荆棘谷热疫…致死的疾…疾病…………只…只有吃下…野人莫…莫…莫克…的心脏…才…才有救…那…是…一只残忍而…狡猾的…野兽。……巫医安巴格瓦巫师…是…唯一会…召唤…它…的人……找到…住在南边…海岬…洞穴…里的安巴格瓦…………快点…我就要死了…就要死了……","小武哥儿"},
[349] = {"荆棘谷热疫","","","小武哥儿"},
[350] = {"老朋友","与暴风城的埃林·提亚斯谈一谈。","马尔松曾和迪菲亚兄弟会的一个成员进行联系，而且莱斯科瓦公爵似乎也脱不了干系……在范克里夫和特雷德被杀之后，莱斯科瓦依然逍遥法外，我们手上还是没有他罪行的证据。除了证据问题之外，莱斯科瓦本身就是个神通广大的贵族，这些优势让他得以凌驾于法律之上。你需要帮助。虽然我并不很情愿走这一步棋，但是的确有一个可以帮助我们的人。你应该到暴风城的贸易区去找提亚斯。","小武哥儿"},
[351] = {"寻找OOX-17/TN！","把定位器带到奥格索普的母体机器人那里。","你发现了一个奇怪的蛋形金属物体。随便拨弄了几下之后，它居然打开了，变成了一个看起来像是由侏儒创造的那种机器装置！一个辟里啪啦的声音从这个蛋形机器装置中传了出来。“我的名字叫奥格索普，我的母体机器人不见了！如果你能帮我找到它的话，我会奖励你的！请把这个定向器带到我的母体机器人那里。我现在已经为你勘探出了它的所在地！它现在就在塔纳利斯的大裂口那里！”","小武哥儿"},
[352] = {"<UNUSED>","","Great Mammoda. Enormous, she was, with claws and teeth like swords. Now, I was caught off my guard, but I don't think being ready would have helped my cause much. One swipe and poof！ Darkness. They say I'm lucky to walk now……Well, not much enjoyment","小武哥儿"},
[353] = {"雷矛的包裹","把给卡尔·雷矛的包裹交给洛克莫丹北部哨塔里的巡山人卡尔·雷矛。","雷矛氏族是一个倍受尊敬的矮人氏族，他们向来以独具慧眼著称——所以远在铁炉堡的巡山人才会托人不远千里地让人传信，委托我给他们打制一把武器，哈哈！这把武器已经完成了，但是巡山人卡尔·雷矛住在洛克莫丹，离这里实在是太远了。如果你正好要到那边去的话，就替我把这个包裹带给他吧。巡山人卡尔·雷矛最后一次和我联络的时候，他说他在洛克莫丹北部的哨塔里。","小武哥儿"},
[354] = {"阿加曼德家族","把格里高的遗骸、妮萨的残骸和萨尔曼的遗骸交给布瑞尔的库勒曼·法席恩。","阿加曼德家族曾是提瑞斯法林地中最富有的家族。我过去曾在他们的磨坊里工作……当然，我是说在瘟疫降临之前。天灾军团入侵的时候，阿加曼德家族的人们加固了他们的庄园，并说服了在他们家做工的人留下来帮助他们抵抗天灾军团。我们实在是太蠢了，但我们至少是愚蠢而忠诚。而阿加曼德家族用荣耀之类的幌子让我们去送死，结果现在他们倒成了天灾军团的走狗！为了被遗忘者，你必须去剿灭堕落于瘟疫之中的阿加曼德家族！把他们的尸体带回来给我。","小武哥儿"},
[355] = {"与塞弗伦交谈","与布瑞尔的执政官塞弗伦谈一谈。","你把阿加曼德家族所有人的遗骸都带来给我了，这完全可以满足我的复仇欲望。但阿加曼德磨坊对我，哦，不仅仅是对我，对我们全体被遗忘者来说仍是个威胁。我已经把你与阿加曼德家族战斗的事迹告诉了执政官塞弗伦大人，他也希望能和你谈谈。","小武哥儿"},
[356] = {"巡查后方","杀死8个可怕的血僵尸和8个游荡的幽灵，然后向亡灵卫兵林奈汇报。","亡灵壁垒上的卫兵们时刻都在提防着从瘟疫之地潜入提瑞斯法的敌人，但仍有些天灾军团的士兵能躲过这样的警戒线。如果想要成功地维持我们对这一带的控制，就必须进行一次清查行动——我们绝对不能腹背受敌。如果补给线被切断了的话，那后果就将是灾难性的。去协助亡灵壁垒的卫兵进行防御吧。往东边一路巡逻过去，如果你发现任何天灾军团的爪牙，就直截了当地把他们干掉。特别注意一下东边的巴尼尔农场，那里已经到处都是天灾军团的散兵了。","小武哥儿"},
[357] = {"巫妖的身份","把巫妖的法术书带给幽暗城的比索·埃斯沙德。","北边澈水湖中的一个小岛上住着一个巫妖。虽然他是个独立的亡灵，不过他认为其他所有的亡灵都是天灾军团的奴隶，他的爪牙会袭击任何靠近他的人。他是个无主之人，所以黑暗女王想要招降他。如果他确实精通于巫术的话，那么他的知识会对我们很有帮助。不过我得先看过他的法术书才能了解他的身份和学问。潜入他的营地，把书拿回来见我。","小武哥儿"},
[358] = {"盗墓贼","杀死腐皮盗墓贼和混血腐皮豺狼人。给布瑞尔的执政官塞弗伦带回8瓶防腐剂。","北边的加伦鬼屋你去过吗？那个地区的西南角是一大片乱坟岗，里面葬着提瑞斯法一带的大量因瘟疫而死的人。那边坟墓里的尸体大多没能变亡灵，但最近天灾军团派出了一群腐皮豺狼人到那里去收集尸体，以此来壮大他们的军队。我们不能允许这样的事情发生！你的任务有两个：杀光躲在乱坟岗和加伦鬼屋里的腐皮豺狼人，并把他们身上的防腐剂抢回来，正是这种防腐剂使他们活过来的。","小武哥儿"},
[359] = {"亡灵卫兵的职责","与亡灵卫兵林奈谈一谈。","我要这里东边的亡灵卫兵驿站立刻给我提交一份最新的报告。我必须知道天灾军团是否已经迂回绕过了防波堤并进入了提瑞斯法林地。我们要时刻保持警惕，封锁住这里与瘟疫之地的边境，绝对不能让天灾军团占据这里的任何一寸土地！沿着路向南走，在第一个岔路口转向东，就可以到达驿站了。到那里去找亡灵卫兵林奈，她手里掌握着我最需要的情报。","小武哥儿"},
[360] = {"向塞弗伦回报","向布瑞尔的执政官塞弗伦报告。","现在带着这些情报回到执政官塞弗伦那里去吧。他急需这几份报告，你动作最好快点。如果你回程的路上看见了任何天灾军团的成员，就顺便干掉他们，我们可不能让这些垃圾在我们的地盘上胡作非为。","小武哥儿"},
[361] = {"未寄出的信件","找到伊维特·法席恩，将萨尔曼·阿加曼德的信交给她。","这封信的作者是格里高·阿加曼德的长子萨尔曼。收件人则是一位名为伊维特·法席恩的女士，尽管现在看来这封信显然是没寄到她手上……","小武哥儿"},
[362] = {"闹鬼的磨坊","杀死代弗林·阿加曼德，然后将代弗林的遗骸交给布瑞尔的库勒曼·法席恩。","代弗林·阿加曼德是阿加曼德家的两个男孩中最小的一个，但这两个男孩子却完全不像是兄弟。萨尔曼身材高大而且待人彬彬有礼，而他的弟弟代弗林却身体虚弱，而且嘴巴很刻薄恶毒。当阿加曼德磨坊遭遇瘟疫的时候，他是第一个被感染的。现在，只要你靠近通向阿加曼德磨坊的道路，就仍能听见他那喋喋不休的呓语。我正在收集阿加曼德家族所有人的遗骸，首先，我想弄到可怜的代弗林的尸骨。找到并摧毁他，然后把他的遗骨带回来给我。","小武哥儿"},
[363] = {"突然醒来","和暗影牧师萨维斯谈一谈。","你醒得可真是时候。我们本来还准备把你和其他的死人一起火葬了，没想到你居然醒来了。我是摩尔多，丧钟镇墓穴的看护人。现在你已不再是巫妖王的奴隶了。暗影牧师萨维斯就在山脚下的教堂里，去和他谈谈吧，他会告诉你更多你必须了解的事情。","小武哥儿"},
[364] = {"无脑的僵尸","暗影牧师萨维斯让你杀掉8个无脑的僵尸和8个丑陋的僵尸。","我们被遗忘者正在与巫妖王的天灾军团作战，那支军队包括用亡灵法术唤起的亡灵军队，大陆北方的那些愚蠢的野兽，还有那些永远遭受折磨的鬼魂。在这个村庄的北部有大量的无脑僵尸到处横行，我们必须消灭他们。消灭他们，即使他们以前可能是我们的兄弟姐妹也不要手软，那些行尸走肉如今只不过是巫妖王的奴隶罢了。","小武哥儿"},
[365] = {"悲伤之地","从位于布瑞尔西边、丧钟镇北边的农场中偷10颗南瓜来，把它们交给布瑞尔的药剂师乔汉。","看看谁来了？你看上去是个菜鸟<职业>吧。如果你想向黑暗女王陛下证明自己的实力，就得先学会我们被遗忘者行事的几条基本原则。这里的西边有个农场，那块地上的人呀，就跟腐烂尸体上的苍蝇一样多。更糟糕的是，血色十字军从他们的哨塔里跑出来巡逻的时候，也可能会经过那里。给这些渣滓们好好地上一课吧，把他们的宝贝南瓜给我偷10颗来。偷到10颗南瓜以后，就把它们交给布瑞尔的药剂师乔汉。","小武哥儿"},
[366] = {"归还书籍","到冈瑟尔居住的小岛去归还他的法术书。","很久以前，冈瑟尔和我，还有现在隶属于天灾军团的图勒·鸦爪，我们三人是很好的朋友，我们曾一起在肯瑞托学习魔法。冈瑟尔和我都是大瘟疫的牺牲品，冈瑟尔后来成为了巫妖王的手下。现在我得知他脱离了巫妖王的魔爪，这真是个好消息。我们一定要找到他。我给他的书上施放了一个魔咒，当他看到这本书的时候就会知道我也已经摆脱了巫妖王的控制，希望他在知道这一点以后会加入我们。","小武哥儿"},
[367] = {"新的瘟疫","布瑞尔镇里的药剂师乔汉要求你收集5瓶黑暗犬的血液。","希尔瓦娜斯大人最近交给了我们皇家药剂师学会一项很有挑战性的命令。黑暗女王相信我们的知识与新发明的魔法将会是她击败阿尔萨斯的有力武器，她要求我们研制出一种新的瘟疫，这种瘟疫要比以前出现在艾泽拉斯大陆上的任何一种疾病都要更加猛烈，它会把阿尔萨斯和他的天灾军团彻底毁灭。我的研究结果表明，野兽的血液也许是一种重要的药引。给我带回五瓶黑暗犬的血液来，我要验证一下自己的理论。","小武哥儿"},
[368] = {"新的瘟疫","布瑞尔镇里的药剂师乔汉要求你收集5片提瑞斯法林地的邪鳍鱼人的鳞片。","在你帮我收集样本的同时，我的实验报告也出来了。看来我还需要更多的材料来进行进一步的研究，适当加强这种新瘟疫的传染能力。毒杀个把倒霉鬼，那是小孩子才玩的把戏，只有将瘟疫传遍整个世界才算得上是有意义的事。我需要5片邪鳍鱼人身上的鳞片，在北边或者西边的海滩上应该就能找到那些鱼人。","小武哥儿"},
[369] = {"新的瘟疫","布瑞尔镇里的药剂师乔汉要你去收集4份邪恶的夜行蜘蛛的毒液样本。","在你出去收集鳞片的时候，我已经在我的藏书中找到了一些古老而有趣的文章。这些文章里面提到，以前曾有一种古代的瘟疫杀死过成百上千的人，而后来又有人发现在夜行蜘蛛的毒液中就能提取到这种瘟疫的致病物质。给我带些夜行蜘蛛的毒液来，让我完成这个实验。我想知道毒液中的感染性元素是否能和我最新研制出来的瘟疫病原体共存。据说这种蜘蛛一般在提瑞斯法林地的东部出没。","小武哥儿"},
[370] = {"与血色十字军的战争","布瑞尔的执行官塞加德要求你杀掉派瑞恩队长、3名血色狂热者和3名血色传教士。","执行官阿伦的文件中对如何清除这群在我们的土地上肆虐的人类的问题作了详细的部署。情报表明，血色十字军派遣了派瑞恩队长以及足有一个整编旅的部队进驻了布瑞尔西南方的废塔。去杀掉派瑞恩队长、3名血色十字军狂热者和3名血色十字军传教士，然后向我回报。","小武哥儿"},
[371] = {"与血色十字军的战争","布瑞尔的执行官塞加德要求你杀掉瓦松队长和5名血色苦行修士。","我们仍然处于战争状态中，而且血色十字军正在逐渐壮大。执行官阿伦给我的报告中提到，在瓦松队长的指挥下，血色十字军正以提瑞斯法东南部巴尼尔农场附近的那座废塔为据点肆意劫掠。去杀掉瓦松和5名血色十字军苦行修士，这对十字军来说将是一次沉重的打击！","小武哥儿"},
[372] = {"与血色十字军的战争","布瑞尔的执行官塞加德要求你刺杀麦拉其队长及他的两名保镖。","血色十字军已经从提瑞斯法林地北部的废塔出发，穿过了法奥之墓。根据目前我们所掌握的情报，一个名叫麦拉其的军官指挥着这支邪恶的部队，他是个非常残忍的家伙。我相信你能完成这个非常重要而又危险的任务。以黑暗女王陛下的名义，杀死麦拉其和他的两名保镖！","小武哥儿"},
[373] = {"未寄出的信","将艾德温·范克里夫的信交给巴隆斯·阿历克斯顿。","搜查艾德温·范克里夫的尸体时，你从一堆杂乱的物品中找到了一封还未来得及发出的信。地址一栏上写着巴隆斯·阿历克斯顿，暴风城石工协会，城市大厅，教堂广场。这显然是最近刚刚写好并封上的。","小武哥儿"},
[374] = {"死亡证明","给布瑞尔的亡灵卫兵伯吉斯带回10枚血色十字军徽记之戒。","执行官塞加德告诉我说你最近和血色十字军干上了，提瑞斯法林地里现在到处都是这帮讨厌的家伙。黑暗女王麾下的瓦里玛萨斯大人计划将人类这种艾泽拉斯大陆上的渣滓与垃圾彻底清除掉。但目前的状况是，人类当中最麻烦的一群家伙——血色十字军——已经杀入了提瑞斯法林地，我们必须得面对他们的挑衅。去吧，去给这群该死的血色十字军一点颜色看看，<职业>。给我带回10枚血色十字军徽记之戒，以此证明你对伟大的黑暗女王陛下与瓦里玛萨斯大人的忠诚。","小武哥儿"},
[375] = {"死亡之寒","给布瑞尔的格雷森·戴德马带回5张夜行蝙蝠的毛皮和一些粗线。","好冷啊……可怕的瘟疫正如冰冷的毒蛇一般在我的血管中逡巡，也许很快我就会彻底失去意志，但这世上没有任何东西能够阻止我为我们伟大的黑暗女王效命。一接到命令，我就开始为希尔瓦娜斯大人军队中那些死去的战士缝制尸袋。但现在我的手却因为寒冷而颤栗不已。如果你能给我带回五张夜行蝙蝠的毛皮和一些粗线的话，我就可以给自己缝条毯子了。帮帮我，，这样我就可以继续为黑暗女王陛下的事业效力了。","小武哥儿"},
[376] = {"被诅咒者","新兵艾尔雷斯需要6只食腐狼的爪子和6只夜行蝙蝠翼。","我的任务包括照料受伤的士兵，缝制铠甲和衣服，还有为暗影牧师萨维斯提供任何他可能需要的支援。看起来，你也即将加入到为他效力的队伍中……我猜是要猎杀那些没脑子的家伙。好吧，如果你还想留着你的小命的话——我想你一定是的——也许我能帮助你。我这里没有足够的狼爪子和蝙蝠翅膀了，如果你能帮我弄一些来的话，我会帮你找几件铠甲。在这里的西北方可以找到大群的狼和蝙蝠。","小武哥儿"},
[377] = {"罪与罚","夜色镇的米尔斯迪普议员要你杀死迪克斯特·瓦德，并把他的手带回来作为证明。","贵族议会好像嫌他们对暮色森林的漠不关心还不够过分，现在他们居然无视夜色镇议会的存在，决定把迪克斯特·瓦德囚禁在暴风城，而不是按照埃伯洛克公爵大人的判决将这个恶棍斩首！迪克斯特·瓦德是在把墓地里的尸体卖给摩本特·费尔时被抓住的，这理应是死罪。可是暴风城却认为他们才拥有对他的处决权！去暴风城的监狱把瓦德杀掉，把他的手给我带回来作为证明，我会奖赏你的。","小武哥儿"},
[378] = {"卡姆·深怒","丹莫德的莫特雷·加玛森要求你把卡姆·深怒的头颅交给他。","你已经向我们展示出了你对麦格尼陛下的忠诚，<职业>。而且我也深刻地感受到了你对那些黑铁矮人的仇恨。我必须要坚守岗位，因此，我不得不把一个本应由我亲自去完成的重要任务交给你。根据罗戈收集到的情报显示，卡姆·深怒正是袭击萨多尔大桥的元凶。由于他所布下的邪恶计划，长须才失去了他的亲人。这个刽子手由于某些政治原因被扣押在了暴风城的监狱里。我要他死，。为了长须！杀死卡姆·深怒，把他的脑袋给我带回来！","小武哥儿"},
[379] = {"口渴的比格维兹","给加基森的首席工程师沙克斯·比格维兹带去五只废土水袋。","你需要能量源，我可以帮你。但是你知道我要什么吗？我要喝的！给我弄五只废土水袋来，然后我就会把4711-FTZ交给你。现在……你想知道在什么地方可以找到废土水袋，对吗？去这里的东边找废土游牧民吧，他们身上会带着这种水袋。","小武哥儿"},
[380] = {"夜行蜘蛛洞穴","执行官阿伦要你去杀掉10只小夜行蜘蛛和8只夜行蜘蛛。","我们的一项最重要的任务就是获取赖以生存的自然资源。即使在当年联盟最鼎盛的时候，黄金资源也是非常缺乏的。这里的西北面有一处金矿，我们需要矿洞里的资源，但是那里蜘蛛横行，我们根本无法进去采掘金矿。我手上没有人可以去完成这项任务，所以我们只有一步一步慢慢地来。去那里看看吧，也许你能做些什么……","小武哥儿"},
[381] = {"血色十字军","从血色信徒和血色新兵身上收集12枚血色十字军臂章，把它们交给执行官阿伦。","得知我们在金矿的进展非常顺利，你一定很开心吧？得益于你的帮助，我们终于可以把注意力放到别的事情上了。我的斥候报告说，一支血色十字军的小分队在东南方建立了营地。血色十字军是一个卑鄙的组织，他们视我们为死敌，只要有一个亡灵——无论是巫妖王的爪牙还是我们被遗忘者——还活着，他们就不会停止追杀我们的行动。所以我们必须先发制人！你要多加小心，这些邪恶而狂妄的十字军是一群非常危险的家伙。","小武哥儿"},
[382] = {"十字军信使","到十字军营地去杀掉信使迈文·考加尔，将你发现的情报交给执行官阿伦。","布瑞尔那边的上级给我发来的文件显示，有一个从血色修道院出发的血色十字军斥候已经潜入了丧钟镇。有报告说这个人携带着非常重要的情报。至于更多的细节，我不得而知。但不管怎么样，我们必须得到这份情报！你是我眼下能调动的最合适的人选，$n。找到那个信使，带回你能弄到的任何情报。","小武哥儿"},
[383] = {"重要情报","把血色十字军文件交给布瑞尔的执行官塞加德。","我必须将这些东西交给我的上级——执行官塞加德，他就在布瑞尔。有了这份详尽的情报，我们就能给血色十字军以沉重的打击。你在丧钟镇对我们做出了很大的贡献，现在我要你去把这份情报及时交给塞加德，我想他能帮你找到更多能让你大展身手的工作。沿着这条路向北走出丧钟镇，在进入提瑞斯法林地以后，你很快就会来到一个十字路口，这时向东走，然后一直向前就可以到布瑞尔了，路上有一座炉灰庄园可以帮你确认自己的方向。","小武哥儿"},
[384] = {"啤酒烤猪排","卡拉诺斯的拉格纳·雷酒需要6块峭壁野猪肋排和1杯狂想麦酒。","啤酒烤猪排是我的老主顾们最喜欢的大餐！问题是，为我提供猪排的猎手被国王征募去打仗了。也许你能帮帮我？如果你可以给我弄六块峭壁野猪肋排，外加一杯酒店里卖的狂想麦酒的话，我就把祖传的啤酒烤猪排的烹饪方法教给你，而且我还可以让你免费品尝我做出来的美食！秘密就在麦酒里！","小武哥儿"},
[385] = {"捕猎鳄鱼","收集5块鳄鱼肉和6张鳄鱼皮，把它们交给旅行者营地里的马雷克·铁心。","很多猎人到洛克莫丹来都是为了捕猎这里的鳄鱼。总有一些商人专门寻找这种鳄鱼皮，用它们来制作衣物或是护甲，还有些人则喜欢品尝鳄鱼肉。我们一直在进行这种贸易，但交易量并不是很大，因为鳄鱼很凶猛，而且它们一般都盘踞在洛克湖中的小岛上。嘿，别被我的话给吓倒了，和鳄鱼较量一番对你来说也是一种历练。你看能不能……","小武哥儿"},
[386] = {"伸张正义","把塔格尔的头颅带给湖畔镇的卫兵伯尔顿。","可怕的塔格尔是加塞尔佐格手下的一个高级杀手。他杀人的手法十分残忍，即使以兽人的标准来看也是残暴无比。那些为了保卫国家而奋勇作战的战士们落在他手里都会被他折磨致死。这个恶棍现在被关在暴风城的监狱里，被判处了死刑。不过，这件事情好像出了点小差错，一个官僚习气十足的贵族推迟了处死他的日期。我敢打赌这里面一定有鬼。处死塔格尔吧，。到暴风城的监狱里去，在他玩出什么把戏之前把他干掉。","小武哥儿"},
[387] = {"镇压暴动","暴风城的典狱官塞尔沃特要求你杀死监狱中的10名迪菲亚囚徒、8名迪菲亚罪犯和8名迪菲亚叛军。","我们必须把暴动给镇压下去！我需要你的帮助。如果外面的人知道监狱里面已经失去了控制，我一定会丢了饭碗的！这是我所见过的最无聊的闹剧了。现在最重要的是逼迫这些囚犯投降，这样才能保证暴风城的安全。叛乱的代价就是死亡。去杀掉一些囚犯，这样叛乱才能得到控制！","小武哥儿"},
[388] = {"鲜血的颜色","暴风城的尼科瓦·拉斯克要你取得10条红色毛纺面罩。","痛苦如同冰冷的河水一样从我的血管中流过。我的孙子麦克是个多好的孩子呀，他只有14岁。当暴风城的军队被派往前线的时候，麦克也拿起了武器去守卫城市。他是监狱的守卫，那座监狱里关押着许多迪菲亚兄弟会的成员。有一些囚徒们把他们的羊毛毯改织成他们组织的头巾，麦克把这件事情上报了，结果他遭到了报复，被人从后面刺了一刀。我要报仇。给我带回10条迪菲亚盗贼们的羊毛面罩，像鲜血一样殷红的那种。","小武哥儿"},
[389] = {"巴吉尔·特雷德","与监狱的典狱官塞尔沃特谈一谈。","范克里夫和我过去都曾是石匠行会的成员，我们的主要工作是在战后重新建设暴风城。当我们完成了自己的职责时，却发现我们被彻底地欺骗了。贵族们拒绝付给我们酬劳，一些石匠行会的元老被提拔成了官员，但范克里夫出于对所有石匠会员的忠诚拒绝了他们。他组织了一场暴动，并离开了城市，从此发誓要进行复仇。他的副官巴基尔·斯瑞德或许对范克里夫的计划有一些了解，他目前正被关押在监狱里。","小武哥儿"},
[390] = {"<UNUSED>","","","小武哥儿"},
[391] = {"监狱暴动","杀死巴基尔·斯瑞德，把他的头带给监狱的典狱官塞尔沃特。","让我们把话挑明了说吧，$n：我不信任你。但是，现在的情况紧急，我也管不了那么多了。你到下面去干掉那个该死的斯瑞德，把他的脑袋砍下来带给我。还有，如果你胆敢跟他合计什么把戏，或者你不上来了的话……只要被我抓到你，就准备跟那群蛆死在一块吧。","小武哥儿"},
[392] = {"好奇的访客","将神秘访客的资料交给暴风城的巴隆斯·阿历克斯顿。","在斯瑞德刑期的第一年里，从来从没有人探视过他。我猜当时迪菲亚兄弟会认为他已经彻底没用了，所以准备任他自生自灭。然而几个月前，一切都变了。有人开始定期探视他……每周一到两次。那是个奇怪的男人，沉默寡言。我有点疑心，但他的证件是真实且合法的。他的名字叫麦里克，这是他的一些资料。我觉得他可能不会再来探视斯瑞德了。","小武哥儿"},
[393] = {"往日的阴影","与旧城区的马迪亚斯·肖尔谈一谈。","我确实没什么线索，$n。但或许另外有人能帮上你的忙，而且他还欠了我一个人情——好了，现在不是说那个的时候。暴风城兵营中的军情七处首领马迪亚斯·肖尔或许能轻松搞定这类事。如果说有谁知道这事的话，一定就是他，他此刻就在旧城区。","小武哥儿"},
[394] = {"禽兽的首级","去见暴风城旧城区的马迪亚斯·肖尔。","到暴风城去找肖尔，告诉他莱斯科瓦的问题已经被你解决了。我敢说他一定会为暴风城出了你这样的一位英雄而感到自豪的。他甚至有可能将你引荐给暴风城里的达官显贵。你要知道，$n，这座城市里还真没有什么肖尔搞不定的事情。贵族们可以自认为他们完全控制着暴风城，但总有一些事情是他们无能为力的。","小武哥儿"},
[395] = {"兄弟会的灭亡","与暴风城的巴隆斯·阿历克斯顿谈一谈。","啊，我差点忘了。阿历克斯顿在你离开的时候来过，他有话想跟你说。显然他是想向国王陛下报告关于迪菲亚兄弟会的事情。给你个忠告，$n。如果有人问到这个，我会把除了你杀掉莱斯科瓦以外的所有细节都告诉他。相信我，我…对这种事…已经习以为常了……另外，别跟任何人说起提亚斯的事情。","小武哥儿"},
[396] = {"觐见国王","将有关迪菲亚兄弟会的报告送给暴风要塞里的国王瓦里安·乌瑞恩。","我准备了一份报告呈递给国王陛下。当我听说了你最近的事迹之后，我认为你是递送这份报告的最佳人选。别担心，国王陛下一定会嘉奖你的。你的觐见已经被列入了陛下的日程表，所以你最好快点到暴风要塞里去等待召见。","小武哥儿"},
[397] = {"干得好","去找黑爪加尔德斯的仆人兹吉谈一谈，并向他索要你的酬劳。","我听说维沙克公爵很喜欢他收到的饮料。你帮了我们的大忙，。暴风城的术士们从此可以不再受他人干涉地自由行事了。我准备了一件特殊的小礼物给你，以表示我们的感谢。去找我的仆人兹吉，收下你的报酬吧。","小武哥儿"},
[398] = {"悬赏：蛆眼","杀死蛆眼，并将他的爪子交给布瑞尔的执行官塞加德以换取酬劳。","悬赏：蛆眼！这只名叫蛆眼的豺狼人臭名昭著，即使是在它的同类眼中都显得非常邪恶而污秽，它因为对被遗忘者们犯下了不可饶恕的罪名而被判处了死刑，这只卑鄙的野兽为巫妖王的军队偷盗了无数的尸体。上次有人看到蛆眼作恶是在布瑞尔北边的加伦鬼屋。布瑞尔镇将为执行这项判决的勇敢者提供一份高额的奖金。完成任务之后，请将这只野兽的爪子交给执行官塞加德。只有弱者才会有怜悯之心。","小武哥儿"},
[399] = {"童年的记忆","到巴隆斯·阿历克斯顿在西部荒野的房子里去找到他的指南针，并将它带回暴风城的教堂广场交给他。","许多年前，我还只是个在西部荒野的农场里干活的小男孩，不过现在看来，这段回忆只能封存起来了。俗话说时光一去不复返，这句话在我身上得到了印证，我家的房子已经被烧毁，现在又给一群盗贼占领了。我曾向父亲询问过我的一些物品的下落——包括我的第一个指南针，他说他没办法把那些东西拿回来。但是他又说……它们应该就藏在农场外面的什么地方。你可以在哨兵岭的西边找到阿历克斯顿农场。你能帮我把那些东西找回来吗？","小武哥儿"},
[400] = {"贝尔丁的工具","把贝尔丁的工具交给贝尔丁·钢架。","贝尔丁·钢架是本地最好的坦克机械师！不过他从来不爱护他的工具，他弄坏扳手的速度远远大于我们的供货速度！我们刚刚才赶出他最近订的一批货。如果你能把这些东西交给他，我想他一定会让你感到不虚此行的。他开的钢架补给站就在卡拉诺斯的东北边。老牌的攻城坦克驾驶员们经常在那里碰头，所以你到了那里之后要睁大眼睛，说不定能找到好些活儿。","小武哥儿"},
[401] = {"等待希拉完工","稍等片刻，然后再和希拉·沃宁迪交谈。","我很快就能把信件翻译完了。请稍等一会儿再过来吧。","小武哥儿"},
[402] = {"正在忙碌的希拉","晚点再去见希拉，看他是否还在忙着。","真抱歉，不过我手头上还有些别的事务要处理。如果我们能活下来，也许我就能完成这段翻译。","小武哥儿"},
[403] = {"戒备森严","","","小武哥儿"},
[404] = {"腐烂的爪子","给布瑞尔的亡灵卫兵迪林格尔带回7只腐烂的爪子。","有一小撮天灾军团的士兵已经渗入了提瑞斯法林地，在布瑞尔以西一带的旧桥附近活动。去那边去增援我们的部队，杀光所有你见到的腐烂的死者和破碎的尸体。把他们都给我拆成骨头架子，然后把他们那腐烂的爪子给我带回来，我会奖励你的。","小武哥儿"},
[405] = {"流浪的巫妖","将塞弗伦的命令交给幽暗城的比索·埃斯沙德。","幽暗城里的一位法力强大的高阶法师比索·埃斯沙德给了我一个任务，让我去为他找一个与天灾军团有着丰富斗争经验的勇士。你，，显然就是他要找的人。现在立刻去向比索报到，他会给你指派新的任务。我也不清楚任务的细节，但大致上好像是要招安一名独居的巫妖之类的。这份工作可能会很危险。去做好准备吧，。你绝对不能失败。比索就在幽暗城的魔法区里。","小武哥儿"},
[406] = {"<UNUSED>","","","小武哥儿"},
[407] = {"悲伤之地","将斑纹南瓜带给被关在恐惧之末旅店地下室中的血色十字军俘虏。","看上去这南瓜没有什么不正常吧？如果我们想要阻止阿尔萨斯的军队在北方继续推进外加人类势力在南方的肆虐横行，那么我们必须从现在开始就意识到自己身为亡灵的优势。只要稍微耍点小把戏，一个简单的南瓜就能让任何人成为黑暗女王的优秀探子。我最新培育的这种南瓜就可以做到这一点。现在据说又有个血色十字军狂热者被俘虏了，他被关在恐惧之末旅店的某个房间里。把这个南瓜拿去给那个蠢货，让他吃了。","小武哥儿"},
[408] = {"家族墓穴","杀死8个哀嚎的鬼魂和8个腐烂的古尸。消灭达高尔队长，并将他的颅骨交给布瑞尔的执政官塞弗伦。","如今阿加曼德磨坊已经成了天灾军团的一处重要据点，其中防守最为坚固的地方就是阿加曼德的家族墓穴了。天灾军团的一个兵团就驻守在那里，他们由一个名叫达高尔队长的骷髅领导着。他们还利用某种通灵术复活了阿加曼德家族的死者们，并打算利用它们来对付我们。我们绝对不能允许这种事情发生，你必须阻止它。到阿加曼德家族墓穴去，战胜那些还魂的阿加曼德家族的死尸们。还有，把达高尔队长的颅骨也给我带回来。","小武哥儿"},
[409] = {"证明忠诚","拿上一根诱灵蜡烛。召唤出莉莉丝·奈法拉并杀死她。然后向岛上的冈瑟尔回报。","你说你没有被巫妖王控制住自己的思想，这一点已经由比索在我书上灌入的魔法证实了。但是，你仍然得先证明自己是天灾军团的敌人，这样我才会彻底信任你。在这座岛屿南边的小岛上有一处古老而血腥的祭坛，那里目前被一个强大的天灾军团斥候莉莉丝·奈法拉所占据着。从我身边的这个木箱里拿出一根诱灵蜡烛，然后将其点燃并放到祭坛上，莉莉丝会很快醒来。消灭莉莉丝，这样一来，我就会相信你确实是巫妖王的敌人了。","小武哥儿"},
[410] = {"潜伏的阴影","","","小武哥儿"},
[411] = {"巫妖归顺","将虚空宝石交给幽暗城的比索·埃斯沙德。","拜托你，请将这块虚空宝石带给我的老朋友比索。这样我就能和他交流了……我有好多事想和他说呢。","小武哥儿"},
[412] = {"自动净化装置","收集8个多档齿轮和8个自适应齿轮，把它们交给卡拉诺斯的拉兹·滑链。","通过对诺莫瑞根现状的进一步分析，我们发现不但那些该死的穴居人没有被消灭，反而有更多的侏儒变成了丧心病狂的、邪恶的怪物。我和奥齐希望用我们的最新发明——自动净化装置——来扭转这种局面。这台机器即将大功告成，不过我们急需一些多档齿轮和自适应齿轮才能搞定最后的部分，请从诺莫瑞根的麻疯侏儒那里弄些过来吧。","小武哥儿"},
[413] = {"微光酒","把这一大桶微光酒交给巡山人维拉特·麦酒。","我希望我兄弟维拉特能够品尝一下我最新酿制的微光酒。他是一个在南面的警戒塔里执勤的巡山人，就是靠近洛克莫丹边界的那两座哨塔里的一座。他不是酿酒师，但是他非常喜欢喝酒，而且我相信他一定喜欢这种酒的。你能替我把这桶微光酒交给他吗？","小武哥儿"},
[414] = {"卡德雷尔的酒","把这桶微光酒带给巡山人卡德雷尔。","我兄弟酿造的微光酒真是极品！我想让我的一个朋友也品尝一下，他叫卡德雷尔，经常在塞尔萨玛附近的路上巡逻。要去塞尔萨玛的话，就往东南方穿越隧道，然后在岔路口向东北方走，最后沿着大路一直走就能到塞尔萨玛了。把这桶微光酒交给巡山人卡德雷尔尝尝，看看他是不是也赞不绝口！","小武哥儿"},
[415] = {"雷杰德的新酒","和雷杰德·麦酒谈一谈。 ","烈酒村的雷杰德·麦酒正在找你。他要和你谈谈他最新正在酿造的一种酒……他告诉我你帮了他很多忙。你也许应该去一次烈酒村，看看他要说什么。也许，你可以在那里免费享受到一顿大餐…… ","小武哥儿"},
[416] = {"狗头人的耳朵","收集12只坑道鼠的耳朵，把它们带给塞尔萨玛的巡山人卡德雷尔。","我们在西边遇到了点麻烦。坑道鼠狗头人在那里的丘陵地带建起了巢穴，把我们的地盘弄得乌烟瘴气！我们必须把他们给消灭掉。去捕杀那些坑道鼠狗头人，把他们的耳朵拿回来给我，我就给你赏金。坑道鼠狗头人的巢穴就在塞尔萨玛北边的山脚下。","小武哥儿"},
[417] = {"驾驶员的复仇","杀死癞爪。把它的肮脏的爪子和莫里·铁钻的日记交给驾驶员塞克·锤足。","莫里·铁钻在他的日记中写道，他受到了一头名叫癞爪的巨型冰爪熊的袭击。他赶走了这只野兽，不过自己也已遍体鳞伤。从莫里尸体上的伤痕判断，癞爪一定又折回来杀死了他。然而，莫里在他的日记中写下了他最后的遗愿：杀死癞爪，为我复仇。","小武哥儿"},
[418] = {"塞尔萨玛血肠","收集3块熊肉、3根猪大肠和3份蜘蛛的毒液，把它们交给塞尔萨玛的维德拉·壁炉。","塞尔萨玛这儿饥肠辘辘的人可真不少，有跑进跑出的孩子，也有在挖掘场忙了一整天的工人。我们这儿有一道出名的菜色——血肠，你大概还没尝过吧？没有？在这儿要吃饭就得干活，别以为你是个出色的<职业>就可以例外。我需要熊肉、做肠衣用的猪大肠，还有做调料用的蜘蛛的毒液。把这些东西找来，剩下的就交给我维德拉好了！","小武哥儿"},
[419] = {"失踪的驾驶员","找到驾驶员莫里·铁钻。","我的朋友，同时也是同一蒸汽坦克车组的同事——莫里·铁钻，在山上失踪了。我们当时正在寻找一种可以用来制作高爆炸药的稀有矿石。在我们搜寻的过程中，莫里驾驶着他的坦克攀上一处陡峭的山坡后抛锚了！他确信矿石就在这片山地里，所以就让我守着我们的机车，而他一个人步行继续去搜索。莫里已经有好些天没回来了，夜里我时常能听见山中的野兽发出的咆哮。莫里是个硬汉，不过我还是有点为他担心。求求你，，帮我找到他。","小武哥儿"},
[420] = {"森内尔的观察站","把格瑞林的报告交给卡拉诺斯的森内尔·白须。","隧道里的穴居人非常具有攻击性，它们会毫不犹豫地对隧道中的过客发动袭击。不过你看起来挺结实的，应该不会有什么危险。方向？如果你要找森内尔，就到卡拉诺斯去吧。一直穿过隧道，出去之后沿着大路向前走，没几步就到卡拉诺斯了。","小武哥儿"},
[421] = {"证明你的价值","瑟伯切尔的达拉尔·道恩维沃尔要求你杀死5只月怒白头狼人。","希尔瓦娜斯主人已经授命瓦里玛萨斯大人全权负责征服南方的人类和矮人的领土。但阿鲁高那个蠢货——过去他是达拉然的大骗子，现在他是影牙城堡里一只中了诅咒的困兽——他那不计后果的魔法给银松森林里那座极具战略意义的要塞带来了一场大浩劫。我需要一些拥有优秀战斗技巧的人帮我把阿鲁高留下的烂摊子给收拾掉。杀死5只月怒白头狼人以证明你的实力吧，这些野兽一般都在山脚下的道路两旁游荡。","小武哥儿"},
[422] = {"阿鲁高的愚行","为瑟伯切尔的达拉尔·道恩维沃尔找回《阿鲁高的拯救》。","阿鲁高这样一个施法能力比一张纸还要浅薄的家伙居然能够得到肯瑞托的承认，这让我实在难以想像。现在最重要的是，搞清楚阿鲁高究竟使用了什么魔法，这样一来我才能对付他，并为黑暗女士平定银松森林。阿鲁高曾经住在桥北的麦田旁，一名亡灵哨兵回报说，他发现了阿鲁高拥有的几本法术书，但无法偷取它们。把其中一本名叫《阿鲁高的拯救》的法术书从其它书里找出来，并带回来给我。","小武哥儿"},
[423] = {"阿鲁高的愚行","给瑟伯切尔的达拉尔·道恩维沃尔带回6副暴食者镣铐和3副魔魂镣铐。","在我研究过阿鲁高的书以后，我最坏的设想不幸被证实了。肯瑞托竟在那个连给达拉然的法师们扫屋子都不配的家伙干出那种愚昧行径的时候完全不闻不问，一群蠢货！阿鲁高使用了附有魔法的物品来加强他薄弱的施法能力。我需要尽快研究一下这些物品。去杀掉一些月怒暴食者和月怒魔魂狼人，收集他们身上带着的魔法镣铐供我研究之用。这些污秽的生物在北边和东边到处都是。","小武哥儿"},
[424] = {"阿鲁高的愚行","杀死白毛狼人格瑞姆森，把他的头带给瑟伯切尔的达拉尔·道恩维沃尔。","看来想揭开隐藏在阿鲁高所用的巫术中的黑暗秘密并不简单，这比我想像中要花掉的时间多出很多。但与此同时，我需要你来帮忙处理一下我们的亡灵哨兵发现的一个小问题。似乎阿鲁高的魔法已经控制了东南方山中的埃利姆矿洞。这座矿洞对瓦里玛萨斯大人的推进有着非常重要的意义。我希望你能干掉矿洞里的工头，白毛狼人格瑞姆森。只要他一死，矿洞就是我们的了。","小武哥儿"},
[425] = {"邪恶的伊瓦","杀死邪恶的伊瓦，并将伊瓦的头颅带给伊瓦农庄的兰妮·尤瑞克。","我正在和哥哥奎恩执行侦察银松森林的任务，并准备向最高执行官哈德瑞克复命。但我们进行得不太顺利——我们穿过这座农庄的时候，被食尸鬼伊瓦袭击了。我们从伊瓦那里逃了出来，但他还是重创了奎恩。喝了你给他的药水以后，哥哥正逐渐痊愈，但这段时间里伊瓦仍可能会过来。杀死伊瓦，以保证奎恩有足够的时间复原吧。伊瓦一般都躲在谷仓那里，在我放松警戒的时候它就会开始行动。","小武哥儿"},
[426] = {"磨坊告急","收集5根锯齿肋骨和3个焦黑的颅骨，然后向布瑞尔的亡灵卫兵迪林格尔回报。","天灾军团正试图在阿加曼德磨坊那边建立起一座前哨基地。如果他们得逞了，那么他们在提瑞斯法的军事行动将得到有利的支持。上头已经发话下来了，必须将磨坊那边的天灾军团势力全部清除干净。到磨坊那边去，从断骨士兵和碎颅士兵身上收集锯齿肋骨，再从暗眼骷髅法师身上收集焦黑的颅骨。你只需沿着道路一直向西走，过桥以后在第一个岔路口转向北就行了。当你看到风车的时候，战斗随时都会开始。","小武哥儿"},
[427] = {"与血色十字军的战争","布瑞尔的执行官塞加德要求你杀掉10名血色战士。","执行官阿伦大人提供给我们的文件中指出，我们将无法避免与那些卑劣的血色十字军进行一场战争。我们已经知道了他们穿越提瑞斯法林地所走的那条小径的确切位置。但亡灵卫兵还有其它艰巨的任务，巫妖王的军队正在夜色中逐渐壮大起来。我们需要一些像你这样的志愿者来把那群血色十字军送进坟墓。顺着镇外的道路向西走，穿过索利丹农场到废塔那里去，杀死10名血色十字军战士。以此来证明你有足够的能力为黑暗女王陛下服务。","小武哥儿"},
[428] = {"失踪的亡灵哨兵","找到亡灵哨兵兰妮·尤瑞克和奎恩·尤瑞克。","几周前，亡灵哨兵兰妮·尤瑞克和奎恩·尤瑞克被派遣到银松森林北部去执行一次侦察任务。可我们一直没有再得到他们的消息。也许他们已经成了天灾军团的牺牲品。当然，我仍然希望有人能去确认一下，你去找到这两名亡灵哨兵。他们最初的任务是去侦察银松森林北边的农场，你可以从那里开始搜索。","小武哥儿"},
[429] = {"荒野之心","收集6颗变色的狼心，把它们交给瑟伯切尔的药剂师伦弗利尔。","我的哥哥奎恩被食尸鬼伊瓦打成了重伤，我不知道在没有魔法帮助的情况下，他是否还能痊愈。尽管我不是一个药剂师，但我知道我们的药剂师能用变色的狼心制作治疗药水。帮我收集一些心脏并带给南边坟场的药剂师伦弗利尔，然后把做好的药水带回来。这附近和东边的玛尔丁果园之间有不少座狼在到处游荡。","小武哥儿"},
[430] = {"回到奎恩身旁","将奎恩的药水带给瑟伯切尔北方伊瓦农场的奎恩·尤瑞克。","这就是那种能帮助奎恩·尤瑞克复原的药水。现在，如果你没什么事的话，我就先失陪了。我还有重要的工作要继续……","小武哥儿"},
[431] = {"诱灵蜡烛","","","小武哥儿"},
[432] = {"该死的石颚怪！","在古博拉采掘场里替工头乔尼·石眉杀死6个石颚击颅者。","那些该死的石颚怪，它们把我的工作地点变成了一片废墟！看那里，又一个火药桶！啊啊啊啊啊，我真想钻到地底下去扭断它们那豆芽一样的脖子！我要把它们赶尽杀绝！即使这样也无法消除我的愤怒……它们留给了我什么？什么也没有！我要亲手杀了它们，不过我的胳膊已经不再那么有力了！到采石场去，干掉那帮该死的家伙！我会奖赏你的！只要你去干掉它们！","小武哥儿"},
[433] = {"公众之仆","在古博拉采掘场里替参议员梅尔·圣石杀死10个石颚断骨者。","作为参议院与探险者协会的成员，我已经开始过问这个地区石颚怪泛滥的事情了。它们把古博拉采掘场搞了个天翻地覆，而且它们的这种行为看起来毫无理由。当我们在矿井中挖掘矿石的时候，它们突然出现，毁坏了我们的设备，赶走了我们的矿工。我们别无选择，只有杀光他们，之后我们才能重建工地并继续工作。如果你愿意帮助我解决掉那些石颚怪的话，我会很乐意报答你的。","小武哥儿"},
[434] = {"伏击！","等待葛瑞格·莱斯科瓦公爵和沉默之刃马尔松在花园里的对话结束，杀死他们两个，之后向暴风城的提亚斯回报。","等我做好间谍机器人的伪装，他会进去和莱斯科瓦谈话。守卫会让他进去的。在你帮我准备材料的同时，我会暗示马尔松，让他再次和莱斯科瓦会面，我甚至会给他一点假消息，好让他对此深信不疑。接下来，莱斯科瓦就会让他的卫兵解散，然后在花园里等马尔松。等你听到他们谈起迪菲亚兄弟会的时候就采取行动。你要把他们两个都干掉。听懂了吗？当你完成任务之后，尽快向提亚斯回报。","小武哥儿"},
[435] = {"护送埃兰德","护送亡灵哨兵埃兰德避过群狼，直到他找到兰妮·尤瑞克。","外面的狼群看来是不想离开了，而且我每次走出屋子的时候，它们都恶狠狠地盯着我。这些野狼显然是饿极了，它们把我当成了大餐！我得通知我的队友，亡灵哨兵兰妮·尤瑞克。也就是说，我要到她那里去，得先找人帮我搞定这群狼。请护送我吧！不过，这边的狼也实在是多了点，如果你还有别的朋友的话…再好不过……","小武哥儿"},
[436] = {"铁环挖掘场","和麦格玛尔·落斧谈一谈。","勘察员基恩萨·铁环正在负责挖掘洛克湖东边的一座古老的废墟。虽然我们已经给他送去了不少物资，但是他那里最近进展非常缓慢。基恩萨·铁环是一个顽强、诚实而精干的矮人，没理由会如此懈怠，所以我担心他那儿出了什么问题。到铁环挖掘场去问问麦格玛尔·落斧，他负责挖掘场的琐事，一定知道那里到底是怎么了。你要可以从湖的南端绕过去，然后一直向东走，就可以到挖掘场了。","小武哥儿"},
[437] = {"亡者农场","清剿亡者农场的腐皮豺狼人。当奈塔拉什出现时，把她也杀掉。将奈塔拉什的灵魂带给瑟伯切尔的高级执行官哈德瑞克。","我们在银松森林的探子回报说，腐皮豺狼人在北边的一处名叫亡者农场的地方建立了一个基地。我们已经派遣了小股突袭部队去对付他们，但每次他们都能得到女妖奈塔拉什的增援，每次都是她的魔法击溃了我们的部队。我们必须杀掉奈塔拉什。到亡者农场去杀掉那里的腐皮豺狼人。如果没有看到奈塔拉什的话，就继续屠杀腐皮豺狼人直到她出现为止，然后击败她。她的灵魂将会变成尘土。把这些尘土带回来，作为你杀死了她的证明。","小武哥儿"},
[438] = {"破旧渡口","到破旧渡口去，找到天灾军团占据那里的理由。","，我们最近发现了天灾军团的一个新据点：破旧渡口。这处渡口就在瑟伯切尔的东方，有许多腐皮豺狼人和其他亡灵层层守卫着那里。天灾军团占据了那里，这其中一定有些什么阴谋。到破旧渡口去调查一下，看看为什么天灾军团会在那里。","小武哥儿"},
[439] = {"线索","将黛丽娅的戒指带给瑟伯切尔的高级执行官哈德瑞克。","在一大堆尸体中间，有一只裸露的手。这是一只女人的手，虽因瘟疫而导致皮肤上布满红痘，但仍然十分白皙。她的手上戴着一只戒指。你从尸体的手上取下这只戒指，看到戒指内环中有一道铭文：“赠予黛丽娅”","小武哥儿"},
[440] = {"黛丽娅的戒指","将黛丽娅的戒指带给布瑞尔的执政官塞弗伦。","如果你想找到黛丽娅的丈夫或情人，也就是送给她戒指的那个人的话……去找布瑞尔的执政官塞弗伦谈谈吧。他或许拥有最近的死亡记录，当然，如果你走运的话，还能发现谁是黛丽娅。但我也不抱希望。无论给她戒指的人是谁，现在恐怕也已经死了。如果他成了亡灵，也就不会再关心黛丽娅了。","小武哥儿"},
[441] = {"拉林夫与幽暗城","把黛丽娅的戒指交给拉林夫。","黛丽娅有个丈夫叫拉林夫，他现在居住在幽暗城。如果居住在布瑞尔的这位黛丽娅就是这只戒指的主人，想必他应该知道。拉林夫就在幽暗城的贸易区。","小武哥儿"},
[442] = {"突袭芬里斯岛","将图勒的头颅带回给瑟伯切尔的高级执行官哈德瑞克。","现在是把天灾军团彻底赶出银松森林的时候了。你必须再去一次那个岛，杀死图勒·鸦爪，把他的头颅提来见我！这个任务非常危险，但是你也应该知道它的重要性，。所以你只能成功，不能失败。","小武哥儿"},
[443] = {"腐皮豺狼人的脓液","给瑟伯切尔的药剂师伦弗利尔带去8瓶腐皮豺狼人的脓液。","在我们对芬里斯岛展开一次突袭行动之前，我们必须得弄清楚谁是腐皮豺狼人背后的真正主人，我们的药剂师们相信它们的体内发生了某种神秘的变化。到破旧渡口东边的芬里斯岛去，收集一些腐皮豺狼人身上流出的脓血，然后把脓液交给瑟伯切尔外的药剂师伦弗利尔。","小武哥儿"},
[444] = {"腐皮豺狼人的产生","将脓液样本交给幽暗城的比索·埃斯沙德。","我还原了你带给我的脓液，并把它们分离成了一些基本成分。我的发现还不是结论性的，但我可以肯定恶魔法术和死灵法术在这脓液的产生过程中起了极其重要的作用。在我继续研究脓液的同时，我希望你能给幽暗城的比索·埃斯沙德带些样本过去。比索虽然不是一名药剂师，但他在魔法方面的学识将会帮助我们揭开这些腐皮豺狼人的秘密。快去吧，比索就住在幽暗城的法师区。","小武哥儿"},
[445] = {"给银松森林送信","将药剂师乔汉的研究成果带给银松森林的药剂师伦弗利尔。","如今，对我们这些希尔瓦娜斯女士的仆从来说，时间就是一切。显然现在你也非常清楚这一点。身为皇家药剂师学会的一员，我必须将我的研究成果与同事们分享，只有依靠所有会员的共同努力，我们才能向黑暗女王陛下提供她最期望的新瘟疫。将这些报告带给住在银松森林瑟伯切尔里的药剂师伦弗利尔，从布瑞尔向南走，到了幽暗城再转往西南就可以了。","小武哥儿"},
[446] = {"图勒·鸦爪","把比索的卷轴交给银松森林中的药剂师伦弗利尔。","这种脓液是我以前的一个同僚图勒·鸦爪制成的。在大战之前，他是一个有着大好前途的年轻法师，但在巫妖王的势力崛起之后，他背叛了他的朋友与兄弟，加入了天灾军团。我没料到他还活着，更没有想到的是，原来是他在领导腐皮豺狼人与我们对抗。我对他的许多法术都有所了解，应该能帮忙调制出一种能击败他们的药剂。把这个卷轴交给药剂师伦弗利尔，卷轴上面写着调制药水所需要的咒语。","小武哥儿"},
[447] = {"致命的配方","收集6个灰熊的心脏和6份粘稠的血液样本，并将这些东西送给幽暗城的大药剂师法拉尼尔。","阿尔萨斯的手下越来越多。不过，只要再来一次新的瘟疫，我们就可以一劳永逸地同时根除天灾军团和人类。我的研究已经证明，将灰熊心脏中提取出的毒素和蜘蛛血混合在一起，就可以制成一种致命的毒药。从西北方的粘丝洞中的蜘蛛身上和银松森林中游荡着的熊身上采集一些样本回来，然后把它们送给幽暗城皇家药剂师学会里的大药剂师法拉尼尔。","小武哥儿"},
[448] = {"给哈德瑞克的报告","向瑟伯切尔的高级执行官哈德瑞克复命。","在你展开对芬里斯岛的攻击之前，先向高级执行官哈德瑞克复命吧。他或许还有些额外的装备或者情报要给你。","小武哥儿"},
[449] = {"亡灵哨兵的报告","将亡灵哨兵的报告的报告交给瑟伯切尔的高级执行官哈德瑞克。","尽管奎恩的伤基本已经好了，但我仍想尽可能快地把报告呈送给高级执行官哈德瑞克。这里面的情报对被遗忘者来说十分重要，它将关系到我们在整个银松森林的统治地位。","小武哥儿"},
[450] = {"致命的配方","从焚木村的旅店中找到伯纳德的日记，把它交给瑟伯切尔的药剂师伦弗利尔。","其实你还能为皇家药剂师学会再做一些事情，。当初阿鲁高在整个森林中施展了他那可恶的魔法时，我们当中一位最有前途的成员——药剂师博拉尔德，也被他诅咒了。现在博拉尔德已经变成了一个忠于阿鲁高的傀儡，换句话说，他对我们已经彻底没用了。但是他的研究成果可能对我们非常有用，因为他在多年以前曾经研究过一种杀死了洛丹米尔湖中所有生物的瘟疫。将伯纳德的日记从他在焚木村旅店中的研究室里偷出来，然后把日记交给药剂师伦弗利尔。","小武哥儿"},
[451] = {"致命的配方","收集6份湖岸爬行者苔藓的样本、6份湖岸潜藏者苔藓的样本和1块硬瘤，把它们交给幽暗城的大药剂师法拉尼尔。","根据博拉尔德的研究日记，采自湖岸爬行者和潜藏者身上的苔藓会对我们制造出这种瘟疫大有助益。这些野兽就栖息于东边的洛丹米尔湖中的群岛上。他还提到曾在一只邪鳍鱼人身上发现了一种非常稀有的硬瘤，显然这种瘤很难得到，博拉尔德也只找到了一个。收集一些苔藓和那种稀有的瘤，把它们带给幽暗城的大药剂师法拉尼尔。","小武哥儿"},
[452] = {"焚木村中的伏击","帮助亡灵哨兵费雷亚消灭焚木村议会。","你来得正好，！焚木村议会随时都有可能回来，而阿鲁高此时正好无暇顾及这里。他利用议会作为傀儡控制着焚木村中无知的村民们，我相信如果没有议会的引导，阿鲁高的奴隶们一定会反戈一击，背叛他们的主人。我无法独自应付他们所有人。我需要你的帮助，只要齐心协力，我们一定能为希尔瓦娜斯主人消灭焚木村议会。","小武哥儿"},
[453] = {"搜寻乌鸦岭","找到那个模糊的人影。你的线索：他不是夜色镇的本地人。他是个紧张而敏感的人。他离开夜色镇往西边去了。","祝你好运，。我希望你能找到这个家伙，也希望他还活着。外面可没有夜色镇这么安全，他可能早就成了野兽的猎物。","小武哥儿"},
[454] = {"恶战之后","和米兰谈一谈。","在这事之前，我们一直在来来回回拖着这几个装着火药的桶往挖掘场运。现在我们得分工一下，米兰负责搬这些桶，我负责搬其它的。不过让米兰一个人运送剩下的货物我多少有点不放心，你能不能在他下次送货的时候护送他一程呢？","小武哥儿"},
[455] = {"丹奥加兹告急","翻越丹奥加兹。杀死8个龙喉斥候和6个龙喉步兵。向米奈希尔港的瓦斯塔格·铁颚报到。","龙喉氏族的兽人在湿地有了一处巢穴，现在他们的势力已经快扩展到丹奥加斯了！我们可绝不能让他们在这里立足，不然，我们在湿地唯一的港口与要塞——米奈希尔港与洛克莫丹的联系将会被切断。穿越丹奥加兹到湿地那边去，向米奈希尔港的瓦斯塔格·铁颚报到，路上顺便杀它几个兽人玩玩！米奈希尔就在丹奥加兹的另一边，只要先顺着路向北，然后在岔路口转向西边就是。我们寄希望于你，。可别让我们失望。","小武哥儿"},
[456] = {"自然的平衡","杀死7只夜刃豹幼崽和4只草刺野猪幼崽，然后向管理员伊尔萨莱恩复命。","你好，。我是管理员伊尔萨莱恩。我的职责是维护幽影谷一带的自然平衡。今年的春雨似乎比往年来得都要连绵不绝，这导致了森林中某些动物的过度繁殖，而其它动物就遭了殃。其中，夜刃豹和草刺野猪的族群已经过于庞大了，幽影谷无法为它们提供更多的食物。去吧，年轻的<职业>，去减少野猪和夜刃豹的数量，以保证自然的和谐。","小武哥儿"},
[457] = {"自然的平衡","管理员伊尔萨莱恩要求你杀死7只癞皮夜刃豹和7只草刺野猪。","削减幽影谷地中生物幼兽的数量是一个很好的开始，，但这还远远不够。如果问题不能得到根本解决的话，森林中的资源还是很快就会被耗尽的。杀死某些生物对于生长在这片土地上的所有生物来说都是有益的。为了自然的平衡，到森林里去清除一些癞皮夜刃豹和一些草刺野猪吧。","小武哥儿"},
[458] = {"森林守护者","找到树妖塔琳德拉。","谢天谢地你在这儿，<职业>。森林中的小精灵们告诉了我一些奇怪的消息。神秘的森林守护者塔琳德拉又回到了幽影谷。这位树妖的身影已经许多年都没有在卡利姆多大陆上的森林中出现过了。她既然回到了这里，就意味着这里一定出了什么事情。找到了塔琳德拉，并且问问她我们的森林到底怎么了。有个哨兵向我报告过，塔林德拉曾在奥达希尔的西边出现过。","小武哥儿"},
[459] = {"森林守护者","收集8块魔苔，把它们交给塔琳德拉。","一些邪恶的事物正在泰达希尔的森林中滋生着。看看那些原先性情温和的熊怪们居住的地方吧。他们放弃了自己的家园，聚集在了所谓的脊骨部落的名下。一定是那些腐朽毒恶的魔苔的瘴气造成了这种变异。小劣魔和劣魔也在幽影谷滋生开来，惊扰着这里的居民。去和这些小劣魔和劣魔战斗吧，，观察一下他们是否真的是受了魔苔的影响。","小武哥儿"},
[460] = {"支离破碎","将奥拉瑞克的头颅带到他的坟墓旁。","你看上去跟那帮腐皮豺狼人不一样，这真好。我都快绝望了……我叫奥拉瑞克，过去曾是图勒的大管家兼保镖。他用他的魔法“保护”了我，使我免受“亡灵瘟疫”的影响，但他的魔法也让我变成了这个半死不活的样子。而且，自从图勒创造了那群该死的腐皮豺狼人之后，他竟然砍了我的头……还把我的头给那群豺狼人当球踢！拜托，把我带到我的身体那儿去。那群豺狼人大概是把它埋在了芬里斯城堡的马厩旁……","小武哥儿"},
[461] = {"密室","将奥拉瑞克带到密室去。","我知道在这城堡中有间密室，密室里藏着一件对图勒和他的同伙们来说很宝贵的东西，也许那里面也有些对你很有用的东西。把我带到那里去！这密室就在城堡西南的塔里，在一处满是灰尘的柜子后面。带上我的身子，但是不要靴子…这靴子就没合适过……","小武哥儿"},
[462] = {"暂无内容","杀掉马鲁克·龙鳞。然后向米奈希尔港的瓦斯塔格·铁颚报告。","除了你之外，我还派了两个斥候去奥加兹，但是只有一个斥候回来了。以下是他带回来的情报:龙喉氏族的一个中尉马鲁克·龙鳞组织了一支兽人部队集结在奥加兹，从而切断了那里和米奈希尔港之间的通道！我们必须阻止他们。干掉马鲁克，然后向米奈希尔港的瓦斯塔格·铁颚回报。马鲁克的老巢在一个小山洞里，穿过奥加兹隘口第二和第三条通道之间的水塘就可以找到它。在你穿过奥加兹之后，沿着路一直往西走就能到达米奈希尔港了。","小武哥儿"},
[463] = {"绿色守卫者","找到绿色守卫者。","你听说过绿色守卫者？你应该不是在找他吧，是不是？如果是的话，我真得说你是个疯子，不过我为什么要阻止一个疯子去找他送死呢？好吧，如果你真是在找那只凶兽的话，我听说它就在沼泽里，在通向丹莫罗的那个岔路口的东边。他就潜伏在那个危险的地方，在鳄鱼群之间……听说那里还有些更可怕的东西！把你的钱留在这里吧，要是你去找他，钱对你来说也就没用……你该不会想在那家伙咬你的时候用你的金币给他镶金牙吧？","小武哥儿"},
[464] = {"龙喉战旗","给斯托菲队长带回8面龙喉战旗。","按理说，龙喉氏族的兽人应该已经在第二次兽人战争中全部被消灭干净了呀。那时，他们失去了对红龙的控制，而被奴役了许久的红龙对兽人极度仇恨，所以就到处猎杀他们。只有一小部分龙喉兽人从格瑞姆巴托逃了出来，躲进了维尔加挖掘场东边的山里。现在他们的族群似乎又恢复了兴盛，有线报说他们在米奈希尔的东北方建立了一座营地。我们要你去进攻那座营地，并带回一些战旗作为功勋评定的证据。","小武哥儿"},
[465] = {"古耶克的阴谋", "摧毁龙喉氏族的投石车。", "在你与龙喉兽人交战时，我们发现了更糟的情况——古耶克建造了投石车，打算围攻米奈希尔港！而丹奥加兹通道的战斗又阻断了我们的增援路线！必须摧毁那些投石车，它们就在龙喉营地。带上这些火绒，杀到投石车旁点燃它们。完事后找到并杀死古耶克。我们要斩断这条龙喉毒蛇的头颅！", "小武哥儿"},
[466] = {"火岩矿石","给丹莫罗的驾驶员迪恩·石轮带回6份火岩矿石。","我听说最近在湿地一带发现了一种特别稀有的矿石，大家管它叫火岩，那矿洞就在奥加兹大门西北方的一处洞穴里。火岩矿石非常不稳定，它很容易爆炸，但我敢说，如果加工方法正确的话，它就可以用来制作威力强大的炮弹！给我搞一些火岩矿石的样本来，我可以去找个够胆的家伙来对它进行实验。哦，要想采集到这些矿石的话，你可得懂点采矿技术才行。如果你完全不懂的话，那么……就找个懂行的朋友一起去吧！","小武哥儿"},
[467] = {"迪恩·石轮的梦想","和驾驶员迪恩·石轮谈一谈。","驾驶员迪恩·石轮和其他驾驶员一样非常喜欢他的攻城坦克，他一直都想要找到加强坦克火力的方法！他听说有一种罕见的矿石，现在正在到处拉人为他寻找这种矿石呢。如果你想找点事干的话，就去丹莫罗的钢架补给站找他，看看他都需要些什么。","小武哥儿"},
[468] = {"向巡山人罗克加报告","与巡山人罗克加谈一谈。","巡山人罗克加正在招募一些能穿越丹奥加兹到湿地去执行任务的志愿者。如果你想去北边感受一下鞋子里灌满水的感觉，那就到丹奥加兹去找罗克加谈谈吧。沿着道路向北，走过哨塔就到丹奥加兹了。","小武哥儿"},
[469] = {"日常供货","将这捆鳄鱼皮带给米奈希尔港的皮匠詹姆斯·哈洛兰。","你好，旅行者！你是不是要去米奈希尔港？如果不是的话，我建议你就留在这里吧，你要是想买点东西啊，喝一杯啊，或者放松放松神经什么的话，这里就再合适不过啦。如果你确实是要去米奈希尔的话，那么……我想……你应该不会介意把这捆鳄鱼皮捎给皮匠詹姆斯·哈洛兰吧？我本来是想自己亲自走一趟的，但我那个在城里的老婆最近正发脾气呢，我实在不想马上就见到她，能拖多久就拖多久。","小武哥儿"},
[470] = {"搜寻软泥怪","铁须之墓中的某只软泥怪身上有塞达的背包，夺回背包，把它送还给米奈希望港的塞达。","我每周都要对西北方山脚下的铁须之墓进行例行的拜访。然而，上次过去的时候，我竟然遭到了那些可怖的软泥怪的攻击，我当时自然是吓坏了。我身上也没带武器，只好抓起背包丢它们，不过那完全没有用！软泥怪很轻松地把我的背包给吞掉了……不过，幸运的是，这也为我争取到了逃跑的时间。但是我现在很需要包里的东西！我已经忘记把包扔进哪只软泥怪里了，它们看起来都是一模一样的！所以呢，你恐怕得多杀个几只才能找到我的包。铁须之墓就在东北方，丹奥加斯附近。多谢你啦！","小武哥儿"},
[471] = {"学徒的职责","为米奈希尔港的詹姆斯·哈洛兰带回6张巨型鳄鱼的皮。","我把我的学徒派到了沼泽那边去，希望他能给我搞到一些著名的巨型鳄鱼的皮回来。然而他一直都没回来，我只好亲自去找他……怎么说呢，反正我当时看到了一些比较惨的场面。医生说他很快就会恢复健康的，但现在，我仍然急需鳄鱼皮！……要是你能帮我杀几条这种凶猛残忍的大鳄鱼，从它们身上给我剥几张皮下来，我会非常高兴的。沿着海岸北上，走过了那些鱼人搭建的简陋小屋之后就能找到鳄鱼了。","小武哥儿"},
[472] = {"丹莫德的陷落","在丹莫德镇附近寻找布莱德·长须的踪迹。","丹莫德已经被黑铁矮人攻陷了！我伤得很重，<职业>。我们的大多数战友都已经牺牲了！我们在萨多尔桥遭遇了伏击，正在重整部队的时候，那群该死的黑铁矮人再度突袭了我们。我们的领袖布莱德·长须被迫吹响了撤退的号角。我们刚一离开镇子，我就被人从背后砍了一斧子，然后就眼前一黑昏死了过去。当我醒来的时候已经身在米奈希尔了，但是，我现在很担心我手下的士兵们。我依然保有一丝希望，也许布莱德·长须还活着！看看你能不能在丹莫德附近找到他吧，<职业>！","小武哥儿"},
[473] = {"向斯托菲队长报告","与斯托菲队长谈一谈。","，龙喉氏族的兽人们一天天地壮大了起来，这样下去它们迟早会攻破奥加兹的。斯托菲队长正在诚招志士来对抗那些兽人，他就在城堡里面的指挥室中。","小武哥儿"},
[474] = {"击杀古耶克", "杀死古耶克将军*将古耶克的首级带给斯塔费斯特上尉。", "现在投石车已被焚毁，是时候找到并解决古耶克将军了。", "小武哥儿"},
[475] = {"烦恼之风","在星风村找到盖洛拉斯·塔文斯伦。","一阵令人烦恼的微风吹过了森林。盖洛拉斯·塔文斯伦一直负责为那些在班奈希尔兽穴中休眠的猛禽德鲁伊们放哨。作为沉睡者们的保护者，他的职责是确保德鲁伊们的安全，从而使他们可以履行与伊瑟拉定下的契约。但是我很久都没有收到盖洛拉斯的消息，现在我已经越来越紧张了。到东边的星风村去一趟，帮我把盖洛拉斯的报告带回来，这样会让我心里轻松一些。","小武哥儿"},
[476] = {"瘤背熊怪的堕落","返回多兰纳尔去见阿斯瑞达斯·熊皮。","瘤背氏族的熊怪已经堕落了！曾经爱好和平的熊怪现在转而与森林的保护者为敌。我刚刚动身准备去班奈希尔兽穴的时候就遭到了它们的伏击，而熊怪们现在还准备掠夺星风村！它们的首领——大槌乌萨尔——正在运用魔苔的邪恶力量使它们变得更加疯狂。我伤得太重了，无法返回去把这个十万火急的消息告诉阿斯瑞达斯。这个任务就交给你了，年轻的<职业>。我们只能希望疯狂的瘤背熊怪还没有对班奈希尔下手！","小武哥儿"},
[477] = {"越境","从达拉然法师的木箱中拿出里面的东西。","你也许知道，安伯米尔镇里还有一群人类在负隅顽抗，事实上，这主要是因为达拉然的法师们在支援着他们。我不知道他们到底有什么计划，不过我想，既然他们对这样一个偏僻的小镇表现出如此浓厚的兴趣，那么这个地方一定有什么还不为我们所知的重要意义。法师们隔三差五地用马车把一些木箱从希尔斯布莱德运到安伯米尔去，他们补给线的终点就在焚木村北面的一处营地里。帮我把木箱里的东西拿来一些，让我好好研究一下。","小武哥儿"},
[478] = {"地图与符记","将这个奇怪的坠饰交给瑟伯切尔的暗影牧师奥利斯特。","<你迅速从箱子里中拿起了坠饰并将箱子重新盖好。>","小武哥儿"},
[479] = {"调查安伯米尔","为瑟伯切尔的暗影牧师奥利斯特抢到8个达拉然坠饰。","达拉尔正在尝试着定位出达拉然法师们施法时的能量流向。现在，我们必须要尽我们一切努力来暂缓他们的进程……那些咒术师、法师和保卫者恐怕会拚死保护坠饰。你必须清除掉这些阻碍，并把饰物抢到手。沿着大路向南走，在岔路口转向东边就可以到安伯米尔了。","小武哥儿"},
[480] = {"法师的头领","杀死达拉然大法师，并把他的法杖交给瑟伯切尔的暗影牧师奥利斯特。","一位具有强大法力的大法师正在监管着启动节点的行动。在目前的形势下，我们只有杀死那个大法师才有可能阻止他们了。这将是个艰巨的任务，无疑会有许多法师与守卫层层护卫着他。你必须出发了，尽快结果掉他。大法师死了以后，把他的法杖带回来给我。现在就去，快！","小武哥儿"},
[481] = {"达拉尔的推理","把刻有符文的坠饰交给瑟伯切尔的达拉尔·道恩维沃尔。","把这个饰物交给达拉尔·道恩维沃尔，或许他能从中发现一些蛛丝马迹。","小武哥儿"},
[482] = {"达拉然的意图","与瑟伯切尔的暗影牧师奥利斯特谈一谈。","啊！我想起来了！安伯米尔一直是为肯瑞托所关注的地方，因为那里隐藏着一个能量节点。那群法师们一定计划启动节点，并使用里面蕴涵着的能量来为他们更深一层的目的服务。我们不能允许这样的事情发生……启动节点需要花费大量的魔法能量，只要我们把这些坠饰抢走，达拉然的法师们就无法继续他们的行动了。把这件事告诉奥利斯特，他会制定出行动计划的。","小武哥儿"},
[483] = {"唤醒圣物","找回四件唤醒圣物，把它们交给多兰纳尔的阿斯瑞达斯·熊皮。","瘤背氏族的熊怪正在西边的班奈希尔兽穴里肆虐。除非我们伸出援手，否则那些正在沉睡的德鲁伊将永久地陷于翡翠梦境中，对即将降临的噩运浑然不觉。只有拿到所有的唤醒圣物，我们才能将休眠仪式打断。到兽穴里去帮我找回鸦爪神符、黑色羽毛、天蓝之石和筑巢符文。德鲁伊们把这些圣物藏在神圣的盒子里，把它们带给我，我要准备进行唤醒仪式。","小武哥儿"},
[484] = {"小鳄鱼皮","为米奈希尔港口的詹姆斯·哈洛兰带回4张小鳄鱼皮。","我是皮匠詹姆斯·哈洛兰。我用鳄鱼皮做东西的手艺可是艾泽拉斯第一流的，每天都有大船把我的产品一箱一箱地运到世界各地的港口去。你见过埃纳尔了吧？他也是专门为我提供新鲜鳄鱼皮的诸多猎人之一。最近我这里的小鳄鱼皮供应量在直线下降，鉴于目前我真的很缺货，如果你能帮我弄些小鳄鱼皮回来，我会给你开出一个非常不错的价码。你可以在镇外的沼泽里找到那种小鳄鱼。","小武哥儿"},
[485] = {"找到OOX-09/HL！","把定位器带到奥格索普的母体机器人那里去。奥格索普的母体机器人位于辛特兰的河水源头，就在藏身石的附近。","你发现了一个奇怪的蛋形金属物体。随便拨弄了几下之后，它居然自动打开了，变成了一个看来是由侏儒制造的机器装置！一个奇怪的声音从这个蛋形机器装置中传了出来。“我的名字叫奥格索普，我的母体机器人不见了！如果你能帮我找到它，我就会奖励你的！请把这个定向器带到那个母体机器人那里。别担心，我现在已经检测到了它的所在地！它现在就位于藏身石那一带的河水源头附近！”","小武哥儿"},
[486] = {"大槌乌萨尔","杀掉大槌乌萨尔，然后回到多兰纳尔的阿斯瑞达斯·熊皮那里。","现在我们必须去解救猛禽德鲁伊了。如果我们现在失败了，他们就将永远迷失于睡梦中。我将为苏醒仪式做好准备，不过为了进行这个仪式，就必须杀死造成现在这种混乱局面的罪魁祸首。只有到那时，仪式才能正常进行和完成。大槌乌萨尔把一切都搞得一团糟，现在只有让它为此付出代价，猛禽德鲁伊才能重获自由。到西南边的脊骨堡去杀了它！","小武哥儿"},
[487] = {"通往达纳苏斯之路", "将10个瘤背熊怪护符交给多兰纳尔外的哨兵阿玛拉·夜行者。", "必须确保通往达纳苏斯的道路安全。从多兰纳尔前往达纳苏斯的旅人不断报告遭到瘤背部落堕落熊怪的袭击。这条道路每日都承载着达纳苏斯重要的商贸与情报往来，决不能容忍这群野蛮之徒横行。以神圣森林之名拿起武器吧，冒险者。它们的巢穴就在这片高地下方某处。带回它们神圣的护符向我复命。", "小武哥儿"},
[488] = {"赛恩的要求","给多兰纳尔外面的赛恩·腐蹄带去3颗夜刃豹的牙齿、3根巨翼枭的羽毛和3份树林蜘蛛丝。","我知道你渴望工作，对你来说今天是个幸运的日子，因为我今天只能靠你这个乳臭未干的<职业>来帮忙了。你知道，，我可以使你非常幸福，我可以让你拥有你从未想过的好东西。但是首先，你必须给我带些东西来。我在森林里的工作需要一些材料……给我拿来三颗夜刃豹的牙齿、三根巨翼枭的羽毛和三份树林蜘蛛丝。","小武哥儿"},
[489] = {"寻求救赎！","收集3个魔锥果，把它们给在多兰纳尔外面的赛恩·腐蹄。","森林议会听说你帮助了赛恩·腐蹄，这个险恶的萨特是森林的敌人。作为一个<种族>，你应该更清楚我们不能杀害自然的生物，玷污圣洁的森林。如果你希望继续做泰达希尔的朋友的话，你就必须在众人的关注下挽回这个过错。给赛恩·腐蹄一个教训，你就可以得到原谅。魔锥果是从树上掉落的腐坏的种子，一般都冒着绿色的烟气。给赛恩带去3个魔锥果，他会以为那些只是无害的点心。","小武哥儿"},
[490] = {"<UNUSED>","Shayla Nightbreeze outside of Darnassus wants you to bring her 20 Gnarlpine Fangs.","By strict orders from the Council of Darnassus, I am commissioning a bounty on the Gnarlpine Tribe. They are no longer friends of the forest. Their corruption has left them mindless threats to our people and the creatures of the glade.As decreed by th","小武哥儿"},
[491] = {"给比索的魔杖","将狼人魔杖带给幽暗城法师区的比索·埃斯沙德。","图勒曾经告诉过我，很久以前，他和两名同僚利用各自手中的魔杖混合造出了一根新的魔杖。这根魔杖是友谊的象征。不过图勒虽然珍视他的友谊，但他却更珍视这件物品，并且不会允许自己与别人共同拥有这样一件宝物。所以他偷走了这支魔杖，将它藏在了芬里斯城堡。就是这个。将这个魔杖送给比索·埃斯沙德，许多年前他曾是图勒的好朋友。我相信他会需要的。","小武哥儿"},
[492] = {"新的瘟疫","将乔汉的特制饮料交给被俘虏的巡山人。","亡灵卫兵们说，他们又抓住了一个愚蠢的矮人巡山人。在对这个俘虏做出“妥善”处理之前，卫兵们似乎打算把他先关在恐惧之末旅店的地下室里。不如你帮我跑一趟，去看看这位可怜的俘虏喜欢不喜欢我为他特制的饮料吧。那饮料里只掺了一丁点黑暗女王想在整个艾泽拉斯大陆上使用的那种东西……","小武哥儿"},
[493] = {"前往希尔斯布莱德丘陵","将伦弗利尔的研究成果交给希尔斯布莱德山脚下塔伦米尔的药剂师林度恩。","为了给黑暗女士研究出一种新的瘟疫，皇家药剂师学会最近正承受着巨大的压力。当然，我们一直在努力工作并取得了突破性的进展。我们坚信，如果我们学会的成员彼此分享研究成果的话，进展将会更快。因此我要求你将这些我的最新发现送到塔伦米尔的药剂师林度恩那里去。塔伦米尔是一座位于希尔斯布莱德丘陵地带的小镇，这趟路程可能会很远。顺路一直向南走，记得看路标！","小武哥儿"},
[494] = {"进攻的时机","到塔伦米尔去，把亡灵哨兵莱什的口信带给高级执行官达萨利亚。","嘘！安静点，仔细听我说，<职业>。我被派到这个地方来监视希尔斯布莱德镇里的人类的动向，你必须把我的口信带给塔伦米尔的高级执行官达萨利亚，跟她说一句：“西边传来乌鸦的第三声叫声。”沿着大路往东走，注意看路标。快点！赶快去塔伦米尔，这件事情很紧急！","小武哥儿"},
[495] = {"意志之冠","到希尔斯布莱德丘陵去，向塔伦米尔的梅里萨拉报到。","希尔瓦娜斯殿下曾派出玛格萨尔和他的食人魔手下们前往奥特兰克去夺取意志之冠。然而，不幸的是，他们并没把它还回来，那个白痴竟然把它戴在了自己的头上……我猜这群食人魔恐怕对这种亮闪闪的东西没什么抵抗力吧。无论如何，他这种自作主张的行为已经酿成了大错。想必是意志之冠操控了他，令他背叛了希尔瓦娜斯殿下。黑暗女王陛下希望我们处理掉愚蠢的玛格萨尔，以此来警示其它不识时务的蠢货。到希尔斯布莱德丘陵的塔伦米尔镇去，向我的部下梅里萨拉报到。","小武哥儿"},
[496] = {"受难药剂","塔伦米尔的药剂师林度恩要你去收集10个灰熊的舌头和一些食苔蛛的毒液。","唉，又在塔伦米尔度过了倒霉的一天。这里的新鲜空气让我浑身都不舒服，。我们最好早点给这些人类下毒。我一直在仔细研究我的药物里可能用到的致命药剂。如果你想帮忙的话，就给我收集这些东西：10个灰熊的舌头，还有非常稀少罕见的食苔蛛的毒液。塔伦米尔周围到处都是熊和食苔蛛。","小武哥儿"},
[497] = {"<UNUSED>","Go to Tarren Mill and find out the status of the party sent by Thrall.","As a child, raised as a gladiator at Durnholde Keep, I was befriended by Taretha, the daughter of my wet nurse and mistress of the damned bastard Blackmoore.The past is the past, $n, but reports of human movements in Hillsbrad reminded me of that time","小武哥儿"},
[498] = {"拯救行动","塔伦米尔的克鲁斯克要你把德鲁尔和托格萨从敦霍尔德城堡救出来。","酋长派我和其他一些战士从敦霍尔德拿回一件东西，并调查这个所谓的辛迪加。我们到敦霍尔德去转了一圈，很惊讶地在那里看到了很多人类。我们勇敢地和他们战斗，不过他们在人数上占有绝对的优势。我们当中有些同伴被俘虏了，不过我逃了出来。敦霍尔德就在这里的东南部，过了河就是。德鲁尔和托格萨还被囚禁在那里，你得去把他们救回来。","小武哥儿"},
[499] = {"受难药剂","把受难药剂交给乌比。","我得花一会儿时间把这些成分混合在一起，做成受难药剂。成功了！啊，还有什么能比给这个世界带来点灾难更让人愉快的呢？让我们看看这种药剂能不能达到预期的效果。让我的助手乌比瞧瞧黑暗女王为人类和天灾军团准备了什么样的礼物。","小武哥儿"},
[500] = {"破碎岭食人魔","从奥特兰克山的破碎岭食人魔身上收集9个肮脏的指节骨，把它们带给南海镇的治安官雷德帕斯。","破碎岭食人魔在奥特兰克城废墟附近的山上挖了一座小丘。我的侦察兵告诉我，他们现在还占领了那片遗迹。我们可不能让他们在那儿享福，一旦他们觉得在那儿生活很安全，下一步就会转移到丘陵地带，然后就是我们南海镇了！到北方的奥特兰克山去猎杀几个食人魔。把他们那肮脏的指节骨带回来，我会给你奖赏的。","小武哥儿"},
[501] = {"痛苦药剂","收集10瓶山地狮的血液，把它们交给塔伦米尔的药剂师林度恩。","哦，……希尔斯布莱德的花都开了，空气这么清新，让我不得不沉湎在这种痛苦之中。我从肮脏的窗子里望出去，渴望着那一天早点到来，让整个世界都感染上新的瘟疫，让他们得到应有的报应。我喜欢整天坐在这里思考，而现在黑暗女王赋予我的使命正在召唤我，请你帮帮我吧。我的研究表明，山地狮的血液可以制作出最棒的毒酒来。给我找一点来，让我们做点有趣的事吧。","小武哥儿"},
[502] = {"痛苦药剂","把痛苦药剂喂给小狗斯坦雷。","啊，我最喜欢的就是在这丘陵地区弥漫的鲜血的气味！现在我们加点这个再加点那个，然后最有趣的事情就要发生了！我想把这瓶用血制成的药剂叫做痛苦药剂。如果我的计算正确的话，这个药剂肯定能给希尔瓦娜斯殿下带来不少好处。不过我们还需要做个实验才能确认这一点。把这瓶药剂拿到西南方的希尔斯布莱德农场，然后到那个地区北部的农庄里去，让我们看看农夫雷恩的小狗斯坦雷喜不喜欢这份“礼物”。","小武哥儿"},
[503] = {"高迪尔","救出高迪尔，然后回到塔伦米尔去见克鲁斯克。","从你拿到的文件来看，高迪尔被关在北边的一个辛迪加基地里，很有可能就在奥特兰克山。他已经被关押太久了，你必须尽快把他救出来。","小武哥儿"},
[504] = {"破碎岭好战者","杀死10个破碎岭好战者，然后回南海镇向治安官雷德帕斯报告。","你已经和破碎岭食人魔打过交道了，现在我要你去好好教训教训他们……到奥特兰克遗迹去猎杀那些破碎岭好战者。我希望你多干掉一些——只有这样才能让这帮畜生离联盟的领土远一点。","小武哥儿"},
[505] = {"辛迪加刺客","杀死12个辛迪加劫匪和8个辛迪加盗贼，然后回到南海镇向赫尼·马雷布镇长报到。","我是南海镇的新镇长，前一任镇长被刺杀之后，我刚刚上任。那些刺客一直都没有找到，不过据我们调查，几乎可以肯定他们是由辛迪加雇佣的——辛迪加是一个由邪恶的贵族掌管着的盗贼组织，而那些贵族则是已经陷落的奥特兰克王国的遗老遗少。根据我们最新的消息，辛迪加在由部落占据的小镇塔伦米尔的北方设有好几座营地，到那儿去杀掉那里的辛迪加成员。","小武哥儿"},
[506] = {"布莱克摩尔的余孽","把高迪尔收集的消息带给塔伦米尔的克鲁斯克。","一两天前，辛迪加的首领来找过我。他叫奥里登·匹瑞诺德，他声称自己是这片土地的领主。他向我吐露了他的计划，说要把反对他的那些兽人都变成奴隶，就像他的父亲和导师埃德拉斯·布莱克摩尔所计划的那样。更重要的是他还带着他的小情人，一个名叫艾丽萨的娇弱女孩。酋长想得到她脖子上带着的项链。现在你可以回去报信了，等手头上的事情忙完之后，我会自己回去的。","小武哥儿"},
[507] = {"奥里登·匹瑞诺德","杀了奥里登·匹瑞诺德领主，并从他的情人艾丽萨身上拿回塔蕾莎的项链。","匹瑞诺德一定要被除掉，这个卑鄙的家伙绝不能继续在这世上逍遥了。他的领地就在北边的洛丹米尔湖岸上。去完成这个任务，$n，别忘了把酋长想要的项链也拿到手，然后再回到这里来。","小武哥儿"},
[508] = {"塔蕾莎的礼物","把塔蕾莎的项链交还给塔伦米尔的克鲁斯克。","项链吗？当然可以给你……拿走它吧！我不想再跟他有什么瓜葛了……求求你，别杀我……","小武哥儿"},
[509] = {"苦楚药剂","收集6朵泥头花，把它们交给塔伦米尔的药剂师林度恩。","又是新的一天，又有一种新的药剂要配制。要我说，我宁愿让那些可怜的人类和天灾军团去互相拚命，他们就喜欢互相残杀。既然黑暗女王要加速这个过程，不如在这段恐怖的日子里再给这片土地加点死亡和疾病怎么样？我有个计划，，你现在到奈杉德哨岗去，那地方在塔伦米尔的南边，南海镇的东边。给我找6朵泥头花来让我配制药剂。","小武哥儿"},
[510] = {"预备行动计划","把预备行动计划带给南海镇的赫尼·马雷布镇长。","这些文件当中有一份物资清单，清单里包括各种日常物品（食物、武器、衣服）和其它工具（面具、油、毒药）。不过其中提到最重要的就是：尽快取得清单中的物资，为文件里所说的“针对南海镇的重要使命”进行准备。","小武哥儿"},
[511] = {"密文信件","把密码信交给南海镇的博学者迪布斯。","桌上有一封用密文写成的信，你根本没法读懂。","小武哥儿"},
[512] = {"贵族之死","为南海镇的赫尼·马雷布镇长收集7个奥特兰克徽记之戒。","我担心辛迪加的幕后首脑想要毁灭南海镇，因此我们必须在他们的计划得以实现之前干掉这些头目。你去北边奥特兰克山里的斯坦恩布莱德废墟调查一下，我们觉得那里是辛迪加的指挥部。我们知道这帮刺客是以前的奥特兰克贵族指使的，贵族们可能会打扮成普通辛迪加密探的样子，不过通过他们手上戴着的徽记之戒就能很容易地判断他们是不是贵族了。把他们的徽记之戒给我拿来。","小武哥儿"},
[513] = {"苦楚药剂","把泥头花药交给幽暗城的大药剂师法拉尼尔。","就在我觉得这一天又要无趣地打发掉的时候，你给我带来了这些泥头花。等我把它们混合在一起。我们还需要幽暗城的大药剂师法拉尼尔给药剂里加上他的腐蚀胶体，然后就等着看好戏吧！把这个泥头花药拿去交给大药剂师法拉尼尔，，现在就去。","小武哥儿"},
[514] = {"铁炉堡的译码者","把密码信带给铁炉堡的勘察员塔伯斯·雷矛。","我在铁炉堡有个同僚也许可以帮忙破译这封信。到铁炉堡的探险者联盟去找勘察员塔伯斯·雷矛谈一谈，告诉他是我让你去的，把这封信给他看。黑石塔以北如果还有人能读懂这封信的话，那一定就是他了。","小武哥儿"},
[515] = {"苦楚药剂","把泥头花水、1瓶强力巨魔之血药水、5块刺脊纳迦的鳞片和5颗碎鳍鱼人的眼球交给塔伦米尔的药剂师林度恩。","泥头花药？太棒了！我怎么就没想到过这个呢？让我给这种可怕的药剂里面加入我研制的腐蚀胶体。如果要激活泥头花水里的污染成分，林度恩就得先弄到强力巨魔之血药水，还有南海岸的刺脊纳迦的鳞片和碎鳍鱼人的眼球。你去找到这些试剂，林度恩会知道怎么处理它们的。天哪，我真想早点知道他的实验进行得怎么样了！","小武哥儿"},
[516] = {"博伦的巢穴","找到博伦的巢穴，杀死6名鸦爪苦工和6名鸦爪守护者，然后向瑟伯切尔的暗影牧师奥利斯特汇报。","我收到报告说，一群天灾军团的亡灵正在附近集结，准备对我们进行一次袭击。既然得到了这样的情报，我们就本应该先下手攻击他们，把他们的计划粉碎在襁褓中才对。但不幸的是，我的情报十分有限，只知道他们在一个名为博伦的巢穴的山洞里集结。确切的位置我也不清楚，但应该在安伯米尔附近的山区中。我相信以你的能力和才智，一定可以找到他们，干掉他们。","小武哥儿"},
[517] = {"苦楚药剂","将一桶矿工烈酒交给塔伦米尔的药剂师林度恩。","新药剂终于进入了实验阶段,不过为什么我们要把一种完美无缺、具有高度传染性的瘟疫浪费在一只青蛙或一条狗身上呢？让我们以希尔瓦娜斯大人的名义好好找点乐子吧。到丹加洛克去，你知道，就是到那些肮脏的小矮人出没的军营里去，给我偷一桶矿工烈酒出来，有了它，你我就可以开始狂欢了，。","小武哥儿"},
[518] = {"意志之冠","塔伦米尔的梅里萨拉要你去杀掉10个破碎岭虐待者。","玛格萨尔和他的破碎岭食人魔在奥特兰克废墟已经泛滥成灾了。不减少食人魔的数量的话，我们就很难去对付玛格萨尔。等他们的实力被削弱以后，我们就能继续前进了。懂了吗？好的。去吧。","小武哥儿"},
[519] = {"意志之冠","干掉塔尔格、玛克拉克和戈洛姆斯，把他们的头带给塔伦米尔的梅里萨拉。","塔尔格、玛克拉克和戈洛姆斯都是玛格萨尔的下属。我们不知道食人魔的忠心来源于什么，不过他们对玛格萨尔可是死心塌地。把他们的头给我带回来，$n，接下来就是砍掉玛格萨尔的脑袋，彻底瓦解那些食人魔。","小武哥儿"},
[520] = {"意志之冠","杀了玛格萨尔，带着他的脑袋和意志之冠去塔伦米尔见梅里萨拉。","玛格萨尔的下属都死了，剩下的就是杀掉玛格萨尔，取回意志之冠。他当然不想失去那顶王冠，所以我想你最好……首先将他周围的障碍都干掉。找到玛格萨尔，把他的脑袋和王冠一起带回来。破碎岭的抵抗就到此为止了。","小武哥儿"},
[521] = {"意志之冠","把意志之冠交给幽暗城的沙琳德拉。","剩下的任务就是把意志之冠交给幽暗城的沙琳德拉。她会派人送去给希尔瓦娜斯大人。我得警告你，别想把它留着自己用，玛格萨尔的死就是最好的例子。","小武哥儿"},
[522] = {"刺客的契约","把刺客的契约带给南海镇的赫尼·马雷布镇长。","这是一份刺杀赫尼·马雷布镇长的契约。合约已经封好，并用一个特殊的徽记之戒在红蜡上做了标记。","小武哥儿"},
[523] = {"男爵之死","把瓦杜斯男爵的头带给南海镇的赫尼·马雷布镇长。","你找到的契约是瓦杜斯男爵签署的，他是以前的奥特兰克王国的贵族，并且一向以冷酷和残暴而著称。这件事的背后由瓦杜斯这样的人主使，我对此一点也不感到奇怪。去找到他，让他受到正义的制裁。他一定在辛迪加经常出没的地方活动，也许在斯坦恩布莱德的废墟，也许在废墟北面的山谷里。","小武哥儿"},
[524] = {"苦楚药剂","把被污染的酒桶放在被俘农夫房间的地毯上。","隔壁的亡灵卫兵看守着几个被俘的人类农夫。高级执行官达萨利亚本来怀疑有一个暴风城来的军事顾问就藏在他们当中，不过我们昨晚发现那个可怜家伙的尸体就躺在瘟疫之地。因此，达萨利亚决定让我来处理这些没什么价值的战俘。我看是时候给这些农夫开个宴会了。这主意听上去真棒，就这么干！把这只被污染的酒桶放在他们房间的地毯上，给他们来一点带着瘟疫的酒！","小武哥儿"},
[525] = {"更大的谜团","把被破译的信件交给南海镇的赫尼·马雷布镇长。","我已经译出了这封信，不过还是不知道它是什么意思。你是在奥特兰克丘陵的盗贼身上找到这封信的吗？真奇怪……你应该把它拿去给南海镇的镇长看看。虽然这封信的含义不甚明了，但是南海镇离奥特兰克最近，如果有什么威胁正在临近的话，我想应该先告诉他。","小武哥儿"},
[526] = {"光铸铁锭","收集5块光铸铁锭，把它们交给湿地的戈罗林·钢眉。","你可能已经在那箱子里找到了一块光铸铁锭，但如果要打造些什么东西的话，这么一点铁是绝对不够的！你得再回去看看，没准在船只残骸附近的鱼人身上会有更多的光铸铁锭。","小武哥儿"},
[527] = {"希尔斯布莱德之战","杀掉6个希尔斯布莱德雇农和6个希尔斯布莱德农夫，还有农夫雷恩和农夫盖兹，然后返回塔伦米尔向达萨利亚报告。","和我说话的时候要立正，<职业>。我受瓦里玛萨斯的直接领导。在我们的药剂师研制出新型瘟疫之前，我们必须要压制住人类的攻势。有消息表明，希尔斯布莱德镇是个防守很薄弱的小镇。你的第一个任务是扰乱敌人的食品供给和基础设施建设。从这里往西边方向进发，你的目标是希尔斯布莱德平原最北边的农场，在那里大开杀戒的同时，别忘了把当地的农场主——农夫雷恩和农夫盖兹也给干掉。","小武哥儿"},
[528] = {"希尔斯布莱德之战","杀死15个希尔斯布莱德农民，然后回到塔伦米尔向达萨利亚汇报。","北方农场被袭击的消息让人类的村民们惊慌失措，你干得很出色。我们的哨兵报告说有农民向希尔斯布莱德南部逃散——这些傻瓜以为他们可以藏在果园里逃过一死。去结果他们吧，。回到希尔斯布莱德农场去，把这些东躲西藏的农民找出来，以黑暗女王的名义杀了他们。解散！","小武哥儿"},
[529] = {"希尔斯布莱德之战","杀掉铁匠维林坦和4个希尔斯布莱德见习铁匠，并从那里抢回一箱铁材，然后向塔伦米尔的达萨利亚汇报。","希尔斯布莱德的人类进行了顽强的抵抗，这实在有点出乎我的意料。问题的关键在于，有几个铁匠在为那些镇民提供武器，我们得切断他们的所有供给线。你的任务是干掉铁匠维林坦，还有他的那些学徒也得杀了。还有，把他们库存的铁也给抢回来。等我们征服了希尔斯布莱德并开始准备进攻南海镇的时候，这些物资就显得非常重要了。","小武哥儿"},
[530] = {"丈夫的复仇","杀掉瓦德雷·莫莱。把他的双手带给幽暗城的拉林夫·安迪恩。","瓦德雷曾经是我的好朋友，但他也是杀害我妻子的凶手。虽然我已经不知道悲伤为何物了，但我复仇的念头却一直没有改变。去帮我杀了瓦德雷，把他那双邪恶的手带给我，我会奖赏你的。我最后一次听到他的消息时，他正准备从银松森林南部的格雷迈恩之墙逃往吉尔尼斯王国。","小武哥儿"},
[531] = {"维林的报复","把奥尔苏迪的头交给旅行者营地的维林·疾风。","天哪！别把这种东西带到营地里来……它太肮脏，太可怕…太…太肮脏了！你把它拿出去行不行？没有人想看到你这件血淋淋的战利品！真的！","小武哥儿"},
[532] = {"希尔斯布莱德之战","杀掉波恩塞德镇长和4个希尔斯布莱德议员，摧毁《希尔斯布莱德宣言》，偷取希尔斯布莱德城镇文档，然后回到塔伦米尔向达萨利亚汇报。","希尔斯布莱德镇现在一片混乱，我们相信它很快就要被攻陷了。但是，我们必须继续坚持对敌人不断地发动攻击，直到把所有的人类渣滓都完全从这里赶出去为止。虽然人类损失惨重，但他们仍然团结在领袖的周围继续抵抗。我们得除掉他们的首领波恩塞德镇长，当然还有镇议会的成员。最后别忘了毁掉他们的政治文件《希尔斯布莱德宣言》，顺便把镇里的文档也都偷过来。","小武哥儿"},
[533] = {"秘密潜入","把关于高迪尔下落的消息带回来给塔伦米尔的克鲁斯克。","我们终于得到了关于高迪尔的线索。人类不停地到处转移他，但是我们已经缩小了搜索范围，现在我们的注意力主要集中在北边的那个辛迪加营地里。到那儿去打探一下，然后回来向我报告。","小武哥儿"},
[534] = {"<UNUSED>","","","小武哥儿"},
[535] = {"仆从瓦里克","给辛迪加营地里的瓦里克带去一杯南海镇烈酒。","呃……重病、濒死，而且还要与敌人作战。毫无疑问，你会杀了我，但如果你可以带给我些南海镇烈酒的话，我会告诉你所有你想知道的——我想你们<种族>平时也喜欢喝点什么吧，不是吗？","小武哥儿"},
[536] = {"清理海岸","南海镇的法尔林·奥里涅尔中尉要你去杀掉10个碎鳍潮行鱼人和10个碎鳍智者。","我从暴风城守卫被调到这个鸟不生蛋的南海镇来做守卫，这镇子简直是一无是处……整日整夜都是一股鱼腥味。更别提治安官雷德帕斯了……他还想要我去对付那帮鱼人，哈！我很难打起精神去跟西部海岸上的那群奇形怪状的鱼人作战。如果你愿意替我去干掉它们，我会很感激你的。","小武哥儿"},
[537] = {"黑暗议会", "杀死阿尔古斯暗影法师并带回一本他们的法术书，交给希尔斯布莱德丘陵南海镇的亨利·马勒布治安官。", "你带来的信件署名者自称纳迦兹，是阿尔古斯觉醒的成员。虽然不清楚这个组织来历，但既然他们与辛迪加勾结，就必然是威胁。去杀掉信中提到的阿尔古斯暗影法师，带回任何能揭示纳迦兹真面目的物品。他们可能在斯坦恩布莱德及其北面的高地活动。祝你好运能找到这些阿尔古斯觉醒的使者。", "小武哥儿"},
[538] = {"南海镇","与南海镇的博学者迪布斯交谈。","，如果你不介意多跑点路的话，我有件任务给你，好为我们的暴风城图书馆增加一些书籍。古代王国奥特兰克在大战之后就已经衰落了，但那里有着大量的藏书。奥特兰克的都城被毁实在是个悲剧，但如果他们的知识也失传了的话，那就将是个更大的悲剧！我们必须竭尽全力地挽救我们能挽救的东西。南海镇是最接近奥特兰克废墟的地方，到那里去找博学者迪布斯吧，他会告诉你在哪里可以找到书。","小武哥儿"},
[539] = {"希尔斯布莱德之战","杀死工头邦德斯和10个希尔斯布莱德矿工，然后回到塔伦米尔向达萨利亚汇报。","希尔斯布莱德城镇文档里的记录表明，碧玉矿洞已经处于联盟的控制之下——这个矿洞是联盟兵工厂运转所需的铁矿石的主要来源。虽然我们已经对希尔斯布莱德镇进行了致命的打击，但是联盟还是积极地支持和保护着碧玉矿洞。这个矿洞就在希尔斯布莱德的正南方。到那里去杀了他们的工头，一个名叫邦德斯的人类，顺便把那里的矿工也干掉。这样的行动可以给联盟传达一个足够清楚的讯息。","小武哥儿"},
[540] = {"保全书籍","把5本失而复得的书籍和包含《格里雷克之臂》的破旧的皮书带给南海镇的博学者迪布斯。","那些野蛮的食人魔现在就驻扎在奥特兰克废墟，一想起他们会把那里的书籍怎么样，我就感到毛骨悚然。你一定要尽力去完成我给你的任务！进入奥特兰克废墟，找到食人魔夺走的书籍。把你找到的所有东西都带给我，特别是这本书：《格里雷克之臂》。这本书里写着巨魔的古老学说，我一定要学。奥特兰克是完整保存这本书的唯一地方。","小武哥儿"},
[541] = {"希尔斯布莱德之战","到丹加洛克去杀掉8个巡山人、4个火枪手、2个牧师，还有达伦·铁山上尉，然后回到塔伦米尔向达萨利亚汇报。","矮人正在协助人类？这帮肮脏的小东西。我们得看看这所谓的联盟的实力到底如何。等这些矮子知道我们的厉害之后，看他们还愿不愿意继续给人类卖命！我们知道这些矮人的据点在哪里，他们在希尔斯布莱德东南部沿着索拉丁之墙的地方建立了一个被称作丹加洛克的军营。你的最终目标是攻占丹加洛克，<职业>。他们的首领达伦·铁山上尉必须得死。","小武哥儿"},
[542] = {"向米尔顿回复","把奥特兰克的书籍带给暴风城的米尔顿·西弗。","我得花点时间来研究你带回来的《格里雷克之臂》，不过我敢说米尔顿已经等不急要把你找回来的另一些书放到暴风城的图书馆里去了。这些就是你从奥特兰克废墟带回来的书，我已经按照目录分类整理过了。把它们带给暴风城的米尔顿·西弗，他一定会很感激你的。","小武哥儿"},
[543] = {"匹瑞诺德王冠","将匹瑞诺德王冠带给暴风城的雷明顿·瑞治维尔。","匹瑞诺德王冠据说是奥特兰克王国被毁灭之前的“名门望族”匹瑞诺德家族的传家之宝，有人说它是由铁炉堡的珠宝大师们用最美丽的翡翠制成的。当奥特兰克家族被毁灭的时候，王冠也随之遗失了。但有传闻说有一个食人魔法师——叫什么守财奴格雷尔伯格的家伙——得到了它，那家伙现在还在奥特兰克遗迹附近游荡，想要找到更多的财宝。我们希望你能为我们取回王冠。","小武哥儿"},
[544] = {"入室偷窃","找到被遗忘者的叛徒，取回他们偷走的神器，然后回到塔伦米尔去见大法师沃迪恩·伍德格莱尔。","我本来是到塔伦米尔来做研究的，不过现在我手头上有个麻烦一定要尽快解决掉。你知道，几个月前曾有四个被遗忘者从幽暗城逃了出来。他们抛弃了自己的同伴，这没什么，但问题是……他们偷了黑暗女王的东西。这些小偷闯入了一间秘密的地窖，偷走了四件供药剂师研究用的神器。黑暗女王命令我们把这四件神器找回来。小偷从幽暗城逃到了达拉然，而那些巫师则把他们收留在洛丹米尔收容所里。","小武哥儿"},
[545] = {"达拉然巡逻队","杀掉6个达拉然召唤师和12个元素奴仆，然后回到塔伦米尔去见大法师沃迪恩·伍德格莱尔。","达拉然的巫师在他们的城市中心建起一个巨大的魔法护罩。有人认为那是为了防止城市遭到攻击，还有人认为他们只是想有个安静的地方供他们进行魔法研究。不管那到底是什么原因，我关心的是在那个护罩之外的郊区废墟里是否藏着有用的魔法物品。不过那里有许多巫师和他们的元素奴仆在到处巡逻。去杀了他们，杀到你手软之后再回来吧。","小武哥儿"},
[546] = {"死亡的纪念品","塔伦米尔的亡灵卫兵沙穆萨想要30个希尔斯布莱德人类颅骨。","听说达萨利亚让你和希尔斯布莱德的人类作战，我很嫉妒你……你在外面享受屠杀人类、掠夺城镇、恐吓无辜者的快乐，而我却像木头一样待在塔伦米尔做守卫。你能可怜可怜像我这样的老亡灵卫兵吗？你知道我在收集人类的颅骨，正好你还要和人类战斗一段时间。那么，能不能在你作战的这段时间里顺便给我收集30个颅骨来？我会让你的努力物有所值的。","小武哥儿"},
[547] = {"亨伯特的长剑","从丹加洛克拿回亡灵卫兵亨伯特的长剑，然后回到塔伦米尔把剑还给他。","高级执行官达萨利亚派我从远处监视丹加洛克。我在一个隐蔽的角落里扎了营，但是那天早上我在烧水的时候离开了一会儿去找柴火……等我回来时，发现放在营地里的装备已经不见了。一定是那些丹加洛克的矮人侦察兵从这儿经过的时候把东西拿走了。我必须得拿回我的剑！如果你能帮我拿回来的话，我会很感激你的。但是那儿的矮人真是太多了……也许你很难在他们当中找出那个小偷。","小武哥儿"},
[548] = {"<NYI> <TXT> Bloodstone Pendant","","This will start the Bloodstone Pendant quest line……<NYI>","小武哥儿"},
[549] = {"通缉：辛迪加成员","杀死10个辛迪加盗贼和10个辛迪加哨兵，然后回到塔伦米尔向高级执行官达萨利亚报告。","经由黑暗女王希尔瓦娜斯授权，辛迪加组织的全部成员都将被处死！那些已经被羁押和俘虏的辛迪加成员必须立刻处决。残余的辛迪加成员目前在塔伦米尔东南部的敦霍尔德城堡废墟聚集。任何向高级执行官达萨利亚证明自己完成了这个任务的人都会受到重赏。","小武哥儿"},
[550] = {"希尔斯布莱德之战","把达萨利亚的奖状交给幽暗城的瓦里玛萨斯。","由于你在希尔斯布莱德战役中的英勇表现，我已经向上级写了这封褒奖状以表扬你。把这密封的奖状带给幽暗城的瓦里玛萨斯大人，你可以满怀骄傲地去见他，<职业>。","小武哥儿"},
[551] = {"附有魔法的羊皮纸","将这张附有魔法的羊皮纸带给南海镇的博学者迪布斯。","这张羊皮纸上被施加了某种咒语，使其无法被破译。但是，卷首的一个词却很容易辨认：\n 纳伽兹","小武哥儿"},
[552] = {"赫尔库拉的复仇","从雪怪手上拿回赫尔库拉的魔棒，把它交给塔伦米尔的学徒塞万德。","正在赫尔库拉大人即将完成他的巫妖仪式的紧要关头，一群人类暴徒发现了他在山上进行仪式的位置，把他残忍地杀害了。更糟的是，他们把他的遗骨埋在了南海镇的墓地里。这种不尊重伟大的巫师的行径绝对是无法让人接受的。作为他的学徒，我一定要让复仇降临在南海镇。首先我们得找到赫尔库拉的魔棒，前不久，一群雪怪侵袭了赫尔库拉的巢穴。毫无疑问是他们当中的一个拿走了赫尔库拉的魔棒。","小武哥儿"},
[553] = {"赫尔库拉的复仇","将埃希尔之焰、沃拉兹之焰和尤基尔之焰的力量注入赫尔库拉的魔棒。把经过仪式洗礼之后的魔棒带到南海镇的赫尔库拉墓地。","拿着赫尔库拉的魔棒，你会用得着它的。赫尔库拉用3个火葬柴堆来构筑他最强大的法术：埃希尔之焰和沃拉兹之焰在丘陵地带的洞穴里，尤基尔之焰在丘陵洞穴上面的另一个洞穴，在山的更北边。赫尔库拉的魔棒必须经过这三堆火焰的洗礼才能发挥作用。在仪式完成之后，把魔棒带到赫尔库拉的墓地去，那座墓地就在由人类重兵把守的南海镇。让赫尔库拉的复仇降临在愚蠢的人类头上吧！","小武哥儿"},
[554] = {"解码高手","把附有魔法的羊皮纸带给铁炉堡的勘察员塔伯斯·雷矛。","勘察员塔伯斯·雷矛是解码和译码的高手。把你找到的羊皮纸交给他，运气好的话，他说不定能弄清楚这里面写着什么。塔伯斯·雷矛现在正在铁炉堡的勘矿指挥部进修。见到他的话，就说你已经跟我谈过了，好像我最近给他添了不少的麻烦……","小武哥儿"},
[555] = {"海龟汤","给南海镇的厨师杰森带去10块海龟肉和一些舒心草。","关于南海镇，你最需要了解的是我们这儿有暴风城以北地区最好的美食！比如说我的秘密食谱：海龟汤。我听说曾有人远从夜色镇赶来这里，只为品尝一碗海龟汤！不过我最近一直都没做过这种美食。我曾经从达拉然一直走到洛丹米尔湖去捕猎钳嘴龟，不过眼下实在不是外出冒险的时候。如果你从北边那条河里弄点钳嘴龟身上的海龟肉来给我，外加一份舒心草的话，我就能很快做出点海龟汤来让你大饱口福。","小武哥儿"},
[556] = {"石雕","收集10个用旧的石雕，把它们带给塔伦米尔的看守者贝尔杜加。","达拉然巫师的一项举世闻名的能力就是他们可以操纵如元素生物这样的从其它空间来的强大生物，他们使用魔法石雕作为控制这些元素生物的工具，现在大法师伍德格莱尔想找些石雕来研究。进入达拉然巫师的领地，去给我找些用旧的石雕回来。你可以在任何一个达拉然市民的身上找到这种石雕，不过我建议你还是去收容所一带找找，那里可比达拉然安全多了。","小武哥儿"},
[557] = {"地缚护腕","为塔伦米尔的看守者贝瓦里尔收集4个地缚护腕。","大法师会对你带回来的石雕进行研究，不过我知道他会需要一些和石雕配合的东西，也就是地缚护腕。法师们将这些护腕带在元素生物的手腕上，以此来束缚他们。去干掉几个在达拉然废墟里游荡的元素生物，把它们的地缚护腕拿回来，大法师一定会很满意的。","小武哥儿"},
[558] = {"珍娜的签名","到塞拉摩去，为你看护的孩子拿到一份珍娜．普劳德摩尔的亲笔签名。","他们说塞拉摩的珍娜．普劳德摩尔是联盟最伟大的英雄之一。当我长大之后，我也要成为联盟的英雄！你认识珍娜吗，？你可不可以帮我个忙，帮我弄到她的签名？我不知道怎么向她开口，也许她很忙而无暇顾及我……但是你可以！你是和她一样伟大的冒险者！我打赌她会给你签名的！求求你了！","小武哥儿"},
[559] = {"法尔林的证据","南海镇的法尔林·奥里涅尔中尉要你从西部海岸的鱼人身上收集10颗鱼人的头颅。","你相信吗，$n？雷德帕斯对咱们杀了那么多鱼人还是不满意——哦，别谦虚了，你在这方面还挺有本事。现在他又要我证明我真的杀过鱼人，他要我把那些冰凉的、粘糊糊的鱼人的头给砍下来让他过目，这样我才能得到他的肯定。","小武哥儿"},
[560] = {"法尔林的证据","把一袋鱼人的头颅交给南海镇的治安官雷德帕斯。","你知道，$n，我真的不想碰这些鱼人的脑袋……既然是你解决了它们，那你能不能再帮我把它们送去给雷德帕斯？","小武哥儿"},
[561] = {"法尔林的证据","和南海镇的法尔林·奥里涅尔中尉谈一谈。","请告诉法尔林·奥里涅尔中尉，我觉得他应该把注意力重新集中在滋生于东部海滩的纳迦身上。告诉他，一旦有什么进展，就亲自来向我汇报。","小武哥儿"},
[562] = {"升官之道","南海镇的法尔林·奥里涅尔中尉要你去杀掉10个刺脊滩行者和10个刺脊海妖。","我以前在暴风城的导师发来消息告诉我联盟的高级将领已经开始关注纳迦带来的威胁了。根据他打听来的消息，任何人在这方面有所表现的话，都很有可能得到提拔，或者至少是调动工作岗位。不过有一个小问题……我对付不了纳迦，$n。哦，当然，我能阻止酒吧里的醉汉互相争吵，也能拖走好斗的乞丐，不过纳迦对我来说就太难对付了。你一定得帮我这个忙，$n。","小武哥儿"},
[563] = {"人事调动","把法尔林的报告交给暴风要塞里的萨缪尔森少校。","我的这份报告看来应该是没什么问题了。新的守卫长官萨缪尔森少校曾是我的导师。有了这份报告，他就完全有理由把我调回暴风城了。我需要你帮忙把报告交给他，不过……你可别让雷德帕斯拿到它。","小武哥儿"},
[564] = {"损失惨重","南海镇的达伦·玛尔维要你杀掉8只山地狮和10只巨型山地狮。","没有什么事比失去这些骏马更让我烦心了。相信我，就是那些讨厌的亡灵、可恶的辛迪加恶匪和其他害人的东西在这一带到处游逛，杀了我们不少的马匹。不过我可以对着我爷爷的墓碑发誓，对这些马匹威胁最大的还是奥特兰克上的山地狮。它们总是从山上跑下来给我捣乱！你觉得自己是个英雄？那就去做点什么来证明吧！","小武哥儿"},
[565] = {"巴图罗的雪人毛皮披风","给南海镇的巴图罗·吉塞提找一个毛布卷、一件山地披风、一股细线和10块雪人的毛皮。","我，伟大的巴图罗，将为你做一件闻名世界、全联盟皆知的雪人毛皮披风！不信你就到处跑跑看，能不能再找件更棒的。每个人都会说：“巴图罗，没有比这更好的披风了！”当然，当然没有。巴图罗需要一个毛布卷，一件由技艺高超的制皮匠缝制的山地披风，一股细线，当然还要有雪人的毛皮！把这些东西带给我，我就让你看看我的本事！","小武哥儿"},
[566] = {"通缉：瓦杜斯男爵","杀了瓦杜斯男爵，把他的头带给塔伦米尔的高级执行官达萨利亚。","高级执行官达萨利亚发出命令，通缉名叫瓦杜斯男爵的人类，此人对被遗忘者犯下了重罪。瓦杜斯是辛迪加组织的高级人物。最后一次有人见到他是在塔伦米尔北部的奥特兰克山高地上。杀死他，然后带着他的头去见高级执行官达萨利亚换取报酬。","小武哥儿"},
[567] = {"危险！","塔伦米尔的高级执行官达萨利亚悬赏通缉书记员赫拉斯·怀特斯蒂德、平民维尔克斯、矿工哈克特和农夫卡拉巴。","危险！以下这个希尔斯布莱德人是危险人物，已被高级执行官达萨利亚悬赏捉拿：通缉犯书记员赫拉斯·怀特斯蒂德杀害了亡灵卫兵托马。通缉犯平民维尔克斯杀害了药剂师埃利。通缉犯矿工哈克特杀害了亡灵卫兵弗雷。通缉犯农夫卡拉巴伏击运往幽暗城的物资。这些敌人都躲藏起来了，很难找到，杀掉他们有重赏。","小武哥儿"},
[568] = {"格罗姆高保卫战","格罗姆高营地的指挥官阿格罗戈什要求你杀死15只鞭尾迅猛龙。","向你致敬，<职业>！你来得真是时候。身为酋长委派到这个丛林基地中的指挥官，我肩负着保卫所有部落成员安全的光荣使命，我们在此的任务是保证对斯通纳德的供应线不被此地的怪物所侵扰。因此，我将委任你来负责减轻格罗姆高附近的迅猛龙给我们带来的威胁。当你取得了显著的进展后，就向我复命吧。","小武哥儿"},
[569] = {"格罗姆高保卫战","格罗姆高营地的指挥官阿格罗戈什要求你杀死10个食人魔蛮兵和5个食人魔巫医。","在第一次进入这片丛林中的时候，我们根本就没想和当地的土著部落发生任何冲突。我们任务中最重要的部分就是保持对斯通纳德的供应线的畅通。但目前的情况很复杂，附近的一群食人魔占领了格罗姆高东南方的米扎废墟。他们从来就没把我们的警告放在眼里，频繁地伏击我们的补给车队。我授命你去解决掉这群冥顽不化的食人魔。到米扎遗迹去吧，就算不能把他们驱逐出这片地区，至少也得让他们好好尝尝苦头。","小武哥儿"},
[570] = {"摩克萨尔丁的魔法","格罗姆高营地的先知摩克萨尔丁要求你给他带回8只深喉猎豹的爪子和一颗雌虎的牙齿。","部落必须意识到丛林中蕴含着的无尽的魔法力量，并尽快学会利用它来为自己服务。到目前为止，我的仪式都是很成功的，现在我已经能够施放很强大的魔法了。勇敢的<职业>，我决定为你制作一件特殊的魔法物品。给我找一些深喉猎豹的爪子和一颗雌虎的牙齿来，不过你要注意，并不是任何牙都可以用的。你必须找到品质最纯正的牙齿才行。这种野兽一般都潜藏在丛林中，但你在附近也能找到，只要从米扎废墟那边渡过河流，然后向东南方走就行了。","小武哥儿"},
[571] = {"摩克萨尔丁的魔法","给格罗姆高营地的先知摩克萨尔丁带回1根成年大猩猩的肌腱。","现在我要你去寻找一件非常难以得到的物品。为了将这些羽毛、爪子和牙齿中的魔法力量连接在一起，我必须要建立一个魔法阵，而这魔法阵只有用成年猩猩的肌腱才能做成。具体说来，老迈的薄雾谷猩猩身上的肌腱就很合适。他们一般栖息在藏宝海湾的东面。你必须找到足够新鲜健康的肌腱才行，这就是说，你有可能要杀死很多大猩猩才能找出一条合我心意的肌腱来。","小武哥儿"},
[572] = {"摩克萨尔丁的魔法","给格罗姆高营地的先知摩克萨尔丁带回10根丛林捕猎者的羽毛。","你刚才从那些野兽身上收集到的这些材料只是制造那件强力魔法物品的第一步。在我使用萨满仪式将这些物品合成之后，你就会得到一件极为有用的工具，它可以帮你更好地为酋长和部落效力。但你先得帮我收集一些丛林捕猎者的羽毛来，据说迅猛龙将这些羽毛当作它们的臂章。在格罗姆高的南边，离大竞技场不远的地方就有一个迅猛龙氏族，你可以到那里去看看。","小武哥儿"},
[573] = {"摩克萨尔丁的魔法","格罗姆高营地的先知摩克萨尔丁要你去取回一瓶圣泉之水，同时还要求你杀死10名纳迦探险者。","现在我们只差最后一种材料就可以完成这个魔法了。向南走到一处面对西侧海岸的高崖之上，你会发现一处圣泉。这处圣泉是许多学者争论的焦点，艾泽拉斯上的所有种族都认为这泉中的水乃是神为他们的子民所创造的。给我带一瓶圣泉的水回来，这是我给你的最后一个任务啦。不过，你得小心点。有一群纳迦卫兵正守在圣泉的附近，你得先对付他们才能取到泉水。","小武哥儿"},
[574] = {"特种部队","杀掉10名库尔森特种兵和6名库尔森精神医师。然后向反抗军营地的多伦上尉复命。","如今我们已经在很大程度上削弱了他的正规部队，但这就意味着你得直接去面对他手下的精锐部队。如果那些家伙没有被派出去袭击我们落单的士兵的话，他们就应该驻扎在库尔森营地后山上一处名为“储藏室”的洞穴里。我私下里认识许多库尔森的手下，他们都是身经百战的老兵，对库尔森忠心耿耿，而且最要命的是，他们对敌人毫不手软。这对你来说恐怕不是个简单的任务，。多加小心。你战胜了他们以后，就去向我的长官多伦上尉复命吧。","小武哥儿"},
[575] = {"供与求","收集2张淡水鳄的皮，把它们交给藏宝海湾的崔斯里克。","“前无古人，后无来者，南海一带最好的也是世界最好的皮匠。”他们就是这么叫我的。我！崔斯里克！最好的皮……呃，好吧。我的皮货以质量优质而远近闻名，都是鉴赏家们的首选之物！我最近收到了来自工匠行会的雷德沃克斯主管的订单，他需要十二双刨花皮靴。啊，就是那种由我制作的、非常抢手的靴子。不过要想做那种靴子的话，我需要一些鳄鱼皮才行。在荆棘谷北边的河边有很多鳄鱼，你看能不能……","小武哥儿"},
[576] = {"海盗的眼睛","藏宝海湾的独眼迪兹要求你从血帆海盗那里找回他的眼睛。","站住！谁在那边？啊，如果没有那只特制的魔法眼，我就是个废人了。当初在一次战斗中，我失去了我的眼睛！但幸运的是，我们的船停靠在米奈希尔港时，一位旅行法师送给了我一只特制的玻璃眼，这样我才又能看见东西了。不过昨天晚上我参加了袭击血帆海盗的行动，在跳出船的时候玻璃眼睛不小心给弄丢了。一定是那帮血帆海盗拿走了我的眼睛！看来他们这群混蛋已经找到了到藏宝海湾来的路。你能不能帮帮我这个老海盗，把我的眼睛给找回来？","小武哥儿"},
[577] = {"收集鳄鱼皮","给藏宝海湾的崔斯里克带回5张钳嘴鳄鱼的皮。","嗯，这些靴子已经基本定型，接下来就要开始打磨表面了。但你带来的皮似乎少了点，做不出足够的鞋垫来。“那现在我们得干什么呢，崔斯里克？”你肯定会马上问这种问题，哈哈，你跟崔斯里克说话可真不幸啊，因为我马上就要给你派活干啦！没人会去观察鞋垫的，所以我们只要找点又厚又便宜的鳄鱼皮就行了。纳菲瑞提湖旁边的那种钳嘴鳄鱼就不错。","小武哥儿"},
[578] = {"海潮之石","为藏宝海湾的大财主里维加兹找到闹鬼的岛屿。","如果个岛上确实有水元素和地精法师的鬼魂的话，也就是意味着在那里可以采到海潮之石！我希望你能找到这座闹鬼的岛屿，去看看上面到底是怎么回事。哦，如果你想知道更多的有关海潮之石的信息的话，可以带着这张凭证去暴风城图书馆，他们会帮你找到我最初读过的那本传说的手抄本。真的是加兹班首先发现那种石头的吗……？","小武哥儿"},
[579] = {"暴风城图书馆","","","小武哥儿"},
[580] = {"威士忌斯利姆的酒","藏宝海湾的威士忌斯利姆想要你帮他找回弄丢的紫葡萄酒。","我们那天喝醉了，结果从很远的辛特兰那边掉下了船，活活地漂到了望海崖这里来，险些喂了鱼。而且我斯利姆从小就没怕过水！我们船长从一艘去暴风城的私掠船上抢来了一箱紫葡萄酒。我们在辛特兰被风暴袭击的时候，我东倒西歪地撞碎了那个箱子，结果那里面的酒在大风大浪里全都掉进海里了。我要是不把它们给找回来的话，船长见了我非拿我喂猫不可！帮帮我吧！","小武哥儿"},
[581] = {"耶尼库的下落","给格罗姆高营地的尼姆布亚带回9根血顶巨魔的獠牙。","厄运！厄运降临在我们酋长的小儿子耶尼库身上……按照氏族里的习俗，他被过继给了祖尔格拉布的巨魔，但我们暗矛氏族随后便决定跟随兽人酋长萨尔离开家乡，可怜的耶尼库就此与我们失去了联系。我是从奥格瑞玛回到荆棘谷来的，我回来寻找我们酋长的孩子。我相信是血顶氏族抓住了他。如果你愿意帮助我的话，就去干掉血顶氏族的那帮家伙吧，他们就在北边。把他们的獠牙给我带来。","小武哥儿"},
[582] = {"猎头行动","给格罗姆高营地的尼姆布亚带去20个皱缩的头颅。","我们必须弄清楚耶尼库是否还活着。杀掉一些血顶部落的猎头者，并把他们身上挂着的皱缩的头颅给我取回来。你必须要收集尽可能多的首级回来，这样我才能检查一下耶尼库的头在不在其中。如果耶尼库真的被血顶氏族给杀了，他们的酋长，那个名叫甘祖拉恩的家伙，就一定会遭受长达600年的恶毒诅咒！去吧，。沿海岸北上，在祖丹亚废墟和祖昆达废墟那里就有很多血顶猎头者在活动。","小武哥儿"},
[583] = {"欢迎来到丛林","与赫米特·奈辛瓦里二世谈一谈。","欢迎来到荆棘谷！也许你没有注意到，那边的那位矮人就是联盟的大英雄、顶级猎手赫米特·奈辛瓦里的儿子。和他父亲一样，他并不欢迎陌生人来这个营地，不过你看上去已经见过大世面了，<职业>。去和他谈一谈吧，或许他能教你些狩猎的技巧。","小武哥儿"},
[584] = {"血顶之颅","将甘祖拉恩的头颅和奈兹里奥克的头颅带回格罗姆高营地，放入冒泡的大锅中。","感谢蛇神，耶尼库的头并不在这些首级当中。但我们仍不清楚他的状况……我们必须知道真相，不过，恐怕只有血顶氏族的酋长和巫医才知道这些事，而他们又是我们暗矛氏族的敌人，所以他们是绝对不会老老实实地告诉我们真相的，恐怕他们只有在死了以后才会愿意和我们谈谈！把甘祖拉恩和奈兹里奥克的头给我带回来，然后放进这个锅里去。他们就躲在祖昆达废墟里的深处。只要有他们的头颅……我们就能和他们好好谈谈了。","小武哥儿"},
[585] = {"奈兹里奥克","带回巴里亚曼战利品、赞塔加战利品和祖玛维战利品各一个，把它们放入格罗姆高营地里中的冒泡的大锅里。","<奈兹里奥克的头说话了>没错，我知道那个暗矛部落的孩子被带到什么地方去了。虽然你杀害了我，而且把我的灵魂也束缚了起来，但要是你们不给我点好处的话，我还是什么都不会说的！血顶氏族正在与劈颅氏族交战，要想让我帮忙，就从劈颅氏族那里偷来3颗颅骨来，放在这里陪着我，这样我在扭曲虚空之中也就有三个奴隶啦。这三个头骨必须分别从他们在巴里亚曼废墟、赞塔加废墟和祖玛维废墟的颅骨堆中拿来。","小武哥儿"},
[586] = {"甘祖拉恩","杀死8名劈颅猎人、6名劈颅猎头者和4名劈颅狂战士。将安纳希克的盔甲碎片放入格罗姆高营地中的冒泡的大锅里。","<甘祖拉恩的头颅开始说话了>我要诅咒你！诅咒你的八辈子祖宗！只有鲜血和复仇才能平息我的愤怒，如果这是你的意愿的话，那么……这么办吧：到东边的劈颅氏族的老窝去，尽情地屠杀吧，要是你够强的话……就干掉他们的酋长，残忍的安纳希克。嘿嘿，把他的盔甲碎片拿来给我看，不过我很怀疑你的能力！他肯定会把你的四肢都撕下来，然后让你烂在地里喂乌鸦，哈哈哈！","小武哥儿"},
[587] = {"鼻烟","藏宝海湾的迪格要求你带给他15份鼻烟。","啊，海上的生活。我不想说这种生活有多美好，但这就是我的生活。当我每次入港的时候，我都会找个地方好好喝上一杯，再找点高品质的鼻烟抽抽。坏习惯吧，但海盗们怎么能没有坏习惯呢，对吧？所以你可以想像一下，当我发现镇上的药草师卖完了他的全部鼻烟并且已经离开了这座小镇的时候，我会有多沮丧有多伤心了！据说给他运货的那条船让那些该死的血帆海盗给抢劫了。我相信像你这样勇敢的<职业>，一定能说服他们交还船上的货物，对吧？","小武哥儿"},
[588] = {"耶尼库的命运","与肯维雷谈一谈。","<奈兹里奥克开口说话了>现在，我会告诉你关于你所寻找的那个耶尼库的事情……年轻的耶尼库和他的氏族失散了。他被巫医赞吉尔给带走了。现在赞吉尔控制了他的身心，只有一种极端强大的法术才能使他恢复自由之身。而你肯定没有这种法术，<职业>。或许你暗矛部落的朋友们有办法拯救耶尼库，不过我对此也相当怀疑。","小武哥儿"},
[589] = {"歌唱水晶","给格罗姆高营地的肯维雷带回3块蓝色波光碎片。","传说荆棘谷的中心地带深藏着一块宝石，这块宝石的名字叫心灵之眼，其中蕴涵着巨大的力量。如果你得到了这块宝石，也许我们就能用它将失落于黑暗之中的耶尼库拯救出来。我会与丛林之灵们商谈，向他们询问心灵之眼的位置。与此同时，你要去一趟东南方的水晶矿洞，从那里的铁颚蜥蜴身上收集一些蓝色波光碎片。这些水晶非常稀有，但我们需要利用其中的魔法能量来控制心灵之眼。","小武哥儿"},
[590] = {"潜行者的交易","打败丧钟镇的卡尔文·蒙泰古。","什么？什么？！你要钱？我可不欠你什么钱。信？什么信？哦，你是不是想打架？好吧，朋友……放马过来啊！","小武哥儿"},
[591] = {"心灵之眼","将心灵之眼交给格罗姆高营地里的肯维雷。","心灵之眼目前落在了一个食人魔法师的手里，他就住在东边的莫什奥格食人魔山的深处，他的名字是麦佐斯。我自暗矛部落还在荆棘谷定居的时候就知道他了，他是一个邪恶的家伙，而且法力非常强大。如果确实是他拿着心灵之眼的话，他的魔法就会具有极大的威力。你必须从这个麦佐斯的手中抢到心灵之眼。这确实是件危险的工作，但这也是我们拯救耶尼库的唯一希望了。","小武哥儿"},
[592] = {"拯救耶尼库","将装满的灵魂宝石交给尼姆布亚。","我已经将心灵之眼重塑为一颗灵魂宝石。你必须先用它震慑住耶尼库，成功之后，就立刻把宝石放在他的额头上，这样才能抽取出他的灵魂。接下来把宝石交给尼姆布亚就可以了。耶尼库和流亡者赞吉尔一起住在阿博拉兹废墟，只要沿着水晶海岸走到荆棘谷的海角那边就能找到了。","小武哥儿"},
[593] = {"灵魂宝石","","","小武哥儿"},
[594] = {"瓶中信","找到瓶中信的作者。","这张便笺上有极漂亮的字迹：致任何能帮助我的人拜托，我迫切地需要帮助。一只巨大的蓝鬃猩猩将我囚禁在了南海的一座岛屿上。这里夜晚的星像我以前从未见过，岛上全是茂密的丛林，但在天气晴朗的时候，我能看见西北方的蛮荒的海岸，还有几条大船在向西南航行。求求你，请帮帮我吧。","小武哥儿"},
[595] = {"血帆海盗","大副克拉兹要求你去侦察一下藏宝海湾北边的海滩。","你看起来特别像要找份活干似的，伙计。虽然我不清楚为什么一个喜欢在平地上过日子的<种族><职业>会愿意帮助我们这些黑水强盗，但我不会阻拦你的。我们的船就停泊在藏宝海湾，而我们的死对头——那些该死的肮脏的血帆海盗——正在整个荆棘谷南部胡作非为。现在我们这里的人不是抱着酒瓶子就是抱着姑娘！我需要一个探子来帮我做事。去侦察一下野人海岸上有些什么，没错，就是藏宝海湾北边的那片沙滩。","小武哥儿"},
[596] = {"染血的白骨项链","给格罗姆高营地的肯维雷带回25串染血的白骨项链。","我是被派来格罗姆高帮助尼姆布亚完成他的任务的，但……我发现这里还有些更有意义的事要做。血顶氏族是我们的敌人。将敌人的战利品抢过来将极大地鼓舞我们的士气，同时也能给对方以沉重的打击。也许你可以帮我们氏族猎杀血顶氏族的成员……他们就居住在北边，干掉那些血顶巨魔，把染上它们鲜血的白骨项链给我拿回来。你拿回来越多项链，我们就会越尊敬你。","小武哥儿"},
[597] = {"血帆海盗","将你的发现报告给藏宝海湾的大副克拉兹。","这是一张藏宝海湾的地图，上面用红笔标叉的地方就是你现在站的位置。图上潦草的写着几行字：“你们的任务就是悄悄地在此地扎营，等待南方指挥部发出信号后再开始攻击。如果任何人试图阻碍你们，格杀勿论。”","小武哥儿"},
[598] = {"裂骨项链","给格罗姆高营地的肯维雷带回25串裂骨项链。","你已经收集了足够多的血顶氏族的战利品，现在我要交给你一项新的任务。劈颅氏族居住在东南方，以前我们一直和他们互无往来。虽然暗矛部落已经不住在荆棘谷了，但现在我们却卷入了与他们的冲突之中。所以，我要你去猎杀他们，把他们的裂骨项链带回来给我。如果你在我们这场战争中帮助了我们暗矛氏族，就一定会赢得我们的友谊。","小武哥儿"},
[599] = {"血帆海盗","把血帆海盗的计划报告给舰队指挥官卡拉·海角。","太令我吃惊了！那么血帆海盗正计划着进攻藏宝海湾吗？这群发了神经病的恶棍当真是不要命了么，藏宝海湾永远都是我们黑水海盗的地盘！这事比我想得还要严重。马上将你所知道的一切报告给舰队指挥官卡拉·海角！这群该死的海狗可能已经开始在镇子外面集结了……","小武哥儿"},
[600] = {"风险投资公司","给藏宝海湾的克兰克·菲兹巴布带回10块蓝色歌唱水晶。","最近，风险投资公司在荆棘谷一带展开了一系列的行动，这让我们这些诚实努力的地精们，你看，比如我，根本没办法在这里讨生活了！拜托，你一定要帮帮我！风险投资公司打算在北边的水晶矿洞那里采矿，可是由于那边的石化蜥蜴到处肆虐，他们根本没办法进入矿洞，只能在周围的山上开采歌唱水晶。去把他们的水晶都抢来，让他们知道他们不该在这片丛林里如此嚣张。还有……嗯嗯……把那些水晶给我带回来当证据！","小武哥儿"},
[601] = {"水元素","为藏宝海湾的大财主里维加兹收集6个水元素护腕。","这些水元素无疑是传说中发现了海潮之石的地精法师加兹班召唤的。也许你知道，海潮之石会诅咒任何挪动它的人，就是说，会让那个倒霉的家伙从这个世界上彻底消失。应该有什么办法可以破除这个该死的诅咒，我们可以请一位达拉然的法师来帮我们分析一下水元素胳膊上戴着的护腕里的魔法。你能不能回到那岛上帮我收集一些进行魔力分析所需的样本？","小武哥儿"},
[602] = {"魔法分析","将水元素护腕交给达拉然的大法师安斯雷姆·鲁因维沃尔。","虽然我听说达拉然的法师们正忙着重建他们那被毁的城市，但我敢说，你肯定能找到一个愿意帮我们检查护腕的法师。根据我对那些法师的了解，他们是绝对不会拒绝任何与魔法有关的谜题的。将这包水元素的护腕拿给他们，让他们看看能不能找到解除石头上的诅咒的方法。","小武哥儿"},
[603] = {"安斯雷姆的钥匙","与藏宝海湾的凯特琳谈一谈。","嗯，拥有那块石头的法师一定通过在某处集中力量来加强他的魔法效力……比如在某个祭坛上。按理说你应该可以用更强大的力量去瓦解它。就目前的情况而言，我知道有件物品可以派上用场：巨魔一族失落的另一件神器，一把远古匕首。但是，还有一个……只有一个……小问题。你知道，我过去在荆棘谷进行研究的时候得到了那把匕首，但我把匕首给了我那任性的女儿，她叫凯特琳。她现在已经去了藏宝海湾，也许是真的想当个海盗吧。","小武哥儿"},
[604] = {"血帆海盗","藏宝海岸的舰队指挥官卡拉·海角要求你杀死10名血帆流氓并将血帆海图和血帆计划书带回去。","克拉兹高度赞扬了你为黑水海盗做出的重要贡献。我信任你，因此我要赋予你一个对于舰队来说至关重要的任务。我们要求你渗透进血帆海盗建立在蛮荒海岸的南方指挥部。偷袭他们的营地，将他们的海图与计划书都给我带回来，我们必须要搞清楚这群渣滓到底想干点什么。","小武哥儿"},
[605] = {"歌唱水晶碎片","为克兰克·菲兹巴布收集10块歌唱水晶碎片。","歌唱水晶是荆棘谷的一种特产，它对某些人来说有着非常重要的价值。我本想运一些歌唱水晶到别的地方去卖，可那该死的风险投资公司想要独占它，所以，像我这样诚实的商人看来就无法亲自去收集水晶了！我决定雇佣你。荆棘谷中的蜥蜴都有吞食这种水晶的习性，这可以使它们的皮肤变得更硬。因此，我们可以从它们身上收获到一些高品质的水晶。随便哪只蜥蜴身上都会有水晶，但最容易对付的是在北边的海岸附近活动的那些蜥蜴。","小武哥儿"},
[606] = {"吓唬病鬼","给藏宝海湾的“病鬼”菲利普带回5块薄雾谷猩猩的内脏。","你知道这里最让我受不了的是什么吗？这儿的人都有死也不还赌债的毛病！现在已经有一大群家伙欠着我的钱了。你能帮我催一下债吗？第一个要催的就是住在港口那边的“病鬼”菲利普。他上个礼拜欠得实在是太多了，我一定要把这笔钱给要回来！但是要想拿到它，我们就得好好吓唬吓唬他。到镇子外边去猎杀一些老迈的薄雾谷猩猩，然后从它们身上搞点内脏杂碎什么的，把这些玩意丢给那病鬼。最好别让他想到那是动物内脏，让他想点更糟的。","小武哥儿"},
[607] = {"向马克基雷回报","将菲利浦的还款交给“海狼”马克基雷。","给，把这个布袋给海狼。告诉他，我是想还他钱的！我发誓！！我只是喝多了点，迷路了而已，还有……总之是一团糟了。他会理解我的——你可别乱说啊！","小武哥儿"},
[608] = {"血帆海盗","藏宝海湾的舰队指挥官卡拉·海角要求你杀死血帆海盗的斯蒂沃特船长，尼哈鲁船长和舰队指挥官菲尔拉伦。","打击一下菲尔拉伦的脆弱神经吧！他连划着小船穿越水晶湖都做不到，更别说独自率领整支舰队来和我们对抗了。血帆海盗一定会为他们的粗心大意而付出代价的。现在我们已经掌握了他们的攻击计划，完全可以在他们什么还都不知道的时候抢先下手。我们并不需要派出全部的舰队，只要一支勇敢的冒险者队伍就能轻易完成这任务。$n，带上你最优秀的同伴守在菲尔拉伦的登陆点，杀掉血帆的指挥官。这样他们的舰队不用多久就可以去喂鱼了……","小武哥儿"},
[609] = {"讨债行动","给藏宝海湾的“海狼”马克基雷带回玛雷的畸形足、乔乔的金色望远镜和苏克的巨型戒指。","我这儿的白条已经少了许多啦，但还是有许多没信誉的家伙欠着我的钱。接下来，我们得对付“畸形足”玛雷·维尔金斯、火柴棍乔乔，还有拇指苏克。这帮家伙的债欠了好久，我看他们是不想还了！后来，我听说他们被什么人给骗到丛林里去了。我当然不关心他们到底会怎么样——我要的是我的钱！他们应该就在东北方的阿博拉兹废墟和朱布瓦尔废墟里。找到他们，把我的钱拿回来。","小武哥儿"},
[610] = {"帅小伙子邓肯","从“帅小伙子”邓肯那里夺回凯特琳的匕首。","我老爸派你来的？我还以为那怪老头已经早就放弃掉我了呢。我之所以离家出走确实不是他的错，他只是不应该为我安排好一条乏味的人生道路，并希望我欣然接受它。我怎么能忍受整天读着那些发霉的书本，整天和那帮灰头发加驼背的乏味老头法师们在一起！如果你需要我的匕首，你可能得从一个叫“帅小伙子”邓肯的血帆海盗那里夺回来。我想你只要教训教训他，他就会屈服的。","小武哥儿"},
[611] = {"海潮的诅咒","用凯特琳的匕首摧毁海潮祭坛，然后杀死加兹班，将海潮之石带给大财主里维加兹。","这么说你正在寻找某个祭坛喽？好吧，虽然我不像我老爸那样是个研究巨魔遗迹的专家，但我对你正在寻找的岛屿也略知一二，在岛的附近有一座沉没在水底的巨魔城市，我想你应该到那里去碰碰运气。既然是你帮我找回了我的匕首，借去用用当然没有任何问题……但我希望你用完以后能还给我！","小武哥儿"},
[612] = {"<UNUSED>","Return Catelyn's blade.","It's a long shot, but perhaps you could try to convince Catelyn to part with her dagger？ The heart of a collector, you know how it is？Perhaps if you mention that it's for me, she might be more well-disposed to sell it to me.","小武哥儿"},
[613] = {"玛雷的腿","把玛雷的钥匙带给藏宝海湾的“海狼”马克基雷。","该死！那见鬼的玛雷居然在他的假腿上安了一个锁，我还死活都打不开！他的宝贝，还有他欠我的钱，都藏在那条假腿里！我们得想办法找到钥匙才行。玛雷这家伙过去因为喜欢和住在东北边食人魔山上的莫什奥格食人魔赌博而出名，而且他告诉过我——我是说当他还活着的时候——他每次赢了一票大的之后都会去一趟那里，所以，或许那边的食人魔会有他的钥匙。要真是如此的话，你八成得大开杀戒才能搞到钥匙……","小武哥儿"},
[614] = {"船长的箱子 (精英)","将斯莫特的箱子交给藏宝海湾的海克拜瑞·斯莫特。","我过去在一条专跑从这里到卡利姆多的棘齿城的航线上干过。我是个很优秀也很有名望的船长。直到……那些该死的海巨人毁了我的生活！他们打沉了我的船，杀光了我的水手，把我丢在一条救生艇上，让我漂回了藏宝海湾。还有，其中一个名叫高拉什的巨人还把我的箱子给偷走了，他说要拿这东西当鼻烟盒，简直是神经病！我听说有人看见高拉什最近在东边的海岸一带闲逛。找到他，把我的箱子给抢回来！快去，你会得到一位船长的敬意的。","小武哥儿"},
[615] = {"船长的弯刀","与斯普罗格谈一谈。","我的第一条船被那些海巨人们搞沉了之后，我只好买了第二艘，而且给它起名为“斯莫特的复仇”。我为它配备了新的装备和船员，并出发去寻找那些该死的巨人。我找到了他们，但……他们又一次击败了我们。他们把“斯莫特的复仇”号给打成了碎片，船员也几乎被他们杀光了，但那帮混蛋却把我丢在了一条救生艇上，让我一个人漂了回来。这次，那些海巨人中的另外一个偷了我的弯刀。到奈古拉什那里去把我的佩刀给抢回来！去和斯普罗格谈谈吧。他本来是“斯莫特的复仇”号上的厨子，沉船的时候他也幸存了下来，我想他能帮你们找到那些","小武哥儿"},
[616] = {"幽灵岛","与藏宝海湾的大财主里维加兹谈一谈。","大财主里维加兹让我留意最近在藏宝海湾和荆棘谷附近流传的古怪传闻。虽然我平时是绝不会关心什么鬼故事的，但这两天在酒馆里听一些水手们说在海岸附近有一座闹鬼的小岛。据他们说，那上面全是水元素和一只整日说着疯话的地精的鬼魂。如果你正好要去见里维加兹阁下的话，能替我将这件事转告给他吗？","小武哥儿"},
[617] = {"一捆海蛇草","给藏宝海湾的海盗布劳兹带回10根海蛇草。","听说你正在找活做，？要是你够胆的话，我这儿倒是有件不错的活正要找人呢。你听说过最近有许多人都在找一处泉水么？是的，有一群纳迦也在找。我有个叫格罗伊的朋友吧，他最近出了一大笔钱，想买一些纳迦称之为海蛇草的东西。我也不清楚那到底是什么，只知道是一种很值钱的海草。他也没说要那玩意干什么，不过他确实出了一个好价钱，大概需要一捆吧。你帮我搞来10根这种什么草，那我们就可以跟他做笔交易啦。不久前有人看见这里北边的海滩上出现了不少纳迦。","小武哥儿"},
[618] = {"挑战奈古拉什","将10块烧烤秃鹰翅膀和5瓶密林葡萄酒带到斯莫特船长的救生艇上去。然后杀死奈古拉什，将斯莫特的弯刀交给荆棘谷的斯莫特船长。","奈古拉什总是一副随时准备把一切都吞下去充饥的样子。那些巨人袭击我们的船的时候，奈古拉什直接冲向了我的厨房，不过他可不像其他巨人那样喜欢吃人。奈古拉什要的是酒……还有我秘制的烧烤秃鹰翅膀。嘿，这可都是我的拿手菜，我当年可是跑到荒芜之地才弄到这食谱的！如果你想把奈古拉什给引出来，只要用点酒再加上一碟烤翅就行啦。把这些东西放进我们当初丢在东南边海岸上的救生艇里，然后你就等着奈古拉什闻到食物的味儿乖乖上钩吧！","小武哥儿"},
[619] = {"引诱奈古拉什","","","小武哥儿"},
[620] = {"刺着字母的腰带","将刺着字母的腰带还给他的主人。","这条精致的腰带的边上刺着两个字母“HS”。","小武哥儿"},
[621] = {"赞吉尔的秘密","收集12份赞吉尔的药剂，把它们交给藏宝海湾的克兰克·菲兹巴布。","流亡者赞吉尔和他的追随者们住在藏宝海湾东北方的朱布瓦尔废墟和阿博拉兹废墟里，这个家伙已经被他的氏族放逐了。为什么？这个……据说是因为赞吉尔掌握了某种可以将自己的心灵与他人连接在一起的方法，而他所属氏族的领袖就因此非常害怕他。他让他的追随者们喝下了一种从植物中萃取出来的液体，用它来压抑他们的自我意识并加强他们的力量。他的这种药剂对那些试图控制别人的家伙来说有非常大的价值。给我弄些这种药剂的样本来，我要研究一下……","小武哥儿"},
[622] = {"向卡雷布下士回报","将修理过的烹调锅交给叛军营地的卡雷布下士。","在你离开的这段时间里我已经把这锅替你修好啦。我甚至还免费加装了一个特制的蒸汽哨，看，华丽吧！这下面还装了一个新的自动菜刀，专门用来切蹄膀的！没错，克拉兹克的烹调锅将为你带来百分之百的烹调乐趣，我敢打赌它的主人会非常满意的！","小武哥儿"},
[623] = {"一捆海蛇草","给塞拉摩的海盗格罗伊带去一束海蛇草。","，你不在的时候，格罗伊托人给我捎了一个信儿过来。他说他很满意我们上次送去的货，现在又有一位新的顾客也想要一些那种海草。我可不想花上整整一个礼拜去一趟塞拉摩，如果你愿意替我去一趟的话，那就再好不过了。很有挑战性吧？你知道那边的尘泥沼泽吧？你可得小心点，塞拉摩可不是个普通人能去的地方。","小武哥儿"},
[624] = {"科泰罗的谜题","解开这道迷题！","有一座装饰华丽，人来人往的桥\n逆风径东，赤脊山南面之地\n在那之下，它正等待着你\n这可以叫提示，也可以叫线索\n在那里，无尽的明天正等待着你\n在悲伤沼泽之中静静地等待着你","小武哥儿"},
[625] = {"科泰罗的谜题","解开这道迷题！","卡利姆多上的某个遥远之地\n危险湮灭了命运与希冀\n贫瘠之地以东的环境糟糕至极\n绝望与威胁伴着沼泽中的尘泥\n但那里埋藏着线索供你寻觅\n在西南的一处洞穴中可解此谜题","小武哥儿"},
[626] = {"科泰罗的谜题","解开这道迷题！","到洛丹伦去！那片混乱中的土地\n在那里，勇敢的战士们与亡灵为敌\n在剧烈的动荡中寻找属于你的路途\n最终你会解开这谜题\n沿着鹰巢山峦，位于瀑布之底\n波光之下的宝藏正等待着你","小武哥儿"},
[627] = {"克拉兹克的要求","给藏宝海岸的克拉兹克带去4块次级血石矿。","在阿拉希高地北部的枯须峡谷中有一处山洞，那里有一种十分稀有的矿石：血石。那个山洞里的血石虽然不是品质最佳的，但即使是低等级的血石也是很有价值的……当然这只是对那些懂得如何使用它们的人来说。我需要一些这种血石。我会在这里修补你的锅子，不过，当我修锅的时候……你去给我弄些血石来吧。对，多带点回来，我当然会给你报酬的。嗯嗯，要是你连这点事都搞不定，就去找个能搞定的人帮你！","小武哥儿"},
[628] = {"刨花皮靴","给藏宝海湾的崔斯里克带回1张老鳄鱼的皮。","既然里面的东西都已经做完了，那么就只剩下外面的表层部分了。表层一定要用质量最好的老鳄鱼的皮。这种皮甚至比帆布还要结实，用它就可以完成我的完美设计。虽然要找到完美的皮很难，但这种老海鳄的皮是唯一能配得上我的设计的材料了。老海鳄只会在其它鳄鱼被攻击的时候才会出来保护族群，所以恐怕你得先杀些普通鳄鱼引它们出来。","小武哥儿"},
[629] = {"暗礁海","给格罗姆高营地里的肯维雷带回一块石板碎片。","很久以前，有一座古老的巨魔城市因为大地震沉入了西北方的野人海岸水下。现在那里被一群鱼人所占据着，任何接近的人都会遭到他们的攻击，我们把那处地方叫作暗礁海。在那片废墟之中有一块古老的石板，上面记录着一位名叫格里雷克的巨魔英雄的传说。那块石板对于我们暗矛部落来说具有神圣的意义，尽管它太大，没办法全部运走，但我仍希望有人能从上面敲下一块碎片，让我们带到奥格瑞玛的新家去供奉起来。","小武哥儿"},
[630] = {"瓶中信","杀死穆克拉并带着钥匙回去救出普巴尔公主。","，我的一切都全靠你了！是蓝鬃猩猩之王穆克拉把我抓进来的，它统治着这岛上所有的野兽，它们不顾我的反抗，用这些铁链把我给锁在这儿。如果你能杀了它，从它身上找到能够打开这套镣铐的钥匙的话，我会好好报答你的。它通常在这座岛的北边活动，但你一定得小心，它绝对是一个很难对付的家伙。","小武哥儿"},
[631] = {"萨多尔大桥","拉格·加玛森要求你找到老伊本瑟。","当时，山里突然传出了一阵巨大的爆炸声，而且在山谷中回荡了很久。那简直太可怕啦！士兵们为了守卫萨多尔大桥死伤惨重。长须说我们总有一天要向黑铁矮人们复仇的。我们目前的情况非常窘迫，而且暂时也得不到任何援军。长须派了老伊本瑟去侦查东边的那座桥，看看我们是否有机会攻陷那里。可这已经是好几天以前的事了。丹莫德目前全城被围，我们根本无法抽出人力去联络他。或许你能帮忙去找他……","小武哥儿"},
[632] = {"萨多尔大桥","向拉格·加玛森回报，并将你在伊本瑟尸体上找到的羊皮纸交给他看看。","很显然，可怜的老伊本瑟遭遇到了黑铁矮人的伏击，已经战死了。但你突然注意到了他紧握着的拳头中似乎有一张皱皱的羊皮纸。将这条令人沮丧的消息告诉拉格·加玛森，并把你的发现报告给他。","小武哥儿"},
[633] = {"萨多尔大桥","摧毁堆积的炸药。","天呀！不！可怜的伊本瑟，这实在是一个悲剧。我们绝对不能让他就这样白白牺牲了。你发现的这张羊皮纸上写道，是卡姆·深怒在背后组织了这次进攻，并且，他还在萨多尔峡谷的阿拉希高地那一侧囤积了不少炸药。如果他们用这些炸药摧毁了桥梁的话，那么我们的通向北边的主要补给线就会被彻底切断！必须摧毁这些炸药，$n！完成了这个任务后立刻回来向我复命。你是我们最后的希望了。","小武哥儿"},
[634] = {"请求援助","去避难谷地找到尼艾丝队长。","我想拜托你再帮我一个小忙，<职业>。我们正等待着来自铁炉堡的援军。但是，罗戈说阿拉希高地上的避难谷地那里还有一处联盟的营地。到那里去找尼艾丝队长吧。问问这位善良的队长，看联盟是否能派一些暂时没有任务在身的士兵来帮我们夺回丹莫德和萨多尔峡谷。","小武哥儿"},
[635] = {"山中的水晶","找到你在幻觉中看到的那块水晶。","你拿着这块碎片，明显地感觉到它在跳动着……你感到它在祈求，好像有什么人想要与你交流，急切地需要你的帮助。你的脑中出现一幕奇特的影像——在阿拉希的北部山脉上，有一块明亮的水晶从地面上突出来。你感觉到自己仿佛被带到了那个地方……","小武哥儿"},
[636] = {"大地公主的传说","找到密斯赖尔水晶裂片。","这本书叙述了元素公主密斯赖尔和她被囚禁在阿拉希高地下面的故事。它还叙述了高地里的一处秘密的水晶岩层。这些被称为“密斯赖尔水晶裂片”的东西是囚禁大地公主的监狱的窗户。如果某个勇敢的人能找到密斯赖尔水晶裂片，那么$g他:她;就有可能和她交谈……","小武哥儿"},
[637] = {"苏利·巴鲁的信","把苏利·巴鲁的信交给铁炉堡的萨拉·巴鲁。","你手中的这封信湿淋淋的，已经面目全非了，只有几页像是得到了精心保护的信纸上的字迹还能辨认。这封信是写给铁炉堡的萨拉·巴鲁女士的，开头写着，“亲爱的萨拉……”","小武哥儿"},
[638] = {"巨魔之敌","前往阿拉希高地的落锤镇，与森谷谈一谈。","随着索拉斯·托尔贝恩的死与激流堡的毁灭，沃金大人指示我们要不惜一切代价将那把传说中的宝剑托卡拉尔从人类的手里抢过来，供我们在与祖尔格拉布的巨魔的战斗中使用。我们已经派出了一个名叫森谷的资深猎人前往阿拉希高地东北部的落锤镇去寻找它。","小武哥儿"},
[639] = {"激流堡符印","帮落锤村的森古拿回激流堡符印。","在古代，巨魔曾与阿拉索帝国以及我们最强大的对手——被称为“激流堡的伊格纳乌斯”的托尔贝恩作战。托尔贝恩总是挥舞着托卡拉尔剑进行作战。在古代语中，托卡拉尔是“巨魔杀手”的意思。然而，现在托尔贝恩子孙的势力已大不如前了，他们的要塞也已经变成了废墟。托卡拉尔剑是由几块符印保护的，这些符印现在都在激流堡的幸存者手中，我们必须获得它们。辛迪加组织拥有第一块——这一块应该就在他们驻扎于激流堡的那群人中的某个人手里。","小武哥儿"},
[640] = {"破碎的符印","从激流堡的守卫者那里取回5块符印碎片，把它们交给落锤村的托尔甘。","索拉斯·托尔贝恩的墓室由三块符印护卫，这其中的第一块你已经从辛迪加手中得到了。另外两块更难得到，因为它们被牢牢地控制在激流堡的民兵手里。索拉丁符印被索拉斯的儿子加林分成了十一块，分别由一个激流堡守卫者掌握。取回这些符印，把它们交给巨魔祭司托尔甘，他能够将它们合成一块完整的符印。","小武哥儿"},
[641] = {"索拉丁符印","把修复的索拉丁符印交给落锤村的森古。","复原得完美无缺。现在，这块完整的符印可以被用于打开托尔贝恩墓穴上的封印了。把它交给森古吧，他一定还有别的任务要你完成。","小武哥儿"},
[642] = {"被困的公主","收集密斯莱尔之尘。把它们放在枯须峡谷中的虹光水晶碎块上。","我叫密斯莱尔，我是大地的公主。巨人们俘获了我，把我拘禁在阿拉希高地的地下深处。这些水晶碎块是我和外界交流的唯一途径。帮帮我。这些巨人的盟友——枯须狗头人——就在东边的枯须峡谷里活动，那里有一块类似水晶碎块。要激活那块水晶，你必须从狗头人那里收集到密斯莱尔之尘，然后把它们放在水晶上。求求你了，，帮帮我吧！","小武哥儿"},
[643] = {"阿拉索符印","取回阿拉索符印，把它交给落锤村的森古。","尽管他们还没有控制激流堡，更不要说整个阿拉希高地，但那人类王子却率领着剩余的骑士在乡间疾驰。我不能理解他为什么这么做，谁又能理解人类的思维方式呢？且不管他到底是怎么想的，最重要的是他把一块符印交给了瓦罗卡尔中尉，也就是那群骑士的首领。找到这个人，把他的符印带回来交给我。","小武哥儿"},
[644] = {"托尔贝恩符印","杀掉加林·托尔贝恩王子，把托尔贝恩符印带给落锤村的森古。","打开索拉斯·托尔贝恩墓室所需的最后一块符印掌握在他儿子手中。他深居在激流堡的一座由民兵控制的教堂里。加林王子的保卫措施非常严密，他本人也是一名强大的勇士，所以这次你的任务会是非常艰巨的。","小武哥儿"},
[645] = {"托卡拉尔","从激流堡的托尔贝恩墓室中取回托卡拉尔剑。","将四块符印放在一起，它们就能互相结合形成一块完整的符印。毫无疑问，这块符印能够击破托尔贝恩地墓室里的防护魔法。托尔贝恩的遗体就埋葬在激流堡教堂后的密室中。去取回托卡拉尔。","小武哥儿"},
[646] = {"托卡拉尔","把托卡拉尔剑交给落锤村的森古。","光芒慢慢地褪去，石鞘中的托卡拉尔剑已经松动了。","小武哥儿"},
[647] = {"马克里尔的月光酒","把马克里尔的月光酒交给南海镇的布鲁米·比格尔。","昨晚我喝了很多月光酒！要是布莱德知道我在当差的时候溜出去准会要了我的命。我喝得有些太多了，就感觉到头顶上有一整支蒸汽坦克部队呼啸而过，满耳都是隆隆的响声。哦，瞧这时间！我答应南海镇的布鲁米·比格尔要送他一些月光酒来抵债的。但是离我交货的最后期限只有15分钟了！请你把这些带给他，好么？要快！","小武哥儿"},
[648] = {"拯救OOX-17/TN！","护送OOX-17/TN到安全地点，然后向藏宝海湾的奥格索普·奥布诺提斯回报。","那个地精的声音再次从那个机器人中传了出来:“我需要你帮忙把OOX-17/TN移动到一个开阔的安全地点，这样它才可以启动起飞程式。它拥有内建的隐蔽系统，但是我需要一点时间从远端来启动这个系统。请你把这个机器人从现在的位置护送到时光之穴附近！那是个非常理想的起飞点，而且护送的路程也可以给我足够的时间来启动连线！”“将它安全地护送到那里，然后再到藏宝海湾来找我！奥格索普·奥布诺提斯─完毕！”","小武哥儿"},
[649] = {"寻找蜜酒","和奥格瑞玛的玛尔顿·杜佛斯谈一谈。","我这有些事情要你来做，如果你和我一样是蜜酒的爱好者，那我敢说你一定会接受这项任务！蜜酒当然是一种酒，你这个蠢货！在一座被部落废弃的村庄那里有很多的辛特兰蜜酒，这些蜜酒是以前那里还有人做生意的时候留下的，那绝对是极品的蜜酒！玛尔顿的手下知道这个村庄的具体位置，我要你去那里一趟，给我带一些蜜酒回来！和玛尔顿谈谈吧，他会给你进一步指示的。","小武哥儿"},
[650] = {"寻找蜜酒","和基沃拉丁·猎日者谈一谈，他的营地就在辛特兰区域。","你得去跟那个名叫基沃拉丁·猎日者的精灵谈谈。他只需闻一下就可以辨别任何一种葡萄酒！他可以帮我们弄到蜜酒。嗯……我们需要至少六瓶包装好的蜜酒，其中两瓶是给爸爸的，至于他实际上需要多少瓶倒无关紧要……当你打包好了蜜酒，并且搞到了给爸爸的两瓶蜜酒之后，就回到我这里来！基沃拉丁的营地在辛特兰的高等精灵大屋附近，不过那些高等精灵不太友善……相信我。","小武哥儿"},
[651] = {"禁锢之石","从西禁锢之石、东禁锢之石和外禁锢之石中搜集烈焰钥匙、海浪钥匙和雷霆钥匙。把它们带到内禁锢之石处。","在阿拉希高地上散布着4块禁锢之石，这些石头将我牢牢地钉在地下。要想解除它们，你就必须解除最坚固的那块：内禁锢之石。首先，你必须搜集到其它三块石头的钥匙。这些石头都有守护者在看守，但是如果你足够聪明或者足够幸运的话，就能找到消灭这些守卫的办法。","小武哥儿"},
[652] = {"打开钥匙之石","找到并杀死弗兹鲁克，然后把秩序魔棒带到阿拉希高地的钥匙之石旁。","禁锢之石的开启基本解开了这些束缚着我的东西，可还有一把牢不可破的锁让我无法动弹。你看到这圈石头中的那块钥匙之石了吗？开锁的钥匙在弗兹鲁克手中，他是囚禁我的巨人之一，也是这石锁的看护人。你必须从弗兹鲁克那里获得一把名叫“秩序魔棒”的钥匙来打开钥匙之石。你已经为我做了这么多，$n，只是再帮个微不足道的小忙……我会对你更加感激不尽的！","小武哥儿"},
[653] = {"密斯莱尔的盟友","和铁炉堡的葛利·硬骨谈一谈。","<密斯莱尔开始说话>自由！我自由了！我终于自由了，我要恢复力量，不过现在我还得躲避那些追捕我的敌人。因为如果他们现在找到我的话，肯定会轻松将我降服并重新监禁我。总有一天我会回到那些巨人的面前，让他们为禁锢我的行为而后悔！你是一个高尚的盟友，。我会再次需要你的帮助。等我准备好之后，我需要你来将我召唤到地表上。去和铁炉堡的葛利·硬骨谈谈吧，他知道如何召唤我。","小武哥儿"},
[654] = {"塔纳利斯的样本","收集8份蜥蜴样本、8份土狼样本和8份蝎子样本，然后在能量源耗尽之前把野外实验工具包还给加基森的安全主管吉罗姆·比格维兹。","启动能量源之后，野外实验工具包开始闪光和震动，看来它开始按照预定的程序工作了。根据首席工程师沙克斯·比格维兹所说的，你现在有两个小时的时间在塔纳利斯沙漠收集你所需的数据。如果你在两个小时内无法收集到全部数据，那么收集到的数据也将消失，而你则不得不重新从安全主管吉罗姆·比格维兹那里购买另外一个能量源。当你完成任务之后就尽快回到他那里。","小武哥儿"},
[655] = {"落锤镇","和落锤村的托尔甘交谈。","一切是那么的清晰，似乎就发生在昨夜……那么多年了，从来都看不到任何希望，却有重重的木枷和钢索将我们的族人束缚在这个可怕的地方。终于，终于！奥格瑞姆酋长回来解救我们了！他像座铁塔一样站在那里，穿着那套如午夜一般漆黑的战甲，将他的战锤高高举起。那……太恐怖了……那懦夫的一击居然击倒了我们最伟大的英雄。那个懦夫骑着战马，手持长矛向他刺去……我跪倒在地。哪里才有希望？哪里才有希望……","小武哥儿"},
[656] = {"召唤大地公主","到密斯莱尔水晶碎块去召唤她，然后打败她。搜出她身上的怪异镣铐，将其和密斯莱尔水晶碎块缚在一起。","你必须在密斯莱尔恢复力量之前打败她。否则，一旦等到她聚集到足够的能量，密斯莱尔就会向追捕她的人发起挑战！有一些人自信能控制住她，但是如果她真能被控制住，巨人们有必要先发制人把她囚禁起来吗？这是个疯狂的逻辑，难道不是吗？你必须在第一次和她接触的密斯莱尔水晶碎块那里将她召唤出来，然后打败她。在打败她之后搜出她身上的怪异镣铐，然后与密斯莱尔水晶碎块缚在一起。只有这样做才能再次将密斯莱尔囚禁起来。","小武哥儿"},
[657] = {"新的瘟疫？","和基恩洛谈一谈。","<奎艾开始仔细地阅读这份文件>这很有趣。看起来药剂师乔瑞尔正在格沙克农场里进行着一些危险的试验，很难说这和希尔斯布莱德有什么牵连，不过我看最好还是别让他得逞。你走了以后，我们看见有一些兽人跑了进来，不过我没有足够的实力去帮基恩洛的忙——她要到农场里去偷取乔瑞尔的那些还没有送往塔伦米尔的研究资料，你能协助她吗？","小武哥儿"},
[658] = {"新的瘟疫？","找到被遗忘者信使，把她的密封的信件交给格沙克农场里的奎艾。","是费恩让你来找我们的吧？我一点都不吃惊，那家伙总是担心这个担心那个的。我们监视这个农场已经有些时候了，基恩洛说她不久前看见有一个信使从那间小房子里走出来，往南边去了。她平时话有些多，不过在这种危险的地方，我总是相信她的直觉。嗯……你的追踪能力怎么样？我们认为那个信使可能是带着信去塔伦米尔了。如果你能弄到那些文件，就有可能帮助我们搞清楚在希尔斯布莱德所发生的那些怪事。","小武哥儿"},
[659] = {"新的瘟疫？","到阿拉希高地上的格沙克农场附近找到奎艾和基恩洛。","欢迎你，。我带着一群探险者到这里来调查最近发生的一些怪事。我在希尔斯布莱德有个堂兄，他最近杀掉了家养的那只名叫斯坦雷的狗，因为这只狗突然长得很巨大，而且还野蛮地攻击所有靠近它的人。我想这一定和亡灵有些关系，我们正在寻找能证明这个猜想的更多证据。我的两个同伴奎艾和基恩洛到阿拉希高地上的格沙克农场去了，最近这些天一直没有她们的消息。你能帮我找到她们吗？我越来越担心了……","小武哥儿"},
[660] = {"新的瘟疫？","保护基恩洛，直到她回到奎艾身边。","好了，。我已经准备好了。可以出发了吗？","小武哥儿"},
[661] = {"新的瘟疫？","到南海镇去找到费恩·奥德利克。","就算让基恩洛在旅店里睡上一晚，她也不会比现在看起来更健康。显然，你很好地保护了她。她从农场拿回来的这些东西至少能让费恩了解到在阿拉希高地附近究竟发生了些什么事情。为了确保你们的行动不会导致任何报复行动，我们会在这里继续留守一段时间。你愿意返回南海镇去和费恩谈谈吗？","小武哥儿"},
[662] = {"深海打捞","大副尼兹利克斯让你从处女号和银松之魂号中取回航海图和航海日志。","奥布里领船进入海湾，我们确信能在这里发现宝藏。先驱号安全靠岸，但是当处女号和银松之魂号靠近港口的时候，退潮开始了。此时发生了怪事！那两艘船撞上了什么东西……似乎是暗礁中的什么庙宇……它们很快就沉没了，这真是一场灾难。我们必须要在离开以前去取回他们的日志和航海图，这些有价值的信息绝对不能留给任何其他人！","小武哥儿"},
[663] = {"法迪尔海湾","和法迪尔海湾的奥布里船长交谈。","鲁鲁看见了一个小<种族>！鲁鲁总是待在哨所上！欢迎来到法迪尔海湾。奥布里船长说过，我们在这里待不了多久。我们只要搜集宝藏然后返回藏宝海湾就行了。但是鲁鲁认为我们要在这儿待很长很长的时间，我们失去了两艘船。可怜的银松之魂号和处女号！她们长眠在海底！鲁鲁说，如果你想在这逗留的话，就去和奥布里船长谈谈吧。","小武哥儿"},
[664] = {"船长的复仇","法迪尔海湾的斯迪加特船长要你去杀掉10个刺脊袭击者和3个刺脊巫师。","啊，多么可怕的生活！我本以为我再也不能像现在这样坐在火堆旁呼吸着新鲜的空气了！船员们为了拯救我那美丽漂亮的处女号尽了全力。愿神保佑他们，保佑他们的心灵。奥布里船长的船安全地进了港，可我们就没那么幸运了，大浪弄沉了我们的船。前一秒钟我们还漂浮在海上，转眼间就又被海浪吞没。而那些该死的纳迦还杀死了所有的幸存者！我逃到这里来，算是勉强保住了性命。我要让那些野兽去死！","小武哥儿"},
[665] = {"水下宝藏","护送菲兹索普教授到洞穴里去并平安返回。","既然我们已经整装待发，那么帮助奥布里先生寻找丢失的精灵宝藏就是当务之急了！在黑暗的海底，如果没有任何辅助手段的话，要想找到那些宝藏几乎是不可能的。博士做的潜水镜可以派上大用场，不过他要从山上的洞穴里弄些魔石来，好给他的潜水镜附上魔法。但是那座洞穴已经被诅咒了！只要我们靠近洞穴就会遭到伏击。你得掩护我，让我控制魔石的能量，将它注入到潜水镜里。","小武哥儿"},
[666] = {"水下宝藏","法迪尔海湾的德拉克里格博士要你去收集10块精灵宝石并在完成任务后归还寻宝潜水镜。","宝藏在海床上放了那么长时间，早已经被岩石包裹起来了。但是借助潜水镜中的魔法力量，你可以轻而易举地锁定这些宝藏。侏儒的创造能力实在是让人惊叹！那么你去把寻宝潜水镜借来用用，$n，看你能不能帮奥布里船长找回些丢失的宝藏。我可以潜游到那儿，可是……嗯……在这片安全而干燥的土地上，我有些重要的科学研究要做……嗯，是这样的。","小武哥儿"},
[667] = {"水下伏兵","在纳迦的攻击中保护沙克斯·奥布里。","太糟了，看来那些刺脊纳迦正在囤积重兵准备发动攻击。纳迦在作战时是出了名的冷酷无情，只要你还有一口气，他们就决不会停止攻击。我并不是说我自己的性命比弟兄们更宝贵，但你必须得保护我，因为如果没有我对大海的了解，弟兄们是不可能回到藏宝海湾去的。纳迦会从大海里向我们发起进攻，我要你留在这儿与我一起对抗他们，齐心协力把他们打退。你准备好了吗，$n？","小武哥儿"},
[668] = {"水下宝藏","把精灵宝石交给奥布里船长。","我们不要让奥布里船长等了。他急着想看到这些宝藏呢。这不正是我们在这儿的原因吗？和这些海盗们打了几个星期的交道以后，我和教授都意识到，手里拿着海盗的宝藏永远是不安全的。拿着这些，$n，把它们交给奥布里。","小武哥儿"},
[669] = {"水下宝藏","把精灵宝石样本交给藏宝海湾的舰队指挥官卡拉·海角。","舰队指挥官卡拉·海角一定想马上知道我们找到了什么。你也看到了，我们还不能离开这儿。不单单是因为潮水太低的缘故，还因为那些被我们惊动的可恶家伙正密切地注视着我们的一举一动。假如你能把口信带给藏宝海湾的舰队指挥官卡拉·海角，并告诉他我们已经发现宝藏的话，你可就帮了我们黑水海盗的大忙了。把这件东西交给舰队指挥官卡拉·海角，这样他就会确信你说的是真的了。","小武哥儿"},
[670] = {"水下宝藏","把海角船长的密信送给阿拉希高地的沙克斯·奥布里。","嘿，$n，看来你是个喜欢冒险的<种族>。在我们重新进货之前，我的船队会一直停泊在藏宝海湾。这里即将发生一些大事，我得找人把相关的绝密信息通报给在阿拉希海岸上的沙克斯·奥布里。你可以确保将口信安全而保密地送达吗？","小武哥儿"},
[671] = {"邪恶的魔法","帮落锤村的托尔甘找10枚血石护符。","我感觉空气中弥散着一种奇怪的东西……这种感觉在我的血液中不断升腾。对此我感到很奇怪，于是便着手去寻找给我造成这种不安的原因，然后我就在西边的诺斯弗德农场找到了一些邪恶的召唤法术留下的痕迹。当我慢慢地靠近时，我的热血开始沸腾，胸中的怒气不断上升。我在地上发现了一枚血石护符，那是用在恶魔召唤仪式中的东西。可是，我找到的这枚血石护符的能量已经被耗尽了。现在我需要再弄一些来研究，可我不敢回农场去了。你能帮我找一些来吗？","小武哥儿"},
[672] = {"振奋精神","从高地阔步龙和高地长尾龙身上取得10个高地迅猛龙的眼球，把它们交给落锤村的托尔甘。","我们把他安顿下来，不断地鼓舞他，向他讲述我们在卡利姆多建立伟大的奥格瑞玛城的故事，但所有的这些都无法打动他。关于我们年轻的酋长的故事，拥有奥格瑞姆的战甲和战锤的萨尔酋长……也许吧……也许吧！我们新发现的萨满魔法或许会带给他新的希望。这值得一试！我们可以给他一件小东西，对……给我带些迅猛龙的眼睛，我要看看我们能做些什么。","小武哥儿"},
[673] = {"邪恶的魔法","取回玛雷兹·考尔的血石宝珠，把它交给落锤村的托尔甘。","我确信有一个强大的术士居住在激流堡城内。这个术士经常通过一种魔法物品来召唤大量的恶魔。我们必须毁掉他的能量源泉。找到这个术士，杀掉他。把所有你在他身上发现的物品都拿来给我，我会设法销毁它的。我们绝对不能让这片大地再被玷污了！","小武哥儿"},
[674] = {"振奋精神","把迅猛龙利爪护符交给戈穆尔。","把这枚护符交给戈穆尔，看看迅猛龙的力量能否唤醒这位勇士的血管中曾经燃烧过的火焰。","小武哥儿"},
[675] = {"振奋精神","和托尔甘谈一谈。","<戈穆尔把护身符扔到了地上>托尔甘让你来的，是吗？呸！我不理解他为什么要怜悯我。在我不能和我的酋长一起战死的时候，我就不再接受任何怜悯了。我注定要被这残酷的命运煎熬……","小武哥儿"},
[676] = {"落锤之战","杀掉8个石拳食人魔和10个石拳执行者，然后去阿拉希高地的落锤村哨所找杜拉姆法尔。","软弱的家伙……他们全都是懦夫……你，<职业>，你在看什么？你觉得自己有什么特殊的么？怎么不去证明一下？阿拉希的落锤村哨所正受到攻击。再不增派援兵的话，他们就会全军覆灭的。不过在你去那里之前，是不是应该先试试看自己够不够格？阿拉希的激流堡东北部有个食人魔的营地，石拳氏族的食人魔就住在那里。等你搞定了那里的食人魔和执行者之后，再去向落锤村的杜拉姆法尔报告吧。","小武哥儿"},
[677] = {"短兵相接","杀死10名枯木掷斧者、10名枯木猎头者和8个枯木巫医，然后回到落锤村哨所的杜拉姆法尔那里。","枯木巨魔和阿拉希的石拳食人魔联合起来，要把我们赶出这片土地，但我们决不会把命运交给他们掌控！我们要除掉他们，让他们知道谁是这儿真正的主宰。巨魔背弃了我们，食人魔想要把我们当作美味的食物——我们决不能允许这种事情发生。现在，让我们从南边的枯木巨魔开始吧。去杀掉他们，让他们血流成河！","小武哥儿"},
[678] = {"短兵相接","杀死10个石拳蛮兵和4个石拳法师，然后向落锤村哨所的杜拉姆法尔复命。","，你的强大已经是有目共睹的了。现在让我们看看你如何去面对一个真正的敌人。从这里往西南走，在通往矮人修建的那座大桥的途中，有一个石拳食人魔的老巢。如果我没搞错的话，那儿的虐待者和法师对你来说应该是个难度不小的挑战——至少到现在为止对于我们来说是这样的。尽可能多地杀死他们，无论最终是胜利还是失败，无论回来见我的是你自己还是你的灵魂，我都会赞赏你在战斗表现出的坚韧精神。","小武哥儿"},
[679] = {"短兵相接","杀死7个石拳萨满祭司和3个石拳领主，然后向落锤村哨所的杜拉姆法尔复命。","，现在是时候和这些家伙算总账了……很明显你完全有能力帮我们完成这最后的一击。这些与我们为敌的蠢货的领导者已经在激流堡废墟里建立了巢穴。激流堡的废墟……那是人类软弱无能的最好证明！找到那些石拳领主和他们的萨满祭司，把他们全都杀掉，这些妄图将我们赶离家园的蠢货们活不了多久了！","小武哥儿"},
[680] = {"真正的威胁","杀死奥卡拉尔，将他的头颅带给落锤村哨所的科林法尔。","你帮我丈夫干得不错，<职业>，可他并不知道为什么落锤村会遭受攻击。奥卡拉尔是玛格萨尔派到激流堡去的走狗，他非常害怕我的丈夫。很多年前，我的丈夫打败了他，他巴不得我的丈夫早点死去。我占卜到奥卡拉尔给我的丈夫设下了陷阱，并且感觉到了那些食人魔正在伺机害他……如果他知道那些食人魔在哪里的话，一定会不顾三七二十一地杀过去。所以……请你帮我杀死奥卡拉尔吧。","小武哥儿"},
[681] = {"诺斯弗德农场","杀掉6个辛迪加雇佣兵和10个辛迪加路霸，然后回到避难谷地去向尼艾丝队长复命。","我们正在为激流堡而战，然而我们却逐渐落入下风。我们、食人魔以及辛迪加分别控制着这座城市的一部分，现在我们这三方势力陷入了整日互相征战却毫无突破的僵局。然而，当敌人们力量开始逐渐增强的时候，我们却在慢慢地变弱。我们需要南海镇的援助，但是辛迪加控制了我们和南海镇之间的领地，因此那边的补给很难运到这里来。到辛迪加在诺斯弗德农场的基地去干掉他们，也许这样做能让我们补给线上的压力大大减轻，然后才能有更多的物资平安运抵这里。","小武哥儿"},
[682] = {"激流堡徽章","把激流堡徽章交给位于避难谷地的尼艾丝队长。","我们的民兵分队正在和控制着激流堡的辛迪加成员激战。为了刺激他们那群乌合之众与我们作战，辛迪加的头目们使出了重金悬赏的手段，只要有人能杀死我们的民兵，并从他们身上缴获激流堡徽章，辛迪加都会给予奖励。我们必须夺回那些徽章——决不能让刽子手们用我们的战士的性命来换取金钱！到激流堡城内的辛迪加控制区去杀掉那些歹徒，取回我们的徽章。","小武哥儿"},
[683] = {"萨拉·巴鲁的请求","把萨拉·巴鲁的便笺交给铁炉堡的国王麦格尼·铜须。","$n，我对你有个小小的请求。这张便笺是我写给铁炉堡的国王麦格尼·铜须的。对于你这种曾为联盟的事业英勇作战的<种族>来说，这个任务再容易不过了。以我在现在这种状态去觐见国王陛下是很不合适的，我相信你应该可以理解。","小武哥儿"},
[684] = {"通缉：玛雷兹·考尔","把玛雷兹的头颅交给避难谷地的尼艾丝队长。","重金悬赏玛雷兹·考尔的项上人头。这个兽人是辛迪加组织的高级顾问和技工，人们最后一次看见她是在激流堡内的辛迪加控制区。赏金请到尼艾丝队长处领取。请注意：玛雷兹是一个强大而狡猾的术士，她和恶魔有着非常密切的联系。追杀她时务必非常小心。","小武哥儿"},
[685] = {"通缉：奥图和法库雷斯特","把法库雷斯特和奥图的头颅交给避难谷地的尼艾丝队长。","激流堡民兵团重金悬赏法库雷斯特公爵和他的保镖奥图的头颅。法库雷斯特是辛迪加在阿拉希地区的主要领导者，他的死将使该组织在这一地区的活动陷入瘫痪。他的保镖奥图不是我们的战略目标，但他生性凶残，已经杀死了许多激流堡的士兵。赏金请到尼艾丝队长处领取。","小武哥儿"},
[686] = {"国王的礼物","国王麦格尼·铜须让你去和大石匠玛布勒斯坦谈一谈。","象巴鲁夫人这样好心的矮人可能无法理解要忍受这场可笑的战争其实是为了我们族人更高的利益。无论是她的丈夫还是其他在战斗中献出生命的矮人，每次听到他们的名字都让我感到非常心痛。虽然我不能让她的丈夫死而复生，不过我可以向他致以崇高的敬意。我会委派大石匠玛布勒斯坦为苏利·巴鲁建造一座纪念碑。把口信带给他，<职业>。你来负责传达我的这条命令。","小武哥儿"},
[687] = {"迷失者塞尔杜林","找到迷失者塞尔杜林。","迷失者塞尔杜林曾经是我们暮光之锤的一员。但是有一天他突然精神失常，摒弃了我们的信条，背叛了我们的信仰。在背离我们之前，他还偷走了密斯莱尔卷轴！我们没能抓到他，但有传言说他就躲藏在荒芜之地中，整日胡言乱语，已经完全疯掉了。如果你要将公主带回来的话，就必须找到卷轴，而要找到卷轴，你就必须找到塞尔杜林。","小武哥儿"},
[688] = {"密斯莱尔的盟友","和落锤村的萨鲁克谈一谈。","<密斯莱尔开始说话>自由！我自由了！我终于自由了，我要恢复力量，不过现在我还得躲避那些追捕我的敌人。因为如果他们现在找到我的话，肯定会轻松将我降服并重新监禁我。总有一天我会回到那些巨人的面前，让他们为禁锢我的行为而后悔！你是一个高尚的盟友，。我会再次需要你的帮助。等我准备好之后，我需要你来将我召唤到地表上。去和落锤村的萨鲁克谈谈吧，他知道如何召唤我。","小武哥儿"},
[689] = {"国王的礼物","铁炉堡的大石匠玛布勒斯坦要5块奥特兰克花岗岩。","我们的国王要建一座纪念碑向一个叫苏利·巴鲁的士兵致敬？你是说那个可怜的士兵是在萨多尔大桥的悲剧中死的？唉，艾泽拉斯还会有和平吗？不管怎样，国王下达的任务就是第一要务。我要用最好的石头来建这座纪念碑，你到希尔斯布莱德的丘陵洞穴为我找一些奥特兰克花岗岩来吧。","小武哥儿"},
[690] = {"马林的要求","找到位于阿拉希高地上的避难谷地中的斯奎尔图。","你好，。我看出你是个渴望冒险的<职业>，现在我有项任务需要你的帮助。我原来的主人，大法师特雷莱恩，不久从位于阿拉希高地的激流堡里逃了出来。他让我到那里去帮他取回一些临走时落下的物品。激流堡现在已经陷入了重围之中，他在努力保卫阿拉索之塔，但是现在看来情况越来越危险了。我的人已经到了阿拉希高地，但他们需要更多的支援。你有兴趣去帮忙吗？","小武哥儿"},
[691] = {"证明实力","帮避难谷地中的学徒克里汀收集10个枯木巨魔的獠牙，4只枯木巨魔的医药包和1把暗影猎手的小刀。","，别怕斯奎尔图。他是因为事情太多才变得这么暴躁。在我们等他完成侦察任务的时候，为什么不做些更有意义的事情呢？马林派我到这里来为他收集一些试剂，对于如何收集这些物品，我感到很困惑。不过现在你来了，我想我的问题也解决了。我需要这些东西：枯木巨魔的獠牙，枯木巨魔的医药包和一把暗影猎手的小刀。你能帮我找到这些吗？枯木巨魔一般都在阿拉希高地的东南一带出没。","小武哥儿"},
[692] = {"遗失的卷轴碎片","把破损的卷轴碎片、弄皱的卷轴碎片和烧焦的卷轴碎片带给迷失者塞尔杜林。","密……密斯莱尔卷轴？！你要那东西干什么？它强大的魔法力量可以把密斯莱尔召唤到地面上来，那时候我们就有大麻烦了！也许……也许已经太迟了，也许她已经自由了。密斯莱尔可能正在为报复我们而聚集力量。如果是这样，那你就必须掌握着这至关重要的卷轴！……太糟了，它被毁掉了。愤怒的元素生物偷走了卷轴，并将它撕成了碎片。现在它们又在为这些碎片争斗不休。如果你能搜集那些碎片的话，也许我们还有希望将它修复成原来的样子……","小武哥儿"},
[693] = {"特雷莱恩的符咒魔杖","帮避难谷地的斯奎尔图找到特雷莱恩的符咒魔杖，并把它带回来。","你好啊，，很抱歉我以前对你那么凶……我可以断定特雷莱恩的第一件宝物的所在：它在石拳大厅的考格雷什手里。顺便说一句，他已经可以使用冰爆术来教训不听话的手下，看来离他完全掌握魔杖力量的日子也已经不远了。石拳大厅就在这里的南边，萨多尔大桥的东边。从那个食人魔手里把那根魔杖拿回来吧。在你回来之前，我要想想我们要怎样解决激流堡的问题。","小武哥儿"},
[694] = {"特雷莱恩的防御","找到一块碧蓝玛瑙石，把它交给避难谷地处的学徒克里汀。","休息好了吗？我们的下一步计划和激流堡的阿拉索之塔周围的食人魔有关。我们必须首先开启这座塔的防御系统，当然，前提是你能活着到达存放那些物品的地方。为此，首先我们需要一些石拳萨满祭司经常携带着的宝石。他们把宝石从塔里带了出来，但他们没有什么机会占有这些宝石了。从他们那里弄一块宝石，把它送去给克里汀——他能够给宝石附魔，这样一来，宝石就可以当钥匙用了。","小武哥儿"},
[695] = {"学徒的魔法","和斯奎尔图谈一谈。","拿着宝石吧，$n。只要将宝石放置在塔基的任何一个支撑脚上，就能激活阿拉索之塔的防御。当你准备进入塔中寻找特雷莱恩的其余物品时，就使用这颗宝石。祝你好运，我将在营地里等你回来。哦，对了，在你离开之前别忘了去和斯奎尔图谈谈，他会告诉你一些你必须了解的细节。","小武哥儿"},
[696] = {"进攻高塔","找到特雷莱恩的护符匣、特雷莱恩的宝珠和特雷莱恩的黑玛瑙，把它们交给避难谷地的斯奎尔图。","以下是你要找的东西：特雷莱恩的护符匣、特雷莱恩的宝珠和特雷莱恩的黑玛瑙。所有这三样东西应该都在塔中的箱子里，你打开这些箱子应该不会有什么问题，只是要当心那些食人魔就成。阿拉索之塔的防御不会作用于那些食人魔，因此你必须时刻准备战斗。如果那些食人魔发现你在偷他们的东西，你就少不了一场恶战。多加小心，祝你好运。","小武哥儿"},
[697] = {"马林的要求","将给大法师马林的信交给暴风城法师区里的大法师马林。","把这封信送到暴风城去，让马林知道我和克里汀很快就可以回家了。对于你给我们的帮助，马林一定会好好回报你的，，对于这一点我深信不疑。祝你旅途顺利。","小武哥儿"},
[698] = {"缺乏补给","给悲伤沼泽的托克卡尔带去8块新鲜的盐齿鳄鱼肉。","我正努力为我们在东边海滩那里的哨所收集一些补给品，托克卡尔已经尽了他的全力。但他又要值勤，又要为他的士兵们做饭，一天这么下来就没什么时间了。他们很喜欢吃盐齿鳄鱼的肉，但我没时间为他们再送去一批补给了。你能帮我这个忙吗？盐齿鳄鱼幼崽的肉不如成年鳄鱼的口感好，所以你别猎杀小鳄鱼，等它们长大了再吃它们也不迟。","小武哥儿"},
[699] = {"缺乏补给","给悲伤沼泽的托克卡尔带去6只盐齿钳嘴鳄的爪子。","我们之所以被部署在这里，是为了警戒在这片海岸附近出没的鱼人，以防它们——或者任何其它什么东西——威胁到斯通纳德，当然，要是他们太嚣张了点的话，我们也会去给它们一些颜色看看。这工作可不轻松，我们几乎很少有自由的时间，所以只好拜托你来帮忙了，当然，我是说如果你愿意的话。加工得当的盐齿钳嘴鳄的爪子可以用来制作精良的武器，给我带些它们的爪子回来，我就会送你一件精致的武器作为酬谢。","小武哥儿"},
[700] = {"国王的礼物","向铁炉堡的国王麦格尼·铜须汇报。","啊，洛丹伦的石头真不赖，可惜那儿已经变成一片废墟了。纪念碑完成了！我想国王陛下一定会满意的。如果你愿意的话，请替我去告诉国王陛下，纪念碑已经完成了。","小武哥儿"},
[701] = {"迅猛龙的狡诈","从高地猎兽龙身上获取12颗迅猛龙的心脏，把它们交给托尔甘。","只要借助一些特别的物品，我就能创造出一件注入了迅猛龙的狡诈力量的东西！这样就应该能让戈穆尔了解到我们新的能量，并重新找回潜藏着的勇士的力量！我需要迅猛龙的心脏来完成这件物品和法书。","小武哥儿"},
[702] = {"迅猛龙的狡诈","把托尔甘的宝珠交给戈穆尔。","拿着这颗宝珠，用它的能量来给戈穆尔灌入迅猛龙力量的精髓。这一定会让他的精神备受鼓舞，并给予他新的生活目标。当他恢复正常之后，我们就可以向他说明部落现在的状况，在我们永无止境的战斗中，这位伟大的战士也将帮上大忙。","小武哥儿"},
[703] = {"烧烤秃鹰翅膀","给里格弗兹带去4只秃鹫的翅膀。","哦，当然，烧烤秃鹰翅膀是我的最爱！酱汁浓郁，肉香扑鼻，香味能把数公里外饥饿的野兽都给吸引过来！我有能做一顿美味佳肴的一切原料，呃……还差点秃鹫翅膀！如果你想尝尝我的手艺，就去帮我弄些秃鹫翅膀来。尽量多弄点，没准我一高兴就把烹饪方法一并教给你！","小武哥儿"},
[704] = {"阿戈莫德的命运","收集4个雕纹石罐，把它们交给洛克莫丹的勘察员基恩萨·铁环。","阿戈莫德送来的最后一份报告让我感到十分困惑，现在他死了，我就更难受了！他提到挖掘队在奥达曼附近的挖掘场找到了一些“远古的石罐”。我担心是他找到的罐子影响了石颚怪，就像这里发现的小石像一样。我要你去找到那些罐子，把它们拿回来以供研究。到奥达曼挖掘场去收集那些罐子吧，完成之后再回到我这里来。","小武哥儿"},
[705] = {"潜水采珍珠","收集9枚蓝珍珠，把它们交给荒芜之地的里格弗兹。","荒芜之地是一个无比荒凉的地方，是凶残的捕食者和食腐动物的乐园。这里的一切都令人感到恐慌，尤其是对于我这样的小个子地精来说。为了生存，我不得不机灵些！我知道闪光弹的制作方法，也常用它来吓走野兽。不过，作为原料之一的蓝珍珠粉快要用完了。你能不能帮我找些蓝珍珠回来？当然我会给你足够的报酬。呵呵，这个东西并不是那么好找的，恐怕你得走不少的路了。我所需要的蓝珍珠可以在暗礁海的牡蛎身上找到。对，就是位于荆棘谷的那个暗礁海。","小武哥儿"},
[706] = {"黑龙之火","为西格鲁·铁斧拿到一颗黑色幼龙之心。","作为费拉诺·钢趾的学徒，我从他那里学会了赋予武器强力魔法的特殊技能。我最后一次听到他的消息时，他正和从洛丹伦过来的狩猎小队合伙工作。我不能告诉你关于这种技术的太多细节，但可以告诉你必须要用黑龙血来完成这个附魔过程， 而且一定要是从黑色幼龙那仍在跳动的心脏中涌出的血液。我现在除了等待铁炉堡的消息以外无事可做，所以如果你能从莱瑟罗峡谷帮我带一颗黑色幼龙之心回来，我就向你展示一下我的技术！","小武哥儿"},
[707] = {"铁环挖掘场需要你！","和洛克莫丹铁环挖掘场的勘察员基恩萨·铁环谈一谈。","。洛克莫丹的勘察员基恩萨·铁环从他的挖掘场给我送来报告，说是需要为我们的另一项挖掘计划外出搜集一些情报。我就知道这么多了，如果你愿意活动一下筋骨，就去和基恩萨·铁环谈谈吧。","小武哥儿"},
[708] = {"黑盒子","把遗失的货物交给军需官朗格尔斯。","这只木桶不大，但非常坚固。木板的接缝处和桶盖边上都用一种味道刺鼻的黄色封蜡封了起来。桶底的标签上写着两行大字：军需官朗格尔斯守望堡","小武哥儿"},
[709] = {"化解灾难","把雷乌纳石板带给迷失者塞尔杜林。","天哪……天哪！厄运就要降临了。它已经朝我而来了！厄运就要降临了！不，我不能说……不能说出他们的名字，否则会被他们听到的！但是，如果我们……如果我们对他们有更多了解的话……也许我们就可以知道如何击败他们！也许……到奥达曼去。不！我说过！你必须找到……找到雷乌纳石板……对，找到它！别让我再提到那个名字！它深藏在那里，就在一个古代的箱子里……这个箱子甚至比矮人族群的年代还要久远……","小武哥儿"},
[710] = {"研究石元素","收集10块小石头碎块，把它们交给荒芜之地的鲁特维尔·沃拉图斯。","在荒芜之地，我停下了所有手头的事情来专注于我的最新项目：元素禁锢镣铐。这些镣铐一旦完成，就可以让法师们在更广的范围内召集更加强大的元素生物。首先，我需要些小石头碎块，来检验我最新的攻击性咒语和小发明。你可以从西面那里的次级石元素身上收集到这些碎片，能给我弄一些来吗？","小武哥儿"},
[711] = {"研究石元素","收集3块大石片，把它们交给荒芜之地的鲁特维尔·沃拉图斯。","，你的能力超过了我所有学徒的总和。我所需的下一个部分需要花些功夫。只要你稍加留心，就能在石元素身上找到一些大石片。他们的身体更加庞大，因而会有足够大的碎片来供我试验。你可以在西边远一点的地方或者东南方的山地边缘找到它们。不用太着急，测试你带来的小石头碎块还需要花些时间。","小武哥儿"},
[712] = {"研究石元素","收集5个石缚护腕，把它们交给荒芜之地的鲁特维尔·沃拉图斯。","，我还需要从荒芜之地的元素生物身上弄一些东西：巨型石元素身上的护腕。据我估测，那些护腕完全可以检验出我的镣铐所具有的力量。我的占卜显示，在西南边有一批巨型石元素。我想起来了，那附近好像还有一些食人魔。给我带5个护腕来，我想5个就足够了。阿布总是放错我的试剂和实验品，这方面它的名声可不太好。","小武哥儿"},
[713] = {"至关重要的冷却剂","找到冰霜之油，把它交给荒芜之地的鲁特维尔·沃拉图斯。","让我来告诉你些有关冰霜之油的事情吧：没有别的什么东西能够像它一样防止发动机或者齿轮过热。它的冷却性能和润滑效果无与伦比。不仅如此，它还有助于保存附着在魔法物品上的魔力。我需要一小瓶冰霜之油以加强镣铐的魔力，好让它们足够强大，不然我可没法阻止那些被召唤来的“朋友们”对我们大开杀戒。我在奥特兰克有一个名叫布洛金的地精朋友，他能教你制取冰霜之油的方法。","小武哥儿"},
[714] = {"发条式什么什么仪","给荒芜之地的鲁特维尔·沃拉图斯带去一个发条式同步协调陀螺仪。","，你所做的一切都是超一流的。<鲁特维尔的注意力显然从工作中移开了>如果我们曾在卡拉诺斯见过，你随时都可以来申请工作。哎呦！快抓住……对，那个。谢谢。我现在还需要一件东西。虽然是件小东西，但是也非常关键的东西，它就是精密的发条式同步协调陀螺仪。如果你能帮我找一个的话，我就能完成工作啦。","小武哥儿"},
[715] = {"卢希恩的药水","为荒芜之地的卢希恩·枪穗找到一瓶次级隐形药水和一瓶治疗药水。","我想你为鲁特维尔找的那些东西会不会给我们带来什么麻烦，。另一方面，你已经在帮助鲁特维尔神圣的科学研究的过程中体现了超凡的才能，那么帮帮我如何？我需要一瓶隐形药水和一瓶治疗药水。如果他的进展一切顺利，这两件东西都必须及时到位。作为报酬，我会给你这个配方，它是我向鲁特维尔求学时，在鲁特维尔长期以来在荒芜之地的研究成果的基础上开发出来的。","小武哥儿"},
[716] = {"有备无患","给荒芜之地的卢希恩·枪穗带去一些青铜花纹护腕。","我知道鲁特维尔疯狂起来会有多么危险，你最好让我给你制作一些装备以防万一。也许它能保护你免受鲁特维尔新发明的折磨。我一直都在研究那些你给他找来的石头，所以我想我能造出一些不错的护腕来供你使用。嗯，它们当然都是附有魔法的。我只需要一些铁匠打造的青铜花纹护腕就可以帮你造出附魔的护腕了。","小武哥儿"},
[717] = {"大地的震颤","用大地印章激活钻石柱、玛瑙石柱和紫水晶石柱并拿到三颗符石。把符石放在大地封印上，释放黑龙布莱克拉什和赫玛图斯。杀了这两条黑龙，把布莱克拉什的锁链、赫玛图斯的锁链和大地印章交给加瑞克。","显然，我们不能保证黑龙布莱克拉什和赫玛图斯仍能被囚禁在莱瑟罗峡谷里。大批黑龙盘踞在那里的现状以及食人魔试图偷走大地印章的事实说明后面将会有更可怕的事情发生。黑龙的监狱由三块符石维持着，只有使用大地印章才能得到它们，而那些符石就是打破封印的关键。$n……我们要确保那些黑龙的梦想永远无法成真。","小武哥儿"},
[718] = {"饥肠辘辘","帮西格鲁·铁斧找回补给箱。","在匆忙撤出奥达曼挖掘场的途中，我们不得不丢弃了很多补给物资，那些柯什营地里的食人魔像兀鹫看见了腐烂的尸体一样疯狂地掠夺我们扔掉的物资，呃，那些家伙闻起来也和晒了好几天的尸体没什么区别……不管怎么说，他们抢走了我们装着武器的马车，而且现在……现在的状况实在是只能用窘迫两个字来形容了——我们现在几乎什么吃的都找不到了。就连腌菜也要吃光了，你看……能不能帮我们弄点什么吃的来？","小武哥儿"},
[719] = {"矮人的工具","找到雷杜尔的好运锄，把它交给铁趾挖掘场南边的勘察员雷杜尔。","你好，<职业>。千万要小心四周。这里到处都是黑铁矮人，似乎都是属于暗炉氏族的。他们刚刚袭击了我们的挖掘场……杀死了那里几乎所有的人，包括我的老板铁趾格雷兹，只有我侥幸逃了出来。挖掘场在这里的北面，我想找回我们的一些物资，尤其是我的好运锄。你能帮帮我吗？如果找不到其它的，至少帮我找回我的锄头吧。","小武哥儿"},
[720] = {"一线希望","找到勘察员雷杜尔，告诉他铁趾格雷兹还活着。","<在地图上有一行用粉笔潦草写下的文字>“雷杜尔，\n他们把我带到了奥达曼，请速来援助。\n——铁趾”","小武哥儿"},
[721] = {"一线希望","在奥达曼找到铁趾格雷兹。","，你能找到他吗？你能在奥达曼找到铁趾吗？如果那些卑鄙的暗炉矮人将他抓为人质是为了获得他掌握的有关泰坦的信息的话，铁炉堡就有大麻烦了。很久以来，黑铁矮人一直在寻找可以制造出威力更大的作战傀儡的魔法。铁趾也在寻找这样的魔法，但他的目的仅仅是为了阻止他们。估计在套出重要情报之前，他们是不会杀了铁趾的。你要抓紧时间，尽快救出铁趾！","小武哥儿"},
[722] = {"铁趾的护符","找到铁趾的护符，把它交给奥达曼的铁趾。","你很勇敢……<咳嗽>……为了我来到奥达曼，<职业>。如果你真要帮助我……那么……<咳嗽>……你就必须找到……帮我找到我的护符。它在……马格雷甘·深影的手里。他就在这附近……肯定在这片废墟上。如果你不能阻止他的话，那枚护符将会引导他……<咳嗽>……找到卷轴。，就看你的了。请……拿到那枚护符。卷轴一旦落入黑铁矮人的手里……一切就都太晚了……","小武哥儿"},
[723] = {"铁趾的遗愿","把铁趾的护符交给荒芜之地的勘察员雷杜恩。","<铁趾捂着伤口，老半天才缓过劲来，他接着说道>找到雷杜恩，……把护符交给他。<猛烈的咳嗽>他……<咳嗽>知道该怎么办。雷杜恩知道我一直在寻找我们种族的起源，他也……<咳嗽>知道阻止暗炉氏族是我的使命。不能让他们找到卷轴……<咳嗽>","小武哥儿"},
[724] = {"铁趾的遗愿","把铁趾的护符交给铁炉堡的史学家卡尼克。","好吧……谁知道下一步该做些什么？史学家卡尼克！没错！他就在铁炉堡里。我想我们可以从他那里寻求一些帮助。铁趾和他曾经共同在奥达曼挖掘古代神器，估计暗炉矮人已经对他们的底细了如指掌了。去把铁趾的不幸遭遇告诉卡尼克，然后把护符交给他——他会告诉你该怎么办。","小武哥儿"},
[725] = {"亡者的警告","找到顾问贝尔格拉姆，把便笺交给他。","，你赶快去找顾问贝尔格拉姆，把你看到的一切都告诉他，问问他我们下一步该怎么做。这封信会让他了解的消息。与此同时，我会和铁趾的亡灵交谈，也许他所知道的事情能够帮助我们解决那帮暗炉氏族的家伙带来的麻烦。让我们祈祷吧。","小武哥儿"},
[726] = {"亡者的警告","和史学家卡尼克谈一谈。","<顾问贝尔格拉姆读到信的结尾，他的眼睛瞪大了好一会儿。>哎哟，这真是太可怕了。，你回去告诉史学家卡尼克，赶快以国王的名义对这一事件采取行动。他必须制止暗炉矮人在荒芜之地的所作所为！","小武哥儿"},
[727] = {"远赴铁炉堡","把战锤印章交给铁炉堡的葛利·硬骨。","石板说明了不少问题，但这还不够，远远不够！有这么一本书，它是雅格因在若干年前写的笔记，上面记载着一些……我想方设法要避开的人……他们在世界各地都珍藏着这本书的复制本。而他们中最有学问的人也一直在研究它，因为它包含着极其丰富的知识……可以让我们免遭灾难的知识！到铁炉堡去找葛利·硬骨，把徽章拿给他看看，他就会相信你是他们中的一员。向他要到雅格因的笔记……然后马上把它交给我！","小武哥儿"},
[728] = {"远赴幽暗城","把战锤印章交给幽暗城的看守者贝尔杜加。","石板说明了不少问题，但这还不够，远远不够！有这么一本书，它是雅格因在若干年前写的笔记，上面记载着一些……我想方设法要避开的人……他们在世界各地都珍藏着这本书的复制本。而他们中最有学问的人也一直在研究它，因为它包含着极其丰富的知识……可以让我们免遭灾难的知识！到幽暗城去找看守者贝尔杜加，把徽章拿给他看看，他就会相信你是他们中的一员。向他要到雅格因的笔记……然后马上把它交给我！","小武哥儿"},
[729] = {"健忘的勘察员","到南边去一趟，看看勘察员雷姆塔维尔现在处境如何。","首席考古学家杜瑟·灰须派我在伟大的勘察员雷姆塔维尔的指导下进行工作，这对我来说是无上的荣誉。在铁炉堡学院时，每个人都知道雷姆塔维尔有许多伟大的发现。不过这位伟大的勘察员实在是……嗯……有些健忘……他常常对周围的一切都浑然不觉。我们刚刚发现了一座大型的古代城镇，但是突然间，可怕的傀儡从地下蜂拥而出，占据了那里。不过雷姆塔维尔似乎还没有发现这一点，我跑回奥伯丁就是为了找人去救他。请到南边去一趟，看看伟大勘察员是否还一切安好！","小武哥儿"},
[730] = {"黑海岸的麻烦事","到奥伯丁去寻找矮人挖掘队的线索。","很高兴见到一个对我们伟大的考古事业有如此浓厚的兴趣的。我们的工作经常被联盟中的其他朋友当成是矮人的休闲活动而不被理解，但是很多人都没有意识到，最近在卡兹莫丹一带的发现证实，一股强大的势力正威胁着从洛丹伦到卡利姆多的整个世界。我很担心那些到黑海岸去考古的兄弟们，他们有好几个星期都音信全无了。到奥伯丁去找找看有没有关于他们的线索吧。","小武哥儿"},
[731] = {"健忘的勘察员","在勘察员雷姆塔维尔搜寻神秘化石的时候保护他，然后回到奥伯丁的考古学家霍莉那里。","好吧，那么，霍莉……哦，不对，你不是霍莉。霍莉去哪儿啦？不说这个了，那不是我们要讨论的话题。我们必须找到那把石刷……我是说神秘的化石！我们必须找到化石。达纳苏斯的探险者协会希望能看到我的工作进展情况。如果你准备好了，就和我说一声，我们去寻找那把刷子……我是说化石！我们要找到一些能让协会满意的东西。你准备好了吗？","小武哥儿"},
[732] = {"大地的震颤","帮加瑞克取回大地印章。","我听西格鲁说，你在过去几天帮了他的大忙。现在我也需要你的帮助。我的主人，肯瑞托的大法师克拉苏斯派我来结束莱瑟罗峡谷的混乱局面。我不能透露这次任务的确切性质以及我要完成的使命，但是这个任务真的非常重要。有一伙四处游荡的食人魔偷走了一件名叫大地印章的东西，我必须要把它拿回来。如果你能帮我找到它，我就让你知道更多的消息。","小武哥儿"},
[733] = {"搜集行动","帮西格鲁收集7块金属碎片。","如果不能弄到一些物资来建构防御工事和其它的必要设施，我们在这里的处境就会非常糟糕。我发现这个地区的食人魔居然有许多金属碎片，也许传说在荒芜之地出没攻城坦克不久之后也会出现……无论如何，勘察员对我们营地的状况非常担忧，所以我要尽早开工。食人魔的主营地就在火山洞穴，从这里往西一直走就能找到。","小武哥儿"},
[734] = {"不祥的感觉","和荒芜之地的卢希恩·枪穗谈一谈。","太好啦，太好啦。<鲁特维尔看了你一会儿，又去摆弄他的镣铐了>去找卢希恩吧，。跟他说我需要一个5号齿轮。你能把它拿来给我吗？","小武哥儿"},
[735] = {"星，手，心","找齐葛利·硬骨的便笺上列出的东西，然后把它们交给铁炉堡的葛利·硬骨。","雅格因的笔记？你要它干什么？没关系，我不该问这个。我会帮你的，因为我这里还有一本。我们得互相帮助，对不对？这样我们才能各自获利。我需要三件宝物，把它们给我拿来，我就给你那本笔记。我不会说出它们的名字，因为可能有人正在偷听，不过我可以把这几个名字写下来。","小武哥儿"},
[736] = {"星，手，心","把贝尔杜加的便笺上列出的东西带给幽暗城的看守者贝尔杜加。","你需要雅格因的笔记？一整本？当然……当然我会帮助你，我的$g兄弟:姐妹;。但你也得帮我。我需要三件威力强大的物品，把这些物品给我找来，笔记就是你的了。我不能把它们的名字说出来，不过我可以给你写下来。把这个单子上的东西找来，如果你能完成这个任务，那么你就有能力接到更重要的工作。","小武哥儿"},
[737] = {"禁断的知识","把雅格因的笔记交给塞尔杜林。","$n，我这里有你想要的笔记，我想不需要我再提醒你要保管好它了吧？特别是绝对不要让它落入敌人之手。这本书里记录了很多真相…………可以毁灭你的真相。","小武哥儿"},
[738] = {"寻找阿戈莫德","找到阿戈莫德。","勘察员阿戈莫德曾是荒芜之地的挖掘场负责人，就是西南边的那座挖掘场。我说“曾是”，是因为……嗯，最近几周我都没有得到他的任何消息。请你帮我找到阿戈莫德并拿到他的报告。我最后一次得到的消息是：阿戈莫德在荒芜之地最南边的挖掘场——那是苦痛堡垒附近的一个不起眼的小地方。你先去那里找找看吧。","小武哥儿"},
[739] = {"莫达洛克","干掉杀害阿戈莫德的凶手：莫达洛克。顺便杀掉12个石窟断骨者。然后向洛克莫丹的勘察员基恩萨·铁环报告。","阿戈莫德留下的足迹表明他是从西边走过来的。从沙石上的斑斑血迹不难看出，矮人阿戈莫德爬行了好一段距离。爬到这里的时候，他终于被死神带走了。经过仔细察看，你在旁边的沙石中发现了几个潦草写下的字迹：“莫达洛克”。字迹就在阿戈莫德的手边。","小武哥儿"},
[740] = {"<UNUSED>","","This quest will take players into the Searing Gorge.Stay tuned……","小武哥儿"},
[741] = {"健忘的勘察员","把神秘的化石交给达纳苏斯的首席考古学家杜瑟·灰须。","勘察员雷姆塔维尔要把神秘的化石送给达纳苏斯的探险者协会？可是我不太想把他一个人留在这里。给你，$n，把这块神秘的化石交给达纳苏斯的首席考古学家杜瑟·灰须。","小武哥儿"},
[742] = {"灰谷狩猎","与灰谷碎木哨岗的塞娜尼·雷心谈一谈。","年轻的冒险者们，注意了！灰谷的野兽正在等着你们！部落在贫瘠之地以北的区域建立了强大的基地。我们的两个前哨站——碎木哨岗和佐拉姆海岸哨岗——正在努力地为部落的荣耀而战！想要证明自己能力的勇士就到那儿去吧。碎木岗哨位于贫瘠之地的正北方，塞娜尼·雷心正在那里招募愿意参与灰谷狩猎中的冒险者！","小武哥儿"},
[743] = {"风怒鹰身人","给血蹄村的卢尔·鹰爪带回8只风怒鹰身人的爪子。","谢谢你抽时间来和我谈话，。我是鲁尔，既是一个战士，也是一个导师。如果你想在莫高雷之外经历更多冒险的话，现在正是让你接受更多考验的时候了。如果你想测试自己的能力，就去东南方找风怒鹰身人作战吧。他们驻扎在山边远离大路的地方。鹰身人是我们的天敌，对你来说，和他们战斗会是个不错的考验。","小武哥儿"},
[744] = {"准备典礼","收集6根碧蓝色的羽毛和6根古铜色的羽毛，把它们交给雷霆崖的伊恩·鹰爪。","，我的兄弟很快就要去面见血蹄酋长了，我要为他做一个头饰，这对我来说是一种荣耀。在我处理这些皮革的时候，你能不能帮我一个忙？我没有时间去收集足够的羽毛，不知道你能否帮助我去收集一些呢？你应该可以在雷霆崖北面和西北面的鹰身人身上找到尺寸合适的羽毛。我需要6片碧蓝色的和6片古铜色的羽毛来完成我的头饰。","小武哥儿"},
[745] = {"土地之争","杀死10个白鬃制革工、8个白鬃剥皮工和5个白鬃偷猎者，然后回到血蹄村向凯恩·血蹄复命。","这片土地上有很多纷争，。我希望你不会像我一样经历那么多的战争，不过我还是希望你去做一件事，让你可以了解到，一个看似不值一提的小小威胁如果不加制止的话，会对我们的领土带来多大的危害。白鬃豺狼人已经在西边的一个洞穴中和血蹄村的南边扎了营。我们曾试图和他们交流，却被他们无理地拒绝了，而且他们还大肆屠杀莫高雷的野生动物。现在语言已经不能解决问题了，我们必须有所行动。","小武哥儿"},
[746] = {"矮人的挖掘场","收集5个勘察员的锄头。在铁匠铺砸碎这些勘察员的锄头。把5件损坏的工具交给血蹄村的凯恩·血蹄。","西北部有些矮人正在准备修建一座挖掘场。他们认为地下埋藏着某些秘密，事实也的确如此，不过挖掘和污染大地并不是获得这些秘密的正确途径。收集矮人的挖掘工具，把它们全都毁掉，然后把这些被损坏的工具带给我。要毁掉这些工具的话，你必须得找到一块铁砧才行。在雷霆崖就有一处铁匠铺，不过任何铁砧——包括矮人营地里的——都可以用来毁掉工具。","小武哥儿"},
[747] = {"开始狩猎","纳拉其营地的格鲁尔·鹰风要求你带给他7片平原陆行鸟的羽毛和7块平原陆行鸟肉。","欢迎来到纳拉其营地，$n。你来到这里的消息很快就传遍了氏族。或许很快有一天你会被迎去雷霆崖上的大城市里，但首先，你必须先向我们证明你的能力。我们这些生活在红云台地上的牛头人无疑对自己优秀的狩猎技术最为自豪，当然，牛头人只为生存需要和竞技而狩猎。我们库存的肉已经不多了，另外我们还需要羽毛来做衣服。现在去猎杀附近的平原陆行鸟来给村庄提供补给吧，同时你也可以借此证明自己的能力。","小武哥儿"},
[748] = {"毒水","收集6只草原狼的爪子和4只平原陆行鸟的爪子，把它们交给血蹄村的穆尔·雷角。","那些地精和他们的爪牙污染了我们神圣的水井！我们必须制止他们！要想净化所有的水井，我得先制造出相应的净化图腾，然后你把图腾拿到水井那儿去完成净化的仪式。首先，我们给冰蹄之井制作一个净化图腾，这需要大地的帮助。去猎捕一些草原狼和成年平原陆行鸟，把它们的爪子带回来给我，它们就在西南方活动。","小武哥儿"},
[749] = {"被破坏的货车","摩林·云行者要你去查看被破坏的货车附近的储备箱里有什么东西。","几天前，我们在石牛湖北岸发现了有一个被重兵保护着的风险投资公司的马车。我们在先前的战斗里已经失去了两个同伴，所以我们就把怒气倾泻在这辆马车身上，速战速决地把它给摧毁了。我们没去管他们的储物箱，满以为一把火就可以把这些东西和马车一起烧成灰。不过有人在那辆熊熊燃烧的货车附近看见了风险投资公司的抢救人员，那些箱子可能没被烧掉。也许你可以去那辆货车旁，看看箱子里面到底是什么。","小武哥儿"},
[750] = {"继续狩猎","纳拉其营地的格鲁尔·鹰风要求你带给他10张山狮皮。","善于狩猎的牛头人从不仅仅将他的猎物看作战利品，这些生活在平原上的野兽对我们的生存有着极为重要的意义。如果你能带回一些珍贵的山狮皮的话，就会令氏族里的长老们对你刮目相看。你可以在南边的山区找到它们。我们的孩子需要衣服，氏族里的帐篷也需要维修了。","小武哥儿"},
[751] = {"被破坏的货车","把风险投资公司文件交给血蹄村附近的摩林·云行者。","撬开盖子之后，你发现了堆得满满的矿石，这又一次证明了风险投资公司确实在莫高雷地区有采矿活动。在矿石的最上面有一捆文件。你可以依稀听见东部丘陵的顶部传来丁丁当当的声音，还可以看见从一大堆篝火上升起的浓烟。","小武哥儿"},
[752] = {"一件琐事","鹰风酋长要求你去纳拉其营地东南方的水井处寻找他的母亲。","我们氏族的所有成员都过着完美和谐的生活，我们一起劳作，一起生活。氏族中的每个成员都对其他人负有义务，并且我们总是将这些义务放在首位。现在我需要你帮我做一件麻烦的事情。我的母亲今天早上去纳拉其东南方的水井中取水，她已经去了很久了。你能不能替我去看看？氏族里的事务让我实在抽不开身。","小武哥儿"},
[753] = {"一件琐事","在井边拿一只水罐。把它带给纳拉其营地里的鹰风酋长。","我这一生也算是经历了不少磨难，走了不少路，现在我这一把老骨头也没什么力气啦。我仍然在为氏族尽力，但有些时候，我还真感觉有些力不从心。不过，你这<职业>似乎是正想找点什么事情做做呀。正好，让我来看看你的体力如何吧。把水井旁的这个水罐交给我儿子，他就在纳拉其营地里。记住，即使是最琐碎的小事，只要你做得够好，也能获得长老们的首肯。","小武哥儿"},
[754] = {"净化冰蹄之井","用冰蹄之井净化图腾为冰蹄之井完成净化，然后回来见穆尔·雷角。","我已经做好了可以净化冰蹄之井的图腾。现在你就把它拿到那儿去完成净化仪式。冰蹄之井就在东南边，有许多地精把守着那里！这不是个简单的任务，不过如果我们想要重新使用那里的水，就必须得这么做。祝你好运，。","小武哥儿"},
[755] = {"大地之母仪祭","找到居住在纳拉其营地正南方山中的灰舌先知。","你愿意为纳拉其的牛头人做这样琐碎的小事，同时又渴望学习新的知识，这足以说明你有着高贵的品质，$n。我相信总有一天你会成为一位在雷霆崖赫赫有名的<职业>。不过在那之前，你必须首先完成大地之母仪祭，这个伟大的传统共由三个不同的试炼组成。第一个试炼是力量之仪祭。去找灰舌先知，告诉他是鹰风酋长派你去的。翻过纳拉其营地正南方的山后，你就可以找到他的居所了。","小武哥儿"},
[756] = {"雷角图腾","收集6个草原捕食者的爪子和6个平原狮的爪子，把它们带给穆尔·雷角。","要制作雷角之井净化图腾，你必须先去收集莫高雷平原上的肉食动物的爪子。去捕猎草原捕食者和平原狮，然后把它们的爪子带回来见我。它们就在这里的东边和西边活动。","小武哥儿"},
[757] = {"力量仪祭","杀掉刺刃峡谷的刺背野猪人并带回12条刺背腰带，把它们交给纳拉其营地的鹰风酋长。","大地之母仪祭对于每一个想要在雷霆崖得到尊重的年轻牛头人来说都是非常重要的。但在那之前，你必须先通过力量仪祭的试炼。在这个试炼中，你必须通过杀死氏族的敌人来证明你的勇猛。生活在东边的刺刃峡谷中的刺背野猪人侵占了我们氏族不少的土地，他们偷袭我们的狩猎小队，还在晚上到村子里来偷东西。杀死他们，展示出你的英勇无畏吧。拿着它们的腰带去见纳拉其营地的酋长，他将证明你通过了试炼。","小武哥儿"},
[758] = {"净化雷角之井","在雷角之井使用雷角之井净化图腾，然后回来见穆尔。","图腾已经准备好了，。这一次还是由你来完成净化仪式。到村庄北面的雷角之井去，用雷角之井净化图腾完成净化仪式，然后再回来找我。愿大地之灵指引你。","小武哥儿"},
[759] = {"蛮鬃图腾","收集8颗草原狼前锋的牙齿，把它们交给血蹄村的穆尔·雷角。","还剩下一口井需要净化，它是以蛮鬃氏族的名字命名的。要想净化这口井，你必须从大地上寻找一种凶猛的肉食动物的牙齿，那就是草原狼前锋的牙齿。去北边寻找草原狼前锋，拿到我要的东西之后再回来。这些草原狼前锋经常在雷霆崖的山脚下游荡。","小武哥儿"},
[760] = {"净化蛮鬃之井","在蛮鬃之井使用蛮鬃之井净化图腾，然后回来见穆尔·雷角。","你净化冰蹄之井和雷角之井的事迹已经被广为传诵了，年轻的。我也已经做好了蛮鬃之井净化图腾，接下来这就是你的最后一个任务了。蛮鬃之井在雷霆崖的北面，到那里完成净化仪式吧，拯救这片被地精污染的土地，让这片土地上的生灵再次畅饮甘甜纯净的井水！","小武哥儿"},
[761] = {"猎捕猛鹫","收集8根猛鹫的羽毛，把它们带给血蹄村的哈肯·风之图腾。","猛鹫是一种狡猾无比、很难猎捕的鸟。收集猛鹫的羽毛可以证明一个猎手的智慧和决心。如果你想接受这个任务，就去平原上猎捕猛鹫吧。把它们的羽毛带给我，为你的氏族赢得荣誉。猛鹫在莫高雷的任何地方都能找到，不过要发现它们，你得有锐利的眼睛；要捕捉它们，你得有灵活的手脚。","小武哥儿"},
[762] = {"邪恶的使者","杀死苦痛堡垒中的因弗努斯大使，把证明他已死亡的信物交给铁炉堡的顾问贝尔格拉姆。","拉格纳罗斯派因弗努斯大使到苦痛堡垒去监督暗炉矮人在奥达曼挖掘神器的工作。我们的同胞已经遭受了惨重的伤亡，然而这样的情况仍然在继续。我不愿去猜测他们会找到多少强大的神器并用它们来对付铁炉堡。我们的目的很简单，<职业>。回到荒芜之地去，干掉因弗努斯大使。在除掉了这个威胁之后，把你完成任务的证据交给顾问贝尔格拉姆。现在马上出发吧。","小武哥儿"},
[763] = {"大地之母仪祭","顺着离开纳拉其营地的路将鹰风图腾带给血蹄村的凯恩·血蹄。","要想继续大地之母仪式，你必须先通过两个小试炼。现在也正好是你去积累积累经验的时候了，$n。到血蹄村去找那里的酋长，凯恩之子凯恩·血蹄吧。你可以在那儿继续你的冒险历程并得到雷霆崖的长老们的承认。把这个图腾带给贝恩。他会读懂我刻在上面的符号，并帮助你继续修行。顺着这条从纳拉其营地通向外面的路快点出发吧，千万别迷路了。","小武哥儿"},
[764] = {"风险投资公司","血蹄村的摩林·云行者要你去杀死14个风险投资公司工人和6个风险投资公司主官。","这就解释了为什么风险投资公司在不断往莫高雷地区增派职员和设备。这些地精……他们的公司扩张得太快了。就像他们自己所说的那样，只要给地精一点甜头，你就能听到他们打算盘的声音。这些小东西实在是太贪婪了。不过我们牛头人决不会让他们在我们的领土上为所欲为。到他们的矿洞去，给他们点颜色看看，那个矿洞就在被破坏的货车的东北方。","小武哥儿"},
[765] = {"菲兹普罗克主管","杀掉菲兹普罗克主管，把他的笔记板带给血蹄村的摩林·云行者。","根据你从箱子里拿来的文件可以看出，风险投资公司已经制定了很多把我们从这儿赶走的计划，然后他们就能随心所欲地掠夺我们的土地了。他们为了利润居然可以堕落到这种程度，这简直让我感到厌恶和惊骇。我们要除掉这个阴谋的策划者，他就是菲兹普罗克主管。你可以在被破坏的货车以东的风险投资公司矿洞里找到他，把他的笔记板带给我，让我们看看有没有什么有价值的东西。","小武哥儿"},
[766] = {"马兹拉纳其","收集草原狼的心脏、平原狮的腿骨、平原陆行鸟的鳞片和猛鹫的胃各一份，把它们交给血蹄村的茂尔·祈雨。","我祖父曾讲述过他和一只叫马兹拉纳其的陆行鸟战斗的故事，说起过它那邪恶的红眼睛，剃刀般锋利的爪子，只要被它咬一口，你就会身中剧毒。在我穿越平原的时候，正巧遭遇了它，肩膀被它咬了一口。它比我祖父所说的还可怕！我需要一些东西来帮我解毒：一颗狼心，狮子的腿骨，平原陆行鸟的鳞片和猛鹫的胃。快点，我快要不行了。","小武哥儿"},
[767] = {"幻象仪祭","和血蹄村的扎尔曼·双月谈一谈。","作为大地之母仪祭之一的幻象仪祭可以指引你最终赢得雷霆崖长老们的尊重。我们早已认识到，土地就是我们最神圣的生命之本。如果你准备好要进行幻象仪祭的话，就得去和村里的精神领袖扎尔曼·双月谈一谈。","小武哥儿"},
[768] = {"收集皮革","收集12块轻皮，把它们交给雷霆崖的维尔伦·陆行者。","你好，年轻的<种族>。我从你的眼中看到了你重回原野捕猎的渴望。希望你能为你的氏族带来荣耀！我擅于利用各种兽皮来为雷霆崖的居民制作护甲和衣物。如果你能帮我搞到一些兽皮的话，那我就可以用它们来为你制作一些你需要的东西。","小武哥儿"},
[769] = {"科多兽皮包","给雷霆崖的维尔伦·陆行者带去4块轻皮和4份粗线。","莫高雷的科多兽强壮而凶猛，它们的这些特质备受我们尊敬。如果你善于皮革加工，而且希望获得制作科多兽皮包的知识，那就给我弄点材料来吧。弄些材料来，我就会把我的手艺传授给你。","小武哥儿"},
[770] = {"恶魔之伤","去打听打听谁听说过鬼嚎。","鬼嚎那粗糙的毛皮上还留着一个可怕的伤口，是在它与燃烧军团的战斗中留下的。也许你应该把鬼嚎的死讯告诉血蹄村里的什么人……","小武哥儿"},
[771] = {"幻象仪祭","收集2块水井石和2个琥珀颗粒，把它们带给血蹄村的扎尔曼·双月。","要想通过幻象仪祭，你必须先找到制作先知之水的试剂。我需要一些水井石，你可以在莫高雷一带的水井附近找到它们。另外，你还得在这周围的大树下面找到一些琥珀颗粒。这两种东西都具有强大的元素力量，把它们结合起来，用氏族之火点燃之后，你可以看到一个幻象。追随它，它就会引领你进入这个神圣使命的下一个阶段。","小武哥儿"},
[772] = {"幻象仪祭","在血蹄村的氏族之火前将先知之水喝下，当幻象出现之后跟随它。","现在，我把神圣的先知之水交给你。准备好了之后，就去氏族之火旁把水喝下，然后稍等片刻，一个幻象就会出现在你的眼前。你必须立刻决定是否要追随这个幻象……","小武哥儿"},
[773] = {"智慧仪祭","到雷霆崖东边的赤色石去和先祖之魂谈一谈。","要让雷霆崖的资深长者接受你，你就必须再完成大地之母仪祭的下一个阶段：智慧仪祭。你已经通过了幻象仪祭，赤色石的先祖之魂会祝福你的，只有那些喝过先知之水的人才能得到这种祝福。向雷霆崖的东面去，到赤色石寻找先祖之魂吧。","小武哥儿"},
[774] = {"<UNUSED>","","","小武哥儿"},
[775] = {"雷霆崖之旅","和雷霆崖的凯恩·血蹄谈一谈。","任何能够完成大地之母仪祭的<种族>都可以赢得整个雷霆崖的尊重。你的最后一个任务是去见见我们的伟大首领凯恩·血蹄，他就住在雷霆崖最高的那座台地上。","小武哥儿"},
[776] = {"大地之母仪祭","雷霆崖的凯恩·血蹄要你将阿兰其亚的角带给他。","你已经通过了大地之母仪祭，在雷霆崖赢得了你自己的一席之地。不过要维持你现在获得的荣誉，你还必须不断证明你自己的价值。我们生来就是猎手，$n。在莫高雷城下有一只非常强大的科多兽，我们称它为阿兰其亚。把它的角带来，向我证明你追踪和捕猎的能力。","小武哥儿"},
[777] = {"不祥的感觉","把5号齿轮交给鲁特维尔·沃拉图斯。","好吧，拿去吧。我现在要去找个掩体……你要不要一起来？","小武哥儿"},
[778] = {"不祥的感觉","击败法姆雷托守护者，并将鲁特维尔的元素禁锢镣铐交还给鲁特维尔。","哈哈！完成啦！镣铐完成啦！记住这个时刻，卢希恩,记住这个时刻，阿布！你准备好了吗？你将亲眼看见炼金术、工程学和魔法的完美结合。我将召集一个强大的元素生物。今天，对于我们来说，是具有里程碑意义的一天！","小武哥儿"},
[779] = {"大地封印","","","小武哥儿"},
[780] = {"斗猪","纳拉其营地的格鲁尔·鹰风要求你去干掉斗猪，并带给他8块斗猪头和8块斗猪肋排。","生活在东边的刺刃峡谷中的斗猪已经侵占了我们氏族的狩猎场。正在与我们交战的刺背野猪人把这些野猪训练成了凶暴而富有攻击性的生物。去把这些可恶的家伙杀掉，再带些猪头和肋排回来，我们可以炖肉给孩子们吃。","小武哥儿"},
[781] = {"纳拉其营地的危机","将刺背野猪人的进攻计划交给纳拉其营地的鹰风酋长。","在仔细查看了地图之后，你意识到刺背野猪人的酋长正计划着对纳拉其营地展开进一步攻击。鹰风酋长必须马上得知这个消息。","小武哥儿"},
[782] = {"破碎的联盟","杀掉索格伦，把大地印章交给卡加斯的高恩。","在第二次兽人战争期间，部落与死亡之翼之间曾有过盟约，我们也因此得知死亡之翼的两个副手——黑龙布莱克拉什和赫玛图斯——现在正被囚禁在莱瑟罗峡谷里。如今我们要让堕落的昔日盟友们“安静”一点，我们要恢复部落的荣耀。我们雇佣了索格伦和他的食人魔雇佣兵团帮我们夺回大地印章，也就是那把可以打开黑龙监狱的钥匙。然而，索格伦背叛了我们，他打败了我们，将大地印章占为己有。","小武哥儿"},
[783] = {"身边的危机","与治安官玛克布莱德谈一谈。","我希望你已经整装待发了，年轻的<职业>。北郡需要你的帮助！当然，我不是在说让你去耕田种地之类的。暴风城的卫兵们努力地维持着这里的和平，但我们人手短缺，更多的危险还在不断迫近。我们正在招募愿意出力保卫家乡和联盟的人。如果你也是应招而来的话，请和我的上级——治安官玛克布莱德谈谈。他就在我身后的这座修道院里。","小武哥儿"},
[784] = {"背信弃义的人类","杀死10个库尔提拉斯水手和8个库尔提拉斯水兵，再把本尼迪克上尉干掉，然后回剃刀岭向加索克复命。","库尔提拉斯的人类曾在普罗德摩尔将军的率领下大举进攻杜隆塔尔，彻底破坏了在共同抵抗阿克蒙德和他的恶魔大军时由酋长和吉安娜·普罗德摩尔定下的互不侵犯协议。我们击退了人类的进攻，并攻下了提拉加德城堡。但最近，由本尼迪克上尉率领的后备军又重新占领了提拉加德城堡，对我们的家园构成了新的威胁，这些人类从不遵守外交协议。到南方的提拉加德城堡去消灭那些人类侵略者，证明你的勇气和荣誉。","小武哥儿"},
[785] = {"协助盟友","在森金村的西侧找到拉尔·猎齿。","萨尔是一位十分睿智而高贵的首领。他在战场上的勇猛善战和他在外交上的高瞻远瞩一样卓越不凡。暗矛部落的食人妖一直以来都是兽人的坚定盟友。为了表示忠诚和荣誉，我们之间签订了协同防卫的契约。大酋长已经下达了命令，要保证我们在森金村的食人妖朋友们不会遭到任何直接的威胁。他们最值得信任的斥候之一拉尔·猎齿已经在密切注意他们村庄西侧的状况。去找拉尔，并根据情况协助他。","小武哥儿"},
[786] = {"科卡尔半人马的进攻","在森金村外面的拉尔·猎齿要求你粉碎科卡尔峭壁内的三份进攻计划。","小声点，<职业>。科卡尔半人马就在西边科卡尔峭壁的山脊上。昨天晚上，我潜入了他们的村庄，发现这些肮脏的野兽准备同时向杜隆塔尔的巨魔和兽人发动三波攻势。我们决不能让他们的入侵计划得逞！你可以召集一些兵力，潜入科卡尔峭壁并粉碎他们的进攻计划。他们已经把进攻计划分别交给了三个首领，准备由他们率领三股部队同时行动。","小武哥儿"},
[787] = {"新的部落","与高内克谈一谈。卡尔图克在你的地图上标出了他的位置，并告诉你高内克居住在西边的大兽穴中。","你终于长大啦，……你可以以部落的名义参加战斗了，为酋长的荣誉而战吧！嗯……<卡尔图克打量了你一番。>你会很出色的。毫无疑问，你的目标是找到一条巨龙或是一个恶魔，然后赤手空拳地打败它，但是从比较弱的对手开始可能是个比较明智的选择。<卡尔图克笑了起来。>去向高内克报告吧，他可以为你这样的年轻指派一项适合你的任务。你可以在西边的大兽穴中找到高内克。","小武哥儿"},
[788] = {"小试身手","杀掉10只杂斑野猪，然后向大兽穴里的高内克报告。","第一项任务将在力量方面对你进行考验。我本来可以把你派去贫瘠之地猎杀科多兽，不过呢，照实说，你活着比死了对我们来说更有用。我相信你更合适和那些杂斑野猪斗一斗，往北边走就可以找到它们。","小武哥儿"},
[789] = {"工蝎的尾巴","给大兽穴中的高内克带回10根工蝎的尾巴。","无论是强大的战士还是笨拙的新手，都有可能会倒在蝎尾上的毒针之下。在这里的西北方有大量蝎子在活动，给我带10条蝎尾回来，以此来证明你的战斗能力吧。事实上，它们尾巴上的毒针正是制作解毒剂的重要材料，解毒剂便是从毒针中提取的。我们需要长期备有大量的解毒剂，以防止像你这样的新手被蝎毒所害……但我肯定你是不会需要这种玩意的，对吧？","小武哥儿"},
[790] = {"萨科斯","杀死萨科斯并将它的爪子带回去交给哈纳祖。","！我差点就神不知鬼不觉地死在这鬼地方了！我在谷里捕猎蝎子的时候，突然看到一只看上去特别凶恶的蝎子。当时我就决定以它为猎物，打算在它那硕大的钳子钳住我的腿以前，先重重地给它来上那么一下子。但我忘记了它还有根毒刺，毒刺猛扎了下来，一下子就刺进我的胸口。拜托，你一定得替我报仇！只有这样才能留存我的名誉！我是在南边的高地上碰上它的。","小武哥儿"},
[791] = {"新的背包","剃刀岭了望塔中的弗恩·凝眉想要8块帆布脚料。","我太老了，已经没法上战场拚杀了。所以我开始用别的途径为部落出力，实现我的价值。我在这里监视周围的情况，我们的力量越来越强大，我吹起号角的机会也越来越少。为了打发时间，我经常给那些保卫家园的年轻战士们做些有用的东西。我可以给你做一个用来放置财物的包袱，但是你得先给我找些帆布脚料来，人类和半人马经常使用这种布料。","小武哥儿"},
[792] = {"邪灵劣魔","杀死12只邪灵劣魔，然后向大兽穴外的祖雷萨复命。","我相信你会在试炼谷学到很多东西，年轻的<职业>。我本是被派到这处谷地里来指引和教育你们的，但我却在这里发现了一些不洁之物……一群自称为火刃氏族的兽人潜入了试炼谷，他们躲进了东北方的一处洞穴里，而他们的邪灵劣魔则肆虐着周边的一大片地区。作为你对抗火刃氏族的第一个任务，我命令你消灭这些劣魔。尽可能地多杀一些，如果杀完了它们之后你还活着的话，就回来向我复命。","小武哥儿"},
[793] = {"破碎的联盟","用大地印章激活钻石柱、玛瑙石柱和紫水晶石柱并拿到三颗符石。把符石放在大地封印上，释放黑龙布莱克拉什和赫玛图斯。杀了这两条黑龙，把黑龙布莱克拉什的锁链、赫玛图斯的锁链和大地印章交给高恩。","大地印章由三块符石控制，它们分别被放置在莱瑟罗峡谷的钻石柱、玛瑙石柱和紫水晶石柱中。用大地印章就可以取下符石并打开大地封印。当心点，$n，黑龙布莱克拉什和赫玛图斯是很难对付的。杀掉它们，把它们身上的锁链交给我。","小武哥儿"},
[794] = {"火刃奖章","给大兽穴外的祖雷萨带回火刃奖章。","我通过预言术发现在火刃集会所的深处藏有一件蕴涵着强大力量的物品，它被一些猛兽和黑暗的魔法守卫着。那件物品叫作火刃奖章，你的下一个任务就是找到它，把它从集会所里偷出来。不过你可得小心，因为奖章的所有者可能是一个火刃部落中的强者，他也许要比你以前对付过的那些家伙要强上许多倍。现在就出发吧，，那个洞穴就在这里的西北方。","小武哥儿"},
[795] = {"大地封印","","","小武哥儿"},
[796] = {"<UNUSED>","","","小武哥儿"},
[797] = {"<UNUSED>","","","小武哥儿"},
[798] = {"<UNUSED>","","","小武哥儿"},
[799] = {"<UNUSED>","","","小武哥儿"},
[800] = {"<UNUSED>","","","小武哥儿"},
[801] = {"<UNUSED>","","","小武哥儿"},
[802] = {"<UNUSED>","","","小武哥儿"},
[803] = {"<UNUSED>","","","小武哥儿"},
[804] = {"萨科斯","将哈纳祖目前的状况告诉大兽穴内的高内克。","看见你为我这么一个素不相识的可怜家伙做了这么多事情，我突然又坚强了起来。我绝不能就这么轻易地死在这种地方！我得坚持下去！可现在我还是不能自己回到大兽穴去。$n，请你再帮个忙，回大兽穴向高内克报告一下我现在的情况。","小武哥儿"},
[805] = {"去森金村报到","与森金村的加德林大师谈一谈。","你在这山谷中的针对火刃氏族的试炼……如今就算是完成了。但我希望你能去向其他人报告一下你的发现。到森金村去找加德林大师吧。先从山谷的东侧出去，在岔路口转向右一直走到底就能抵达森金村了。我们必须把火刃氏族的势力出现在试炼谷的事告诉加德林大师。去吧，，动作要快。恐怕我们在火刃集会所中找到的东西只是更可怕的威胁的预兆而已……","小武哥儿"},
[806] = {"黑暗风暴","把费索的爪子带给剃刀岭的奥戈尼尔·魂痕。","，我有个不妙的消息。对火刃氏族的调查表明，杜隆塔尔境内还有不少这个氏族的势力。这是我们绝对不能允许的！在他们站稳脚跟、滋生邪恶之前，我们必须把他们消灭掉。有个名叫费索·暗雷的地精术士就居住在西北部的雷霆山里，他和他的那群爪牙就在那里制造混乱。去干掉他，再把他的爪子带回来给我！","小武哥儿"},
[807] = {"<UNUSED>","Bring 5 Scorched Hearts to Orgnil Soulscar in Razor Hill.","My scouts report that some of the Durotar wildlife have become infected with a demonic taint.  They were seen to the north and west.They wander among their brethren as normal beasts, but evil powers flow through them, and burning within each one is a","小武哥儿"},
[808] = {"明希纳的颅骨","到回音群岛上去，将岛上法阵中的明希纳的颅骨带回来，交给森金村的加德林大师。","我在梦中听到了我兄弟明希纳的呼唤。回音群岛上的术士扎拉赞恩抓走了他，折磨着他，最后残忍地害死了他。但即使是死亡也没能让我的兄弟得到安宁，因为扎拉赞恩用邪恶的魔法把明希纳的灵魂困在了他的颅骨中。我在梦中看见…我兄弟的颅骨和其他人的颅骨一起被堆在回音群岛中最大的那座岛上的法阵中。只要他的头骨还在那儿，他的灵魂就无法得到自由。请你帮助他吧，。找到那个邪恶的法阵，把明希纳的颅骨带回来给我，让他的灵魂获得自由吧！","小武哥儿"},
[809] = {"雅克塞罗斯","到贫瘠之地去和雅克塞罗斯谈一谈。","自从我们在上一次大战中击败燃烧军团之后，我一直在寻找潜藏在兽人中的恶魔势力的源头。你带来的项圈证实了我的担忧。这个项圈属于火刃氏族，这帮恶魔的信徒正在凭藉着一件被称作恶魔之种的器物重整旗鼓。你可以在鬼雾峰山顶的贫瘠之地找到恶魔之种，一定要把它毁掉！到贫瘠之地边境西边的前沿哨所去找我的助手雅克塞罗斯吧，他会给你进一步的指示。","小武哥儿"},
[810] = {"<UNUSED>","Bring 6 Small Scorpid Carapaces to Kor'ghan in Sen'jin Village.","You would do well to learn how dangerous this land can be, <职业>.The wildlife here can teach us such things…… if we are wise and observant.The scorpids are a perfect example of survival in Durotar. If you are to survive, it would be wise to take on","小武哥儿"},
[811] = {"<UNUSED>","Bring 8 Large Scorpid Carapaces to Kor'ghan in Sen'jin Village.","One of the other traits of the scorpids is their fierce loyalty. They will protect one another if they are in danger--you've probably already seen this behavior in your first scorpid hunt.You would do well to heed that lesson and adapt it for yourself","小武哥儿"},
[812] = {"救命如救火","找到毒尾蝎的解毒剂，把它交给杜隆塔尔西北边境的林纳格。","……你来得真是时候，快救救我……我在毒尾蝎战斗的时候一不小心被蛰伤了，毒液正在不断侵蚀我的血液。看样子…我最多再撑一个小时就得玩完了，我想请你帮个忙…奥格瑞玛的考格汉知道怎么做解毒剂，快去找他…，我…我支持不了多久了……","小武哥儿"},
[813] = {"寻找解毒剂","收集4个毒尾蝎的毒囊，把它们交给奥格瑞玛的考格汉。","林纳格不随身带着解毒剂就去抓毒尾蝎是很不明智的行为，不过现在说这些也于事无补。赶快到奥格瑞玛城的城门外，在那一带的毒尾蝎身上给我找4个毒囊回来，这样我才能给他做解毒剂。动作快点，。我们自己的同胞命在旦夕！","小武哥儿"},
[814] = {"<UNUSED>","Bring 10 Chunks of Boar Meat to Cook Torka in Razor Hill.","Cook and clean--that's all I do！You want to eat, you get me some more meat！ I don't have all day to hunt and prepare food for all these louses. You got to learn to pull your own weight around here if you wanna be treated equal.Get me some Chunks o","小武哥儿"},
[815] = {"恐龙蛋大餐","收集3个鞭尾龙的蛋，并把它们带给剃刀岭的厨师托尔卡。","啊呀！我差点忘了还得做早饭！，快去给我找点鞭尾龙的蛋来，至少得要三个蛋才够明天做饭用。血爪鞭尾龙非常凶猛，而且会拚命地保护自己的蛋。有时它们会把蛋深深地埋在地下让你找不到，不过在森金村东南方的回音群岛上，这些鞭尾龙的蛋满地都是。","小武哥儿"},
[816] = {"丢失的孩子","把关于克鲁恩的消息告诉剃刀岭西北部农场中的米莎·托克伦。","，请帮帮我吧！我的儿子克鲁恩几天前到西边的怒水河畔捕猎鳄鱼，却一直没有回来，我现在觉得不妙了。尽管他十分强壮，但他的固执和自尊常常让自己陷入麻烦。我警告过他，鳄鱼是强大而凶猛的动物，可他一听就火了，掉头就走。如果你找不到他，至少也请给我带来一些关于他的消息，不管是好的还是坏的……就算把怒水河畔每只鳄鱼的肚子剖开也要找到点什么。","小武哥儿"},
[817] = {"生活所需的虎皮","收集四张杜隆塔尔虎皮，并把它们交给森金村的维尔林·长牙。","我们的兽皮大多取自生活在杜隆塔尔地区的老虎身上，。我们捕猎这些野兽的原因很多，比如毯子、护甲，还有帐篷什么的；同样，还有许多原因让我们允许它们继续繁衍生息。但是现在，我们有必要再杀掉一些老虎了。我们的人数在增加，而库存的兽皮也已经开始供不应求了，因此我需要更多兽皮来为他们制作各种生活用品。给我找四张杜隆塔尔猛虎的毛皮来，我会给你一些奖赏的。","小武哥儿"},
[818] = {"沃纳尔大师","把4个龙虾人的眼睛和8小瓶蟹胶带到森金村，交给沃纳尔大师。","虽然我的视力不断衰退，但我还是可以看得足够清楚。我曾经可以很轻易地施放强力的魔法，而现在我更多时候必须依靠炼金术的帮助才行。不过我不收学徒，因为我从来没有看到过任何够格的巨魔或兽人。你是合适的人选吗？当然，你当然是……你当然以为自己合适。我需要一点东西，你能帮我拿来吗？我要一些龙虾人的眼睛和几瓶蟹胶，你可以在杜隆塔尔的海蟹或龙虾人身上找到这些东西，找齐了之后再来见我。","小武哥儿"},
[819] = {"老陈的空酒桶","找到对老陈的空酒桶有所了解的人。","张贴在酒桶一角的纸条上写着：“老陈 - 祝汝精神得提升，祝汝精神永提升。”","小武哥儿"},
[820] = {"<UNUSED>","Bring 8 Shimmerweed to Master Vornal in Sen'jin Village.","Truly a spirit of strength resides in your body--or maybe it was only luck, yes？That is what the young rely on these days: luck…… and the generosity of those more powerful than they. Not many take the time to find their own path. It's always begging","小武哥儿"},
[821] = {"老陈的空酒桶","收集5颗草原狮的獠牙、5个平原陆行鸟的肾脏和1根雷霆蜥蜴的角，把它们交给棘齿城的酿酒师德罗恩。","你想尝尝老陈的雷霆佳酿吗？哈哈，这东西可是很带劲的哦。老陈把酿酒术教给了我师傅，我师傅又传给了我。去帮我找一些酿酒的材料，然后你就会得到物有所值的回报！帮我带5颗草原狮的獠牙、5个平原陆行鸟的肾脏和1根雷霆蜥蜴的角回来，然后我就可以酿酒了。这些东西都可以在贫瘠之地找到。","小武哥儿"},
[822] = {"老陈的空酒桶","收集5个闪电腺、1个雷鹰的唾液腺和1个科多兽的肝脏，把它们交给棘齿城里的酿酒师德罗恩。","雷霆佳酿的味道不错吧？我从老陈那里还学到了另一种酿酒术，你有兴趣吗？酿造这种酒不需要花太多的时间，如果你愿意冒险弄到些原料就成了。帮我弄五个雷鳞蜥蜴的闪电腺、一个巨型雷鹰的唾液腺和一个居住在贫瘠之地上的科多兽的肝脏来。我说过，这种酒很正点，就是我和你提到过的洞穴麦酒。","小武哥儿"},
[823] = {"向奥戈尼尔报告","和剃刀岭的奥戈尼尔·魂痕谈一谈。","我们森金村这边还有许多棘手的问题要解决，非常感谢你的帮助。但是你带来的消息说明火刃氏族也许对所有人来说都是个大麻烦。剃刀岭那里有一处兽人营地，奥戈尼尔·魂痕就在那里负责监视火刃氏族那一类的邪恶势力。去跟他谈一谈，跟他说说我们目前的情况，还有你从试炼谷得到的消息，他肯定会大吃一惊的。剃刀岭就在这里的北边。","小武哥儿"},
[824] = {"大地之环的耶努萨克雷","将被污染的水球交给灰谷佐拉姆加前哨站的耶努萨克雷。","大地之环是个萨满祭司的团体，他们致力于研究和保护自然界中的元素。他们忘掉的关于上古之神的知识可能比大多数学者知道的还要多。你很幸运，我认识灰谷的大地之环的成员。到佐拉姆海岸边上的佐拉姆加前哨站去，向耶努萨克雷展示你找到的这个东西。如果有谁对这颗水球的重要性有所了解的话，那么非他莫属了。","小武哥儿"},
[825] = {"海底沉船","剃刀岭的加索克要你从海岸边的舰队残骸中打捞出3件侏儒的工具。","我得到消息说普罗德摩尔舰队的残骸仍在杜隆塔尔的近海，就在提拉加德城堡的东边。与人类结盟的侏儒是一群粗俗的小东西，但是他们掌握着先进的机械技术。我们必须对任何潜在的敌人都了如指掌，同时我们的族人也可以从这些新知识中受益。$n，潜到那些沉船中，给我拿来联盟使用的工具。","小武哥儿"},
[826] = {"扎拉赞恩","打败扎拉赞恩。杀死8个巫毒巨魔和8个妖术巨魔。把扎拉赞恩的头颅带给加德林大师。","巫医扎拉赞恩就住在东边的回音群岛上，那些岛屿曾经是我们的家园。扎拉赞恩从那里不断派出他的爪牙来到这边的大陆上，用妖术控制我们的同胞，将他们也变成扎拉赞恩的傀儡。我们必须阻止他。打败扎拉赞恩和他的爪牙——那些曾经是我们的朋友和亲人的暗矛巨魔。把扎拉赞恩的头给我带回来，作为你已经斩杀了这个恶魔的证明。","小武哥儿"},
[827] = {"骷髅石","在骷髅石中的火刃祭司身上收集灼热项圈，然后交给玛高兹。","。火刃氏族就躲在奥格瑞玛东部的骷髅石山洞里。他们在洞中进行邪恶的仪式，用灼热项圈去燃烧自己的身体。我相信他们戴上这些项圈之后便会获得恶魔的力量，不过如果要确定这一点，我还得收集一些项圈来做研究。到骷髅石去，从那些火刃祭司身上找些灼热项圈给我，让我来揭开他们的秘密。","小武哥儿"},
[828] = {"玛高兹","和玛高兹谈一谈。","有个名叫玛高兹的萨满祭司对于火刃氏族的堕落颇有了解。他说在奥格瑞玛外面的山里有个叫骷髅石的山洞，有一大批火刃祭司藏匿在那里。在你前往骷髅石之前，去和玛高兹谈谈吧。他十分睿智，会给你一些有价值的建议。玛高兹就住在东北方的海岸和枯水谷中间。你要听从玛高兹的建议，但是不管他怎么说，，我都要求你干掉那些火刃祭司！","小武哥儿"},
[829] = {"尼尔鲁·火刃","给奥格瑞玛的尼尔鲁·火刃带去一个项圈样本。","你带回来的灼热项圈是充满恶魔力量的强大器物工具。它们的来源恐怕已经不是我这样的萨满祭司所能探究的了。我们必须找个专精于此的术士来研究它们。把这个项圈带给尼尔鲁·火刃。他是个技艺高超的术士，但他却擅长使用自己所掌握的恶魔力量来对抗恶魔，还声称他对恶魔的研究都是有益于部落的。不管这些话是真是假，如果我们要对付那些信仰恶魔的家伙，就需要他的帮助。你可以在奥格瑞玛的暗影裂口找到尼尔鲁。","小武哥儿"},
[830] = {"将军的命令","把普罗德摩尔将军的命令带给剃刀岭的加索克。","你打开了陈旧褪色的信封，发现了一份看上去很正式的文件，上面盖着普罗德摩尔将军的徽记。这封信看上去很重要，剃刀岭的指挥官加索克应该会对它感兴趣。","小武哥儿"},
[831] = {"将军的命令","把普罗德摩尔将军的命令交给奥格瑞玛城中的沃金，他就在萨尔的大厅里。","人类是不可信的。我们和他们并肩作战、疲惫不堪，但我们很明白，总有一天这帮家伙会背叛我们。普罗德摩尔将军死了，但这并没有终止他的计划，这个混蛋在他玩完之前就把一切都安排好了。本尼迪克上尉不会是最后一个威胁，天知道什么时候普罗德摩尔的人会又一次从我们的海岸上登陆。我们要尽快让奥格瑞玛的沃金得知这些信息！快去吧，你应该能在萨尔的大厅里找到他。","小武哥儿"},
[832] = {"燃影之眼","把这颗燃影之眼带给尼尔鲁·火刃。","<你感受到饰物中传来一个神秘的声音>加祖兹？加祖兹？……快回答！我们已经听说你在骷髅石发现了那个东西，你必须立刻发动攻击！加祖兹，我命令你赶快回答！否则我就把你的位置告诉尼尔鲁·火刃，他会用最残忍的手段来对付你！别拿你的小命开玩笑！…加祖兹，你在那里吗……？","小武哥儿"},
[833] = {"神圣的墓地","博学者诺拉·暴雨图腾要你在赤色石杀掉8个刺背干涉者。","赤色石是我们牛头人最神圣的墓地，只有最勇敢的牛头人才能得到在这里安息的殊荣。这是给予那些帮助保卫雷霆崖和为氏族的利益而付出生命的伟大战士的无上荣誉。不过这段时间以来，有种邪恶的威胁正在接近我们的神圣领土。有一群刺背干涉者正在破坏我们的墓地，我的年纪太大了，无力把他们赶走。你一定要把他们驱逐出去，$n。","小武哥儿"},
[834] = {"沙漠之风","为奥格瑞玛城外的雷兹拉克取回5个装满货物的袋子。","我叫雷兹拉克，是加兹鲁维的手下。他派我来这里跟杜隆塔尔的兽人作生意……除了那些商队以外，一切都进行得很顺利，商队的安全根本没法保证！你知道吗，这给我添了不少麻烦！上次发出的一批货物——还说肯定能平安送达呢——结果被一票鹰身人从半道上给劫了去……它们好像是从那什么烈风峡谷来的……反正，拿不到那批货我就死定了！帮帮忙吧……沿着大峡谷向南走，你就会看到直接切入山壁东西两面的沟壑。","小武哥儿"},
[835] = {"保卫商路","为奥格瑞玛附近的雷兹拉克杀掉12个尘风暴徒和8个尘风雷巫。","加兹鲁维跟我说过：“雷兹拉克呀，有一件事情你必须铭记，那就是如果你想把事情做好，就得亲力而为。”我不能让那些商队全都有来无回，所以我得自己解决这件事才行。枯水谷在烈风峡谷的东边，那里的鹰身人多到数不胜数，只要把它们全都给做了，那条路就彻底安全了。当然，加兹鲁维还教过我另一点，那就是“有钱能使磨推鬼”。那么，你愿意帮我的忙吗，$n？","小武哥儿"},
[836] = {"拯救OOX-09/HL！","护送OOX-09/HL到安全地点，然后向藏宝海湾的奥格索普·奥布诺提斯回报。","那个地精的声音再次从那个机器人中传了出来:“我需要你帮忙把OOX-09/HL移动到一个开阔的安全地点，这样它才可以启动起飞程式。它拥有内建的隐蔽系统，但是我需要一点时间从远端来启动这个系统。请你把这个机器人从现在的位置护送到隐密的大石堆附近！那是个非常理想的起飞点，而且护送的路程也可以给我足够的时间来启动连线！”“将它安全地护送到那里，然后再到藏宝海湾来找我！奥格索普·奥布诺提斯─完毕！”","小武哥儿"},
[837] = {"野猪人的进犯","为剃刀岭的加索克杀掉4个钢鬃野猪人，4个钢鬃斥候，4个钢鬃传令兵和4个钢鬃卫兵。","我们刚来这里的时候，钢鬃野猪人还占据了大片的土地，让我们头疼不已。经过不懈的努力，我们已经将大部分野猪人都驱逐了出去，不过在某些地方还残留着不少野猪人。这样的情形已经持续太久了。我们要保护自己，决不能让钢鬃野猪人占据我们的领土。野猪人的营地就在西边，去找到这些恼人的东西并除掉它们吧。今天，我们把钢鬃野猪人赶出杜隆塔尔，明天，我们就能把他们驱逐出整个卡利姆多。","小武哥儿"},
[838] = {"通灵学院","和西瘟疫之地亡灵壁垒的药剂师迪瑟斯谈一谈。","通灵学院坐落在凯尔达隆岛上，这所学校是亡灵天灾的一座堡垒。我们的敌人就聚居在那里，安全地进行研究并不断增强他们的力量。有一扇坚固的大门封住了唯一的入口，如果没有一把合适的钥匙，我们无论如何都无法通过它。药剂师迪瑟斯一直以来都负责与通灵学院有关的事务，他应该知道如何才能获得那把钥匙。你应该向我证明你确实有存在的价值，现在我把这个任务交给你，去跟迪瑟斯谈谈关于这件事的详细情况吧。","小武哥儿"},
[839] = {"<UNUSED>","","","小武哥儿"},
[840] = {"部落的新兵","沿着剃刀岭西部的小路一直前进，过桥之后就可以进入贫瘠之地。在桥对面的兽人前哨找到卡加尔·战痕，将你的募兵信交给他。","嗯，你看上去很强壮。是这样的，我的好朋友卡加尔正在为贫瘠之地招募新兵。我知道你想为部落做点有用的事，这次你的机会来了。把这封募兵信交给卡加尔，看看他会不会签字。","小武哥儿"},
[841] = {"另一个能量源？","用10个废土水袋来和加基森的总工程师比格维兹换取另外一个能量源。","让我猜猜——你没有及时完成你所谓的什么惊天动地的任务。不，等等……是不是你把它掉在了流沙里找不回来了？！好吧，不管是什么理由，我这里还有个能量源可以卖给你。这次，我要你用十个废土水袋来换！这年头大家都不好混，$n，能量源当然不会是长在树上随手可得的！呃，也许它们真的可以长在树上……我们绝对应该试试看能不能制造这样一棵能量源树……","小武哥儿"},
[842] = {"十字路口征兵","从卡加尔的前沿哨所往西走。在丁字路口往左拐，然后朝南走。在十字路口的道路交汇处找到瑟格拉·黑棘。","把我签过字的募兵信拿到十字路口去。那里由瑟格拉·黑棘掌管，她是个恶心的萨满祭司，总喜欢在吩咐你去做正事之前跟你胡说一通，把你搞得头晕脑胀。萨尔觉得她是个人才，但我可不这么看。小子，接下来的事情还是你自己去解决吧……","小武哥儿"},
[843] = {"加恩的报复","加恩·石塔让你杀死15个巴尔丹挖掘者和5个巴尔丹工头。把卡兹戈姆的日记交给加恩·石塔。","我一直在这里孤独地徘徊着。巴尔莫丹的矮人对我们的领土从来都没有半点尊重。烈性的炸药在地面上炸出了一个又一个深深的钻孔，嘈杂的机器切开了山丘和平原，曾经属于我们氏族的美好家园现在成了那些破坏成性的矮人们的领地。我们曾希望通过外交途径与他们和解，但是一切努力最终都以失败告终。现在是做出决断的时候了。用武力将这些矮人从巴尔莫丹的挖掘场赶走，把他们的头儿勘察员卡兹戈姆的日记带来交给我。","小武哥儿"},
[844] = {"平原陆行鸟的威胁","收集7个陆行鸟的喙，把它们交给十字路口的瑟格拉·黑棘。","你的第一个任务是非常简单的。东边的平原陆行鸟总是对我们的食物补给心怀鬼胎，它们已经成了十字路口的一大祸害。杀掉那些平原陆行鸟，把它们的鸟喙给我带回来。","小武哥儿"},
[845] = {"斑马的威胁","杀死快步斑马并收集4只斑马蹄，把它们交给十字路口的瑟格拉·黑棘。","斑马虽然并非贫瘠之地上最凶猛的野兽，但也比平原陆行鸟强悍了许多。不要担心，我们总有一天会派你去挑战比斑马更强大的敌人，但现在你最好用它们练练手。去猎杀北边和南边的斑马，并且收集它们的蹄子。完成这个任务之后，也许你就可以去见识见识真正的猛兽了。","小武哥儿"},
[846] = {"加恩的报复","加恩·石塔要你将6瓶硝化甘油、6份木浆和6份硝酸钠交给他。","很显然，矮人们依靠炸药和那些吵闹的机械来进行挖掘，而且不久后他们肯定会再派一个新的工头来接手这里。我要让这些矮人自食其果。按照这日记上面写着的配方，只要把硝化甘油、木浆和硝酸钠混合起来，就能制造出一种强力的炸药。据我们所知，城堡中的火枪手、战士和军官都拥有这些物资。为我收集这些物资，我要制造出一种让矮人们永远都不会忘记的炸药！","小武哥儿"},
[847] = {"迅猛龙的狡诈","和托尔甘谈一谈。","这……这力量……是托尔甘要显示给我的萨满祭司的力量吗？我不得不承认，这很有趣。告诉托尔甘他让我十分信服……至少是现在。我会对他要说的一切都洗耳恭听。","小武哥儿"},
[848] = {"菌类孢子","收集4个菌类孢子，把它们交给十字路口的药剂师赫布瑞姆。","贫瘠之地的绿洲里隐藏着一个谜。生命的能量从绿洲之水中涌出，给那些汲取水分的动植物带来了勃勃生机。与此同时，这种能量也在慢慢地改变这些动植物。在绿洲附近生长着一种蘑菇，我们这些洛丹伦的药剂师都认为这种蘑菇的孢子中包含有一些特殊的物质，它对我们非常有用。帮我带一些孢子回来，我们会非常感谢你的。","小武哥儿"},
[849] = {"加恩的报复","摧毁巴尔莫丹的飞行器，然后向加恩·石塔回复。","按照卡兹戈姆的日记上所述的方法制造出来的炸药应该不会有问题。那么，我们开始吧。首先我有一项特殊的任务要交给你完成。拿上这只爆破筒，去炸掉巴尔莫丹的飞行器。这个飞行器不仅是巴尔莫丹军事设施的关键部分，也是一架可怕的杀戮机器。更重要的是，它是权力的象征，而它对我们的氏族来说则代表着一段耻辱的回忆。我会为你的成功感到自豪，你也将得到丰厚的奖励。","小武哥儿"},
[850] = {"科卡尔首领","把巴拉克的头颅交给十字路口的雷戈萨·死门。","半人马的问题困扰着牛头人已经很多年了，最近，贫瘠之地的科卡尔半人马开始形成真正的威胁。通常他们散居在这片土地上，不过他们当中已经产生了新的首领，他把一盘散沙的半人马集合在一起。为了保护我们的家园，这些半人马领袖就必须要除掉。帮我带回巴拉克·科多班恩的头颅，他在北方的遗忘之池附近驻营。除掉他，然后再回到我这里。","小武哥儿"},
[851] = {"狂热的维罗戈","把维罗戈的头颅交给十字路口的雷戈萨·死门。","有一个被称作狂热的维罗戈的半人马在贫瘠之地四处游荡，通常很难找到他，不过他的营地就在东南方的死水绿洲附近，你应该可以在那里把他给引诱出来。到死水绿洲附近的半人马营地去，斩杀那里的半人马。虽然这会让你处于很危险的境地，不过如果你能杀死足够多的半人马，他们就会发出警报，之后维罗戈就会现身。把他的头带给我，我要把它和巴拉克·科多班恩的头颅放在一起。","小武哥儿"},
[852] = {"赫兹鲁尔·血印","把赫兹鲁尔的头颅交给十字路口的雷戈萨·死门。","赫兹鲁尔·血印是贫瘠之地的科卡尔半人马的首领。他凶猛、残忍，诡计多端。消灭他就可以瓦解半人马部落，从而极大地削弱他们对我们的威胁。去杀了他。就像对付巴拉克和维罗戈那样，带回赫兹鲁尔的头颅。他和他的手下驻扎就在西南方的甜水绿洲一带。","小武哥儿"},
[853] = {"药剂师扎玛","在药剂的效力消失之前，把提炼过的孢子交给雷霆崖的药剂师扎玛。","我用你给我的孢子制成了药剂。现在我必须把它送给我的同事，药剂师扎玛。如果你愿意帮忙把这个带给她，她会拿一些我们存储下来的炼金术用品奖励你的。她就在预见之池里，那是一个位于雷霆崖下面的洞穴。通向洞穴的小路非常隐蔽，不过你可以在灵魂高地下面找到这条小路。快点出发吧，这种药剂的效力只能持续很短的一段时间，在这段时间里必须要送到扎玛那里。","小武哥儿"},
[854] = {"十字路口之旅","去十字路口和索克谈一谈。","我已经预见到你会来找我，年轻的<职业>，虽然你可能已经并不是那么年轻了。我想，现在是时候让你深入这片土地了，我能感觉到你命中注定是要做一番大事业的人。你应该到十字路口去，因为我们和兽人的命运已经紧紧地联系在了一起，他们那儿需要帮助。沿着这条路往东走，然后向北就可以走到十字路口。到那里去找索克吧。","小武哥儿"},
[855] = {"半人马护腕","收集15个半人马护腕，把他们交给十字路口的雷戈萨·死门。","在与科卡尔半人马的战斗中，你已经证明了自己。不过，他们仍然是个威胁。这些半人马的首领的死对我们来说是非常好的消息，不过你必须继续削减他们军队的人数。为此我会交给你一项赏金任务。到科卡尔半人马的领地去，干掉他们的士兵，收集他们的半人马护腕。当你能带回足够多的护腕的时候，部落会奖赏你的。","小武哥儿"},
[856] = {"<UNUSED>","Continue down the road from Camp Taurajo.Turn left at the T intersection and continue North.Follow the path to the Ancestral Sage outside the Crossroads.","Though you have reached the Barrens, your journey is not complete. You must continue on to the Crossroads, where you are needed most.Follow the road as you were, and turn left where the path gives you the choice. Follow it North until you see the wall","小武哥儿"},
[857] = {"众月之泪","被流放的费格雷要你取回他的众月之泪。","那是我的宝贝！我的！我要把它夺回来！夺回来！那些肮脏的挖掘者发现了它……它是如此美丽，众月之泪是我们在巴尔莫丹的第一个重大发现。它本就该是我的！对，我的！我的宝贝！塔文布莱德将军嫉妒众月之泪带给我的力量，居然就把它锁在了城堡里。他说那是一个诅咒！这个蠢货！其他人想要夺走它，他们是不会得逞的！那个叫塔文布莱德的杂种把我赶了出来。我要夺回来！夺回我的宝贝！","小武哥儿"},
[858] = {"打火钥匙","取得打火钥匙，把它交给维兹克兰克。","你该不会是斯布特瓦夫派来的吧？我被困在这儿了。我在不知道需要钥匙才能启动伐木机的情况下就贸然跳了进来。更蠢的是，当另一台伐木机的操作员问我是否一切正常的时候，我居然慌了神！我没有告诉他我手里没钥匙，而只是说机器有些问题。我们要赶紧离开这里！到起重机上的控制室去，那里的管理员应该有这台伐木机的钥匙。帮我离开这儿！","小武哥儿"},
[859] = {"<UNUSED>","","","小武哥儿"},
[860] = {"瑟格拉·黑棘","和十字路口的瑟格拉·黑棘谈一谈。","如果你想继续沿着猎人之道前行，就得到贫瘠之地去了。那儿的野兽强壮而凶猛，在那里打猎会让你学到很多东西，而你的意志力也会随之增强。去和瑟格拉·黑棘谈谈吧，她会是你在贫瘠之地的第一位向导。她就在十字路口，只要从血蹄村一直往东进入贫瘠之地，见到岔路口之后再往北走就可以到那里了。在贫瘠之地旅行的时候可得小心点，那是一个充满危险和挑战的地方。","小武哥儿"},
[861] = {"猎人之道","收集4只平原徘徊者的爪子，把它们带给雷霆崖的梅洛·石蹄。","我看得出来，你是个渴望探索的<职业>。我也渴望到处漫游，至少曾经是这样……漫游，狩猎。狩猎是牛头人最高的荣誉。如果你真想走猎人这条路的话，梅洛·石蹄可以给你一些指引，他就在雷霆崖的猎人高地上。要向他证明你的能力和决心，你就必须把莫高雷一带的平原徘徊者的爪子带给他看。平原徘徊者非常凶猛、狡猾——对于一个想要成为猎手的年轻<职业>来说再合适不过了。","小武哥儿"},
[862] = {"掘地鼠炖肉","给十字路口的格拉布弄到8只掘地鼠。","像你样一个<职业>在贫瘠之地肯定会饿得前心贴后背，你看我，我就已经饿了整整一天了。我跟你说吧，我可以为你做一道大餐，不过得要先弄一些掘地鼠来。那些可恶的巴尔莫丹矮人几乎把这里的掘地鼠都给吃光了！你到南边的巴尔莫丹去给我带一些掘地鼠回来吧。如果你连这都搞不定的话，就不要再自称是经验丰富的冒险家了！","小武哥儿"},
[863] = {"逃跑","保护维兹克兰克以及他偷来的地精伐木机返回棘齿城的斯布特瓦夫那里。","我想我要好好学学才行……应该不会很难。就这些按钮，一个操纵杆和两个……对了，你准备好要出发了吗？","小武哥儿"},
[864] = {"向药剂师金格回报","把实验工具包带给幽暗城的药剂师金格。","“搞定了，现在能量源已经被安全卸载，而你的数据也被完全保留下来了。好了，接下来就只有祝你一路顺风了，希望你的科学实验一切顺利。”那个地精转身开始继续做加基森水业公司的事情。你小心翼翼地把封好的实验工具包收起来，然后准备把它带回幽暗城。药剂师金格正在那里等着你向他进行回报。","小武哥儿"},
[865] = {"迅猛龙角","从赤鳞镰爪龙身上收集5根完整的迅猛龙角，把它们交给棘齿城的米希瑞克斯。","贫瘠之地的迅猛龙比其它地区的更加聪明狡猾，我想它们的智慧就来自它们的角！如果是这样的话，我可以将它们的角磨成粉末，制成“智慧饮料”，然后就能卖个大价钱！！！我想你应该能帮我的忙……从赤鳞镰爪龙身上弄一些完整的迅猛龙角来，它们就栖息在贫瘠之地的南部以及靠近灰谷森林边界的贫瘠之地北部。","小武哥儿"},
[866] = {"根须样本","把根须样本交给棘齿城的麦伯克·米希瑞克斯。","贫瘠之地的草药似乎和其它地方的不大一样。它们的属性几乎相同，不过这里的绿洲之水却令它们发生了一些改变，使它们变得有那么一点点特别了。我想找出这些草药到底有什么特别之处……然后看看它们有没有利用价值！如果你精通草药的话，就帮我在贫瘠之地收集一些这种草药的根须样本吧。把这些样本交给我，这样一来，我就能比较一下它们与其它地区的草药之间的差异了。","小武哥儿"},
[867] = {"鹰身强盗","收集8只巫翼鹰身人的爪子。把它们交给十字路口的达索克·快刀。","这些该死的鹰身人长期以来不停地攻击和掠夺我们的补给商队。现在我们要给她们一点颜色看看了：我们要割断她们的喉咙，削减她们的数量。我一直在她们的巢穴附近细心观察，而且已经确定了谁是她们的领导者。我们应该首先以削弱她们的基础作战力量为目标，这样才能彻底击败她们。慢慢来，先去干掉那些在西北方出没的巫翼鹰身人和巫翼游荡者，然后给我带8只巫翼鹰身人的爪子回来吧。这应该是一个不错的开始……","小武哥儿"},
[868] = {"蝎卵","把12枚异种蝎卵和掘地爪交给十字路口的科兰。","嘿，，奥格瑞玛城里的主人派我到十字路口来观察这片土地并记录这里所发生的一切。我的目标之一是在巨人旷野南方出现的昆虫状生物。我们对这种生物知之甚少，所以我把它作为我的主要研究课题，希望能发现点什么。它们似乎有超出一般生物的智能。拿着这个掘地铲，从土丘里收集一些它们的卵。不过你要当心，这些生物一旦收到同伴的警报，就会立刻蜂拥而至。","小武哥儿"},
[869] = {"偷钱的迅猛龙","收集12颗迅猛龙的头颅，把它们交给十字路口的加兹罗格。","不久前，我们警戒塔中的一箱银币被偷走了。那是十字路口警卫的薪水，当然我们必须找回这箱银币。奇怪的是……被窃那天，我们逮住了那群小偷中的一个。它……它居然是一只迅猛龙！简直难以置信！我不知道迅猛龙要这些银币做什么，不过我也不关心这个——我只关心能不能取回我的银币。杀掉那些迅猛龙，这样它们就不会再偷我们的东西了！在贫瘠之地猎杀这些迅猛龙，把它们的头颅给我拿回来。","小武哥儿"},
[870] = {"遗忘之池","向图加·符文图腾报告你的发现。","很久以前，贫瘠之地曾是个郁郁葱葱、生机盎然的地方。但是战争与灾难接二连三地降临在这片土地上，最后就剩下了这一片干燥荒芜的不毛之地。事实就是这样，真让我伤心。不过，在过去的几年里，贫瘠之地出现了新的绿洲，生机又在这片土地上重现。我们德鲁伊感觉到了在很深的地下有一股试图冲出地面的力量。我们必须找到这股力量的源泉，请到十字路口西北边的遗忘之池去一趟，在那里的湖水中搜寻力量的源泉，然后回到这里来。","小武哥儿"},
[871] = {"野猪人的袭击","在钢鬃野猪人的营地里杀掉8个寻水者、8个织棘者和3个猎手，然后向十字路口的索克复命。","所有的野猪人都是我们的敌人，而其中有些家伙特别让人讨厌。对我们而言，目前最大的麻烦就是钢鬃野猪人氏族不停地对我们与杜隆塔尔之间的补给线发起攻击。我的探子一直在寻找这些袭击事件的指挥者，但是在找到真正的幕后主使之前，我们总得想些办法来对那些可恶的野猪人进行打击才行。从这里的东北方向开始搜寻，你应该很容易就能找到他们的巢穴，野猪人的巢穴都好像是破土而出的带刺藤蔓一样的建筑物。去找到他们，把这些肮脏的家伙彻底干掉。","小武哥儿"},
[872] = {"野猪人的头目","杀掉8个钢鬃地卜师、8个钢鬃防御者和他们的头目克里尼格·糟鼻。把克里尼格·糟鼻的獠牙交给十字路口的索克。","，我的探子目击了一次针对杜隆塔尔商队的袭击，又是那群该死的钢鬃野猪人干的。其中有一个家伙是这次袭击事件的策划者和组织者：克里尼格·糟鼻。有人在这里的东北方见到过他，就在通往杜隆塔尔的大路的正南方。如果我们要结束这一切威胁，就必须杀了克里尼格·糟鼻。我们一定要终止这没完没了的袭击，要让他们吃吃苦头。完成任务之后，带上克里尼格·糟鼻的獠牙回来见我。","小武哥儿"},
[873] = {"依沙瓦克","把依沙瓦克的心脏交给玛伦·星眼。","依沙瓦克是这片水域的主宰，它力大无穷、威武庄严。海岸上的人类都怕它，因为已经有太多的人类被它杀死。但我不怕，因为它对我来说是一次很有价值的挑战，一个值得尊敬的猎物。如果你准备好了，那么就到海里去寻找海中的巨兽依沙瓦克吧。它的灵魂包容在他的心中，听着它跳动的声音，你就将看到自己的命运。","小武哥儿"},
[874] = {"玛伦·星眼","和玛伦·星眼谈一谈。","你已经猎杀了贫瘠之地的猛兽，在这个过程中你的精神力量也已经变得相当强大了。作为一个猎人，你应当时刻都作好准备，一个真正的猎手理应能在任何环境下追踪猎物。无论是山川还是沼泽都无法阻止$g他:她;。甚至连海洋都不能。去找到我的妹妹玛伦，她正在海岸边猎杀一种大型水兽，你可以从她那里学习更高深的狩猎之道。不过你找她的时候要当心，因为贫瘠之地的海岸一带是现在是被人类控制着的。","小武哥儿"},
[875] = {"鹰身人首领","从巫翼杀戮者那里收集6枚鹰身人首领之戒，把它们交给十字路口的达索克·快刀。","哈哈哈，$n，你还想接下一单任务？好呀，我真是太高兴了。这次的任务是剿灭无水岭的鹰身人首领。只有巫翼杀戮者才能成为鹰身人首领，这一点你可以从她们携带的戒指上判断出来。她们其实就是一伙乌合之众，在无水岭一带应该就有不少。只要杀死6个首领就足以对她们的这个母系氏族造成毁灭性的打击了。$n，你一定要让她们死得很惨，我要让那些下贱的鹰身人知道和部落作对是多么愚蠢的事。","小武哥儿"},
[876] = {"塞瑞娜·血羽","杀掉塞瑞娜·血羽，把她的头颅交给十字路口的达索克·快刀。","你在上次与鹰身人首领的战斗中表现得十分出色，所以我希望由你来帮我做最后一件事。塞瑞娜·血羽是很久前被雷克萨杀死的鹰身人族长的妹妹。显然，这些针对部落商队的袭击是她对我们采取的报复行为。你的任务就是割开她的喉咙，把她的头颅带给我。我将会把她的头颅挂在下一次发出的商队的车顶上……让那些鹰身人好好看看跟部落作对的下场。","小武哥儿"},
[877] = {"死水绿洲","调查死水绿洲，然后返回十字路口向图加·符文图腾报告。","你在遗忘之池找到的地缝也许在贫瘠之地的其它绿洲中也存在。如果是这样的话，那么这些地缝就有可能是绿洲的生命之源。我们应该验证一下。带上这些种子，它们已经失去生命的活力。把它们带到东南方的死水绿洲去，如果那里有地缝的话，就把这些种子放在里面……然后仔细地观察一下。","小武哥儿"},
[878] = {"野猪人的内战","杀掉6个刺背寻水者、12个刺背织棘者和12个刺背地卜师，然后到陶拉祖营地的碎牙那里复命。","你必须杀了我的敌人。<猪哼声>你必须帮助碎牙，帮助钢鬃野猪人。我们的氏族都非常依赖自己的精神领袖——他们可以召唤大地的力量，<猪哼声>使他们让野猪人的氏族变得强大……<猪哼声>如果你想要知道是谁频繁对部落<猪哼声>发动袭击，那你就应该帮助碎牙！你去杀了刺背野猪人的精神领袖，削弱他们，这样钢鬃野猪人就可以打败他们，统治贫瘠之地了！","小武哥儿"},
[879] = {"内奸","杀掉纳克、卡兹和洛克·奥克班恩，把它们的颅骨交给陶拉祖营地的碎牙。","有三个来自剃刀沼泽的氏族参与了对部落的袭击。<猪哼声>他们非常狡诈而无情，如果你打败了他们，不仅仅是十字路口，整个贫瘠之地都将迎来和平……<猪哼声>至少野猪人不会再对你们构成威胁了。<猪哼声>你要找的是纳克、卡兹和洛克·奥克班恩，他们就在贫瘠之地的最南边活动。他们中的一个是施法者，另一个是追踪者，他们的首领是个战士。<猪哼声>杀了他们，杀了这帮背叛我的家伙。","小武哥儿"},
[880] = {"变异的生物","收集8块变异的钳嘴龟壳，把它们交给十字路口的图加。","，你的发现真让人难以置信。这些绿洲拥有一些特殊的力量，谁也不知道这些力量是怎样来的。我想知道这几片绿洲是如何影响那些饮用过绿洲里的水的动物的。去捕获一些在甜水绿洲和死亡绿洲活动的绿洲钳嘴龟，把它们的龟壳给我带过来，我得好好研究一下。嗯，","小武哥儿"},
[881] = {"埃其亚基","把埃其亚基的皮交给十字路口的瑟格拉·黑棘。","白雾，也就是我们所说的埃其亚基，是草原狮的首领。它在捕食猎物时悄无声息地行动，就像大地上浮起的一层薄薄的白雾。它的每次出击都是一击毙命，它的猎物甚至来不及恐惧和痛苦就已魂飞魄散。你会体会到的，因为我要让你去猎杀埃其亚基。它的巢穴就在十字路口的东北边，在那些巨大的科多兽骨附近。去吧，当你走到它的巢穴附近时，就吹响这个号角，它正在等着你呢。","小武哥儿"},
[882] = {"伊沙姆哈尔","把伊沙姆哈尔的牙齿交给陶拉祖营地的乔恩。","伊沙姆哈尔是贫瘠之地最凶猛残忍的赤鳞龙，它狩猎并不是为了健身或是食物，而是因为狩猎是它最大的爱好，伊沙姆哈尔天生就是个杀手。，你会了解到它的天性的，因为你很快就要动身去追踪这条赤鳞龙了。开始这次猎杀行动吧。先去杀死一只它最喜欢捕猎的动物——斑马，然后把斑马肉挂在棘齿城西北边的枯树上。当伊沙姆哈尔闻到肉味的时候，它就会出现的。那时，你可要做好准备。","小武哥儿"},
[883] = {"拉克塔曼尼","把拉克塔曼尼的蹄子交给陶拉祖营地的乔恩。","拉克塔曼尼的蹄子是科多兽力量的象征。","小武哥儿"},
[884] = {"奥瓦坦卡","把奥瓦坦卡的尾刺交给陶拉祖营地的乔恩。","只要一被触及，奥瓦坦卡的尾刺就会闪烁起火花。","小武哥儿"},
[885] = {"瓦希塔帕恩","把瓦希塔帕恩的羽毛交给陶拉祖营地的乔恩·星眼。","仅仅是轻轻触碰一下瓦希塔帕恩的羽毛，你都会感到相当刺痛。","小武哥儿"},
[886] = {"贫瘠之地的绿洲","和十字路口的图加·符文图腾谈一谈。","雷霆崖的德鲁伊们感到有一股奇怪的力量正在渗入莫高雷东边的贫瘠之地。图加·符文图腾已经被派去查找这股力量的来源了，但是我们担心他可能需要更多的帮助。到贫瘠之地去和图加谈谈吧，他应该就在十字路口。从血蹄村一直往东走就可以进入贫瘠之地，在路口向北转，然后继续往北走，很快就到十字路口了。记得一直在路上走，，贫瘠之地是一块非常危险的土地。","小武哥儿"},
[887] = {"南海海盗","帮棘齿城的加兹鲁维杀死12个南海歹徒和6个南海炮兵。","我当然希望格雷兹里克中将能够保护我们在这片海域上来来往往的商船。贸易巨头们向商船舰队里砸了这么多的金子进来，而这些海盗却在胡作非为，袭击我的船只，还偷走了我的货物！我听说南海海盗就在南方的海岸边扎营，他们可以说是我的眼中钉肉中刺，假如格雷兹里克搞不定他们，也许你能帮我除掉他们。","小武哥儿"},
[888] = {"被窃的货物","帮棘齿城的加兹鲁维取回一箱靴子以及一块望远镜片。","我希望取回所有丢失的货物，但我想那不太可能。不过，有些货物是我必须要取回的！正如你所见的，我的天文台马上就要建好了，现在只差两块镜片中较小的一块。第一块已由杜隆塔尔的商队运到，第二块运上了船，但现在还没有到。对了，我还没有收到藏宝海湾的崔斯里克给我发来的靴子！到海盗营地去一趟，看看能不能找到这些货物吧。","小武哥儿"},
[889] = {"风之魂","","","小武哥儿"},
[890] = {"丢失的货物","把加兹鲁维的账本交给棘齿城的码头管理员迪兹维格。","我一直在等从藏宝海湾发来的最后一批货物！我确信是海盗偷走了它们，不过为了保险一点，我还是希望你能去一趟码头，帮我问问迪兹维格……问问我的货物是否已经入库。把我的帐本交给迪兹维格，让他赶紧把我的存货记录和他的出货单校对一下。","小武哥儿"},
[891] = {"北方城堡的火炮","棘齿城中的沙罗萨斯船长要你收集10枚塞拉摩徽章并干掉法莫斯队长、炮兵维桑恩和炮兵斯密瑟。","我又有一艘船被北方城堡里的那些狂热的人类给击沉了！到了该和那帮混蛋算账的时候了。他们的偏执让他们变成了一群疯子。为了取乐，这些不计后果的呆瓜向每一个进入他们视野的目标开火。从这里向南走，沿着商旅海岸就可以抵达北方城堡，干掉他们的人，然后把他们士兵的徽章给我拿回来作为证明。为了我心爱的舰队，你必须杀了法莫斯队长和她那些疯狂的炮兵！","小武哥儿"},
[892] = {"丢失的货物","把加兹鲁维的账本交还给棘齿城的加兹鲁维。","我这边的出货记录似乎没什么问题，$n。回去告诉加兹鲁维，他似乎不太走运。不出意料的话，应该是有海盗偷走了他的货物。很遗憾我不能为他做些什么了。呃……不过你可以告诉他，我从安德麦弄了些东西给他，什么时候他有空的话就过来拿一下吧。","小武哥儿"},
[893] = {"野猪人的武器","给陶拉祖营地的塔特纳克·钢炉带去一把钢鬃背刺匕首、一根烧焦的钢鬃魔杖和一面钢鬃大盾。","在巨人旷野以南的地区，生活着大群的钢鬃野猪人。据我所知，他们曾是一群无能的铁匠，不过有人告诉我说，野猪人们现在已经逐渐开始改良他们的那些破烂武器了。我想要从他们那里弄些武器样品来进行研究。如果你能帮我带回来几件武器的话，部落会以你为荣的。帮我带回一把捕猎者用的匕首，一根先知用的魔杖，和一面战士用的盾牌。","小武哥儿"},
[894] = {"什么什么平衡器","在风险投资公司研究基地里找到控制台。","风险投资公司最近在北边设立了小型的研究设备，就在淤泥沼泽的西南部。我对他们在做的东西并不了解，只知道他们正在试验一种名叫“主动式负载平衡器”的装备。那个主动式负载平衡器到底是什么东西呢？不管它是什么，我都想研究研究它，所以我需要找个人来帮我把它弄到手。我手里有控制系统操作手册的副本，你应该知道该怎么把那什么平衡器卸下来。","小武哥儿"},
[895] = {"通缉：巴隆·朗绍尔","把巴隆·朗绍尔的头颅交给棘齿城的加兹鲁维。","通缉令！巴隆·朗绍尔，破浪号的船长吉尔尼斯的朗绍尔船长统领南海海盗横行海上，现因海盗罪名指控被通缉。领取奖赏者必须提供足以证明自己杀掉了巴隆·郎绍尔的证据！——加兹鲁维","小武哥儿"},
[896] = {"矿工的宝贝","从风险投资公司的某个监督或者执行者那里夺取猫眼翡翠，然后把它交给棘齿城的码头管理员迪兹维格。","作为像棘齿城这么繁忙的码头的管理者，我始终关注着每一条有利可图的消息。我知道这里与藏宝海湾的所有物品和货币的交易情况。最近我听到了一些消息，是关于风险投资公司在淤泥沼泽东北的石矿洞的。有个矿工挖出了一枚足有拳头大小的翡翠石。我知道有一些买主肯掏钱买那么大的一块宝石，如果你帮我搞到那块宝石的话，那么我愿意和你五五分成，你看怎么样？","小武哥儿"},
[897] = {"收割者","把收割者的头颅交给乔恩·星眼。","这种奇特的昆虫状生物看起来仿佛不是贫瘠之地的生物，而更像是个天外来物。","小武哥儿"},
[898] = {"逃离监牢","护送基尔萨瑞斯·火枝安全地返回棘齿城的沙罗萨斯船长那里。","终于有人来救我了！你居然能躲过那些守卫，这简直是太不可思议了。这帮塞拉摩的狂热分子已经毫无理智可言了。他们击沉了我们的船只，俘虏了我这个唯一的幸存者，还称我为联盟的敌人和威胁。你看我像是要威胁谁的样子吗？我不过是在棘齿城和藏宝海湾之间来回奔波的下等水手而已。一下子说了这么多，你愿意帮我返回棘齿城吗？等你准备好了，我们就马上越狱。","小武哥儿"},
[899] = {"复仇的怒火","收集60根刺背野猪人的獠牙，把它们交给十字路口的曼科里克。","我的全家都被刺背野猪人杀害了，<职业>。也许你能体会这种失去亲人的伤痛，也许你不能……每天我都等在这里，从日出到日落，寻找这些罪无可赦的恶魔。从那天起，除了关在那边的俘虏之外，我见一个野猪人就杀一个。但这依然远远无法平息我复仇的欲望。我想你这个<职业>能够帮助我。去杀掉那些野猪人，能杀多少就杀多少。带回它们的獠牙，让我们一起为它们的死亡而庆贺吧。","小武哥儿"},
[900] = {"什么什么平衡器","关闭燃油控制阀、调节阀和主控制阀，然后再使用控制台。","三个控制阀门都处于打开状态。根据控制面板上的指示说明，在拆卸零件之前必须要把这三个阀门关闭。","小武哥儿"},
[901] = {"什么什么平衡器","从工匠斯尼格斯那里拿到能打开控制台的钥匙。","关闭设备后就可以开启控制面板，从控制台中移出主动式负载平衡器。一切准备就绪，现在你需要做的就是取得可以打开控制台的钥匙。","小武哥儿"},
[902] = {"什么什么平衡器","把主动式负载平衡器交给棘齿城的斯布特瓦夫。","揭开控制台的盖子之后，你看见了密密麻麻缠绕在一起的电线、管子和其它各种奇形怪状的机械装备——其中大多数看起来没有什么实际用途。你把它们拨向一边，在控制台的最里边找到了主动式负载平衡器。一只机械臂把它从机架上拽了出来。","小武哥儿"},
[903] = {"草原上的徘徊者","帮十字路口的瑟格拉·黑棘收集7只徘徊者的爪子。","现在是该让你迎接一些真正的挑战了。贫瘠之地的徘徊者是一种很强悍的动物，而且非常致命。你可以在草丛里找到这些野兽，它们一般都在十字路口的西南边。猎杀它们的时候要多加小心，，不然的话，你很快就会发现自己的角色不再是捕猎者，而是猎物。","小武哥儿"},
[904] = {"<UNUSED>","","","小武哥儿"},
[905] = {"狂暴的镰爪龙","杀死赤鳞迅猛龙并收集它们的羽毛，把这些羽毛放在3个赤鳞镰爪龙的巢穴里，然后返回十字路口的瑟格拉·黑棘那里。","$n，你要做的下一步事情是打败你的猎物，并找到它们的巢穴。去猎杀南边的赤鳞迅猛龙，然后拿走它们戴着的羽毛。把羽毛放在死水绿洲西南边的赤镰龙巢穴里，让它们知道你无所畏惧！","小武哥儿"},
[906] = {"内奸","把洛克·奥克班恩的颅骨交给十字路口的索克。","<种族>，带上洛克·奥克班恩的颅骨去见索克吧。*猪哼的声音*他应该知道我的氏族发生过什么事。哈，他不知道我也参与了*猪哼的声音*这些事情，但我敢肯定他会对你的所作所为给予奖励的。*猪哼的声音*我们不会再见面了。*猪哼的声音*","小武哥儿"},
[907] = {"被激怒的雷霆蜥蜴","收集3瓶雷霆蜥蜴的血液，把它们交给陶拉祖营地的乔恩·星眼。","现在，你必须面对强大的雷霆蜥蜴。这些野兽的体型非常巨大，连大地也会随着它们的行进而震颤。与它们作战时一定要多加小心，一次小小的失误就会让你丢了性命。你可以在南贫瘠之地找到雷霆蜥蜴，当你击败它们之后再回来见我。","小武哥儿"},
[908] = {"废墟之间","把深渊之核交给灰谷佐拉姆加前哨站里的耶努萨克雷。","暮光之锤已经进入了黑暗深渊中的月光神殿废墟里去了，他们的目标肯定是要强迫元素生物来对付我们。如果我们不及早采取对策的话，这个地区就将永远被他们控制。到黑暗深渊去找到废墟中的深渊之石，它应该在靠近水边的地方。深渊之石里面是深渊之核——那里面记载了所有元素生物的历史。如果我拥有了它，我和陶土议会就能阻止他们了！","小武哥儿"},
[909] = {"阿奎尼斯男爵","把奇怪的水球交给灰谷佐拉姆加前哨站的耶努萨克雷。","被击败的水元素留下了一个奇怪的水球，你猜想这东西可能是为水元素提供能量的。一股看起来就很恶心的水流在球体内翻腾喷溅，而球体本身似乎不受任何自然力的影响。如果说有人能对这个东西有所了解，那就只能是陶土议会的耶努萨克雷了。他就在灰谷的佐拉姆加前哨站里。","小武哥儿"},
[910] = {"降帆靠港","带着你看护的孤儿去贫瘠之地的棘齿城码头。","我听过很多有关棘齿城和藏宝海湾的航海故事！我一直都梦想着能在海洋上航行并参加大型海战，我长大后一定要成为伟大的部落水手！那一定很棒！你愿意带我去棘齿城的码头上看看吗？我保证不会掉到水里或者制造任何麻烦——我只是想看看大帆船，闻闻那带着咸味的海风！","小武哥儿"},
[911] = {"前线之门","带着你看护的孤儿去贫瘠之地北部的摩尔沙农场，它就在靠近灰谷入口的地方。","大家都说灰谷是新的前线战场，而且我听说贫瘠之地的摩尔沙农场是通往那里的必经之处。想想看，部落的前锋部队在一片陌生的森林中为部落争取荣耀，多酷啊！他们说那里将会是联盟和部落竞争最激烈的战场，我要到那里去，！你能不能带我去摩尔沙农场，让我看看新的前线是什么样子的？求求你了！我想要看看部落是怎么把那些讨厌的暗夜精灵赶出去的！","小武哥儿"},
[912] = {"Stonesplinter Trogg Disguise","","","小武哥儿"},
[913] = {"雷鹰的嘶鸣","找到一只雷鹰，杀掉它，然后把它的翅膀交给陶拉祖营地的乔恩·星眼。","雷鹰是一种凶猛的野兽，$n。现在你应该去挑战它们了，把它们的翅膀给我带回来，作为你获胜的证明。完成这个任务，你就差不多可以结束在我这里的训练了。","小武哥儿"},
[914] = {"尖牙德鲁伊","将考布莱恩宝石、安娜科德拉宝石、皮萨斯宝石和瑟芬迪斯宝石交给雷霆崖的纳拉·蛮鬃。","哀嚎洞穴中的那些尖牙德鲁伊，曾经是一些高尚的德鲁伊，他们的目标是治愈贫瘠之地的创伤。然而，现在他们却想把这片土地据为己有——曾经高贵的理想变成了扭曲的妄想，我们决不能让他们得逞。尖牙德鲁伊组织共有四个首领，我在梦中见过他们，即便是现在，他们的面孔仍然萦绕在我的脑海中。打败他们，把他们的宝石给我拿来。去吧，。他们就潜伏在哀嚎洞穴的深处。","小武哥儿"},
[915] = {"草莓冰激凌","为你看护的孩子买一些草莓冰激凌。这个孩子似乎最喜欢“提古勒和弗洛尔”牌的草莓冰激凌。","冰激凌！哦，求你了求你了，帮我买些冰激凌来吧？！我最喜欢草莓味的，而世界上没有比提古勒和弗洛尔的草莓冰激凌更棒的冰激凌了！这是我最最喜欢的冰激凌！上次我在闪光平原的赛车场尝到过它，不过现在我听说他们开始在城里出售冰激凌了！求求你了，我实在是太想尝尝提古勒和弗洛尔的草莓冰激凌了！","小武哥儿"},
[916] = {"树林蜘蛛的毒囊","给奥达希尔的基尔沙兰·风行者带回10个树林蜘蛛的毒囊。","我是为了观察居住在黑丝洞的树林蜘蛛才来到幽影谷的。这些森林蜘蛛是另一种体型更小的蜘蛛的近亲；我相信世界之树在它们身上产生某些特殊的影响，我需要一些样本来研究它们以证实这一点。首先，我需要一些它们的毒液，帮我从这些蜘蛛身上收集一些树林蜘蛛的毒囊吧，它们就在北方的黑丝洞一带活动。有了毒囊，我就可以研究一下这种毒与它们的近亲体内的剧毒有何相似之处。","小武哥儿"},
[917] = {"树林蜘蛛的卵","给奥达希尔的基尔莎兰带回1枚树林蜘蛛的卵。","现在我已经得到蜘蛛的毒液，不过我还需要一些活体样本以便更好地进行研究。不幸的是，抓来一只活的巨型蜘蛛对你来说也许太困难了，年轻的<职业>。而且，我也没办法处理一只巨型蜘蛛！但如果你能找到一枚还未孵化的蜘蛛卵的话，从卵里提取样本作为研究材料就变得容易多了，而且我也能对付卵中未孵化的蜘蛛。在黑丝洞的深处一定有蜘蛛的巢穴。拜托了，帮我到那里去找一枚蜘蛛卵吧。","小武哥儿"},
[918] = {"林精的种子","给奥拉密斯湖边的德纳兰带去8粒林精的种子。","泰达希尔的林精是代表自然的元素生物，它们以某种方式反映了我们这里的自然生态的情况。所以看到林精变得如此愤怒真让人感到担忧。我相信这与土壤有关。我一直在用不同的方法种植植物，可以用林精的种子来试验一下。我请求你，能在奥拉密斯湖周围的林精那儿收集一些种子给我吗？","小武哥儿"},
[919] = {"林精的新芽","给奥拉密斯湖边的德纳兰带去12个林精的新芽。","小林精在奥拉密斯湖周围和涌泉湖以西迅速成长。我害怕它们会的数量会多到无法控制——我们应该在它们惹出乱子之前把它们从土地上清除。你在湖边行走的时候，如果看到任何林精的新芽长出来，就顺便除掉它。让我们的土地免受污染！","小武哥儿"},
[920] = {"特纳隆的召唤","与奥达希尔顶部的特纳隆·雷拳交谈。","你叫$n，没错吧？我听说特纳隆大人正在找你。你可以在奥达希尔树冠的最顶层找到他。虽然我们的生命近乎无限，可你最好别让他等得太久。","小武哥儿"},
[921] = {"大地之冠","装满水晶瓶并将其带回给奥达希尔顶部的特纳隆·雷拳。","是该出发去追寻并探索你的自己的命运了，$n。但是在你走出我们美丽的森林之前，你应该首先好好了解我们近代的历史。自海加尔山战役之后，我们的族人改变了许多。因为消耗了全部的力量来击败阿克蒙德并赶走燃烧军团，诺达希尔再度被暗淡的阴影笼罩……有一个你必须去完成的任务，到奥达希尔北边的月亮井里装一瓶水，然后把它拿回来给我。","小武哥儿"},
[922] = {"雷利亚·绿树","给达纳苏斯的雷利亚·绿树带去一粒林精的种子。","，你能给我的朋友雷利亚·绿树带去一粒种子吗？他是个住在达纳苏斯的德鲁伊，我们上次谈话时，他对我的林精研究工作很感兴趣。他有自己的想法，如果有粒可以用来作试验的种子的话，他一定会非常感激的。谢谢你，。你帮了我一个大忙。希望有一天你能看到我的劳动成果。","小武哥儿"},
[923] = {"青苔之瘤","收集5个青苔之瘤，然后把它们交给达纳苏斯的雷利亚·绿树。","一种邪恶的力量正在森林中滋生。我们到处寻找邪恶之源，但当我们找到的时候……为了泰达希尔的安全，我们必须消灭掉那些已经无法挽救的林精。生长在泰达希尔北部的涌泉湖的林精所受的污染最为严重，你必须消灭它们！消灭在那里发现的林精，收集生长在它们身上的青苔之瘤，然后把那些瘤交给我，让我烧掉它们。","小武哥儿"},
[924] = {"恶魔之种","取一块有瑕疵的能量石。在能量石失去魔法之前把它带到火焰祭坛去，然后向雅克塞罗斯复命。","恶魔之种是燃烧军团使用的一种强大工具，它生长在鬼雾峰洞穴里的恶魔火坛上。我已经准备好了能量石，只要把它放在恶魔之种附近，就可以切断它与燃烧军团的联系。从石台上取一块能量石，把它带到鬼雾峰上的火焰祭坛去。从这里一直往西走，然后在交叉路口向北转，鬼雾峰就在你的左边。从鬼雾峰北坡爬上去应该是最安全的路线。动作快点——石头的魔力在很短的时间内就会耗尽。","小武哥儿"},
[925] = {"凯恩的蹄印","到雷霆崖去，为你看护的孩子拿到一份凯恩·血蹄的蹄印。","他们说凯恩·血蹄是部落有史以来最伟大的英雄之一。当我长大之后，我也要成为部落的英雄！你认识凯恩吗，？你可不可以帮我个忙呢？你能不能帮我搞到他的蹄印？我不知道怎么向他开口，他也许一直很忙而没有时间理我……但是你可以！你是和他一样伟大的冒险者！我打赌他会很乐意把蹄印给你的！求求你了！","小武哥儿"},
[926] = {"有瑕疵的能量石","","","小武哥儿"},
[927] = {"布满苔藓的心脏","将布满苔藓的心脏交给奥拉密斯湖畔的德纳兰。","恶臭的黑苔兽的心脏上长满了又黑又油腻的苔藓。事实上，如果它没有那缓慢而有节奏的心跳，也许你根本就看不出这是颗心脏来。也许德纳兰会想要研究一下这颗心脏。","小武哥儿"},
[928] = {"大地之冠","将装着半瓶水的瓶子交给多兰纳尔的科瑞萨斯·月怒。","关于月亮井和泰达希尔的点点滴滴实在是太多了，我无法一一告知给你，这需要你自己去探索。科瑞萨斯·月怒正在等着你。我已经把你所带回来的水倒入了这个容器中，把它送到科瑞萨斯那里去吧。出发吧，科瑞萨斯就在多兰纳尔的月亮井旁。你只需要沿着奥达希尔南边的小路走出幽影谷，沿着鹅卵石铺成的小路一直走，然后向西转就行了。注意，你要一直沿着路走，$n。最近路旁的森林里出现了许多危险的野兽。","小武哥儿"},
[929] = {"大地之冠","用月亮井的水装满翡翠瓶，然后把它交给多兰纳尔的科瑞萨斯·月怒。","首先，让我告诉你必须要完成的任务的其他一些细节。达纳苏斯的德鲁伊需要使用泰达希尔的月亮井的水，所以月亮井的水需要不断地补充。使用这种特制的瓶子，你可以收集起月井之水。带着这个瓶子去东边的星风村，装满村外的月井里的水，再带回来给我。你完成任务之后，我将继续讲述台纳隆的故事……","小武哥儿"},
[930] = {"发光的水果","把这颗发光的水果交给奥拉密斯湖的德纳兰。","一颗又大又圆的果实挂在叶下。你觉得德纳兰一定会想要研究一下这东西。","小武哥儿"},
[931] = {"发光的树叶","给奥拉密斯湖畔的德纳兰带去1片发光的树叶。","植物上的叶子泛着微弱的光，产生了一种不断变化的光晕。你觉得德纳兰可能会想要研究这种东西。","小武哥儿"},
[932] = {"扭曲的仇恨","杀掉迈雷纳斯，带他的头去见多兰纳尔的塔隆凯·捷根。","$n，你必须提高警惕，我们不能对这件事袖手旁观。萨特就够我们头疼的了，而眼前的这件事更是火烧眉毛。有个名叫迈雷纳斯的恶棍就住在附近的地狱石洞穴里，他在那儿聚集了一大批骁勇的战士为自己卖命，他的心如无月的夜晚一般黑暗，他目前正在密谋着一些极端邪恶的勾当。到这里北边的洞穴去找他，带他的头来见我。","小武哥儿"},
[933] = {"大地之冠","用月亮井的水装满红玉瓶，然后把它交给多兰纳尔的科瑞萨斯·月怒。","在达纳苏斯城门的东南方还有一口月亮井，就在阿里斯瑞恩之池的岸边。由于瘤骨熊怪的数量无节制地增长，以及他们对于这个地区的疯狂攻击，哨兵们根本无法有效地控制这一地区。在寻找月亮井的时候小心点，一定要时刻握紧你的武器。","小武哥儿"},
[934] = {"大地之冠","用月亮井的水装满紫水晶瓶，然后把它交给多兰纳尔的科瑞萨斯·月怒。","然而泰达希尔并不是一切都尽如人意。范达尔·鹿盔对于世界之树的计划正如他自己所希望的那样一步步展开了，但是还有一个小问题，这个问题或许会给泰达希尔带来一些麻烦。不过我不打算介入此事。你得去一趟最后一口月亮井，就在这里西北面的神谕林地里，就在神谕之树的树干下面，那是我们的第一口也是最强大的一口月亮井。在那里灌一瓶水，然后回来向我报告。","小武哥儿"},
[935] = {"大地之冠","将装满月亮井水的瓶子带给在达纳苏斯的大德鲁伊范达尔·鹿盔。","没有生命的赋予者阿莱克斯塔萨和时间之王诺兹多姆的祝福，泰达希尔的成长就很难一帆风顺。我不断收到有奇怪的猛兽出现的报告，而疯狂的熊怪也开始不断地袭击路人。我只能希望大德鲁伊们能尽快找到解决的方法。我会将把你带来的所有月亮井水都灌入这个瓶中，然后让你把它带到达纳苏斯去。把这只瓶子交给范达尔·鹿盔，你可以在德鲁伊之林里找到他。","小武哥儿"},
[936] = {"协助大德鲁伊","与雷霆崖的大德鲁伊哈缪尔·符文图腾谈一谈。","打扰一下，<职业>，如果可能的话，我想占用你一点时间。雷霆崖的塞纳里奥议会希望能找到像你这样经验丰富的冒险家来帮助他们进行一项重要的研究项目。虽然我不知道详细的情况，但是我可以告诉你，正是哈缪尔·符文图腾亲自负责这项研究。要是你感兴趣的话，请直接去雷霆崖的长者高地找他谈谈。","小武哥儿"},
[937] = {"神谕林地","收集6条血羽腰带，把它们交给神谕林地里的哨兵阿瑞尼亚·碎云。","我和一个哨兵小组被派到这里来保护神谕之树免受鹰身人的威胁。它们已经在沼泽周围建造了很多巢穴，我们正在试着把它们赶回去。神谕之树曾派信使到达纳苏斯去通报这一情况，但一群鹰身人在中途杀死了那个信使。如果你认为你能胜任这项任务的话，就到它们的巢穴里去，杀死它们，把它们的腰带拿回来作为证明。","小武哥儿"},
[938] = {"密斯特","护送密斯特去神谕之树附近的月亮井旁找哨兵阿瑞尼亚·碎云。","这只猎豹的毛皮是很特别的暗灰色，与四周的森林几乎融为一体。她静静地躺在地上，你发现她伤得很重，背部和腹部都有很深的伤口。她抬起头盯着你，蓝色的双眼闪着智慧的光芒。她似乎希望跟随你。","小武哥儿"},
[939] = {"萨瓦里克长笛","将萨瓦里克长笛和5个碧火魔符交给费伍德森林南部的艾瑞丹·蓝风。","打败萨瓦里克之后，你仔细看着从他的尸体上拿到的木制长笛。这根带节的木棍摸起来很结实，但是当你把它拿在手中翻看时，笛子表面的纹理似乎突然开始旋转了起来。你猛然间感觉到了一丝恐惧……你摇了摇头，感到这可能是你的感觉在和你开玩笑。可能其它的萨特身上有关于你所发现的东西的线索。将你发现的线索交给费伍德森林南部的德鲁伊，艾瑞丹·蓝风。","小武哥儿"},
[940] = {"泰达希尔","把神谕之树的报告交给达纳苏斯的大德鲁伊范达尔·鹿盔。","你的事迹在森林里传扬，$n。鹰身人已经被赶走，森林恢复了平静，这里的生物再次感受到了安全和宁静。我几乎已经不敢派信使去大德鲁伊那里了，但我知道你会帮我把信息安全送达的。把消息传递给他，我知道森林将保佑你安全地将信息送达目的地。","小武哥儿"},
[941] = {"培养心脏","把被污染的心脏放到德纳兰的培养槽里。","我已经除去心脏上的苔藓，但它早已经被污染了……把心脏放到我的培养槽里，营养丰富的土壤也许能净化并治愈这颗心脏。","小武哥儿"},
[942] = {"健忘的勘察员","把神秘的化石交给米奈希尔港的考古学家弗拉冈特。","这块化石和我在铁炉堡看到的一块化石非常的相似。一个名叫弗拉冈特的考古学家把它带到了我们一年一度的探险者协会研讨会上。他坚信那块化石中蕴藏着奇特的魔力，而且那种魔力是可以被提取出来的。上一次我听到弗拉冈特的名字时，他待在米奈希尔港的深水旅店里，等人护送他到维尔加挖掘场。去找他，并且把雷姆塔维尔的化石交给他，也许他能揭开化石中蕴含着的秘密。祝你一路顺风。","小武哥儿"},
[943] = {"健忘的勘察员","米奈希尔港的考古学家弗拉冈特要你把雷鲁之石带给他。","嗯，我在那里会议之后把原始样品交给了勘察员维尔。最近，我在洛克莫丹发现了雷鲁之石，我认为它就是解开神秘化石的钥匙。当我准备赶往维尔加挖掘场的时候，遭到了迅猛龙的攻击，雷鲁之石也给弄丢了。我不知道是哪只迅猛龙吞掉了这块石头，但如果你能找回它，我应该就可以释放这些化石中的魔力了。当然，我们也需要最初从维尔加挖掘场取回的那枚化石。","小武哥儿"},
[944] = {"主宰之剑","收集信息，然后使用占卜之水创造出一个占卜之碗，并利用这个碗和安努通话。","我很奇怪纳迦为什么会出现在这里，在黑海岸。但更奇怪的是……暮光之锤。那些信徒崇拜非常非常古老的大地之神，一个很久以前就被打败的神。主宰之剑就是那个古神被打败的地方。去那里找到更多暮光之锤的信徒。带上这瓶占卜之水。等你到了主宰之剑之后，就用它制造一个占卜之碗，通过那个碗，你可以直接和我通话。","小武哥儿"},
[945] = {"护送瑟瑞露尼","帮助瑟瑞露尼逃跑，然后告诉在艾森娜神殿的瑟瑞希尔，她的妹妹目前很安全。","救命呀！我正在主宰之剑附近散步的时候，这些肮脏的家伙包围了我。多亏我善于隐藏才没有被他们找到！我很厉害吧！你能帮我离开这里吗？还有还有，你能不能给我姐姐瑟瑞希尔捎个口信，告诉她我平安无事？要不然她会担心死的。她住在艾森娜神殿里，那地方就在南方的灰谷森林里。","小武哥儿"},
[946] = {"<UNUSED>","","","小武哥儿"},
[947] = {"洞中的蘑菇","收集5个粗柄蘑菇和1个毒帽蘑菇，把它们交给奥伯丁的巴瑞萨斯·月影。","我正在研制一种药剂，需要一种生长在特定洞穴里的稀有蘑菇才能配制。这个洞穴位于壁泉河瀑布的后面，在东边稍稍偏北的地方。我本来准备自己去，不过古树之林建议我不要靠近那个地方。我们尊贵的盟友觉得那个洞穴是黑海岸新出现的邪恶势力的藏身之处。，请你帮我收集那些蘑菇。与此同时，请察看一下那处洞穴以便确认古树所担心的事情。","小武哥儿"},
[948] = {"安努","和古树之林的安努谈一谈。","古树之林里的一棵知识古树安努得知了你到壁泉河瀑布去的这次旅行，他希望和你谈谈。古树之林就在南方的山麓附近。这些古树耐心而充满睿智，，不过，如果是安努找你是为了向你询问瀑布一带的情况，我想事情一定非常紧急。","小武哥儿"},
[949] = {"暮光之锤的营地","到位于主宰之剑的暮光之锤营地去寻找线索。","暮光之锤来到主宰之剑的目的还不得而知，不过肯定是为了某些不可告人的邪恶目的。到主宰之剑去搜寻他们的营地……设法查出他们准备干什么。在制定计划之前，我们必须首先知道他们的意图。","小武哥儿"},
[950] = {"向安努回复","把令人发狂的书页交给安努。","仔细阅读暮光之书会让人发疯。只要盯上一小会儿，书上的字就开始游动乱舞，原本美妙的插图和花边也扭曲得变了形。为了不至于让神志陷入混乱之中，你只好赶快撕下了一张写着这些可怕的文字的书页。","小武哥儿"},
[951] = {"玛塞斯特拉遗物","收集6个黑暗深渊遗物，把它们交给古树之林的安努。","你在主宰之剑找到的那页书来自于一本古籍……一本精灵撰写的古籍。但它已经被暮光之锤诅咒和玷污了，看来暮光之锤的信徒是希望用古代精灵的魔法将他们古老的主人重新召回我们的世界。到东北边的玛塞斯特拉废墟去看看，找到那些古代的遗物。如果我能研究一下它们的话，也许能搞清楚暮光之锤打算如何使用那些精灵的魔法。","小武哥儿"},
[952] = {"古树之林","把范达尔的信交给黑海岸古树之林里的安努。","如果你有时间为神谕之树跑跑腿的话，我想让你帮我送一封信到黑海岸的古树之林去。你大概只有乘角鹰兽才能到黑海岸，不过我相信你绝对可以完成这个任务。把这个交给知识古树安努，他正等着我的消息，就像我曾焦急地等待来自神谕林地的消息一样。","小武哥儿"},
[953] = {"亚米萨兰的毁灭","研究刻有亚米萨兰的故事及其被毁经过的石碑，然后回到黑海岸的哨兵坦莎·月刃那里。","到东边去就可以发现亚米萨兰废墟。现在，那些未曾安息的暗夜精灵贵族的亡灵如同生前一般盘踞在那里，那里也曾经是艾萨拉的仆人练习他们强大魔法的地方。我在奉命探索那片废墟的时候偶然发现有两块巨大的石碑，上面是潦草写下的亚米萨兰的故事，还有这座城市被毁灭的历史。在我阅读碑上的刻文的时候,突然有亡灵出现和我说话，吓得我赶紧逃了回来。如果你够胆量的话就去一趟那片废墟，替我破译一下石碑上的刻文。","小武哥儿"},
[954] = {"巴莎兰","到巴莎兰废墟去找到奇怪蓝光的源头。","有一伙恶魔的爪牙在东部的巴莎兰废墟里到处横行。盘踞在那里的劣魔和萨特疯狂地汲取着魔法的能量，致使它们的魔力不断地迅速膨胀。但是，我也注意到那里有一处它们始终无法侵犯的神殿，就在那片废墟西侧的小峭壁上，那座神殿里弥漫着奇特的蓝光……一定有什么原因使得恶魔不愿靠近那里。我希望你去调查一下。","小武哥儿"},
[955] = {"巴莎兰","帮巴莎兰的阿斯特利安收集8只劣魔耳环。","如果要我把一生的故事都讲出来，恐怕你会失去耐心。简单地说，我的一生漫长而痛苦，而现在这种鬼魅般的生活更是对我最痛苦的折磨。我被魔法囚禁在这里。也许我说的话有些夸张，但我可以向你发誓，如果你能帮我找到从这里逃脱的办法，我一定会对你感激不尽的。现在我被施加了封印，如果你能帮我拿些萨特和劣魔的耳环，我也许能找到一些线索。","小武哥儿"},
[956] = {"巴莎兰","获取远古月亮石封印，把它交给巴莎兰的阿斯特利安。","如果劣魔开始与施加在我身上的封印频频联系的话，我想我已经猜到原因了。毫无疑问，这枚封印已经落入指挥他们的萨特的手中。我强烈地感觉到了这一点，$n。某个萨特得到了那个封印。如果你能得到它，或许就可以帮我冲破这牢笼，我将对你不胜感激。","小武哥儿"},
[957] = {"巴莎兰","用亚米萨兰废墟中的远古火焰摧毁远古月亮石封印，然后回到巴莎兰的阿斯特利安那里。","某位非常强大的贵族制造了这个用来囚禁我的封印。在南方的亚米萨兰有一处与这里相似的废墟，那里至今仍燃烧着远古的火焰，那蓝色的火焰可以摧毁这个封印。不过在那片废墟里，你千万要当心，$n……","小武哥儿"},
[958] = {"上层精灵的工具","帮奥伯丁的桑迪斯·织风取回7个上层精灵的遗物。","，我有一项任务交给你。你去过亚米萨兰废墟吗？如果还没有，你可以在通向南方的大路东侧找找看。亚米萨兰废墟曾经是众多暗夜精灵贵族的家园，而如今那里却成为他们滥用魔法的见证。据哨兵的报告，那些贵族的亡灵依然在使用古代的魔法武器进行抵抗。我们必须获得那些遗物，只有这样我们才有可能真正摧毁那些亡灵。","小武哥儿"},
[959] = {"港口的麻烦","棘齿城的起重机操作员比戈弗兹让你从疯狂的马格利什那儿取回一瓶99年波尔多陈酿，疯狂的马格利什就藏在哀嚎洞穴里。","啊呀！你也看到了，最近有点背运！早间从藏宝海湾过来了一支大型的运货船队，我是说大型的！我从没有见过那么多的箱子。我想加快点速度，所以卸货卸得稍微快了点。结果呢，还没等我弄清楚是怎么回事儿，我看到那个可恶的家伙——疯狂的马格利什——手拿一瓶99年波尔多陈酿跑了出来。我一路追他到了哀嚎洞穴，但是我可不想进到那个可怕的地方去。嗯……你够不够胆量去把他给我找出来？","小武哥儿"},
[960] = {"正在冥想的安努","","","小武哥儿"},
[961] = {"正在冥想的安努","","","小武哥儿"},
[962] = {"毒蛇花","为雷霆崖的药剂师扎玛收集10朵毒蛇花。","幽暗城的皇家药剂师学会派我来这儿完成一个特殊的任务，$n。我想你会愿意帮助我的，因为黑暗女王领导下的被遗忘者将会通过我的任务得到进一步的加强。近来我在研究一种罕见的植物，它的名字叫毒蛇花，我相信这种药草有着巨大的能量。不幸的是，它只生长在哀嚎洞穴的最深处，那是贫瘠之地最危险的洞穴之一。","小武哥儿"},
[963] = {"永志不渝","释放安娜雅·晨路的灵魂，把她的坠饰交给奥伯丁的塞瑞利恩·白爪。","永恒之井的战斗结束以后，亚米萨兰被毁灭了，全城的暗夜精灵都成为了这座城市的陪葬，其中就有我的至爱安娜雅。我也没有想到，在那次灾难过去了数千年之后，对安娜雅的回忆依然萦绕在我的梦中。有一次，当我恍恍惚惚地在黑海岸的森林里游荡的时候，我发现自己正置身于亚米萨兰的废墟之中……我居然看见了我的至爱——她那饱受折磨的亡魂。她必须得到自由，但我没有勇气去做，因为让她得到自由，就必须先摧毁她的亡灵。","小武哥儿"},
[964] = {"骸骨碎片","将15块骸骨碎片交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。","通灵学院大门的钥匙名叫骷髅钥匙，它一定是由某具骸骨制造而成——事实上是若干具骸骨——并在适当的模具中使用最坚硬的金属进行加固。天生就能打开通灵学院大门的人拥有一种特殊的力量，这种力量能让钥匙发挥作用。重要的事情要优先处理掉，。我们需要一些骸骨碎片来制造钥匙。安多哈尔内的骸骨应该符合我们的要求，但是安多哈尔城外的那些骸骨也许同样有效。","小武哥儿"},
[965] = {"奥萨拉克斯之塔","在黑海岸的奥萨拉克斯之塔附近找到巴苏尔·影击。","欢迎你，年轻的<种族>。我是艾莉萨·星风，保卫奥伯丁不受邪恶势力的侵害是我的职责。正因为如此，我派巴苏尔·影击去调查东北方的奥萨拉克斯之塔，那里最近发生了一些怪事。他早就应该回来了，我担心他在森林里碰到了危险，如果你能帮我找到他，并看看他是否一切安好的话，我会非常感激你的。","小武哥儿"},
[966] = {"奥萨拉克斯之塔","在奥萨拉克斯之塔附近帮巴苏尔·影击收集4块破旧的羊皮纸。","一群术士在这座塔的里里外外住了下来。我本应该早些回去向艾莉萨报告，但我想如果我亲自去报告的话也许会错过些什么。德尔格伦怀疑这伙人聚集在塔周围是要密谋什么坏事，但我们对此知之甚少。我手里有一些术士的羊皮卷轴碎片，但我还需要更多的碎片才能解开这个谜。对了，我必须警告你，千万不要冒险进入塔中，因为塔里的术士非常可怕！","小武哥儿"},
[967] = {"奥萨拉克斯之塔","把巴苏尔的信送给灰谷森林中的净化者德尔格伦。","我的主人，净化者德尔格伦，是一位伟大的圣骑士。为了保护森林不受恶魔和亡灵的袭扰，德尔格伦一直在尽全力帮助我们。他向我传授了圣光术和各种其它的战斗技巧。你必须尽快把这个教派的消息告诉德尔格伦。他就驻扎在南方的灰谷森林里的迈斯特拉岗哨。请快一点，我非常担心这个暗滩教派带来的威胁会越来越大。","小武哥儿"},
[968] = {"深渊之神","把《深渊之神》交给铁炉堡的葛利·硬骨。","尽管这本书又旧又破，但你依然能看清封面的标题：深渊中的力量在这本皱巴巴的书里是一串不知如何发音的名字的列表，这些名字后面都注有令人感到不安的头衔称谓、祭祀的方式以及首选的祭品等等……其中很多祭品是活的人型生物。在封面的内侧有这样的文字：“葛利·硬骨的符文和厄运，铁炉堡……经营者：葛利·硬骨。”如果葛利·硬骨卖的是这样的书，那么也许他会把这本书买回去。","小武哥儿"},
[969] = {"祝你好运","收集4块霜槌碎片，把它们交给永望镇的巫医玛艾里。","啊，我一看见你就知道——你想要一个幸运符咒。玛艾里无所不知！在冬泉谷的南部有一道峡谷，那里的巨人身上有时候带有一种具有强大能量的冰块，当然你也可以自己从峡谷中收集冰块碎片。带给我十片霜槌碎片回来，然后我的幸运符咒就是你的了。","小武哥儿"},
[970] = {"奥萨拉克斯之塔","搜集一枚发光的灵魂宝石，并把它交给迈斯特拉岗哨的净化者德尔格伦。","巴苏尔的这封信里的消息真是可怕。这个暗滩教派对我们而言始终是一个很大的威胁，必须尽快清除才行。我和东北方的奥迪拉兰城中的暗滩教派打过交道，他们中的一个人持有一枚灵魂宝石，其中蕴藏着有关这个教派的魔法的秘密。把它交给我，我应该有办法从中找出一些信息来。","小武哥儿"},
[971] = {"深渊中的知识","把洛迦里斯手稿带给铁炉堡的葛利·硬骨。","你也许知道，我喜欢收集各种知识：古老的知识，有用的知识，可以打开神秘通路的知识，可以唤醒沉睡之人的知识。据说有本古老的书卷叫做洛迦里斯手稿，它被藏在黑海岸的黑暗深渊底部。那里是往日死去的精灵安息的地方。那些精灵在他们的城市被毁灭之前都有着广博的知识。到黑暗深渊去找手稿吧，我不会忘记你为我做的事，即使到世界毁灭的那一天……","小武哥儿"},
[972] = {"水之灵契","","","小武哥儿"},
[973] = {"奥萨拉克斯之塔","把伊克鲁德·玛格苏尔之书交给迈斯特拉岗哨的净化者德尔格伦。","伊克鲁德·玛格苏尔，没错，我了解他。他可是一个强大的兽人术士，就住在火痕神殿里，那是一个位于灰谷西南的极端邪恶的地方。至今他并没有给我们造成太大的麻烦，而我也没工夫去对付他，不过现在看起来……他的死期到了。","小武哥儿"},
[974] = {"究根问底","安戈洛尔环形山的克拉兰克要你去找到火羽山中温度最高的地方。当你找到一个看上去很热的地方时，就右键点击温度计来测量当地的温度。不断尝试，直到你找到温度最高的地方。","对我来说，这里的温泉简直就是个不解之谜，这些热量究竟是哪里来的？这些水池离火羽山那么近，我真的想知道火山和温泉之间到底有没有关系。我制作了一个测温计来读取火山的温度，我想要找到温度最高的地方。它是按照我独创的计量单位进行测量的！拿着这个温度计，当你经过某个炎热的地方，就顺便读取一下那里的温度！","小武哥儿"},
[975] = {"玛艾里的容器","与巫医玛艾里再次谈话，然后拿到好运符。","在给你符咒之前，我最好解释一下如何使用它。如果你戴上符咒，你就可以从那些被你干掉的生物身上得到特殊的物品，如果你没有戴上符咒的话，那你就得不到那些物品，懂了吗？这些物品的名字叫做魂精。如果你找到它们，就把它们交给玛艾里，她会帮你解决剩下来的事情。在我给你修理符咒的时候，请在这里等一会儿。","小武哥儿"},
[976] = {"奥伯丁的补给品","护送费罗·艾隆汉安全地穿越灰谷森林，然后和迈斯特拉岗哨的净化者德尔格伦谈一谈。","德尔格伦让我给奥伯丁的哨兵艾莉萨·星风捎信，顺便给她提供一定的补给，但是我讨厌一个人上路。密林深处到处危险的敌人，我可不想让这些物资和信息落到他们的手里。如果你或者其他人能担当我的护卫，我们现在就可以出发了。有你的帮助，我坚信这些物资一定能平安运抵奥伯丁。","小武哥儿"},
[977] = {"雪怪计划！","为永望镇的乌米收集2支完美的雪人角。","现在我已经有了遮盖机体的东西，然后只需再有一件东西就成了。好吧，实际上是两件。两支角！冰蓟雪人王和冰蓟雪人女王身上都有这样的角，它们就住在东南边的洞穴里。那里的雪人数量众多，我想你不会找不到它们的。记住，我只要外观最好的角——绝对不要有伤痕的或者破碎的角！","小武哥儿"},
[978] = {"月光羽毛","从冬泉谷收集10片月光羽毛，然后将它们带给鲁瑟兰村的艾瑞拉斯·琥珀。","从辛特兰收集到的枭兽羽毛中包含着魔法能量的痕迹。这些能量……看来并不是枭兽能够运用的，它们只是简单地蕴含在这些生物体内——而带有这种能量的都是最强悍的枭兽。在研究这个问题的过程中，我听说在白雪皑皑的冬泉谷那有很多的枭兽。那些生物是否携带着相同的能量呢？请帮我找到这个问题的答案，。到冬泉谷去收集它们的羽毛，然后把它们交给我。","小武哥儿"},
[979] = {"兰莎尔拉","在冬泉谷找到兰莎尔拉。","嗯，嗯，这些羽毛上附着的魔法似乎与我以前见到过的很类似……虽然我并不能确定我们会发现什么，但我想你必须继续追查下去，$n。我的一位同事最近到冬泉谷去观察当地枭兽的生态了，你为什么不去找她谈一谈，看看她有些什么发现呢？","小武哥儿"},
[980] = {"新的泉水","到冬泉谷去和多诺瓦·雪山谈一谈。","我听说在北边的冬泉谷里还有其它的温泉。奇怪的是，那地方并没有任何火山的存在。这听起来很有趣，对吗？好吧，如果你想要查个水落石出，那就到冬泉谷去跟我的朋友谈一谈吧。他的名字叫做多诺瓦·雪山，现在就在那温泉附近。温度计的事情真是太感谢你了，祝你好运，再见！","小武哥儿"},
[981] = {"奥萨拉克斯之塔","和迈斯特拉岗哨的净化者德尔格伦谈一谈。","你应该为你所作出的贡献而得到奖励。回到德尔格伦那里，告诉他埃瑟里克斯·纳拉辛已经死在你的手下，暗滩教派也已经被打得一败涂地，溃不成军。","小武哥儿"},
[982] = {"深不可测的海洋","找到银色清晨号的保险箱和迷雾之纱号的保险箱，把它们交给奥伯丁的高尔博德·钢手。你可以在村庄北部遇难的船只里找到这两只箱子。","从我们现在所在位置沿着海岸一直往北可以看到两艘沉船——银色清晨号和迷雾之纱号。这两艘船在穿越茫茫大海，最终将要达到奥伯丁的时候遇到了那些可恶的鱼人，它们现在只能躺在海底作为那些恶棍的战利品了。这两艘船的船长都没有能幸免于难，他们的日志以及其它有价值的东西还锁在船里的箱子中。我希望你能帮我找到这些东西，这对于那些生还的船员也是颇有意义的。","小武哥儿"},
[983] = {"传声盒827号","收集6只蟹腿，把它们放进传声盒827号。","嘿！看看我这划时代的最新发明：传声盒！通过它，你可以和很远的人进行交谈！也许你已经见过它们了，嗯，就是那些上面有操纵杆的盒子。不过传声盒有一个毛病，就是它们需要经常性的维护。而且每一个盒子的问题都不一样，不过我在这个问题上做得就很巧妙！你看，我把每一个盒子都放在那些能给它提供最合适的修理零件的生物附近。现在传声盒827号出了点故障，它就在奥伯丁的南边，需要6只蟹腿来进行修理。我会奖赏你的……","小武哥儿"},
[984] = {"熊怪的威胁","在黑海岸找到一处堕落熊怪的营地，然后向奥伯丁的特伦希斯报告。","，我来这里是想看看魔苔的影响有多么厉害。我的一些同胞险些被泰达希尔的一个堕落的熊怪杀死，而我发誓不会让类似的情况再次出现……更别提更糟糕的情况了。在黑海岸，我已经看见了一系列有关各种生灵堕落的线索，但我需要找到这种堕落是否有蔓延的迹象。我想我们仍然应该通过熊怪来进行调查，你可以帮我找到一个熊怪的营地吗？如果你发现了任何情况，就马上回来报告我。","小武哥儿"},
[985] = {"熊怪的威胁","杀掉8个黑木探路者和5个黑木风语者，然后回到奥伯丁向特伦希斯汇报。","，在侦察敌人方面，你已经展示了足够的才能。但你与他们作战的技能如何呢？并不是所有的冒险者都喜欢面对面的遭遇战，我是某些冒险者更喜欢潜行之类的隐秘行动。如果你觉得自己能行，就到奥伯丁南边的那个熊怪营地吧，那里的熊怪对我们构成了极大的威胁。在那一带活动的都是黑木氏族的熊怪，去杀掉8个黑木探路者和5个黑木风语者，然后回来向我报告。","小武哥儿"},
[986] = {"失踪的主人","收集5张优质月夜猛虎毛皮，把它们交给奥伯丁的特伦希斯。","，你帮了我很多忙，我能不能再请求你帮助一下锐爪和他的主人沃科尔？我可以帮你精心制作一件有魔力的斗篷，它能够让你在寻找沃科尔时畅通无阻，免受黑海岸上任何猛兽的阻挠。不过要制作这件斗篷，我需要从月夜雄虎或者月夜雌虎身上获取几张张上等毛皮。你可以在急弯河以南找到那些月夜猛虎。","小武哥儿"},
[987] = {"<UNUSED>","","","小武哥儿"},
[988] = {"<UNUSED>","Speak to Volcor.","I noticed the cloak you are wearing, 。 If you'd be willing to sacrifice it, I can renew its magics, and use it to escape. The problem with that, though, is you'll be left here in the cave alone.Are you able to make it out of here on your own if we c","小武哥儿"},
[989] = {"<UNUSED>","Speak to Volcor.","If we decide to fight our way out, the plan is simple: we'll make our way down to the road and kill any furbolgs that get in our way…… or anything else that decides it wants to stop us.I wish there was another way, but sooner or later the furbolg thr","小武哥儿"},
[990] = {"灰谷之旅","在灰谷中找到莱恩·狼行者。","，我的主人莱恩·狼行者正在灰谷的阿斯特兰纳城中等你。有了你的帮助，我们至少能稍微控制一下那里混乱的局势。从这儿向南走，沿着路一直前进——只要跟着那些指示牌，你应该不会迷路的。","小武哥儿"},
[991] = {"蕾妮的净化仪式", "在灰谷寻找泰洛尼斯。", "一位长期协助哨兵部队的老友迟迟未归。他出发前曾说找到某件神器可能遏制熊怪对暗夜精灵的袭击——那是某个已故邪恶法师制作的权杖。他提到要在西部山脉脚下的法拉希姆湖神殿寻找镶嵌权杖的宝石，那里在被熊怪占领前曾是宝石保管地。请找到我的朋友。", "小武哥儿"},
[992] = {"加基森水业公司","用未使用的寻水器在流沙岗哨旁边的池中采集水样。一旦你收集到水样，就尽快将其交给加基森的高级勘探员菲兹杜瑟。","如果你感兴趣的话，我们现在正在为加基森水业公司招聘兼职初级勘探员。那些游牧民不断地侵占我们的水井，这迫使我们不得不去勘探更多的水源！沙漠中到处都可能有水的存在，但是只有聪明人才能找到它们。拿着这个瓶子，到流沙岗哨旁的水池那里帮我采集一些水样回来。那个水池旁边有些巨魔在看守着，小心点，完成任务之后尽快把水样送到我这里来。","小武哥儿"},
[993] = {"丢失的主人","找到沃科尔。","，斗篷做好了。你现在可以去寻找沃科尔，我希望时间还来得及。斗篷上的魔法被激活之后持续不了多久间，也许就只有五分钟左右的时间。你可以自行决定什么时候使用它，不过我建议你在找到锐爪以后再用。如果锐爪告诉我的消息是真的，那么你应该可以在南边的某个洞穴中找到他的主人。锐爪会在路边等你，看见它以后向它挥手打个招呼（使用/wave指令），然后它就会将它的主人所在的位置告诉你。","小武哥儿"},
[994] = {"杀出重围","保护沃科尔离开，然后去和奥伯丁的特伦希斯谈一谈。","很好，，就是这样，让我们一起冲出去。我们要杀出一条到锐爪身边的路，到了那里之后我们可以分开行动。不过我想特伦希斯一定会听你来讲述这次惊心动魄的逃亡，所以在我们活着离开这里以后，别忘了尽快去一趟奥伯丁。","小武哥儿"},
[995] = {"偷偷溜走","离开熊怪洞穴，然后去见奥伯丁的特伦希斯。","好吧。我们走。记住，在你逃脱以后，到奥伯丁去找特伦希斯。我会自己赶去那里的。","小武哥儿"},
[996] = {"被腐化的迎风花","","","小武哥儿"},
[997] = {"德纳兰的泥土","把稀土交给奥拉密斯湖畔的德纳兰。","你在往南方旅行吗？你要去奥拉密斯湖吗？如果是这样的话，我有个任务想请你帮忙……我的同伴德纳兰在湖的东岸有个营地，他在那儿对泰达希尔的植被进行研究和试验。他想要一包达纳苏斯的稀土，但送货的在路上耽搁了，我这两天才刚刚收到稀土。你能把这包稀土带给他吗？","小武哥儿"},
[998] = {"被腐化的迎风花","","","小武哥儿"},
[999] = {"梦魇成真","","","小武哥儿"},
[1000] = {"新的边疆","与雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾谈一谈关于议会号召部落成员探索卡利姆多大陆的事情。","注意了，英雄们！塞纳里奥议会正在招募精干的部落成员来帮助他们探索卡利姆多大陆！在塔纳利斯沙漠的西边隐藏着常人难以想像的危险，议会希望有人能光荣地接过这个任务，去探索那个地方。所有对此感兴趣的部落成员都应该去向塞纳里奥议会报到。去和雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾谈谈吧！","小武哥儿"},
[1001] = {"传声盒411号","从位于传声盒411号附近的深海中收集3颗黑海岸蛇颈龙的眼球。","细小的声音辟里啪啦地从机器内部传出来。“这里是维兹班恩！下一个传声盒在奥伯丁北部海岸上的某个地方。我的记性有时候不太好，不好意思！那台传声盒的编号是411，需要3颗蛇颈龙的眼球来修理。你可能得跳进漆黑冰冷的大海深处去寻找黑海岸鱼龙……真抱歉……就像上次一样，只要你给传声盒带去维修所需的物资，它就会给你吐出报酬的。*打嗝*……什么？没事，我很好！”","小武哥儿"},
[1002] = {"传声盒323号","收集6颗月夜猛虎的牙齿，把它们放进传声盒323号。","传声盒突然静了下来，然后你听见维兹班恩又开始说话。“下一个传声盒的编号是323。它在奥伯丁北部，不过……我的麦酒哪儿去了？什么？哦，在路上，小桥边，你不会找不到它的。”维兹班恩咕哝咕哝地说了一些不连贯的话，然后你听见大口喝酒的声音。“这个传声盒需要月夜猛虎的牙齿来维修……需要6颗。”","小武哥儿"},
[1003] = {"传声盒525号","收集4块灰色头皮，然后把它们放在传声盒525号中。","在一阵什么东西沸腾和油滴四溅的奇怪声音之后，你听见维兹班恩颤抖的声音从机器中传出。“顺着这条路，在遥远的南方就能找到下一个传僧盒。里应该不难发现它……就在路边上……在栅栏附近。我想我把它藏在矮……矮树丛里了。呵呵呵……没错，传声盒525号得有从那些灰斑蓟熊身上扒下来的灰色头皮才能维修。对，灰色的……呵呵呵……”当机器停止下来的时候，你听到更多类似吞咽的声音。然后，突然之间，它又启动了。“4块！”","小武哥儿"},
[1004] = {"新的边疆","与雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾谈一谈关于议会号召部落成员探索卡利姆多大陆的事情。","注意了，英雄们！塞纳里奥议会正在招募精干的部落成员来帮助他们探索卡利姆多大陆！在塔纳利斯沙漠的西边隐藏着常人难以想像的危险，议会希望有人能光荣地接过这个任务，去探索那个地方。所有对此感兴趣的部落成员都应该去向塞纳里奥议会报到。去和雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾谈谈吧！","小武哥儿"},
[1005] = {"潜藏的危机","","","小武哥儿"},
[1006] = {"隐藏的危机","","","小武哥儿"},
[1007] = {"远古雕像","把远古雕像交给塔尔伦，他的营地就在佐拉姆海岸附近。","我有一项任务交给你，。当我坐船经过被淹没的佐拉姆废墟的时候，受到了纳迦的攻击。这些家伙突然从水里冒出来，他们的利爪差点就把我撕个粉碎！我想尽办法带上所有可以带走的物资逃了出来，然后在这里搭建了一个简易的营地。但是，当我逃上岸的时候……我最重要的宝贝不见了。求求你，，找到我遇袭的地方，帮我寻找一尊古代雕像。正是为了它，我才会鼓起勇气闯入佐拉姆海岸这么危险的地方。","小武哥儿"},
[1008] = {"佐拉姆海岸","收集20颗怒尾纳迦的头颅，把它们交给阿斯特兰纳的辛德瑞尔。","在我们的西北海岸，也就是佐拉姆海岸一带，潜伏着一股邪恶的势力。佐拉姆海岸是已经被毁灭的佐拉姆城残存的部分，佐拉姆主城在大爆炸中被摧毁，沉到了海底，这些很久以前发生的事情已经快要被暗夜精灵忘却了。现在，纳迦又回来了。至于他们为什么会回来，谁也不知道。但是这些并不重要，我们必须杀了这些魔鬼，把他们送回地狱！完成任务之后，就立刻回来向我报告。","小武哥儿"},
[1009] = {"卢泽尔","找到佐拉姆之戒，把它交给佐拉姆海岸边的塔尔伦。","除非你能找到可以打开雕像上的那只锁的钥匙，否则雕像的秘密将永远无法解开。那把钥匙其实是一枚戒指——佐拉姆之戒。在这座城市被很久以前那场大爆炸所掀起的波涛淹没之前，佐拉姆之戒曾经属于这座城市的统治者。这枚戒指已经丢失很多年了，不过纳迦最近找到了它。他们的领导者卢泽尔就住在佐拉姆北部边缘的一个小岛上。请帮我取回这枚戒指吧，。","小武哥儿"},
[1010] = {"巴斯兰的头发","收集5份巴斯兰的头发，把它们带给灰谷的奥雷迪尔·阔叶。","在北边那座巴斯兰鬼屋的废墟上，曾经生长着一种叫做巴斯兰的头发的植物，它能够让人的灵魂安宁下来。在村庄里有个患病的孩子，我想他的病痛不仅仅是肉体上的。你愿意帮我到巴斯兰鬼屋去寻找一些巴斯兰的头发吗？我需要用它来医治这个孩子。巴斯兰鬼屋就在迈斯特拉岗哨以北，灰谷和黑海岸交界的地方。","小武哥儿"},
[1011] = {"被遗忘者的病菌","找到一瓶病毒，把它交给慰藉之林中的凯尼斯·静风。","被遗忘者——部落中的亡灵势力——已经潜入了灰谷，现在就潜伏在我们的废墟和洞穴之中。我们认为他们的目标是在暗夜精灵的领地上散播疾病。这一点必须尽快得到确认！被遗忘者在南边有一个营地，就在朵丹尼尔兽穴附近，那是他们制造和封装毒物的地方。攻入那个营地，给我偷取一瓶病毒，我得研究一下这些毒药，这样才能搞清他们真正的意图。","小武哥儿"},
[1012] = {"疯狂的德鲁伊","杀死这些德鲁伊：坦尼尔·黑木、尤希尔·唤月和玛沃里斯·裂云，然后向慰藉之林中的凯尼斯·静风复命。","在我和被遗忘者的毒物抗争的时候，曾经在恍惚之中产生了一段幻觉，我看到朵丹尼尔兽穴中的德鲁伊被亡灵下毒害死了！他们现在是游荡的幽灵，他们的灵魂离开了身体，并且变得越来越疯狂。为了让德鲁伊的灵魂早日安息，你必须进入朵丹尼尔墓穴，杀死那些昔日的德鲁伊领袖：坦尼尔·黑木、尤希尔·唤月和玛沃里斯·裂云。赶快去吧。","小武哥儿"},
[1013] = {"乌尔之书","把乌尔之书交给幽暗城炼金区里的看守者贝尔杜加。","，在影牙城堡里有一本书，它被称作乌尔之书，我很想得到它。乌尔在天灾军团到来之前曾是达拉然的一位伟大的法师，他对其它世界的研究对……被遗忘者中的某些团体……很有价值。到影牙城堡去找到这本书，把它交给我，我会向黑暗女王汇报你的贡献。","小武哥儿"},
[1014] = {"除掉阿鲁高","杀死阿鲁高，把他的头带给瑟伯切尔的达拉尔·道恩维沃尔。","现在我已经对整个诅咒有了一个全面的了解，并开始着手研究如何补救了。但阿鲁高依然好好地住在影牙城堡中。在干掉阿鲁高之前，我们还不能宣称银松森林已经是黑暗女士的地盘。但是，我得去搞明白怎样才能根除他的魔法影响，$n。所以我只能把除掉阿鲁高的任务交给你了。到影牙城堡去，永远地结束阿鲁高的肮脏法术。把他的头给我带来！影牙城堡去，永远地结束阿鲁高的肮脏法术。把他的头给我带来！","小武哥儿"},
[1015] = {"新的边疆","与达纳苏斯塞纳里奥区的大德鲁范达尔·鹿盔谈一谈关于议会号召联盟成员探索卡利姆多大陆的事情。","注意了，英雄们！塞纳里奥议会正在招募精干的部落成员来帮助他们探索卡利姆多大陆！在塔纳利斯沙漠的西边隐藏着常人难以想像的危险，议会希望有人能光荣地接过这个任务，去探索那个地方。所有对此感兴趣的联盟成员都应该去向塞纳里奥议会报到。去和达纳苏斯的大德鲁伊范达尔·鹿盔谈谈吧！","小武哥儿"},
[1016] = {"元素护腕","收集5个完整的元素护腕，并对它们使用占卜卷轴。然后把使用过的占卜卷轴带给银风避难所的哨兵维尔莉妮·星坠。","拿着这张占卜卷轴——它可以侦测出那些水元素是谁召唤出来的。但是你必须从水元素身上拿到一些东西才能查到真相。只需几个完整的元素护腕就可以完成占卜过程，其它类型的护腕对我们没什么用，但是也许会有商人想要收购那些东西。当你拿到了完整的元素护腕之后，就对它使用占卜卷轴，得出结果之后回到我这里来，让我们看看下一步该怎么办。","小武哥儿"},
[1017] = {"召唤者","干掉萨瑞鲁斯·法伯尼，把他的首级交给银风避难所的哨兵维尔莉妮·星坠。","这世上只有一个法师——就是那个躲在贫瘠之地的亡灵法师——才能够召唤出那么多的水元素来。也只有他这样白痴的家伙才会想要这么做。现在这个名叫萨瑞鲁斯·法伯尼的蠢货恐怕正坐在鬼雾峰顶嘲笑我呢。$n，你必须深入敌人的领地，干掉这个卑鄙的家伙。关于这家伙的白痴行为我已经听说得够多了。我们要让他知道挑衅我们哨兵部队会有什么样的下场。杀了他，带他的人头回来见我。不过你得当心，部落那边可是危机四伏的。","小武哥儿"},
[1018] = {"新的边疆","与雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾谈一谈关于议会号召部落成员探索卡利姆多大陆的事情。","注意了，英雄们！塞纳里奥议会正在招募精干的部落成员来帮助他们探索卡利姆多大陆！在塔纳利斯沙漠的西边隐藏着常人难以想像的危险，议会希望有人能光荣地接过这个任务，去探索那个地方。所有对此感兴趣的部落成员都应该去向塞纳里奥议会报到。去和雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾谈谈吧！","小武哥儿"},
[1019] = {"新的边疆","与达纳苏斯塞纳里奥区的大德鲁范达尔·鹿盔谈一谈关于议会号召联盟成员探索卡利姆多大陆的事情。","注意了，英雄们！塞纳里奥议会正在招募精干的部落成员来帮助他们探索卡利姆多大陆！在塔纳利斯沙漠的西边隐藏着常人难以想像的危险，议会希望有人能光荣地接过这个任务，去探索那个地方。所有对此感兴趣的联盟成员都应该去向塞纳里奥议会报到。去和达纳苏斯的大德鲁伊范达尔·鹿盔谈谈吧！","小武哥儿"},
[1020] = {"奥雷迪尔的药剂","把奥雷迪尔的药剂交给阿斯特兰纳的皮尔图拉斯·怀特姆恩。","，我合成了一种药剂，相信它能帮助这个饱受折磨的孩子。把药带到阿斯特兰纳去，交给这孩子的父亲皮尔图拉斯·怀特姆恩。顺着这条路向南走，然后向东转，就能看到阿斯特兰纳了。","小武哥儿"},
[1021] = {"身陷危险的树妖！","到萨维亚去找到安妮莉亚。","听着，我不知道你是谁，但我需要你的帮助。我的姐妹们去从萨特那里取回塞纳留斯的树枝，她们说会很快回来，可是已经过去两天了！$n，你得赶快去找到我的姐妹们，她们到去东北边的萨维亚去寻找一个暗夜精灵的废墟了。我的脑海里是一片空白，不知道该干什么了……去找到安妮莉亚吧，她是这次搜寻行动的首领。","小武哥儿"},
[1022] = {"狼嚎谷","到狼嚎谷去，研究一下麦尔莎迪丝之书，然后向林歌神殿的哨兵梅丽瑞亚·霜影复命。","尽管我们投入了大量的物资和人力想要将剩余的恶魔赶出北方的费伍德森林，但是看来似乎并没有什么效果。我们只能把大部分的恶魔御于灰谷之外。在北方的费伍德森林附近，有一群神秘的狼人占据了麦尔莎迪丝神殿的废墟。他们令人心颤的嗥叫使得那个地区得了个“狼嚎谷”的名字。保存在神殿中的麦尔莎迪丝之书也许能让我们知道这些狼人出现在这里的原因。","小武哥儿"},
[1023] = {"莱恩的净化","找到发光的宝石，连同泰洛尼斯的日记一起交给阿斯特兰纳的莱恩·狼行者。","在检查泰洛尼斯的遗物时，你发现了一本完好无损的日记。你收起日记之后就离开了泰洛尼斯的尸体。接下来你唯一要做的事情就是找到泰洛尼斯一直在寻找的那颗宝石。莱恩曾经提到过宝石就在这个地区，也许在鱼人的手里……","小武哥儿"},
[1024] = {"莱恩的净化","在东北方的月亮井旁找到莎尔蒂恩。","你得自己去进行研究，但是从泰洛尼斯的记录来看，你下一阶段的工作将是去寻找达图尔所造的魔棒的其它部分。我建议你从伊瑞斯湖东部的月亮井开始。如果你准备好了，就沿着这条路越过环绕着伊瑞斯湖的群山，然后向北走。一个名叫莎尔蒂恩的树妖会在那里为你提供向导。记得带上宝石，如果莎尔蒂恩愿意帮你重造魔棒，她肯定会需要这块宝石的。","小武哥儿"},
[1025] = {"先发制人","杀掉污林氏族里的1个污林卫兵、2个污林巨熊、10个污林萨满祭司和12个污林战士，然后回到阿斯特兰纳向莱恩·狼行者复命。","在你出发去月亮井之前，如果你愿意测试一下自己能力的话，我还有另外一项可以造福灰谷的任务交给你。沿着这条路一直向东走，在靠近弗伦河的地方有一些熊怪频频攻击过路的旅客。他们扭曲的灵魂只有在给别人带来恐惧时才能得到抚慰，他们疯狂的心智只有在啜饮无辜者的鲜血时才能得到满足。帮助哨兵部队守护我们的领地，去对付那些熊怪吧，以血还血，以牙还牙。我认为他们的营地应该在这条路的南方……你要多加小心。","小武哥儿"},
[1026] = {"莱恩的净化","找到木制钥匙和一段达图尔的魔棒，然后回到月亮井的莎尔蒂恩那里。","情况越来越糟糕了。莱恩的猜测是对的，我很了解达图尔的发明以及这个地区的树人——至少我曾经了解。树人们现在开始堕落了，他们的灵魂变得扭曲。如果你想要找到魔棒的下一块碎片的话，就必须先找到一把木制钥匙，用它来打开锁住这块碎片的箱子。这把木制钥匙就在东北方的费伍德森林附近的一个树人手里。得到了钥匙之后，你就可以顺着这条路向西走，在靠近费伍德森林的边界地区寻找一小块林间空地……箱子就藏在那里的某个地方。","小武哥儿"},
[1027] = {"莱恩的净化","找到达图尔的魔棒的最后一段，然后回到月亮井旁的莎尔蒂恩那里。","魔棒的最后一段是由朵丹尼尔的德鲁伊保管的，但是我不清楚他们把它藏到了什么地方。很抱歉，恐怕我只能帮你这么多了。我所能告诉你的就是：顺着这条通向贫瘠之地的路一直走下去，这群德鲁伊隐居在路的东边，可是他们也没法帮助你，因为他们最近被杀死了……那是一段我不愿再回忆的过去。如果你找到了最后一段魔棒，就把它带回来交给我，我会帮你修复魔棒的。","小武哥儿"},
[1029] = {"莱恩的净化","回到阿斯特兰纳的莱恩·狼行者那里。","我建议你去找莱恩，告诉她魔棒的魔力已经复原了。我想她会告诉你下一步该做什么的。祝你好运，。","小武哥儿"},
[1030] = {"莱恩的净化","找到一个尚未堕落的熊怪，利用达图尔的变形魔棒的能力与其交谈。","唉，我不能完全肯定地说他下一步想要做什么。如果他关于魔棒的说法是真的，那么这根魔棒就可以将你变成另一种形态——我也不知道会变成哪一种形态。也许他本想利用魔棒的力量更加靠近那些堕落的熊怪，可是假如他不当心的话，就连没有堕落的熊怪也会杀了他。 在变形之后，达图尔得找到一个没有受到魔苔影响的熊怪谈谈。","小武哥儿"},
[1031] = {"塞纳留斯的树枝","杀掉加萨里斯，把塞纳留斯的树枝交给林歌神殿的伊莉亚娜。","安妮莉亚把手放在你的肩头上，慢慢地把你拉近她的身边。她艰难地喘着气，抬手指向北方的拱门。在她的气息渐渐变得微弱，眼睛慢慢地闭上之前，安妮莉亚留下了最后一句话：“被他夺走了……加萨里斯……”她临终时还在想着要让塞纳留斯的树枝回到树妖的手中。","小武哥儿"},
[1032] = {"猎杀萨特！","收集16支萨特的角，把它们交给林歌神殿的伊莉亚娜。","我不敢相信安妮莉亚居然离我而去了……我们以前天天都在森林里一起游玩。我感觉很……难过。也许有一个办法可以让我感觉好一点。请你去杀了那些从我身边夺走安妮莉亚的萨特！请你把它们的角拿给我作为证明，我会永远感谢你的。","小武哥儿"},
[1033] = {"月神之泪","找到月神之泪，把它交给阿斯特兰纳的皮尔图拉斯·怀特姆恩。","我曾把挽救蕾拉的生命的希望寄托于奥雷迪尔的医术上，可让我担心的是，那只能延缓疾病在我孩子体内的蔓延而不能让她彻底痊愈。我们一定要找到更有效的药物！感谢奥雷迪尔，他告诉我如果第一种治疗方法不能起作用的话，还有下一步的治疗方法。有一种名叫月神之泪的特殊的石头，只有在阿斯特兰纳东部的伊瑞斯湖中心的小岛上才能找到它。奥雷迪尔说这块石头能治疗一切疾病……求求你，，帮我找来月神之泪，祈求它能结束我孩子的痛苦。","小武哥儿"},
[1034] = {"星尘废墟","收集5份星尘，把它们交给灰谷的皮尔图拉斯·怀特姆恩。","月神之泪减轻了我女儿的一些病痛，感谢艾露恩，她发恶梦的次数也大大减少了。可是……她仍发着高烧。奥雷迪尔告诉我，在南方的星尘废墟中可以找到一种结晶的星尘，或许它能缓解蕾拉的高烧。请你帮我收集一些星尘吧。愿艾露恩保佑你速去速回。","小武哥儿"},
[1035] = {"坠星湖","从沼泽兽智者那里取回一枚陨落的月亮石，并把它带给阿斯特兰纳的皮尔图拉斯·怀特姆恩。","蕾拉的高烧退了，但她还是很虚弱。我想她很难靠自己的力量康复，我们可能要借助月亮石的魔力才能让她痊愈。过去我们常在东南部的坠星湖搜集月亮石……但是沼泽兽来了之后就不行了。这群野兽的领袖是一个沼泽兽智者，它成堆成堆地收集所有从天上掉下来的月亮石。现在，你得从沼泽兽智者那里取回一枚月亮石。要达到这一目的，恐怕你必须先杀了那个沼泽兽智者。","小武哥儿"},
[1036] = {"嘿，水手！","登上停泊在荆棘谷海岸边的红雾号，与船里的舰队指挥官菲尔拉伦谈一谈。","……对，我听说过你。我听说你不是藏宝海湾的朋友——就像我们血帆海盗一样。舰队指挥官菲尔拉伦正在征召像你这样精力充沛的去执行一个特殊的任务。如果你感兴趣的话，就去红雾号的甲板下找他吧。红雾号就停泊在这里东面的海岸边，靠近斩浪号和达姆希的好运号。","小武哥儿"},
[1037] = {"维琳德·星歌","在达纳苏斯的战士区与塞恩提尔·刃纹谈一谈。","维琳德·星歌是我在灰谷森林的前任指挥官。起初，她似乎将费伍德森林的一切都调理得井井有条，然而她对于森林的影响却变得越来越小。终于有一天，她突然消失了。我被派来接替她的工作。不过恐怕我对于这位女祭司了解得并不使很多。也许哨兵部队的指挥官塞恩提尔·刃纹会知道更多有关她失踪的细节。当然，她也知道这件事情的重要性。","小武哥儿"},
[1038] = {"维琳德的日记","在维琳德的箱子里搜寻她的日记，把日记连同钥匙一起交给达纳苏斯的塞恩提尔·刃纹。","你是由麦尔萨迪斯之书中得知这一切的？我认为你应该去检查一下她的所有物品，虽然那样做可能不太妥当。用这把钥匙可以打开她放在哨兵小屋里的储物箱。她把平时的工作都记录了下来，因此你从她的日记中应该可以了解到很多事情。我应该告诉你，哨兵们认为她是因为某些特殊的原因而离开的，她随时都有可能再回来。女祭司过去做过很多让我们对她倍加信赖的事情。","小武哥儿"},
[1039] = {"贫瘠之地的港口","和棘齿城的码头管理员迪兹维格谈一谈。","棘齿城是贫瘠之地唯一的港口。最有可能发生的情况是，维琳德在棘齿城登上了一条驶往艾泽拉斯的黑水湾的商船。我们和管理港口的那些地精交往有限，不过码头的管理者应该有来来往往的乘客的信息。顺着这条路往东南方走，过了灰谷就进入贫瘠之地了。你要当心，$n，部落一方的战士一直在那片土地上巡逻。不过，在港口地区你应该是安全的。","小武哥儿"},
[1040] = {"藏宝海湾的航道","坐船去藏宝海湾，和旅行者拉兹戈特谈一谈。","啊，终于找到了。她是很久以前经过这里的，你看……维琳德，乘黑色鱼鹰号去往藏宝海湾。其它的没什么要说的了，我想那艘船应该是安全抵达目的地了。我没有什么可以帮你的啦，不过她问过一些关于在那片陆上旅行的事情，我向她提到了拉兹戈特，一个藏宝海湾的商队成员。没准维琳德会去找他当导游什么的。现在出发吧，我没时间再陪你了。","小武哥儿"},
[1041] = {"商队通路","与夜色镇的书记员达尔塔谈一谈。","若我说的不对请不要见怪，我应该记得没错，毕竟不是每天都会发生这样的事儿的。我记得你要找的那个维林德。那是不久前发生的事，要知道，不是每天都会有一位漂亮的夜精灵女祭司会愿意搭着我这辆破烂的大蓬车旅行的，不过，我的车用来代步的确很不错，不是么？我们在向北去的路上分手了，她往夜色镇去了。那里的书记员应该有所有的出入记录，或许从那里你能知道些对你有用的东西。在丛林里你最好多加小心，即使是在安全的时节，那儿仍然是个危险的地方。","小武哥儿"},
[1042] = {"卡尔文家族","去和夜色镇的乔纳森·卡尔文谈谈。","不，夜色镇没有关于这个维琳德·星歌的任何记录……不过如果你不介意的话，我想说，我很难想像一个暗夜精灵的女祭司会在旅店里过夜，你懂我的意思吗？不过我听说过你提到的这些狼人。就在前几天，卡洛尔还提着几个狼人的头到镇上来。卡洛尔是为卡尔文家族效力的，这个家族专门对付恶魔、亡灵和各种杂七杂八的怪物。你去和乔纳森谈谈吧，他是卡尔文家族的首领。","小武哥儿"},
[1043] = {"月神的镰刀","去找关于月神镰刀的消息，然后回到夜色镇见乔纳森·卡尔文。","你的故事听上去不像是假的……我不能完全理解你的动机，不过如果你想要除掉暮色森林的狼人，我就不需要了解这些。在南方有一座矿山，很多狼人在那里出没……天知道他们是从哪里冒出来的，不过据我们所知，他们最早就是在那里出现的。去忙你的吧，不过如果你有什么重要消息，请一定要告诉我。我们需要所有能帮我们对抗邪恶的信息。","小武哥儿"},
[1044] = {"问题的答案","回到达纳苏斯去见塞恩提尔·刃纹。","不要担心，我们会解决狼人的问题，也一定可以遏制这些由你朋友引到森林里来的邪恶势力。对于你的朋友，我也没有什么敌意。各种诡异的事情越来越多了，$n，黑暗的势力不会停止它的脚步。我就不耽搁你了，可能还有其他人想要知道你在暮色森林的矿山里发现了什么。","小武哥儿"},
[1045] = {"莱恩的净化","杀死兰恩·血牙和4个血牙保镖，然后向密斯特拉湖附近的克罗尔格复命。","暗夜精灵是个历史悠久的种族，但是他们的傲慢毁灭了他们的世界。现在，这样的傲慢也毁掉了我们的生活，一切都失控了……我把许多灾难归咎于那些精灵们，但是我们也应该为自己的行为承担责任。即使在堕落之前，我们也具有非常邪恶的一面。兰恩·血牙就是这种邪恶面的体现。对权力的渴望，无尽的物欲……现在的堕落只会让他更加强大。我的心中燃烧着对这些精灵的怒火，但我对他们的后代并无恶意，我们也必须管教好自己的儿女，让他们不再重蹈我们的覆辙……","小武哥儿"},
[1046] = {"莱恩的净化","把兰恩·血牙的颅骨和达图尔的变形魔棒交给阿斯特兰纳的莱恩·狼行者。","回到你自己的氏族去吧，让他们知道你在这里取得的胜利。向他们展示你的战利品，并享受胜利的荣耀吧……","小武哥儿"},
[1047] = {"新的边疆","与达纳苏斯塞纳里奥区的大德鲁范达尔·鹿盔谈一谈关于议会号召联盟成员探索卡利姆多大陆的事情。","注意了，英雄们！塞纳里奥议会正在招募精干的部落成员来帮助他们探索卡利姆多大陆！在塔纳利斯沙漠的西边隐藏着常人难以想像的危险，议会希望有人能光荣地接过这个任务，去探索那个地方。所有对此感兴趣的联盟成员都应该去向塞纳里奥议会报到。去和达纳苏斯的大德鲁伊范达尔·鹿盔谈谈吧！","小武哥儿"},
[1048] = {"深入血色修道院","杀掉大检察官怀特迈恩、血色十字军指挥官莫格莱尼、血色十字军勇士赫洛德和驯犬者洛克希，然后向幽暗城的瓦里玛萨斯回报。","当黑暗女王陛下将主要精力放在对付北方的天灾军团时，我更关心那些身边的问题。毫无疑问，有一群自称为血色十字军的人类渣滓正在威胁着我们的领土。提瑞斯法林地目前正被这群红蚂蚁逐渐侵蚀和占据。到修道院里去干掉大检察官怀特迈恩与她手下的那些军官，<职业>。","小武哥儿"},
[1049] = {"堕落者纲要","从血色修道院里找到《堕落者纲要》，把它交给雷霆崖的圣者图希克。","大地之环对那些被遗忘者开诚布公，但是谁又知道那些亡灵们对我们到底有什么意图？虽然被遗忘者与我们结了盟，但他们从来就以精于欺诈而闻名。我们的这个盟约实在是太草率了，也许凯恩会睿智地留意到来自奥格瑞玛的警告。在血色修道院深处，那些疯狂的人类狂热者们守卫着《堕落者纲要》。虽然这帮家伙是如此的疯狂和顽固，但他们的研究也许会对我们有些用处。","小武哥儿"},
[1050] = {"泰坦神话","从修道院拿回《泰坦神话》，把它交给铁炉堡的图书馆员麦伊·苍尘。","未来是已经命中注定了的！我们的命运就像雨点落入大海一样无可改变。不过研究过去也许可以让我们预见未来，并提前做好一些准备。在灾难降临在洛丹伦之前，提瑞斯法林地中有一处藏有许多书籍的地方——老修道院的图书馆，据说有一本《泰坦神话》就收藏在哪里。把它给我拿回来，也许我们可以一起揭开过去的秘密。","小武哥儿"},
[1051] = {"沃瑞尔的复仇","把沃瑞尔·森加斯的结婚戒指还给塔伦米尔的莫尼卡·森古特斯。","虽然我现在是个独立的亡灵，但我恐怕无法再为黑暗女王效力，因为我觉得支撑我生命的力量都被毁了。这一切都是那个审讯员韦沙斯造成的！他折磨了我好几个星期，还拿走我的结婚戒指送给了他的妻子。那个混蛋！复仇……我要复仇！那个自负的笨蛋总是吹嘘他的宝贝老婆南茜多么多么娇艳，她就住在洛丹米尔湖一带，去杀了她，把我的结婚戒指还给我那在塔伦米尔生活的妻子莫尼卡。请帮助我完成这最后的愿望……","小武哥儿"},
[1052] = {"血色之路","将安东修士的表彰信带给南海镇的虔诚的莱雷恩。","我们血色十字军拥有着从壁炉谷到提瑞斯法林地一线的许多要塞。这些要塞构筑了保护洛丹伦大陆的主要防线，我们为此感到十分自豪。你在南艾泽拉斯对抗亡灵的行动已经证明了你的价值。但真正的威胁仍然来自正在洛丹伦北部蔓延的瘟疫。到一处叫做南海镇的城镇去，在那里找到一个名叫莱雷恩的十字军战士，把这封由我亲自密封的表彰信交给他，他将会护送你前往充满荣耀的血色修道院。","小武哥儿"},
[1053] = {"以圣光之名","杀死大检察官怀特迈恩，血色十字军指挥官莫格莱尼，十字军的勇士赫洛德和驯犬者洛克希并向南海镇的莱雷恩复命。","我曾怀着荣耀、忠诚、自豪的心情加入了血色十字军。我曾坚信他们有着将艾泽拉斯的所有亡灵生物都消灭干净的崇高理想。但自从我在提瑞斯法林地的修道院里待了一阵之后，我意识到他们现在已经几近疯狂了。他们认为除了那些穿着十字军制服的人之外的所有人都已经感染了瘟疫，而任何被怀疑感染上瘟疫的无辜者都要遭到他们无情的拷打。以圣光的名义，血色十字军必须被铲除掉。你，$n，必须消灭这个疯狂的组织。","小武哥儿"},
[1054] = {"解除威胁","把达尔·血爪的颅骨交给阿斯特兰纳的莱恩·狼行者。","从阿斯特兰纳出发，一直向北走，你能看到许多蓟皮熊怪。我的侦察兵向我报告说，熊怪的数量在最近几个月里成倍地增加。如果它们的数量变得足够多的话，就可能会直接向阿斯特兰纳发起攻击。你能杀掉多少熊怪就杀多少，但你要把他们酋长的颅骨给我带回来作为证明……我会留在阿斯特兰纳等你的消息，愿艾露恩与你同在。","小武哥儿"},
[1055] = {"莱恩的净化","回到月亮井旁的莎尔蒂恩那里。","完整的魔棒就在你的手中，莎尔蒂恩正在静候佳音。","小武哥儿"},
[1056] = {"石爪峰之旅","拜访石爪峰的看守者奥巴格姆。","森林之魂告诉我，你是个勇敢无畏而且乐于旅行的<职业>。在南方离密斯特拉湖不远的地方，有一条名叫石爪峰小径的隧道，沿着这条隧道走，你会到达石爪山脉中的一个名叫风剪峭壁的地方。到了那儿以后，穿越西南方的峭壁湖，然后向北爬上陡峭的斜坡，就可以到达石爪峰了。看守者奥巴格姆在那里等着你。听从他的吩咐，$n。这次旅程会很危险。","小武哥儿"},
[1057] = {"夺回焦炭谷","石爪峰的守护者奥巴格姆要求你杀死7个血怒鹰身人、7个血怒伏击者、7个血怒杀戮者和7个血怒游荡者。","你应该能猜出来，身为森林之灵的守护者的我为什么会如此愤怒。你翻越了无数山岭来到这里，一路上你应该已经看到在这片土地上都发生了些什么。贪婪正在将这神圣的山脉引向毁灭的深渊。南方的焦炭谷正在遭受那群贪得无厌的机械化工业大军的荼毒。更糟的是，那里的鹰身人竟然拒绝让我们进入那里抚慰大地受到的创伤。把这群肮脏的鹰身人给我赶出去，$n！","小武哥儿"},
[1058] = {"金吉尔的森林魔法","玛拉卡金的巫医金吉尔需要5瓶石爪苔液、5根夜行虎须、30颗巨角鹿的眼球和1块灵龙的鳞片。","我实在是太兴奋了！笼子里的三个小精灵！但我们该对我们这些整天都要抱着树的小朋友们做些什么呢？有了！让他们尝尝那个……他们是怎么叫它来着……“森林魔法”的滋味吧！我首先需要一些苔藓分泌出来的石爪苔液，然后你再从那些凶悍的夜行虎身上给我搞点胡须来。啊，对了，还要许多的巨角鹿眼珠子。还有还有，差点忘记了，还要一块灵龙的鳞片！这些东西都能在石爪峰上找到，动作快点，$n，我要准备施展这森林魔法了！","小武哥儿"},
[1059] = {"夺回焦炭谷","在千针石林与菲拉斯的边境上找到法芬德尔。","虽然血怒氏族目前已经被我们压制住了，但如果我们不采取进一步的行动的话，她们很快就会再度组织起来。在离贫瘠之地很远的南方，有一个叫作千针石林的地方。如果你能从千针石林一直向西走，一直走到菲拉斯森林的边缘，就会在那里找到一位名叫法芬德尔的德鲁伊。这位伟大而睿智的德鲁伊能够召唤大量的森林之灵来帮助我们将焦炭谷变成一片茂密的森林。马上去找到他吧，$n！","小武哥儿"},
[1060] = {"写给金吉尔的信","把达索克的亲笔信交给金吉尔，他住在石爪山的洞穴中。","$n，你能活到现在就足以证明你是个幸运的家伙，我这里有些东西要让你看看。鹰身人的老家离贫瘠之地并不远，她们都来自一个叫做石爪山的地方，从这里往西北方向走很远才能到达那里。虽然那很可能是片危险的地方，但我还是要你帮我把这封信带给一个住在那儿的老朋友，一个叫做金吉尔的巫医。如果他听说塞瑞娜·血羽已经死了的话一定会很开心的，而且，我想你会慢慢发现石爪山其实是个有趣的地方。","小武哥儿"},
[1061] = {"石爪之灵","找到石爪山的希雷斯·碎石并和她谈一谈。","地精们在石爪山地区烧杀劫掠，山灵们已经被彻底地激怒了。土地正在哭泣，而那些可以听到这种哭泣的人……正在聆听着这声音……希雷斯·碎石是部落里的一位前途无量的萨满祭司，她已经被派去了石爪山。她报告说那里到处都是地精的伐木站，并向我们请求支援。到石爪山去和她会合吧，你只需要沿着贫瘠之地的十字路口西边的道路一直前进即可，她的营地就在巨木谷里。","小武哥儿"},
[1062] = {"地精侵略者","杀死15个风险投资公司樵夫，然后向石爪山与贫瘠之地交界处的希雷斯·碎石复命。","由地精运营的风险投资公司进入了石爪山西部，开始无节制地砍伐树木、焚烧森林。森林中的山灵们已经几乎要被地精带来的痛苦与愤怒逼疯了。我们必须阻止风险投资公司的恶行！向西进入巨木谷，你可以在那里找到正在工作的地精和他们的仆从——告诉他们，部落决不会允许他们把石爪山弄得一团糟。用他们最容易理解的语言——暴力——来和他们沟通……","小武哥儿"},
[1063] = {"长者","与雷霆崖的玛加萨谈一谈。","为了彻底平息石爪山的山灵，我们必须与牛头人长老们商讨商讨。我记不清他们那么多首领的名字，但我知道其中肯定有一个名叫玛加萨的。我听说她已经很老了，但漫长的岁月赐予了她无穷的知识。如果说有哪位牛头人能够提供精神力量的帮助的话，那一定就是她了。玛加萨就居住在牛头人氏族的首都城市雷霆崖中的长者高地上，也就是城市西北部的那座高地。去与玛加萨谈谈，告诉她石爪山这边发生的事情。","小武哥儿"},
[1064] = {"被遗忘者的援助","和预见之池的药剂师扎玛谈一谈。","牛头人和这片土地是血脉相连的，听到石爪山陷入困境之后，我感到非常痛苦。恐怕如果我们要治愈这片土地，就必须先着手祛除这片土地上的疾病。说起来也巧，被遗忘者正好和我们结了盟，他们应该对疾病有不少了解。我相信他们能帮助我们，而且他们也能借此加强我们之间的相互信任。去和药剂师扎玛谈谈吧，她是被遗忘者派来的使者。你可以在灵魂高地下的预见之池找到她。","小武哥儿"},
[1065] = {"塔伦米尔之旅","把扎玛的信带给塔伦米尔的林度恩。","为了把风险投资公司赶出石爪山，我们就必须采取极端的措施。极端的，但是不用流血。我的一个同事可能有我们需要的工具，他叫林度恩，就住在希尔斯布莱德丘陵的塔伦米尔镇，那地方在遥远的洛丹伦地区。要去希尔斯布莱德的话，就要先乘飞艇到我们的首都幽暗城，然后往北到提瑞斯法林地，再往西南进入银松森林，最后再转向东南才能到希尔斯布莱德丘陵。找到林度恩，把这封信带给他，里面详细叙述了我们需要什么样的帮助。","小武哥儿"},
[1066] = {"无辜者之血","为塔伦米尔的药剂师林度恩收集5瓶无辜者之血。","我要制造一种毒药，给风险投资公司的那些暴力分子一点教训，让他们不再那么嚣张。这样就能解决部落在石爪山的问题了，不是吗？不过要制造毒素的话，我还需要一些无辜者之血，这种东西很难找。幸运的是，这个地区的人类强盗组织——辛迪加组织雇佣了一些暗影法师……这些法师为了自己的邪恶目的专门收集无辜者之血。到东南方的敦霍尔德城堡去，你可以在那里找到不少辛迪加暗影法师。","小武哥儿"},
[1067] = {"返回雷霆崖","把林度恩的毒药交给雷霆崖的药剂师扎玛。","毒药做好了。用它来对付风险投资公司的话，一定能让我们无往而不利，甚至可能还会有一些意想不到的效果。我得说，看见我的研究成果能在战场上发挥作用真是太令人兴奋了！不过在使用之前，你得先把它拿去给药剂师扎玛。她会想出让毒药发挥最大效果的方法。","小武哥儿"},
[1068] = {"伐木机","杀死伐木机XT:4和XT:9，然后向石爪山与贫瘠之地交界处的希雷斯·碎石复命。","萨满祭司的灵魂魔法与德鲁依的自然魔法之间有着一些共性，因此，我们萨满祭司也能聆听到石爪山山灵的哭诉。它们的大部分话语我已经不记得了，但有一件事……一个景象，却一直清晰地出现在我脑海之中……我记得我看到两台人型的巨大机械在巨木谷西北的狂风峭壁之中以飞快的速度砍伐着树木，你必须去阻止这些金属怪兽的疯狂行径！在我脑海中的景象里，那两台机器上分别标有这样两个奇怪的标志：XT:4和XT:9。","小武哥儿"},
[1069] = {"深苔蜘蛛的卵","收集15颗深苔蜘蛛的卵，把它们交给棘齿城的麦伯克·米希瑞克斯。","煎蜘蛛卵是藏宝海湾的时尚菜肴。问题是……藏宝海湾的蜘蛛卵已经断货了。我发誓这绝对是个赚钱的好机会！在风剪峭壁——就是石爪山的西北地区——那里有一种深苔蜘蛛，如果你能帮我弄来一些深苔蜘蛛的卵的话，我一定会付给你一大笔钱！这些蜘蛛最喜欢在树荫下爬行……但可恶的风险投资公司砍掉了它们赖以生存的大树！不过，你还是到风剪峭壁去找找深苔蜘蛛吧，它们的卵在有树的地方还是很多的。","小武哥儿"},
[1070] = {"守卫石爪山","找到位于石爪山脉狂风峭壁旁的山谷中的凯拉·影矛。","你好，。你看起来真像是个喜欢旅行的<种族>啊。你有没有去过石爪山？现在那个地方被风险投资公司和其他一些暗夜精灵的敌人给占据了。最近，哨兵莱恩·狼行者派我的朋友凯拉·影矛到那里去进行调查，但至今我还没收到她的任何消息。更让我担心的是，联盟还派了一名侏儒法师跟着她……这真是麻烦。你能找到她，然后把她的近况汇报给我吗？","小武哥儿"},
[1071] = {"侏儒学者","杀掉10名风险投资公司樵夫和10名风险投资公司砍树工，然后向石爪山的加克希姆·尘链复命。","你看，，我也是伟大的魔法、化学和工程学研究会的成员，我的目标……嗯嗯，我的使命，便是好好教导这帮暗夜精灵们，让他们知道魔法、化学和工程学的融合便可拯救他们的森林！但这是一场艰苦的战斗，地精们的繁殖速度简直就像兔子一样。我甚至没有时间去搞新的发明！我需要些时间来进行计划和组织。但这需要你的帮助，去帮我把东边狂风峭壁那里的绿皮玩意们干掉一些。","小武哥儿"},
[1072] = {"老同事","与铁炉堡的洛玛克·链带谈一谈。","我正在构想的新装置是这世上最先进的，但我需要有一种特殊的药水来驱动它。我想我们应该得弄一些质量上乘的材料来制作这些东西，也许这会是你这个最后一个任务，所以我当然会希望做得尽善尽美。除此以外，我们还需要一些强力爆炸材料：硝酸甘油炸药。能制出NG-5炸药的只有一个人，那就是我的老朋友洛玛克·链带，你可以在侏儒区的升降机边上找到他。你让他帮我们造些NG-5吧，我要去继续制造我的新装置了。","小武哥儿"},
[1073] = {"失职+药剂=快乐","给铁炉堡的洛玛克·链带拿去4瓶初级法力药水和2瓶初级坚韧药剂。","哈哈哈……你来搞硝酸甘油炸药是为了阻止地精们破坏森林？！我现在不关心你和加克希姆到底熟不熟了……我可以把这玩意给你，谁管最后是你还是他们被炸成碎片！但是还有一个小问题，我现在身边没有成品。只要你把我需要的材料带给我，我就可以马上给你做一些。但在这之前，至少你得证明你在炼金术方面不是个白痴。","小武哥儿"},
[1074] = {"失职+药剂=快乐","将硝酸甘油炸药带回石爪山，交给加克希姆·尘链。","去吧，陌生人。小心点……这玩意很容易被引爆的。如果你真是加克希姆的朋友，别忘了替我跟他问个好。如果不是的话，那么就祝你被炸飞吧。","小武哥儿"},
[1075] = {"马伦的卷轴","找到暴风城的科林·马伦。","好吧，现在我们来研究一下我计划里的远程引爆这部分吧……哦，我有解释过吗，没有？好吧好吧，简而言之就是这样的：只需要一个小魔法，我就可以在远离这玩意的情况下引发爆炸。这么一来，我得给它加一个装置，这样就可以让你只消轻轻按下一个按钮，NG-5便会爆炸。但我需要另一个老友的帮助，就是暴风城里的科林·马伦，让他给我提供引爆用的法术。他就在暴风城的法师区里，他是一个人类，相信你很容易就可以找到他。","小武哥儿"},
[1076] = {"西部荒野中的恶魔","将尘魔的残骸带回给暴风城的科林·玛林。","啊，有了。一个传信法术……我相信你需要的就是这种效果。我会为你做一张抄写有这道法术的卷轴，不过要完成它，我得先弄些尘魔的残骸来。在我找到其它的材料之前，你能到西部荒野去给我抓一只这种邪恶的生物回来吗？它们的确很危险，但我肯定，如果你想为加克希姆的实验做点什么贡献的话，没什么是你不能搞定的。我会在这里等你回来。","小武哥儿"},
[1077] = {"给加克希姆的特快专递","将通讯卷轴交给石爪山的加克希姆·尘链。","拿着这个吧，。这张卷轴会满足你的要求的。当你再见到加克希姆的时候，记得替我向他问好。我正等着听到你们凯旋的消息呢。再见。","小武哥儿"},
[1078] = {"完鳞归玛伦","给暴风城的科林·玛伦带回8片水晶鳞片。","旅行者们一直在问我有关石爪山的事情，看来那里已经成为一个公认的最佳冒险场所了——当然前提是你没有在寻找双足飞龙、元素生物，也没有跟风险投资公司扯上关系。在石爪山脉深处的焦炭谷中还居住着一群披着厚重鳞片的蜥蜴。把那些鳞片磨成灰就是我施放一些法术所必需的原料。如果这些蜥蜴还活着的话，你能不能帮我搞一些它们的鳞片来？注意点时间，不用太着急，而且我会付给你不错的酬劳。","小武哥儿"},
[1079] = {"隐秘行动：A","将风险投资公司工程计划书从峭壁湖的伐木场中偷出来。","就是这样啦，。仔细看着，装置已然准备就绪了。拿着这几张纸——上面已经把引爆和爆炸的具体情况全写明白了呀，当然，包括你该把这些炸药放在哪儿。记住，任务的成功与否并不取决于你炸毁了多少东西，A计划的成功取决于你是否从峭壁湖南部的伐木场里带回了风险投资公司的计划书。","小武哥儿"},
[1080] = {"隐秘行动：B","将风险投资公司函件从峭壁湖最东面的风剪矿洞中偷出来。","B计划跟A计划差不多，。我们分散他们的注意力，然后将重要的信函都给偷出来。关键是要弄到他们的信件……记住这一点。我给你的纸上已然写明白了你该把炸药放在哪里。去吧，活着把那些信带回来……","小武哥儿"},
[1081] = {"泰兰德的接待","到达纳苏斯去找到泰兰德·语风。","，我想泰兰德·语风一定会感谢你接下这个任务。相信我，如果你能很好地完成这个任务，我们在石爪山脉的力量就将大大增强。如果你认为你也可以帮助我们对抗地精的暴行，就去达纳苏斯城的月神殿找到泰兰德吧。","小武哥儿"},
[1082] = {"向塞恩希尔报告","向灰谷的哨兵塞恩希尔复命。","感谢你的巨大帮助，。如果你向她们证实了我和加克希姆还活着的消息，灰谷的哨兵部队一定会重重酬谢你的。告诉她们，我们正在努力地阻止着风险投资公司在此的恶行，努力地为治愈这片大地而忙碌。去找阿斯特兰纳的塔拉·塞恩希尔吧，她会很高兴听到你的好消息的。","小武哥儿"},
[1083] = {"怒灵","从焦炭谷中的任意火元素身上收集8个闷烧余烬，把它们交给石爪山的凯拉·影矛。","我不敢肯定风险投资公司对这座山谷做了些什么，不过显然他们刚来的时候根本没有能力和这里的生物抗衡。于是他们只好在这里放了一把大火，然后用他们那强大的机器在山谷里四处屠杀。而且，这些无知的家伙还释放出了一些乱七八糟的元素生物，把山谷搞得一团糟。这些生物在谷中随意游荡，连艾露恩都不再眷顾这片土地了。干掉那些元素生物，把它们身上的闷烧余烬带给我，以此来作为你曾奋力拚杀的证明。","小武哥儿"},
[1084] = {"受伤的古树","给石爪山的凯拉·影矛带回一块被腐蚀的弹片。","显然，那些一直以来都守卫着山谷的树人们也已开始了驱逐风险投资公司的行动。不幸的是，甚至是这些最伟大的守卫者们也开始逐渐堕落。加克希姆认为他们的堕落与地精们撤退时所使用的某种武器有关。我告诉他，我打算从某个受伤的树人那里收集一份样本，这样他就可以通过对这份样本的研究来确定这个推断是否属实。给我带回一些弹片来，好让那个侏儒来研究它……","小武哥儿"},
[1085] = {"守卫石爪山","与加克希姆谈一谈。","就一个暗夜精灵和一个侏儒的搭档来说，石爪山目前的状况实在是不容乐观。风险投资公司几乎快把这里全都毁了，而我正努力地阻止着他们。请别对加克希姆抱有偏见，他知道我们得精诚合作。如果你愿意帮助我们的话，就先去和加克希姆谈谈吧。很抱歉我现在没法让你给塔拉带去一些好消息，但我想很快就会有了。","小武哥儿"},
[1086] = {"地精空港","把剧毒粮草带到风险投资公司的空港去，然后向药剂师扎玛复命。","毒药已经准备好，接下来就是如何下毒的问题了。，你来负责这个工作。风险投资公司的指挥部和石爪山的基地之间肯定有一条快速传送消息和小型货物的运输线。我想那应该是一个小型空港，它对地精飞艇来说可能还不够大，不过应付一般的飞行器应该是绰绰有余了。到风险投资公司控制下的石爪山地区查查看，如果确实有这样的空港存在的话，就把毒药放在那里。放下毒药就赶快回来。","小武哥儿"},
[1087] = {"塞纳留斯的遗产","为石爪峰附近的布莱林·火拳杀死4名塞纳留斯的儿子，4名塞纳留斯的女儿以及4名塞纳里奥植物学家。","你根本无法想像到我是多么地憎恶这片污浊的土地。石爪峰那里有一小撮可怜兮兮的塞纳留斯族类和暗夜精灵的德鲁依们聚集起来，妄图彻底抑制住魔法的传播……甚至还妄想着夺回他们深深眷恋着的极南之地的森林。尽管我很乐意回到加德纳尔去享受传授魔法的快乐，但在我的工作完成之前，主人恐怕是不会让我回去的。我确信你和我一样，对暗夜精灵一族及他们盟友都没有任何好感。所以，请帮助我吧，这样一来，我们都能得到令自己满意的结果。","小武哥儿"},
[1088] = {"奥达努斯","将奥达努斯的头颅带给石爪峰的布莱林·火拳。","他们自以为能够阻止魔法的传播，但他们无疑大错特错了！他们自以为能藏得住奥达努斯，但我一定要他死！魔法赋予了我真知……没错，我能看到他。一处岔路……就在灰谷森林中的一棵巨树的顶部。这棵巨树的名字叫作……瑞恩伍德。它是森林之神最初的几位子嗣之一。当初，在我找到奥达努斯之前，他就从石爪峰离开了，但现在，他的生命即将结束！把他的头带回来给我，我将送给你一件强力的魔法物品作为礼物。","小武哥儿"},
[1089] = {"大兽穴","到石爪峰上的洞穴中去，使用守门人的钥匙拿到能打开石爪峰顶的猛禽洞穴储藏室的物品。","德鲁依们在石爪城堡中建造了一个石爪猛禽洞穴，在那里面保存着一些威力强大的物品。他们制订了一整套详细的防范方案来避免这些物品落入他人之手。幸运的是，我想尽一切办法从他们当中的某个人口里套出了一些有用的细节。只要你找到那个洞穴入口处的一只小灯笼，就可以拿到守门人的钥匙。用这把钥匙就可以打开隐藏在洞穴中各处的暗格，而暗格里就藏有能打开中央大仓库的工具。","小武哥儿"},
[1090] = {"格雷苏的要求","在匹兹尼克完成开采之后拿到神秘矿石。","你知道的，我曾经是这里的二把手，但在格雷苏接管了这里之后，一切就全变了。我的老板菲兹克斯被他炒了鱿鱼，而我被丢到这片矿里来当苦力。菲兹克斯让我就呆在这里，暗中收集信息，如果我们能知道格雷苏在打什么算盘，菲兹克斯的新老板就会付给我们不错的酬劳。无论如何，现在我知道的是，格雷苏下令要大量地开采这种青绿色的矿石。要不这样，我给你搞出一份样本来，你帮我带给菲兹克斯，但是我在采集矿石的时候，你得帮我留意外面的巡逻兵。","小武哥儿"},
[1091] = {"向凯拉回报","将风险投资公司函件带给凯拉·影矛。","，把这些信拿去交给凯拉。我确定她会对里面的内容有兴趣，至少哨兵部队会感兴趣。记得告诉她，我们的行动是有多么的成功，哦，还有，别忘了强调一下，如果不用点魔法的话，我们是不可能成功的。","小武哥儿"},
[1092] = {"格雷苏的要求","将未经化验的矿石送到石爪山的菲兹克斯那里。","我想我也应该赶紧跑路了。这件事情马上就会传到上头人的耳朵里，而且他们肯定不会给我好果子吃。我得从这里偷偷逃出去，然后去见菲兹克斯。如果他能给我找到一份新工作就再好不过了！我得先把这里给打扫打扫，不能留下什么痕迹，而你最好现在就动身，马上把矿石的样本给菲兹克斯送去。他说他就在狂风峭壁西边建了一片营地，祝你走运！","小武哥儿"},
[1093] = {"超级收割机6000","为石爪山的菲兹克斯偷来超级收割机6000型的设计图。","风险投资公司到底在搞什么鬼啊，嗯？他们到底在想些什么呀？地精的公司里竟然雇佣了一个侏儒！好在斯布特瓦夫是个识货的家伙，知道我是个天才，他在我被公司炒了以后马上就雇佣了我！据说公司正在制造一种新型的大型伐木机，斯布要把我这东西的设计书偷来给他。不过格雷苏——那个满手是血的侏儒——他一看见我就想把我给干掉……或许你能替我去把设计书给偷来？你应该可以在他们的操作员身上找到它。","小武哥儿"},
[1094] = {"新的指示","将密封的信封交给贫瘠之地的斯布特瓦夫。","这信封里有我被撵走之后风险投资公司方面的全部情报……公司内部文件，一些操作手册，技术设备……嗯嗯，当然还有超级收割机6000型的蓝图。斯布特瓦夫就在贫瘠之地的棘齿城，你应该很容易找到他的……特征？太明显了，他的皮肤是绿色的。","小武哥儿"},
[1095] = {"新的指示","把新的指令带给石爪山的菲兹克斯。","风险投资公司雇用侏儒的事情在安德麦引起了太多的风波。贸易巨头们不赞成拉兹杜克与这个叫格雷苏的家伙合作。雷德沃克斯主管让我来处理这个问题，我相信是某几位贸易巨头让他这么做的。当然，主管并没有告诉我这些，只是我自己的猜测而已。不管怎么样，我们必须赶走格雷苏，让菲兹克斯去“照顾”他一下应该是个不错的主意。","小武哥儿"},
[1096] = {"格雷苏","将格雷苏的机械臂带给石爪山脉的菲兹克斯。","我只见过格雷苏一次，但我得告诉你，那家伙一眼看上去就知道他不好对付。他的一部分身体似乎已经残废了，于是他给自己装上了一些金属部件和装备，这样他的部分肢体就机械化了。格雷苏就在西北方峭壁湖的湖岸边上监视着整个地区的工作进展。我想我是没办法去那里了……但你看起来也许有能力对付他。如果你能为我干掉他的话，我会付给你不错的酬劳的。","小武哥儿"},
[1097] = {"艾尔默的任务","与格瑞曼德·艾尔默谈一谈。","暴风城里有位名叫格瑞曼德·艾尔默的矮人铸剑师，他需要有人帮忙送一份东西。据我所知，他是把一个包裹送到他在北方的故乡去。你看上去很强壮，所以如果你有兴趣做这份跑腿工作的话，就去找格瑞曼德吧。我们这儿的确很需要你，但我们也得加强与矮人盟友们的联系。你可以在暴风城矮人区的武器店里找到格瑞曼德·艾尔默。","小武哥儿"},
[1098] = {"影牙城堡里的亡灵哨兵","找到亡灵哨兵阿达曼特和亡灵哨兵文森特。","为了一次针对影牙城堡的突袭行动，我们派了两名亡灵哨兵潜入到城堡内部去收集情报。他们一直没有回来，可如果我们还想让这次攻击行动不至于无功而返的话，就必须收到他们的报告！这就是你的任务了，。潜入南边的影牙城堡并找到亡灵哨兵阿达曼特和文森特。找到他们之后要尽力帮助他们。这个任务很危险，但也很重要，。只许成功，不许失败。","小武哥儿"},
[1099] = {"地精获胜！","","","小武哥儿"},
[1100] = {"亨里格的日记","阅读亨里格·独眉的日记。","你慢慢打开亨里格·独眉的这本破旧的日记……","小武哥儿"},
[1101] = {"卡尔加·刺肋","把卡尔加·刺肋的徽章交给萨兰纳尔的法芬德尔。","可怜的赫尔拉斯！还有这个矮人……他是多么的勇敢。我们不能让他们白白牺牲。卡尔加·刺肋……必须受到制裁。当然，深入剃刀沼泽是非常危险的，但现在已经没有时间通知达纳苏斯了。$n，组织一支队伍去杀掉卡尔加·刺肋。把她的徽章交给我，作为她已死的证明。","小武哥儿"},
[1102] = {"奥尔德的报复","把卡尔加·刺肋的心脏交给雷霆崖的奥尔德·石塔。","凯恩是个高贵而睿智的领导者，是他带我们在雷霆崖建立了新的家园。但我绝对不会原谅那些将我们从世代相传的土地上赶走的家伙。我们在贫瘠之地的南部生活了数十年，这片土地对我们来说是神圣的。但我们却被为数众多的敌人赶了出去。我要对卡尔加·刺肋这个恶棍进行报复，就是他在剃刀沼泽纠集了大批邪恶的部队，让我们背井离乡。把卡加尔的心脏给我带来，这样我才能安息，。","小武哥儿"},
[1103] = {"水之召唤","如果你没能与水之魂交谈，就给银松森林的提夫·摩杜恩再拿去一瓶水之灵契。","你好，我的$g兄弟:姐妹;！你是来净化这里的水并展示从伊斯伦那里学到的东西的吗？我刚刚打败了堕落的水灵，正准备把护腕和余下的水放在火盆上。那是什么？啊……只要有什么地方出了问题，提夫总能洞察一切。如果你想再次见到纯洁的水灵，提夫应该能帮你。从伊斯伦那里拿一瓶水之灵契来证明你已准备就绪，然后接下来的事情就交给我吧。","小武哥儿"},
[1104] = {"含盐的蝎毒","为闪光平原的菲兹尔·铜栓带去6份含盐的蝎毒。","我有很多关于改进火箭车的计划！很多很多！我必须一一尝试！！！我在研究一种新燃料，一种燃烧起来非常非常热的燃料！！但是我还没有将配方制作到尽善尽美，我想我知道还缺什么东西……在闪光平原上游荡的蝎子体内有一种含有很多盐分的毒液，这种毒液非常特别！那正是我想要的！带些毒液给我，相信我——有了这些毒液，我们的赛车就可以快到飞起！！","小武哥儿"},
[1105] = {"硬化龟壳","收集9块硬化龟壳，把它们交给闪光平原的维兹尔·铜栓。","我的兄弟正在为他的火箭车研究一种新燃料。他很聪明，真的，他真是太聪明了……我想他设计的新燃料一定非常强悍，甚至可以蚀穿车子的底盘！为了防止这种情况的出现，我想应该要加固一下燃料箱。这片平原上的乌龟有很硬的壳，我想用它们来制造火箭车的新燃料箱，这样就可以装载我兄弟的新燃料了。你看起来很可靠，愿意去给我弄一些这样的壳吗？","小武哥儿"},
[1106] = {"流放者马特克","把菲兹尔·铜栓的信带给荒芜之地的流放者马特克。","我正在研制一种新的发动机，它可以让赛车开得更快！快到飞起来！我只要有一个能承受重压的活塞就能够完成这个发动机了，但是之前所有的活塞样品试验都失败了，就因为活塞的质地不够硬！我想有人知道怎么解决这个问题。他叫流放者马特克，是个伟大的铁匠，他比任何人都更加了解金属的特性。把这封信交给他，我知道他能帮我！但他在很远的地方，在艾泽拉斯大陆上的荒芜之地，和一个地精同住在一个营地里！去找到他吧！","小武哥儿"},
[1107] = {"坚硬的尾鳍","给闪光平原上的瑞兹尔·铜栓带去10片坚硬的尾鳍。","我们的火箭车是平原上速度最快的！不过有点太快了……我担心高速行驶中的摩擦力会把它给撕开！为以防万一，我要配制一种合成剂来给车子的转动部件涂上。它必须坚固、耐冲击、能抵抗盐分的侵蚀，并且不易老化。你听说过暗礁海吗，？它就在荆棘谷地区的海岸边。盐鳞鱼人在那一带活动，它们的尾鳍正是我所需要的重要原料！","小武哥儿"},
[1108] = {"精铁碎片","收集10块精铁碎片，把它们交给荒芜之地的流放者马特克。","我大老远地跑到这儿来并不是为了躲开什么人。，如果你有足够的勇气，那么荒芜之地的矿藏绝对可以让你大发横财。有一种被称作精铁的矿石，据说它具有很强的耐压和耐热性，这也许会对菲兹尔的车有所帮助。但是我们需要进一步地确定。去帮我找些精铁的样品来测试它的特性吧。真正的精铁矿石深藏在奥达曼，但荒芜之地的石窟穴居人身上常常带着一些矿石碎片，给我找一些这种矿石碎片来。","小武哥儿"},
[1109] = {"蝙蝠的粪便","帮幽暗城的大药剂师法拉尼尔带回一堆沼泽蝙蝠的粪便。","就如你所见到的一样，$n，我们正要在皇家药剂师学会进行一个非常…嗯…有趣的实验。作为这里的领导者，我的职责就是监管所有最具潜质的化学实验。所以说我总是梦想太多，时间太少！你看上去是个擅长跑腿的<职业>，也许你可以帮我的忙。我需要一种稀有的原料，这种原料只有在产于剃刀沼泽的一种罕见的蝙蝠身上才能找到。去剃刀沼泽帮我带回一些沼泽蝙蝠的粪便来，然后我们就可以开工了……","小武哥儿"},
[1110] = {"火箭车零件","收集30个火箭车零件，把它们交给闪光平原的克拉维尔·浓须。","咳咳，所有的赛车跑起来都像飞一样，出一些小事故也就不足为奇了。如果你在闪光平原四周转转的话，就会看到过去撞车事故的遗物——火箭车的碎片散落得到处都是！这些零件对侏儒和地精来说非常值钱，它们一直都想为它们的赛车装上更多的设备。所以你可以去给我搜集这些零件，我会给你巨额报酬的。","小武哥儿"},
[1111] = {"码头管理员迪兹维格","把克拉维尔的零件订单交给棘齿城的码头管理员迪兹维格。","满足人们的需要就是我的工作，现在那边的侏儒弟兄们需要一些零件。一星期前那些零件就已经运到棘齿城了，但我一直都没有时间去取货。所以……你愿意替我跑一趟吗？到棘齿城去，将这张零件订单交给码头管理员迪兹维格——他很可能就在码头上忙活。我的朋友，这些工作的报酬可是非常诱人的哦……","小武哥儿"},
[1112] = {"给克拉维尔的零件","把克拉维尔的零件交给闪光平原的克拉维尔·浓须。","，这是克拉维尔要的货。你把货交给他的时候记得转告他……如果他想要更多的特别订货，就必须得付更多的钱！","小武哥儿"},
[1113] = {"狂热之心","幽暗城的大药剂师法拉尼尔需要20颗狂热之心。","你也许会问我们为什么需要这种粪便，嗯，在这个实验中，我想要看看两种性质截然相反的物质相互作用会产生怎样的效果，特别是当这两种物质都与最具毒性的物质相混合之后，它们将产生……非常惊人的结果。在提瑞斯法林地的东北面有一座血色修道院。那里是疯狂的血色十字军信徒出没的地方。干掉他们，把他们的狂热的心脏给我拿回来。我们制作的混合物将是世上毒性最强的！","小武哥儿"},
[1114] = {"侏儒的货物","把精密赛车零件交给菲兹尔·铜栓。","既然手续齐备，那你就把这些零件带给菲兹尔·铜栓吧。他为此已经等待很久了——我相信他不会在意我从他那些零件中拿了点小东西……当然我也不会和他提这件事情，这对于他来说只是九牛一毛而已，没什么意义。相信我。","小武哥儿"},
[1115] = {"车手的传闻","和藏宝海湾的克拉兹克谈一谈。","既然我们已经为侏儒服务过了，那么也该帮帮地精一把！我听说地精的赛车手，就是名叫纳兹·斯迪波尔的那个，他并不是一直都用这个名字。我想知道他为什么改名字，这其中是否隐藏着一个秘密，还有……我不知道他是否很看重这个秘密。如果说有人知道真相的话，那肯定是在荆棘谷南端的藏宝海湾里的克拉兹克。去找克拉兹克谈谈，问问他关于那个地精驾驶员的事情。如果你从他那儿得到有用的信息的话，我们也许能从中挣一大笔钱。","小武哥儿"},
[1116] = {"沼泽中的梦境粉尘","为藏宝海湾的克拉兹克收集10份梦境粉尘。","你打听到的有关纳兹的消息真是帮了我一个大忙，，确实帮了我一个大忙。既然你已经特意大老远地从闪光平原赶来……那么你是否愿意再多走些路呢？在我想办法打听相关信息的时候，你何不去帮我收集一些东西呢？嗯……怎么样？帮我找一些梦境粉尘吧，你可以在悲伤沼泽的幼龙和龙族的身上找到梦境粉尘。我很喜欢在鼻烟袋里放一点梦境粉尘！给我弄些梦境粉尘来，，我会用你需要的信息和你进行交换。","小武哥儿"},
[1117] = {"地精的谣言","把地精的谣言带给闪光平原的克拉维尔·浓须。","看来我要好好对待自己了，把那瓶稀有的精灵葡萄酒送掉，然后开始减肥！但是我找到了一些你正在寻找的信息。拿着这个，我写了一封信，其中包含了一些关于我们的朋友纳兹的有趣的事情。你可以随便怎么处理它——我自己去传播的话会很危险。记住不要告诉任何人你是从哪里得到它的！","小武哥儿"},
[1118] = {"返回藏宝海湾","把克拉维尔的计划书交给藏宝海湾的克兰克·菲兹巴布。","，我想你是一个值得信赖的<职业>，既能把任务做好，又能严守口风。我在酝酿一个新的计划。这个计划非常危险，但只要成功，我们就能大赚一笔！我想你正是做这件事的最佳人选。首先，你得回藏宝海湾一趟。我很抱歉，好心的，我知道上一个任务也把你派到那儿去，但是这次，还得请你去和克兰克·菲兹巴布谈谈。把这封信带给他，如果他需要帮助，尽你所能去帮他。你的努力会得到应有的回报的。","小武哥儿"},
[1119] = {"赞吉尔的药剂和蠢人酒","把蠢人酒交给克拉维尔。","我已经搞清楚怎样用赞吉尔的药剂和烈性酒来合成更强力的饮料了，我称它为蠢人酒。我知道这东西正是克拉维尔所需要的，但回头你别忘了告诉我它的效果到底如何。还有，，别把这东西放太久，赞吉尔的药剂对酒中的酵母有一种超乎寻常的影响，能让它迅速爆发出惊人的活力来，因此你也就无法长时间保持蠢人酒的新鲜了。","小武哥儿"},
[1120] = {"灌醉侏儒","把蠢人酒带给侏儒车队老板。","我们要用蠢人酒在那些车队的工作人员身上做试验。如果你想在侏儒身上试试的话，那么就拿去吧——把酒交给侏儒车队的老板。不要拖得太久，这种酒会慢慢变质的。","小武哥儿"},
[1121] = {"灌醉地精","把蠢人酒交给地精车队老板。","我们要用蠢人酒在那些车队员工身上做做试验。如果你想在地精身上试验的话，那就拿去吧，把酒交给地精车队的老板。不要拖得太久，这种酒会慢慢变质的。","小武哥儿"},
[1122] = {"向菲兹巴布报告","把蠢人酒试验报告交给藏宝海湾的克兰克·菲兹巴布。","蠢人酒的效果太妙啦！我打赌下一场比赛我们必胜，而且……我很想看看喝了那些酒的家伙们出丑！眼下我只有一个任务交给你了——把这封信带给藏宝海湾的克兰克·菲兹巴布，他一定会很想知道这项试验是不是成功了。而且我们希望以后能够得到更多的蠢人酒！","小武哥儿"},
[1123] = {"拉比恩·萨图纳","与月光林地永夜港的拉比恩·萨图纳谈一谈。月光林地在费伍德森林和冬泉谷之间，可以从木喉要塞中的一条通道抵达那里。","这个任务的内容是这样的，守护者雷姆洛斯在月光林地的总管——拉比恩·萨图纳——正在征集愿意去探索塔纳利斯沙漠以及安戈洛尔环形山地区的冒险者，他就住在月光林地的永夜港里。我想让你明白你出现在那里的重要性，达纳苏斯的暗夜精灵和月光林地的塞纳里奥议会之间的关系越来越紧张。你要抛开种族区别，去和议会的成员谈谈吧。祝你好运。","小武哥儿"},
[1124] = {"废土","在希利苏斯的勇士之墓附近找莱耶·星击谈谈，把拉比恩的信交给他。","在安戈洛环形山以西，穿过西北部的山脊，是一片荒芜的土地——希利苏斯。很少有人知道，暗夜精灵曾在那里与一个邪恶而诡异的种族进行过一场恶战。邪恶最终被封印了，但是我怀疑它们正在蠢蠢欲动，想要让恐惧卷土重来……去寻找我们派往希利苏斯的一名使者，莱耶·星击。他就在勇士之墓，那儿是在战争中牺牲的勇士们安息的地方。把这封信交给他，他就会信任你。","小武哥儿"},
[1125] = {"南风村的灵魂","在南风村释放8个被折磨的德鲁伊和8个被折磨的哨兵的灵魂，然后向希利苏斯勇士之墓的莱耶·星击复命。","在我们的西南方有个悲惨的地方——南风村的遗迹。我们就从那里开始吧，。根据我所掌握的情报，那座村庄曾经是暗夜精灵在希利苏斯的基地。很久以前异种蝎群攻陷那里，并将其夷为一片废墟。我简直不敢去想像南风村被虫群吞没的恐怖景象……那些饱受痛苦的德鲁伊和哨兵的亡魂在那座遗迹中漫无目标地游荡。探索那个地区，并释放那些悲惨的灵魂。","小武哥儿"},
[1126] = {"塔中之巢","爬上南风村的塔，找寻激活异种蝎群的方法。把任何你认为不寻常的东西交给希利苏斯勇士之墓的莱耶·星击。","我们必须找到南风村的异种蝎巢穴，而我知道有一个方法可以找到它。以我的经验来看，它们对于周围的环境很敏感，这也就解释了为什么它们会在听到灵魂的死亡嚎叫之后发起攻击。塔里的异种蝎群最为强大——就是那座有很多飞虫围绕着的塔。爬上那座塔，然后骚扰虫巢。向我汇报你所发现的东西！如果你找到了什么有价值的东西，就把它带回来给我。","小武哥儿"},
[1127] = {"蠢人酒","收集12份赞吉尔的药剂，把它们交给藏宝海湾的克兰克．菲兹巴布。","你想要一些蠢人酒？是用在赛车比赛上么……好吧，给我弄些赞吉尔的药剂来，我就给你调制更多的酒。","小武哥儿"},
[1128] = {"<NYI> The Gnome Pit Crew is Thirsty","","","小武哥儿"},
[1129] = {"<NYI> The Goblin Pit Crew is Thirsty","","","小武哥儿"},
[1130] = {"梅洛的关注","和雷霆崖的梅洛·石蹄交谈。","，梅洛·石蹄已经听说了你的作为，并为你的将来做了打算。如果你愿意的话，去雷霆崖和他谈谈，他就在猎人高地上。","小武哥儿"},
[1131] = {"钢齿土狼","把钢齿土狼的肋骨带给雷霆崖的梅洛。","有时我们为了食物而狩猎，有时我们为了荣耀而狩猎，而有时我们为了得到大地母亲的教诲而狩猎。但是这次我让你去捕猎的却是一个例外中的例外，我要你去杀死一个不被大地母亲所祝福的生物。这个名叫钢齿土狼的生物游走于贫瘠之地南面的千针石林，它是个残暴的统治者，它率领着其它的土狼，给原本平静的兽群带来恐惧和无谓的伤亡。找到钢齿土狼，，找到它，打败他。","小武哥儿"},
[1132] = {"菲欧拉·长耳", "与塞拉摩的菲欧拉·长耳交谈", "啊，多么渴望再次扬帆远航！感受海风的亲吻，让波浪像多年前温柔的慈母般轻摇！我真羡慕你的好运，冒险者，因为我从你身上看到了大海的未来！我的工作就是为渴望机遇的灵魂指引卡利姆多大陆的方向。如果你愿意跨海冒险，就从这里乘船前往美丽的塞拉摩港吧。到那里找我的搭档——精灵菲欧拉·长耳，她会带你开启卡利姆多的冒险！", "小武哥儿"},
[1133] = {"通往阿斯特兰纳的旅途","到阿斯特兰纳去和辛德瑞尔·速火谈谈。","如果你刚从米奈希尔港坐船过来，那么你应该先到阿斯特兰纳去。我确信像你这样热心的联盟成员会在这里有一番作为的。和辛德瑞尔·速火谈一谈，尽可能地帮助他吧。对了，你不必提起我，因为辛德瑞尔根本不认识我……","小武哥儿"},
[1134] = {"石爪山的双足飞龙","收集12个巨翼双足飞龙的毒囊，并把它们交给阿斯特兰纳的辛德瑞尔·速火。","尽管我们还没有跟部落全面开战，但是这来之不易的和平却已经处于崩溃的边缘了，最近他们愈加频繁地展开针对我方的秘密行动。我们安插在塞拉摩的密探向我们报告说，在石爪峰南面的暗色湖一带有许多巨翼双足飞龙在活动，而兽人正在该地收集它们的毒液，然后兽人的刺客就会使用这些毒液来悄无声息地对联盟发动致命的突袭！如果他所说的都是真的，那么我们就必须阻止他们，。我们必须切断他们的毒液来源！","小武哥儿"},
[1136] = {"霜喉雪人","把霜喉雪人的鬃毛带给雷霆崖的梅洛·石蹄。","，你现在得去跑一趟远路，而且我想你应该已经准备好了。你的任务是去猎捕霜喉雪人，它是奥特兰克山里的一个雪人。霜喉雪人可不是那么容易就能被抓到的，因为它白色的毛皮与山中的皑皑白雪融合在了一起，很难分辨，而且它极少暴露自己。不过现在我要教教你如何把像它这样的家伙给引诱出来。拿着这个卷轴，我已经在上面写好了诱捕霜喉雪人的方法。现在就动身吧，。你的旅途漫长而充满挑战。只有当你拿回霜喉雪人的鬃毛的时候，你的任务才算是完成了。","小武哥儿"},
[1137] = {"回复菲兹尔","和闪光平原的菲兹尔·铜栓谈一谈。","精铁有惊人的抗热性！我肯定它对菲兹尔要制造的活塞有所帮助，但他需要真正的精铁矿石，而不仅仅是一些小碎片。完美的矿石只能从荒芜之地北部边境的奥达曼挖掘场深处采到，只有那里才是精铁矿真正的产地。请代我向菲兹尔·铜栓致意，并把我对你说的话告诉他。路上小心，。我相信我们会再次见面的。一旦菲兹尔知道有精铁这样一种东西，他一定会让你帮他去奥达曼采集那些矿石的！","小武哥儿"},
[1138] = {"海中的水果","收集6块优质蟹肉，把它们交给奥伯丁的古博·布拉普。","我爱螃蟹，螃蟹就好像是海中的水果！你可以把它烤了吃、煮了吃、炖了吃、炸了吃、炒了吃、煎了吃；你可以把螃蟹做成螃蟹色拉、螃蟹汤、螃蟹炖肉、黑胡椒螃蟹、柠檬汁炖螃蟹、清蒸螃蟹和铁炉堡特级螃蟹——这就是螃蟹存在的意义！我现在要留在这里钓鱼，所以没有办法自己去找到上好的螃蟹肉。你可以从暗礁蟹和硬壳潮行蟹身上得到品质上乘的螃蟹肉，然后把它们烤了吃、煮了吃……","小武哥儿"},
[1139] = {"意志石板","找到意志石板，把它们交给铁炉堡的顾问贝尔格拉姆。","通过切断暗炉氏族与黑石塔的联系，我们已经成功减缓了他们的行动。不过，铁趾的遗愿仍未完成，他不能就这么白白死去。他的梦想是要找到意志石板，那是一块注入了魔法能量的石头碎片。利用这种魔法，泰坦赋予那些由他们创造出来的物体以鲜活的生命，甚至将思想和意志赐予这些生命。我们必须赶在暗炉氏族之前找到意志石板。返回奥达曼去找到石板，然后立刻回到这里。","小武哥儿"},
[1140] = {"奥萨拉克斯之塔","在夜道谷和萨提纳尔找到被禁锢的上层精灵的灵魂，释放它们，然后回到迈斯特拉岗哨的净化者德尔格伦那里。","兽人们写起字来比小孩子的涂鸦好不到哪里去。当我决定去学习他们的语言时，我的许多部下都曾经取笑过我，但我想这样做还是有助于进一步了解我们的敌人。从伊克鲁德的乱七八糟的文字中，我们可以知道埃瑟里克斯仍掌握着两颗灵魂宝石，它们分别在灰谷东北部的夜道谷和萨提纳尔，这两个地方都是被萨特控制的地区。千万小心点，$n，面对那些被萨特之血浸透了地面的神殿，即使是像你这样经验丰富的<职业>也会心神不宁的。","小武哥儿"},
[1141] = {"钓鱼世家","为奥伯丁的古博·布拉普抓6条黑海岸石斑鱼。","布拉普家族一向以酷爱钓鱼而闻名。我的名字叫古博·布拉普，我在钓鱼。在这个地区我最希望钓到的鱼是黑海岸石斑鱼。以前我会坐船出海专门钓这些石斑鱼，但是由于那些该死的鱼人的出现，我已经很久没有出海钓鱼了。我打赌那些鱼人早把这里的石斑鱼给吃光了。那么说来，你愿意帮我抓一些黑海岸石斑鱼回来？如果你愿意的话，我可以给你一把货真价实的布拉普家族鱼竿！这根鱼竿可是钓鱼时的乘手工具啊！","小武哥儿"},
[1142] = {"临终遗言","将塔莎拉的坠饰带给达纳苏斯的塔莎拉·静水。","我现在很虚弱……没…没多久可活了。……那个勇…勇敢的矮人，亨里格·独眉，已经被派去警…警告法芬德尔了……但…我死…死之前…………我的妻子，塔莎拉……我们两人定情的坠饰…被…那群卑鄙的入侵者…偷走了……拜……拜托你，找到它……把它还给在达纳苏斯的塔莎拉…………还有……告诉她……我爱她……","小武哥儿"},
[1143] = {"奥萨拉克斯之塔","杀掉埃瑟里克斯·纳拉辛，把他的项上人头交给奥萨拉克斯之塔附近的巴苏尔·影击。","我知道了。如果你所说的是真的，那么我们必须马上发起进攻。我认为埃瑟里克斯就住在塔上。不过你要当心，在他的周围有很多强大的术士，比你以前所见到过的任何术士都还要可怕。","小武哥儿"},
[1144] = {"进口商威利克斯","护送进口商威利克斯逃出剃刀沼泽。","总算有人来帮忙了！你肯定不知道我被关在这鬼地方有多久，我已经不记得外边的世界是什么样子了。你看，我好歹还是个大商人来着。照他们的说法我这叫“见钱眼开”，前一阵子看到这里有利可图我就来了！麦伯克·米希瑞克斯愿意为在这个猪圈一样的地方生长的红叶薯付个好价钱，我还以为这是个有利可图的营生哪，结果……如你看到的一样，我犯了个小错误！总之，如果你这大善人愿意帮我逃出这儿的话，我是不会吝啬的。","小武哥儿"},
[1145] = {"疯狂的虫群","把科兰的密信交给奥格瑞玛的贝尔戈洛姆·石槌。","许多路过十字路口的旅行者都曾帮助过我从巨人旷野收集虫卵，他们大都知道那里的生物有多么可怕。我们现在有足够的证据说明，那里的昆虫远远比我主人想像中的还要可怕。我需要有一个信使到奥格瑞玛去找贝尔戈洛姆·石槌。这个任务并不简单，你必须要严肃地对待这个任务。贝尔戈洛姆一般就在战士公会外面。","小武哥儿"},
[1146] = {"疯狂的虫群","把贝尔戈洛姆的密信交给千针石林的摩克塔·克林。","这么说，科兰对这些昆虫得出和我相同的结论了——它们的威胁确实比我预想的要大。几天前有一个从千针石林回到我这儿的猎人受了重伤，现在情况非常危急。他是和一个突击队一起被派去执行任务的，本来他们要将一个矮人挖掘队从闪光平原驱逐出去，但是在行动中，许多这种昆虫从挖掘场的一个岩洞里倾巢而出，几乎使突击队全军覆没。突击队是由摩克塔·克林率领的，现在他们正在闪光平原的边境上寻求庇护。把我的这封信交给他吧。","小武哥儿"},
[1147] = {"疯狂的虫群","杀掉5只异种搜寻者、5只异种筑巢蝎和5只异种侵略者，然后向千针石林的摩克塔·克林复命。","嗯，看来贝尔戈洛姆确实开始重视这些怪物了，他想把它们打回老巢去。在我看来，我们这次的任务不光是赶走探险者协会派来的矮人，接下来还要用剩下的队伍去进行另外一次战斗。仅凭我们自己是无法赢得这样的战斗的，至少在目前的情况下是这样。挖掘场就在这里的南边，那里应该没有什么该死的矮人了。那么，你能帮我们去清除那些可恶的虫子吗？","小武哥儿"},
[1148] = {"虫群的样本","收集1颗异种蝎的心脏、5只异种蝎的爪子和3个完整的异种蝎壳，把它们和你手中的这个破碎的异种蝎壳一起交给十字路口的科兰。","你仔细观察着这个壳。当你把它拿在手中翻来覆去观察的时候发现它的构造很复杂，这让它变得异常坚固。这个壳不同于你所见过的任何东西。你进一步检查尸体，发现这些生物非常有力，而且进化程度也很高。再看看这个壳，你想科兰应该会有兴趣进一步研究这些生物。这可以帮他搞清楚它们到底是什么，以及它们是从哪儿来的。","小武哥儿"},
[1149] = {"信仰的试炼","如果你有坚定的信仰，就从那个可以俯瞰千针石林的木板跳下去。","你已经找到我了——或者是命运把你带到了我这儿，不管怎么样，现在你来到了这里，一段新的旅程即将开始。生命是由多种要素构成的：精神，身体，思想。某些要素可以由它所属的文化传统来衡量，而某些要素……我们就只能期望是自己与生俱来的特质了。如果你同意的话，我将要求你进行针对这些要素的试炼。如果你通过了这些试炼，你将变得更为强大。如果你没通过，你也许会感受扭曲虚空的黑暗。第一个试炼就是信仰的试炼。","小武哥儿"},
[1150] = {"耐力的试炼","把格林卡的爪子交给千针石林的多恩·平原行者。","我很高兴看到你的勇气依然不减。既然你的信念已经不可动摇，那么现在就让我们来对你的体能进行试炼吧。首先是耐力的试炼。到乱风岗西边的飞羽洞穴去一趟，进入那些鹰身人的巢穴最深处，毁掉它们的粮食储备。那样肯定会让它们勃然大怒，如果你能够在鹰身人的围攻之中生存足够长的时间，那么格林卡·血啸就会亲自出来对付你——杀了她，把她的爪子带给我，以此来证明你完成了试炼。","小武哥儿"},
[1151] = {"力量的试炼","把罗卡里姆的碎片交给千针石林的多恩·平原行者。","在远古之神的时代，元素生物主宰着世界。他们崇拜远古之神，这些神灵用他们的力量将元素生物和世界紧密地结合了起来。当远古之神消失时，元素生物便从我们的世界上消失了，现在只有非常强大的法师才能将它们召唤回来。当然万事皆有例外，有些元素生物很强大，足以凭自己的力量在这个世界上生存，其中一个就是罗卡里姆。为了通过力量试炼，你必须在千针石林里找到罗卡里姆，然后杀了它。","小武哥儿"},
[1152] = {"知识试炼","找到连接石爪山和灰谷的石爪小径里的布劳格·幽魂。","你与我在一起的时光就要结束了。虽然我具有丰富的知识，但是知识的试炼不是由我来安排的。有许多新的知识等着你去学习，有许多新的地方等着你去探索。如果你已经准备好了，那就去找布劳格·幽魂——他是个拥有无穷智慧的萨满祭司。他将进一步对你进行试炼，你要按照他的话去做，。一切准备就绪后，就去找连接石爪山和灰谷的通道，布劳格就住在那儿。要当心，, 暗夜精灵也许会阻止你的试炼。","小武哥儿"},
[1153] = {"新的矿石样本","从砂齿掘地工或砂齿勘探员那里找一块未精炼的矿石样本，把它交给陶拉祖营地的塔特纳克·钢炉。","，你过去帮我做了不少事情。酋长对我所完成的工作非常满意，并且要求我继续负责这里的一系列任务。我在酋长面前对你的作为大加赞赏，现在我要再次请求你的帮助。近来有一批旅行者从南方过来，他们在一个被称为千针石林的地方杀死了一个狗头人，从它身上得到了一块非同寻常的矿石，但这些旅行者不想卖掉它。我想要弄到一个那样的矿石样本来进行研究。","小武哥儿"},
[1154] = {"知识试炼","找到《巨龙的遗产》，把它还给位于灰谷和石爪山之间的石爪小径里的布劳格·幽魂。","你已经通过了多恩的试炼，现在你想通过下一个试炼了。非常好。但是到目前为止，你面对过的挑战还都是小儿科。锻炼你的身体很容易，但锻炼你的思想就完全是另外一回事了。让我来简单地解释一下：找到我说的那本书，研究它，然后回答我提出的关于其内容的问题。你一定会问是哪本书？是《巨龙的遗产》。它在灰谷南部的朵丹尼尔的底部，被死去的德鲁伊和杀害他们的凶手保护着。","小武哥儿"},
[1155] = {"<NYI> <TXT> bug crystal side quest","x","x","小武哥儿"},
[1156] = {"<NYI> <TXT> speak to alchemist pestlezugg","x","x","小武哥儿"},
[1157] = {"<NYI> <TXT> pestlezugg needs items","","","小武哥儿"},
[1158] = {"<NYI> <TXT> speak to rabine saturna","x","x","小武哥儿"},
[1159] = {"知识试炼","找到幽暗城的帕科瓦·芬塔拉斯。","干得好，。你已经通过了知识的试炼的第一部分，但是此外还有一个问题要你回答，这个问题将由别人来提出。去找洛丹伦城的帕科瓦·芬塔拉斯。在被瘟疫控制之前，他曾是一个伟大的人类历史学家。现在他依然继续寻求着启迪，虽然那是一种不同性质的启迪。他在向你提问之前会另有一个要求。到目前为止你都能对各种情况应付自如——因此我也相信你能越过这个障碍。","小武哥儿"},
[1160] = {"知识试炼","找到《亡灵的起源》，把它交给幽暗城的帕科瓦·芬塔拉斯。","我会告诉你必须去寻找的东西，我还会向你提出我的问题，但我做这些并不是因为你想证明你自己。知识远比力量重要，即使别人在能力上超越了你，你对世界的认知也会让你更胜一筹。到提瑞斯法林地北部的修道院去一趟，在那儿的图书馆里有一本名叫《亡灵的起源》的书，它曾被那些现在已经堕落了的圣骑士用来对抗我们。把这本书给我拿来。","小武哥儿"},
[1161] = {"<NYI> <TXT> gossip shade of ambermoon","x","x","小武哥儿"},
[1162] = {"<NYI> <TXT> speak to hamuul runetotem","x","x","小武哥儿"},
[1163] = {"<NYI> <TXT> speak to tyrande whisperwind","x","x","小武哥儿"},
[1164] = {"科娜塔一家","将科娜塔、法迪尔和马塞尔的头颅交给幽暗城的吉纳维·卡隆。","贱人！猪头！科娜塔竟然还活着！我在这里受苦受难，她居然全家和睦健康，人丁兴旺的。我被她抛弃了！我已经没有家了，他们都被瘟疫带走了。我的财产也都在战争中被抢光烧光了。这些也就算了，然而就是她和她的那些野种们，竟然厚着脸皮趁我不在的时候偷走了我家最后一件值钱的东西。我倒是不再关心那些被偷的东西了。现在我要的是他们的人头！到阿拉希高地去，避难谷地的东北方有一个达比雷农场，去那里把他们都给我杀光啊！","小武哥儿"},
[1165] = {"<NYI> Ore for the Races","","","小武哥儿"},
[1166] = {"莫格穆洛克的任务","蕨墙村的莫格穆洛克大王要你从石槌废墟拿回他的烈酒、鼻烟和保险箱。","向莫格穆洛克大王鞠躬致敬吧！是雷克萨让我做了石槌氏族的领袖！我是个好领袖，是我保卫氏族安全。大龙来了，烧了我们的家园，是我这么个有头脑的食人魔在这儿给氏族找了个新家。离开原来的家的时候太匆忙，我忘了点东西。小<种族>，去把我的东西拿来。往南走，去拿回我的烈酒、鼻烟和保险箱。你做好了我就会喜欢你。","小武哥儿"},
[1167] = {"奥萨拉克斯之塔","去和奥萨拉克斯之塔附近的巴苏尔·影击谈一谈。","在你正面对抗埃瑟里克斯之前，最好先向巴苏尔请教请教。毫无疑问，他一直都在警惕地观察着那座塔，应该会有一些新消息。","小武哥儿"},
[1168] = {"黑龙军团","蕨墙村的萨尔格要你去杀掉10个火鬃斥候，10个火鬃灰尾龙人和5个火鬃守卫。","雷克萨让莫格穆洛克做大王。莫格穆洛克只知道权力，很少关心食人魔。黑龙杀了很多食人魔，还杀了萨尔格的妻子。莫格穆洛克叫我们逃跑，让我们到这儿来。食人魔应该战斗。食人魔不逃跑。莫格穆洛克只关心他自己。我只把石槌村叫做家。我喜欢南边。帮食人魔打黑龙军团。我们要复仇。我们要回家。","小武哥儿"},
[1169] = {"群龙之首","蕨墙村的德拉兹辛比要你给他收集7条灼热之舌和7颗灼热之心。","莫格穆洛克那个懦弱的傻瓜只知道权力，他整日和萨尔格争夺着氏族的领导权，大概只有我才在想着要找出袭击我们以前家园的邪恶势力的源头。干嘛用这种疑惑眼神看我，$n？你以为我会像个粗俗的混蛋那样说话吗？就因为我是个食人魔？说正事吧，从那些大大小小的黑龙身上弄些心脏和舌头回来给我，也许我可以找出这邪恶的源头。","小武哥儿"},
[1170] = {"奥妮克希亚的血脉","和蕨墙村的莫格穆洛克大王谈一谈。","石槌村被奥妮克希亚的种族所侵犯，不过死亡之翼的女儿怎么会来侵犯我们的领地？这真是个大麻烦。奥妮克希亚来这里肯定不仅仅是为了围攻食人魔，而是还有别的什么目的。快去通知莫格穆洛克！我们必须采取行动了。","小武哥儿"},
[1171] = {"奥妮克希亚的血脉","去和蕨墙村的德拉兹辛比谈一谈。","别烦我。去告诉德拉兹辛比，我们就留在这儿。这儿没有黑龙。","小武哥儿"},
[1172] = {"奥妮克希亚的血脉","蕨墙村的德拉兹辛比要你去毁掉5枚奥妮克希亚的蛋。","黑龙谷到处都是奥妮克希亚的子嗣，决不能让它们继续繁殖下去了！赶紧到尘泥沼泽西部的巨龙沼泽去，那儿肯定是奥妮克希亚的巢穴。找到那里的龙蛋，把它们给毁了。如果他们还在不断滋生，我们就别想夺回石槌村。至于莫格穆洛克这个家伙……我自有办法。","小武哥儿"},
[1173] = {"挑战莫格穆洛克","打败莫格穆洛克，再把消息带给蕨墙村的德拉兹辛比。","你竟敢挑战莫格穆洛克？啊啊啊啊啊啊啊！我来踩扁你这个小<种族>！什么时候准备好挨揍就告诉我。","小武哥儿"},
[1174] = {"地精获胜！","到千针石林找克拉索·滑链。","","小武哥儿"},
[1175] = {"安全隐患","为闪光平原的赛道管理员泽尔林杀死10条盐石蜥蜴、10条盐石水晶蜥蜴和6条盐石凝视者。","自从地精的红雷赛车和一只大蜥蜴撞了个满怀之后，科鲁克莱德就雇了我去看守赛道。我不知道平原上的这些动物都是吃什么的，居然长得这么大，但我们必须多加小心，免得它们在比赛时突然跑进赛道里。我跟你说啊，如果你想打点零工的话，那就去把这些蜥蜴赶走吧。","小武哥儿"},
[1176] = {"减轻负重","给闪光平原的普兹克找10根空心秃鹫骨。","说到赛车，每一点都很重要！不论是动力输出的调整，压力线圈的松紧，或者是对于整部机车重量的控制，每一项都很关键，所以你必须考虑所有的东西。我们用秃鹫的骨头对赛车进行了改造，这样就提供了力量与重量的完美平衡，真棒。更棒的是，我们可以很容易地得到更多的秃鹫骨头，因为这一带到处都是秃鹫。去帮我找一些秃鹫骨头来，我会给你个好价钱的。","小武哥儿"},
[1177] = {"饿！","尘泥沼泽北部的马德克拉什要你去抓8条泥鳍小鱼。","马德是大食人魔。我饿了。去抓点鱼来。给马德找吃的。你喂饱马德，不然马德就吃你。","小武哥儿"},
[1178] = {"地精赞助商","和棘齿城的加兹鲁维谈一谈。","不管在哪里，我们的赛车队都是地精的骄傲。你会对那些以各种方式为车队贡献自己力量的人感到吃惊的。你认识加兹鲁维吗？他为我们从全世界寻找赛车零件，有一次他甚至为我们找来了一台完整的赛车！几星期前，他说他要送给我们一套新的燃油调节器，但至今还没有到货。他一向说话算数……你能去棘齿城帮我问问吗？我原本并不是特别心急，但是侏儒正在赶上我们的步伐！","小武哥儿"},
[1179] = {"防撞头盔","给闪光平原上的维兹尔·铜栓捎去一箱防撞头盔。","你听说过闪光平原吗？这是一片位于卡利姆多大陆上的盐堿地，就在千针林大峡谷的南面。这是块绝佳的竞速场地，因为……它实在是太平坦了！有一对侏儒兄弟，嗯，他们是我的朋友，就在那儿试验他们新近研制的火箭车，我听说这玩意跑得还挺快，快到频频撞车的地步，把驾驶员都给撞出脑震荡来了。所以这两个家伙让我帮他们弄几顶蒸汽坦克驾驶员的头盔。可是我这边还有别的任务，根本抽不出身来！你能替我跑个腿吗？","小武哥儿"},
[1180] = {"地精赞助商","和藏宝海湾的码头管理员罗兹基尔谈一谈。","回到关于你为何来这里的话题上。我的确向普兹克保证过会帮他运一台新的调节器，但我现在还没有收到这台机器。藏宝海湾的里维加兹说他已经把东西装船运了过来，也许是在运输过程当中出了什么差错。如果是那样的话，我们就无能为力了。现在我只知道它已经从藏宝海湾运了出来。去找码头管理员罗兹基尔吧，他应该能帮你查一查出货记录。","小武哥儿"},
[1181] = {"地精赞助商","与藏宝海湾的大财主里维加兹谈一谈。","恐怕我也只能帮你这些了，$n。如果你还想了解更多事情的话，就直接去找大财主里维加兹本人吧。还有谁能比里维加兹对他自己的生意更了解呢？你到港口那边的小酒馆顶楼的房间里就能找到他了。","小武哥儿"},
[1182] = {"地精赞助商","将燃料调节器的蓝图交给藏宝海湾的大财主里维加兹。","瞧，纳菲瑞提湖那边的地精风险投资公司的伐木机上都装备了最新型号的燃料调节器。我觉得，普兹克要是能拿到调节器的详细设计图，一定可以善加利用它。糟糕的是，那边的工头比我预计的要精明得多，要取得设计图似乎并不容易。你看起来应该有能力去拿到那张设计图。据我所知，他把那些东西都锁在了屋子里。","小武哥儿"},
[1183] = {"地精赞助商","把燃料调节器的蓝图带给闪光平原的普兹克。","你现在就赶快出发吧。替我向普兹克问好，顺便告诉他，如果他需要什么东西，就尽管跟我说。我期待着他能马上打破记录！","小武哥儿"},
[1184] = {"虫群的消息","回到奥格瑞玛的贝尔戈洛姆·石槌那儿。","返回奥格瑞玛的贝尔戈洛姆那里，告诉他摩克塔正在一丝不茍地执行他的命令。把我的研究进展也告诉他，我希望他能知道这些信息，贝尔戈洛姆一定会为此感到高兴的。","小武哥儿"},
[1185] = {"壳中的东西…","","","小武哥儿"},
[1186] = {"第十八个驾驶员","和闪光平原的拉泽瑞克谈一谈。","我要开始着手将这个新的燃油调节器装到赛车上去了，如果你想要帮助车队的话，就去和拉泽瑞克谈谈吧。他是我们的驾驶员——更确切地说，是第18个驾驶员——他想为这些赛车做一个小小的修改。他经常有些奇思妙想，所以请不要太吃惊了。","小武哥儿"},
[1187] = {"拉泽瑞克的调整","为闪光平原的拉泽瑞克取回爆盐增压器。","我知道，普兹克是个伟大的机械师，但是他不敢加大油门赶超别人。但我不像他那么胆小。在普兹克赛车的设计完成后，我花了点时间做了一些小小的修改。把控制器松一松，改造某些结构，增加更多的润滑剂，诸如此类。我从加基森的史瑞夫那里订了一个爆盐增压器，但是那运货的飞艇却一头栽进了尘泥沼泽！$n，帮我去把东西取回来吧！","小武哥儿"},
[1188] = {"安全第一","把爆盐增压器交给加基森的史瑞夫。","等等，这是怎么回事？史瑞夫打开了保险装置？这样会限制推进器的输出功率的。我说过那个装置要关掉！对我来说开着那东西一点好处也没有！你必须把这个拿到塔纳利斯沙漠中的加基森去，让史瑞夫把那该死的保险装置给我拆了。","小武哥儿"},
[1189] = {"安全第一","将改进型爆盐增压器还给闪光平原的拉泽瑞克。","看，我已经按照拉泽瑞克的要求去做了。我跟他说过，在关闭安全装置时要当心点，否则即使是最小的错误也会酿成大错，轻则让整辆赛车无法移动，重则把他直接在车里烧成灰。如果真的那样的话可就太丢人了，我们到哪里去找第十九个愿意入伙的赛车手呢？","小武哥儿"},
[1190] = {"跟上节奏","让扎米克掩护你，然后为闪光平原的普兹克偷到瑞兹尔的计划。","铜栓兄弟俩发现了一种新的材料，这是唯一说得通的解释。它们的车速比以前快了，但它们的设计，以及我们搜集的其它一些数据都和以前的一致。我们知道的是，瑞兹尔·铜栓一直以来都致力于这项新发明的计划之中。扎米克可以为你提供掩护，这样你就能从他们那儿偷到这些计划了。","小武哥儿"},
[1191] = {"扎米克的困扰","","","小武哥儿"},
[1192] = {"精铁矿石","","","小武哥儿"},
[1193] = {"破碎的陷阱","","","小武哥儿"},
[1194] = {"瑞兹尔的图表","把精铁矿石样本交给闪光平原上的普兹克。","瑞兹尔的图表上介绍了精铁矿石的精炼过程。从他的草稿中可以得知，精铁矿石来自于荒芜之地之中的奥达曼挖掘场。很多其它笔记的内容都与这种矿石的抗热性能有关。整个笔记的重头似乎是关于未精炼的精铁矿石的。","小武哥儿"},
[1195] = {"神圣之火","把装满水的蚀刻瓶交给雷霆崖的赞金·石蹄。","千针石林的加拉克半人马一直在保护着一件神器，它的历史可以追溯到半人马刚刚在这片土地上出现的时候。我们要得到它，但我们必须得有一瓶来自于暗夜精灵月亮井的水。要取水还必须找一个特殊的瓶子，在灰谷森林中心地带靠近林中树居一带出没的树妖或许就有这种瓶子。在靠近弗伦河西岸的大路南面有一口月亮井，你可以在那里装满水，然后把它带回来给我。","小武哥儿"},
[1196] = {"神圣之火","把装满水的蚀刻瓶交给乱风岗的劳恩·峭壁行者。","把这装满水的蚀刻瓶给乱风岗的劳恩·峭壁行者带去吧。你可以搭乘贫瘠之地南部边境的升降梯去千针石林。","小武哥儿"},
[1197] = {"神圣之火","拿到裂开的蹄子，把它交给乱风岗的劳恩·峭壁行者。","你找来的水可以暂时浸湿守护半人马遗物的火焰，但是效果不会持续很久，所以你必须行动迅速。半人马的要塞——加拉克峭壁——就在这里的北边，火焰就保存在那座重兵把守的要塞中。小心点，加拉克半人马的数量众多，他们决不会轻易放弃如此珍贵的东西。","小武哥儿"},
[1198] = {"寻找塞尔瑞德","到黑暗深渊去找到银月守卫塞尔瑞德。","这些天有很多关于暮光之锤与黑海岸北部黑暗深渊里的纳迦结盟的传闻。我在这里的任务是收集尽可能多的情报，这样我们就知道何时何地会需要帮助了。我派去侦察黑暗深渊的斥候塞尔瑞德已经离开好几个星期了，但直到现在他也没有提交任何报告。糟糕的是我的其他斥候也正在处理一些紧急事务，实在抽不出人手了。帮我找到塞尔瑞德，并且帮助他完成任务吧，$n。","小武哥儿"},
[1199] = {"暮光之锤的末日","收集10个暮光坠饰，把它们交给达纳苏斯的银月守卫玛纳杜斯。","通过祭祀上古之神的古代仪式，暮光之锤的成员获得了强大而混乱的力量，这些信徒正在试图唤回他们黑暗的主人，在这个世界上继续传播死亡与恐惧。现在我们可以确信，暮光之锤已经和纳迦结成了联盟，集结在灰谷海岸边的黑暗深渊中。我们必须阻止他们在那座古代神殿的深处所筹划的险恶计划。向暮光之锤发起攻击，然后带回你的战利品，我们会重重酬谢你所做的一切。","小武哥儿"},
[1200] = {"黑暗深渊中的恶魔","把梦游者克尔里斯的头颅交给达纳苏斯的哨兵塞尔高姆。","力量在我身上逐渐流失，我需要你的帮助！很久以前，这里曾是雄伟的月神之殿。然而，不幸却降临了这里，上古之神的堕落势力从地下突现，玷污了神圣的月亮井，最终使得这里成为了一片废墟。阿库麦尔，上古之神的仆人，从水中突然出现。暮光之锤的信徒与纳迦联合在一起，占领了这片土地。梦游者克尔里斯领导着他们为阿库麦尔而战，以许多无辜的生命来换取邪恶的力量。你一定要阻止这些恶魔！杀了克尔里斯，把他的头颅交给达纳苏斯的塞尔高姆！","小武哥儿"},
[1201] = {"塞拉摩间谍","杀掉9个塞拉摩间谍，然后回到蕨墙村去见纳泽尔·血矛。","部落和联盟正处于某种令人不安的休战期。两大阵营之间的小规模的冲突和暗杀活动时有发生，而我们的职责就是确保部落始终占据上风！现在正是行动的时候。联盟派了一些间谍驻扎在蕨墙村的东部，他们监视着村子，把我们的动向报给告塞拉摩，决不能让他们继续下去。去追踪那些间谍，把他们干掉。让他们的头儿知道我们决不会允许他们的间谍在我们面前晃来晃去！","小武哥儿"},
[1202] = {"塞拉摩码头","把指挥官的文件交给蕨墙村的纳泽尔·血矛。","，我们派了两个间谍到一艘停泊在塞拉摩码头的船上偷文件。他们找到了文件，不过却被人发现了行踪，只好把文件丢进海里。有一个间谍后来逃脱了，但是他却两手空空地回来，向我报告了他们失败的行动。现在我把这个任务交给你。文件就装在一只小提箱里，而那提箱已经沉在塞拉摩码头下面的海水里了。找到那些文件，把它们交给我。","小武哥儿"},
[1203] = {"加尔的剑","将刺脊的剑交给尘泥沼泽的“沼泽之眼”加尔。","我要切点东西，呃……我不能告诉你我要切什么，不过……反正我需要把剑。一种特殊的剑……我叫它快剑。你能帮帮我吗？那些鱼人，你知道，像鱼的人，像人的鱼，它们之中有一个名叫刺脊的，手里有一把巨剑，它就在这里北边的海滩附近。不过，不要等到明天再去找。我切的东西可不能放太久……","小武哥儿"},
[1204] = {"泥石龟蟹汤","给塞拉摩的摩根·斯特恩收集8个分叉的泥石龟舌。","我正在研究一道叫作“泥石龟蟹汤”的菜，现在我还需要一些原料……唉，我觉得我真是不适合在尘泥沼泽里长途跋涉！那么，，你能帮我去打猎吗？首先，我需要泥石龟的舌头，这些海龟经常在海岸附近出没。不过我要的还不是一般的舌头！听说有些泥石龟的舌头是分叉的……他们说那样的舌头吃起来味道特别好，而且我也很喜欢给我的菜里加点特别的风味……","小武哥儿"},
[1205] = {"死沼巨鳄","把死沼巨鳄的牙齿带给雷霆崖的梅洛。","死沼巨鳄是一只栖息在尘泥沼泽里的远古鳄鱼，现在是时候让它获得解脱了。当它挪动着庞大的身躯游过沼泽的时候，那衰老的骨骼饱受碾磨之苦。尽管它依旧有着可怕的力量和年轻时的速度，但老化的躯体却折磨着它内心强大的精神——那是一种激情不减的精神。然而现在它长期生活在巨大的痛苦中，这种痛苦折磨得它几近疯狂。，现在你必须去结束它的生命，把死沼巨鳄引向安宁的天国。","小武哥儿"},
[1206] = {"加尔和蜘蛛眼","收集20颗黑雾蜘蛛的眼球，把它们交给水光庄园的“沼泽之眼”加尔。","用眼睛制成饮料的味道非常好，可惜很多生物都只有两只眼睛。不过蜘蛛有很多眼睛，很多很多。黑雾蛛眼汁很好喝，醇美而味咸！真是没有比那更好的饮料了……黑雾蜘蛛就在西边的黑雾洞穴里活动。你说这些蜘蛛的名字是来自这个洞的名字呢，还是有别的什么说法？","小武哥儿"},
[1218] = {"沼泽蛙腿大餐", "将3份舒心草带给尘泥沼泽的*泥眼*贾尔", "我喜欢烹饪，尤其是地道的沼泽美食。比如这道油炸绿蛙腿就很特别。但我需要香料，舒心草香料。然后我就能炖出一锅好汤，咕嘟咕嘟喝下去，还能分你一碗。你喜欢炖汤吗？", "小武哥儿"},
[1219] = {"兽人的报告","把间谍的报告交给塞拉摩的艾登中尉。","你可以在松土里看到一只紧紧握起来的兽人的手，手里抓着一根用骨头刻出来的管子，里面塞着一张粘着泥土的羊皮纸。羊皮纸上的文字都是兽人的文字……这看上去很重要。","小武哥儿"},
[1220] = {"维米斯队长","把间谍的报告交给盖兰·维米斯队长。","应该让维米斯队长看看你找到的这份报告，，他的兽人语不错。我们得让他知道塞拉摩附近有部落的间谍！队长眼下正在塞拉摩岛东北面的兵营里。","小武哥儿"},
[1221] = {"蓝叶薯","找到一个开孔的箱子。找到一根地鼠指挥棒。找到并阅读《地鼠指挥手册》。在剃刀沼泽里用开孔的箱子召唤一只地鼠，然后用指挥棒驱使它去搜寻蓝叶薯。把地鼠指挥棒、开孔的箱子和6块蓝叶薯交给棘齿城的麦伯克·米希瑞克斯。","蓝叶薯是美味绝顶的佳肴！但是这种东西很罕见，非常非常罕见。它们只生长在贫瘠之地，在剃刀沼泽的地下深处。不过知道这一点也没什么用，因为如果你不知道它们的确切位置，那么就算近在咫尺你也不一定找得到它们。这就是我训练这些地鼠去寻找蓝叶薯的原因——它们有很灵敏的嗅觉，在五十步以外就能嗅到蓝叶薯块茎的气味。这差事并不轻松，但是如果你帮我弄来一些蓝叶薯的话，我会付给你一笔可观的报酬。","小武哥儿"},
[1222] = {"伊格纳兹的逃亡","护送伊格纳兹，然后和塞拉摩的摩根·斯特恩谈一谈。","太好了，总算碰到一个不是要来吃了我的人了！我正愁没人来帮我对付这儿的怪物哪，$g兄弟:小姐;，你看来就挺合适。那个叫摩根·斯特恩的厨子在研究一套新食谱，他让我来这儿采集一点睡菜叶。那家伙可能觉得睡菜叶挺好吃吧。就在我找睡菜的时候……我发现我被包围了！你能帮我从这儿逃出去吗？哦，对了，顺便在我找睡菜的时候替我断后。","小武哥儿"},
[1238] = {"遗失的报告","把间谍的报告交给蕨墙村的纳泽尔·血矛。","你可以在松土里看到一只紧紧握起来的兽人的手，手里抓着一根用骨头刻出来的管子，里面塞着一张粘着泥土的羊皮纸。羊皮纸上是一个在塞拉摩侦察了好几个星期的兽人写的报告。浏览过羊皮纸之后，你决定立刻把它送给蕨墙村的兽人情报官。","小武哥儿"},
[1239] = {"被斩下的头颅","把兽人的头颅交给蕨墙村的纳泽尔·血矛。","继续挖掘了一番之后，你找到了一颗男性兽人的头颅，脖子上有参差不齐的割痕。他的脸上还保持着发出怒吼的样子，黑色的眼睛不屈地怒视着前方。","小武哥儿"},
[1240] = {"巨魔巫医","把兽人的头颅带到荆棘谷的格罗姆高营地里，交给肯维雷。","我们必须弄清楚玛格究竟是怎么死的！唯一的方法就是使用巨魔的巫术。把玛格的头拿给肯维雷，他就在荆棘谷的格罗姆高营地里。肯维雷是暗矛巨魔里最强的巫医，能和玛格·夜眼的灵魂说话的人也只有他了。","小武哥儿"},
[1241] = {"失踪的使节","在暴风城的英雄谷找到乔贞。","最近我们派出了一名外交使节前往塞拉摩与吉安娜·普罗德摩尔女士会晤，但那位使节没能抵达目的地。我坚信是迪菲亚兄弟会密谋了这个事件，但我并不清楚具体的过程。使节失踪的消息对外严密封锁，但这件事情迟早要被曝光。国王的密探已经行动起来，在全城范围内寻找线索，但我打算私底下再找一些人来解决此事。我的一个老朋友乔贞现在就在英雄谷中。将这封便笺带给他，然后听他的命令行事。","小武哥儿"},
[1242] = {"失踪的使节","将乔贞的密信带给暴风城贸易区的埃林·提亚斯。","把这张便笺带给埃林·提亚斯，除此以外不要和他说任何话。你只需要礼貌地等着他的回答就是了。不用担心，他一定会回答你的。我必须再跟你清清楚楚地说一遍，：把这件事看得认真点，在任何人面前都要管好你的嘴。你可以在他的奶酪店“提亚斯奶酪坊”里找到他，就在贸易区。祝你好运。","小武哥儿"},
[1243] = {"失踪的使节","将密信带给暮色森林的守夜人巴库斯。","乔贞，你这老小子……那么，事情就是这样了，是吧？好吧，我会处理的。我倒是希望他早点死了呢！这么着，。我会开始派出我在这里的线人，不过你得帮我跑跑腿，好给我省点钱。到暮色森林的夜色镇去找守夜人巴库斯——他总是在镇子北边的路上巡逻。告诉他你正在为我调查迪菲亚兄弟会的活动，他会把他知道事情一股脑儿都告诉你的。","小武哥儿"},
[1244] = {"失踪的使节","找到迪菲亚记事本，把它带回给暮色森林的守夜人巴库斯。","迪菲亚兄弟会的活动？好吧，他们总是在活动。就算他们按兵不动，我们也仍然视之为威胁。但现在我认为，最近事情变得有点奇怪。大概是在两三周前吧，他们的许多密探都在腐草农场附近频繁出没。由此看来，那里一定是发生了什么重要的事情。你为什么不先去那里调查调查呢？记得把你调查到的结果拿给我看看。那座农场就在由西部荒野进入暮色森林的大路南边。","小武哥儿"},
[1245] = {"失踪的使节","将迪菲亚记事本带给暴风城的埃林·提亚斯。","哎呀，如果这只是个用来干扰你的视线的幌子，那他们也未免搞得太复杂了，我也不太清楚这东西到底是什么。把它交给提亚斯吧——他一定能弄明白其中的意义。千万小心，别让任何人把它抢走。我们都知道，这事可比我的命还重要，甚至比他的命还要重要。最后，拜托你一件事，，别对任何人说起我帮助过你。我的上司如果知道我对这件事有所了解而又没有向他们汇报的话，没准会绞死我的。","小武哥儿"},
[1246] = {"失踪的使节","与暴风城旧城区里的达舍尔·石拳谈一谈。","对了，就是他，现在我想起来了…达舍尔…达舍尔…什么来着……他的名字是什么来着？拳！达舍尔·石拳。圈里人都叫他拳——或许是因为他喜欢制造事端的缘故吧。你通常可以在旧城区里见到他——在旧城区中心练拳。去和他谈一谈，如果有必要的话，你不妨威胁威胁他，用点暴力手段什么的，有时候只有那样才能让他说点真话出来。别犹豫！要是真像这份东西上所写的那样，他应该已经深陷其中，不会那么轻易就告诉你什么有用的信息。","小武哥儿"},
[1247] = {"失踪的使节","与暴风城的埃林·提亚斯谈一谈。","原来如此……唔……我对腐草农场那边的会议略知一二，我记得是几周前组织的，但我没有去参加那个会议。我只参加了A计划的那部分，但A计划失败了……那些该死的冒险者。我们的线人说，那个执行B计划的小子来自米奈希尔，他的外号叫干柴。对于他们的后备计划我就知道这么多了。","小武哥儿"},
[1248] = {"失踪的使节","与湿地的米克哈尔谈一谈。","我有一个隐居在米奈希尔港的线人。他已经退休了，不过如果你告诉他你是为我工作的话，他应该会很愿意帮助你的。他名叫米克哈尔，在几年前离开暴风城的时候，他提到过自己要去旅店工作。和他谈谈，想办法找到这个干柴，再打听一下有没有关于使节被绑架的消息。我们现在得弄清楚他被带到了什么地方去，或者至少弄清楚他是谁。这份摘要里没有提到绑架行动完成以后的事。","小武哥儿"},
[1249] = {"失踪的使节","在塔伯克·贾恩逃跑前制服他，然后回米奈希尔港旅店去找米克哈尔。","你说是埃林派你来的？好吧，现在我要拿出十倍的热情来招待你。想要什么尽管说，我会竭尽全力来帮助你的。嗯，你说的是干柴？似乎是没听说过的名字，但我一定会注意他的。别抬头，，壁炉旁边的那家伙正往我们这边看呢。这家伙似乎有点太专心地听我们的对话了，你明白我的意思吗？如果我是你，我就会趁他溜走之前好好教训教训他。","小武哥儿"},
[1250] = {"失踪的使节","与湿地的米克哈尔谈一谈。","好吧，迪菲亚兄弟会出价虽高，可还不值得把我的命也给赔上。他们抓走的是国王。对，没错，正是暴风城的国王，他可不是什么简单的外交使节。他当时正在去塞拉摩与吉安娜·普罗德摩尔会面的路上——这显然是件大事，当然也是个大秘密。但这可不是迪菲亚兄弟会的主意，实际上他们也是为别人效力的。我想只有他们自己知道谁是他们的雇主。我的份内事就是趁国王的船还在港里的时候，和他们在船上的内应碰头，那家伙叫亨德尔。我就知道这么多了，我发誓！","小武哥儿"},
[1251] = {"黑色盾牌","把被熏黑的铁盾牌带给蕨墙村的克罗格。","有一面被烧毁旅店的大火熏黑了的铁盾牌和倒塌的烟囱连在一起，这根烟囱是树荫旅店烧毁之后留下的几段残砖断瓦中的一部分。这面铁盾牌可以从烟囱的砖上拿下来。","小武哥儿"},
[1252] = {"帕瓦尔·雷瑟上尉","把雷瑟的徽章拿给塞拉摩的盖兰·维米斯队长。","地上闪过的一道光芒把你的视线引到碎石的下面。你拨开了碎石，发现灰尘下有一枚白色的徽章，表面上印有金色的船锚，那是塞拉摩的标记。锚的下面刻着“帕瓦尔·雷瑟上尉”的字样。","小武哥儿"},
[1253] = {"黑色盾牌","把被熏黑的铁盾牌交给塞拉摩的盖兰·维米斯队长。","有一面被烧毁旅店的大火熏黑了的铁盾牌和倒塌的烟囱连在一起，这根烟囱是树荫旅店烧毁之后留下的几段残砖断瓦中的一部分。这面铁盾牌可以从烟囱的砖上拿下来。","小武哥儿"},
[1258] = {"还有螃蟹！","给塞拉摩的摩根·斯特恩收集12根新鲜的螃蟹腿。","新菜谱里还需要一种大螃蟹的腿，不过尘泥沼泽的污壳螃蟹可不行！唯一合适的螃蟹在悲伤沼泽里，离这儿很远。螃蟹腿的壳是构成这道菜的外观的一大要素，所以我必须要新鲜而且没有任何疤痕的蟹腿。一只成熟螃蟹大概只有一条或两条这样的腿，而我却需要大量的螃蟹腿来试验菜谱。那么，……你愿意跑一趟吗？","小武哥儿"},
[1259] = {"帕瓦尔·雷瑟上尉","从塞拉摩的泰索兰副官那儿找出更多关于雷瑟的消息。","我不认识这个帕瓦尔·雷瑟上尉，你最好还是去问问泰索兰副官。他负责管理塞拉摩所有守卫的档案，包括守卫的个人资料和他们的装备。他可以查查这些档案，然后告诉你这个雷瑟到底是谁。","小武哥儿"},
[1260] = {"摩根·斯特恩","和塞拉摩的摩根·斯特恩谈一谈。","我在为餐馆编写新的菜谱，这套新菜谱里都是本地特产的菜色，以“海湾”为主题。我想，蓝色隐士旅店的客人一定会很喜欢这个的！我让我侄子摩根到塞拉摩去收集当地的食谱了，那地方就在尘泥沼泽的边界地带。现在我得知道他目前都找到了些什么。去塞拉摩的路很长，起码对我来说是太长了些。不过像你这么个年轻的<职业>对这种长途旅行一定会欣然往之的，对吧？","小武哥儿"},
[1261] = {"玛尔格的嘱托","把宝石坠饰带给蕨墙村的纳泽尔·血矛。","可恶的龙虾人！我是不会束手待毙的！啊…但是…我已经死了，看来它的确是把我杀掉了……但是我的使命，我的使命啊！，你必须替我完成它。我曾在塞拉摩附近监视一队在海滩上露营的联盟士兵，其中一个士兵身上配戴着一件饰品，是那种镶嵌着很多宝石，再有钱的士兵也买不起的饰品！那天晚上，我溜进他们的营地，偷走了那件饰品，但是在我返回基地的途中，一个污壳龙虾人杀死了我！，你必须找到那只该死的龙虾人，并夺回那件饰品。","小武哥儿"},
[1262] = {"向佐尔报告","把镶宝石饰品带给奥格瑞玛的佐尔·孤树。","很奇怪的是，玛尔格偷取的这件饰品居然是一个普通士兵的东西。它的主人也许掩饰了自己真正的身份，或者那个士兵本身就是个窃贼！不管事实是怎样的，总之这是一件贵族的饰品。如果我们想要揭开这个谜团，就必须找出它真正的主人。带着饰品去奥格瑞玛找佐尔·孤树吧。他对联盟那边的事情颇有了解，应该会知道这件饰品是否和暴风城的贵族们有关系。","小武哥儿"},
[1263] = {"燃烧的旅店","","","小武哥儿"},
[1264] = {"失踪的使节","找到尘泥沼泽的指挥官萨穆尔。","每个月初，库尔提拉斯的水兵们都会领取薪水，然后离开塞拉摩到别的地方去游玩。大部分人会到这里来找女人，喝酒，寻欢作乐一番。他们当中有一些人整天都会泡在酒馆里，我敢肯定亨德尔也是其中之一。只要那家伙现在还留在塞拉摩的话，那么当地的指挥官萨穆尔就能帮你找到他。虽然他只对普罗德摩尔家族效忠，但如果你说出埃林的名字，他也会帮助你的……应该会的。","小武哥儿"},
[1265] = {"失踪的使节","在警戒哨岗中打探亨德尔下士的消息。","亨德尔？是的，我知道这个人。不过你找我的士兵有什么事呢？埃林派你来找他？嗯，好吧，我感觉有些不妙了。你肯定遇到了麻烦，因此埃林才让你来先找我的。我理解你可能不愿告诉我详情，但请明白这一点：我有责任保护好这片土地。如果你是来制造麻烦的话，最好能先得到我的允许。据我所知，亨德尔就驻守在塞拉摩外的第一座哨塔上。请自己多加小心！","小武哥儿"},
[1266] = {"失踪的使节","找到尘泥沼泽中的亨德尔下士。","亨德尔下士就在这里的西边，他现在正在执行保护那些轮休的塞拉摩密探们的任务。密探们正在那边监视着部落的前哨基地——蕨墙村，当然也时刻留心着其它任何有可能威胁到我们的东西。你应该很容易就能找到他，沿着道路搜索每一个帐篷就行。我现在还有另一件事要处理，但很快就可以追上你。","小武哥儿"},
[1267] = {"失踪的使节","与尘泥沼泽的吉安娜·普罗德摩尔谈一谈。","","小武哥儿"},
[1268] = {"可疑的蹄印","把树荫旅店的可疑蹄印报告给蕨墙村的克罗格。","有几排蹄印从树荫旅店那仍然冒着烟的废墟中延伸出来。大部分蹄印都埋在沼泽地的松软泥土里没法辨认，不过至少还有一些是可以看清的。","小武哥儿"},
[1269] = {"帕瓦尔·雷瑟上尉","把雷瑟的徽章带给蕨墙村的克罗格。","地上闪过的一道光芒把你的视线引到碎石的下面。你拨开了碎石，发现灰尘下有一枚白色的徽章，表面上印有金色的船锚，那是塞拉摩的标记。锚的下面刻着“帕瓦尔·雷瑟上尉”的字样。","小武哥儿"},
[1270] = {"伊格纳兹的逃亡","护送伊格纳兹，然后和棘齿城的麦伯克·米希瑞克斯谈一谈。","太好了，总算碰到一个不是要来吃了我的人了！我正愁没人来帮我对付这儿的怪物哪，$g兄弟:小姐;，你看来就挺合适。棘齿城一个叫麦伯克·米希瑞克斯的地精需要弄些睡菜叶……或是别的什么东西来做药剂，说实话我不在乎他做什么，反正他给的报酬不错，而我又正巧熟悉这个沼泽，所以我就来了。倒霉的是还没找到睡菜，我就被包围了！你能帮我从这儿逃出去吗？哦，对了，顺便在我找睡菜的时候替我断后。","小武哥儿"},
[1271] = {"盛筵","","","小武哥儿"},
[1272] = {"寻找雷瑟","","","小武哥儿"},
[1273] = {"盘问雷瑟","和奥格隆一起去和雷瑟谈一谈，然后回到蕨墙村见克罗格。","我花了很长时间终于找到雷瑟了。他躲藏得很好。奥格隆担心他在沼泽地里待了这么久可能已经疯了，你跟我来，咱们一起去从他那里套出一些我们需要的答案。","小武哥儿"},
[1274] = {"失踪的使节","找到暴风要塞的德拉维主教。","很抱歉，$g先生:夫人;。德拉维主教要我征召一些冒险者以帮助他解决一件棘手的事情。如果你能尽快而且悄悄地去一趟暴风要塞与他谈一谈的话，我想他将会非常感谢你的帮助。我得再申明一次，口风请紧一些，这件事情很重要。","小武哥儿"},
[1275] = {"研究堕落","奥伯丁的戈沙拉·夜语需要8块堕落者的脑干。","愚蠢的血精灵们已经彻底陷入了对魔法的狂热之中了，难道他们没有见到卡利姆多大陆上的萨特与纳迦们身上发生了些什么吗？我总觉得血精灵们也将会踏上这样一条不归之路，但是艾泽拉斯已经无法再承受多一种被魔法扭曲了心智的怪物了。我希望能够研究一下萨特和纳迦的脑干组织，这样也许就能了解那些精灵们的命运将会走向何方。在灰谷海岸边的黑暗深渊中有许多萨特和纳迦，你去那里找一找吧。这将会是一段漫长的旅程，一路小心，$n。","小武哥儿"},
[1276] = {"黑色盾牌","把被熏黑的铁盾牌拿给雷霆崖的莫萨恩看一看。","啊，我想起来了！莫萨恩是个，嗯，他是雷霆崖的一个受人尊敬的铁匠。我就知道以前肯定在哪儿听过他的名字。大地之环为了感谢我，送了我一套莫萨恩打造的护甲，他的手艺很不错。关于莫萨恩打造的盾牌，他自己也许可以告诉你更多。这不是什么重要线索，不过既然帕瓦尔·雷瑟还什么都没有说，这就是我们所了解的全部了。","小武哥儿"},
[1277] = {"<nyi> <TXT> The Centaur Hoofprints","Beat down.","Kagoro has revealed that the centaur hoofprints belong to some chumps in Mauradon.","小武哥儿"},
[1278] = {"<nyi> <TXT> The Grim Totem Clan","","","小武哥儿"},
[1279] = {"<nyi> <TXT>The Centaur Hoofprints","","Finish one of the three.","小武哥儿"},
[1280] = {"<nyi> <TXT>The Centaur Hoofprints","","","小武哥儿"},
[1281] = {"吉姆的歌谣","","","小武哥儿"},
[1282] = {"微笑的吉姆","与塞拉摩的盖兰·维米斯队长谈一谈。","我对吉姆的事很遗憾……他以前不是那样的。他曾在沼泽地开了个旅店，那是个很不错的地方。我真不想谈这个。你想谈的话就去找维米斯队长吧。","小武哥儿"},
[1283] = {"树荫旅店的大火","","","小武哥儿"},
[1284] = {"可疑的蹄印","把树荫旅店的可疑蹄印报告给塞拉摩的盖兰·维米斯队长。","有几排蹄印从树荫旅店那仍然冒着烟的废墟中延伸出来。大部分蹄印都埋在沼泽地的松软泥土里没法辨认，不过至少还有一些是可以看清的。","小武哥儿"},
[1285] = {"戴林的下属","把雷瑟的资料报告给塞拉摩的盖兰·维米斯队长。","雷东……雷德帕斯……啊，找到了！帕瓦尔·雷瑟上尉。他和大部分跟随普罗德摩尔女士横渡大海的征募兵一起加入了塞拉摩守卫军。16岁时加入库尔提拉斯海军，战绩出色，屡获提升……已列入失踪名单。","小武哥儿"},
[1286] = {"背叛者","从巴鲁斯·加科因及尘泥沼泽的背叛者那里打探消息。","在沼泽地里立足确实是非常艰难的，但是通过不懈的努力，最后我们终于在这一带守住了几座防守哨塔。我收到的最新消息和侦察报告说一群背叛者占据了我们在在旅店的西南方的一座废弃哨塔。这群背叛者的首领叫加科因，去看看能不能从他身上找到什么消息。小心点，$n。他可是个难对付的家伙。","小武哥儿"},
[1287] = {"背叛者","和塞拉摩的盖兰·维米斯队长谈一谈关于雷瑟的事。","雷瑟？那个懦夫？我们把他赶出营地，因为他坚持要袭击蕨墙村的食人魔，还要抢他们的物资。我们人数不够，没法跟那帮不长脑子的畜生斗。他不止一次做出过分的事，所以我们就把他赶了出去。现在我帮了你的忙……那么，别管你是不是偶然来这儿的，不如帮帮我的忙，别给我惹麻烦了吧？","小武哥儿"},
[1288] = {"维姆的报告", "将维姆的报告交给塞拉摩的吉安娜·普罗德摩尔女士", "你表现得非常出色，是我见过最优秀的非专业人士。普罗德摩尔女士要求我随时汇报这个敏感事件的进展，但我已很久没向她报告了。本来打算稍后亲自递交报告，但由你去向她当面说明更为合适。你肯定能比我更准确地回答她的问题。", "小武哥儿"},
[1289] = {"维米斯的报告*","返回塞拉摩，与维米斯交谈。","很好, 从维米斯的报告来看, 你在这次调查中帮了很多忙, 在此我感谢你.噢，我可以空出手来做其它事情了. 如果你愿意，你可以回去和维米斯一起把这件事调查完。","小武哥儿"},
[1290] = {"<nyi> Investigating Mosarn","Talkie.","Talk to Guard Komak. Asking questions gets you killed.","小武哥儿"},
[1291] = {"<nyi> <TXT> Centaur Hoofprints","","","小武哥儿"},
[1292] = {"<nyi><TXT> Centaur Hoofprints","","","小武哥儿"},
[1293] = {"<nyi> <TXT> Centaur Hoofprints","","","小武哥儿"},
[1294] = {"<nyi> <TXT>Centaur Sympathies","","","小武哥儿"},
[1295] = {"<nyi> <TXT> Course of Action","","","小武哥儿"},
[1296] = {"<nyi> <TXT> Course of Action","","","小武哥儿"},
[1297] = {"<nyi> <TXT> Course of Action","","","小武哥儿"},
[1298] = {"<nyi> <TXT> Thrall's Dirty Work","","","小武哥儿"},
[1299] = {"<nyi> <TXT> Thrall's Dirty Work","","","小武哥儿"},
[1300] = {"<nyi> <TXT> Lorn Grim Totem","","","小武哥儿"},
[1301] = {"詹姆斯·海厄尔","和米奈希尔港的文森特·海厄尔谈一谈。","在蓝色隐士旅店干活之前，我曾在一个最棒的厨师兼旅店老板手下学艺，他的名字是詹姆斯·海厄尔。我今天能有这样的成就都得归功于他。不知道他现在在干什么，他和他的兄弟文森特到米奈希尔港的一家旅店去工作了，不过最近我一直没听到他的消息。你要是碰巧要往米奈希尔去的话，能不能帮我问候他一下？","小武哥儿"},
[1302] = {"詹姆斯·海厄尔","与塞拉摩城堡中的书记员伦德瑞谈一谈。","我的兄弟詹姆斯跟随吉安娜女士到塞拉摩去了。我最后一次听到他的消息是说他们在那儿打完了仗，詹姆斯还在那里的某个地方开了个旅店。不管他现在在哪儿，我想他的生意肯定很红火，他是个很棒的厨师。啊，说起来我已经有一阵子没听到他的消息了——旅店的生意太忙了——不过塞拉摩的书记员应该可以帮你找到他。他就在那里的城堡顶楼。","小武哥儿"},
[1318] = {"戈多克食人魔的事务","找到戈多克力量护手，并将它交给厄运之槌的克罗卡斯。\n根据克罗卡斯所说的，“传说”自称是王子的精灵托塞德林从一名戈多克食人魔手中偷走了那件神器。","现在你是大王，你可以从那个精灵王子手里拿回令戈多克骄傲的神器！你前一任的大王失败了，自从托塞德林那个可恶的精灵从我们古代戈多克大王手中偷走它之后，没有一个大王能想办法把它夺回来！这个神器叫做戈多克力量护手。传说说只有真正的戈多克大王才能把它拿回来。这个可恶的精灵还在附近──如果你找到它的话，那你就可以使用它！真的！","小武哥儿"},
[1319] = {"黑色盾牌","把被熏黑的铁盾牌拿给塞拉摩的卡兹·双链看一看。","我很抱歉帮不了忙，$n，不过可以给你介绍个能帮忙的人。卡兹·双链是我们最好的铁匠，他就在铁匠铺给人打铁器。把盾牌拿给他，看看他能告诉你什么。","小武哥儿"},
[1320] = {"黑色盾牌","与塞拉摩的盖兰·维米斯队长谈一谈。","啊，我差点没注意到这个……背面的皮带一定是被烧掉了，不过看上去这条皮带是给某个身材高大的家伙用的。我猜是个牛头人。我就只能告诉你这些了，告诉维米斯队长，很抱歉我帮不上别的什么忙了。","小武哥儿"},
[1321] = {"黑色盾牌","把被熏黑的铁盾牌拿给蕨墙村的杜高尔看一看。","嗯……我看不出这个盾牌有什么特别之处。我们应该把它拿给铁匠杜高尔，看看他有什么说法。不过我也不抱太大希望……","小武哥儿"},
[1322] = {"黑色盾牌","为蕨墙村的杜高尔收集5个酸性毒囊。","嗯，在盾牌的边上这儿刻着字，可惜烧过了读不出来。要用些酸液洗干净，用沼泽地里的暗牙蜘蛛的毒液就可以了。那些蜘蛛盘踞在一座旧矿洞里，现在那里被称为黑雾洞穴。给我找点它们的毒囊来，我可以把盾牌清洗一下以便辨认。","小武哥儿"},
[1323] = {"黑色盾牌","和蕨墙村的克罗格谈一谈。","呃，我想我大概倒了太多酸液在盾牌上，得擦掉点儿……嗯……有点难辨认，不过好像是一个叫“莫萨恩”的名字。从来没听过这个名字。克罗格认识不少人，他也许知道这个莫萨恩是谁。","小武哥儿"},
[1324] = {"失踪的使节","击败尘泥沼泽的亨德尔下士。","什么？！你到这里来就是为了指控我和迪菲亚兄弟会有染？！我无法容许你这么侮辱我！看来我非得好好教训教训你才行。","小武哥儿"},
[1338] = {"卡尔·雷矛的订单","把卡尔·雷矛的订单交给暴风城的弗伦·长须。","有一个名叫弗伦·长须的矮人铸甲匠，我很欣赏他做的东西，那手艺简直是无人能敌。我需要一面新盾牌，而且一定要他亲手做出来的盾牌！问题是……弗伦住在遥远的南方，在暴风城的矮人区里。他竟然住在人类的领地里！我没法想像他怎么会住在离铁炉堡这么远的地方，那帮人类一定出了足够收买国王的大价钱把他给留在那儿！如果你正好要去那里旅行一趟，又想顺便挣点钱的话，能不能去弗伦那儿让他给我做一面盾牌？","小武哥儿"},
[1339] = {"巡山人卡尔·雷矛的任务","和巡山人卡尔·雷矛谈一谈。","我听说巡山人卡尔·雷矛正在找一个为他跑腿的人。你看怎么样，要去试试看吗？如果愿意的话，你就去北边的哨塔找他吧。","小武哥儿"},
[1358] = {"给赫布瑞姆的样本","把一箱蜘蛛毒带给贫瘠之地的药剂师赫布瑞姆。","我有一位名叫赫布瑞姆的药剂师同事目前正在卡利姆多大陆工作。他正在研究洛丹伦大陆上的毒物在卡利姆多大陆生物身上所造成的影响。为了帮赫布瑞姆的忙，我收集了提瑞斯法和银松森林一带各种蜘蛛的蛛毒，现在需要找人帮我把这些毒液给他带去。他就在贫瘠之地的一处名为十字路口的镇子上。要找到他，你必须先搭飞艇到兽人的首都奥格瑞玛去，然后步行向南去杜隆塔尔，最后向西进入贫瘠之地，这样很快就可以到达十字路口了。","小武哥儿"},
[1359] = {"给金格的货物","将狼心样本交给幽暗城的药剂师金格。","你拿来我的狼心具有与众不同的特质。从中提炼出的特殊毒素甚至可以毒死长着这种心脏的狼！这让我感到非常惊讶，所以我们必须对此进行深入的研究。把这几份心脏样本送到我的同事药剂师金格那里。你应该可以在幽暗城的炼金房里找到她。","小武哥儿"},
[1360] = {"失而复得","到奥达曼的北部大厅去找到克罗姆·粗臂的箱子，从里面拿出他的宝贵财产，然后回到铁炉堡把东西交给他。","我本来有个不错的工作，就是在荒芜之地的奥达曼挖掘场干活……直到那些该死的穴居人出现之后。我险些就没能活着跑出来，而且还什么也没来得及拿。在一片慌乱之中，我弄丢了我最重要的财产。我那箱子很难撬开是没错，不过你知道么，那里满地都是穴居人！你去帮我拿回箱子来，我就好好谢你！那个写着我名字的箱子就在北部大厅的尽头，你得一路杀进去才行。","小武哥儿"},
[1361] = {"雷戈萨·死门","和雷戈萨·死门谈一谈。","有一个名叫雷戈萨·死门的部落战士正在招募愿意前往凄凉之地执行任务的人。如果你愿意的话，就去和他谈谈吧。雷戈萨·死门就在贫瘠之地的十字路口西边的工事中。准备好你的武器，凄凉之地是一片危机四伏的土地。","小武哥儿"},
[1362] = {"凄凉之地的科卡尔氏族","和凄凉之地幽灵岗哨的费古尔·双刃谈一谈。","科卡尔半人马居住在凄凉之地，但他们的势力已经渗透到了贫瘠之地。这是事实，我们已经派了斥候去时刻监视着他们。只要凄凉之地的半人马依然足够强大，对我们而言，他们就是个威胁，我们应该主动出击清除这个威胁。去和凄凉之地幽灵岗哨的费古尔·双刃谈谈，他也是被派去收集有关半人马的情报的，他会知道该如何对付凄凉之地的科卡尔氏族的。","小武哥儿"},
[1363] = {"马森的请求","与暴风城里的助手迪利斯谈一谈。","作为魔法和科学学院图书馆的管理员，我的职责是保证所有的魔法书和卷轴随时在库。如果这些充满魔法能量的文字落在邪恶的人手里，天知道会发生多可怕的事情！啊，我突然想起来……我的助手迪利斯上礼拜犯下了一个可怕的错误。他在图书馆里确实是个好帮手，但他一走出暴风城就几乎寸步难行。你能帮我把老迪利斯给找回来吗？","小武哥儿"},
[1364] = {"马森的请求","夺回《卡德加的空间收敛研究笔记》，将它送给守望堡的看守者马哈尔巴。","马森大人的指示再简单不过了：将这篇重要的文章递交给守望堡的看守者马哈尔巴。但我从来没有去过诅咒之地！这段路程太可怕了！我在悲伤沼泽那边迷了路，被一大群像是植物一样的沼泽生物给包围了。它们在我身边徘徊着，似乎是想要攻击我，所以我就飞也似的逃了回来……结果我在慌乱中把文章给弄丢了。我敢肯定是有只怪物把它给捡跑了。你能帮我找回文章并把它送给马哈尔巴吗？","小武哥儿"},
[1365] = {"戴兹帕可汗","把戴兹帕可汗的头颅交给凄凉之地的费古尔·双刃。","科卡尔并不是凄凉之地唯一的半人马氏族。许多半人马氏族都游弋在这片干燥的平原上，他们相互残杀，纷争不断。他们的窝里斗对我们来说不是件坏事，因为半人马强壮而且残忍，如果这些半人马联合起来对付我们的话，那将是极其可怕的力量。在他们联合起来之前，我们必须将他们各个击破。你的第一个任务是让科卡尔氏族出现内乱，只要干掉他们的首领戴兹帕可汗就可以了。科卡尔村就在东北方。去吧，祝你好运。","小武哥儿"},
[1366] = {"悬赏半人马","收集15只半人马的耳朵，把它们交给凄凉之地的费古尔·双刃。","既然你已经震慑了半人马氏族，那么现在该让他们出点血了。开始在凄凉之地猎杀半人马吧，我不关心你去猎杀哪一个氏族，收集半人马耳朵就是了。减少他们的数量也就等于削弱他们的野心，打消他们不断扩张的念头。祝你狩猎愉快，。","小武哥儿"},
[1367] = {"玛格拉姆氏族","和玛格拉姆氏族建立良好的关系，然后和瓦鲁格谈一谈。","要想打败半人马，我们就必须让他们自相残杀。首先我们要笼络一支半人马氏族，利用它们打败所有的半人马。如果你准备和玛格拉姆氏族结盟，那么就去杀掉他们的敌人——吉尔吉斯氏族的半人马，这会使你在玛格拉姆氏族中赢得尊重。当你得到足够的尊重之后，就可以去会见玛格拉姆氏族的首领瓦鲁格，他就在凄凉之地东南部的玛格拉姆村外。","小武哥儿"},
[1368] = {"吉尔吉斯氏族","和吉尔吉斯氏族建立良好的关系，然后和智者乌泰克谈一谈。","要想打败半人马，我们就必须以毒攻毒。我们要先笼络一支半人马氏族，利用他们打败其他的半人马。如果你准备和吉尔吉斯结盟，那么就去攻击他们最憎恨的对手——玛格拉姆氏族。在你赢得了吉尔吉斯氏族足够的尊重以后，就可以去见他们的萨满祭司，智者乌泰克，他就住在凄凉之地西南的吉尔吉斯村外面。","小武哥儿"},
[1369] = {"破碎之泪","继续和玛格拉姆氏族保持良好的关系，把3块破碎之泪交给玛格拉姆村庄的瓦鲁格。","吉尔吉斯以为半人马之母瑟拉达丝在护佑着我们，他们都是蠢货！没有人在护佑半人马，玛格拉姆氏族不需要护佑！我们是最强的！让吉尔吉斯半人马知道他们有多蠢——到他们村庄附近的洞穴里去一趟，他们把那种名叫瑟拉达丝之泪的水晶石藏在了洞里。毁掉那些水晶，把碎片交给我！","小武哥儿"},
[1370] = {"偷取物资","把6包粗制干肉交给吉尔吉斯村的智者乌泰克。","在作战之余，我们为了食物而打猎。肉可以为我们补充力量，吃饱喝足之后作战会更加勇敢。玛格拉姆氏族的半人马和我们一样，他们贮藏多余的肉食，这样他们就能进行更持久的战斗。如果你能去袭击他们在东部的村庄，并且偷走他们贮藏的肉，他们的力量就会衰竭。","小武哥儿"},
[1371] = {"瓦鲁格的玩具","继续和玛格拉姆氏族保持良好的关系，给玛格拉姆村的瓦鲁格找到一个高级假人。","很久以前，有一个小侏儒来到凄凉之地。他是乘着马车来的，车上装着奇怪而有趣、燃烧后会放出五彩缤纷的焰火的东西，还有一些没有生命、但是居然可以自己移动的东西。我杀了这个小侏儒，不过在那之前……他让我乐坏了。我从他的马车上拿走了我最喜欢的东西，那是个木头做的人偶，在我把它砸得粉碎之前，它总是在那里向我招手。现在我想要一个新的，帮我弄一个来！","小武哥儿"},
[1372] = {"真言药水","到乞丐鬼屋去和药剂师法奥斯丁谈一谈。","瓦里玛萨斯派遣我们这支远征军来对艾泽拉斯南部进行侦查。我偶然发现一个人类间谍在乞丐鬼屋附近探头探脑。我正准备暗中跟踪他，这个家伙就被一些…我们的兽人朋友抓去，押进了位于悲伤沼泽里的斯通纳德要塞。兽人们还不知道我们在这里安营扎寨，不过…我想去帮助他们，帮助我们的兽人盟友。去找法奥斯丁，让他给我们在斯通纳德的朋友制造一瓶真言药水……","小武哥儿"},
[1373] = {"盎格库尔","继续和吉尔吉斯氏族保持良好的关系，并把德莱尼水晶碎片交给凄凉之地吉尔吉斯村的智者乌泰克。","你还需要更多的行动来证明自己，我要你去很远的地方完成一个任务，所以从现在开始，吉尔吉斯氏族就要独自和玛格拉姆氏族作战了。大地把很多的秘密告诉了聆听它声音的人，我听到的秘密是关于一种红色水晶的。这种被称作德莱尼水晶的东西最近才出现在这片大陆上，它来自一个遥远的地方，那里的山脉在天空中悬浮，恶魔掌控着那里的一切。给我带一片德莱尼水晶碎片来，它能让我的魔法变得强大无比！这片德莱尼水晶碎片应该就在悲伤沼泽的失落者盎格库尔手里。","小武哥儿"},
[1374] = {"杰恩可汗","把杰恩可汗的头颅交给凄凉之地吉尔吉斯村的智者乌泰克。","大地告诉我说，玛格拉姆氏族变得越来越衰弱了。现在是干掉他们的可汗的时候了！把玛格拉姆氏族的杰恩可汗的头给我提来！","小武哥儿"},
[1375] = {"沙卡可汗","继续和玛格拉姆氏族保持良好的关系，把沙卡可汗的头颅交给凄凉之地玛格拉姆村的瓦鲁格。","你帮助了玛格拉姆氏族，我喜欢你。现在去杀了吉尔吉斯的可汗！他叫沙卡，我要他的脑袋！我要盯着他的脑袋取笑他！","小武哥儿"},
[1380] = {"赫鲁萨可汗","继续和吉尔吉斯氏族保持良好的关系，把玛洛迪钥匙碎片交给吉尔吉斯村的智者乌泰克。","，你帮助我们战胜了玛格拉姆氏族。现在，请再帮助我们打败玛洛迪氏族吧！干掉他们的首领赫鲁萨可汗！要挑战他，先要吹响玛洛迪号角，这把号角就在长矛谷中的一处高耸的峭壁上。而要吹响号角，你必须得到一只哨嘴。这种东西很少见，只有萨鲁赫可汗的心腹们才有资格携带。号角一响，玛洛迪半人马就会蜂拥而至。放手屠杀他们，直到赫兰萨出现。赫兰萨可汗手里有一把……一把钥匙。把这把钥匙交给我，我就会告诉你有关它的秘密。","小武哥儿"},
[1381] = {"赫鲁萨可汗","和玛格拉姆保持良好的关系，把玛洛迪钥匙碎片交给凄凉之地玛格拉姆村的瓦鲁格。","吉尔吉斯可汗已经被干掉，现在轮到玛洛迪了！干掉他们的首领赫鲁萨可汗！要挑战他，先要吹响玛洛迪号角，这把号角就在长矛谷中的一处高耸的峭壁上。而要吹响号角，你必须得到一只哨嘴。这种东西很少见，只有萨鲁赫可汗的心腹们才有资格携带。号角一响，玛洛迪半人马就会蜂拥而至。放手屠杀他们，直到赫兰萨出现。赫兰萨可汗手里有一把……一把钥匙。把这把钥匙交给我，我就会告诉你有关它的秘密。","小武哥儿"},
[1382] = {"奇怪的联盟","和吉尔吉斯氏族建立良好的关系，然后和智者乌泰克谈一谈。","我们的确很幸运，半人马氏族之间正在同室操戈。如果他们拧成一股绳，那将会是一股无法阻挡的力量。没错，我们很幸运，所以我们应该紧紧抓住现在的这种优势。众多半人马氏族中的一支——吉尔吉斯，正在与玛格拉姆氏族激烈地战斗。我希望在我们进攻玛格拉姆的同时，吉尔吉斯氏族也能同时发动攻击。去和智者乌泰克谈谈吧，他就在凄凉之地西南的吉尔吉斯营地外面。也许我们可以通过他来和吉尔吉斯结成联盟，同时对玛格拉姆发起致命的攻击！","小武哥儿"},
[1383] = {"真言药水","乞丐鬼屋的药剂师法奥斯丁需要5颗暗影黑豹的心脏、1颗泥沼之王的蘑菇和一些绿色雏龙之血。","我脑中已经想到了合适的药剂配方，可以让口风最紧的人喝下之后也知无不言。要制成这种药水，我需要几颗沼泽地中的暗影黑豹的心脏，另外还需要住在那儿的泥沼之王的蘑菇。$n，像你这么能干的人一定可以说服他给你一个蘑菇的。最后一味药是绿龙的血液，比如伊萨里奥斯的洞穴外面的那些。事不宜迟，你赶快出发吧！","小武哥儿"},
[1384] = {"突袭科卡尔","和吉尔吉斯氏族保持良好的关系，把10个粗制咒符交给凄凉之地吉尔吉斯村的智者乌泰克。","科卡尔半人马认为他们的魔法很强大，其实他们根本就不知道魔法是什么东西！即使是把魔法扔在他们脸上，他们也不会知道的！你去让他们知道他们的魔法有多么脆弱吧。去杀了科卡尔氏族的蠢货们，把他们的咒符带回来，我要把它们丢进火坑里，然后放声大笑！","小武哥儿"},
[1385] = {"野蛮外交","和玛格拉姆氏族建立良好的关系，然后和瓦鲁格谈一谈。","凄凉之地是一片杀戮场。半人马氏族之间互相残杀，我们担心最后的胜利者会不断扩张领土，并最终威胁到我们的要塞。我们决不能允许这种情况出现。我们必须学会如何打败半人马氏族，为了打败他们……我们就必须和诸多半人马氏族中的一支结盟。玛格拉姆氏族与吉尔吉斯氏族正在互相征伐，如果你去攻打吉尔吉斯氏族，那么玛格拉姆氏族就会视你为盟友。想办法得到玛格拉姆氏族的信任，然后去和瓦鲁格谈谈，他就在凄凉之地东南的玛格拉姆村里。","小武哥儿"},
[1386] = {"突袭科卡尔氏族","继续保持和玛格拉姆氏族的良好关系，杀掉12个科卡尔半人马，12个科卡尔斥候和6个科卡尔虐待者，然后回到凄凉之地向玛格拉姆氏族的瓦鲁格报告。","科卡尔氏族认为他们很强大，但我们对他们嗤之以鼻！我们杀这些杂碎根本不费吹灰之力！你也可以杀了他们。让我看看你也是否也能像我们一样杀死科卡尔半人马。","小武哥儿"},
[1387] = {"悬赏半人马","收集15个半人马耳朵，把它们交给尼耶尔前哨站的麦尔金斯下士。","半人马的社会是由多个氏族组成的，每一个氏族都有各自的领袖和纲领。所有的半人马氏族只有一点是相同的：残忍。如果我们要寻求和平，就必须先消灭这些半人马。你的任务就是消灭他们。在凄凉之地猎杀半人马，割下他们的耳朵。给我尽可能多带些半人马的耳朵回来。为了联盟，请一定要这么做，，只有这样，和平才会降临这片土地。","小武哥儿"},
[1388] = {"真言药水","把法奥斯丁的真言药水交给乞丐鬼屋的亡灵哨兵莱度斯。","一切都在按照计划进行，$n。把真言药水交给莱度斯，他会告诉你怎样使用它……哈哈！","小武哥儿"},
[1389] = {"德莱尼水晶","给悲伤沼泽避难营地里的玛格图尔带去6块德莱尼水晶。","农田避难所里的那些失落者和我们是同族，但他们已经是疯狂的怪物了……在我们来到艾泽拉斯的那段残酷的征途把他们活活逼疯了！他们现在就住在东边的农田避难所里，任何在附近徘徊的人都有可能被他们抓住或杀掉……他们还偷走了我们的圣物——德莱尼水晶。我们没有足够的力量进入农田避难所去夺回那些被他们扔在小屋和营火附近的水晶，但是失去了那些水晶……我们就会迷失自己的方向。","小武哥儿"},
[1390] = {"BETA Oops, We Killed Them Again.","Missing text","Missing text","小武哥儿"},
[1391] = {"真言药水","把莱度斯的酒带给斯通纳德的间谍玛克森。","要办成这事，我们还得想点办法。毕竟你不可能大摇大摆地走进去，然后说服那个傻瓜喝下法奥斯丁配制的药水，对吧？不过有一样东西是这些人类肯定不会拒绝的，那就是酒。我会把法奥斯丁的药水和这瓶麦酒混合在一起，那个可怜的傻瓜肯定会毫不犹豫地一饮而尽。赶紧去悲伤沼泽的斯通纳德要塞，$n。什么都不要告诉别人……","小武哥儿"},
[1392] = {"木棒诺博鲁","把诺博鲁的木棒交到悲伤沼泽中的避难营领导人手中。","避难营里的德莱尼人已经被诺博鲁虐待了好几个月了，他的棒子对于这些失落者来说是一种残忍和暴力的象征。","小武哥儿"},
[1393] = {"加林的逃亡","护送加林逃出困境，然后打开他放在悲伤沼泽营地里的保险箱。","请救救我！这些东西想要吃掉我！帮我离开这儿，我就给你一笔巨大的财富！那笔财富就在斯通纳德北部沼泽的营地中，但是被锁在了一个保险箱里，只有我知道方法来打开箱子。如果你帮我逃走，我就告诉你怎么拿到那笔财富！","小武哥儿"},
[1394] = {"通过试炼","和千针石林的多恩·平原行者谈一谈。","你做得很好，。你已经通过了所有的试炼，现在回到千针石林的多恩那里去吧。他会感觉到你的变化，他会看出你的思想、身体和精神都已经足够强大了，而你的努力理应受到嘉奖。将你在这些测试中所表现的优秀素质继续保持下去吧，。如果你能做到这些的话，多恩将在以后的日子里再次对你进行试炼。","小武哥儿"},
[1395] = {"守望堡的物资","在能量石的魔法效果消失以前，把它们带给守望堡的军需官朗格尔斯。","这一箱能量石要送去位于死亡之地的守望堡。它们不能长久保持魔法的效力，因此我们恐怕不能等到下一支商队出发时让他们捎去了。你必须带上它们，迅速赶往守望堡，动作一定要快。把它们带给城堡里的军需官朗格尔斯。要想到达那里的话，你就必须向东穿越逆风小径，再向东穿越悲伤沼泽，然后向南穿越死亡之地。你要小心，。你要连续穿越好几个危险地带，但是你绝对不能失败。","小武哥儿"},
[1396] = {"逼近的野兽","杀死8只小盐齿鳄鱼、10只沼泽纺丝蛛和10只沼泽虎，然后向悲伤沼泽的卫兵比格斯报告。","我的车队本来是要去守望堡的，但我们没能到达目的地。食人魔攻击了我们，他们杀死了护卫，然后将所有的货物全都给抢走了，那帮该死的家伙逃进了逆风小径。只有我一个人逃过了他们的袭击。我曾发誓要保护好那些货物，发誓要把它们安全送到守望堡！但这一带的野兽太多了。拜托，不要让那群野兽侵入我们的营地！","小武哥儿"},
[1397] = {"<nyi> Saved！","","","小武哥儿"},
[1398] = {"晒干的流木","给悲伤沼泽的卫兵比格斯带回8块晒干的流木。","我对你实在是感激不尽，。你有一颗充满荣耀的心。现在，我想我仍需要谦卑地请您帮我完成另一个任务。如果我还想到守望堡去的话，就一定得修好这辆马车。因此……我需要一些木材，我要的是结实的干木，而不是从那些沼泽中的树上砍下的像海绵一样松软的木头。，请到东边的海滩上去找些已经被太阳晒干的流木，把它们给我拿来。","小武哥儿"},
[1418] = {"尼卡·血痕","和尼卡·血痕谈一谈。","可怕的荒芜之地就在联盟所控制的洛克莫丹地区南方，因此斯通纳德与荒芜之地中的卡加斯前哨站之间的交流经常中断。去证明你自己的实力吧，。旅行到荒芜之地去，与尼卡·血痕谈一谈，她是卡加斯前哨站的侦察队长。把她的报告给我拿回来。","小武哥儿"},
[1419] = {"捕猎山狗","带30块山狗的颚骨去见卡加斯的尼卡·血痕。","<职业>，你在荒芜之地呆了很长时间吗？你感觉到那里的炎热了吗？你是否跟那些在尘土飞扬的平原上到处游荡的野兽打过交道？如果还没有的话，现在是时候了。峭壁山狗是一种让人头疼的猛兽，这些强壮而凶猛的家伙总喜欢潜入卡加斯，偷走我们的食物补给。帮我们的前哨基地解决掉这些小偷吧！捕杀这些峭壁山狗，把它们的颚骨拿来见我。带给我足够多的颚骨，那样也许我才会相信你真的了解荒芜之地。","小武哥儿"},
[1420] = {"向赫格拉姆报到","把尼卡的报告交给斯通纳德的赫格拉姆。","我刚写了一份要交给斯通纳德的赫格拉姆的报告，请你帮我带去给他。千万别在途中迷了路，也别让这份报告落到敌人的手中。","小武哥儿"},
[1421] = {"丢失的货物","在农田避难所中找到商队的货物，并拿到巫师的材料，把它交给卫兵比格斯。","那些失落者们攻过来的时候，我一下子就被吓呆了。等我回过神来，就看见一只受惊的马拖着车一路狂奔出去，窜入了北边的失落者村庄里。那辆车上运的是非常贵重的施法材料，都是守望堡的巫师们急需的。找到我们的材料，，帮我把它们带回来。","小武哥儿"},
[1422] = {"海中的威胁","与悲伤沼泽的卡塔尔谈一谈。","在我给你打造武器的时侯，为什么你不去和卡塔尔谈谈呢？他曾说过需要有人帮忙在海滩上巡逻，我非常乐意看到像你这样睿智而警觉的<种族>去协助他，而不是我们这片营地中的某些只会骗酒喝的家伙。","小武哥儿"},
[1423] = {"遗失的补给品","把遗失的货物交给军需官朗格尔斯。","这只木桶不大，但非常坚固。木板的接缝处和桶盖边上都用一种味道刺鼻的黄色封蜡封了起来。桶底的标签上写着两行大字：军需官朗格尔斯守望堡","小武哥儿"},
[1424] = {"泪水之池","斯通纳德的费泽鲁尔要求你收集10件阿塔莱神器。","酋长大人派我们去调查阿塔哈卡神庙中发生的奇怪现象。阿塔莱巨魔是由一群使用黑暗法术的施法者组成的氏族，以惯于运用禁断的魔法而著称。你可以想像一下，当我们到达那里，却发现整座庙已经沉入了水中时，我们会有多么惊讶。现在那里被一群自称是艾泽拉斯保卫者的绿龙占据着。我们得弄清楚那里到底发生了些什么事。去探索一下泪水之池周围，收集一些阿塔莱神器。有了这些信息，我就可以开始把这个谜一点一点地给解开了。","小武哥儿"},
[1425] = {"运送货物","把货物带给守望堡的军需官朗格尔斯。","，在我修车的时候，我另外还有一件工作要交给你。我已经把从食人魔那里抢救回来的最重要的几件货物都放在了包裹里，你把它们都带到守望堡里去吧。这座城堡就在死亡之地北方的丘陵地带中，时刻监视着黑暗之门里的动静。你只要顺着这条路一直向东走，在第一个岔路口向南进入死亡之地，然后再在第二个岔路口向左转，就可以到达守望堡了。记住，要一直顺着路走，，多加小心。","小武哥儿"},
[1426] = {"海中的威胁","杀掉10个沼泽鱼人、10个沼泽喷墨鱼人和10个沼泽食腐鱼人，然后向悲伤沼泽的卡塔尔回报。","我一点都不喜欢大海，更不喜欢那些从深海里游上来的生物。他们都是些强大野蛮而又盲目的蠢货。要是我有足够的气力，我就会去成百上千地屠杀鱼人。不过现在我还没那么凶悍，所以就只好退而求其次，只要能看见这群鱼人死在任何遵从着部落意愿的勇士手里，我也就满足了。你怎么样呢，<职业>？你能杀死多少鱼人？你愿意和鱼人当中最强的一群较量较量吗？","小武哥儿"},
[1427] = {"海中的威胁","与悲伤沼泽的托克卡尔谈一谈。","在你休息之前，记得再去和托克卡尔谈谈吧，我估计在你离开的时候他就应该把那些武器完成了。为了感谢你的帮助，他会送一把给你。一切都准备就绪以后，你就可以在对抗鱼人的过程中好好试一下那把武器了……","小武哥儿"},
[1428] = {"海中的威胁","杀掉10名沼泽喷墨鱼人、10名沼泽食腐鱼人和10名沼泽鱼人智者，然后向悲伤沼泽的卡塔尔回报。","看着你对鱼人的憎恶也如同我一般地与日俱增，我非常高兴。沿着海滩巡逻，你就可以找到更多的鱼人，去杀吧。当你觉得自己杀得够多了以后就回来找我，我会好好奖励你一下的。","小武哥儿"},
[1429] = {"阿塔莱流放者","将一捆阿塔莱神器交给辛特兰的阿塔莱流放者。","当你勇敢地在泪水之池周围冒险的时候，我的斥候带回了一张用血写成的卷轴。那看起来像是对阿塔莱氏族中的某位祭司的审判书。这位祭司被判处了阿塔莱氏族中的极刑，他的命运将比死亡还要更可怕。他被放逐到了极北的辛特兰，被迫与一群枯木巨魔住在一起。\n$我会帮你把这些物品包好的，请你带着它们去找到这位流放者，或许你能从他那里得知他们的氏族到底使用了怎样的魔法。任务完成之后，请立刻向我回报。","小武哥儿"},
[1430] = {"新鲜的螃蟹腿","给悲伤沼泽的达尔带去10条巨大的螃蟹腿。","最近我的顾客总是会来买鲜嫩多汁的螃蟹肉，特别是那些巨型淤泥蟹的肉。如果你最近要去海边转转的话，最好能帮我带一些螃蟹腿到奥格瑞玛去，我会付你可观的报酬的。海岸就在这里的东边，那里遍地都是螃蟹，很容易就可以弄到螃蟹腿。","小武哥儿"},
[1431] = {"联盟关系","与奥格瑞玛的科尔丹谈一谈。","请等一下，<职业>，让我告诉你一些对我们的族人来说非常重要却几乎不为人知的东西。我们兽人是个令人骄傲的种族，而与人类之间的战争是如此漫长，就连萨尔都有些不耐烦了。你知道的，我们的酋长睿智而谨慎，并总是以他的族人为重。总之，他是一个出色的外交家，在他与人类共同生活的那段日子里，他也学会了许多人类的行事之道。如果我刚才说的故事引起了你的兴趣，那么就去找城市西门附近的科尔丹吧。","小武哥儿"},
[1432] = {"联盟关系","与凄凉之地的塔卡塔·钢刃谈一谈。","随着联盟在卡利姆多的推进越来越深入，部落与燃烧军团有染的错误结论一定会流传开来。酋长可不会允许这样的事情发生。受酋长所托，我正在负责这个问题的解决。我已经往凄凉之地派了密探，就在科多兽坟场北部的幽灵岗哨附近。你的任务是跨过石爪山脉，一直走到山脉的南侧，到那里去找塔卡塔·钢刃。","小武哥儿"},
[1433] = {"联盟关系","去找凄凉之地的玛乌林·碎骨谈一谈。","和火刃氏族相关的说法是多如牛毛，但你要知道，这帮家伙实在是邪恶到家了，他们的精神已经腐朽，他们利用破坏与毁灭来维持并证明自己的存在。科尔丹派玛乌林·碎骨来与我同行，因为玛乌林对火刃氏族及他们的术士之道都有着充分的了解。他负责策划针对火刃氏族的行动，而我则负责对付在凄凉之地活动的恶魔。去和他谈一谈吧，他会告诉你如何按他的计划行事。","小武哥儿"},
[1434] = {"萨特的威胁","杀死7只怨怒盗贼、7只怨怒魔仆、7只怨怒背叛者和7只怨怒唤魔者，然后向凄凉之地的塔卡塔·钢刃复命。","恶魔是绝对不会凭空就出现的——他们需要一些空隙使邪恶得以立足。这空隙或许会产生自孱弱的精神，或许是对权力的无谓欲望，或许是对复仇的渴求，或许是要求最终审判的控诉。当我们被痛苦所困扰时，邪恶就会利用我们——例如萨特这样的邪恶力量。火刃氏族与它们之间显然有很紧密的联系，因此萨尔认为他们必须被清剿干净。到东北方向去寻找的它们的踪影，在将他们驱赶出这一带后回来向我报告。","小武哥儿"},
[1435] = {"灵魂的燃烧","将15块燃烧宝石转变为灌入灵魂的燃烧宝石，然后把它们交给凄凉之地的玛乌林·碎骨。","对那些为了某些自私的理由而背叛了自己首领的卑劣生物们而言，死亡是他们最合适的归宿。但对于那些将自己的全部身心奉献给黑暗的家伙们来说，死亡还远远不够。拿着这块宝石，当你附近有火刃氏族的爪牙死去时，就启动宝石上面的魔法。这个法术会拯救堕落的灵魂，将它们拉出黑暗的深渊，灌注到宝石里。在这些宝石中灌入了灵魂之后，把它们带回来交给我，我会妥善处置它们。现在就出发吧，多加小心。","小武哥儿"},
[1436] = {"联盟关系","与奥格瑞玛的科尔丹谈一谈。","形势很顺利，。如果我们能继续保持目前的推进势态的话，或许酋长会允许我们在换季之前回到久别的家园。回到科尔丹那里去，告诉他我们都干了些什么。我敢打赌他一定会为你在这儿的功绩而奖励你。他的事业对他来说很重要，并且如果酋长也会对他的成就表示敬意的话，他一定会非常自豪。","小武哥儿"},
[1437] = {"瓦拉里尔的搜寻","去凄凉之地寻找泰拉尼斯·玛雷姆和黛琳达·玛雷姆的马车。","你好，$n，我是瓦拉里尔。我到这里是来寻找达纳苏斯商业世家——玛雷姆家族的两个失踪的孩子。这个家族的族长已做好了最坏的打算，不过我还是要尽一切可能找到他的孩子。我已经开始了搜寻泰拉尼斯和黛琳达的工作，但愿一切顺利。我最近得知的线索是，几周前他们已经越过了石爪山。如果你发现了他们的踪迹，就请立刻通知我。","小武哥儿"},
[1438] = {"瓦拉里尔的搜寻","去凄凉之地找到黛琳达·玛雷姆。","找到泰拉尼斯和黛琳达，然后带着你的发现回来见我。从这座城堡开始进行搜寻吧，我会立刻和达纳苏斯的上级联系，让他们知道这里的情况。对了，，还有一件事情一定会让你影响深刻。我的上级最关心的并不是泰拉尼斯以及他在这里的活动。对他们来说，更重要的是黛琳达能否安全地回来。泰拉尼斯……在他回来之前必须要接受评估。","小武哥儿"},
[1439] = {"寻找泰拉尼斯","去凄凉之地找到泰拉尼斯·玛雷姆。","兽人杀掉了我们所有的护卫和仆从，然后把我们带到了这里。天啊，那真是太可怕了！我以为他们肯定也会杀了我们，不过显然它们有别的计划。泰拉尼斯试图和他们交涉，我想他试图用对奥术的了解来博得他们的好感……我不知道他为什么要那么做。没有找到哥哥的下落，我就不离开这里。找到他，然后再回来救我吧。","小武哥儿"},
[1440] = {"回复瓦拉里尔","护送黛琳达·玛雷姆离开雷斧堡垒，然后回到凄凉之地的瓦拉里尔·屠魔者那里。","怎么样，你准备好了吗？我感谢你的帮助，如果时间不是太紧的话，请在此时此刻就接受我对你的感谢：感谢你对我和我的家族所做的一切。如果你准备好了，我们就赶快动身离开吧。","小武哥儿"},
[1441] = {"<UNUSED>","","","小武哥儿"},
[1442] = {"寻找科尔宝石","给黑海岸的桑迪斯·织风带去一块科尔宝石。","你好，。我能为你这位追寻神圣之道的人做点什么呢？哦，铁匠斯迪威尔……很久以前的事了，不过我还记得他，有一段时间没听到他的消息了。我知道他决不是那种卑鄙的人，他想要一块科尔宝石一定也是为了某种高尚的目的。如果你真想要科尔宝石，就到灰谷的西北方去。你会在古老的废墟里看到黑暗深渊，而那些仍然在使用科尔宝石纳迦就聚集在那里。你一定要小心，不要单独行动。","小武哥儿"},
[1443] = {"<nyi> The Shakedown","","","小武哥儿"},
[1444] = {"向费泽鲁尔复命","向斯通纳德的费泽鲁尔回报。","预言者迦玛兰宣读了对我的放逐令，将我从阿塔哈卡神庙中赶了出来。我过去曾认为这位祭司是一位优秀的领导者。但他对自己的预言能力的过度依赖与盲目的服从一定会导致我们阿塔莱氏族的毁灭，这是迟早的事情。当我说出了我所担忧的事情时，我被判为异端，从庙里被赶了出来。你拿来的这些东西都是无害的。但如果迦玛兰找到了能够启动召唤仪式的魔法神像，这个世界一定会落入巨大的灾难之中……","小武哥儿"},
[1445] = {"阿塔哈卡神庙","收集20个哈卡神像，把它们带给斯通纳德的费泽鲁尔。","他提到了迦玛兰的预言？这位阿塔莱氏族的精神领袖相信，只要哈卡从扭曲虚空回到艾泽拉斯，这位神祇就将赐予阿塔莱氏族的每一个成员以永恒的生命。若你问我怎么看，我会说这实在是一个只会带来灾难的愚蠢行为。你说那个流亡者提到了魔法神像？这令我十分担心。如果这种东西确实是那个阿塔莱召唤仪式中的必需品，那我们就必须弄清楚这东西中蕴藏着怎样的力量。到那个神庙里去一趟，把这些神像都给我带回来！","小武哥儿"},
[1446] = {"预言者迦玛兰","辛特兰的阿塔莱流放者要你给他带回迦玛兰的头。","我的枯木同伴们对贸然闯入他们领地的陌生人不太和善。我吗？我连家都没有了。我原本属于悲伤沼泽的阿塔莱氏族，不过现在却被我的同胞流放到这里来了。我们的精神领袖迦玛兰曾有过一个“预言”，他声称召唤哈卡会带给阿塔莱氏族永恒的生命。但是我觉得有些不对劲的地方，如果这个预言仅仅是为了操纵我们，那我们该怎么办？我要为他们流放我的举动复仇，给我把迦玛兰的头带回来，也许这样我的同胞就可以重获自由。","小武哥儿"},
[1447] = {"失踪的使节","击败暴风城的达舍尔·石拳。","没错，你显然不是到暴风城里来的最聪明的<职业>，但如果你现在不赶快给我消失的话，你就是最笨的那个了！嘿，你还不走？那就跟我的朋友过过招吧！","小武哥儿"},
[1448] = {"调查神庙","暴风城的布罗哈恩·铁桶要求你去找到阿塔哈卡神庙。","我年轻的时候，也是像你这样活力充沛，有一股冲劲的。但现在我老了，也不能像当初那样在这片大陆上到处冒险了。啊，真是怀念那段日子啊！但我过去的冒险生涯中却里还有一个未解之迷。在我的最后一次任务中，探险者协会派我去调查阿塔哈卡神庙，据说那座庙宇就在悲伤沼泽里。但当时我却感到害怕，只是坐在狮鹫上飞过了这片地方，自然，我并没有找到神庙。你愿意满足一个老矮人最后的愿望吗？或许你走路过去的话就可以找到神庙……","小武哥儿"},
[1449] = {"去辛特兰的旅程","找到辛特兰的弗斯塔德·蛮锤。","正如我之前所说的，我曾经尝试过从空中寻找那座神殿。事实上，那次我并不是独自行动的。我先是去了位于辛特兰的鹰巢山上那座著名的狮鹫饲养场，在那里我请他们的一位最优秀的飞行员帮助我。在探险中，那位飞行员从他的座骑身上掉了下去，一直掉进了沼泽之中……我老了以后，这个可怜人的名字一直出现在我的脑海里，挥之不去。饲养场的管理员也应该还记得这件事。到那里去找弗斯塔德·蛮锤吧。我们得搞清楚那位飞行员后来到底怎么样了。","小武哥儿"},
[1450] = {"狮鹫管理员","与辛特兰的鹰巢山狮鹫饲养场里的狮鹫管理员沙拉克·鹰斧谈一谈。","那么说你这个$g毛头小子:小姑娘;来这里就是给探险者协会里的某个老头子跑腿的吗？那你听好了，<职业>。我根本不知道他说的那个曾经在艾泽拉斯到处飞的老家伙是谁。你跑来问我这些，难道我脸上写着“狮鹫管理员沙拉克·鹰斧”这几个字吗？嗯？要是你想飞那么一次两次的，干嘛不去找个正儿八经的狮鹫饲养员呢？你要是还在这里继续闲晃的话，那我就真的要给你找点什么活去做做了。快走快走。","小武哥儿"},
[1451] = {"拉普索迪·铁铲","去辛特兰找到拉普索迪·铁铲。","拉普索迪那家伙特别爱喝酒，不要误会我的意思——我们饲养场里所有的矮人没事的时候都爱喝上那么一小口麦酒。但拉普索迪不一样，那家伙一碰见烈酒就跟狮鹫见了天空一个模样。而且我不得不承认的是，没人能比拉普索迪这家伙飞得更好了。但是自从他勉强和你那位朋友飞回来以后，他就彻底变成了另一个人，因此我们只好让他走了。我听说拉普索迪东边的某个地方弄了个酒窖。","小武哥儿"},
[1452] = {"拉普索迪的卡利姆多鸡尾酒","辛特兰的拉普索迪·铁铲要求你带给他3块大鹏的砂囊、3块格罗多克猩猩的肝脏和3块铁鬃熊的肝脏。","嗝儿！你是那疯子加蠢蛋布罗哈恩派来的啊？我们倒是一起经历过一次大……大冒险……嗝儿！如果你想要知道我那时候掉进沼泽里的时候看到了什么，行，不过我得先喝上一杯好的。要知道那底下可不是什么美景……嗝儿！要不这么着吧……如果你给我弄些原料来配制卡利姆多鸡尾酒，我就告诉你。至于原材料，先去塔纳利斯搞点大鹏的砂囊……然后，然后……我看看……再去菲拉斯弄点格罗多克猩猩和铁鬃熊的肝脏来……这便是唯一能打开我的话匣子的东西，美味的卡利姆多鸡尾酒呀！","小武哥儿"},
[1453] = {"寻物公司的业务","和凄凉之地的克雷迪格·安戈尔谈一谈。","我有些活儿要你去凄凉之地跑一趟，。那里满地都是半人马和其它讨厌的东西，是个非常凶险的地方。不过如果你想找一份为期一星期的充实工作的话，就去那儿找克雷迪格·安戈尔，告诉他是我叫你去的。他就在尼耶尔前哨站，那是凄凉之地北部山区里的一个小营地。当你从石爪山进入凄凉之地的时候就向东转，尼耶尔前哨站有些难找，所以路上要多留心看看，免得错过了。","小武哥儿"},
[1454] = {"卡尼托的海难","在凄凉之地找到卡尼托的箱子。","我的第一笔订单来自于法师卡尼托，他是暴风城里的一个贵族。他的船似乎在西北边的海岸附近受到了海巨人的袭击，他和仆人们想把最值钱的一个箱子带上岸，然而，海巨人成群结队地发起攻击，所以他不得不放弃了这个想法，把自己和仆人传送到了安全的地方。他希望我们能帮忙找到那只箱子，并且把它送到暴风城。","小武哥儿"},
[1455] = {"卡尼托的海难","回到凄凉之地的克雷迪格·安戈尔那里。","你仔细考虑着到底是什么东西撬开了箱子，同时观察着箱子四周和顶部的又长又深的痕迹。显然，这并不像是某个人或是某个海巨人干的，而且这些撬痕似乎也不是匕首或者是利剑留下的。打开箱子检查了一番之后，你发现它是空的。找不到一点头绪，于是你关上箱子准备离开。克雷迪格一定会很失望。","小武哥儿"},
[1456] = {"卡尼托的海难","找到卡尼托的背包，把它交给凄凉之地的克雷迪格·安戈尔。","真有趣。其实，我们也不是一点希望都没有。在那个海岸更靠北的大海深处，有一片暗夜精灵的废墟。一个纳迦部落把那里当成了他们的家，他们管那地方叫什么来着……滑刺……不，是滑刃氏族！我想我们可以去那里碰碰运气。如果有什么人能够深入到那么远的南部，那他们一定非常强大。如果你要去找卡尼托的东西，那么就准备对付更加强大的纳迦——滑刃潮行者或者滑刃海巫吧。","小武哥儿"},
[1457] = {"卡尼托的背包","把卡尼托的背包交给铁炉堡的罗顿·石锤。","去把卡尼托的东西交给铁炉堡的罗顿吧，他会付你报酬的。哈哈，我敢跟你打赌，他一定会盛情邀请你加入我们的。再一次感谢你，$n，你干得很好。回去的时候要多加小心，别耽误太多的时间——卡尼托不是那种很有耐心的人，但是毫无疑问，他是非常慷慨的。","小武哥儿"},
[1458] = {"寻物公司的委托","收集10只怨怒萨特的爪子和10根怨怒萨特的角，把它们交给凄凉之地的克雷迪格·安戈尔。","我到这里来的一个主要任务就是帮莱弗维奇收集材料，莱弗维奇是卡拉诺斯城中的一个侏儒法师。罗顿总觉得这件事对我们来说轻而易举，却对我们这里人手短缺的现状视而不见。他列出的清单上的前几件物品应该很容易找到，如果你帮我找到它们的话，就可以获得丰厚的报酬。首先你得从东边的怨怒萨特身上弄一些角和爪子回来，然后我们再来寻找清单上列出的其它物品。","小武哥儿"},
[1459] = {"寻物公司的委托","收集7瓶鞭尾蝎的毒液和3块老迈科多兽的毛皮，把它们交给凄凉之地的克雷迪格·安戈尔。","莱弗维奇货单上的下一条……我看看……哦，在这里。非常简单，而且说明也写得非常清楚。他需要荒土蝎的毒液和科多兽的毛皮。清单上写得很清楚：这两件东西分别来自两个特定的物种：毒液来自于荒土鞭尾蝎，而毛皮则来自老迈的科多兽，注意，既不是濒死的科多兽也不是远古科多兽。法师……他们总是要一些稀奇古怪的东西……","小武哥儿"},
[1460] = {"<UNUSED>","","","小武哥儿"},
[1461] = {"<UNUSED>","","","小武哥儿"},
[1462] = {"大地灵契","向鸦羽先知要另一瓶大地灵契。","","小武哥儿"},
[1463] = {"大地灵契","向坎纳甘·地鸣要另一个大地灵契。","","小武哥儿"},
[1464] = {"火焰灵契","向泰尔夫·祖拉姆再要一个 火焰灵契。","","小武哥儿"},
[1465] = {"瓦拉里尔的搜寻","向凄凉之地的瓦拉里尔·屠魔者回复。","当你继续搜寻马车的残骸时，你发现有一串足印一直向南方延伸过去。在远方有一座巨大的城堡上空烟雾缭绕，那烟雾来自于城堡哨塔上的烽火，而不是房屋的燃烧。你的直觉告诉你：如果玛雷姆兄妹还活着，那他们一定就在那里。","小武哥儿"},
[1466] = {"寻物公司的委托","收集10个地狱犬的脑子、10对魔女之翼和10瓶末日看守之血，把它们交给凄凉之地的克雷迪格·安戈尔。","这是物品列表上的最后一些东西了，我不会撒谎，撒谎可不是件光彩的事情。恐怕你得花更多的时间去寻找这些……我已经说了这么多了，言归正传。莱弗维奇的要求是：从噬法魔犬，法师猎手或者灵能猎犬那里收集大脑；从地狱魔女、地狱巫女或地狱修女那里收集魔女之翼；还有……从末日看守队长或者末日看守领主那里收集末日看守之血。是不是很简单啊？呵呵……如果你不想接这项任务的话，我也能理解。","小武哥儿"},
[1467] = {"寻物公司的委托","把莱弗维奇的包裹交给铁炉堡的罗顿·石锤。","要想得到报酬，你就得去一趟铁炉堡，亲自和罗顿谈谈。他会非常乐意收到莱弗维奇的包裹的。把这个交给他，然后你应该就能收到报酬了。别担心，我回去以后会替你美言几句的，从理论上讲我应该不会在这个鬼地方呆太久的。","小武哥儿"},
[1468] = {"儿童周","使用人类孤儿哨来和你在儿童周期间要照顾的孩子进行对话。","你愿意帮助我们的孤儿院？愿圣光保佑你，我的朋友。你在儿童周这段时间内对我们的帮助将是无价的。拿着这个口哨，你只有在这7天内可以使用它－也就是儿童周的这七天。当你使用它的时候，你可以和那些你照顾的孩子进行对话。再次使用就可以解散那个孩子。不管怎么样，——使用这个口哨然后去见见你要保护的人！我相信孩子们一定很想见到你。","小武哥儿"},
[1469] = {"拉普索迪的故事","将阿塔莱石板碎片交给暴风城的布罗哈恩·铁桶。","在出发前，我喝了整整一桶的烈酒。嗝儿！那是怎样的一次飞行呀！布罗哈恩跟着我飞了几圈，还是没看见庙。嗝儿！我喝得有点醉了，结果没抓稳就从坐骑上掉了下去。我一头栽进了水里，而且沉到了底儿，这个时候我竟然看见了那座庙。不过很快就从不知道哪里冒出了一大群巨魔把我给围了起来，废话，当然得快溜了！不过我还是从那些巨魔手中搞了点纪念品回来。给，把这个带给布罗哈恩，告诉他神庙确实就在那下面。嗝儿！","小武哥儿"},
[1470] = {"控制小鬼","收集3个断骨骷髅的颅骨，把它们交给温雅·玛山德。","你好，孩子。以一个术士的标准来看，你还太年轻了些，因为你还无法掌控那些力量。我能感受到你渴望学习的热切心情。你也一定能学会的。无知就没有力量，知识就是我们最好的武器。运用知识，我们就能控制无序的魔法和虚空之中的生物，让它们臣服于我们的意志。我会教你如何让一个奴仆服从你的意志，但首先你要带三个断骨骷髅的颅骨给我，你可以在废弃的铁匠铺附近找到它们。","小武哥儿"},
[1471] = {"誓缚","召唤并征服一只虚空行者，然后将召唤符文还给诅咒神庙中的凯伦丁·哈加尔。","你应该见过下边的那个召唤法阵了吧？只有站在那上面，你才能召唤出虚空行者来。用这些符文就可以进行召唤了，但在那之后，无论是用武器还是魔法，你必须击败它才能够对它进行操控。等虚空行者被你征服之后，它就会与你订下契约。契约签定完成之后就过来找我，我会向你说明召唤法术的使用方法，以便你以后随时召唤它。","小武哥儿"},
[1472] = {"噬魂者","与诅咒神殿中的高德瑞克·法杉谈一谈。","魅魔是灵魂的吞噬者，心灵的毁灭者，它们以诱惑人类为生，它们的心中只有纯粹的邪恶。在没有诱饵的情况下，我们是无法将它引入到我们的世界中来的。因此，我们要以它自身的力量来对抗它。只要有一个真正善良、纯洁而博爱的人的心脏，魅魔就将因为无法抵抗这种吸引力而被引入我们的世界。之后，你就要控制它，使它对你俯首贴耳。与我的助手高德瑞克·法杉谈谈吧，他就在神殿里。他会帮你找到你需要的诱饵。","小武哥儿"},
[1473] = {"虚空中的生物","夺回埃加林的魔典，把它交给诅咒神庙中的凯伦丁·哈加尔。","看来大家一致认为你已经可以学习如何召唤虚空行者了。虚空行者是一种由虚空中的混乱力量所构成的实体，如果你召唤出虚空行者但却不能控制住它的话，你就会被它撕成碎片。世上第一个虚空行者是埃加林召唤出来的，而在他的魔典中也详细地写明了整个召唤过程。不幸的是，这本书被血色十字军的一个成员给偷走了，他把书藏在十字军在西边占据的一座塔中。把它给我拿回来，然后我就可以把召唤虚空行者的方法传授给你了。","小武哥儿"},
[1474] = {"誓缚","召唤并征服一只魅魔，然后将纯洁的心还给诅咒神庙里的凯伦丁·哈加尔。","在召唤法阵上，以这些心脏为材料施展一个法术，就可以为魅魔打开一个通向这个世界的通道。尽管你现在的力量已经很强了，但你还是得竭尽全力才能战胜魅魔。小心她的魅惑能力，$n，有很多意志坚强的人都被她诱惑，屈从了她的意志。如果你战胜了魅魔，她将会回到虚空中去，然后我将教你如何召唤这个魅魔，让她听你调遣。","小武哥儿"},
[1475] = {"进入阿塔哈卡神庙","为暴风城的布罗哈恩·铁桶收集10块阿塔莱石板。","根据传说，阿塔哈卡神庙是供奉着古代神祇“夺魂者阿塔哈卡”的神圣祭坛，有一个名叫阿塔莱的巨魔氏族世世代代守护着这座庙宇，据说从来也没人能进到庙中去一窥究竟。潜到泪水之池底部并从庙中取出古代的神器是件很困难的事，但这却正是我要你去做的，$n。帮我收集一些完整的阿塔莱石板，把它们带回来给我，这样一来我就能以英雄的身份回到探险者协会去了。我会和你一起分享这份荣耀。","小武哥儿"},
[1476] = {"纯洁者之心","将达林和科马的心脏交给诅咒神殿里的凯伦丁·哈加尔。","有荣誉感与善良的人？这种人到底存在过吗？在进行了多年的研究并翻阅了无数的典籍与传说之后，我终于找到了两个符合我们标准的人。第一个叫达林·弗治维特，他将自己的全部身心都投入到了拯救那些被遗弃在格雷迈恩之墙外的洛丹伦难民的事业中。另一个叫科马·韦拉德。此人对他失踪了的爱人忠贞不渝，一直以来都在湿地中寻找着他的爱人的下落。把他们的心脏交给凯伦丁，不过首先，让我先告诉你到哪里去找。","小武哥儿"},
[1477] = {"重要的补给","和守卫队长索里加尔谈一谈。","法师们正在死亡之地的守望堡里进行研究，这项重要的研究关系到我们对黑暗之门的了解。他们需要持续的补给，然而我们到守望堡的补给线非常脆弱。你必须提供帮助以保证补给物资安全抵达守望堡。到夜色镇去找守卫队长索里加尔，按他的指示去做。这次任务要求你进入敌方区域，准备出发吧，。","小武哥儿"},
[1478] = {"哈加尔的召唤","与幽暗城的凯伦丁·哈加尔谈一谈。","啊，$n！我刚刚收到了凯伦丁·哈加尔托人带来的口信，他希望你能去接受进一步的训练。你应当为此感到自豪，$n。哈加尔先生可不是每天都会私下里指导年轻术士的。他在幽暗城的法师区里，应该就在诅咒神殿旁边。","小武哥儿"},
[1479] = {"永恒之树","带着你看护的孤儿去达纳苏斯的银行。银行就坐落在一棵中空的树里，它被称为永恒之树。","我听说过一个故事，故事里面说夜精灵的银行是建在一棵树里面的，那棵树看起来像一头熊！真是太酷了！夜精灵非常注重保护自然的和谐，但是熊熊听起来就很可怕！带我去看看那棵“熊树”吧？求求你了！有一条船会带我们去那里，一点都不远。求你了求你了求你了！","小武哥儿"},
[1480] = {"堕落者","把恶魔之皮拿给凄凉之地的玛乌林·碎骨看看。","这片被裁下来的皮子很臭，似乎已经有点腐烂了, 值得注意的是，这块看上去干燥而松脆的东西却异常柔软。在摊开它之后，你可以清楚地看见其中一面上有着用某种语言写成的红色标记文字。在皮子的底端有一个十分清晰的符号，你认为这是个签名。也许玛乌林能告诉你些什么？","小武哥儿"},
[1481] = {"堕落者","给凄凉之地的玛乌林·碎骨带回一张巡影者的头皮。","我可以在拥有适当材料的情况下找到这个恶魔领主。如果他确实如我推测的一般强大，那我就得先准备一些只有从非常危险的生物身上才能收集到的物品。既然你是为酋长做事的，那么我想你应该会接受我交付给你的任务吧。首先，我需要破坏他的反侦测结界。去给我找一块萨特的头皮来，不过并不是任何萨特的头皮都可以的，只有怨怒巡影者的头皮才能用。从凄凉之地东北部的古代遗迹附近开始找起吧。","小武哥儿"},
[1482] = {"堕落者","给凄凉之地的玛乌林·碎骨带回一块神谕水晶。","如果有一块神谕水晶就好了。这种东西一般都是由纳迦制造出来用于预言的。从这里向西北方向走，一直沿着海岸线前进，你会看到一个巨大的珊瑚礁，纳迦们通常在那一带活动。你可以在那里找到神谕水晶。滑刃纳迦并非善类，而且他们也不会对你的闯入表示欢迎，所以你要小心点，动作快点。等你回来以后，我们就可以开始寻找魔王阿兹雷索克了。","小武哥儿"},
[1483] = {"菲兹克斯","和狂风峭壁的菲兹克斯谈一谈。","风险投资公司偷走了许多最有天分的地精的创意，不过我们时不时地会偷一些回来。不久以前，风险投资公司在石爪山的分支机构居然雇佣了格雷苏——一个侏儒！他们的另一个工程师菲兹克斯只有靠边站了。他恳求我帮他在工匠协会找份工作，我交给他一些任务，不过他或许会需要帮助。也许你能帮他一把？菲兹克斯现在就住在狂风峭壁的西部。","小武哥儿"},
[1484] = {"堕落者","与凄凉之地的塔卡塔·钢刃谈一谈。","这家伙远比我预料的要危险得多。塔卡塔肯定会怀疑我是否能够成功地刺杀他，而且如果不把这件事情告诉他的话，实在是对他的侮辱。去告诉塔卡塔，如果他允许的话，你将去刺杀那个恶魔，不过你也不要太坚持，如果他有别的办法就最好了。","小武哥儿"},
[1485] = {"邪灵劣魔","给鲁赞带回6颗邪灵劣魔的头颅。","我们之前的术士，在这里得到的只有部落的不信任，虽然我们现在得到了一些容忍，但是部落仍然对我们没有丝毫敬爱。这令我们术士们更加团结在一起，当然，也有一些人选择了隐居的生活，独自研究着他们的魔法。我不会强迫或引导你选择其中的任何一条道路，只会帮助你变得更加成熟。在我教会你召唤恶魔的方法之前，先给我带六颗邪灵劣魔的脑袋回来，在东北方的山洞里就能找到这种生物。","小武哥儿"},
[1486] = {"变异皮革","哀嚎洞穴的纳尔帕克想要20张变异皮革。","由于纳拉雷克斯彻底陷入了他的恶梦之中，有一种此前没有见过的野兽突然侵入了哀嚎洞穴。这些邪恶的生物有着某种奇怪的、不属于这个世界的特性。在我看来，虽然它们本性邪恶，但它们的存在对卡利姆多的居民也并不是完全没有价值的。我相信它们的皮革在制皮业中可能会非常有用。如果你愿意接下这个任务的话，那就到洞穴深处去，想办法帮我找一些变异皮革吧。","小武哥儿"},
[1487] = {"清除变异者","哀嚎洞穴的厄布鲁要求你杀掉7只变异破坏者、7只剧毒飞蛇、7只变异蹒跚者和7只变异尖牙风蛇。","纳拉雷克斯有着一个崇高的目标。我们这位伟大的领袖一直想要进入翡翠梦境，将那片如今已经变得一片荒芜的土地变回过去那样茂密的森林，但似乎有一些可怕的事发生了。纳拉雷克斯的梦境不知为什么突然转化成了一场恶梦，同时，大量的堕落生物出现在了洞穴之中。一些纳拉雷克斯的信徒正在想办法来唤醒我们的领袖，而我此时的职责就是清除洞穴中的那些邪恶生物。去吧，$n，勇敢地把那些变异的生物都清除干净。","小武哥儿"},
[1488] = {"堕落者","杀掉魔王阿兹雷索克和祖格卡，然后向凄凉之地的塔卡塔·钢刃复命。","虽然我对这个魔王阿兹雷索克一无所知，但我同意玛乌林的观点：我们一定要尽快消灭掉这个恶魔，尤其是他正在逐渐控制火刃氏族为他的邪恶目的服务。到了你实现自己的诺言，为酋长和部落而战的时候了，我也相信你有能力召集一只小队去刺杀这个恶魔领主和他的爪牙。如果你准备好了，就直接向南方出发，消灭了这个威胁之后就回来向我复命。","小武哥儿"},
[1489] = {"哈缪尔·符文图腾","和哈缪尔·符文图腾谈一谈。","你带来的兽皮有一种奇怪的斑点，一种我从来没有见过的斑点。我确信绿洲里的水是造成这些斑点的原因，我甚至能够感受到它们给这片土地带来的混乱，这片土地现在死气沉沉的，就好像是长眠不醒了一样。哀嚎洞穴一定就是这一切问题的源头。但是，在你去那里调查以前，先去找德鲁伊长老哈缪尔·符文图腾谈谈吧。我托人给他捎了信，把关于在贫瘠之地所发生的一切都转告给他了。这位博学的长者应该能给你很多忠告。他就在雷霆崖的长者高地上。","小武哥儿"},
[1490] = {"纳拉·蛮鬃","和纳拉·蛮鬃谈一谈。","我进入了梦境，梦见一群住在哀嚎洞穴的德鲁伊。他们曾经是那么的高贵，但如今却已经迷失了方向，变成了一股邪恶力量的奴仆，协助他们的主子席卷贫瘠之地。我已经年老力衰，无法长时间地停留在梦境之中，也无从得知更多有关那些堕落的德鲁伊的事情。不过，纳拉很年轻，她的精力非常旺盛。当我离开的时候，她还在梦境里搜索。去找她吧，她就在那边的帐篷里。","小武哥儿"},
[1491] = {"智慧饮料","收集6份哀嚎香精，把它们交给棘齿城的麦伯克·米希瑞克斯。","好吧，这些角似乎不太有用。不过没关系——万事开头难嘛！我想我已经找到另一种原料，可以让我制造出更好的智慧饮料！有一种叫做哀嚎香精的物质，我想这种东西就是造成贫瘠之地出现各种奇特动植物的原因。帮我找到这种物质，我要把它加入我的饮料里试试看！我听说这种物质可以在西边的哀嚎洞穴里的那些怪物身上找到，去猎捕这种生物，帮我收集哀嚎香精吧。","小武哥儿"},
[1492] = {"码头管理员迪兹维格","把保险箱交给棘齿城的码头管理员迪兹维格。","我需要把一只装有药品、材料和其它物品的箱子送给我在卡利姆多的合伙人。我没时间把它送到棘齿城的码头上去，况且最后一支商队也早已经起航了。如果你方便的话，请把这只箱子交给码头管理员迪兹维格，他会把这只箱子放在下一班开往黑水湾的船上。","小武哥儿"},
[1498] = {"防御之道","给贫瘠之地前沿哨所的犹塞克带回5块烧焦的鳞片。","作为一个战士，你最重要的任务是……保护。我们是部落的护盾和壁垒，我们要保护比我们弱小的同胞的安全。如果你要加入我们，那你就必须先证明自己与我们一样拥有着无比的勇气。到杜隆塔尔的雷霆山去，那里有不少闪电蜥蜴和雷霆蜥蜴。去猎捕那些蜥蜴，向我证明你比它们更加强大！在它们的攻击面前要毫不畏缩，把它们的鳞片给我带回来作为证明。快点出发吧，完成这个任务之后，我将继续让你进行训练课程。","小武哥儿"},
[1499] = {"邪灵劣魔","与祖雷萨谈一谈。","祖雷萨正在找你这样的新手，让他们到当初你猎杀邪灵劣魔的那个地方旁边的洞穴里去，削减那里的生物数量。我想你可以在帮助她的过程中学到很多东西。记得跟她说，你是去帮忙解决小鬼问题的，她肯定会准备一份奖励给你。","小武哥儿"},
[1500] = {"唤醒纳拉雷克斯","","","小武哥儿"},
[1501] = {"虚空中的生物","为奥格瑞玛的甘鲁尔·血眼找回维尔加石板。","很少有术士能活得够久的……我们冒着巨大的风险来研究恶魔，风险越大，回报越大。你必须尽快成熟起来，这样才会成为对酋长和部落有用的人。现在是该让你去学习新的召唤法术了。首先，你必须夺回维尔加石板，那个东西被火刃氏族的术士偷走了，现在石板被保存在他们的巢穴里，那个巢穴就在奥格瑞玛城东的骷髅石。有了石板之后，我会教你如何召唤虚空行者。","小武哥儿"},
[1502] = {"索恩格瑞姆·火眼","与贫瘠之地的索恩格瑞姆·火眼谈一谈。","一柄铸造精良的武器对于战士来说是很重要的。兽人这里最好的武器铸造师是索恩格瑞姆·火眼，他隐居在十字路口东边的山上。如果你想要寻求一把称手的武器，那就去找索恩格瑞姆吧。从这里往西走，到了十字路口以后再往东进入山区，他的营地就在山顶上。","小武哥儿"},
[1503] = {"锻造好的钢锭","把锻造好的钢锭带给贫瘠之地的索恩格瑞姆·火眼。","，我会给你一柄武器，但首先我需要你的帮助。几天前的一个晚上，西北边的那些钢鬃部落的家伙摸进了我的营地，他们不敢和我正面交战，但是他们知道我眼睛不好使，所以就想办法用响声把我引出来，然后派几个同伙溜进去偷了我的东西！他们偷走了一只铁箱子，里面是一些铸造好的钢锭。如果你能够找到它们的话，我就会给你一件你用得到的武器。你应该可以在钢鬃野猪人的营地里找到那只铁箱子，把那些钢锭给我拿回来。","小武哥儿"},
[1504] = {"誓缚","召唤并征服一只虚空行者，然后带着召唤铭文向奥格瑞玛的甘鲁尔·血眼回报。","现在，看着这块维尔加石板，这上面雕刻着的文字会告诉你怎样进行召唤仪式。把它拿到洞穴另一边，放在尼尔鲁·火刃帐篷里的法阵上，然后你就可以开始召唤虚空行者了。无论用格斗也好，用魔法也好，你必须仅凭自己的力量独立战胜它。在这一切都完成之后，带着石板回来找我，我将为你和这个强大的恶魔制定永恒的盟约。","小武哥儿"},
[1505] = {"老兵犹塞克","和前沿哨所的犹塞克谈一谈。","部落非常尊重战士，因为他们具有毋庸置疑的力量。但是真正伟大的战士同时也是一个优秀的学生。去找犹塞克吧，他经历了很多场战斗，并且向很多年轻的战士传授过精湛的战斗技艺。你可以在前沿哨所的南边找到他，那个地方位于贫瘠之地和杜隆塔尔的交界处，就在这里的东边。","小武哥儿"},
[1506] = {"甘鲁尔的召唤","去奥格瑞玛和甘鲁尔·血眼谈一谈。","嘿，你！你叫$n，没错吧？你现在不忙吧？甘鲁尔要马上见你。他在暗影裂口和几个高阶术士待在一起。根据我以前和他打交道的经验，他找你要么是有什么美差吩咐给你，要么就是你大难临头了。","小武哥儿"},
[1507] = {"噬魂者","和暗影裂口的卡祖尔谈一谈。","是时候让你学些其它的召唤魔法了。你得学习如何召唤魅魔，那是一种具有非常强大的精神力量的恶魔。她会诱惑意志薄弱者，让他们心甘情愿地成为她的奴隶！我觉得你已经有足够的能力去面对这样的挑战了。魅魔只能在以一件象征着伟大的爱与奉献的物品作为媒质的情况下才能被召唤出来，你必须自己去寻找一件这样的东西。建议？去和卡祖尔谈谈吧……这世上没什么东西是那个老术士不知道的。","小武哥儿"},
[1508] = {"盲眼卡祖尔","和奥格瑞玛的赞卡沙谈一谈。","嗯……根本不用问你是为什么来找我的。既然是甘鲁尔让你来，那你一定是想要召唤魅魔了，而你现在需要一件东西作为媒质，对吧？嗯……如果你确信我这个瞎子能够帮助你的话，那就听着吧，$n。在奥格瑞玛城内的通天塔以西的一处断崖上住着一个名叫赞卡沙的女性。去找她吧。","小武哥儿"},
[1509] = {"多格兰的消息","找到十字路口的加兹罗格并和他谈一谈。","我的丈夫多格兰最近被派去十字路口值勤了。这对他来说是一种奖赏，令他感到十分自豪。不过我对此却不是那么开心，不过我当然不能让他知道这些，更不能让他担心。大家都说贫瘠之地是一片比奥格瑞玛要危险得多的土地，在我看来那是世上最糟糕的地方。他一星期之前就该回来了，但我现在却仍然没有得到他的丝毫消息……<职业>，你能不能去一趟十字路口，帮我打听一下他们那边有什么消息？他与一个名叫加兹罗格的战士是搭档，那个加兹罗格应该还在那里值勤。","小武哥儿"},
[1510] = {"多格兰的消息","找到玛拉卡金的肯兹格拉并和他谈一谈。","他是在陶拉祖营地被抓住的。我们当时正在和那里的野猪人交战，他带了一小队步兵去进攻野猪人的一处营地，但他在那场战斗里受了重伤。其他战士杀出重围，然后想要回去救他，但多格兰的情况很糟糕，他的伤口已经溃烂了，所以他们觉得要是不能先把他治好再带出来的话，他可能就会因为伤筋动骨而死掉。所以他们和这里联络了一下，希望能从石爪山的玛拉卡金那里的巨魔手里讨些伤药来。我们已经派人去找巨魔们了，但他们至今还没有回复我们。","小武哥儿"},
[1511] = {"肯兹格拉的伤药","将肯兹格拉的伤药交给陶拉祖营地的步兵劳格玛。","我得告诉你们，可能还会有其他人来向我讨伤药，所以我得在这里随时做好准备。快回去吧，$n。你得注意，一开始只能给他一半伤药！这一半足以让他在活动的时候不再出血，免得失血过多而死。等过了一个晚上之后再给他另一半。总之，你得把它带给陶拉祖营地里的劳格玛。根据他派来的上一个信使所说的，他应该已经知道多格兰被关在哪儿了。","小武哥儿"},
[1512] = {"爱的礼物","把沾满泥土的坠饰带给奥格瑞玛的甘鲁尔·血眼。","赞卡沙年轻而美丽，却得跟一个残废过上一辈子……我可不能让她受这种苦。别管我了，$n。谢谢你。我将会在战斗中光荣地结束我的生命，而不是拖着这破碎的躯壳白白度过后半辈子。拜托，别把这些告诉我的老婆……我可不想让她在良心上受谴责。","小武哥儿"},
[1513] = {"誓缚","召唤并征服一只魅魔，然后将多格兰的坠饰还给奥格瑞玛的甘鲁尔·血眼。","把这个放进尼尔鲁帐篷里的召唤法阵，召唤出那邪恶的魅魔，并将她纳入你的掌握。我相信你的魔法能力已经足够强大了。不过你也要和平常一样小心，因为骄傲和过分的自信曾经毁灭过不少前途无量的术士。在你战胜魅魔以后，把那个坠饰拿给我，我好把消息告诉给赞卡沙。","小武哥儿"},
[1514] = {"被腐化的迎风花","","","小武哥儿"},
[1515] = {"多格兰之囚","把肯兹格拉的伤药带给贫瘠之地的多格兰。","你为这件事儿出了很多力，所以你如果愿意帮忙帮到底的话，我当然不会阻止你。但我没办法派给你更多的人了，所以你恐怕只能一个人去救多格兰……多格兰被关在北边的一处野猪人营地里。注意那里的两座小屋子，如果他还没被杀掉或者因为伤口恶化而死掉的话，那群野猪人应该会严密看守他的。祝你好运。","小武哥儿"},
[1516] = {"大地的召唤","给试炼谷的坎纳甘·地鸣带去2只地狱捕猎者的蹄子。","是时候了，年轻的<职业>。你的肉体已经足够强壮，而你的精神也已如大地一般坚韧。你选择了遵循萨满之道，这代表着你拥有无可置疑的睿智。让大地来指引你的命运，让它成为你的一部分吧。但你必须自己去面对大地的力量，如果你已经准备妥当，你就会看见一些只有萨满祭司才能理解的事物。去北边去搜寻那些地狱捕猎者，给我带一对它们的蹄子回来，然后我们再来好谈谈你的未来。","小武哥儿"},
[1517] = {"大地的召唤","找到灵魂石地，在那里喝下大地灵契。","灵契是一种可以在我们的灵魂与元素之间建立起连接的特殊药水。这种融入了魔法的药水将使完全放开了心灵的你看到别人所不能看到的元素。你的灵魂将会永久地与灵契所对应的元素连接起来，只有我们中的少数被选中的人才知道灵契的制法。你必须知道一点……只有在神圣的地方喝下灵契才有效，其它任何地方都是不行的。到这里西南面的灵魂石地去吧——它就隐藏在一些茂密的藤蔓植物之间。到那里去把你的灵契喝掉，然后……嗯，到时候你就知道该怎么做了。","小武哥儿"},
[1518] = {"大地的召唤","把粗石英交给试炼谷的坎纳甘·地鸣。","把这块粗石英交给坎纳甘·地鸣，以此证实我们会过面了。他将会为你制造一根图腾，而这块小圆石则会是图腾的核心。可能它看上去小了点，不过你马上就会知道，大小并不重要，即使是最小的石子也可能比山川还要恒久。耐心一点，。继续保持强健的体魄，并努力追寻智慧吧。这是大地对你的要求。最终，你也将融入大地中，尊重它，它也会尊重你。","小武哥儿"},
[1519] = {"大地的召唤","给纳拉其营地的鸦羽先知带回2份仪式药膏。","是时候了，年轻的<职业>。你的身体已经够强壮，你的精神如大地一般坚韧，这正是你已经成熟的标志。大地引领并教导着我们的族人，以后你也将得到它的指引。但在那之前，你必须先通过试炼。在你完成了试炼之后，就会看到那些只有我们才能看到的东西。往东边去，找到刺背野猪人的萨满祭司，把他们在仪式中使用的药膏拿回来一些。在你得到了足够的药膏之后再回来向我复命。","小武哥儿"},
[1520] = {"大地的召唤","找到科多石并喝下大地灵契。","灵契是一种可以在我们的精神和自然的元素之间建立连接的药水。这种药水融入了魔法，它可以使打开了心灵之门的你看到别人所不能看到的元素。你的精神将会永久地与灵契相应的元素连接起来，只有我们中的少数被选中的人才知道灵契的制作方法。灵契只能在神圣的地方生效，其它的任何地方都不行。到东边的萨满祭坛去，在那里喝下灵契吧。","小武哥儿"},
[1521] = {"大地的召唤","将粗石英带给纳拉其营地的鸦羽先知。","把这块粗石英交给鸦羽先知，这是我们会过面的证明。她将会为你制造一根图腾柱，而这块小圆石则是那根柱子的核心。它可能看上去小了点，不过你马上就会知道，尺寸并不重要，即使是最小的石子也可能比整座山岭还要恒久。耐心一些，。在保持着力量的同时追寻智慧吧，这是大地对你的要求。最终你将会成为大地的一份子，尊重它，它也会尊重你。","小武哥儿"},
[1522] = {"火焰的召唤","去贫瘠之地找到卡纳尔·菲斯。","嘿，火焰可是很强大的，孩子。我看你在地系魔法方面还挺有一套，是时候让你和卡纳尔谈谈了。卡纳尔就住在贫瘠之地，从十字路口一直向北走。他擅长元素魔法，可以教教你怎么使用火焰……当然你得先做好准备。你可以很容易地找到他，不过别走太远——太远就进入精灵的领地了。","小武哥儿"},
[1523] = {"火焰的召唤","去贫瘠之地找到卡纳尔·菲斯。","你已经很久没有接受试炼了，。到目前为止，你已经证明了自己有足够的耐心，现在是时候让你学习更多东西，是时候让你了解毁灭…和混乱了。只要你明白自己即将为此付出的代价，火焰的元素就会与你建立连接。到贫瘠之地去找卡纳尔·菲斯，他就住在十字路口北部的一间小房子里。路上小心点，走太远的话，你就会进入精灵的领地。","小武哥儿"},
[1524] = {"火焰的召唤","把眠炎火炬带给杜隆塔尔的泰尔夫·祖拉姆。","你已经有足够的力量来运用火焰图腾了，不过这并不意味着你已作好了充分的准备。沿着杜隆塔尔的怒水河前进，在河水流入无尽之海的地方，有一条隐蔽的小路，它通向这片大陆上最高的山峰之一。沿着这条小路走到最高处，你就会看到一处由泰尔夫·祖拉姆看守的圣殿，那就是眠炎圣殿。把这个火炬交给泰尔夫·祖拉姆，它是你试图驯服火焰力量的证明。用圣殿里的火盆点燃火炬并把它带回来，我就会将火焰图腾交给你。","小武哥儿"},
[1525] = {"火焰的召唤","找到1个火焰焦油和1个试剂袋，把它们交给杜隆塔尔的泰尔夫·祖拉姆。","你该不是到这儿来上历史课的吧？你是要得到永恒之火和你的火焰图腾。首先，你要制造一个灵契，并将你和它连接起来。只要你给我找来两样东西，我就可以为你制造火焰灵契。第一件是火焰焦油，这个相对而言比较简单，钢鬃野猪人的施法者通常会带着这种东西。另一件则比较危险：从火刃氏族的祭司身上找一个试剂袋。你可以在奥格瑞玛东部找到他们。","小武哥儿"},
[1526] = {"火焰的召唤","击败火焰之魂，将余烬放在恒焰圣殿屋顶的火盆里。","火焰灵契已经做好了，现在你必须面对火焰元素的灵魂。在圣殿中使用灵契，然后去挑战山顶上的火焰之魂。他不会在你没有准备好的时候就攻击你，不过他知道你能看见他。你必须迅速打倒他，，拖得越久他的力量就会越强大。在击败他之后，将他的余烬放在火盆里，然后点燃火炬。","小武哥儿"},
[1527] = {"火焰的召唤","将恒焰火炬交给贫瘠之地的卡纳尔·菲斯。","你手中紧握着火炬离开火盆，望向远处的杜隆塔尔，神圣的火焰随风狂舞，令你感到心中充满了激动和兴奋。你沿着小路回到贫瘠之地去找卡纳尔·菲斯。","小武哥儿"},
[1528] = {"水之召唤","找到贫瘠之地的水之先知伊斯伦。","从你上次接受测验到现在已经有很长的时间了，凶残十三娘。迄今为止，你展示了足够的耐心，不过现在你应该学到更多的东西，应该去了解水的纯洁。去贫瘠之地找到水之先知伊斯伦，沿着怒水河的东岸向棘齿城的南方走，你可以在一间小渔屋里找到她。祝你好运，凶残十三娘。","小武哥儿"},
[1529] = {"水之召唤","找到贫瘠之地的水之先知伊斯伦。","从你上次接受测验到现在已经有很长的时间了，。迄今为止，你展示了足够的耐心，不过现在你应该学到更多的东西，应该去了解水的纯洁。去贫瘠之地找到水之先知伊斯伦，沿着怒水河的东岸向棘齿城的南方走，你可以在一间小渔屋里找到她。祝你好运，。","小武哥儿"},
[1530] = {"水之召唤","到南贫瘠之地去找到布瑞恩。","关于水，有一点是你必须要了解的：水意味着重生。水流动着，消蚀和清洗一切事物。水的治疗和恢复能力是无与伦比的，但这只有在水是完全纯洁的情况下。如果水受到了污染，那么它将毁灭一切它接触到的东西。理解了这一点，你就应该能明白保证水源的纯洁性是多么的重要。如果你想要得到水之灵契，就到南贫瘠之地去找布瑞恩吧，她的家园最近时常受到野猪人的骚扰。","小武哥儿"},
[1531] = {"空气的召唤","到千针石林去找普拉特·白云。","你正在不断地进步，朋友。你已经证明了自己拥有可以控制空气图腾的能力，但是首先，你要去千针石林找普拉特·白云。如果你给予她足够尊重的话，她会很乐意告诉你如何得到空气图腾。从这里一直往南穿越贫瘠之地，在你进入千针石林之后再往东走。你会在一座山洞里找到她和她的男朋友的——哈哈，不要告诉她我说了她那么多的坏话——否则她可不会放过我，真的。","小武哥儿"},
[1532] = {"空气的召唤","到千针石林去找普拉特·白云。","卡利姆多之风正急切地想要见你，而你应该已经成为了我们最强大的$g兄弟:姐妹;之一。我很荣幸能够看到你的光辉未来。风元素是一种非常难以控制的元素，但是我相信以你的能力可以克服挡在你面前的一切困难。到贫瘠之地的最南端，然后从那里走到千针石林。你可以在千针石林的东部找到普拉特·白云，她可以教你更多的东西。","小武哥儿"},
[1533] = {"<NYI> Call of Air","","","小武哥儿"},
[1534] = {"水之召唤","到灰谷的星辰废墟去，将空的蓝色水囊盛满泉水，然后把它交给贫瘠之地的布瑞恩。","现在，你必须带上这个水囊，深入到那片被暗夜精灵称为灰谷的茂密森林中，那地方就在贫瘠之地的北方。进入森林之后向西走，顺着隔断石爪山与灰谷的山脉前进，你会在密斯特拉湖的尽头发现一处圣地：星辰废墟。在那里的湖中央有一眼小喷泉。取回一些喷泉水，那是制作灵契所需的最后一种水样，然后我就可以把你送回伊斯伦那里了。","小武哥儿"},
[1535] = {"水之召唤","到野猪人的水池去，用井中的水装满空的棕色水囊，然后把水囊交给贫瘠之地的布瑞恩。","要得到我的信任并从我这里取得灵契，你就必须找到最纯洁的水。在你寻找这种水样时，别忘了注意周围的动静。要小心那些依赖这种水生存并守护着它的生物，要注意这种水是如何影响森林和荒漠的。看看这种维持生命的特殊物质是如何强迫这些生物进行杀戮的。让我们先从一个简单的任务开始吧：在我的小屋下面有一小池这种珍贵的液体，装满这个水囊后再回来找我。","小武哥儿"},
[1536] = {"水之召唤","用塔伦米尔的井水装满空的红色水囊，然后把它交给贫瘠之地的布瑞恩。","很久以前，我和一些同伴一起去过希尔斯布莱德丘陵。我们为了保护自己而和那里的人类作战，后来发现自己正置身于一个由被遗忘者控制的小镇：塔伦米尔。在那里，我有一个特别的发现：小镇中心有一口清泉小井。我不清楚镇中那些被感染的居民是否清楚它的价值——那口井是那片被亵渎的土地上唯一一块未受亵渎的神圣之地。用这只水囊帮我带回一些那口井里的水。","小武哥儿"},
[1537] = {"<NYI> Call of Air","","","小武哥儿"},
[1538] = {"<NYI> Call of Air","","","小武哥儿"},
[1558] = {"巨石水坝","带着你看护的孤儿去洛克莫丹的巨石水坝。你应该带他去水坝的中间，然后让他俯瞰巨大的瀑布。","铁炉堡是矮人和侏儒的聚居地。在这附近有个地方叫做洛克莫丹，矮人在那里建造了一座巨大的水坝。他们说那是世界上最壮观的建筑！你能不能把我带到洛克莫丹去看看那座水坝呢？我想那座水坝叫巨砖……嗯……巨墙？巨石水坝？它很大——绝对大得让你吃惊。我想要去看看那里的巨大瀑布……我保证我绝对会紧紧跟着你的！","小武哥儿"},
[1559] = {"闪光弹的制法","","","小武哥儿"},
[1560] = {"图加的任务","把图加带回到他的妻子托尔塔身边。","我走丢了！我的妻子托尔塔让我出来找晚餐，我一定是迷了路！你能行行好带我回到托尔塔身边吗？她正在热砂港南部等我。","小武哥儿"},
[1578] = {"前线的补给","给洛克莫丹南部警戒塔的索瓦尔德带去6把铜斧和6条铜质链甲腰带。","洛克莫丹的巡山人正在和穴居人战斗，可真是忙得不可开交呢！要对付那些穴居人，就必须给我们的部队不断提供盔甲和武器。这就是索瓦尔德待在那里的原因，他在为巡山人筹集足够的物资好让他们保持强大的战斗力。如果你能打造一些铜斧和铜质链甲腰带并把它们交给索瓦尔德的话，他一定会感激你的，没准他还会跟你分享他的知识和经验。索瓦尔德就在洛克莫丹的南部警戒塔。","小武哥儿"},
[1579] = {"小齿轮","收集8个小齿轮，把它们交给奥伯丁的维兹班恩·曲针。","我到奥伯丁来仅仅是因为这里相当的安静。我喜欢在安静的地方进行发明创造，因为在一夜痛饮之后，铁炉堡的喧嚣足以让我发疯！因此我乘船来了奥伯丁，路上喝了不少酒，结果我一不小心就把一盒小齿轮掉在了船上！我不能确定把它们掉在什么地方了，但如果你愿意到大海里钓钓看的话，也许……","小武哥儿"},
[1580] = {"导电器","收集12个导电器，把它们交给奥伯丁的维兹班恩·曲针。","我们知道你是个幸运星，不过……你到底有多少幸运呢，？有一天晚上，我沿着黑海岸的小路散步，想要找一条河或一片湖来试验我新发明的自行驱动火爆式诱鸭器，但那时我可能有点醉了……所以我一不留神就睡了过去，几个小时后醒来的时候已经在奥伯丁了。我的头发烧焦了，导电器也都不见了！我一定是把它们丢在水里了！也许你能在黑海岸附近的湖泊或是溪流中钓到它们……","小武哥儿"},
[1581] = {"刃叶的药剂","给在多兰纳尔的塞拉尔·刃叶带去6瓶狮王之力药剂和2瓶初级防御药剂。","我们的药草和炼金原料店发展势头很快，但我的丈夫将太多的时间花在混合药剂上了，我们从来都没有时间留给彼此。如果你能弄来一些已经做好了的药剂，我可以拿一些珍贵的药草来和你交换，你看怎么样？","小武哥儿"},
[1582] = {"月光外衣","把1双雕花皮手套、5双雕花皮靴和5件雕花皮质披风交给达纳苏斯的洛瑟里亚斯。","达纳苏斯的居民，尤其是像我这样的手工艺者，都是相当繁忙的。年轻的冒险家们很想在旷野里试试他们的身手，当然这就需要相应的装备来做保障。如果你能帮我搞到足够多的皮革制品的话，我也许会教你一些高级的制皮技术。","小武哥儿"},
[1598] = {"失窃的典籍","为杜希拉·拉萨雷找回《虚空灵能》。","嘿，说你哪！你叫$n，没错吧？我希望你确实想要成为一名术士，如果你不能执着于自己的信念的话，那你就可能会彻底迷失自我。我会给你指引，但我首先得确定你是否够格。不久前有一个在修道院中修行的学徒逃了出去，加入了迪菲亚兄弟会。为什么我会对这个如此介意呢？是这样的，他偷走了一些重要的典籍。其中有一本正好还是我很想要的，书名叫《虚空灵能》。你去把它给我偷回来，盗贼们应该把这些书藏在了他们农场中的帐篷里。","小武哥儿"},
[1599] = {"开端","给安威玛尔的阿拉玛尔·格里姆带回3个羽毛咒符。","你就是那个每个人都说起的新术士吧。他们一定很喜欢你，不然他们就不会叫我抽出做研究的时间来培训你了。你要学的最简单的一种召唤咒语是召唤小鬼，不过在我把这种咒语传授给你之前，你必须要证明自己有控制小鬼所必需的魔法技能和身体素质。从西南洞穴里的霜鬃巨魔新兵那里给我拿三个羽毛咒符回来再说。","小武哥儿"},
[1618] = {"赤脊山的补给","托姆斯·深炉要你给赤脊山的弗纳·奥斯古带去4条铜质符文腰带和4把铜质大锤。","并不是只有我们矮人在战斗，事实上，我们的人类盟友也忙得不可开交！赤脊山不断受到黑石兽人的袭击，装备和物资也一直跟不上。如果你能提供一些帮助的话，他们的铁匠弗纳·奥斯古应该会教你一两招独家绝活。","小武哥儿"},
[1638] = {"战士的训练","和哈里·伯加德谈一谈。","你已经展示了作为一个战士应有的天赋，。但是你现在还很年轻，还有很多东西需要学习。去和哈里·伯加德谈谈吧——他通常都在暴风城旧城区的猪和哨声旅店里。哈里是个老兵，也是个优秀的老师。他能教你许多一生受用的知识。","小武哥儿"},
[1639] = {"醉鬼巴特莱比","和巴特莱比谈一谈。","当然，我可以教你。不过，我先要看看你到底有多大的本事。看见酒吧最里面的那个醉汉了吗？就是那个巴特莱比，我要你去把他的酒杯拿来。哈哈，如果你了解巴特莱比，你就会明白他是不会轻易把酒杯给你的。","小武哥儿"},
[1640] = {"击败巴特莱比","打败巴特莱比，然后再和他谈一谈。","你要什么？？你疯了吧？你想要我的酒杯？来试试看啊！","小武哥儿"},
[1641] = {"圣洁之书","","","小武哥儿"},
[1642] = {"圣洁之书","与暴风城的达索瑞恩·拉尔谈一谈。","无论在什么时候，圣骑士都必须严格地遵循圣光之道，因为它是我们力量的源泉。对于我们圣骑士来说，为了追求神圣而进行的几近苛刻的修行并不意味着我们是为了神格而努力——我们的目标是要在各方面都努力完善。虽然和邪恶斗争是眼前的当务之急，但是你必须牢记，只有无私地帮助他人才是圣骑士区别于普通人的根本要素。同情、耐心、勇敢——这些品德对圣骑士而言，和战斗中所表现出来的力量一样重要。记住这点，永远不要忘记。","小武哥儿"},
[1643] = {"圣洁之书","在暴风城的贸易区找到斯蒂芬妮·特纳。","你的任务就是在暴风城里找到一个需要帮助的人，一个心灵纯洁动机单纯的人。这也许是某个想要帮助别人的人，也许是某个需要指引的人。不管怎样，这个人必须心地纯朴，而且需要你的帮助。完成这件事之后再回到我这里来，那时我们再来谈关于你的修行之道，以及成为圣骑士的意义。","小武哥儿"},
[1644] = {"圣洁之书","给暴风城的斯蒂芬妮·特纳收集10块亚麻布。","愿圣光护佑那些孩子，他们大多因为几年前那次亡灵天灾的袭击而失去了家庭。我丈夫约翰为我收集给孩子们做衣服裤子的布料，不过我没时间做，因为我得成天忙着照顾他们的饮食起居。什么？你愿意帮忙？赞美圣光，也感谢你，好心的。如果你能给我找点亚麻布来的话,我就能给孩子做衣服了，那可真是帮了我的大忙。","小武哥儿"},
[1645] = {"圣洁之书*","同我再次交谈，我将给你圣洁之书！","完成任务得到任务书，右键点击任务书，接受以完成这次任务！","小武哥儿"},
[1646] = {"圣洁之书","与铁炉堡的蒂萨·热炉谈话。","无论在什么时候，圣骑士都必须严格地遵循圣光之道，因为它是我们力量的源泉。对于我们圣骑士来说，为了追求神圣而进行的几近苛刻的修行并不意味着我们是为了神格而努力——我们的目标是要在各方面都努力完善。虽然和邪恶斗争是眼前的当务之急，但是你必须牢记，只有无私地帮助他人才是圣骑士区别于普通人的根本要素。同情、耐心、勇敢——这些品德对圣骑士而言，和战斗中所表现出来的力量一样重要。记住这点，永远不要忘记。","小武哥儿"},
[1647] = {"圣洁之书","在铁炉堡的外环区域找到约翰·特纳。","，你的任务是在铁炉堡里找到一个需要帮助的人，一个心灵纯洁动机单纯的人。这也许是某个想要帮助别人的人，也许是某个需要指引的人。不管怎样，这个人必须心地纯朴，而且需要你的帮助。完成这件事之后再回到我这里来，那时我们再来谈关于你的修行之道，以及成为圣骑士的意义。","小武哥儿"},
[1648] = {"圣洁之书","收集10块亚麻布，把它们交给铁炉堡的约翰·特纳。","我和我的妻子在暴风城管理着一家孤儿院，帮助在过去几年里因为亡灵天灾的袭击而失去双亲的孩子们。我差不多每个月都要来铁炉堡收集这里的居民捐赠的物资，而且我也会和不同的团体商谈，尽可能地寻求他们的帮助。这样的旅程往往让人苦恼，因为它很费时间而且收效甚微。如果能找到些亚麻布来让我妻子给那些孤儿做些衣服的话，我想我就可以寄些东西回家了。","小武哥儿"},
[1649] = {"勇气之书","与暴风城的达索瑞恩·拉尔谈一谈。","勇气，以及伴随着它而共同存在的一切美德，就如同那些珍贵的矿石一般：当你拥有它们的时候，要记得珍惜，因为它们非常宝贵。你也需要花费很大的精力去开采，去提炼。当你恰当地将这些矿石混合起来，一种新的坚不可摧的金属就会产生，即使是最强大的力量也无法将其破坏。这种来自你的信仰和勇气的力量必须经过考验。你必须学会绝不放弃信仰，并了解到在圣光之力的庇护下，你可以跨越过凡人根本无法跨越的障碍。","小武哥儿"},
[1650] = {"勇气之书","在西部荒野找到达芙妮·斯迪威尔。","很好！你对此表现出来的毫不犹豫可以清晰地佐证：你已经准备好了，并渴望着进行试炼。那么，去吧。在西部荒野的长滩最南端的尽头，有一处临海而建的小屋。屋里住着一对名叫斯迪威尔的夫妇。丈夫乔丹·斯迪威尔是一位技艺精湛的铁匠，他暂时去铁炉堡会见他的矮人朋友们了。于是他那无依无靠的妻子达芙妮目前一个人在家里待着。根据线报，迪菲亚兄弟会几乎已经完全控制了那片地区，势单力薄的达芙妮或许需要一位勇士的保护。去吧。","小武哥儿"},
[1651] = {"勇气之书","在迪菲亚兄弟会进攻时保护达芙妮·斯迪威尔的安全。如果你想成功的话，你和达芙妮都不能死在他们的剑下。","我敢打赌，他们马上就要再杀过来了，你最好有所准备。我在屋里放了一把枪，我会用它来帮你的，不过可别太指望我了，最终你还是得靠自己。我不知道他们来了多少人，但我敢肯定会比先前来的要多。祈祷圣光保佑你和我吧，因为……你听到脚步声了吗？他们来了！准备战斗！","小武哥儿"},
[1652] = {"勇气之书","与暴风城的达索瑞恩·拉尔谈一谈。","拜托你，请回到达索瑞恩那里，转告诉他我现在已经安全了，我一定要好好感谢你和教会。他会派人给正在铁炉堡的乔丹带份口信，让他不要担心我。啊，我是多么想念他呀……我都等不及想见他了。","小武哥儿"},
[1653] = {"正义试炼","去和铁炉堡的乔丹·斯迪威尔谈一谈。","事实上，我想乔丹本人会非常感谢你的。我正准备找人给他送个信，让他知道他的妻子目前很安全，我想你就是个合适的人选。乔丹原本可以成为一名为圣光而战的圣骑士，不过后来为了继承他父亲的手艺走上了另一条路——他对我们的生活方式非常熟悉，也是我们最忠实的朋友。他应该还在铁炉堡，白天的时候，乔丹喜欢在室外工作，比如在山里呼吸新鲜的空气。","小武哥儿"},
[1654] = {"正义试炼","按照乔丹的武器材料单上的说明去寻找一些白石橡木、精炼矿石、乔丹的铁锤和一块科尔宝石，然后回到铁炉堡去见乔丹·斯迪威尔。","如果你愿意接受奖赏的话，我会给你奖赏的。请不要误会，我的慷慨取决于你能给我多少帮助，不过这样的同盟关系对你我都有好处。我可以为你制作一把配得上你的成就的武器，一把象征着圣骑士的精神和圣光的武器，不过首先，你要给我找到制作这把武器所需的材料。我已经列出了所需的材料，现在得有一个勇敢能干的人去找到它们。你愿意去完成这个任务吗，$n？","小武哥儿"},
[1655] = {"白洛尔的矿石","把乔丹的矿石带给洛克莫丹的白洛尔·石手。","啊！你吓了我一跳，$G先生:小姐;！你没看到我在思考吗？那是什么？乔丹的矿石…送去铁炉堡的……啊，这样啊，我知道你说的是什么了。那群莫格罗什食人魔抢走了我朋友的矿石，商队从这里前往湿地的路上遭到了埋伏。唯一从袭击中逃出的守卫也在前几天死掉了——医师没能及时赶到。你想找到那些矿石，就往东北方向去，在洛克湖的另一边。矿石一定就在那里的某个地方。","小武哥儿"},
[1656] = {"未完的任务","将一捆毛皮带给血蹄村的旅店老板考乌斯。","拜托，，求求你了，帮我一个忙吧！我正在完成我的力量仪祭，但父亲又要求我将这些皮毛送到血蹄村的旅店。我实在分不开身去同时完成仪祭和父亲交付给我的任务。你……能不能替我跑一趟？在长途旅行之后，旅店可是个休息的好地方。我敢说你到了那里之后也会同意的。","小武哥儿"},
[1657] = {"臭气熏天的南海镇","将三颗亡灵臭气弹放置在希尔斯布莱德丘陵的南海镇中心，完成任务之后回到提瑞斯法林地的黑暗召唤者雅恩卡那里。","我们这次万圣节的庆祝要换个方式……我们要给南海镇的敌人带去痛苦！拿着这些特殊的臭气弹。其中包含了任何人类——或者较弱的野兽——都无法忍受的味道。你需要把这些臭气弹丢在南海镇的中心，然后使它生效，准备和联盟好好干一仗吧！当你完成任务之后……完成这个象征我们自由的标志之后，回到我这里来！","小武哥儿"},
[1658] = {"稻草人的节日","在提瑞斯法林地找到被遗忘者的稻草人节日举办地点。任务完成之后回到南海镇的哈特曼中士那里。","我需要勇敢的人去提瑞斯法林地然后找到亡灵的稻草人节日举办地点。我不想撒谎——去那里会有危险。那里的守卫非常凶悍。但是，我们需要知道今年这个展会的规模有多大，另外就是被遗忘者打算在万圣节给我们造成多大的麻烦。如果你愿意接受这个任务的话，去提瑞斯法林地进行侦查吧。当你得到有价值的情报之后就回到我这里来，我会给予你优厚的补偿。","小武哥儿"},
[1659] = {"<UNUSED>","","","小武哥儿"},
[1660] = {"<UNUSED>","","","小武哥儿"},
[1661] = {"高贵之书","与暴风城的达索瑞恩·拉尔谈一谈。","很高兴再见到你，。我很荣幸能够称呼你为$g兄弟:姐妹;——你的奉献和无私对我们而言是一种恩赐。现在我要对你进行嘉奖了，但是你要知道，虽然这次我把它免费送给你，但是将来，如果时间允许的话，这将成为所有圣骑士都要接受的挑战。等一会再来与我交谈，我就将给你一份很棒的礼物。","小武哥儿"},
[1662] = {"<UNUSED>","","","小武哥儿"},
[1663] = {"<UNUSED>","","","小武哥儿"},
[1664] = {"<UNUSED>","","","小武哥儿"},
[1665] = {"巴特莱比的酒杯","把巴特莱比的酒杯交给伯加德。","好吧，这是我的酒杯。等等！让我先把酒喝光……给你。","小武哥儿"},
[1666] = {"治安官哈迦德","和治安官哈迦德谈一谈。","你学会了一些招数，但你应该有一件像样的武器。我敢打赌，只要你和治安官哈迦德先生谈谈的话，他一定会帮助你的。\n$哈迦德先生就住在艾尔文森林东谷伐木场的一个庄园里。他已经退休了，不过他在工作期间曾收集了不少装备。告诉他是我派你去的，如果你够走运的话，他会提供给你一件武器的。","小武哥儿"},
[1667] = {"蛀牙杰克","从蛀牙杰克的营地里取回治安官哈迦德的徽章，把它交给治安官哈迦德。","是伯加德派你来的吗？是的，我这里的确有一些剩余的武器，不过首先有一项任务交给你……不久以前，一个被称作蛀牙杰克的迪菲亚混蛋捉弄了我。天很黑，他穿着一件暴风城卫兵的衣服，我还以为他是治安官杜汉呢。他说他要我那个旧的暴风城治安官徽章，我就把徽章给了他……然后他便大笑起来，在我反应过来之前就跑掉了！帮我取回我的勋章！蛀牙杰克应该是把徽章放在南边的迪菲亚盗贼营地里了。","小武哥儿"},
[1678] = {"维吉雷克","将维吉雷克的头颅交给铁炉堡的穆伦·雷矛。","如果你想提高自己在战士中的地位，那么你就必须变得更加坚韧一些。我可以教你一些新的技能，不过在此之前，你要向我证明你能够对付真正的敌人。维吉雷克是这一地区最强大的巨魔，也是你即将挑战的对手。他住在霜鬃要塞南方山脚下的棚屋里。把维吉雷克的头颅交给我，让我看看你的勇气和力量。","小武哥儿"},
[1679] = {"穆伦·雷矛","和穆伦·雷矛谈一谈。","你好，战士！你有很大的潜力，不过你还要学习更多的技巧才行，穆伦·雷矛是最合适向你传授这些技巧的矮人。你可以在铁炉堡军事区的军事大厅里找到穆伦。当你准备要成为一名真正的勇士的时候，就去和他谈谈吧。","小武哥儿"},
[1680] = {"托姆斯·深炉","和托姆斯·深炉谈一谈。","既然你已经学了几招，该是为你配备一件像样的武器的时候了。去和托姆斯·深炉谈谈吧，他能铸造一件肯定让你喜欢的武器。托姆斯就在铁炉堡的大锻炉。","小武哥儿"},
[1681] = {"铁环营地","把暗影矿石交给铁炉堡的托姆斯·深炉。","我的导师，斯塔基·铁环，原本在丹莫罗东部的盔枕湖南边有一处独家小院。他在那里向别人传授铁匠的技能，他绝对是最棒的。不过，有一天，他的一个学生带给他一块奇特的矿石。铁环把它叫做暗影矿石，他很希望能用它做点什么，可是，之后不久……一伙黑铁矮人袭击了他的小院。他们杀死了所有的人！到铁环的小院去，，为我的导师复仇，然后把那块暗影矿石给我带回来。","小武哥儿"},
[1682] = {"灰铁武器","","","小武哥儿"},
[1683] = {"沃鲁斯·邪蹄","将沃鲁斯的角交给达纳苏斯的艾兰娜瑞。","在我向你传授知识之前，你必须显示出决心。有一个名叫沃鲁斯·邪蹄的萨特找到了我们的一口月亮井，就在班奈希尔兽穴的东南方。他正在井中戏耍，用他邪恶的身躯污染纯洁的井水。到月亮井那里去找到沃鲁斯，把他干掉。把他的角给我带回来，然后我就会向你传授更高级的战士技能。去月亮井的路不太好找，但是如果你细心一点的话，应该不会迷路的。","小武哥儿"},
[1684] = {"艾兰娜瑞","和艾兰娜瑞谈一谈。","你好啊，勇敢的战士。你的技能越来越纯熟，但战士这个职业的要求比你想像中的要高很多。要想再进一步，你就必须要找到一个优秀的老师。艾兰娜瑞就住在达纳苏斯的战士区里，她会成为你的良师。","小武哥儿"},
[1685] = {"加科因的召唤","去暴风城的法师区向黑暗缚灵者加科因报到。","难道不是每次都这样吗？！我找了你一整天都不见你的踪影，等我已经不指望能找到你的时候你却来了。你已经浪费我太多时间了，所以现在咱们就少废话了。加科因大师要召见你进行更多训练，我觉得你最好还是尽快找到他。他在已宰的羔羊旅店的地窖里。顺便说一句，他的藏身地点你可得保密，不要让别人知道了。","小武哥儿"},
[1686] = {"艾鲁拉的阴影","将艾鲁拉的徽章和8块月神矿石交给达纳苏斯的艾兰娜瑞。","你已经学会很多东西了，。现在我们将为你制作一件精良的武器，一件属于战士的武器。要完成这一使命，你必须去一趟黑海岸。很久以前，有一条船在奥伯丁灯塔附近触礁，许多装有月神矿石的箱子沉入了海底。首先，你必须打败守护那些矿石的亡魂——艾鲁拉的阴影。作为一船之长，她对自己施加了诅咒，变成了一个在海洋深处巡游的亡魂，时时刻刻保护着船上的货物。打败她，摘下她的徽章，然后收集丢失的月神矿石。","小武哥儿"},
[1687] = {"幽灵灯塔","带着你看护的孤儿去西部荒野海岸边的灯塔。","有时候，我们孤儿院的院长会在晚上给我们讲一些鬼故事。真是太恐怖了！其中有一个故事说在西部荒野的灯塔那里有一个游荡的幽灵。他们说那是一个海盗船长，他的船被别的海盗给抢了。这真是太刺激了！你能不能把我带到西部荒野的灯塔那里去？我想要看看那个幽灵船长是不是真的在那里！我保证会一直跟着你，而且绝对不会跑开或者惹些什么麻烦！","小武哥儿"},
[1688] = {"苏伦娜·凯尔东","为暴风城的黑暗缚灵者加科因夺回苏伦娜的项圈。","我曾有一个名叫苏伦娜·凯尔东的学生。她过去和现在的你一样，一心渴求学习到强大的术士魔法，而且她也拥有着十分了得的天赋。更难能可贵的是，她很年轻，而且很漂亮。我最近又看见她了，那个背叛了我的女人！那时候她和迪菲亚兄弟会里的一个小贼埃尔兰·杜德摩尔私奔了。她走掉其实倒也没什么，但我曾送给她一条血石项圈，我必须把它拿回来。现在她的性命对我来说一点都不重要了。你应该可以在布莱克威尔南瓜田找到她，到那儿去把我的东西给夺回来！","小武哥儿"},
[1689] = {"誓缚","召唤并制服一个虚空行者，然后将血石颈环还给暴风城的黑暗缚灵者加科因。","你找回了我的颈环并击败了苏伦娜，这证明你有着至少与她势均力敌的力量。虽然这么说，但我还是认为你需要进一步的训练。你现在已经能够控制魔法的流动了，这很好，但如果你要想要成为一位优秀的术士，这还远远不够。我会教你如何控制虚空行者，不过在我教你之前，你得先在召唤法阵上召唤它出来并制服它，无论你用什么武器都好——剑或者魔法——随你自己乐意吧。在下面的召唤法阵上使用这个颈环里的魔法，然后击败从虚空中出现的恶魔。","小武哥儿"},
[1690] = {"废土的公正","去加基森的东面杀掉10个废土窃贼和10个废土强盗，然后向总工程师比格维兹复命。","你！是你出马帮助加基森水业公司的时候了！那些废土游牧民几乎占据了塔纳利斯沙漠上所有的水井！如果得不到这些水井的控制权，那我们的水源供应很快就会出现问题。如果你想帮助我们的话，就去解决那些该死的游牧民吧！从这里往东走，去干掉10个废土窃贼和10个废土强盗，然后立即向我报告。你一定要为我们这些人……呃……地精们伸张正义啊，不管怎么样，快点行动吧！","小武哥儿"},
[1691] = {"废土的公正","杀死10个废土暗法师、8个废土游荡者和6个废土刺客，然后向加基森的总工程师比格维兹报告。","现在我们需要你去对付那些更强大的废土游牧民。到现在为止你都表现得相当出色，但是如果我们想要夺回水井的话，那么就必须要干掉更多的游牧民！这次，我要你去杀死他们的游荡者和刺客，还有暗法师。你可以在这里的东南面找到这些家伙。说实话，他们都很棘手。但是请你一定要帮忙，我们要取回属于自己的东西！","小武哥儿"},
[1692] = {"铁匠玛希尔","把这箱月神矿石交给铁匠玛希尔。","我把你收集到的月神矿石装进了一只箱子。把它交给铁匠玛希尔，他会帮你打造一件月神武器。玛希尔住在靠南的地方，就在这座建筑物的另一侧。","小武哥儿"},
[1693] = {"月神武器","","","小武哥儿"},
[1698] = {"犹鲁斯·麦酒","与犹鲁斯·麦酒谈一谈。","犹鲁斯·麦酒向联盟所有强大的战士发出了挑战。他在赤脊山的湖畔镇旅店等候着你们，并承诺会给所有通过试炼的战士提供丰厚的报酬。","小武哥儿"},
[1699] = {"往返瑞斯班洞穴","进入瑞斯班洞穴，然后在规定的时间内回到犹鲁斯·麦酒那里。在整个过程中你都不能死掉或者释放灵魂，否则任务就宣告失败。","我把我的挑战项目称作“往返瑞斯班洞穴”。要想通过这次挑战，你要做的就是进入瑞斯班洞穴，然后回到这里——非常简单的任务！当然，路上也许会有一些小波折……你必须在一个小时之内返回这里，有成堆的赤脊山豺狼人挡在路上，所以你得花些时间打发它们。在出发之前，请喝下以我的家族名字命名的美酒：热麦酒！那么，你觉得如何？瑞斯班洞穴就在湖畔镇北面的山脚下，你准备好了吗？","小武哥儿"},
[1700] = {"格瑞曼德·艾尔默","把弗伦的笔记交给格瑞曼德·艾尔默。","帮你铸造铠甲的时候，我记下了一些心得体会。我要找个人帮我把这份笔记交给格瑞曼德·艾尔默，他在矮人区的武器店里。把笔记交给他的时候要显得低调一点，他对自己的技术有近乎狂妄的自信，根本不愿从我这里学点什么……","小武哥儿"},
[1701] = {"弗伦的铠甲","收集必需的材料，将它们交给暴风城的弗伦·长须。","我已经给了你一面精致的盾牌，不过我们的合作决不会就此结束。我知道如何铸造异常坚固的铠甲，但是铸造起来并不容易，我需要一些稀有的材料，只要你愿意跑跑腿，我保证会为你打造一件。你觉得怎么样，？如果你愿意接受挑战的话，我会给你一份列表，上面记载着我需要的材料和到可以找到这些材料的地点。","小武哥儿"},
[1702] = {"铸盾师","将这桶热酒交给弗伦·长须。","，当你完成挑战时，我就看出你是个厉害的家伙啦。当然，我说话算话，我会按照承诺给你奖励……不过，这件礼物在暴风城。去跟我的朋友弗伦·长须谈谈吧，他在暴风城的矮人区里。我敢说他是你见过的最棒的铸盾师，他欠我一份人情。给，把这桶热麦酒交给弗伦，让他为你制造一副盾牌。那品质绝对让你满意！","小武哥儿"},
[1703] = {"玛希尔","把弗伦的笔记交给玛希尔。","在帮你铸造铠甲的同时，我记下了自己的心得体会。现在我得找个人帮我把笔记交给铁匠玛希尔，他住在遥远的达纳苏斯，但我相信他一定非常希望看看我记录的这些东西。","小武哥儿"},
[1704] = {"科罗莫特·钢尺","把弗伦的笔记交给科罗莫特·钢尺。","在帮你铸造铠甲的时候，我顺手记下了我学到的技术。现在我得找个人帮我把笔记交给科罗莫特·钢尺。他是铁炉堡的侏儒铁匠，当他知道我学到的技术以后……我敢打赌，他一定会兴奋地拔掉胡子的！","小武哥儿"},
[1705] = {"燃烧之血","把20瓶燃烧之血和1块燃烧之石交给暴风城的格瑞曼德·艾尔默。","我很不愿意相信弗伦可能发现了什么新奇的东西。不过，为了确认这一点，我要把他的技术应用到这副新的铠甲上。如果你能帮我找来这些原料，，你就能拥有这样的一件铠甲。要制造这件铠甲的话，我需要一些燃烧之血和一块燃烧之石。我知道唯一能找到它们的地方是暮色森林，那些在罗兰德末日矿洞里出没的夜行狼人拥有燃烧之血，而他们的首领加特斯比尔则拥有燃烧之石。愿好运永远与你同在, 。","小武哥儿"},
[1706] = {"格瑞曼德的铠甲","","","小武哥儿"},
[1707] = {"收集水袋","收集5只废土水袋，把它们交给加基森的鲁格伦克。","你好啊，！我叫鲁格伦克，如果你想要找些事情干，我们这里现在就有一件重要的工作给你！没有什么能比帮我带回一些废土水袋来更能令我这个老家伙开心的了。那可都是我们的水——就是那些混蛋把它们偷走了！你每给我带回五只废土水袋来，加基森水业公司就会奖励给你一个可以用来碰运气的小包裹。更重要的是，我们会永远记住你所提供的帮助！","小武哥儿"},
[1708] = {"铁珊瑚","收集20块灼热珊瑚，把它们交给铁炉堡的科罗莫特·钢尺。","我希望在我自己的铠甲上应用弗伦·长须的新技术。因为你帮了弗伦的忙，而他又帮了我的忙，所以当我做好铠甲以后，你可以第一个试用它！要打造铠甲的话，我就得弄到一种特别的珊瑚，灼热珊瑚。它只生长在一个地方——湿地的米奈希尔港南边的海岸地带。只要你给我带来我足够多的灼热珊瑚，我就可以马上开始铸造铠甲啦。快点，，我恨不得现在就开始工作！","小武哥儿"},
[1709] = {"科罗莫特的成果","","","小武哥儿"},
[1710] = {"晒焦的蛋壳","把20个晒焦的蛋壳交给达纳苏斯的玛希尔。","我很想测试一下弗伦·长须的最新发现，希望能将它用于我正在研究的新式铠甲上，我认为弗伦的技术一定能产生最好的结果。你愿意帮助我吗？如果你愿意帮我收集制造铠甲所需的原料，我就会帮你也做一件。我需要晒焦的巨翼双足飞龙蛋壳，这种飞龙大都栖息在千针石林的风巢中。在它们的巢下可以找到我要的蛋壳，当你收集了足够数量的蛋壳之后就赶快回来找我。","小武哥儿"},
[1711] = {"玛希尔的铠甲","","","小武哥儿"},
[1712] = {"塞克隆尼亚","把巴斯拉的羊皮纸上列出的东西交给奥特兰克的捕风者巴斯拉。","我几十年来都在关注着这个地方。我关注着，希望有一天能看到强大的塞克隆尼亚被人击败。但迄今为止，我还没有找到一个能打败风之王的勇士。也许你就是那个勇士。证明给我看吧，给我找来召唤塞克隆尼亚所需的东西，这样你就能证明自己是一个伟大的勇士。也许你能打败他并夺得他的旋风之心。这样的话，我将把这颗心的力量注入一把武器里，供你在今后的冒险旅程中使用。这张羊皮纸上写着我需要的东西。","小武哥儿"},
[1713] = {"召唤","将旋风之心带给捕风者巴斯拉。","我已经准备好仪式要召唤塞克隆尼亚了。当他被召唤出来时，你必须打败他，然后得到他的旋风之心。我将用它来把塞克隆尼亚的力量注入到一件武器中。，你准备好面对风之王了吗？","小武哥儿"},
[1714] = {"流放精华","","","小武哥儿"},
[1715] = {"已宰的羔羊","去暴风城的法师区向黑暗缚灵者加科因报到。","哎，以前术士们都在卡兹莫丹由诺莫瑞根的大师训练，现在我们不得不搬到铁炉堡这个老鼠洞里，而且麦格尼又在一直监视我们，所以我们只能把新手都送到暴风城去训练了。幸运的是，加科因还算是个有能力的人，你还是能在那里学到你需要的东西的，不过现在这种样子还是让我很冒火！加科因就在暴风城的“已宰的羔羊”旅店的地下室里。","小武哥儿"},
[1716] = {"噬魂者","与贫瘠之地的先知塔卡尔交谈。","魅魔是灵魂的吞噬者，心灵的毁灭者，思想的控制者。她脑中永远只有邪恶的念头。这就是你现在要学会召唤并控制的生物，但在没有诱饵的情况下，你是无法将她引入到我们的世界中来的。以一件象征爱的事物作为诱饵，魅魔才会回应你的召唤。在这之后，你只有战胜她才能将她变为你的工具。但是找到象征着爱的东西可不容易，你最好和先知塔卡尔谈谈。他就住在卡利姆多大陆的贫瘠之地，靠近陶拉祖营地的地方。","小武哥儿"},
[1717] = {"加科因的召唤","去暴风城的法师区向黑暗缚灵者加科因报到。","$n！没想到在这儿遇见你，不过我接到指示说要注意你的行踪。你应该接受更多训练了，下一次去暴风城的时候记得去见一下加科因，他正在等你。","小武哥儿"},
[1718] = {"岛民","和克兰诺克·马克雷德谈一谈。","作为一名战士，你的名声越传越响，。现在是时候让你和其它战士比试一下，看看你真正的实力了。在贫瘠之地的海岸附近有一座名叫勇士岛的小岛，就在棘齿城的南部，强大的战士们时常在那里聚会。他们在那里相聚，然后互相切磋。去和勇士岛的首席战士克兰诺克·马克雷德谈谈吧。如果他认为你够格的话，就会指引你在勇士的道路上更进一步的。","小武哥儿"},
[1719] = {"格斗考验","杀掉比格维尔，然后向勇士岛的克兰诺克·马克雷德回复。","如果你想从我这儿学到什么，你必须首先通过格斗考验。对于我们勇士岛上的自认为勇猛而又跃跃欲试的战士们来说，这是他们必须通过的挑战，如果你能通过这个考验，那么你就证明了自己的价值。要开始接受考验的话，就走到那边人群中的斗阵中央。图维基·弗拉海德会知道你已经准备好了，然后他就会派出挑战者来对你进行考验。在战胜了所有挑战者之后，他会叫出比格维尔。杀了比格维尔，在限定的时间内回到我这里来复命。","小武哥儿"},
[1738] = {"同心树","从灰谷取回同心树，把它交给暴风城法师区里的黑暗缚灵者加科因。","为了你的到来，我拨开时间的迷雾，搜寻了整个世界，终于找到了你在寻找的东西。在上古战争的一场战斗中，有一对恋人一起倒下了。在他们死去的地方，一棵同心树茁壮地生长了起来，那是他们至死不渝的爱情的象征。那棵树应该足以用来引诱魅魔，你可以在灰谷森林西北的奥迪拉兰废墟里找到它。","小武哥儿"},
[1739] = {"誓缚","召唤并制服一个魅魔，然后将同心树之核还给已宰的羔羊旅店的黑暗缚灵者加科因。","你可以使用同心树之核在下面墓穴里的召唤法阵中施展一个法术，以此打开一个供魅魔通行的传送门。小心点，$n，即使是意志最坚定的人，也会被魅魔轻易控制。一旦你成功地击败了她并把她投回无尽虚空之后，就回来找我，我会告诉你如何召唤并控制她。","小武哥儿"},
[1740] = {"索兰鲁克宝珠","找到3块索兰鲁克宝珠的碎片和1块索兰鲁克宝珠的大碎片，把它们交给贫瘠之地的杜安·卡汉。","当燃烧军团中的某个恶魔失宠以后，他们的灵魂就会被囚禁在宝珠中，供他们的法师或者术士差遣。很多宝珠被赐给了艾泽拉斯的恶魔之仆。即使是一颗破碎的宝珠，仍然可以蕴含着强大的恶魔力量。索兰鲁克宝珠碎成了两块，其中的一块又被砸成碎片，分发给黑暗深渊中的暮光之锤侍僧使用。另一块比较大的碎片在影牙城堡的一个巫师的手中。把它们找来给我，我可以用这些碎片重塑宝珠。","小武哥儿"},
[1758] = {"阴谋之书","与铁炉堡的克罗姆·粗臂谈一谈。","仅仅靠一个简单的召唤法阵是无法为你召唤出地狱猎犬来的。我和我的三个助手会帮助你制造召唤法阵，但是你必须先弄到一本阴谋之书的副本，我们很久之前就把那本书给弄丢了。阴谋之书是当初一批术士为了召唤地狱猎犬而写的书。克罗姆·粗臂也许能给你提供一些帮助，他原本是一个四处巡游的术士，但是现在却整天躲在铁炉堡的图书馆里苦心研究古代文献。","小武哥儿"},
[1778] = {"圣洁之书","与铁炉堡的蒂萨-热炉谈一谈。","我计划不久后就回到家乡。幸运的是，斯蒂芬妮在暴风城把孤儿院照顾得不错，我简直等不及要见她了。再见，。","小武哥儿"},
[1779] = {"圣洁之书","带上生命符记，和铁炉堡的穆里顿·热炉谈一谈。","我希望你带上这个，。它的名字叫生命符记。你已经显示了自己的仁慈与耐心，现在我需要你证明在战斗和魔法两个方面的能力。最近，我的丈夫穆里顿在和黑铁矮人的战斗中负伤归来，他几乎丢了性命——一个牧师治好了他所受的伤。带上生命符记，和我丈夫谈谈。如果你能帮助他的话，我们可以再聊聊。愿圣光保佑你。","小武哥儿"},
[1780] = {"圣洁之书","与暴风城的达索瑞恩·拉尔谈一谈。","我今天就把这些拿给孩子们。你要多加小心，好心的$n。城里已经很难看到像你这样乐于助人的$G绅士:女士;了，不过你已经证明了圣骑士决不会拒绝帮助那些陷入困境的人。请多保重。","小武哥儿"},
[1781] = {"圣洁之书","把生命符记带给暴风城的贾森·坦诺姆。","拿着这个，。这是生命符记。你已经证明了自己的仁慈和耐心，现在让我们看看你是否有能力掌握光明之道的一项最伟大的能力。我的朋友贾森最近刚从艾尔文森林的英烈碑回来，他在那里遭遇了迪菲亚盗贼，差点就没命了。现在他正在圣坛边上接受牧师的治疗。把这个符记带给他，和他谈谈。如果你帮得了他，我们很快就能再见面了。愿你永享圣光的荣耀。","小武哥儿"},
[1782] = {"弗伦的铠甲","","","小武哥儿"},
[1783] = {"圣洁之书","使用生命符记复活丹莫罗的纳姆·法奥克。","我们一直在侦察一些潜伏在盔枕湖以南的黑铁矮人。我们知道他们出现在那里决不是什么好事，因此我和纳姆决定靠近些去看看——看看他们的头目到底下了些什么命令。我和纳姆发起了突袭，杀掉了一些黑铁矮人，但他们比我们想像的还要顽强，一大堆黑铁矮人朝我们扑了过来。纳姆让我来求援，我就跑回来了。纳姆需要帮助，我们一定要尽快，否则我不会安心的。你能帮助我吗，？","小武哥儿"},
[1784] = {"圣洁之书","从盔枕湖附近的黑铁矮人那里取回一份黑铁手稿，把它交给铁炉堡的穆里顿·热炉。","在我陷入苦战以前，我和穆里顿在那座小房子附近几乎干掉了一个黑铁间谍。我们亲眼看见他们的头儿给他一条手令，于是我们就想把他干掉，然后抢到那条手令。铁炉堡议会里的一些家伙还不相信丹莫罗有黑铁矮人的存在。只要能得到那条手令，我们不仅能证实他们的确在这个地区活动，还能知道他们到底想要做什么。去拿到那份手令，然后把它交给穆里顿，。","小武哥儿"},
[1785] = {"圣洁之书","与铁炉堡的蒂萨·热炉谈一谈。","我的妻子正在那里骄傲地微笑，你最好快过去和她谈谈，我想她有些话要和你说。圣光会保佑你的，伟大的<职业>。相信有一天，我会邀请你一起来对抗亡灵天灾和那些该死的黑铁矮人。","小武哥儿"},
[1786] = {"圣洁之书","把生命符记带到艾尔文森林的英烈碑去，复活亨兹·法奥克。","亨兹和我去了英烈碑，那地方就在艾尔文森林东北的石碑湖中央的一座小岛上。我们听说迪菲亚盗贼在边境一带搞间谍活动，就受命去找到证据交给国王的顾问。我们看见两个人在鬼鬼祟祟地阅读什么文件，就向他们发起了突袭。这时突然出现了很多法师将我们团团包围。亨兹为我拖住了他们，让我先逃脱了……这个傻瓜，他为什么要那么做……我的兄弟亨兹，他的尸体现在还躺在那里。你能帮助我们吗，？","小武哥儿"},
[1787] = {"圣洁之书","从石碑湖小岛上的迪菲亚巫师手中拿到迪菲亚手稿，把它交给暴风城的贾森·坦诺姆。","我们以后再来谈生命符记的事情吧，现在最重要的是把那份迪菲亚盗贼阅读过的文件拿回来。如果能得手的话，我们就能证明迪菲亚盗贼混入艾尔文森林了，甚至还有可能了解到他们的计划是什么。你觉得你有能力把这些文件从这座小岛上的迪菲亚盗贼手里拿过来吗？如果你拿到文件的话，就把它交给贾森，顺便告诉他我现在没事了。","小武哥儿"},
[1788] = {"圣洁之书","与暴风城的达索瑞恩·拉尔谈一谈。","在达索瑞恩看过这份文件之后，我会把它交给国王的顾问，不过你现在应该去和达索瑞恩谈谈。他一定会表扬你的！再次感谢你，。我希望我们还能见面。有你这样的朋友绝对是我的骄傲与荣幸。","小武哥儿"},
[1789] = {"生命符记","","","小武哥儿"},
[1790] = {"生命符记","","","小武哥儿"},
[1791] = {"捕风者","和捕风者巴斯拉谈一谈。","现在既然你已经学会了狂暴姿态，就应该去弄一把称手的武器。去和捕风者巴斯拉谈谈吧，他是住在奥特兰克山脉和西瘟疫之地之间一个巨魔隐士。他是制造武器的行家，也是一个强大的萨满祭司。去找到巴斯拉，沿着塔伦米尔东侧的河流一直向北——巴斯拉的营地就在这条河东岸的废墟旁。","小武哥儿"},
[1792] = {"旋风武器","","","小武哥儿"},
[1793] = {"勇气之书","","","小武哥儿"},
[1794] = {"勇气之书","","","小武哥儿"},
[1795] = {"誓缚","召唤地狱猎犬并打败它，然后把阴谋之书交给棘齿城的斯坦哈德·法尔杉。","如果你已经做好了充足的准备，那么我们就开始吧。首先让我来解释一下整个过程。第一步是创造出基本的召唤法阵，然后，我的助手将使用导能魔棒来将其强化成为更加强大的法阵。当以上这些工作都完成之后，由你来诵读阴谋之书上的咒语，召唤地狱猎犬。$n，你要当心。地狱猎犬可是非常强大的生物，我希望你能保护好自己。","小武哥儿"},
[1796] = {"魔化金线血袍","将奥法之袍交给贫瘠之地的梅纳拉·沃伦德。","我要帮你制作的第一件装备就是长袍，你要负责为我收集若干材料，然后我会把它们组合到一起。这样你就将拥有有首件能使你变得更加强大的装备。首先，你必须给我拿来一件奥法之袍。你可以去找个裁缝帮忙制作，也可以从其他冒险者手中购买——当然如果你能自己制作的话就更好了。但是无论如何，你要先把奥法之袍交给我，然后我们才能开始。","小武哥儿"},
[1798] = {"寻找斯坦哈德","与贫瘠之地的斯坦哈德·法尔杉谈一谈。","是该教你召唤地狱猎犬的时候了，$n。但我现在手里没有教你这个法术所必需的材料，所以你得去找另外一个人来教你，也就是斯坦哈德·法尔杉，他是我们我们的另一个成员。他就住在地精港口城市棘齿城附近。在你到达之前，我会通知他你要过去的。","小武哥儿"},
[1799] = {"宝珠碎片","在棘齿城外的塔里与梅纳拉的侍僧们谈话，选择自己修行的方式。然后给尘泥沼泽的塔贝萨带去一颗地狱火珠。","很好，那么我们开始吧。首先，你必须到里面去跟我的助手们谈谈，然后决定自己要走哪条路——他们会给你更详细的解释。然后，你必须到凄凉之地的玛诺洛克集会所去，从那里的某个术士身上找到一颗地狱火珠。你要净化这颗宝珠，隐居在尘泥沼泽南部的一个名叫塔贝萨的法师会帮你完成净化。她肯定会帮助你，因为我们曾有共同的过去。我再强调一次，这些任务没完成之前，你就别回来见我。","小武哥儿"},
[1800] = {"洛丹伦的王座","带着你看护的孤儿去幽暗城电梯外的王座大厅。","在我们很听话的时候，孤儿院院长就会给我们讲述许多伟大的故事，其中的一个就是关于洛丹伦的陷落，以及邪恶的阿尔萨斯是如何杀死自己的父亲来夺取政权的。他这样做真是太无耻了，！等我成长为强大的部落战士之后，我将为荣誉而战——而不是为了邪恶的权力！你愿不愿意带我去洛丹伦的王座看看呢？王座就在你进入幽暗城之前的那个大厅里。","小武哥儿"},
[1801] = {"阴谋之书","和幽暗城的约拉·安尼森谈一谈。","要召唤地狱猎犬并迎接它的挑战，一个简单的召唤法阵是不够的。我和三个侍僧可以帮你制造法阵，但是你需要一本《阴谋之书》。很久以前我们就把这本书给弄丢了，它是由最早的那批不借助任何外力帮助就召唤出地狱猎犬的术士写下的。也许约拉·安尼森能帮你的忙。这段时间里，他作为一名制图师受雇于幽暗城，在古籍方面他知道的比我多。","小武哥儿"},
[1802] = {"阴谋之书","为铁炉堡的克罗姆·粗臂找回发霉的书籍和破损的手稿。","它是丢了，不过我知道一些可以帮你找到它的线索。这本书的复制品只有一本，而且它也已经被损坏了，很大一部分的书页全都被撕了下来，现在听说它们落入了千针石林的半人马手里。其余的部分在南海镇的西岸丢失了，原本这些书页是要用船送往米奈希尔港的，不过却从来也没能送到。你看，我告诉了你这么多消息，好歹你也得在找回东西以后拿来给我看看吧？","小武哥儿"},
[1803] = {"阴谋之书","给幽暗城的约拉·安尼森带回发霉的书籍和破损的手稿。","啊！你果然是个品位与我相当的术士呀。事实上，能得到阴谋之书一直是我的一大心愿。你知道那本书一度曾被保存在洛丹伦城里吗？然而，那本书如今已经被摧毁了，大部分的书页都不见了。到底是哪个白痴干出这样可憎的事？据说，失落的那一半目前在千针石林中的一群半人马手里。剩下的另一半本来是要被转移到铁炉堡去的，不过在押运过程中丢失在了南海镇西部的海滩上。","小武哥儿"},
[1804] = {"阴谋之书","将翻修过的书籍和3根导能魔棒交给棘齿城的斯坦哈德·法尔杉。","唉……我真是恨不得一辈子都抱着这本书。不过既然这是你找到的，而且你还要用它做更重要的事，我还是把它还给你吧……不过，请你一定要告诉斯坦哈德帮我抄写一本。对了，你去找书的时候，他托人带了个消息过来，让我告诉你说他的助手要协助进行召唤，不过你必须帮他找到3根导能魔棒。斯坦哈德可能不知道要到哪里去找导能魔棒，不过我碰巧知道！龙喉氏族的兽人法师们手上应该还有一些这种魔棒。","小武哥儿"},
[1805] = {"阴谋之书","将翻修过的书籍和3根导能魔棒交给棘齿城的斯坦哈德·法尔杉。","这书上写的东西是我这几年中看过的文章里最有趣的。这边的书很少，选择也很少——大多数的书都是地理方面的——而且，我都把它们翻来覆去地读了好些遍了。我真希望斯坦哈德能抽空给我也送一本这样的书来。去和他谈谈吧，他在你离开的时候托人给我带来了口信，说是要交给你一个任务，要求你找回三根召唤魔棒。当然，为了答谢你允许我继续看这本书，我告诉你一个小秘密：你可以在湿地的兽人龙喉氏族那里找到你要的东西。","小武哥儿"},
[1806] = {"正义试炼","等待乔丹·斯迪威尔为你铸造武器。","我们现在就到熔炉边上去开始工作吧！我已经为你的到来准备很久了，现在不用再等了。在我们完成这把武器之后，你就可以更好地为圣光而战，这一点我绝对可以保证。说实话，，看到你所取得的这些成绩，我真有点羡慕。不过我知道我也可以用我自己的方式给你提供一些帮助，这样就已经让我很高兴了。","小武哥儿"},
[1818] = {"迪林格尔","和布瑞尔的亡灵卫兵迪林格尔谈一谈。","亡灵卫兵迪林格尔告诉我有一份工作可以交给像你这样的<职业>。如果你想要为黑暗女王效力的话，那就马上去迪林格尔那边报到吧。亡灵卫兵迪林格尔在布瑞尔最西边执勤，就在墓地的旁边。","小武哥儿"},
[1819] = {"切割者奥拉格","杀死切割者奥拉格，然后和亡灵卫兵迪林格尔谈一谈。","当亡灵天灾席卷提瑞斯法林地的时候，我们曾经抓住他们中的一员进行研究。他具有自己的意志，并自称为切割者奥拉格。但是，虽然他的意志是自由的，但他仍然只是一个被巫妖王掌控和奴役着的傀儡。我们希望能够让他脱离巫妖王的控制，但是失败了。现在，我看是时候让他彻底地“解脱”了。让他解脱，杀了他。激活北部陵墓那里的颅骨石机关，解除奥拉格身上的魔法封印。然后……做好准备，。","小武哥儿"},
[1820] = {"库勒曼","和库勒曼·法席恩谈一谈。","你已经向黑暗女王证明了自己的价值，现在你应该有资格继续完成她下达的其它任务了。库勒曼·法席恩正在征召可以帮助他对付敌人的勇士。你可以在布瑞尔东部的恐惧之末旅店找到他。","小武哥儿"},
[1821] = {"阿加曼德家传武器","把阿加曼德家传长剑、阿加曼德家传战斧、阿加曼德家传钉锤和阿加曼德家传匕首交给库勒曼·法席恩。","在我活着的时候，阿加曼德家族是我的主人，但他们也是让我死去的罪魁祸首！现在他们得到了应有的报复，阿加曼德家族已经成为了巫妖王手下的行尸走肉。现在我要剥夺他们最后的荣耀。到他们家族的墓地里去，帮我抢来他们的传家之宝：一把剑，一柄斧，一柄匕首，还有一把钉锤。将这些东西全都给我拿来！阿加曼德家族墓穴就在阿加曼德磨坊的最北端，那里有许多亡灵天灾的部队和死去的阿加曼德族人守卫着。","小武哥儿"},
[1822] = {"祖传武器","","","小武哥儿"},
[1823] = {"和鲁迦交谈","和鲁迦·狂暴图腾谈一谈。","作为一名战士，你已经具备了相当的素质，而且名望也日渐显赫。也许你已经准备好要接受鲁迦·狂暴图腾的试炼了？如果是这样的话，就去贫瘠之地的陶拉祖营地找鲁迦吧。他一直以来都在那里等待英勇的战士响应他的召唤。","小武哥儿"},
[1824] = {"巨人旷野的试炼","收集5根颤抖的触角，把它们带给贫瘠之地陶拉祖营地的鲁迦。","要通过试炼，你必须一直向南到巨人旷野去，在那里有一大群叫做异种蝎的昆虫生物。我以前从未在贫瘠之地看到过这种生物，也不知道它们的到来究竟预兆着什么。把它们的触角交给我，，要刚刚割下来、还再抽搐的那种。不要浪费时间，因为一旦你把触角割下来，它们很快就会彻底失去活力。在规定的时间内把触角带给我，这样你就通过了考验。","小武哥儿"},
[1825] = {"和索恩格瑞姆交谈","与贫瘠之地的索恩格瑞姆·火眼谈一谈。","著名的兽人铁匠索恩格瑞姆·火眼已经听说了你为部落作出的杰出贡献。他愿意为你制作一套护甲，马上去找他谈谈吧。索恩格瑞姆的营地就在贫瘠之地十字路口的东边。","小武哥儿"},
[1838] = {"野蛮护甲","为索恩格瑞姆收集15根烟雾铁锭、10份蓝铜粉、10块铁锭和1瓶燃素。","我听说了关于你的英勇事迹，所以希望能为你制作一套护甲，这能够帮助你去为部落作出更多更伟大的贡献。但是制作这样一件护甲需要你的帮助，，如果你能帮助我，那你也就帮助了部落里所有的铁匠。拿着这个卷轴，这是我经过无数不眠之夜，强睁着我半瞎的眼睛写下的，上面记载着制作护甲所需要的材料。把卷轴上所列出的材料帮我找来，我会为你制作一套护甲。","小武哥儿"},
[1839] = {"尤拉莱克和野蛮护手","与杜隆塔尔的尤拉莱克谈一谈。","巨魔铁匠尤拉莱克会为你铸造一副野蛮护手，他住在杜隆塔尔的森金村里，那儿是暗矛氏族的家园，他正在等着你。","小武哥儿"},
[1840] = {"奥姆·石蹄和野蛮头盔","和雷霆崖的奥姆·石蹄谈一谈。","奥姆·石蹄因为他杰出的铸造技术而被大家尊敬，他会为你铸造野蛮头盔。你可以在雷霆崖找到他，他就在城市中心最大的那根图腾旁的池塘附近。","小武哥儿"},
[1841] = {"维罗拉·奈特雷和野蛮腿甲","与幽暗城的维罗拉·奈特雷谈一谈。","在死亡之前，维罗拉·奈特雷曾是洛丹伦最好的铸甲师。看来死亡让她的技艺退步了许多。去和维罗拉谈谈——她会帮你铸造野蛮腿甲。维罗拉住在洛丹伦的幽暗城里，你可以在贸易区找到她。","小武哥儿"},
[1842] = {"萨特之蹄","收集7只完整的萨特之蹄，把它们交给杜隆塔尔森金村的尤拉莱克。","我可以为你铸造一副具有很强魔法力量的野蛮手套。但是首先，你必须先替我去收集这样的魔法力量。为了获取这片森林的力量，许多萨特聚集在灰谷的东北面，它们在那里贪婪地吸取和破坏着森林的力量。你可以从它们肿胀的蹄子上判断出到底是哪些萨特在吸取灰谷的魔力。这些蹄子都有不小的魔法力量，把它们给我带来，这样我就可以给你铸造野蛮手套了。","小武哥儿"},
[1843] = {"野蛮护手","","","小武哥儿"},
[1844] = {"奇美拉之角","把光滑的奇美拉角交给雷霆崖的奥姆·石蹄。","我会帮你铸造头盔，但是你必须向我证明你值得我这么做。石爪山的西北面是一个名叫焦炭谷的山谷，那里曾经是一片郁郁葱葱的森林，但是现在已经被完全被污染，那里剩下的生物也都被痛苦和绝望逼疯了。现在我就要派你去那里，。你必须去焦炭谷找到雌奇美拉，杀死她，让她从苦痛中得到解脱，把她那光滑的奇美拉角带给我作为你完成任务的证据，然后我就会为你铸造头盔。","小武哥儿"},
[1845] = {"野蛮头盔","","","小武哥儿"},
[1846] = {"龙喉胫骨","给幽暗城的维罗拉·奈特雷带去12根结实的龙喉胫骨。","要铸造野蛮腿甲，我就需要一些结实的胫骨。湿地里的龙喉兽人就有非常合适的胫骨，我就需要那样的。但是你一定要确保胫骨是绝对牢固的，在你收集它们的时候记得要试一下它们是不是足够牢固：如果你能徒手把它们弄碎，那么它们肯定不符合我的要求。","小武哥儿"},
[1847] = {"野蛮腿甲","","","小武哥儿"},
[1848] = {"野蛮锁甲","","","小武哥儿"},
[1858] = {"碎手氏族","偷来塔赞的钥匙，用它打开他的背包，然后将里面的物品交给奥格瑞玛暗影裂口的瑟祖克。","你得去想办法把塔赞的包给弄开，这样咱们才能把里面的东西拿出来。这锁的结构还真挺复杂的，所以你想要弄开它的话就只能靠钥匙了。如果你没有在塔赞的尸体上找到钥匙，那他就一定把钥匙放到某个安全的地方去了……啊，对了！他有一个助手叫加摩尔，是个彻头彻尾的大酒鬼，你八成能在酒馆里找到这家伙。我建议你“安静地”把钥匙从他手里搞来。","小武哥儿"},
[1859] = {"瑟祖克","到奥格瑞玛的暗影裂口和瑟祖克谈谈。","小声点，。没错，我知道你叫什么。有人让我注意一个兽人，你完全符合他的描述。我们听说你在战斗中颇有一套，有时也会使用一些非常的手段。我没说错吧？不管怎样，你得去见见奥格瑞玛的瑟祖克，他有事要吩咐你。","小武哥儿"},
[1860] = {"和詹妮亚交谈","和暴风城的詹妮亚·坎农谈一谈。","我们法师有一项任务要交给你去完成，一项对于暴风城和艾尔文森林的安全至关重要的任务。詹妮亚·坎农会告诉你任务的细节。她正在暴风城的法师区里的巫师圣地里学习，你最好尽快找到她。","小武哥儿"},
[1861] = {"明镜湖","把一份明镜湖水的样本交给暴风城的詹妮亚·坎农。","大规模的魔法战争已经使得原本稳定的魔法流开始出现异常的波动。我们正在努力调查这种波动究竟会造成怎样的影响，而有些人已经做好了最糟糕的打算！但是现在还不能轻易下结论，我们们要派你去收集更多的信息。拿着这个水袋，到艾尔文森林明镜湖瀑布的底部收集那里的水样，然后把水样给我带回来，这样我就可以用它来进行魔法污染情况的研究了。","小武哥儿"},
[1878] = {"收集水袋","","","小武哥儿"},
[1879] = {"和彬克交谈","和铁炉堡的彬克谈一谈。","！我在铁炉堡的侏儒同事彬克送话过来说，她有一项必须交由某个法师来完成的任务！你不正好是个法师吗，？如果你愿意的话，去和彬克谈谈吧。她就在铁炉堡秘法区的秘法大厅里。","小武哥儿"},
[1880] = {"法师文档存储器","帮彬克找回她的法师文档存储器。","我们法师能做的事情可不仅仅是弹动一下手指变出美丽的火花那么简单！我们控制着魔法，控制着构建这个世界的源泉！当然，这需要极大的决心和极强的能力，还有知识……足够多的知识！我发明的一台设备——法师文档存储器——里面存储着无数的知识。不过问题是，我把它弄丢了！当我们逃离诺莫瑞根的时候，我把它留在城外一座小屋的箱子里，现在那地方麻疯侏儒横行！，请帮我取回我的法师文档存储器！","小武哥儿"},
[1881] = {"安娜斯塔西娅","和安娜斯塔西娅·哈特威尔谈一谈。","，安娜斯塔西娅·哈特威尔有个任务需要你这样有才干的<职业>来完成。她就在幽暗城的魔法区，去和她谈谈，准备为被遗忘者的法师们完成你的第一个任务吧。","小武哥儿"},
[1882] = {"巴尼尔农场","将巴尼尔金鱼草交给幽暗城法师区的安娜斯塔西娅·哈特威尔。","东边的瘟疫之地处于混乱的状态。巫妖王控制下的天灾军团将邪恶的魔法灌入土地之中，腐化并杀死那里的一切生灵。虽然瘟疫具有强大的破坏力量，但是我们——被遗忘者的法师——相信它必定可以被清除掉。首先，我们必须判断出它在提瑞斯法到底散播到了怎样的程度。到提瑞斯法东部的巴尼尔农场去，在那里的花园中收集一些金鱼草，然后再回来。","小武哥儿"},
[1883] = {"安苏瓦","和安苏瓦谈一谈。","森金村的部落法师安苏瓦发现杜隆塔尔的魔法流出现了波动，为此他向我寻求帮助。去和安苏瓦谈谈，尽你所能去帮助他。快去吧，到时一定会有更多的秘密展示在你的面前。","小武哥儿"},
[1884] = {"魂能骨堆","摧毁4个魂能骨堆，然后向森金村的安苏瓦汇报。","回音群岛的术士扎拉赞恩扰乱了杜隆塔尔的魔法流。他那些邪恶的魂能骨堆就是造成这一切的罪魁祸首，他把那些骨堆放在回音群岛的主岛上。骨堆破坏了我们的生活，还让在黑暗角落里隐藏着的术士和恶魔获得源源不断的力量。你必须在魔法流被彻底改变之前摧毁那些魂能骨堆，。","小武哥儿"},
[1885] = {"米奈特·卡加德","与幽暗城盗贼区的米奈特·卡加德谈一谈。","$n？虽然现在的情况并不像我所预计的一样，但卡加德确实对你非常感兴趣。听起来是不是有点难以置信？无论如何，你得尽快去找他谈谈。我想你并不想知道上一个对他的召唤置之不理的人的下场吧。","小武哥儿"},
[1886] = {"亡灵哨兵","得到阿斯托的介绍信，并将其交给盗贼区的米奈特·卡加德。","想加入瓦里玛萨斯大人的精英卫队——亡灵哨兵的话，你首先必须证明自己的价值。坦城地说吧，$n，你很可能在这种证明自己价值的任务中丧命，所以我劝你最好三思而行。现在，我有一个任务要你去完成。有一位来往于银松森林与幽暗城之间的信使，他叫阿斯托·哈德恩，由于特殊的公务需要，我必须得到他身上的一些私人物品。至于采用怎样的策略去得到这些物品，那是你的事情，不要问我。如果你的好奇心能小一点，不那么关心这些物品的用途的话，你会过得更自在一些。完成这个任务之后，我会再和你谈的。","小武哥儿"},
[1898] = {"亡灵哨兵","与幽暗城的安德隆·甘特交谈。","这封介绍信足以使安德隆认为你就是他正在等的那位信使。我之前已经见过安德隆了，估计以他那点脑子是根本不会怀疑你的。瓦里玛萨斯大人怀疑安德隆正在为某些其他的组织提供援助。他想知道那是个什么组织，而且你要收集到充分的证据。我要求你在与安德隆的谈话中把这些信息都给套出来，他的店就在炼金房旁边。","小武哥儿"},
[1899] = {"亡灵哨兵","将阿斯托的的账本交给幽暗城盗贼区的米奈特·卡加德。","你在我背后的书架上就可以找到记有你的主子最需要的信息的账本。把它交给他们，记得代我问他们好。哦，还有，告诉他们，如果他们觉得与我合作确实不错，并且还打算按日程继续合作下去的话，他们最好还是派你来。","小武哥儿"},
[1918] = {"被污染的水元素","将被污染的水球交给灰谷碎木哨岗的马斯托克·维尔西斯。","被毁灭的水元素留下了一颗水球，它令你感到极端的厌恶，仿佛污染密斯特拉湖的所有物质都包含在这颗水球中一样。你不清楚谁会对这个感兴趣，不过碎木哨岗的马斯托克·维尔西斯——那个最初派你来这里的家伙——也许对此有所了解。","小武哥儿"},
[1919] = {"向詹妮亚报告","和暴风城的詹妮亚·坎农谈一谈。","你的能力正在不断地增强，年轻的。你准备好要接受真正的挑战了吗？你愿意加入到我们正在进行的这场秘密战争之中吗？如果你愿意的的话，就去和詹妮亚·坎农谈谈吧，她在暴风城法师区的巫师圣殿里。她有一项任务要交给你，这将帮你打开通向那个秘密世界的第一扇窗。","小武哥儿"},
[1920] = {"调查蓝色隐士","从詹妮亚·坎农身后拿取一根显形卷轴以及一盒封灵箱。将3个装满的封灵箱交给巫师圣殿里的詹妮亚·坎农。","有报告称，法师区的蓝色隐士旅店里出现了异常的魔法波动。一些隐形的奇怪生物徘徊在旅店里，我担心那里已经有了一道魔法裂隙。我希望你去调查一下旅店，捕获那些生物。用旅店中的显形卷轴让它们现出原形，然后用封灵箱抓住它们。当你抓到足够数量的隐形生物之后，就带上装满了的封灵箱和显形卷轴回到我这里来。","小武哥儿"},
[1921] = {"收集原料","把10匹亚麻布和6颗充能裂隙宝石交给暴风城的维恩·拉尔森。","你帮了你的法师同行们很多忙，现在是为你制作巫师长袍的时候了。维恩·拉尔森可以帮你这个忙，不过你必须把必需的原料交给她。制袍用的亚麻布很容易找到，不过你还必须得到充能裂隙宝石，唯一出产这些宝石的地方是在洛克莫丹的银泉矿洞，它们大多被密封在矮人矿工协会的箱子里。收集好亚麻布和宝石之后，把它们交给法师区拉尔森服装店里的维恩·拉尔森。","小武哥儿"},
[1938] = {"乌尔的暗影魔法研究论文","将《乌尔的暗影魔法研究论文》交给暴风城的高阶巫师安多玛斯。","很久以前，三个法师在暴风城里一起学习法术，直到其中的一个开始研究黑暗魔法。他原本并不想深入其中，但是却发现自己在不经意间越陷越深。最终，他被放逐出了暴风城。这个被放逐的法师就住在赤脊山的伊尔加拉之塔中，他手中有一本强大的魔法书——《乌尔的暗影魔法研究论文》。我们这些暴风城的法师希望能把那本书拿回来。你要做的就是溜进伊尔加拉之塔，帮我们取回那本书。","小武哥儿"},
[1939] = {"高阶巫师安多玛斯","和高阶巫师安多玛斯谈一谈。","高阶巫师安多玛斯希望和你谈谈，。他就在暴风城法师区的高塔顶端。能去和他会面可是非常难得的机会，因为安多玛斯是少数几个没有被困在达拉然的超强的大法师之一，他找你也一定是有非常重大的事情。","小武哥儿"},
[1940] = {"新鲜的蜘蛛丝","找到8束新鲜的蜘蛛丝，把它们交给暴风城的维恩·拉尔森。","你一直在帮助我们，。我想，也许你应该换一件好点的长袍了，一件更适合资深法师地位的长袍。如果你能收集到必需的原料，我们就帮你做一件新的长袍。你必须进入暮色森林，猎捕那里的食腐独行蛛。抽出它们的丝，但只有最好的、最纯的丝才行。你得到足够的蛛丝后，就把它们交给维恩·拉尔森来帮你缝制长袍，她就在法师区的拉尔森服装店里。","小武哥儿"},
[1941] = {"法力之纹长袍","","","小武哥儿"},
[1942] = {"星结之衣","","","小武哥儿"},
[1943] = {"巨魔法师迪诺","和迪诺谈一谈。","，巨魔法师迪诺需要你的帮助，她就住在奥格瑞玛的暗木小屋里。","小武哥儿"},
[1944] = {"克萨维亚之水","将克萨维亚水样交给奥格瑞玛的迪诺。","传说中的克萨维亚城位于灰谷的东部，据说在那里可以找到所有智者都渴望获得的古代知识，而克萨维亚之水也具有超强的魔法力量。我需要一些克萨维亚之水——要从水源直接取得的那种。拿着这只瓶子，去寻找传说中的克萨维亚城吧。从那里最高的瀑布底部收集水样，然后把它交给我。在那里你要步步小心，萨特占领了整个遗迹，它们一定不会喜欢让多事的法师侵入它们的领地。","小武哥儿"},
[1945] = {"欢笑的姐妹","给十字路口的基尔哈拉带去12缕欢笑姐妹的头发。","我已经把为你制作新袍子的事情安排妥当了，就等你来提供一些材料……我需要一些头发来制作你的法袍，你应该可以在灰谷的树妖身上弄到符合条件的头发，那些树妖们都聚集在林中树居那里。当你找到足够的材料之后，就把它们交给贫瘠之地十字路口的基尔哈拉，他是一个巨魔裁缝。他正等着为你制作最新款的法袍。","小武哥儿"},
[1946] = {"虚灵长袍","","","小武哥儿"},
[1947] = {"沼泽之旅","和塔贝萨谈一谈。","现在，是让你得到自己的法师魔杖的时候了。首先，你得去和住在尘泥沼泽的人类隐者塔贝萨谈一谈。你可以在沼泽深处找到她的小室，那地方就在塞拉摩的西边，石槌废墟的北边。去和她谈谈，她的知识非常渊博。","小武哥儿"},
[1948] = {"强大的物品","将电能草莓和1颗翡翠交给尘泥沼泽的塔贝萨。","铸造一根法师的魔杖并不容易。我们需要一些珍贵的材料，而且必须制作一个能储存大量魔法能量的容器——这些事情就交给你了。我已经把要你去找的东西写在这张羊皮纸上了，把上面列着的东西交给我，另外你一定要按照羊皮纸上的指示行事。如果你不听从我的指示擅自决断的话，我们铸造魔杖时就可能会有……大麻烦。","小武哥儿"},
[1949] = {"隐藏的秘密","和闪光平原的大法师提尔斯谈一谈。","为了制作你的魔杖，我得查询一本书里的一些关键段落。这本书叫做《能量仪祭》，是大法师提尔斯写的。我没有这本书，世界上所有的大图书馆也没有收藏。你必须去和提尔斯谈谈，从他那里要一本来。祝你好运。提尔斯曾经是个伟大的法师和学者，不过他现在把时间都花在饮酒、赌博，还有去闪光平原观看侏儒与地精的车赛上了。","小武哥儿"},
[1950] = {"解封咒语","找到提尔斯保险箱的解封咒语，然后向提尔斯复命。","我可以给你书，但你得先帮助我！你要找的书被锁在我的魔法箱里了。必须念出一些咒语才能打开它，但是我忘记这些咒语了！通常都是我的助手帮我记这些事情，但现在他也不知道跑哪里去了。如果你想要我的书，那就得先找到我的学徒！到赛车道周围去问问——如果幸运的话，会有人知道他在哪里的。要么把他给我带回来，要么从他那儿问到咒语，不然就别想打开我的箱子！","小武哥儿"},
[1951] = {"能量仪祭","将《能量仪祭》交给尘泥沼泽的塔贝萨。","嗯……我想起来了，我的书已经没有了！你要知道，我欠了一屁股的债，不得不把最后一册《能量仪祭》卖掉来还债，我把它卖给了一个牧师……他是血色十字军的成员。他一定把那本书带到了他们的根据地——提瑞斯法林地里的血色修道院图书馆去了！如果你想要那本书的话，就得去一趟修道院。很抱歉给你带来这么多麻烦，这些天我已经有些头昏脑涨了……","小武哥儿"},
[1952] = {"法师的魔杖","等塔贝萨的仪式完成后，和她谈一谈。","我现在要去铸造魔杖了。","小武哥儿"},
[1953] = {"返回沼泽","和塔贝萨谈一谈。","，是时候让你去和塔贝萨谈谈了……这位尘泥沼泽里的隐士将指导你如何铸造强大的法师物品。塔贝萨就隐居在尘泥沼泽的深处，塞拉摩的西边。","小武哥儿"},
[1954] = {"地狱火宝珠","将一颗地狱火宝珠交给尘泥沼泽的塔贝萨。","首先，我们必须弄到一颗有魔力的宝珠。火刃氏族的术士有高质量的宝珠……糟糕的是，他们将恶魔收入了宝珠里！当然我们可以解决这个问题，对……我们可以。到凄凉之地去，从火刃召唤师那里夺取一颗地狱火宝珠。那帮家伙通常在玛诺洛克集会所活动。拿到宝珠之后就尽快返回我这儿来。","小武哥儿"},
[1955] = {"驱除魔鬼","杀死宝珠之魔，然后与塔贝萨谈一谈。","既然我们已经得到了召唤师的宝珠，现在就让我们来把恶魔从里面驱赶出来。我能做到，这部分相当容易。我有个艰巨的任务给你，你必须在恶魔出现的时候杀死它。而且动作要够快。如果你耗时过久的话，或许它就会再跳进去，那我们又得重来一次了！所以你得准备好最强的技能和所有的物品，如果你有朋友的话，也一起叫上。这件事情不会很轻松的。","小武哥儿"},
[1956] = {"奥达曼的能量源","找到一个黑曜石能量源，将其交给尘泥沼泽的塔贝萨。","既然恶魔已经被消灭了，接下来我们就得去找一个能量源。不幸的是，最合适的能量源往往非常古老而且极难获得。有的时候，命运就喜欢这样捉弄你，难道不是吗？所以，为了得到能量源，你必须到奥达曼去打败那里的黑曜石守卫。他体型巨大而且很难对付，但是你可以从他身上得到我们所需要的能量源！祝你好运，。如果你运气不好的话，那么……很高兴认识你。","小武哥儿"},
[1957] = {"法力怒灵","在限定时间内杀死12只法力怒灵。","我们几乎已经要大功告成了，但是最后一步也是最危险的，。我有一颗空的召唤宝珠，准备给它注入力量。我们将通过一道魔法裂缝来完成这个步骤，首先，我会念一段咒语来打开裂缝，此时特殊的生物——法力怒灵将大量涌出来。你必须打败这些生物以释放它们的能量，我会及时用宝珠收集这些能量。在裂缝关闭之前杀死足够多的法力怒灵，我会把所有收集起来的能量注入你的宝珠。","小武哥儿"},
[1958] = {"苍穹之力","","","小武哥儿"},
[1959] = {"向安娜斯塔西娅报告","和安娜斯塔西娅·哈特威尔谈一谈。","幽暗城的法师们注意到城里出现了一股魔法波动，他们随即发出消息，请求部落的法师来协助他们进行调查。安娜斯塔西娅·哈特威尔会告诉你更多的详细内容，她就在幽暗城的魔法区，去和她谈谈吧。","小武哥儿"},
[1960] = {"调查炼金店","从安娜斯塔西娅·哈特威尔身后拿取一根显形卷轴以及一盒封灵箱。将3个装满的封灵箱交给幽暗城的安娜斯塔西娅·哈特威尔。","在炼金房的奥格诺恩炼金店里有一股奇怪的魔法波动。由魔法能量构成的隐形生物在商店里四处游荡，这其中一定有什么原因，我们必须找到它！我希望你去调查一下，捕获那些生物。用我身后的显形卷轴让它们现出原形，然后用封灵箱抓住它们。当你抓到足够数量的隐形生物之后，就带上装满了的封灵箱和显形卷轴回到我这里来。","小武哥儿"},
[1961] = {"收集原料","把10块亚麻布和6块达拉然法力宝石带给乔瑟夫·格里高利。","，是时候为你制作你的第一件法师袍了。那会是你地位的标志，同时也是对你的一次考验。你必须从银松森林的达拉然法师身上获得制作法袍所必需的法力宝石。那些法师和我们拥有相似的信仰，所以杀掉他们会是一件让人感到不快的事情，但是既然他们不具备抵御我们的力量，那他们也就没有继续存活下去的价值了。把宝石和亚麻布交给法师区裁缝店里的乔瑟夫·格里高利，他会为你制作你的第一件法师袍。","小武哥儿"},
[1962] = {"魔焰长袍","","","小武哥儿"},
[1963] = {"碎手氏族长","杀死塔赞，把他的背包带给奥格瑞玛暗影裂口的瑟祖克。","酋长行事的方法实在是有些太谨慎了。他总是很小心地不让部落显得过于锋芒毕露。一旦我们足够强大了，我们的力量将能征服一切。部落必须重现往日的荣耀和尊严，而现在看来能做到这一点的就只有我们碎手氏族了。我们必须在暗中积蓄力量，再突然向敌人发起致命的打击，神不知鬼不觉地将敌人除掉。如果你想加入我们，就必须先为我完成一个任务，以此来证明你自己的价值。有个名叫塔赞的巨魔在棘齿城附近和海盗们做交易，而他那里有我感兴趣的消息。杀了他，把他的背包拿来给我。","小武哥儿"},
[1978] = {"亡灵哨兵","将安德隆的账本交给幽暗城黑暗女王大厅里的瓦里玛萨斯。","辛迪加？我竟然从来都没有想到是他们，看来奥特兰克的那些贵族们自从背叛联盟以后真是愈加堕落了。瓦里玛萨斯大人知道了这些一定会非常高兴，另外，既然你在这次侦查行动中表现得这么出色，那么，就由你把我们的调查结果给他送过去吧。啊，我怎么可能忘了说这个呢！欢迎加入亡灵哨兵的行列。","小武哥儿"},
[1998] = {"芬维克·萨托斯","杀掉芬维克·萨托斯，把他的头颅交给幽暗城盗贼区的米奈特·卡加德。","瓦里玛萨斯大人刚刚给我下达了一道命令，要求我派人去把一个对我们构成巨大威胁的家伙立刻铲除掉。他的名字是芬维克·萨托斯，瓦里玛萨斯大人认为他是一群在银松森林中肆虐的亡灵的领袖。一接到这个任务，我马上就想到了你，$n。我坚信，以你的能力一定可以将这个任务轻松完成。我们派遣到银松森林的亡灵哨兵们发回的最新报告中指出，萨托斯就躲藏在洛丹米尔湖岸边的一处废弃码头上。","小武哥儿"},
[1999] = {"交易工具","找到达拉然形势报告，把它交给幽暗城盗贼区的米奈特·卡加德。","安伯米尔的肯瑞托法师那里保存着大量关于达拉然现状的文档，这些情报是我们从一个囚犯的口中拷问出来的。瓦里玛萨斯大人已经下令，要求我们必须把这些文件弄到手。于是这个任务就落到了你的肩上，$n。你需要一些装备，更重要的是得学会开锁的技术。去跟我们的工具商艾斯特蕾·根德瑞谈谈，在你出发前向她要一套开锁工具吧。","小武哥儿"},
[2000] = {"洛卡·刃影","去找杜隆塔尔的洛卡·刃影谈话。","你最近有点太悠闲了，。该是让你多学点我们的谋生技巧的时候了。就在昨天晚上，我们在奥格瑞玛的一处岩洞里发现了五个同伴的尸体，现场只留下极少的线索。这一定是我们敌人做的，竟然以我们的手法来对付我们。所以我决定派你去学习开锁这门艺术。很不幸地，这门精巧的手艺对我这双手来说并不适合。你得去找洛卡，他就住在杜隆塔尔附近的山里。尽管他已经年纪很大了，但我想他应该还是有在接触这门技艺的。","小武哥儿"},
[2018] = {"洛卡的试炼","杀死监督者格里比，把他的哨子交给杜隆塔尔的洛卡·刃影。","啊，现在瑟祖克竟然把他的小学徒送到我这儿来了，是吧？嗯，我想我还是能教你些什么的。我根本不关心你的事情，但我也不想平白无故地让你去送死。你必须先证明你自己的价值。我得告诉你，，我根本不喜欢风险投资公司。这片土地让我想起了德拉诺，所以我很讨厌那些毁了这里的地精们的想法。如果我们能干掉他们在淤泥沼泽里的监督者，他们的工程进度也许会瘫痪下来了。","小武哥儿"},
[2019] = {"交易工具","向奥格瑞玛暗影裂口的瑟祖克复命。","出发吧，。这些东西你用起来一定会很趁手。它们都是我亲手制作的，我发誓你找不到更好的了。别把你的工作告诉我，那只会让我心烦。毕竟，我对瑟祖克的计划是一点兴趣都没有了，我只希望自己能过上平静的退休生活。如果你需要一套新的工具的话，就随时回来找我，我会给你造一套新的。不过你要小心使用它们！","小武哥儿"},
[2020] = {"<UNUSED>","","Now here's the locky lock.","小武哥儿"},
[2038] = {"宾格斯的补给品", "找回宾格斯的工具：宾格斯的扳手、螺丝刀、锤子和宾格斯的爆盐雷管", "坠毁在洛克湖已经够糟了，附近岛上的石腭怪还袭击我，偷走了工具和特制的爆盐雷管。没有旋翼机和爆炸物，光复诺莫瑞根的行动就无从谈起！找回我的工具和爆盐雷管吧，冒险者。为了诺莫瑞根！", "小武哥儿"},
[2039] = {"寻找宾格斯","去洛克莫丹寻找宾格斯。","我们和宾格斯失去了联系！他被派去侦察诺莫瑞根，不过已经有足足一个星期没回来报告了。这家伙应该是失踪了。最后有人看到他时，他正在洛克湖上空飞行。你可以去那一带调查一下，。","小武哥儿"},
[2040] = {"地底突袭","从死亡矿井中带回小型高能发动机，将其带给暴风城矮人区中的沉默的舒尼。","诺莫瑞根已经被那群卑鄙懦弱的穴居人们完全占据了！情况很紧急，或许你能帮上我们的忙，。在死亡矿井深处有一台功能强大的地精伐木机，找到这台伐木机并带回它的能源供应机件。有了这台伐木机的能源供应机件，我们就能给高速钻孔挖掘机供应足够的能量，用它来钻透这里与诺莫瑞根之间的岩石。钻开一条路，给他们来一次侏儒式的突袭！","小武哥儿"},
[2041] = {"沉默的舒尼","去暴风城和舒尼谈一谈。","也许……也许你能帮我们攻打诺莫瑞根。你可以到暴风城去找秘密攻击部队的指挥官，沉默的舒尼。舒尼需要有人帮他找一些东西。你可以在暴风城的矮人区中找到她。祝你好运，。","小武哥儿"},
[2058] = {"<UNUSED>","","Kill a guy, member of the Assassins' League. He killed the old leader of the Deathstalkers.","小武哥儿"},
[2059] = {"<UNUSED>","","Well guess what, we're interested in you.","小武哥儿"},
[2078] = {"基尔卡克的报复","找到基尔卡克的大副——机械打手4100型，把他带到基尔卡克那里。","旱鸭子，你得帮忙找到我的大副。带上这把钥匙，把它插入我的大副身上的钥匙孔里，然后把他给我带回来。那些鱼人们马上就要吃不了兜着走了，因为我的大副就要回来啦！","小武哥儿"},
[2098] = {"基尔卡克的钥匙","找到基尔卡可钥匙的3段碎片，把它们交给基尔卡克·旋杆。","想要当一个出色的海盗可不简单呀，你这个旱鸭子是不会理解的。我们的生活并不仅仅只是掠夺和痛饮！唉，我的船在海岸附近被那些可恶的鱼龙给弄沉了。我希望我的大副能够重新回来工作！当我被冲到海岸的时候，大副的钥匙在岩石上折断了，接着又被黑海岸那一带的怪物给偷走了，我只记得隐约看见一些狂暴暗礁蟹、凶猛的森林陆行鸟和几个鱼人正在搜寻船的残骸……","小武哥儿"},
[2118] = {"瘟疫蔓延","活捉一只狂暴蓟熊，把它带到萨纳瑞恩那里。","一种疾病正在黑海岸蔓延，它能够控制一切与它接触的灵魂和肉体。这种瘟疫对蓟熊的影响最大，使得这种曾经高贵的动物现在几乎变成了毁灭和杀戮的机器——它们变得狂暴，完全失去了理智。我有一种方法应该可以治疗这种病。把这个陷阱放到森林的空地上。任何狂暴蓟熊经过时，都会在短时间内变得驯服。一旦蓟熊安静下来了，就上前安抚它，减轻它的痛苦（使用/soothe命令），然后它就会跟你走。把它带到这里来，。","小武哥儿"},
[2138] = {"清除疫病","到森林里去杀掉20头狂暴蓟熊。","正如我所担心的，这种疗法没有起到效果。对我来说，任何野生动物的死都是一件令我难过的事情，但是我们必须杀掉这些感染了瘟疫的狂暴蓟熊。，回到森林里去，杀掉20只狂暴蓟熊。这虽然无法驱散瘟疫，但可以在短期内降低狂暴蓟熊对这片森林和森林里的居民们带来的破坏。","小武哥儿"},
[2139] = {"萨纳瑞恩的希望","找到雌蓟熊，然后杀掉它。","，我们用惨痛的代价换取了黑海岸和奥伯丁的平安。你杀了很多早已病入膏肓的动物，减轻了森林的痛苦，也解脱了这些动物的灵魂。尽管这种状况只能持续一小会儿，但是奥伯丁的人民感谢你。我要交给你最后一项任务，请注意，这将是又一次的杀戮任务。我希望这是最后一次让你去做这样的事情，。有一只雌蓟熊住在东北方的一个靠近巴莎兰的洞穴里，杀了她。","小武哥儿"},
[2158] = {"休息和放松","和狮王之傲旅店的旅店老板法雷谈一谈。","每个冒险家在疲惫的时候都需要休息——而休息和放松的最佳去处就是狮王之傲旅店！我的好朋友法雷是那里的旅店老板。告诉他是我介绍你去的，也许他还会给你些特别优惠呢。如果你要去狮王之傲旅店的，沿着大路往南走就没错了！","小武哥儿"},
[2159] = {"多兰纳尔的货物","把药草送到旅店老板凯达米尔手中。","你好，年轻的<职业>。你能帮我一个忙吗？我有一包药草必须送到多兰纳尔去，但是现在我还要忙于处理幽影谷德鲁伊的事情，所以走不开。你能帮我把这包药带去吗？把它送到多兰纳尔旅店的老板凯达米尔那里，那座旅店就在南方的路边上。","小武哥儿"},
[2160] = {"塔诺克的补给品","给卡拉诺斯的塔诺克·霜锤带去一箱旅店补给品。","嘿！我一看就知道你是个精力充沛的冒险家。如果你要继续前进的话，能不能帮我带个包裹到卡拉诺斯的旅馆去？你应该已经计划在那个旅店里稍作休息了，对吧？我敢说只要你到了旅店，就肯定会想在那里歇一下脚。无论如何，请把这包裹带给旅馆主人的助手塔诺克·霜锤。我自己是没法活着穿越那危险的通道了，巡山人卫队还得过些天才会经过这儿，所以我只能靠你了。","小武哥儿"},
[2161] = {"苦工的重担","把乌克尔的货物交给剃刀岭的旅店老板格罗斯克。","对不起，你能帮帮我吗？我这儿有一车食物，一路上我遭遇了蝎子、蜘蛛，还有其它更可怕的东西！我把这些食物送到了试炼谷，因为我觉得他们可能会需要这个，同时我又很乐意帮助他们。但是他们居然根本就不需要食物！现在我还得把这些东西带回剃刀岭，可是我害怕路上的那些野兽……你能不能帮我送回去呢？我只是个苦工，可你是个大英雄，你一定什么都不怕！请把东西交给剃刀岭旅馆的老板格罗斯克。","小武哥儿"},
[2178] = {"炖陆行鸟","给急弯河的奥兰达利亚·夜歌带回5块陆行鸟肉。","你闻到扑鼻的香气了吗？那可是用我的秘方精心烹制的、新鲜出炉的炖陆行鸟，口感超绝，美味无比！你对我的食谱很感兴趣吧？在我告诉你食谱之前，你得证明你能对付那些动物。我可并不是要求你简单地跑出去驯服一只陆行鸟，然后骑回来见我。你得去捕杀一些陆行鸟，把它们那些多汁的肉脯带回来给我。只有这样我才会把炖陆行鸟的秘方教给你。","小武哥儿"},
[2198] = {"破碎的项链","找到破碎的项链的来源，从而了解其潜在的价值。","你找到了一条破碎的项链，但是破旧不堪的外表并不能掩饰它高超的制作工艺。项链已经破碎，原本应该镶在项链上的三块宝石不见了。在项链的内侧印有铁炉堡的徽记，旁边还刻着三个小字：“TdK”。如果你想要了解这条项链背后的故事，你就必须找到它的主人。也许那个徽记和小字就是线索……","小武哥儿"},
[2199] = {"昂贵的知识","给铁炉堡的塔瓦斯德·基瑟尔带去五块银锭。","我在铁炉堡可是鼎鼎有名的珠宝匠！好吧，我承认那是以前的我……因为一个竞争对手的污蔑让我变成现在这个样子！名声不好在这行里就根本混不下去。结果，你看，我现在就变得穷困潦倒。现在，我要你给我搞五块银锭来，这样我才能完成我手头上的这份订单——看来这是我唯一的一份订单了。你给我五块银锭之后，我就会回答你所有关于这条项链的问题。","小武哥儿"},
[2200] = {"回到奥达曼","去奥达曼寻找塔瓦斯的魔法项链，被杀的圣骑士是最后一个拿着它的人。","我的一个邪恶的竞争对手居然污蔑我，说是我制作的项链诅咒了那个圣骑士！显然没有人愿意买被诅咒的东西。不如我们来做笔交易吧：如果你能帮我找回宝石，我就能重新把它镶到项链上，然后只要你帮我宣传这条项链并没有受到诅咒，帮我恢复名誉的话，我就将把这条项链送给你！我建议你从奥达曼开始搜集线索，或许那个圣骑士的尸体就在下面，毕竟他是最后一个拥有它的人！当你找到宝石之后就使用这个东西，它可以让你随时和我进行联系。","小武哥儿"},
[2201] = {"寻找宝石","在奥达曼寻找红宝石、蓝宝石和黄宝石的下落。找到它们之后，通过塔瓦斯德给你的占卜之瓶和他进行联系。","从这个圣骑士的日记上看，只有奥达曼才有可能是项链上的那三块宝石的所在地。如果日记的描述还算准确的话，在奥达曼里有大量的暗炉矮人和石颚怪在活动。知道了这些信息之后，对宝石的搜索行动就可以开始了。当你收集到所有的宝石之后，通过塔瓦斯德的占卜之瓶和他联系来获取下一步的指示。","小武哥儿"},
[2202] = {"奥达曼的蘑菇","收集12颗紫色蘑菇，把它们交给卡加斯的加卡尔。","，我听说有一种紫色蘑菇刚刚被发现，它们似乎只在奥达曼挖掘场里生长。我需要十二个这样的蘑菇来进行炼金术的研究。你要多加小心，这种蘑菇会喷射出有毒的孢子。帮我这个忙吧，我会给你丰厚的报酬，另外还可以让你尝尝我收藏多年的好酒！","小武哥儿"},
[2203] = {"荒芜之地的材料 II","用空的魔瓶吸收荒芜之地的烈焰守护者的血液。装满所有瓶子之后，把它们交给卡加斯的加卡尔。","，你帮我了大忙了。我愿意与你分享你曾经品尝过的那种佳酿的配方……但我还要你去完成一项相当危险的任务。仔细听好我的要求。这只有锁的箱子里面装着三个空的魔瓶，它们被赋予了一种能够汲干烈焰守护者血液的魔法能量，用魔瓶收集烈焰守护者的血液是非常危险的，所以请多加小心。当你装满了三个瓶子之后，就把它们交给我。快去吧，你离那个配方只有一步之遥了。","小武哥儿"},
[2204] = {"修理项链","从奥达曼最强大的石人身上获得能量源，然后将其交给铁炉堡的塔瓦斯德。","你现在需要去为项链找到它的“精神”力量，奥达曼无疑最适合的地方。据说那里有很多的石人跑来跑去，对吗？那么，杀死他们当中最强大、最邪恶的那个石人，然后把他身上的能量源夺过来！我敢保证可以把那能量源里的能量重新注入到项链之中。如果没有那样的能量源，想要修复项链根本是不可能的。取得能量源之后尽快回到铁炉堡来找我，然后我们就能把项链完全恢复到原来的状态啦！","小武哥儿"},
[2205] = {"军情七处","把科瑞恩·塞尔留斯的包裹带给暴风城兵营的马迪亚斯·肖尔。","徽章？哦，没什么，你应付不了的。看你的样子，我敢说马迪亚斯·肖尔一定会把你当成送奶酪的$g男孩:女孩;而不是个真正的盗贼。不管怎样，我被指派了一个任务，而且我曾保证要完成这个任务。对了，说到这个，你去把这个包裹带给马迪亚斯吧，他可能会交代你去做些事情。快去吧。","小武哥儿"},
[2206] = {"连偷带抢","找到迪菲亚码头主管，从他那里为马迪亚斯·肖尔拿到迪菲亚船运时间表。","我们派在外面的探子回报说，迪菲亚兄弟会在闪金镇南部的活动相当频繁。报告中还说道，迪菲亚兄弟会控制了杰罗德码头，并利用它将大量的违禁品从赤脊山走私到西部荒野去。我要你想办法到码头旁的屋子里去一趟，把里面的船运时间表给我偷出来，那东西应该就在码头主管的衣服口袋里。……还有，，如果你的行动被发现了的话，暴风城军情七处将不会承认你的存在。","小武哥儿"},
[2218] = {"救赎之路","和铁炉堡的霍夫丹·黑须谈一谈。","又一个迷失的灵魂，是来寻找指引的么？我想你一定希望能找到目标——属于你自己的目标。像你这样的<种族>我已经见过不下一千个了，又是一个找活干的英雄！今天你运气不错，朋友，霍格拉尔可以帮你。按照我说的去做吧：沿着这条路到铁炉堡，找到被遗弃的洞穴里的盗贼公会，和霍夫丹·黑须谈谈，他会指引你一条救赎之路的。","小武哥儿"},
[2238] = {"国王的财宝","在诺莫瑞根附近找到奥宁·雨锤。","你知道，国王抢走了采集矿石宝物的机会，那些财富……矮人活十辈子也挣不到。我们在铁炉堡那里有些关系，，很有价值的关系，你懂吧？国王应该把他的财宝拿出来和我们分享，不过我们不想让那老家伙知道他正在和我们分享——你懂我的意思吧。你到诺莫瑞根附近去和奥宁·雨锤谈一谈，然后回来跟我报告。那个狡猾的矮人混迹在一群麻疯侏儒当中，你要小心点。","小武哥儿"},
[2239] = {"奥宁的报告","把奥宁的报告交给铁炉堡的霍夫丹。","你是说采石场？是的，我几乎天天都能看见那些庞大的蒸汽坦克从营地边经过。我在东边布下的线人告诉我，这些机车是从铁炉堡出发的，在古博拉矿场稍作停留之后，在卡拉诺斯补给燃料，由于某些该死的原因，他们用了很长的时间才经过诺莫瑞根，最后在铁炉堡卸下了货物。情况全都写在这份报告里了，<职业>。把它交给霍夫丹，让他好好计划下一步的行动。","小武哥儿"},
[2240] = {"密室","阅读巴尔洛戈的日记，探索密室，然后向铁炉堡的勘察员塔伯斯·雷矛汇报。","现在我手头有个任务。我们要找到一间被称作卡兹穆尔大厅的密室。问题是这个房间在一扇巨大的门后面，而那扇门被锁住了！幸运的是，我知道如何打开它。我把所有东西都写在我的日记里了，就在这个台子上。我的队伍现在被困在这里……所以呢，$n，你必须为我们找到卡兹穆尔大厅！阅读我的日记，探索那间密室，然后向铁炉堡探险者协会的勘察员塔伯斯·雷矛汇报。","小武哥儿"},
[2241] = {"詹诺克的花","把詹诺克的玫瑰带给达纳苏斯的塞尤娜。","他们说我已经“陷入爱的深渊”，管它是什么意思呢。当然啦，我清醒的每一刻都在想念着塞尤娜，我的家里也挂满了她的画像。当然，我会经常不吃不喝也不睡地度过一整天，深陷于我们曾经拥有的美好爱情的回忆之中。这难道有错吗？现在她不会再见我了！我想要给她传递消息，但她不愿和任何人说话，除非那人是个盗贼。你能替我把这些花带给她吗？别忘了告诉她这些花是詹诺克送的。","小武哥儿"},
[2242] = {"命运的召唤","找到远古的塞希尔，带回任何你可能发现的线索。","我们相信有一个萨特可以帮助我们搞清泰达希尔的森林中究竟发生了什么。但不幸的是，他可不会老老实实地跟我们合作。他的藏身之处就在神谕林地外围的一棵树上，但是与他接触的人——无论是使用武力还是试图交涉——都被他杀死了。也许只有偷偷摸摸地行动才是唯一可行的方案，。去看看塞希尔的包裹里有些什么，然后回来向我报告。","小武哥儿"},
[2258] = {"荒芜之地的试剂","前往荒芜之地取回加卡尔需要的试剂，然后回到卡加斯把试剂交给他。","，我需要你的帮助。我是个略有名气的炼金术者，现在我想请你去荒芜之地帮我弄些试剂来。我需要以下物品：5个秃鹫的胃囊，10颗峭壁山狗的牙齿，还有5个石元素的碎片。当然，你可以从那里的野兽身上弄到这些东西，但是假如你不是那么善于战斗的话，就去找一些朋友帮帮忙吧。帮我找到这些物品，我就会给你些钱作为报酬。愿意试试吗？","小武哥儿"},
[2259] = {"艾瑞安·影语","与达那苏斯的艾瑞安·影语取得联系。","别担心，，我不是要把你送去见塞尤娜。艾瑞安正在塞纳里奥区等你，快点吧！","小武哥儿"},
[2260] = {"艾瑞安的命令","到暴风城去找到“剃刀”雷吉克。","你已经是个很有名气的<职业>了，。事实上，暴风城的情报机构点名要你去为他们效力。这次旅行会很辛劳，而且一路上危机四伏，不过我想谁也不会轻易放弃在暴风城军情七处训练的机会。一个崭新的世界在等着你，。到暴风城的旧城区去,和军情七处总部里的“剃刀”雷吉克谈一谈吧，祝你好运。","小武哥儿"},
[2278] = {"白金圆盘","和石头守护者交谈，从他那里了解更多古代的知识。一旦你了解到了所有的内容之后就激活诺甘农圆盘。","财宝室的中间是四块巨大的白金圆盘，每块圆盘上都刻满了各种各样的未知文字和图案。你的手触摸这些圆盘的时候，你感到了一丝震动。就在你接触圆盘的一瞬间，一个巨大的石头守卫者的形象出现在了你的面前。“你好。我是知识的守卫者。土灵的创造者所留下的一切有关这个种族的知识都已经存储在了这张诺甘农圆盘上了。”你发掘到了迄今为止这个世界上最宝贵的知识财富！","小武哥儿"},
[2279] = {"白金圆盘","把迷你版的诺甘农圆盘带到铁炉堡的探险者协会去。","再次触及诺甘农圆盘让你的手感受到了又一次的震颤。这一次从圆盘传出了一种奇怪的研磨声。你的背包忽然沉了一下。打开背包之后，你发现了一张迷你版的圆盘！毫无疑问，在任何对艾泽拉斯大陆历史感兴趣的人手中，这张圆盘都绝对是无价之宝。铁炉堡的探险者协会是一个非常有名的探险团体，也许他们能好好利用这张圆盘。","小武哥儿"},
[2280] = {"白金圆盘","把迷你版的诺甘农圆盘带到雷霆崖的贤者那里。","再次触及诺甘农圆盘让你的手感受到了又一次的震颤。这一次从圆盘传出了一种奇怪的研磨声。你的背包忽然沉了一下。打开背包之后，你发现了一张迷你版的圆盘！毫无疑问，在任何对艾泽拉斯大陆历史感兴趣的人手中，这张圆盘都绝对是无价之宝。雷霆崖的先知们对历史知识的了解程度享誉整个部落，也许他们能好好利用这张圆盘。","小武哥儿"},
[2281] = {"赤脊山的联络员","到赤脊山的湖畔镇去和卢修斯谈一谈。","现在就把你派出去等于让你去自杀，雷吉克可不想再让哪个初出茅庐的盗贼平白挂掉。不过你也别着急，。雷吉克要先培养你的能力。现在你就动身去赤脊山，和一个名叫卢修斯的军情七处联络员谈一谈吧。他就在湖畔镇的码头附近，和其他一些游手好闲的家伙整天搅在一起。","小武哥儿"},
[2282] = {"奥瑟尔伐木场","打开卢修斯的箱子，拿到偷窃技能证明物，然后把它归还给湖畔镇的卢修斯。","多年以来，我们都在这里对盗贼进行训练！毕竟不是每一个盗贼都能像老卢修斯那样机灵和优雅的。沿着这条路向前走，一直到奥瑟尔伐木场去。我在那里放了一只装着重要物品的箱子。去把箱子里的东西给我拿来，我就给你颁发偷窃技能认证书！","小武哥儿"},
[2283] = {"搜寻项链","在奥达曼挖掘场中寻找一条珍贵的项链，然后将其交给奥格瑞玛的德兰·杜佛斯。项链有可能已经损坏。","我们有工作要交给你做，不过能否完成要看你有没有胆子！在荒芜之地的深处有一个名叫奥达曼的挖掘场，我们最近听说有个没脑子的圣骑士在里面挂了。我之所以如此关心这个问题是因为那蠢货身上带着一条非常珍贵的项链，项链上有三块大宝石：一块红宝石，一块蓝宝石和一块黄宝石。现在的问题是，我们需要它，而且我们会付给完成这个任务的人最丰厚的报酬。也许那条项链已经受到了损坏，但是不管怎么样，只要你把它带给我们，就总是会有办法修好它。","小武哥儿"},
[2284] = {"搜寻项链，再来一次","在奥达曼里找寻宝石的线索。","玛尔顿这个笨蛋，我确信宝石还在奥达曼的某个地方，你必须回去找到它们。就像我之前所说的那样，如果我们掌握的情报是正确的话，那么这条项链上原本应该有红宝石、黄宝石和蓝宝石各一块。找到它们，并且把它们放回到项链上。至于那些宝石的具体位置就没有人知道了。如果你运气不错的话，也许你能找到那个笨蛋圣骑士的尸体。如果他还没有被剥光的话，没准你还能在他身上找到那些宝石。","小武哥儿"},
[2298] = {"国王的搜查","到暴风城里去找到“剃刀”雷吉克。","然后我们就到了那里，准备执行第三阶段的计划。突然，一伙麦格尼手下的家伙闯了进来，他们自称是来搜查的，二话不说就要抓人。但是没人敢在我霍夫丹·黑须面前动粗！于是双方唇枪舌剑地开始吵，结果你的名字就被不知道哪个白痴吼了出来！我的意见？赶紧骑上狮鹫离开铁炉堡，到暴风城去。到旧城区里去找我的一个老朋友，他的名字叫“剃刀”雷吉克。","小武哥儿"},
[2299] = {"去找霍夫丹！","到铁炉堡去和霍夫丹·黑须谈一谈。","你去哪儿啦，？霍夫丹到处找你。我们都以为国王把你抓起来了。快去铁炉堡找霍夫丹！","小武哥儿"},
[2300] = {"军情七处","到暴风城去找到“剃刀”雷吉克。","雷吉克在找你呢，新手。如果我是你的话，就不会让马迪亚斯的副手干等着。","小武哥儿"},
[2318] = {"翻译日记","在荒芜之地的卡加斯哨所里寻找一个可以帮你翻译圣骑士日记的人。","显然你看不懂日记上的字，得找个人来帮忙翻译才行。这个世界上有不少可以胜任这项工作的人，最近的一个应该在荒芜之地的卡加斯哨所里。也许你应该去那里找找。","小武哥儿"},
[2338] = {"翻译日记","将项链借给加卡尔。作为交换，他将帮你翻译日记。","杜佛斯那个蠢货是不可能恢复项链的力量的，不过我可以。现在我要做的就是好好研究一下项链，然后给你制作一条跟它完全一样的复制品。请把项链借给我作为我帮你翻译日记的交换吧，在你出发去找寻宝石的这段时间里，我应该可以完成对项链的研究和对日记的翻译工作。这个交易很简单明了，而且没有别人可以帮你翻译日记。你看怎么样？","小武哥儿"},
[2339] = {"寻找宝贝","从奥达曼找回项链上的所有三块宝石和能量源，然后把它们交给卡加斯的加卡尔。红宝石被藏在暗影矮人层层设防的地区。黄宝石藏在石颚怪活动地区的一个瓮中。蓝宝石在格瑞姆洛克手中，他是石颚怪的领袖。能量源可能在奥达曼的某个最强生物的手中。","日记已经全部翻译完毕了。其中的关键是红宝石在暗炉矮人手里，黄宝石在石颚怪手里，而蓝宝石则在一个名叫格瑞姆洛克的石颚怪那里。你需要一个强力能力源来让项链重新恢复以前的力量，这一点是德兰·杜佛斯所不知道的。我所能想到唯一符合如此要求的能量源应该在奥达曼的最强生物身上，所以你必须深入奥达曼的最底层，杀掉所有看上去最强的生物，这样你就肯定可以获得它。当你把所有东西找全之后就尽快把它们带回来给我。","小武哥儿"},
[2340] = {"交付宝石","把项链和宝石送到奥格瑞玛的德兰·杜佛斯那里。","只要采用相同的材料进行制作，任何的项链和宝石的组合都能发挥作用。而这个能量源才是真正给项链提供力量的关键……我希望如此。只要能量源能够一直保持正常运转，我随时都可以为你制作这么一条项链。去奥格瑞玛找德兰·杜佛斯完成你们的交易吧。记住不要透露任何关于项链的信息，当你回来的时候，我会给你一个特别的惊喜的。","小武哥儿"},
[2341] = {"项链任务的终结 (地下城)","去卡加斯看看加卡尔是否成功了。","在德兰和玛尔顿为了他们的战利品而争执不休的同时，你的任务也算完成一半了。现在你得去荒芜之地完结这个任务，卡加斯营地里的加卡尔应该已经为你准备好了特别的奖励。","小武哥儿"},
[2342] = {"寻找宝物","从奥达曼南部大厅的箱子中找到加勒特的家族宝藏，然后把它交给幽暗城的帕特里克·加瑞特。","我简直烦透了用这把破扫帚在这里打扫蝙蝠窝了！我靠这个该死的工作中存了一些钱，而且我愿意用这些钱来雇你帮我做些事情。加瑞特家族的祖传武器自从我们家到那里去当挖掘工以来就一直被锁在奥达曼的南部大厅中的箱子里。没有它，我就要永远被困在这里——也就是说，我就得永远跟这些该死的蝙蝠在一起！找到我家族的宝藏，把它给我拿来！帮我找回原本就属于我的东西！","小武哥儿"},
[2358] = {"奈兹拉之角*","把奈兹拉之角还给在湖畔镇的阿兰提尔之影。","很多年前,奈兹拉之角在拉文霍德庄园被盗,找遍了大陆和海洋后我发现,一些不足挂齿的野兽一直占有着它。杀死你途经所有的黑石兽人，直到你得到奈兹拉之角。一旦你拿到了它，就来湖畔镇找我吧。你的名字会被拉文霍德庄园的人记住的，。","小武哥儿"},
[2359] = {"克拉文之塔","偷取迪菲亚塔楼钥匙，进入迪菲亚塔楼，看看暮色森林的箱子里到底有什么东西，然后向暴风城的马迪亚斯·肖尔汇报。","我为如何进入这座塔的问题头痛好久了，。最近从暮色森林来了一船货物，同时还来了不少守卫。他们是谁？我也有着和你一样的疑问。我所知道的是——他们不是人类。不管怎么样，这批货物中有一只特殊的箱子——我想这就是那些亡灵在守护的东西。带着狼牙棒的那个家伙手里有那座塔的钥匙。拿到钥匙，进入塔里，看看箱子中到底有什么，然后去向马迪亚斯报告。","小武哥儿"},
[2360] = {"马迪亚斯和迪菲亚盗贼","去西部荒野和密探吉尔妮谈一谈。","，不久之前，军情7处接到西部荒野出现大量迪菲亚兄弟会成员的报告。现在他们已经占据了位于哨兵岭东南部的一座荒废的哨塔，并将其作为从赤脊山走私补给物资的中转站。到西部荒野去和密探吉尔妮会面，你应该可以在哨塔的附近找到她。另外……$n，一旦你的行动被发现，军情7处将会否认与你有任何联系。","小武哥儿"},
[2361] = {"修理项链","","","小武哥儿"},
[2378] = {"寻找碎手氏族","前往奥格瑞玛，和暗影裂口那的申苏尔谈一谈。","，你一向以来都对我们衷心耿耿，现在是让你出去闯一闯的时候了。虽然你已经展现出了在盗贼之路上过人一等的天赋，但是你还是需要更多的练习才能达到更高的境界。我们和碎手氏族是盟友。去找他们吧，一直以来我们的关系都很好——去奥格瑞玛找申苏尔。","小武哥儿"},
[2379] = {"赞杜沙","与暗影裂口的赞杜沙谈一谈。","单凭你的决心是无法帮助我们克服困境的。去和赞杜沙谈谈，然后你就可以作为碎手氏族的一员接受训练了。只有掌握了潜行和偷窃的技术，你才能继续沿着你的命运之路前进。","小武哥儿"},
[2380] = {"向奥格瑞玛进发！","在奥格瑞玛城中的暗影裂口和申苏尔谈谈。","你还不是个秘密行动和欺诈的高手，不过迟早会是的。曾经训练过你的导师们都对你的潜力印象深刻，于是伟大的申苏尔点名要召见你。沿着路向北走，一直到奥格瑞玛去，在暗影裂口和申苏尔谈一谈。","小武哥儿"},
[2381] = {"抢劫海盗","把南海宝藏带回给棘齿城的卑鄙的维尼克斯。不要忘了从维尼克斯的机械设备中拿取一份大饼干和盗贼工具，你的任务需要使用这两件东西。如果你被任何奇怪的鹦鹉攻击，就对它使用大饼干！","我并不是要吓唬你，，但是前五个派去偷南海宝藏的小偷都是被别人一块块运回来的……沿着这里南边的海岸走，你会找到海浪剃刀号，那是南海海盗的船。货舱中的东西就是你的目标——南海宝藏。在船舱的二层是海盗的聚集处，那里也是他们训练盗贼的地方。设法登上那条船，然后把南海宝藏给我偷到手。你可以在那群海盗扎堆的地方试试自己的身手，但是你要非常小心，否则你就会成为第六个！","小武哥儿"},
[2382] = {"棘齿城的维尼克斯","到棘齿城去，与卑鄙的维尼克斯谈一谈。","赞杜沙确实看到了！是的，我看到了那一天的到来！萨尔死了……匕首刺在他的背上，毒液渗透到他的血管之中……赞杜沙说得太多了。！赞杜沙有个任务要交给你！你必须马上到十字路口东边的棘齿城去，跟卑鄙的维尼克斯谈谈。","小武哥儿"},
[2383] = {"简易羊皮纸","阅读简易羊皮纸，然后和试炼谷的弗郎恩谈一谈。","啊，刚刚你不在的时候，有人送来了这张羊皮纸，。如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这张羊皮纸是战士训练师弗朗恩写的，他有事找你。你可以在大兽穴外面的阴凉处找到他。","小武哥儿"},
[2398] = {"失踪的矮人","在奥达曼找到巴尔洛戈。","奥达曼挖掘场从前并不是现在这样一团糟的。我们铁炉堡的矮人曾经控制了这个区域，但是……当穴居怪来了之后，一切都变了。它们的数量太多了，连我们矮人也挡不住它们！事实上，因为它们非常突然地发起了攻击，所以我担心我们有些人被困在了挖掘场里面。我的朋友巴尔洛戈带了一个矮人小队进入了挖掘场深处，就在穴居怪发起攻击之前。如果他和他的同伴们还活着的话，我希望你能找到他们。","小武哥儿"},
[2399] = {"发芽的树叶","","","小武哥儿"},
[2418] = {"能量石","给荒芜之地的里格弗兹带去8块德提亚姆能量石和8块安纳洛姆能量石。","不久之前，我和暗炉矮人打过一段时间的交道。他们把我带到了苦痛堡垒，让我对两种来自于奥达曼的奇怪石头进行研究。我发现这两种石头如果经过正确的处理，就会变成相当理想的能量源。能在那个废旧的挖掘场里发现这样的东西让我感到十分惊奇！之后，在我告诉他们这个秘密之后，那帮该死的家伙就把我踢出了苦痛堡垒，然后自己在奥达曼挖掘更多的石头。我要为自己搞一些那种石头！帮我带那两种石头来，我会给你丰厚的报酬的。","小武哥儿"},
[2438] = {"翡翠摄梦符","将翡翠摄梦符交给多兰纳尔的塔隆凯·捷根。","班奈希尔兽穴的德鲁伊守护者盖洛拉斯·塔文斯伦曾经给了我一个翡翠摄梦符。这种强大的护符可以吸取翡翠梦境的能量，给拿着它的人带来好运。不过，我把它放在星风村的衣柜里了，没办法把它取回来……星风村原本是个宁静的小村子，但现在那里受到了熊怪的侵袭。你能不能帮我拿回摄梦符，<职业>？","小武哥儿"},
[2439] = {"白金圆盘","把你的报酬凭证交给铁炉堡银行的丁尼塔·石衣。","这东西真是个惊人的发现。如果这里储存的知识都是正确的话，那么这些圆盘所涉及的古代泰坦——或者说造物之神——肯定和我们的起源有所联系！我们要用尽可能多的时间来研究它。至于你，英勇的<职业>，把这个凭证交给大厅里的丁尼塔·石衣，你一定会为你的伟大发现得到应有的报酬！准备好了之后就回到我这里来，探险者协会还有很多事等着你去做！","小武哥儿"},
[2440] = {"白金圆盘","把报酬凭证交给雷霆崖的本娜·冰蹄。","我要把精力都集中在这些圆盘上，它们一定会向我展示其真正的作用。至于你，，你的努力也会得到我的回报。把这个证明交给雷霆崖的炼金师本娜·冰蹄，她会给你一样不错的东西作为回报，还会给你一些我私人收藏的药水。尽快回来见我，我感觉这个发现还会让我有很多事要忙。","小武哥儿"},
[2458] = {"卧底密探","到淤泥沼泽北边的风险投资公司塔楼去，联系碎手氏族的卧底费苏勒。看到塔楼之后，用信号枪发射信号，向工头费苏勒示意你已经到达。发出两个闪光信号，然后使用碎手军礼和工头费苏勒接头。注意，这些步骤必须依次进行，因为费苏勒会攻击并干掉任何他无法识别的人。","风险投资公司……也许你听说过他们？一年以来，我们一直都想在他们的高层中安插一名密探，经过艰苦的努力和仔细的谋划，我们终于成功了。最近密探给我们带来情报说风险投资公司有个大规模的计划，所以我派你到淤泥沼泽的北部去，在风险投资公司的塔楼附近联系我们的卧底密探费苏勒。找到塔楼之后，用这个信号枪和费苏勒联系，然后用碎手军礼向他致敬。","小武哥儿"},
[2459] = {"噬梦者菲罗斯塔","多兰纳尔的塔隆凯·捷根要你杀掉7个瘤背秘法师，并找到遗失的珠宝。","翡翠……不见了！我的摄梦符被毁了！星风村北部有一群瘤背秘法师。我接到报告说他们的领袖——噬梦者菲罗斯塔的脖子上戴着一根在夜间会发出绿光的项链。我觉得就是它偷走了我的翡翠……它决不会想到那颗翡翠对它毫无用处。去找到丢失的宝石，。另外，你在那儿活动的时候，别忘了顺便清除一些堕落的秘法师。","小武哥儿"},
[2460] = {"碎手军礼","对着申苏尔练习碎手军礼。","作为碎手氏族的盗贼，你必须学会碎手军礼。这是识别氏族成员的唯一方法。看好了，然后重复做一遍。","小武哥儿"},
[2478] = {"基本不可能的任务","从工头希里克斯那里偷出希里克斯的塔楼钥匙，进入塔楼，然后杀掉两个变异风险投资公司工人、两个风险投资公司巡逻员、两个风险投资公司看守。杀掉大工头普兹克·加里维克斯，取了他的首级，然后打开加里维克斯的箱子，拿走赞吉尔的改良药剂。将药剂和加里维克斯的头颅交给奥格瑞玛的申苏尔，等候进一步的指示。","你必须从工头希里克斯身上偷出塔楼的钥匙，。拿到钥匙之后，就把它收好——你也许用得到它。记住，毒药已经让塔楼里的所有人都变得虚弱不堪。尽你所能给那些家伙制造混乱和破坏，把他们全都杀了——不要手下留情！等里面所有人都躺在血泊中之后，你就可以去打开加里维克斯的箱子，然后拿走赞吉尔的改良药剂。把加里维克斯的脑袋和药剂一起交给奥格瑞玛的申苏尔。","小武哥儿"},
[2479] = {"希诺特的帮助","到希尔斯布莱德丘陵的塔伦米尔去，把赞吉尔的药剂样品交给瑟尔格·希诺特。要去塔伦米尔，可以搭乘飞艇到幽暗城，然后沿着大路向南穿过银松森林，直到希尔斯布莱德丘陵。跟着路标走！","把这个混合物的样本交给塔伦米尔的瑟尔格·希诺特。只有瑟尔格能治得了你所中的毒。如果你能活得久一点的话，他还能教你制造并使用这种毒药的方法。","小武哥儿"},
[2480] = {"希诺特的帮助","等待瑟尔格·希诺特完成解药。","我从来没有见过哪种毒药能产生这么惊人的效果！你是说赞吉尔？从没听过这个家伙，不过既然他能制造出这种毒药来，那他还是值得我刮目相看的。那么你是要我帮你解毒，然后教你如何使用这种毒药？给我点时间研究一下毒药，。","小武哥儿"},
[2498] = {"向德纳兰回报","雷利亚·绿树要你和奥拉密斯湖的德纳兰谈一谈。","我刚接到消息，奥拉密斯湖畔的德纳兰可能已经发现了让林精长出那些毒瘤的原因。你去和他谈谈吧，告诉他是我派你去的。动作快点，，他需要我们的帮助。","小武哥儿"},
[2499] = {"奥肯斯古尔","奥拉密斯湖的德纳兰要你去拿到奥肯斯古尔身上的巨大的瘤。","在湖南岸的山洞里有一个名叫奥肯斯古尔的林精，它正在使居住在奥拉密斯湖周围的所有生物变得堕落。我不敢离那里太近，不过即使从远处看去，我也能看得很清楚：奥肯斯古尔已经被一颗我所见过的最大的肿瘤所毒害了……那个肿瘤简直可以被称作庞然大物。，你已经帮了我许多忙，不过我还要请你做一件事。杀掉奥肯斯古尔，拿到它身上的肿瘤，让这个堕落之源永远从我的家园消失。","小武哥儿"},
[2500] = {"荒芜之地的材料","从荒芜之地拿到加克所需的材料，然后回到塞尔萨玛去见他。","，我需要你的帮助。我是个小有名气的炼金师，我需要你去荒芜之地帮我找一些原材料。我需要这些东西补充我的库存：五个秃鹫的胃囊、十颗峭壁山狗的牙齿和五块岩石元素碎片。当然你可以从这些动物身上拿到这些东西，不过如果你不擅长打仗的话，可以找些擅长的朋友。找到这些东西给我，作为交换你可以得到一些钱币。好吧，你觉得怎么样？","小武哥儿"},
[2501] = {"荒芜之地的材料 II","在荒芜之地的守护火龙身上使用空的魔瓶。将这些容器都盛满之后，把它们交给塞尔萨玛的加克。","你对我的帮助很大，。我可以把以前我给你的那种酒的配方作为报酬送给你，不过还得让你先帮我个忙才行——这次的事比较危险。这只上锁的箱子里装着三个空的魔瓶，里面有一种可以吸取火龙血液的魔法能量。用这些容器去对付火龙会把它们激怒，所以你得小心点。把三个容器都盛满了，再把它们拿回来给我。完成这个任务之后，配方就是你的了。","小武哥儿"},
[2518] = {"月神的泪水","达纳苏斯月神殿的女祭司艾茉拉让你把萨丝拉的银色丝囊交给她。","萨丝拉曾经受到月神的宠爱，这只优雅而纯洁的蜘蛛在月光下的迷雾中编织着银线，用以收集银色的露水，并将这种有治疗功效的露水存放在这个大殿里。不过最近萨丝拉却突然变得疯狂起来，她的后代也受到了威胁。找到萨丝拉，，结束她的痛苦。她住在泰达希尔的北部边界。找到她的银色丝囊，把它们交给我。","小武哥儿"},
[2519] = {"月神殿","艾奎恩妮让你和月神殿的女祭司艾茉拉谈一谈。","森林里有一个曾经强大无比的生物现在急需帮助，<职业>。现在你有一项艰难的任务必须完成。请你去找女祭司艾茉拉，她会向你解释具体的问题。她就在这里东南方的月神殿里。","小武哥儿"},
[2520] = {"萨丝拉的祭品","女祭司艾茉拉让你将萨丝拉的银色丝囊放在大殿的喷泉处，然后回去见她。","现在你必须完成交给你的任务。拿上银色丝囊，然后将它作为萨丝拉的祭品献给艾露恩，让这只蜘蛛得以安息。找到大殿中央的喷泉，在那儿放下祭品。神圣的泉水可以净化并清洗让萨丝拉发疯的堕落力量。完成任务之后再回来见我。","小武哥儿"},
[2521] = {"为库米沙效力","在你探索诅咒之地的旅程中，如果碰巧发现了无暇的德莱尼水晶球，就把它交给收藏家库米沙。你要知道，这种宝石是整个艾泽拉斯最珍稀的水晶。诅咒之地上的任何一种生物都有可能带着一颗无暇的德莱尼水晶球。每找到一颗，你都会得到相应的酬劳。","$R，你的小脑袋能理解一颗无暇的德莱尼水晶球有多么珍稀吗？无数德莱尼人终其一生就想要寻找一块这样的水晶，可是却屡遭失败，一直没能达到愿望。你现在就站在库米沙面前，你知道库米沙想要什么，而且你还愿意帮助我？很好，<种族>……在你探索者个区域的过程中，只要找到一颗无暇的德莱尼水晶球，就把它带回来给我，我会以你永远都无法想像的财富回报你。","小武哥儿"},
[2522] = {"库米沙的努力","找到一颗无暇的德莱尼水晶球，把它交给收藏家库米沙。","虽然召唤传送门的魔法失败了，不过我相信下一次一定能成功。德莱尼人的希望就像你们$R对财宝的渴望一样强烈，回到这块被诅咒的土地中去，再给我拿回一颗无暇的德莱尼水晶球来。当然，要不要接受这个任务完全取决于你*咧嘴笑*。","小武哥儿"},
[2523] = {"被腐化的轻歌花","","","小武哥儿"},
[2541] = {"沉睡的德鲁伊","将一个萨满巫毒符咒交给班奈希尔兽穴的奥本·怒爪。","这里的瘤背萨满祭司找到了一种可以在德鲁伊休眠时将他的灵魂和肉体分离的方法。熊怪就这样驱使着我的肉身，利用我去袭击那些对班奈希尔兽穴进行侦查的人。现在我沉睡在翡翠梦境里，无法阻止他们。你一定要帮帮我。瘤背萨满祭司用一种特殊的符咒来完成这种仪式，我希望能研究一下这种咒符。$n，全靠你了。","小武哥儿"},
[2561] = {"利爪德鲁伊","奥本·怒爪要求你去杀掉他那失去灵魂的身体，然后对其尸体使用巫毒咒符。","在研究过这个咒符之后，，我知道该做什么了。请拿着它，然后照我说的去做。你必须到班奈希尔兽穴的深处去，在那里，你会发现我那失去灵魂的躯体……虽然我对将要让你这么做感到很遗憾，但是除此之外我找不到其它可以让我摆脱瘤背熊怪控制的办法了。你必须杀了我的肉身，然后对我的尸体使用巫毒咒符。完成这个任务之后就请回到我这里来。","小武哥儿"},
[2581] = {"弯牙土狼的颚骨","收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。","众所周知，土狼的颚骨具有强大的力量，不过它能折断三英吋厚的瑟银条吗？不可能，决不可能，可是我却亲眼看到了这种事情。到诅咒之地去给我弄三个弯牙土狼的颚骨回来，路上顺便打一些野猪和蝎子，因为我还需要两片诅咒之地的野猪肺和一个厚甲蝎螯。","小武哥儿"},
[2582] = {"远古之怒","收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。","啊，，欢迎回来。你好像非常喜欢从土狼的颚骨中提炼出来的药剂所带给你的感觉。但是你要小心，虽然它可以使你拥有泰坦一般的力量，不过它对你的精神和智力也具有长期的负面作用。我跟你说了这么多之后，你还想要更多这种药剂吗？如果你还要的话，就给我弄三个弯牙土狼的颚骨、两片诅咒之地的野猪肺和一个厚甲蝎螯来。","小武哥儿"},
[2583] = {"野猪的活力","收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。","这片不毛之地上生活着两种野猪：灰鬃野猪和地狱野猪。看来这些野兽的耐力十足，这让它们几乎可以不受任何伤害，因此其它动物都无法与之抗衡。我们要做进一步的研究，。你给我弄三片诅咒之地的野猪肺、两个厚甲蝎螯和一颗石化蜥蜴的大脑来，我就可以从中提炼出一种超强的药剂。而你就将成为我的第一个实验对象！","小武哥儿"},
[2584] = {"野猪之魂","收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。","在第一次试用这种药剂的时候，我就知道仅用一两次是无法满足你对它的渴求的。即使是现在，我也还能看见你眼中的渴望。这种药剂会让人上瘾，再有意志力的人也无法抵挡它的诱惑。好吧！如果你还想要更多的肺片鸡尾酒，就到诅咒之地里去给我弄三片诅咒之地的野猪肺、两个厚甲蝎螯和一颗石化蜥蜴的大脑来。","小武哥儿"},
[2585] = {"决定性的打击","收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。","你见过它们作战吗，？我是说那些蝎子。你有没有见过他们优美、敏捷的动作？有没有看到过它们那迅捷的攻击？如果我们能将它们的敏捷性分离出来并制成药剂，那我们就发达了……我的意思是……那将是我们对科学的一大贡献！帮帮我吧，，我可以送给你一份实验样品。我需要三个厚甲蝎螯，两个秃鹫的砂囊和一片诅咒之地的野猪肺。","小武哥儿"},
[2586] = {"厚甲蝎盐","收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。","你还活着！这真是个好消息。我猜你回来是想要更多的厚甲蝎盐吧？很好，，那么，你再回到诅咒之地去，帮我弄三个厚甲蝎螯、两个秃鹫的砂囊和一片诅咒之地的野猪肺回来吧。","小武哥儿"},
[2601] = {"石化蜥蜴的大脑","收集10颗石化蜥蜴的大脑和2个秃鹫的砂囊，把它们交给血法师莱诺雷。","这块荒地上到处都是红石蜥蜴，。这些蜥蜴的族群比这里的其它任何生物都要兴旺。我曾经在远处观察过它们的捕猎和其它日常活动——这些野兽表现出了某种思考过程，它们的智商甚至比某些人型生物还要高。我得研究一下他们的脑子！给我找十颗蜥蜴的大脑来，。还有，你必须再找两个秃鹫的砂囊，否则我就无法完成药物的配制。","小武哥儿"},
[2602] = {"清晰的思想","收集10颗石化蜥蜴的大脑和2个秃鹫的砂囊，把它们交给血法师莱诺雷。","药效这么快就没了？看来我还有更多的研究要做！哦，当然，条件不变，。回到诅咒之地去，给我弄十颗石化蜥蜴的大脑和两个秃鹫的胃囊来。","小武哥儿"},
[2603] = {"秃鹫的活力","收集10个秃鹫的砂囊和2块弯牙土狼的颚骨，把它们交给血法师莱诺雷。","死亡在这片被诅咒的土地上长出了翅膀，<职业>。我曾亲眼目睹那些秃鹫将探险者的尸体狼吞虎咽地吃掉——有时它们甚至会吃下携带着致命疾病的尸体。它们身体内部的系统竟然能够抵御席卷了这片土地的瘟疫，这的确令我感到十分惊奇。请帮助我进行研究，！我需要秃鹫的砂囊，还需要两块弯牙土狼的颚骨作为原料。我会和你五五分成的。","小武哥儿"},
[2604] = {"精神矍铄","收集10个秃鹫的砂囊和2块弯牙土狼的颚骨，把它们交给血法师莱诺雷。","我看到你体内的火焰已经渐渐熄灭，那就是说，药效只持续了一个小时？如果你还需要更多砂囊口香糖，就给我弄更多的砂囊来。在诅咒之地中收集十个砂囊和两块颚骨之后再回来。","小武哥儿"},
[2605] = {"口渴的地精","找到1个饱满的露水腺，把它交给加基森的马林·诺格弗格。","住在大沙漠里真是活受罪！我都要被烤干了。不过我有个主意。听说有一种被称作露水收集者的生物就在西南方活动……它们有一种特殊腺体，可以用来储藏水分。如果能得到这种腺体，我就可以畅饮一顿，至少滋润滋润我的嘴唇！你能帮帮我吗，？找到有一大片仙人掌的地方，，露水收集者常在那里出没。","小武哥儿"},
[2606] = {"好味道","马林·诺格弗格让你与加基森的斯普琳科谈一谈。","呸！这个东西真难吃！这个主意也不过如此嘛……等等，你说什么？哦，我知道，我知道，你认为我不该就这么放弃它。那么，好吧。对了，我有个主意！一个妙极了的主意！去和我朋友斯普琳科谈谈吧——她是个出色的厨师。告诉她我们想做什么，还有我们想要知道加点什么才能把让人这东西咽下去。我的意思是，如果它这么难吃的话，总得让它有些让人兴奋的东西才行……可是我现在就是感觉不到。","小武哥儿"},
[2607] = {"赞吉尔之触","到兵营的地窖里去和道克·米希匹克斯谈一谈。","看样子你带来的消息比我想像的还要多。这的确是一个奇怪的转折点，。解药？嗯……到地窖里去跟道克·米希匹克斯谈谈吧——他也许能提供点帮助。","小武哥儿"},
[2608] = {"赞吉尔之触","用/lay指令躺下，接受道克·米希匹克斯的治疗。如果他找不到病因，就找不到治疗的方法。","哦，天哪，你看上去就像死人一样。纠正一下——我见过死人，你看上去比死人还要糟，简直像是死了又死！哈哈！诺拉姆，你听见了吧？把它记下来！*咳嗽*嗯，好吧。为了帮助你，我得先给你抽点血。别担心，只有前几次抽血会有点疼……大概前五十次吧……准备好了之后就躺下（使用/lay指令），。","小武哥儿"},
[2609] = {"赞吉尔之触","给道克·米希匹克斯带去一束普通野花、一只铅瓶，一根青铜管，最后还要一卷淡绿色丝线。伊提斯综合症可不会不治而愈，年轻的$g先生:小姐;。","我们达成了共识，，你得的是“伊提斯综合症”。幸运的是，我这里有医治伊提斯综合症的药方。我需要些东西：一束普通野花、一只铅瓶，一根青铜管，最后还要一卷淡绿色丝线。奥·艾玛在“最好的线团”那家店里给我留了一卷这样的线，就在运河区沿岸。赶紧出发吧，，记住在你的病痊愈之前不要接触任何人。哦，还有，蒙特高莫医生说你该洗个澡了——他说的，不是我说的。","小武哥儿"},
[2621] = {"悔恨的战士","与斯通纳德的分队指挥官鲁尔格谈一谈。","遗憾，我现在只有遗憾。一个错误的决定造成了这么可怕的结果。我真应该留在那儿等候命令。也许它可以告诉我们，在那个该死的地方有什么可怕的事情在等着我们！也许它是要将我们调到别的地方去？归根结底还是我的错，都是我的错。所以我现在就站在这儿，等候命令。我必须了解情况，必须拿到那些命令。传令官鲁尔格驻扎在斯通纳德，去找他，查明那封命令现在到底在哪里。","小武哥儿"},
[2622] = {"丢失的命令","与本戈尔谈一谈。","命令？你怎么能向我要酋长的那封命令？你是什么意思，？我当然派人把命令送了出去！我派去送信的士兵被鱼人伏击，损失惨重，只有本戈尔活下来——如果那还算活着的话。他现在几乎不能说话，更不要说走路了，他只能靠管子喂食，奄奄一息。如果你想知道那封命令出了什么事，就去和他谈谈，他肯定就在附近什么地方……还有，这里到处都是危险的生物，你一定要小心一点。","小武哥儿"},
[2623] = {"沼泽空谈者","取回酋长的命令，把它们还给部落英雄的灵魂。","分队指挥官下达了命令。我们接……接到了命令。在去诅咒之地的路上，被伏击了。鱼人……很多鱼人……其中一个叫沼泽空谈者的鱼人，从我手上抢走了命令，然后……长矛插入了我的头骨。它应该就在东边……山洞……<本戈尔昏死了过去。>","小武哥儿"},
[2641] = {"斯普琳科的秘密佐料","加基森的斯普琳科要你去给她找到一颗紫色水生菇。","在我还小的时侯，我姐姐包揽了所有烧饭的活，那简直是糟透了！她做的有些东西简直让我无法忍受——直到我发现了一种被我称作“秘密佐料”的东西，只要加上一点……啧啧！味道好极了！你问那是什么东西？嗯，是一种被称作紫色水生菇的蘑菇。如果你要我把这个尝起来像拖把一样的东西变成可以下咽的食品，那么我建议你去一趟辛特兰，到那里去找一个小湖泊。哦，记住了，紫色水生菇只有在水下才能找到。","小武哥儿"},
[2661] = {"给马林的粉末","斯普琳科让你把紫色粉末交给加基森的马林·诺格弗格。","这是紫色粉末，，把它交给马林，告诉他，他欠我一个人情！","小武哥儿"},
[2662] = {"诺格弗格药剂","马林·诺格弗格让你在他制成药剂之后再去找他。","现在，把这些粉末和露水混合在一起。等会儿再回来找我……那时我应该已经完成效力惊人的诺格弗格药剂了！","小武哥儿"},
[2681] = {"禁锢我们的石头","解救九个拉瑟莱克的仆从、三个瑟温妮的仆从、三个奥利斯塔的仆从和三个戈洛尔的仆从。完成任务后，回到部落英雄的灵魂这里。","要击败拉瑟莱克和他的手下，只靠你一个是不够的。召集一队勇士，让我的同伴摆脱永恒的折磨吧！你要打碎十八块石头。努力战斗吧，。","小武哥儿"},
[2701] = {"古代英雄","打开箱子，取走你的酬劳。","请把这些古老的遗物拿走吧，我们不再需要这些东西了。希望在你和燃烧军团的战斗中，它们能对你有所帮助。","小武哥儿"},
[2702] = {"古代英雄","和桑德·裂蹄谈一谈。","你用你高尚的行动和英勇的表现为我赢得了荣誉，。你也为他们赢得了荣誉……","小武哥儿"},
[2721] = {"基利斯","找到基利斯的下落。","你已完成了一次冒险，现在又有新的冒险在等着你，。我有个手下至今下落不明，他应该在诅咒之地的某个地方，我说的就是基利斯中尉。我告诉过你，我和他当时被奥利斯塔囚禁起来严刑拷打，可怜的基利斯……他的意志力变得越来越薄弱。在我的牢房里都能听到他受刑的声音，他的惨叫在山洞里回荡。那是我最后一次听见基利斯的声音。","小武哥儿"},
[2741] = {"超级测蛋器","","","小武哥儿"},
[2742] = {"林吉被困住了！","护送林吉逃出奎尔丹尼小屋，然后在望海崖找到他藏起来的东西。","嘿，那边的<种族>！请你帮林吉逃出去，我知道像你这样的<种族>不喜欢林吉，不过林吉求你了！我要逃出去！如果<种族>帮林吉逃出这里，<种族>就可以得到一些好东西……林吉在望海崖藏了个大秘密。","小武哥儿"},
[2743] = {"黑暗笼罩","回去见部落英雄的灵魂，将你的发现告诉他。","我们都别拐弯抹角了，<职业>，我的时间有限。你必须摧毁保护恶魔之王拉瑟莱克的三大魔头的势力。这个任务可不像解救一个被诅咒的灵魂那样简单。<基利斯咧开嘴大笑着>。你要知道，拉瑟莱克的三个手下各自戴着一件由拉瑟莱克特制的护符的三分之一。有了这个护符，你才能召唤那个恶魔。回去见特雷博，告诉他需要什么东西才能召唤拉瑟莱克，他会给你进一步的指示。","小武哥儿"},
[2744] = {"恶魔猎手","与艾萨拉的洛拉姆斯·萨里比迪斯谈一谈。","那三个魔王受到拉瑟莱克的保护。为了让他们忠诚地为他效力，拉瑟莱克使他们在诅咒之地可以使用几乎无限的力量。他们佩带的护符和他们的命运联系在一起，并使他们变得不老不死。只要他们待在诅咒之地，你就没法杀了他们，他们的生命力可以维持到世界末日。我认识一个也许可以帮助你的朋友，。到艾萨拉地区的小岛上去找恶魔猎手洛拉姆斯·萨里比迪斯谈谈吧。","小武哥儿"},
[2745] = {"潜入城堡","与暴风城堡的泰里恩谈一谈。","嗯，真是个有趣的故事，而且我们还要认真对待它。好吧，我可以帮你，但如果你想成功的话，就必须采用某种……正义而非法的手段。我们要赶快解决莱斯科瓦和马尔松，你认为你能胜任吗？你必须下定决心，到城堡里去找我的一个老朋友，一个名叫泰里恩的侏儒。几星期来他一直在监视着莱斯科瓦，他可以帮你解决这件事。","小武哥儿"},
[2746] = {"必备物品","将3块丝绸和2只克拉拉的新鲜苹果交给暴风城的泰里恩。","提亚斯要加快实施计划了吗？好吧，我们可以做到，不过我还没准备好。你知道，我要做的是最困难的部分，而你是负责动手的人，明白吗？很好。我要让你先帮我准备些东西，这样我就可以对间谍机器人进行伪装，让它安全地骗过那些守卫。给我带回一些丝绸和几只苹果来。丝绸你自己去找，不过城外那个克拉拉的小农场上有非常合适的苹果。","小武哥儿"},
[2747] = {"特别的蛋","","","小武哥儿"},
[2748] = {"优良的蛋","","","小武哥儿"},
[2749] = {"普通的蛋","","","小武哥儿"},
[2750] = {"坏掉的蛋","","","小武哥儿"},
[2751] = {"野人装甲","将2副青铜花纹护腕、2把青铜巨剑和2只锋利的爪子交给奥格瑞玛的奥罗克·沃姆什。","这只铁锤在沃姆什家族中传了二十代，。我们熔铸的铁有成千上万吨。不幸的是，这门技艺到了奥罗克手中却传不下去了，这是沃姆什家族的耻辱——我既没有亲属，又无法生育后代。决不能让沃姆什的祖传技艺和我一起死去！必须有人继承它，不管他是不是沃姆什家族的后裔！向奥罗克证明你的能力吧，。给奥罗克找来这些东西：两副青铜花纹护腕，两把青铜巨剑和两只锋利的爪子。把这些找来，我们再继续。","小武哥儿"},
[2752] = {"铁肩铠","将4把青铜战斧和4把青铜战锤交给奥格瑞玛的奥罗克·沃姆什。","奥罗克可以看出你眼中的渴望，。你像海绵一样渴望吸收沃姆什的智慧。我会教你三样东西！到铁砧那边去，感受熔炉的热量，为奥罗克铸造四把青铜战斧和四把青铜战锤，然后你才能学习制造铁肩铠。","小武哥儿"},
[2753] = {"踩在脚下","将4顶绿铁头盔、4副绿铁护腕和4副绿铁护腿交给奥格瑞玛的奥罗克·沃姆什。","奥罗克还剩两课要教给你，。我知道你的肌肉很疼，不过为了沃姆什家族，你还要继续！把四顶绿铁头盔、四个绿铁护腕和四个绿铁护腿拿来给奥罗克——你可以学到知识，你的敌人也会更加痛苦！","小武哥儿"},
[2754] = {"疯狂之角","将2只结实的铁锤、2双镀银青铜战靴和2副镀银青铜手套交给奥格瑞玛的奥罗克·沃姆什。","这是奥罗克教你的最后一课，。回到神圣的铁砧和锻炉旁去！将两只结实的铁锤、两双镀银青铜战靴和两副镀银青铜手套交给奥罗克。你会看到敌人眼中的恐惧！","小武哥儿"},
[2755] = {"沃姆什的喜悦","观察并学习沃姆什的喜悦之舞。","奥罗克没哭，，眼睛进了灰。<奥罗克偷偷地抹去一滴眼泪>还有一个沃姆什家族的秘密，奥罗克可以告诉你。多谢，奥罗克现在死而无憾了。学习沃姆什家族的喜悦之舞，然后你就掌握了锻造钢铁手套的技术！","小武哥儿"},
[2756] = {"古老的技艺","将4套钢质胸甲和4顶钢质头盔交给奥格瑞玛的铁砧阿图尔克。","很久以前，阿图尔克可以碾碎敌人的头颅，将他们的骨头磨成粉做灯丝……很久以前，<种族>。现在酋长号召各氏族和平相处。那些往日的敌人，现在我们只能用厌烦的眼光看着他们！我知道这很难以接受，不过这就是萨尔的意愿。实在是让我感到悲哀！你是来学习的，那你就学吧！给我拿四套钢质胸甲和四顶钢质头盔来，你可以在锻造它们的时候尝到战争的滋味！","小武哥儿"},
[2757] = {"藏宝海湾之旅！","与藏宝海湾的马克迦文谈一谈","听着，孩子，你在我这儿已经学不到什么东西了。我认识一个铁匠，他认识另一个优秀的铁匠……听起来有些混乱。你应该到藏宝海湾的铁匠铺去找他，只要你把这枚徽章交给他看看，他就会把有关秘银的知识都传授给你。怎么样？踏上真正的求知之旅吧，。如果你对此感兴趣的话，就去找马克迦文吧。别忘了给他看看这枚徽章。","小武哥儿"},
[2758] = {"锻造的本源","将6副金鳞护腕交给暴风城的巨锤汉克。","我像你这么大的时候，在一个名叫加尔文的矮人门下学习了铸造护甲的技术。在他离开这里前往藏宝海湾之前，曾让我向他许诺，要帮助训练所有决心在锻造这门技艺上学有所成的人——于是这么多年来，我一直在这么做。现在是时候让你学点新东西了。给我打造六套金鳞护腕，你就会知道锻造的本源是什么了，。","小武哥儿"},
[2759] = {"寻找加尔文","与藏宝海湾的马克迦文谈一谈。","虽然加尔文很多年前就离开了藏宝海湾，但镇子里还有一个秘银会的成员，希望能找到另一个值得加尔文亲自授业的铁匠。把这个徽章交给藏宝海湾的马克迦文。我相信，如果你能见到加尔文的话，他一定会非常器重你的！","小武哥儿"},
[2760] = {"秘银会","和荆棘谷的加尔文谈一谈。","我们招募的人几乎没有能平安抵达藏宝海湾的，。即使是意志最坚定的铁匠也难以抵挡这枚徽章的光芒，他们难免会产生私吞的贪念。他们都是傻瓜，因为与你即将得到的巨大财富相比，这枚徽章只是沧海一粟而已！去找到加尔文，把徽章交给他。他住在这里的北面，就在祖尔格拉布和莫什奥格食人魔山之间的地方。","小武哥儿"},
[2761] = {"铁匠必修课","将40块秘银锭和40块铁锭交给荆棘谷的加尔文。","很多铁匠都以为采矿和锻造是两件完全独立的事情，不过锻造能离得开采矿吗？啊哈——那是不可能的！成功的铁匠还必须得是成功的矿工。让加尔文看看你的能力吧，。 给我找40块铁锭和40块秘银锭来，然后加尔文就会教你打造精制密银短裤的方法！","小武哥儿"},
[2762] = {"白花花的银子","将40块秘银锭和5块真银锭交给荆棘谷的加尔文。","据说真银比秘银更坚固耐用，加尔文对这个说法没有什么异议，但是严格说起来，真银并不是真的！秘银比真银更加高贵！哈！不管怎么说，这一次，你要去收集一大堆银子来，。给我弄四十块秘银锭和五块真银锭来，作为交换，我会向你传授打造精制秘银手套的技艺，以及更为重要的，让你知道真银并不是真的！","小武哥儿"},
[2763] = {"灌魔工艺","将40块秘银锭和4块黄水晶交给荆棘谷的加尔文。","搜寻珍贵的宝石对我们来说是最重要的，。很少有比黄水晶更为珍贵的宝石。有了黄水晶，我们就能将注入各种装备中的魔法特性得到大幅度提升。这一课，我们要用四块黄水晶加强四十块秘银锭，这将使你更加了解神奇的宝石学，并学会如何制造精制秘银护肩。","小武哥儿"},
[2764] = {"加尔文的得意门生","和加基森的特伦顿·轻锤谈一谈。","如果你准备要结束在加尔文这里的训练课程，就应该到加基森去。在那儿有我最得意的学生：特伦顿·轻锤。他可以教你很多有关精制秘银装备的知识，当然你也可以留在这里继续学习！哦，对了，加基森在塔纳利斯沙漠里！","小武哥儿"},
[2765] = {"锻造专家！","到加尔文那里拿取报酬！","你刚来的时候，我就知道你会成为我最出色的学生之一！你毫不犹豫地把这个有魔力的饰品交给了马克迦文，因此你才有了来见我的资格。你的全心奉献和坚定信念应该得到回报。你已经在锻造技艺方面取得了长足的进步，。拿上你的回报吧！","小武哥儿"},
[2766] = {"寻找OOX-22/FE！","把定位器带到深痕谷附近山洞中的奥格索普的导航机器人旁边。","你发现了一个奇怪的蛋形金属物体。随便拨弄了几下之后，它居然自动打开了，变成了一个看来是由侏儒制造的机器装置！一个奇怪的声音从这个蛋形机器装置中传了出来。“我的名字叫奥格索普，我的母体机器人不见了！如果你能帮我找到它，我就会奖励你的！请把这个定向器带到那个母体机器人那里。别担心，我现在已经检测到了它的所在地！它现在就位于深痕谷中的一个山洞里！”","小武哥儿"},
[2767] = {"拯救OOX-22/FE！","护送OOX-22/FE到安全地点，然后向藏宝海湾的奥格索普·奥布诺提斯回报。","那个地精的声音再次从那个机器人中传了出来:“我需要你帮忙把OOX-22/FE移动到一个开阔的安全地点，这样它才可以启动起飞程式。它拥有内建的隐蔽系统，但是我需要一点时间从远端来启动这个系统。请你把这个机器人从现在的位置护送到主要的道路上！那是个非常理想的起飞点，而且护送的路程也可以给我足够的时间来启动连线！”“将它安全地护送到那里，然后再到藏宝海湾来找我！奥格索普·奥布诺提斯─完毕！”","小武哥儿"},
[2768] = {"探水棒","把探水棒交给加基森的首席工程师沙克斯·比格维兹。","布莱中士偷了我的东西！他说只是借一下，但那混蛋却偷了我宝贵的探水棒！没有这根棒子，我就不知道该在哪里打井找水！去找到布莱，把我的探水棒拿回来！我听说他带着一帮恶名远扬的冒险者去了西边的祖尔法拉克古城寻宝，你肯定可以在那里找到他。但愿那里的巨魔已经把他干掉了，因为如果你必须打败他才能拿回探水棒的话，那必将是一场恶仗。","小武哥儿"},
[2769] = {"铜栓兄弟","和闪光平原的维兹尔·铜栓谈一谈。","你有没有遇见铜栓兄弟？他们在卡利姆多的闪光平原上与地精赛车，而且他们通常都会获得胜利，这并不奇怪——地精的赛车轮胎总是爆掉，他们几乎从来都没有完成过比赛！但即使是这样，铜栓兄弟也还是在寻找新的方法使他们的车速更快，维兹尔跟我说过，他的下一个实验需要一种很稀有的原料。或许他需要别人的帮助来获取这种原料，你去和他谈谈就知道了。","小武哥儿"},
[2770] = {"加兹瑞拉","把加兹瑞拉的鳞片交给闪光平原的维兹尔·铜栓。","在塔纳利斯沙漠的巨魔古城祖尔法拉克深处，有一个神圣的池塘。巨魔可以从那个池塘里召唤一头巨大的野兽——加兹瑞拉！它凶猛异常，甚至连它的鳞片都会因为巨大的能量而发出声响。我要用它的能量来给我的赛车增加动力！把加兹瑞拉的鳞片给我弄来！不过，召唤加兹瑞拉的方法是巨魔的秘密。如果你想要面对加兹瑞拉的话，首先就要从巨魔那里弄到召唤它的方法。","小武哥儿"},
[2771] = {"罩帽和护肩","将2顶秘银罩帽和1副精制秘银护肩带秘银护肩交给特伦顿·轻锤。","看来师傅一开始就计划好了。你学会制造的东西都是我不会的，而我学会的那些你也不会。师傅很聪明，。这样我们就可以互相学习了！你教我如何制造秘银罩帽和精制密银护肩，然后我再教你制造精制密银头盔，如何？","小武哥儿"},
[2772] = {"世界在你脚下","将2双秘银重靴和1条精制秘银短裤交秘银短裤交给特伦顿·轻锤。","在去年的全谷铁匠冠军赛里，我在众目睽睽之下被一个来自风险投资公司的卑鄙家伙用扫堂腿放倒在地。但是他们却不知道我为什么还能继续站在那里完成比赛，并取得冠军。答案就是——没错，精制秘银战靴！如果今年我还想取胜的话，就得学会精制秘银短裤的制作方法，因为这次会有一个风险投资公司的伐木工参加比赛！教我制作短裤，我就教你制作靴子，怎么样？","小武哥儿"},
[2773] = {"秘银小子","将2件重型秘银胸甲和1副精制秘银手套带给特秘银手套交给特伦顿·轻锤。","我被大家称作秘银小子。我给来自世界各地的冒险者们提供精制秘银装备。<特伦顿悄悄地说。>但是没几个人知道我根本不会打造精制秘银手套。嘘！这是你我之间的小秘密。如果你教我如何打造精制秘银手套的话，我就把从加尔文那里学来的手艺传授给你——精制秘银胸甲的制作方法！","小武哥儿"},
[2781] = {"通缉：卡利夫·斯科比斯汀","将卡利夫·斯科比斯汀的头颅交给加基森的首席工程师沙克斯·比格维兹。","通缉：卡利夫·斯科比斯汀！\n$塔纳利斯的加基森水力公司愿支付高价悬赏废墟歹徒首领卡利夫·斯科比斯汀的项上人头。他的罪行包括：1. 杀害加基森水力公司的雇员！\n2. 偷窃加基森水力公司的资源！\n3. 抢劫加基森水力公司的财产！将卡利夫·斯科比斯汀的死亡证明交给首席工程师沙克斯·比格维兹，我们将立刻兑现你的奖赏！","小武哥儿"},
[2782] = {"林吉的秘密","奥兰·斯内克威瑟是个学者，她对枯木巨魔很有研究，也许她可以帮你看看这块石板。奥兰就住在幽暗城的魔法区里。","这块石板上布满了枯木巨魔的印记。林吉的秘密真是难以猜测……或许你手头上的东西非常宝贵。当然，这东西也很有可能一文不值。悲伤中的枯木巨魔为了摆脱困境什么事情都干得出来……","小武哥儿"},
[2783] = {"争论","与诅咒之地和悲伤沼泽交界处的部落英雄的灵魂谈一谈。","我们在和错误的敌人进行战斗，。这片土地上真正强大的力量正在不断增强，而我们却还在和兽人为了这片焦土进行无谓的争斗。我们难道要继续这种争斗，直到有一天让燃烧军团把我们都踏扁吗？这实在是一种愚蠢的行为。，抛开你的偏见，和部落英雄的灵魂谈谈吧，他知道诅咒之地真正的秘密。","小武哥儿"},
[2784] = {"失落的荣耀","聆听部落英雄的灵魂讲述他的故事。","请听听我的故事，<种族>。","小武哥儿"},
[2801] = {"悲伤的故事","聆听部落英雄的灵魂讲述他的故事。","请你一定要先听听我的故事。","小武哥儿"},
[2821] = {"质量的保证","给羽月要塞的普拉特·马克格鲁比带去10张厚重的雪人皮。","我对于皮革制作的哲学是要做就做最好——没有商量余地。任何说质量不要紧的人都是想要把丹莫罗的那些水货卖给你！在寻求高质量材料的过程中，我接触到了厚重的雪人皮。雪人是菲拉斯土生土长的一种生物，大多在深痕谷活动。我需要一些它们的皮，如果你给我十张的话，我可以让你在我的皮货中选一件。如果你觉得听起来还算公平，那我们就成交了吧。","小武哥儿"},
[2822] = {"质量的保证","给莫沙彻营地的杉多尔·迅蹄带去十张厚重的雪人皮。","我为自己制作的皮革作品感到骄傲，它们也值得我骄傲，质量是永不可能妥协的东西。任何说质量不要紧的人都是在信口乱说！在寻求高质量材料的过程中，我接触到了厚重的雪人皮。雪人是菲拉斯土生土长的一种生物，大多在深痕谷活动。我需要一些它们的皮，如果你给我十张的话，我可以让你在我的皮货中选一件。如果你觉得听起来还算公平，那我们就成交了吧。","小武哥儿"},
[2841] = {"设备之战","从诺莫瑞根拿到钻探设备蓝图和麦克尼尔的保险箱密码，把它们交给奥格瑞玛的诺格。","侏儒的技术——两年前它最普遍的用途是被当作笑话，但是时代确实变了，现在他们建造的新型钻探设备比我们所有伐木机加起来都要精密。我需要它的设计图，！不幸的是，这些设计图被锁在麦克尼尔·瑟玛普拉格身边的一只保险箱里了。更糟的是，保险箱的密码只有麦克尼尔·瑟玛普拉格一人知道。尽你所能得到那个密码，。把设计图给我带回来！","小武哥儿"},
[2842] = {"主工程师斯库提","和藏宝海湾的斯库提谈一谈。","斯库提和我刚刚从克努比那里得到关于新型侏儒钻探设备的消息，就马上开始动手研制捷运器6000型了，它是去诺莫瑞根最快捷可靠的方法！现在它已经完成了，。如果你想试试的话，就到藏宝海湾去和空运处的斯库提谈谈吧。你可以从棘齿城乘船去藏宝海湾。当然，你也可以试试从满地都是矮人的丹莫罗山脉走到诺莫瑞根去！","小武哥儿"},
[2843] = {"出发！诺莫瑞根！","等斯库提调整好地精传送器。","只要你有传送器，你所要做的就只是踩上踏板，然后就会被传送到诺莫瑞根！你可能会有一些不适感，但这些副作用应该都不是永久的……我几乎忘了最重要的部分——如何回来。当你准备好要回来时，只要在诺莫瑞根踩上传送器的踏板就行了！现在请把传送器按照你的体型和体重做一些调整。","小武哥儿"},
[2844] = {"大保姆","寻找走丢了的精灵小姑娘。","都是我不好，。我本应细心照顾我的小朋友，沙恩。但是不知道为什么，她离开了我。我并不十分清楚发生了什么事，真的，但我最后一次看到她的时候，我们正在穿越这里北面的废墟。一切都很正常，但我转过身一看……她就不见了。现在我不知道该怎么办了。你有办法吗，？我很担心。嘿，你帮我去找沙恩怎么样？你看上去应该比我跑得快一些。","小武哥儿"},
[2845] = {"迷路的沙恩","从箱子里拿取沙恩的铃铛，然后护送沙恩·飘叶回到罗克比特的营地。","你能带我回到我的朋友罗克比特身边吗？他本来是要照看我的……但我总是不知不觉之间就迷路了。这里有这么多好看的东西，我东看看西看看就不知道该怎么走了。但是有一样东西可以一直吸引我的注意力。在这个箱子里有一只对我来说最为珍贵的铃铛，我就喜欢听它的声音。我保证，如果我走失了，只要你摇响铃铛，我就会马上跑回来。","小武哥儿"},
[2846] = {"深渊皇冠","将深渊皇冠交给尘泥沼泽的塔贝萨。","很久以前我曾经拥有一件美丽的珍宝，深渊皇冠。它不仅美丽——而且它对于知道怎么使用它的人来说更是一件拥有巨大力量的宝贝。所以当水占师维蕾萨听说皇冠的事情之后，她就发誓要得到它。维蕾萨派人在我外出的时候到我家来偷走了皇冠，这些卑鄙的小偷！我要取回我的皇冠！到位于塔纳利斯沙漠中的巨魔城市祖尔法拉克去，把皇冠从她手上抢回来。把它还给我，你会得到报酬的。","小武哥儿"},
[2847] = {"蛮皮护甲","给羽月要塞的普拉特·马克格鲁比带去10块厚皮。","$n，你已经是个很熟练的制皮匠了！我知道一些装备的制作方法，你可能会感兴趣……那就是蛮皮护甲！蛮皮中包含了野葡萄的混乱而强大的力量，你可以在这片茂盛的森林中找到这种植物，也可以在森林中的某些动物身上找到。用它制作的装备简直是无以伦比！我会把制作蛮皮护甲的方法教给你，条件是你要为我做点事情。首先你得给我带十块厚皮来，等你拿来十块厚皮之后我们再详谈。","小武哥儿"},
[2848] = {"蛮皮护肩","给羽月要塞的普拉特·马克格鲁带去6片厚重护甲片和1株野葡萄。","蛮皮护肩能够很好地支撑穿戴者的身形，为其上臂和肩部提供了极好的保护。和所有的蛮皮护甲一样，制作时所使用的野葡萄会使其附带一种强大的随机魔法效果。如果你想要这种护甲的图样，就给我弄六块厚重护甲片和一株野葡萄来，这对你来说应该不算什么过分的要求。","小武哥儿"},
[2849] = {"蛮皮外衣","给羽月要塞的普拉特·马克格鲁带去2件龟鳞胸甲、2副龟鳞手套和1株野葡萄。","蛮皮外衣是蛮皮护甲中最主要的部分，它的结构以及编织于其中的野葡萄能使其在具有很强的保护作用的同时，还附带着强大的魔法力量。B如果你想要这种护甲的图样，就给我弄两件龟鳞胸甲、两副龟鳞手套和一株野葡萄来。这不是件容易的活儿，但你一定可以完成它。","小武哥儿"},
[2850] = {"蛮皮头盔","给羽月要塞的普拉特·马克格鲁比带去2件夜色外套、2条夜色头巾和一株野葡萄。","蛮皮头盔可以为你的头部提供极好的保护，与此同时，它也具有相当的舒适性。和所有的蛮皮护甲一样，制作头盔时使用的野葡萄会使它产生一种强大的随机魔法效果。对于穿着皮甲的人来说，这东西可是非常不错的！想要得到这顶头盔的图样的话，就给我带两件夜色外套、两条夜色头巾和一株野葡萄来。完成这个任务之后，图样就是你的了！","小武哥儿"},
[2851] = {"蛮皮战靴","给羽月要塞的普拉特·马克格鲁带去2条夜色裤、2双夜色靴和2株野葡萄。","你现在已经学到了很多东西，$n，但你仍有更多的东西要学习。现在我们来谈谈蛮皮战靴，它是这一套装备的基石。这种靴子舒适合脚，可以让你的双脚在长途跋涉之后仍然轻松自如。柔软的鞋底对于那些喜欢悄悄行动的人来说再合适不过了。如果你想要得到它的图样，就给我拿两条夜色短裤和两双夜色长靴来。另外我还需要两株野葡萄……只有一株的话可不够。拿到以上这些东西之后，就把它们交给我。","小武哥儿"},
[2852] = {"蛮皮护腿","给羽月要塞的普拉特·马克格鲁比带去2顶龟鳞头盔、2副龟鳞护腕和2株野葡萄。","基础教程已经完成，你应做好准备掌握更为复杂的制作了，$n。蛮皮护胫是最坚硬和强大的皮制系列装备中的一样。野兽系列皮装备让你的胸部，大腿，小腿和其他致命的部位都被保护起来。再加上野葡萄所起的辅助作用，拥有这种装备的冒险者一定会永远感谢你的。如果你想要得到这个图样的话，带给我两顶龟鳞头盔，两付龟鳞护腕和两株野葡萄。","小武哥儿"},
[2853] = {"蛮皮护甲大师","将普拉特的信交给达纳苏斯的制皮大师泰龙尼斯。","好吧，$n，你就是勤奋的楷模。蛮皮护甲只剩下一种式样你还没有学会了。我不会要求你为最后的式样无谓地浪费时间和精力，你可以直接得到它，还有一些……但我不能自己传授给你。我的老师，就是带我进入这一行的人，他会教你怎么做。把这封信交给泰龙尼斯，他在达纳苏斯教授皮革制作的工艺。给他看这封信，让他像我一样认同你。","小武哥儿"},
[2854] = {"蛮皮护甲","给莫沙彻营地的杉多尔·迅蹄带去10块厚皮。","$n，你已经是个很熟练的制皮匠了！我知道一些装备的制作方法，你可能会感兴趣……那就是蛮皮护甲！蛮皮中包含了野葡萄的混乱而强大的力量，你可以在这片茂盛的森林中找到这种植物，也可以在森林中的某些动物身上找到。用它制作的装备简直是无以伦比！我会把制作蛮皮护甲的方法教给你，条件是你要为我做点事情。首先你得给我带十块厚皮来，等你拿来十块厚皮之后我们再详谈。","小武哥儿"},
[2855] = {"蛮皮护肩","给莫沙彻营地的杉多尔·迅蹄带去6块厚重护甲片和1株野葡萄。","蛮皮护肩能够很好地支撑穿戴者的身形，为其上臂和肩部提供了极好的保护。和所有的蛮皮护甲一样，制作时所使用的野葡萄会使其附带一种强大的随机魔法效果。如果你想要这种护甲的图样，就给我弄六块厚重护甲片和一株野葡萄来，这对你来说应该不算什么过分的要求。","小武哥儿"},
[2856] = {"蛮皮外衣","给莫沙彻营地的杉多尔·迅蹄带去2件龟鳞胸甲、2副龟鳞手套和1株野葡萄。","蛮皮外衣是蛮皮护甲中最主要的部分，它的结构以及编织于其中的野葡萄能使其在具有很强的保护作用的同时，还附带着强大的魔法力量。B如果你想要这种护甲的图样，就给我弄两件龟鳞胸甲、两副龟鳞手套和一株野葡萄来。这不是件容易的活儿，但你一定可以完成它。","小武哥儿"},
[2857] = {"蛮皮头盔","给莫沙彻营地的杉多尔·迅蹄带去2件夜色外套、2条夜色头巾和1株野葡萄。","蛮皮头盔可以为你的头部提供极好的保护，与此同时，它也具有相当的舒适性。和所有的蛮皮护甲一样，制作头盔时使用的野葡萄会使它产生一种强大的随机魔法效果。对于穿着皮甲的人来说，这东西可是非常不错的！想要得到这顶头盔的图样的话，就给我带两件夜色外套、两条夜色头巾和一株野葡萄来。完成这个任务之后，图样就是你的了！","小武哥儿"},
[2858] = {"蛮皮战靴","给莫沙彻营地的杉多尔·迅蹄带去2条夜色短裤、2双夜色长靴和2株野葡萄。","你现在已经学到了很多东西，，但你仍有更多的东西要学习。现在我们来谈谈蛮皮战靴，它是这一套装备的基石。这种靴子舒适合脚，可以让你的双脚在长途跋涉之后仍然轻松自如。柔软的鞋底对于那些喜欢悄悄行动的人来说再合适不过了。如果你想要得到它的图样，就给我拿两条夜色短裤和两双夜色长靴来。另外我还需要两株野葡萄……只有一株的话可不够。拿到以上这些东西之后，就把它们交给我。","小武哥儿"},
[2859] = {"蛮皮护腿","给莫沙彻营地的杉多尔·迅蹄带去2顶龟鳞头盔、2副龟鳞护腕和2株野葡萄。","看来你已经准备好学习更加复杂的课程了，。蛮皮护胫是最坚硬和强大的皮制系列装备中的一样。野兽系列皮装备让你的胸部，大腿，小腿和其他致命的部位都被保护起来。再加上野葡萄所起的辅助作用，拥有这种装备的冒险者一定会永远感谢你的。如果你想要得到这个图样的话，带给我两顶龟鳞头盔，两付龟鳞护腕和两株野葡萄。","小武哥儿"},
[2860] = {"蛮皮护甲大师","将杉多尔的信交给雷霆崖的制皮大师犹纳。","，我能教你的你已经全部都学会了。蛮皮护甲只剩下一种式样你还没有学会了。我不会要求你为最后的式样无谓地浪费时间和精力，你可以直接得到它，还有一些……但我不能自己传授给你。我的老师，就是带我进入这一行的人，她会教你该怎么做的。带这封信给犹纳；她在雷霆崖教授皮革制作。给她看这封信，让她像我一样地认同你。","小武哥儿"},
[2861] = {"塔贝萨的任务","与尘泥沼泽的塔贝萨谈一谈。","据说有个名叫塔贝萨的法师想要某个祖尔法拉克巨魔的命。如果你去找塔贝萨的话，她会让你知道详情的。别忘了带上几个伙伴，$n。如果塔贝萨真的让你去祖尔法拉克的话，你最好不要独自前往。塔贝萨的小屋就在尘泥沼泽里，准确地说，是在塞拉摩的西边，石槌废墟的北边。","小武哥儿"},
[2862] = {"与豺狼人开战","将10份木爪豺狼人的鬃毛交给莫沙彻营地的哈杜肯·迅蹄。","豺狼人……它们现在不再只是一个小麻烦了，它们已经对我们形成了巨大的威胁！这些豺狼人是不是菲拉斯的原住民已经不重要了；如果我们无法有效地对抗它们，那我们早晚都会被赶出这个地区的。豺狼人最近对营地的攻势愈演愈烈，因此我们需要你的帮助来削弱它们的数量。带给我十份豺狼人的鬃毛，我会为你付出的努力而给予优厚的报酬。赶快出发吧！","小武哥儿"},
[2863] = {"突然袭击","在1个小时内杀死5个木爪突击队员，并向哈杜肯·迅蹄汇报。","我们计划在很短的时间里拿下豺狼人的领导者——按他们自己的说法是突击队员。如果我们顺利地执行了这个计划……不仅他们的内部会出现混乱，而且这也会向他们愚蠢的脑袋传达一个信息，那就是我们有能力而且必将消灭他们！我想让你成为传达这个信息的使者，你必须在一小时内消灭五个突击队员，否则我们还会处于这种僵局中。","小武哥儿"},
[2864] = {"特兰雷克","与加基森的特兰雷克谈一谈。","我的兄弟特兰雷克现在显然处于困境中。几个星期之前他曾经向我承诺会给我一批圣甲虫的壳，但是至今为止我还没有收到。他是我的兄弟，所以我可不想派人去加基森砸他的场子。你能帮我去问问特兰雷克到底是怎么回事吗？在我真的发飙之前他最好快点把货给我送来。加基森就在卡利姆多大陆上的塔纳利斯沙漠北部。","小武哥儿"},
[2865] = {"圣甲虫的壳","给加基森的特兰雷克带去5个完整的圣甲虫壳。","塔纳利斯这里的圣甲虫的壳都很硬！硬得足可以给好多东西当建筑材料，好多东西！事实上，因为那些壳都太有用了……圣甲虫已经被猎杀得近乎灭绝了！我知道哪里有更多的圣甲虫，如果你保证会给我弄些壳来，我就告诉你它们在哪里。你保证吗？好吧，祖尔法拉克里面有许多圣甲虫，我想巨魔们并不因为想要那些壳而猎杀它们。但你可以！到祖尔法拉克去给我弄些完好无损的壳回来！","小武哥儿"},
[2866] = {"索兰萨尔废墟","探索索兰萨尔废墟，并调查纳迦在那个地区的情况。","在我们的南边就是索兰萨尔废墟，那个地区的历史相当悠久。我们探索过那个遗迹，没有发现什么特别值得注意的东西，所以我们就离开了。最近，憎世纳迦占据了那片遗迹，而且他们的数量已经多到了让我们不得不警惕的程度。一开始我们认为那些纳迦是准备对我们发起攻击，虽然这种可能性现在依然存在，但我们觉得他们可能是有什么别的目的。现在就到那片废墟去查看一番吧，祝你好运，$n。","小武哥儿"},
[2867] = {"返回羽月要塞","向羽月要塞的珊蒂斯·羽月汇报你的发现。","在索兰萨尔废墟的心脏地带发现了奇怪的瞭望台之后，你觉得应该马上回到羽月要塞去向珊蒂斯·羽月汇报这个发现。","小武哥儿"},
[2868] = {"<TXT> The Shriveled Heart","","Turn this badboy into some troll tomb in the Sunken Temple, and get something cool！","小武哥儿"},
[2869] = {"憎世纳迦之战","收集10块憎世纳迦的鳞片，把它们交给羽月要塞的拉托尼库斯·月矛。","我们认为，无论纳迦想要干什么，他们最终的目的无非是完全占据这座岛屿，由此我们制定了相应的行动计划。我们要尽早采取攻击行动来消除这种威胁，否则就可能全盘皆输。给我带来十块完整的憎世纳迦的鳞片——你应该知道如何获得这东西。这样一来，纳迦在萨尔多岛上的力量就被大大削弱了，这对我们是非常有利的。","小武哥儿"},
[2870] = {"击败沙尔扎鲁","消灭沙尔扎鲁，然后把神秘遗物交给羽月要塞的拉托尼库斯·月矛。","$n，新的侦查报告让我们对纳迦部队的组成有了一个更清晰的概念。纳迦的皇室成员在他们的部队中具有最高的权威性。皇室成员中的沙尔扎鲁是个极端残酷的纳迦，侦查报告表明最近他在南部的遗迹中发现了一块奇怪的古代遗物，那个地方就在恐怖之岛那里。你的任务就是结果他，然后把那块遗物给我带回来进行研究。","小武哥儿"},
[2871] = {"递送遗物","将神秘遗物交给羽月要塞的维斯提亚·月矛。","如果你能帮我将这个东西送给我的妻子维斯提亚，那我会非常感激的。她不仅是我们这里的女祭司，也会是你所见过的最博学的学者之一。我即使抓破头皮也搞不清楚这个东西到底是什么，可我的妻子不同，如果世界上有人能知道这东西是什么，那无疑就是她了……我们也迫切地需要知道真相！拜托了，$n。","小武哥儿"},
[2872] = {"斯杜雷的债务","与热砂港的斯杜雷谈一谈。","我的老朋友欠我一瓶特殊的朗姆酒。他在塔纳利斯沙漠的热砂港里经营着一家酒吧，他向我保证说，那里的朗姆酒绝对比藏宝海湾的任何酒都要香醇，还说如果我喝了他的酒不满意的话，那他就会双倍奉还他欠我的钱！好吧，我想他现在已经不像他上次说这话的时候那么自信了，他害怕给我尝他的朗姆酒了。但是我还是想继续这个赌注，那么你就替我去和他谈谈吧……","小武哥儿"},
[2873] = {"斯杜雷的货物","将斯杜雷的货物交给热砂港的斯杜雷。","我欠藏宝海湾的“海狼”马克基雷一些朗姆酒，那是打赌输的，但我现在一瓶朗姆酒都没有了！科尔戈船长偷了我最后一船货，他把它们藏在南边的那个戒备森严的海盗镇里。如果你能找到我的那批朗姆酒并把它们给我拿回来的话，那我就可以向马克基雷证明，藏宝海湾的那些酒跟我的朗姆酒比起来只能被称作垃圾！","小武哥儿"},
[2874] = {"给马克基雷的货物","将斯杜雷的瓶子交给藏宝海湾的“海狼”马克基雷。","再次感谢你的帮助，。这里有一瓶热砂港朗姆酒。把它交给马克基雷，这样他就可以抛弃藏宝海湾烈酒，改喝热砂港朗姆酒了！","小武哥儿"},
[2875] = {"通缉：安德雷·费尔比德","将安德雷的头颅交给热砂港的安全主管吉罗姆·比格维兹。","可恶的海盗安德雷·费尔比德因对热砂港和加基森所犯的罪行正被通缉。根据政府讨论所发布的决议，任何阅读这则通缉令的人有权在逮捕安德雷和他的同党过程中采取可能致其死亡的手段。进一步的决议表明，如在审讯期间，安德雷死了或病了，他的人头可以作为代替品，将它交给安全主管吉罗姆·比格维兹仍将使这份通缉令生效。","小武哥儿"},
[2876] = {"船运时刻表","把船运时刻表交给热砂港的某个官员。","这卷轴上面记载着热砂港和藏宝湾之间的船运时刻表，包括过去和未来计划中的船运批次和船名，一些船的旅程旁有个大大的红叉记号，剩下的旁边有类似“华丽的战利品”和“坚固的战舰”之类的字样。热砂港那里的人一定非常想看看这个文件。","小武哥儿"},
[2877] = {"清理隐匿石","杀掉10个绿色淤泥怪和10个玉石软泥怪，然后回到鹰巢山向弗拉加尔报告。","比起那些铁炉堡的兄弟们来，我们蛮锤氏族对于过去曾发生过的事情有着更加深刻的记忆。如果你想在这里交朋友的话，那么你就要证明给我们看！部落的蛮子们从隐匿石一带撤了出去，现在那里满地都是淤泥怪。我们想要占领那个地区，不过首先我们要找些人来帮我们清理一下恼人的淤泥怪。这就是你要做的事情了！到那边去干掉十个绿色淤泥怪和十个玉石软泥怪，然后回到这里来向我报告。快出发吧！","小武哥儿"},
[2878] = {"被腐化的轻歌花","","","小武哥儿"},
[2879] = {"艾奎尼克斯法杖","给特洛亚斯的法杖注入能量，并找到艾奎尼克斯石碑。","看来这根法杖可能就是艾奎尼克斯法杖了。它事实上是把钥匙，你可以用它打开位于北方废墟中的艾奎尼克斯石碑。找到仍在那片废墟中燃烧的四团烈火：萨姆哈之焰、拜尔坦之焰、伊姆贝尔之焰和莱哈萨之焰。从这些火焰那里采集它们的精华。然后在艾奎尼克斯石碑旁使用这些精华，把它们的能量注入法杖。如果这真的是艾奎尼克斯法杖的话，你就可以打开石碑，并得到存放在里面的古物。","小武哥儿"},
[2880] = {"巨魔氏族项链","给鹰巢山的弗拉加尔带去5条巨魔氏族项链。","直接说吧，<职业>——我们不属于联盟！蛮锤氏族是独立的，我们依靠自己所做的事情来证明自己的价值，不像那些只会说废话的家伙一样，用闲聊来掩饰自己什么都不想做的态度！如果你要和我们作朋友，那么首先向我们证明你的价值！那些遍布辛特兰的巨魔有时会带着他们氏族的项链。给我带五条项链过来作为友好的证明吧！","小武哥儿"},
[2881] = {"巨魔氏族项链","","","小武哥儿"},
[2882] = {"科尔戈的黄金","找到科尔戈的黄金！","这张地图上画着一条对着南方的海滩，图下面用优雅的字体写着……\n热砂港南边\n家的南边\n找到骨头，旗子和旗杆\n如果你够胆，就去挖挖看\n挖挖看啊，科尔戈的金子光灿灿！\n开箱需钥匙，钥匙你会看见\n你面对的要用血来做交换。","小武哥儿"},
[2902] = {"调查木爪岭","在莫沙彻营地以南的豺狼人营地中寻找豺狼人的战斗计划。","豺狼人不是菲拉斯最具威胁的势力，但它们最近的活动毫无疑问是有些具体战略的。如果我们能找到它们的计划，那么我们就能知道究竟是什么让它们变得如此精明。我要你回到木爪岭去，寻找任何有可能是它们的战斗计划的东西。他们一定有些这样的东西，因为它们的攻击行动太协调了，没有一个像样的战斗计划是不可能进行的。找到那东西，然后再回到我这里来。","小武哥儿"},
[2903] = {"作战计划","把木爪豺狼人的作战计划交给莫沙彻营地的哈杜肯·迅蹄。","既然我们已经发现了豺狼人的作战计划，接下来要做的就是把计划交给莫沙彻营地的哈杜肯·迅蹄。他或者那儿的其他什么人也许可以进一步弄清楚豺狼人到底想要做什么。","小武哥儿"},
[2904] = {"一团混乱","将克努比护送到出口，然后向藏宝海湾的斯库提汇报。","<克努比呻吟着>发……发生什么事了？我只记得自己被一队黑铁矮人抓住了，他们暴打了我一顿，把我跟这些丑陋的穴居人扔在一块儿。快救我出去，！我有个计划：把我带到出口，如果我们能活着走出去的话，你就到藏宝海湾去，告诉斯库提我去了棘齿城，然后警告廷克维斯，黑铁矮人准备制造超强的钻探设备。让我们开始吧！","小武哥儿"},
[2922] = {"拯救尖端机器人！","将尖端机器人的存储器核心交给铁炉堡的工匠大师欧沃斯巴克。","当我们挚爱的诺莫瑞根城沦陷时，我可怜的发明——尖端机器人——受到了某种致命的打击。它原本包含了很多精巧的设计，并且储存了大量的信息，凭借这些，它无数次地帮助了我和我的同事，但现在它的正电子脑被极化，变成了负电子脑……尖端机器人的行为已经变得完全异常了。它像个疯子似的在诺莫瑞根里咆哮！也许我们仍然可以挽救它，如果你能找回尖端机器人的存储器核心并把它交给我，那么我就能找到故障的原因，然后把我可怜的尖端机器人修好。","小武哥儿"},
[2923] = {"工匠大师欧沃斯巴克","与铁炉堡的工匠大师欧沃斯巴克谈一谈。","工匠大师欧沃斯巴克正在为他发明的尖端机器人的命运感到沮丧。我记得尖端机器人对侏儒来说是一种很友好的辅助工具，但欧沃斯巴克告诉我，它出了故障。我很难过，不过如果运气不错的话，也许他还可以修好尖端机器人！去跟铁炉堡侏儒区的工匠大师欧沃斯巴克谈谈吧，看到有你这样的<职业>想要帮助他，他会很高兴的。","小武哥儿"},
[2924] = {"基础模组","收集12个基础模组，把它们交给铁炉堡的科劳莫特·钢尺。","有一种通用型的机械部件——基础模组——对于诺莫瑞根的技师和铁匠来说都非常重要，不过在我们大举逃出诺莫瑞根的时候，谁也没想起要把这些东西带上！我手头上的工作需要大量这种部件。请去诺莫瑞根给我拿一些基础模组回来，它们就装在城市深处的机械储存柜里。谢谢你，，请尽快出发吧！","小武哥儿"},
[2925] = {"帮助科劳莫特","与铁炉堡的科劳莫特·钢尺谈一谈。","我的侏儒朋友科劳莫特·钢尺从铁炉堡给我捎了个信过来，说是要我找人去完成一项很危险但也很重要的任务：潜入诺莫瑞根。现在这座壮观的侏儒城市里到处都是疯狂的侏儒和他们的机械装置。我必须呆在这里，但无法帮助我的朋友让我感到很心痛。如果你能替我去的话，我会很感谢你的。你可以在铁炉堡的侏儒区里找到科劳莫特。","小武哥儿"},
[2926] = {"诺恩","用空铅瓶对着辐射入侵者或者辐射抢劫者，从它们身上收集放射尘。瓶子装满之后，把它交给卡拉诺斯的奥齐·电环。","事故后，诺恩想的说的都离不开两个主题：如何将石颚怪赶出诺莫瑞根，以及如何为席卷诺莫瑞根的瘟疫找到治疗的方法。幸运的是，拉兹和我已经快要研究出一种治疗方法了——要不然就是一种很强劲的朗姆酒的配方。我们要试过才知道！当然，为了检验我们的理论是否成立，我们需要一些东西，准确地说，是诺莫瑞根城里那些石颚怪身上的辐射尘。用这个小瓶子装一些泛着绿光的辐射尘，然后把它带回来！","小武哥儿"},
[2927] = {"灾难之后","与卡拉诺斯的奥齐·电环谈一谈。","你不会认为我生来就是是秃子吧？事实并不是这样的，$g先生:女士;！诺莫瑞根的放射性泄露导致了我悲剧性的脱发。在那之前，我有着整个艾泽拉斯世界独一无二的侏儒式飞机头！<诺恩一边说一边挥舞着拳头>那些该死的穴居怪——他们都该死！！或许现在还不晚，。我们也许仍然可以挽回局势——我说的是这座城市！去跟卡拉诺斯的奥齐·电环谈谈吧，他和他伙伴拉兹正在想办法。","小武哥儿"},
[2928] = {"陀螺式挖掘机","收集24副机械内胆，把它们交给暴风城的舒尼。","太糟糕了，。我们没有足够的零件让我们的陀螺式挖掘机部队进入丹莫罗。我们需要的是零件，，更多的零件。说到寻找零件，难道还有比诺莫瑞根更好的地方吗？我听说那里的机器人像牧区的牛似的到处游荡。我要你做的就是到诺莫瑞根去，把这些机器人拆开，拿出它们的内部装置。给我弄两打来就够了。","小武哥儿"},
[2929] = {"大叛徒","到诺莫瑞根去杀掉麦克尼尔·瑟玛普拉格。完成任务之后向大工匠梅卡托克报告。","我以前曾经非常信任麦克尼尔，我从未想过他会背叛我和所有侏儒同胞。他为什么要背叛我们？为了权力？为了金钱？这些东西只要加以时日他都可以拥有。现在我们背井离乡，那个疯子掌握了政权，成了个什么都没有的国王……我们要夺回诺莫瑞根，。在夺回自己的城市之前，我们决不停止努力。如果你想加入我们，就先去完成一个简单的任务：杀了那个叛徒，麦克尼尔·瑟玛普拉格。","小武哥儿"},
[2930] = {"抢救数据","将彩色穿孔卡片交给铁炉堡的大机械师卡斯派普。","在逃离诺莫瑞根的时候，我们留下了太多的数据！非常重要的数据！我需要一张彩色穿孔卡片，你可以从诺莫瑞根城里的矩阵式打孔计算机3005-D型里找到这种卡片。不过糟糕的是，要得到它的话，你就必须先接近低级安全终端，也就是A型，B型和C型计算机，然后用不同的穿孔卡片开启它们，从白色的卡片开始……而且我们把所有的穿孔卡片都留在城里了。这真是一场灾难！你能帮忙吗？","小武哥儿"},
[2931] = {"卡斯派普的任务","与铁炉堡的大机械师卡斯派普谈一谈。","铁炉堡的大机械师卡斯派普正在征集冒险者！他正在组织一个冒险小队，要到诺莫瑞根去执行一项极度机密和重要的数据收集任务。卡斯派普也许不是炼金术、魔法和工程学协会的一员，不过他也算是个很聪明的侏儒，如果是他认为这是件很重要的事情，那么根据我的计算，这件事有百分之八十四的可能性是确实很重要的！这个可能性可不小！","小武哥儿"},
[2932] = {"可怕的消息","在辛特兰收集枯木巨魔的头皮，把它们串在尼姆布亚之矛上。将尼姆布亚的长矛插在辛特兰的某个枯木巨魔村庄中，然后回到荆棘谷的尼姆布亚那里。","枯木巨魔原来是部落的盟友，但他们现在背叛了萨尔……他们要为此受到惩罚！来，拿起我的长矛，到北面的辛特兰去，那个地方就在塔伦米尔的东北方向。追捕那里的枯木巨魔，收集他们的头皮，把我的长矛插在他们的某个村庄中，比如西利瓦萨或者祖瓦沙。让他们知道，背叛部落，迟早要还的！","小武哥儿"},
[2933] = {"毒液瓶","将毒药瓶交给塔伦米尔的某个药剂师。","这些瓶子里装有绿色的毒液。由村庄中这种瓶子的数量来看，枯木巨魔一定很重视这些东西。或许塔伦米尔的药剂师会对这些毒液的样本感兴趣。","小武哥儿"},
[2934] = {"完好无损的毒囊","将完好无损的毒囊交给塔伦米尔的药剂师林度恩。","我必须要有一个你带来的那种毒液的新鲜样本才能进行研究。生产毒液的蜘蛛一定生活在辛特兰一带——猎捕这些蜘蛛，直到你找到一个完好无损的毒囊，把它给我带来。巨魔们的沙德拉洛城附近有许多蜘蛛，到那里去找找吧。别耽搁了，毒囊一定要非常新鲜才行。","小武哥儿"},
[2935] = {"请教加德林大师","与森金村的加德林大师谈一谈。","巢穴守卫的毒液没有你先前带来的毒液那么有威力，它肯定来自不同类型的蜘蛛。我要那种毒液的新鲜样本。如果要找到它的出处，那么你必须与一个很了解枯木巨魔的巨魔谈一谈——我说的是森金村的加德林大师。到杜隆塔尔去找加德林吧。如果运气好的话，他会知道枯木巨魔是在哪里找到这种毒液的。","小武哥儿"},
[2936] = {"蜘蛛之神","阅读塞卡石板，了解枯木巨魔的蜘蛛之神的名字，然后回到加德林大师那里。","枯木巨魔崇拜蜘蛛之神，他们从她那里收集极具威力的毒液。如果你想要毒液，就必须召唤他们的蜘蛛之神！要召唤她的话，你就必须知道她真正的名字，刻有这个名字的石板被埋藏在一座墓穴中，那墓穴就在塔纳利斯沙漠中的巨魔城市祖尔法拉克，由殉教者塞卡守卫着墓穴的入口。击败塞卡，阅读那块石板，找到蜘蛛之神的名字。知道了她的名字之后就回到我这里来。","小武哥儿"},
[2937] = {"召唤沙德拉","在沙德拉洛祭坛上击败沙德拉，把它的毒液交给塔伦米尔的药剂师林度恩。","拿着这张羊皮纸，在辛特兰的沙德拉洛祭坛上念诵羊皮纸上的咒文。这样就可以召唤蜘蛛之神沙德拉。","小武哥儿"},
[2938] = {"送往幽暗城的毒药","将法拉尼尔的包裹交给幽暗城的大药剂师法拉尼尔。","你在枯木巨魔的蜘蛛之神身上采集的毒液真是一个重大的发现！只消一小滴，我就可以杀死足足二十只兔子。当然，有些兔子很幼小，小得足以放在手掌上，它们对毒药的抵抗力非常低，但你也不能否认这种毒药极具威力！我想要给我的上级——幽暗城炼金房的大药剂师法拉尼尔——送去一些样本，我敢说他也会对此很感兴趣的。","小武哥儿"},
[2939] = {"寻找知识","与鲁瑟兰村的达蕾恩·轻风谈一谈。","虽然遍布菲拉斯的废墟和遗迹可能很危险，但是它们讲述了许多曾经发生的事情……几天前我在南边的碎石堆里搜索的时候，发现了一个看起来像是根普通法杖的东西。但是，我总觉得事情并不是那么简单，安吉拉斯和我在这里钻研书籍已经很久了，不过我们没发现什么和它相关的信息。我在达纳苏斯有一个同事，她能告诉我这是什么东西，。你为什么不去跟她谈谈呢？也许她能帮助我们。","小武哥儿"},
[2940] = {"菲拉斯的历史","如果你想借达蕾恩·轻风的书，要先得到她的允许。","看起来这本书很久没有人打开过了。它的封面破旧而且书页发黄，但检查后你会发现这正是特洛亚斯要找的那本书。你把它捡了起来，但你却突然意识到，也许应该在借阅之前得到物主的允许。","小武哥儿"},
[2941] = {"海龟照片","把信交给塔纳利斯的克格尔·曲藤。","我一生中研究了许多课题，最近我迷上了遍布辛特兰海滩地区的钳嘴龟。我特别想看到一只名叫加莫里塔的大型钳嘴龟，本来呢，我想要自己去一趟，但繁重的研究工作让我不得不留在这里。如果能搞到一张它的画像就好了。把这封信交给塔纳利斯的克格尔·曲藤。她为我发明了一种可以快速抓取图像的装置，我想她把那个东西叫做“快照”……","小武哥儿"},
[2942] = {"晨光石","将闪光的石头和艾奎尼克斯法杖交给羽月要塞的特洛亚斯·月风。","石碑中的东西被你拿出来的一瞬间，你突然感到艾奎尼克斯法杖的力量开始衰竭。","小武哥儿"},
[2943] = {"向特洛亚斯回复","把书交给羽月要塞的特洛亚斯·月风。","给你，。请小心保管我的书。现在快点出发吧，特洛亚斯正在翘首企盼你的回归呢！","小武哥儿"},
[2944] = {"超级摄影器FX","用超级摄影器FX给加莫里塔拍张照片，然后把它交给鲁瑟兰村的达蕾恩·轻风。","先来看看我的发明吧，。你所要做的只是将它对准任何一个你想要拍摄的物品，然后按下这个按钮。你说的辛特兰的生物是什么？加莫里塔？好吧，祝你好运，希望你能找到它。我坚信达蕾恩会对你给她的照片很满意的。不说那么多了，这是给你的超级摄影器。玩得开心点！","小武哥儿"},
[2945] = {"脏兮兮的戒指","想方法把脏兮兮的戒指弄干净。","你在一个黑铁矮人的尸体上发现了一枚戒指。但要辨认戒指的细节却很困难，泥土和坚硬的污垢将它整个包裹了起来，你根本没法戴上它。你觉得它是用某种珍贵的金属制成的，似乎还镶着宝石。如果你想好好看看这枚戒指的话，就得找些东西把戒指表面的污垢清理掉。","小武哥儿"},
[2946] = {"拭目以待","将迷你白金圆盘拿到塔纳利斯的奥丹姆大门去，找出两者之间的联系。","我希望你把这张圆盘拿到奥丹姆的封印之门去。我们……我们不能肯定这样做会带来什么后果。当然，这听上去确实很危险，但也有可能什么都不会发生。也许你要将圆盘放在什么东西上，也许你只要带着圆盘，大门就会自己打开。总之，不试一试是不会知道真相的。等你完成这项任务之后就回到铁炉堡来，我们还有很多事需要讨论。","小武哥儿"},
[2947] = {"戒指归来","你要么自己留着这枚戒指，要么就按照戒指内侧刻着的名字找到它的主人。","打开由超级清洁器5200型制作的盒子之后，你看到了一枚闪闪发光的戒指！你戴上了戒指，立刻感觉身体中涌动着神奇的力量。戒指的内侧有一个很小的铁炉堡徽记，旁边刻着三个字母：“TdK”。这可能是它以前的主人或是制作者的姓名缩写。是将这枚戒指留着自己用，还是把它物归原主，这要由你自己来决定……","小武哥儿"},
[2948] = {"侏儒的手艺","将闪亮的金戒指、1块银锭、1块绿玛瑙和30个银币交给铁炉堡的塔瓦斯德·基瑟尔。","听着，$n，这戒指当然是你的……但是我可以给你做一枚更好的！就像我说的一样，那种设计实在太简单了。现在我的技术更加娴熟了，只要你付我三十个银币的费用，我就可以帮你制作一枚新戒指！好吧，事实上还要再加一点点……我现在手头很紧，我的所有存货都用完了。如果你给我一块银锭和一块绿玛瑙，我就可以让戒指看起来更加闪亮华贵！相信我！","小武哥儿"},
[2949] = {"戒指归来","你要么自己留着这枚戒指，要么就按照戒指内侧刻着的名字找到它的主人。","打开由超级清洁器5200型制作的盒子之后，你看到了一枚闪闪发光的戒指！你戴上了戒指，立刻感觉身体中涌动着神奇的力量。戒指的内侧有一个很小的铁炉堡徽记，旁边刻着三个字母：“TdK”。这可能是它以前的主人或是制作者的姓名缩写。是将这枚戒指留着自己用，还是把它物归原主，这要由你自己来决定……","小武哥儿"},
[2950] = {"诺格的手艺","将闪亮的金戒指、1块银锭、1块绿玛瑙和30个银币交给奥格瑞玛的诺格。","不，不，不——我当然不是突然就说这枚戒指是我的。嗯，我通常不这样做，但你提供的关于黑铁矮人的情报很有用，所以我会破例为你改造你的戒指，我的手艺绝对比制作这个小东西的家伙要高超得多。嗯，八成是个侏儒做的……如果你给我拿来一块银锭、一块绿玛瑙和三十枚银币作为加工费的话，我就可以在戒指中加入白银和玛瑙的精华来加强其魔力。怎么样，感兴趣吗？","小武哥儿"},
[2951] = {"超级清洁器5200型！","将脏兮兮的东西放入超级清洁器5200型，记得要用三枚银币来启动机器。","这个装置屹立于那些竭力保护房间的侏儒中，装置上有一块小金属牌，上面写着“超级清洁器5200型”，还有一段文字：：“污垢和残渣让你的东西看起来污秽不堪？超级清洁器5200型会使它重现光芒！将你想要清理的物品放入清洁器中，然后向槽里投入三枚银币。稍候片刻，你的珍宝就会重新变得洁净而耀眼！”","小武哥儿"},
[2952] = {"超级清洁器5200型！","","","小武哥儿"},
[2953] = {"再次使用超级清洁器","","","小武哥儿"},
[2954] = {"石头卫士","询问诺甘农的石头卫士，搞清楚它要让你干什么，然后再次点击它脚下的奥丹姆石座。","“向你致意——我是把守入口的守护者。除非你拥有完整的奥丹姆圆盘，否则我不会让你进入奥丹姆城。”这个石头卫士一定就是派你来这里的人希望能在这里找到的东西。看来你必须在继续探索之前找出石头卫士背后隐藏的故事。","小武哥儿"},
[2962] = {"更多的辐射尘！","到诺莫瑞根去收集高强度辐射尘。要多加小心，这种辐射尘非常不稳定，很快就会分解。奥齐要求你把沉重的铅瓶也交给他。","你的样本不仅数量不够，而且纯度也不够。我们需要更多的辐射尘。很显然，穴居怪身上的辐射剂量根本无法满足我们的需要。你必须重返诺莫瑞根，直接从辐射源头取回一些辐射尘。我指的是那些受到辐射的泥浆怪、潜伏者和水元素。小心一点，收集这种辐射尘并不容易。也许你得试好几次才能找到一个合适的样本。","小武哥儿"},
[2963] = {"奥丹姆的线索","与铁炉堡探险者大厅中的史学家卡尼克谈一谈。","你好，很高兴再一次见到你，$n！你在奥达曼的发现使探险者协会兴奋不已。协会一直都在努力揭开你所发现的那张白金圆盘的秘密。你来的正是时候，我可以和你分享一下我们的最新进展！史学家卡尼克发现了一些很重要的线索，可能有助于找到塔纳利斯沙漠中的守卫之谷的起源。他想和你谈谈，越快越好！","小武哥儿"},
[2964] = {"进一步的任务","与铁炉堡的资深探险家麦格拉斯谈一谈。","好吧，$n…我们现在好像走进了一个死胡同。我们知道我们需要的是什么——奥丹姆圆盘——但我们不知道这些东西在哪里。我们得进行大量的研究才能制定出确实可行的计划。关于到哪里去寻找圆盘……我有一些想法，我坚信我们马上就会要求你尽快出发去找到它。这件事要通知资深探险家，$n，毫无疑问，他也会再次感谢你对探险者协会的帮助。","小武哥儿"},
[2965] = {"奥丹姆的线索","与雷霆崖长者高地的纳拉·蛮鬃谈一谈。","啊，，你来得正好。你在奥达曼挖掘场的发现让我们的贤者进行了激烈的讨论。我和纳拉·蛮鬃也交换了看法，因为当初我和她一起经历过一段冒险旅程，这段经历对于我们将要采取的下一步行动非常重要。我想让你和她去谈一谈，听听她当年在塔纳利斯的守卫之谷中遇到的事情。她在长者高地等你。","小武哥儿"},
[2966] = {"拭目以待","将迷你白金圆盘拿到塔纳利斯的奥丹姆大门去，找出两者之间的联系。","圣者图希克和我希望你把这张圆盘拿到奥丹姆的封印之门去。我们……我们不能肯定这样做会带来什么后果。当然，这听上去确实很危险，但也有可能什么都不会发生。也许你要将圆盘放在什么东西上，也许你只要带着圆盘，大门就会自己打开。总之，不试一试是不会知道真相的。等你完成这项任务之后就回到我这里来，我们还有很多事需要讨论。","小武哥儿"},
[2967] = {"返回雷霆崖","与雷霆崖的纳拉·蛮鬃谈一谈。","你打开了底座，白金圆盘又一次突然出现在你的背包里。你从石头守卫那里获取了许多信息，而且白金原盘又回到了你的手中，现在你应该回雷霆崖向纳拉·蛮鬃汇报这个大发现了。","小武哥儿"},
[2968] = {"进一步的任务","与雷霆崖的圣者图希克谈一谈。","好吧，$n…我们现在好像走进了一个死胡同。我们知道我们需要的是什么——奥丹姆圆盘——但我们不知道这些东西在哪里。我们得进行大量的研究才能制定出确实可行的计划。关于到哪里去寻找圆盘……我有一些想法，我坚信我们马上就会要求你尽快出发去找到它。这件事必须要通知圣者图希克，$n，毫无疑问，他也会再次感谢你对我们的帮助。","小武哥儿"},
[2969] = {"精灵龙的自由","从恐怖图腾营地的围栏里释放被俘获的小精龙。至少6个小精龙和辛达尔·月纹必须活着。如果6分钟之内你还没能达成这个目标，辛达尔就会决定撤退，任务也会随即失败。","可恶的恐怖图腾氏族正在捕捉精灵龙，。耶尔卡和我不知道他们打算对这些精灵龙做什么，但那总不会是什么好事。我们还没有强悍到可以杀进营地去解救那些精灵龙，但也许有了你的帮助……如果你能找到一些得力的帮手的话，就从笼中释放那些精灵龙吧，另外你要保证它们都活着逃出去。我也会帮你的。耶尔卡会留在这里继续戒备。","小武哥儿"},
[2970] = {"菲拉斯的正义","杀掉12个恐怖图腾博学者、10个恐怖图腾袭击者和6个恐怖图腾萨满祭司，然后向菲拉斯的耶尔卡·月纹汇报。","辛达尔已经跟你说过了，我们准备去和恐怖图腾氏族作战。干掉几个牛头人对我们两个来说不是什么问题，但如果你愿意帮忙的话，我们还是很欢迎的。看到下面那个营地了吗？东边有更多这样的营地。运用你的战术，尽可能让那些牛头人多吃些苦头。当他们被你和辛达尔打得落花流水之后，我们再回到这里来碰头。","小武哥儿"},
[2971] = {"<UNUSED>","[PH] Log Description","[PH] Description","小武哥儿"},
[2972] = {"菲拉斯的正义","将耶尔卡的徽记之戒交给达纳苏斯的高阶女祭司泰兰德·语风。","在这片蛮荒的土地上，辛达尔和我有无数的方法来报答你，但我们想让你有更多的成就感。把我的戒指拿去吧，如果你哪一天到了泰达希尔，就去一趟达纳苏斯城里的月神殿。你可以在那里找到高阶祭司泰兰德·语风。她看到这枚戒指就会知道我们在这里一切安好，并相信你所说的一切。，我们都很感谢你。","小武哥儿"},
[2973] = {"新斗篷的光辉","给莫沙彻营地的克鲁伊格·碎颅带去10个闪光的小精灵翅膀。","你好，<职业>。我和我的伙伴们正准备去菲拉斯执行任务。我的妻子科琳很喜欢新衣服，所以我想为她做一件用小精龙的翅膀装饰的新披风。你能帮帮我吗？长着美丽翅膀的小精龙在莫沙彻营地的西边。","小武哥儿"},
[2974] = {"可怕的发现","收集20支恐怖图腾之角，把它们交给千针石林的克鲁伊格·碎颅。","什么？！你在这一地区碰到牛头人了？你开玩笑吧！他们长什么样？！恐怖图腾氏族！你看到他们了？贝尔戈洛姆对他们这种生物很有兴趣……甚至出重金悬赏他们。你必须得回去，<职业>。回去给我带些他们的角回来……如果可以的话，尽可能多弄一些。你可别低估了恐怖图腾氏族，回去杀了他们，让菲拉斯的河流被他们的鲜血染红。","小武哥儿"},
[2975] = {"菲拉斯的食人魔","莫沙彻营地的洛卡·奥赫要你杀掉10个戈杜尼食人魔、10个戈杜尼食人魔法师和5个戈杜尼蛮兵。","戈杜尼食人魔在这一地区的影响已经不容忽视了。，你可以清楚地看到这一点，他们的存在污染了这片土地。在他们进一步扩张之前，我们一定要把他们赶回去。沿着河向北走，你会找到他们的前哨营地。去杀掉他们，。我们必须告诉这些食人魔：他们在这里不受欢迎。","小武哥儿"},
[2976] = {"可怕的发现","将一箱恐怖图腾之角交给奥格瑞玛的贝尔戈洛姆·石槌。","什么？！啊，我确实提到过奖赏，对吗？好吧，我知道了你完成了任务，我觉得你应该得到最高的奖赏。把这些角拿去，我会帮你把它们放到箱子里。到荣誉谷去找贝尔戈洛姆·石槌，向他汇报你所见的一切，他会表彰你的。祝你一路平安，<职业>，再次感谢你。","小武哥儿"},
[2977] = {"返回铁炉堡","与铁炉堡的史学家卡尼克谈一谈。","你打开了底座，白金圆盘又一次突然出现在你的背包里。你从石头守卫那里获取了许多信息，而且白金原盘又回到了你的手中，现在你应该回铁炉堡向探险者协会汇报这个大发现了。","小武哥儿"},
[2978] = {"戈杜尼卷轴","将戈杜尼卷轴交给莫沙彻营地的洛克·奥汉。","你捡起了这个沾满泥土的卷轴，发现上面写着某种集会或仪式的内容。洛卡·奥赫应该会对这个卷轴以及它对戈杜尼食人魔的意义感兴趣。","小武哥儿"},
[2979] = {"黑暗仪式","莫沙彻营地的洛卡·奥赫希望你找到一颗戈杜尼之宝珠。","这些好像是某种黑暗仪式的计划，。根据我所了解的情况，这种仪式是由戈杜尼食人魔中的大法师进行的。从某个戈杜尼大法师身上给我弄一颗宝珠来。法师的宝珠蕴含了巨大的力量，它可以帮我们搞清楚更多关于这种仪式的细节。","小武哥儿"},
[2980] = {"菲拉斯的食人魔","莫沙彻营地的洛卡·奥赫要你去杀掉十个戈杜尼萨满祭司、10个戈杜尼术士和5个戈杜尼虐待者。","现在你已经证明了自己是一个真正的勇士，我相信你具备足够的勇气继续完成下一个任务。到这里西南边的高原荒野去，在那块原本属于暗夜精灵的土地上还残存着一些被遗弃和毁坏的建筑物。搜索那些废墟，当你看到枯萎的树木和满目疮痍的大地时，你就会看到那些戈杜尼食人魔。把他们都干掉。这些食人魔比你曾面对的任何敌人都要强大，。你一定要小心行事。","小武哥儿"},
[2981] = {"菲拉斯的危机","贝尔戈洛姆·石槌想让你去和莫沙彻营地的洛卡·奥赫谈一谈。","菲拉斯是一个有成就的<职业>证明自己能力的理想场所。有个名叫戈杜尼的食人魔部落是那里最主要的军事力量，而且他们的势力仍在不断增长。在这些食人魔威胁到我们在菲拉斯的地位以前，我们必须要阻止他们。我认识一个名叫洛卡·奥赫的战士，她住在菲拉斯的莫沙彻营地里，去找她谈谈吧，她会让你知道更多情况的。","小武哥儿"},
[2982] = {"高原荒野","安吉拉斯·月风要求你杀死8个戈杜尼术士、8个戈杜尼萨满祭司和8个戈杜尼蛮兵。","虽然菲拉斯森林的废墟中隐藏着巨大的危险，但特洛亚斯和我一直以来都在调查这个地区。最近特洛亚斯老是独自一人去高原荒野，这很让我担心。戈杜尼食人魔已经占领了那里，他们不会对任何进入他们领地的冒险者手下留情的。我希望你能到菲拉斯南部去一趟，消灭一些食人魔。让我的特洛亚斯安全一点，我会十分感激你的。","小武哥儿"},
[2983] = {"火焰的召唤","去贫瘠之地找到卡纳尔·菲斯。","你上次考验至今已经有一段时间了，。从那以来，你一直耐心地学习，但在是时候让你学习更大的力量了……是时候让你学习真正的力量。如果你准备好付出，火的元素就是你的了。在贫瘠之地找到卡纳尔·菲斯。他居住在十字路口北部的小房子里，小心，如果你到了被诅咒的暗夜精灵的领地，那你走得太远了。","小武哥儿"},
[2984] = {"火焰的召唤","去贫瘠之地找到卡纳尔·菲斯。","你已经很久没有接受试炼了，。到目前为止，你已经证明了自己有足够的耐心，现在是时候让你学习更多东西，是时候让你了解毁灭…和混乱了。只要你明白自己即将为此付出的代价，火焰的元素就会与你建立连接。到贫瘠之地去找卡纳尔·菲斯，他就住在十字路口北部的一间小房子里。路上小心点，走太远的话，你就会进入精灵的领地。","小武哥儿"},
[2985] = {"水之召唤","找到贫瘠之地的水之先知伊斯伦。","你的下一个目标是水，。 我可以看出你已经能很熟练地运用火焰的力量，看来你也准备好去和伊斯伦谈谈了。伊斯伦住在贫瘠之地的河岸边，你只要沿着怒水河往南走，就肯定能找到她。她对各种元素的使用方法都很熟悉，可以教你关于水元素的知识……不要向南走得太远，她就在棘齿城旁边，。","小武哥儿"},
[2986] = {"水之召唤","找到贫瘠之地的水之先知伊斯伦。","从你上次接受测验到现在已经有很长的时间了，。迄今为止，你展示了足够的耐心，不过现在你应该学到更多的东西，应该去了解水的纯洁。去贫瘠之地找到水之先知伊斯伦，沿着怒水河的东岸向棘齿城的南方走，你可以在一间小渔屋里找到她。祝你好运，。","小武哥儿"},
[2987] = {"戈杜尼钴矿石","莫沙彻营地的奥尔文·吉兹米克需要12块戈杜尼钴矿石的样本。","我刚刚到达菲拉斯时，曾听说这里的戈杜尼食人魔有一些有趣的矿石。天知道食人魔用矿石来干什么，但他们确实在很小心地保护那种东西！他们有意隐藏这些矿石，以免我们接触到它。如果你愿意的话，我会把我的铲子给你。到北面的戈杜尼前哨站去，给我挖些戈杜尼钴矿回来。注意找那些泛着蓝光的矿石，然后就挖！","小武哥儿"},
[2988] = {"枯木巨魔的牢笼","检查两个枯木巨魔村落里的笼子，然后向狮鹫管理员沙拉克·鹰斧回复。","我们最强大的狮鹫的儿子失踪了！几天前，沙普比克和它的父母外出打猎时失踪了，我们认为是巨魔抓走了它。你必须帮帮我们！到枯木巨魔的两个村子里去搜一搜那里的笼子，看看沙普比克是不是被关在里面。","小武哥儿"},
[2989] = {"祖尔祭坛","检查祖尔祭坛的顶部，然后向狮鹫管理员沙拉克·鹰斧报告。","沙普比克没有和枯木巨魔在一起，那么或许是邪枝巨魔带走了他……到邪枝巨魔控制地区的西部边缘去，在那里的祖尔祭坛上找一找吧。","小武哥儿"},
[2990] = {"萨迪斯·格希德","将沙普比克的羽毛交给诅咒之地的萨迪斯·格希德。","把这根羽毛交给占卜师萨迪斯·格希德。几年前，他离开鹰巢山去寻求黑暗的知识，但他内心深处仍是一个不折不扣的蛮锤矮人！也许他的智慧能帮助我们找到沙普比克。这根羽毛是从它的巢穴里拿出来的，如果你把它交给萨迪斯，那么他也许就可以用占卜法术找到沙普比克。祝你好运，。你可以在诅咒之地找到萨迪斯，他就在守望堡的法师塔上。","小武哥儿"},
[2991] = {"耐克鲁姆的徽章","将耐克鲁姆的徽章交给诅咒之地的萨迪斯·格希德。","我会帮你找出那头狮鹫的下落，但你得先为我做点事情。巨魔城市祖尔法拉克里面有一个名叫耐克鲁姆的巨魔，他拥有一枚徽章，我很想研究一下那东西。把徽章交给我，我就帮你找到沙普比克。祖尔法拉克在塔纳利斯的沙漠中。","小武哥儿"},
[2992] = {"占卜","等待萨迪斯完成占卜仪式。","在我进行占卜仪式的过程中，不要打断我。我会找出你拿来的那根羽毛和它主人之间的关系，然后顺藤摸瓜找到沙普比克。理论上讲是这样……如果一切都按照计划进行的话。如果不是，那么……你最好闭上眼睛。","小武哥儿"},
[2993] = {"返回辛特兰","与辛特兰的狮鹫管理员沙拉克·鹰斧谈一谈。","沙普比克被关在巨魔城市辛萨罗的悬崖上的一只笼子里，笼子的钥匙由邪枝巨魔的邪恶祭司海克斯掌管着。我已经做了我该做的那部分事情，希望你执行任务的时候一切顺利，。","小武哥儿"},
[2994] = {"拯救沙普比克","到辛萨罗山顶去，杀掉邪恶祭司海克斯，找到沙普比克笼子的钥匙，然后救出沙普比克。","你必须得救出沙普比克！杀进邪枝巨魔那座城市——辛萨罗的山顶，从邪恶祭司海克斯那里拿到沙普比克笼子的钥匙，找到沙普比克，把它救出来！","小武哥儿"},
[2995] = {"联络中心","幽暗城的奥兰·斯内克威瑟让你到辛特兰去烧毁高原精灵记录、高原精灵报告和高原精灵信件。","奎尔丹尼小屋是高等精灵在辛特兰的联络中心。他们的使者正在试图与其他种族建立联系，他们会与这些种族分享与辛特兰南部的枯木巨魔的情报。所有联络其他种族所需的文件都被保存在了小屋中。我们不希望那些精灵与其他种族建立联盟关系，。去摧毁他们的文件，或者说，我们要毁掉他们的联络中心……","小武哥儿"},
[2996] = {"寻找斯坦哈德","与棘齿城的斯坦哈德·法尔杉谈一谈。","我过去曾教过你一些知识和技艺，现在该让别人继续教你了。我说的是棘齿城的斯坦哈德，他是个人类，但不要以为他很弱小。虽然他看上去非常矮小，但是却有着超强的力量。他可以教你最强大的召唤法术——我觉得你已经准备好了，现在就到他那里去吧。他住在棘齿城……他的塔就在那座港口城市旁边的山上。","小武哥儿"},
[2997] = {"圣洁之书","和铁炉堡的蒂萨·热炉谈一谈。","你好，。我知道你在忙着帮助丹莫罗的人民，但如果你有时间的话，你应该去铁炉堡，到那里去跟我们最受尊敬的族人蒂萨·热炉谈一谈。当年轻的圣骑士需要学习更多关于圣光以及其它一些必要的知识时，他们就会去找她。","小武哥儿"},
[2998] = {"圣洁之书","与暴风城的达索瑞恩·拉尔谈一谈。","你好，我的$G兄弟:姐妹;。我们这里最有影响力的圣骑士——达索瑞恩·拉尔最近谈起过你。我听他说过你应该去找他接受试炼了……我也从他那里听说过你的出色表现。如果我是你，而且我有时间的话，我就会去暴风城和他聊聊的。我很肯定他会待在光明大教堂里——他一般都待在那里。","小武哥儿"},
[2999] = {"圣洁之书","与铁炉堡的蒂萨·热炉谈一谈。","你好，。我知道你在忙着帮助丹莫罗的人民，但如果你有时间的话，你应该去铁炉堡，到那里去跟我们最受尊敬的族人蒂萨·热炉谈一谈。当年轻的圣骑士需要学习更多关于圣光以及其它一些必要的知识时，他们就会去找她。","小武哥儿"},
[3000] = {"圣洁之书","和铁炉堡的蒂萨·热炉谈一谈。","你好，。我知道你在忙着帮助丹莫罗的人民，但如果你有时间的话，你应该去铁炉堡，到那里去跟我们最受尊敬的族人蒂萨·热炉谈一谈。当年轻的圣骑士需要学习更多关于圣光以及其它一些必要的知识时，他们就会去找她。","小武哥儿"},
[3001] = {"寻找斯坦哈德","在棘齿城找到斯坦哈德·法尔杉。","我过去曾教过你一些知识和技艺，现在该让别人继续教你了。我说的是棘齿城的斯坦哈德，他是个人类，但不要以为他很弱小，也不要以为他是你的敌人……至少现在不是。他很强大，所以理应受到尊重。他可以教你最强大的召唤法术，我觉得你已经准备好了，现在就到他那里去吧。他住在棘齿城……他的塔就在那座港口城市旁边的山上。","小武哥儿"},
[3002] = {"戈杜尼宝珠","将戈杜尼宝珠交给奥格瑞玛暗木小屋里的尤塞尔奈。","虽然我很熟悉我的敌人，但我只是一个战士，。我不知道这颗宝珠是用来干什么的。我认识一个住在奥格瑞玛的法师，他可以告诉你更多关于宝珠的信息。把它拿到他那里去吧。","小武哥儿"},
[3022] = {"小心运送","把仔细包装过的箱子交给鲁瑟兰村的艾瑞拉斯·琥珀。","，显然你很想帮我进行崇高的事业。嗯，当然，你可以为我做一些事情！请把这箱蛋送给艾瑞拉斯·琥珀。他是一个很重视这些蛋的德鲁伊，而且一直在帮助孵化这些蛋，以及训练幼小的角鹰兽。你可以在泰达希尔南边的一个名叫鲁瑟兰村的村庄里找到他。","小武哥儿"},
[3023] = {"<UNUSED>","","","小武哥儿"},
[3042] = {"巨魔调和剂","收集20瓶巨魔调和剂，把它们交给加基森的特伦顿·轻锤。","祖尔法拉克的沙怒巨魔用砂石制造巨魔调和剂，我可以用它来加强我铸造的东西！有眼光的行家会出高价购买经过这样处理的装备，所以，如果你能给我提供足够的调和剂，那我一定会重重奖赏你的。祖尔法拉克在加基森的西北边。祝你好运。","小武哥儿"},
[3062] = {"黑暗之心","莫沙彻营地的塔罗·刺蹄要你给他拿去艾丹娜·邪爪的黑心。","艾丹娜·邪爪是居住在西面废墟里的北泉鹰身人的皇后。她是个彻头彻尾的恶魔，我听说她的心是水晶做的。除了对别人的仇恨之外，她没有一丝其它的情感。你必须干掉艾丹娜，把她的黑心交给我。我听说鹰身人有一种号角——在废墟北部的邪爪石那里吹响号角就可以召来她。当她发现召唤她的是死亡的命运而不是她的同族时，她会有多么惊讶啊！","小武哥儿"},
[3063] = {"对鹰身人的复仇","塔罗·刺蹄让你杀掉4个北泉鹰身人、4个北泉游荡者、4个北泉唤风者和4个北泉杀戮者。","年轻时，我曾是个经验丰富的猎手，没有什么野兽会让我感到害怕，直到……有一次在树林里，我在一场恶战之后正在打磨自己的武器，这时我遭到了伏击。鹰身人包围了我，好不容易我才脱了身。直到现在，我还能听见它们的嚎叫在耳边回荡……现在我已经不再年轻了，不过仇恨还在我的心中燃烧——这么多年了，我一定要报仇。北泉鹰身人就在西边，，去为我复仇。","小武哥儿"},
[3064] = {"海盗帽","带20顶完整的海盗帽给尤尔巴·斯库比格特。","我的商店需要海盗帽。给我带一些来！","小武哥儿"},
[3065] = {"普通石板","阅读普通石板，然后和试炼谷的弗朗恩谈一谈。","啊，刚刚你不在的时候，有人送来了这块石板，。如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这张羊皮纸是战士训练师弗朗恩写的，他有事找你。你可以在大兽穴外面的阴凉处找到他。","小武哥儿"},
[3082] = {"风蚀石板","和试炼谷的基沙谈一谈。","啊，刚刚你不在的时候，有人送来了这块石板，。如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这张羊皮纸是猎人训练师基沙写的，她有事找你。","小武哥儿"},
