[26157] = {"熊猫人元", "将熊猫人元交给藏宝海湾的阿尔塔迪娜", "你发现了熊猫人元。这枚绘有精雅纹饰的圆币，曾流转于潘达利亚的商队之间。钱币收藏家会感兴趣。", "小武哥儿"},
[26158] = {"暴风城王冠币", "将暴风城王冠币交给藏宝海湾的阿尔塔迪娜", "你发现了暴风城王冠币。这枚铸有雄狮徽记的金币，象征着人类王国的鼎盛时期。钱币收藏家会感兴趣。", "小武哥儿"},
[26159] = {"暴风城先令", "将暴风城先令交给藏宝海湾的阿尔塔迪娜", "你发现了暴风城先令。这枚镌刻暴风城徽的银币，记录着联盟心脏的商业脉搏。钱币收藏家会感兴趣。", "小武哥儿"},
[26160] = {"暴风城法新", "将暴风城法新交给藏宝海湾的阿尔塔迪娜", "你发现了暴风城法新。这枚百姓日常使用的铜币，承载着王国的市井记忆。钱币收藏家会感兴趣。", "小武哥儿"},
[26161] = {"暴风城六便士", "将暴风城六便士交给藏宝海湾的阿尔塔迪娜", "你发现了暴风城六便士。这枚制作精良的小额硬币，彰显着人类经济的稳健全貌。钱币收藏家会感兴趣。", "小武哥儿"},
[26162] = {"激流堡先令", "将激流堡先令交给藏宝海湾的阿尔塔迪娜", "你发现了激流堡先令。这枚带着战痕的银币，诉说着阿拉希高地的峥嵘岁月。钱币收藏家会感兴趣。", "小武哥儿"},
[26163] = {"未知钱币", "将未知钱币交给藏宝海湾的阿尔塔迪娜", "你发现了来源不明的钱币。这些陌生符号可能属于失落的文明或未知种族。钱币收藏家会感兴趣。", "小武哥儿"},
[26164] = {"风险投资公司欠条", "将风险投资公司欠条交给藏宝海湾的阿尔塔迪娜", "你发现了风险投资公司欠条。这张盖着企业徽记的潦草票据，其兑现可能性令人怀疑——但对猎奇收藏者另当别论。", "小武哥儿"},
[26165] = {"风险投资公司代金券", "将风险投资公司代金券交给藏宝海湾的阿尔塔迪娜", "你发现了风险投资公司代金券。这份看似正规的兑换凭证实际价值存疑，但因其稀有性颇具玩味。", "小武哥儿"},
[26166] = {"蛮锤弗罗林", "将蛮锤弗罗林交给藏宝海湾的阿尔塔迪娜", "你发现了蛮锤弗罗林。这枚刻着风暴纹章的古朴硬币，承载着高地部族的自由之魂。钱币收藏家会感兴趣。", "小武哥儿"},
[26167] = {"甜蜜危机", "从斯克岩石的部落废弃基地木箱中回收10瓶辛特兰蜜波酒", "我需要你去打捞一种琼浆玉液——没错就是蜜波酒！那群没品味的家伙根本不懂，只有辛特兰产的蜜波才配叫佳酿。斯克岩石的废弃营地里还藏着存货，不过要当心占领废墟的软泥怪领袖。", "小武哥儿"},
[26168] = {"蛛卵行动", "从沙德拉洛收集12枚沙德拉卵，交给鹰巢山的科尔·铁视", "维德巴克的巨魔正在培育蛛母后代。即使杀光他们，那些即将孵化的蛛卵仍是威胁。把卵从囊袋中取出带给我处理——切记勿自行破坏！", "小武哥儿"},
[26169] = {"蛛卵行动", "从沙德拉洛收集12枚沙德拉卵，交给恶齿村的锋牙托克", "西边的维德巴克巨魔在照料沙德拉的卵。必须彻底清除这些隐患。带回完整的蛛卵由我处理，切勿擅自破坏！", "小武哥儿"},
[26170] = {"净滩行动", "在辛特兰海岸击杀10名咸水滩泳者", "听着伙计，村子附近的渔获越来越少，全怪那些该死的咸水滩泳者！想尝尝地道的海岛烧烤吗？那就先帮忙清理些污染海域的家伙。", "小武哥儿"},
[26171] = {"坠落缓降", "从沙德拉洛的枯木巨魔处收集8件枯木披肩碎片和8张完美育蛛丝。", "我是大工匠亲自派来加强联盟与蛮锤部族关系的。我的任务很简单——让他们的狮鹫骑行更安全。我计划制作一些自动感应坠落的降落伞。听起来很棒对吧？但需要些蛮锤没有的材料。首先是伞面——附近的枯木巨魔精通裁缝，虽然他们的蜘蛛很恶心，但吐的丝非常棒。去帮我弄点来吧。", "小武哥儿"},
[26172] = {"坠落缓降", "在辛特兰山脉中寻找鲁普·兹普科。", "下一步需要高度仪！简单说就是：开始坠落？高度仪就工作。简单吧？可惜我没带现成的。我们侏儒在辛特兰有个小据点，我同事那儿可能有货。你能去问问吗？他们在奎尔丹尼小屋北面的山里——往东走就能找到那个秘密据点。", "小武哥儿"},
[26173] = {"坠落缓降", "从阿戈瓦萨湖底找回高度仪。", "蒂兹要高度仪？我们确实有过——关键字是*有过*。不久前在阿戈瓦萨湖边做实验时出了点意外，部分设备沉湖底了。你要是能潜下去找找，肯定能找到那个高度仪。", "小武哥儿"},
[26174] = {"坠落缓降", "将完好的高度仪带给鹰巢山的蒂兹·火花工艺。", "给火花工艺小姐的完好高度仪。她到底要用这个做什么？自动开伞的降落伞...有意思...我得安排观摩最终成品的演示。", "小武哥儿"},
[26175] = {"坠落缓降", "使用蒂兹的火箭背包升空测试自动开伞装置。", "就是现在...表演时刻！带着这个去找弗斯塔德本人，让他近距离观摩——然后拉响火箭背包。转眼你就能冲上云霄，开始坠落时伞就会自动打开。理论上...好吧，只有试了才知道！", "小武哥儿"},
[26176] = {"坠落缓降", "将自动开伞装置交给弗斯塔德·蛮锤。", "要是这玩意儿还不能让蛮锤部族对我们刮目相看，我就真没辙了。你愿意代我把这个交给弗斯塔德吗？", "小武哥儿"},
[26177] = {"钢喙友情", "收集8份石斑鱼排和12根皇家噬咬芦苇茎制作狮鹫零食。", "我们部族视狮鹫为神圣生物。它们不仅是坐骑，更是聪明狡猾的天空伙伴。想获得蛮锤氏族的友谊？先从讨好狮鹫开始！它们最爱吃不常见的零食：混着鲜鱼排的脆芦苇。这群小家伙会为之疯狂。阿戈瓦萨附近的溪流入海口能找到厚肉石斑鱼和皇家芦苇，收集材料给我来制作零食吧。", "小武哥儿"},
[26178] = {"钢喙友情", "给鹰巢山东南方的驯养钢喙狮鹫投喂零食。", "拿好这袋新鲜零食。驯养的钢喙狮鹫在鸟巢东南边的林间游荡。去帮我喂几只怎么样？", "小武哥儿"},
[26179] = {"隐居的乌波", "寻找乌波——这位恶齿村前守卫因厌恶村民食用龟肉而离群索居。", "咱们遇上麻烦了，需要你这样的勇士解决。守卫乌波因为看不惯村里吃龟肉，独自跑到北边当隐士去了。村子需要他的守卫本领。找到他并带回来，重重有赏。这活你接不接？", "小武哥儿"},
[26180] = {"钳嘴龟点心", "收集8份石斑鱼排和12根皇家噬咬芦苇茎制作龟类零食。", "既然有位乌龟洛阿神存在，龟类必定不凡。我们恶齿部族却为了取乐滥杀乌龟，真让我恶心。想准备连托加都会满意的供品。我见过海龟吃种特殊芦苇和上游冲下来的鱼。去收集些鱼排和芦苇茎，我要做它们爱吃的点心。", "小武哥儿"},
[26181] = {"零食分派", "沿着辛特兰海岸给钳嘴龟投喂零食。", "用你带来的材料，我给钳嘴龟做了些特制零食。帮个忙把这些分发给沿岸的钳嘴龟吧。", "小武哥儿"},
[26182] = {"和平献礼", "在辛特兰海岸收集8块乌龟金块。", "现在明白我为什么爱这些乌龟了吧？也明白我为什么不肯回村了！我受够了他们派冒险者来游说。这些零食的副作用是会被快速排出...所以岸边会有很多新鲜金块能送给恶齿村当礼物。快去捡些回来。", "小武哥儿"},
[26183] = {"和平献礼", "从乌波小屋北面小岛取回雕花骨灰盒。", "现在需要个华丽礼盒来增加诚意。早该让你先捡盒子的...北边岛上有我母亲的骨灰盒——这手工精品正合适，更重要的是...她老人家绝对会觉得这事特别好笑。", "小武哥儿"},
[26184] = {"和平献礼", "将乌波的和平献礼交给辛特兰恶齿村的守望者奥威。", "把这厚礼带给村里的奥威，以后他应该不会再派冒险者烦我了。快去——你最好就是最后一个。", "小武哥儿"},
[26185] = {"拉德的珠子", "从沿海巡逻的鲨鱼杰伯牙处夺回拉德的珠子。", "拉德最喜欢在码头往海里扔石头玩！有次能打三个水漂呢！结果太兴奋把珠子也扔出去了...转眼就被坏鲨鱼杰伯牙吞了！能帮拉德从鱼肚子里掏珠子吗？", "小武哥儿"},
[26186] = {"远程零件", "将点心篮带给铁炉堡的米罗·碎怒换取攻城零件。", "在远离铁炉堡的地方维护攻城器械简直是噩梦！我老婆想出妙招——用美食贿赂！哪个矮人能抵挡美食诱惑？把这篮点心带给铁炉堡的米罗·碎怒，换些零件回来。", "小武哥儿"},
[26187] = {"远程零件", "将零件箱带回给鹰巢山的总工程师乌林。", "本来绝不允许零件流出铁炉堡...但看在这些点心的份上...破例一次！下次让他们捎点麦酒来！", "小武哥儿"},
[26188] = {"猎杀潜行者", "击杀15名银鬃潜行者和15头银鬃嗥狼。", "无数勇敢矮人倒在银鬃狼群爪下！它们潜伏在灌木丛中伺机偷袭...要想找到这些畜生，就得像它们一样思考——潜伏、猎杀、一个不留！", "小武哥儿"},
[26189] = {"极品粘液", "从巨型软泥怪身上获取软泥样本。", "我的私酿秘诀就是加入绿皮软泥怪的粘液——对，就那些吃矮人的恶心玩意儿！斯库克岩洞底有只巨型软泥怪叫恐胶怪...敢不敢去挖块样品回来？", "小武哥儿"},
[26190] = {"极品粘液", "从恐胶怪处获取软泥样本。", "斯库克岩洞的软泥怎么清都清不完！我怀疑洞底有个软泥源头...去弄些样本回来研究，说不定能发现它们再生的秘密！", "小武哥儿"},
[26191] = {"凶残职业", "击杀鹰巢山东面的10头凶残枭兽。", "我们和巨魔的斗争本已趋于平和...直到这些枭兽开始袭击双方运输队！想维持和平就得先解决这群搅局者——去东边削减它们的数量吧。", "小武哥儿"},
[26192] = {"原始殴击", "消灭辛特兰中部的10头原始枭兽。", "越往东走枭兽就越原始凶暴。虽然挑战更大...但为了蛮锤氏族必须清理它们！每消灭一只，辛特兰就多一分安宁。", "小武哥儿"},
[26193] = {"野蛮捶打", "击杀眺望崖附近的10头野蛮枭兽。", "海岸边的枭兽让巨魔误以为是我们下的杀手！这些野蛮枭兽更狡诈也更危险...虽说于心不忍，但为了避免冲突升级——必须除掉它们！", "小武哥儿"},
[26194] = {"枭兽首领", "找到瑞克的神像并焚烧以激怒他。", "现在是除掉它们首领的时候了。瑞克是只藏身金萨罗北面的特殊枭兽——比其他同类更聪明。找到它搭建的神像烧掉...我打赌这能把它引出来。", "小武哥儿"},
[26196] = {"龟壳力量", "从眺望崖沿岸海龟身上获取10块精瘦龟肋。", "蛮锤矮人结束漫长工作后最想来杯麦酒和龟肉汤！去眺望崖搞些新鲜龟肋回来——要最嫩的部位！", "小武哥儿"},
[26198] = {"通缉：污翼", "在勇士之湖边击杀失控的狮鹫污翼。", "数月前，蛮锤巡逻兵遭巨魔标枪击落。他的狮鹫伙伴污翼因此陷入狂暴——无差别攻击野生动物、巨魔甚至矮人！必须终结这头可怜野兽的痛苦。", "小武哥儿"},
[26199] = {"通缉：污翼", "在勇士之湖击杀污翼。", "自从主人被射杀后，污翼狮鹫陷入嗜血狂怒。在它造成更多伤亡前，必须除掉这个威胁！", "小武哥儿"},
[26209] = {"蛮锤骸骨", "从辛萨罗夺回10块蛮锤骸骨。", "邪枝巨魔长期用偷来的矮人骸骨进行邪恶仪式！奉海克斯祭祀之命从我们墓园盗取遗骨...前往辛萨罗，在巨魔祭坛夺回我们先祖的遗骸！", "小武哥儿"},
[26210] = {"鹰巢山护卫队长招聘", "击杀20名邪枝战士/暗影施法者/剥皮者/阿曼尼守卫。", "蛮锤氏族现招募能带队清剿辛萨罗的勇士！应聘者需完成以下任务：击杀各类邪枝巨魔精锐用实力证明你的统帅才能！", "小武哥儿"},
[26211] = {"战术打击", "击杀邪枝祭司海克斯和守护者希泰娅。", "虽然无法彻底铲除邪枝巨魔...但斩首行动能让他们乱上一阵子！潜入辛萨罗顶端，除掉他们的精神领袖——祭司海克斯和守护者希泰娅！", "小武哥儿"},
[26212] = {"巫毒配方", "收集8份邪枝巫毒熔剂。", "我研究邪枝武器多年，发现他们锻造时使用特殊巫毒熔剂增强武器威力。去辛萨罗弄些样品回来——也许能改良我们的装备！", "小武哥儿"},
[26213] = {"霍温的钓鱼点", "到眺望崖瀑布顶端找回霍温的鱼饵。", "我在东边瀑布钓鱼时被邪枝巨魔袭击，连最爱的鱼饵都落在那儿了！帮我找回来吧——其他渔具无所谓，我只要那枚特制鱼饵！", "小武哥儿"},
[26214] = {"霍温的钓鱼点", "在瀑布底部搜寻鱼饵。", "钓鱼椅周围一无所获...可能渔具都被冲下瀑布了。试试在瀑布底的泥潭里找找看？", "小武哥儿"},
[26215] = {"霍温的钓鱼点", "前往禁忌之海搜寻鱼饵。", "湍流把物件卷向禁忌之海...说不定霍温的鱼饵就在东面的海床上。总不能空手回去告诉他鱼饵丢了吧？", "小武哥儿"},
[26216] = {"霍温的钓鱼点", "将鱼饵带回鹰巢山。", "奇迹！漂流木上钩着枚鱼饵——希望这就是霍温要找的那枚！", "小武哥儿"},
[26217] = {"湖底遗物", "从洛丹米尔湖底打捞杨斯家族遗物。", "阿尔萨斯背叛后，我们全家乘船逃难...结果破船在葬影村东面沉没。冰冷的手将我拽上岸...但传家宝永远沉在了湖底。帮忙打捞的话必有重谢！", "小武哥儿"},
[26218] = {"红雀号残骸", "前往葬影村北面的北流谷海岸，在红雀号残骸中寻找烟木牧场的货箱。", "几个月前我从烟木牧场订购了一批材料，货船红雀号从卡利姆多出发，结果在葬影村北面的浓雾中搁浅。北流谷附近有狼人出没，我一直没敢去查看沉船。如果能从红雀号货舱找回那批货，我愿意和你分享里面的材料。", "小武哥儿"},
[26219] = {"应有补偿", "将一副野性之心手套带给铁炉堡的德莉亚娜。", "你信守承诺带来了穆克斯制造的装置。为表谢意，我可以用更精良的装备替换你的腰带和手套。", "小武哥儿"},
[26220] = {"应有补偿", "将一副野性之心手套带给奥格瑞玛的莫克瓦尔。", "你证明了是个可靠的伙伴。接下来我会根据你的表现给予相应的奖励。现在先帮你替换腰带和手套，如果合作愉快还会有更多装备。", "小武哥儿"},
[26221] = {"安提恩的遗言", "将一副野性之心护肩带给铁炉堡的德莉亚娜。", "瓦尔塔拉克的灵魂就封在这个护符里。因为贪婪，我们愚蠢地把它分成了三份，却不知会招来诅咒。只有重组护符才能解除法术。告诉德莉亚娜，伯德雷是她找回剩余碎片的唯一希望。至于奖励...尽管向她开口吧。我终于可以安息了。祝你好运——你肯定会需要的！", "小武哥儿"},
[26222] = {"安提恩的遗言", "将一副野性之心护肩带给奥格瑞玛的莫克瓦尔。", "瓦尔塔拉克的灵魂就封在这个护符里。因为贪婪，我们愚蠢地把它分成了三份，却不知会招来诅咒。只有重组护符才能解除法术。告诉莫克瓦尔，伯德雷是他找回剩余碎片的唯一希望。至于奖励...尽管向他开口吧。我终于可以安息了。祝你好运——你肯定会需要的！", "小武哥儿"},
[26223] = {"压轴好戏", "将你的野性之心外衣交给德莉亚娜。", "真是个精彩的故事！我代表所有相关人员向你致以衷心感谢。现在我终于能睡个安稳觉了。至于你的奖励...我相信有几件东西你会特别喜欢。", "小武哥儿"},
[26224] = {"压轴好戏", "将你的野性之心外衣交给莫克瓦尔。", "真是个了不起的成就！你的努力让我们得以弥补过去的过错。现在该兑现你的奖励了——这些都是你应得的！", "小武哥儿"},
[26225] = {"安提恩的遗言", "将一件野性之心褶裙带给铁炉堡的德莉亚娜。", "瓦尔塔拉克的灵魂就封在这个护符里。因为贪婪，我们愚蠢地把它分成了三份，却不知会招来诅咒。只有重组护符才能解除法术。告诉德莉亚娜，伯德雷是她找回剩余碎片的唯一希望。至于奖励...尽管向她开口吧。我终于可以安息了。祝你好运——你肯定会需要的！", "小武哥儿"},
[26226] = {"安提恩的遗言", "将一件野性之心褶裙带给奥格瑞玛的莫克瓦尔。", "瓦尔塔拉克的灵魂就封在这个护符里。因为贪婪，我们愚蠢地把它分成了三份，却不知会招来诅咒。只有重组护符才能解除法术。告诉莫克瓦尔，伯德雷是他找回剩余碎片的唯一希望。至于奖励...尽管向他开口吧。我终于可以安息了。祝你好运——你肯定会需要的！", "小武哥儿"},
[26227] = {"应有补偿", "将一副光铸护手带给铁炉堡的德莉亚娜。", "你信守承诺带来了穆克斯制造的装置。为表谢意，我可以用更精良的装备替换你的腰带和手套。", "小武哥儿"},
[26228] = {"应有补偿", "将一副光铸护手带给奥格瑞玛的莫克瓦尔。", "你证明了是个可靠的伙伴。接下来我会根据你的表现给予相应的奖励。现在先帮你替换腰带和手套，如果合作愉快还会有更多装备。", "小武哥儿"},
[26229] = {"安提恩的遗言", "将一副光铸肩铠带给铁炉堡的德莉亚娜。", "瓦尔塔拉克的灵魂就封在这个护符里。因为贪婪，我们愚蠢地把它分成了三份，却不知会招来诅咒。只有重组护符才能解除法术。告诉德莉亚娜，伯德雷是她找回剩余碎片的唯一希望。至于奖励...尽管向她开口吧。我终于可以安息了。祝你好运——你肯定会需要的！", "小武哥儿"},
[26230] = {"安提恩的遗言", "将一副光铸肩铠带给奥格瑞玛的莫克瓦尔。", "瓦尔塔拉克的灵魂就封在这个护符里。因为贪婪，我们愚蠢地把它分成了三份，却不知会招来诅咒。只有重组护符才能解除法术。告诉莫克瓦尔，伯德雷是他找回剩余碎片的唯一希望。至于奖励...尽管向他开口吧。我终于可以安息了。祝你好运——你肯定会需要的！", "小武哥儿"},
[26251] = {"安西昂的临终遗言", "将一套元素肩甲带给奥格瑞玛的莫克瓦尔。", "瓦尔塔拉克的灵魂就封印在这枚护身符中。因我们的贪婪，愚蠢地将其分成了三块，却不知等待我们的将是可怕的诅咒。要阻止瓦尔塔拉克的法术，唯一的办法就是将这枚护身符重新拼合。返回奥格瑞玛，告诉莫克瓦尔，博德利是他寻回剩余碎片的唯一希望。跟他谈谈你们谈妥的奖励事宜。这一次，我终于能安息了。祝你们好运——你们会需要每一分运气的！", "小武哥儿"},
[26252] = {"把最好的留到最后", "将你的元素背心交给迪莉安娜。", "这真是个了不起的故事，！你让我和所有参与此事的人都深表感激。现在也许我能安心合眼了。至于你的奖励，我想我有几样东西你一定会喜欢。", "小武哥儿"},
[26253] = {"把最好的留到最后", "将你的元素背心交给莫克瓦尔。", "你确实是个了不起的故事，！你让我和所有参与此事的人都深表感激，我可以保证。通过你的努力，我们从过去的错误中解脱了出来。至于你的奖励，我想我有几样你绝对应得且会非常喜欢的东西。", "小武哥儿"},
[26254] = {"安西昂的临终遗言", "将一件元素短裙带给铁炉堡的迪莉安娜。", "瓦尔塔拉克的灵魂就封印在这枚护身符中。因我们的贪婪，愚蠢地将其分成了三块，却不知等待我们的将是可怕的诅咒。要阻止瓦尔塔拉克的法术，唯一的办法就是将这枚护符重新拼合。返回铁炉堡，告诉迪莉安娜，博德利是她寻回剩余碎片的唯一希望。跟她谈谈你们谈妥的奖励事宜。这一次，我终于能安息了。祝你们好运——你们会需要每一分运气的！", "小武哥儿"},
[26255] = {"安西昂的临终遗言", "将一件元素短裙带给奥格瑞玛的莫克瓦尔。", "瓦尔塔拉克的灵魂就封印在这枚护身符中。因我们的贪婪，愚蠢地将其分成了三块，却不知等待我们的将是可怕的诅咒。要阻止瓦尔塔拉克的法术，唯一的办法就是将这枚护符重新拼合。返回奥格瑞玛，告诉莫克瓦尔，博德利是他寻回剩余碎片的唯一希望。跟他谈谈你们谈妥的奖励事宜。这一次，我终于能安息了。祝你们好运——你们会需要每一分运气的！", "小武哥儿"},
[26256] = {"公正补偿", "将一套勇气护手带给铁炉堡的迪莉安娜。", "你信守承诺，带来了穆克斯制造的装置。如果我想让你继续帮我保命，是时候给你点奖励了。把你想要升级的腰带和护手带来，我保证给你的替换品会好得多。", "小武哥儿"},
[26257] = {"公正补偿", "将一套勇气护手带给奥格瑞玛的莫克瓦尔。", "你已经证明自己是个非常可靠的人。尽管我相信你会帮我度过难关，但按表现奖励你是明智之举。现在我先换你的腰带和护手，如果我们一起解决这事，剩下的部件我也给你。", "小武哥儿"},
[26258] = {"安西昂的临终遗言", "将一套勇气肩甲带给铁炉堡的迪莉安娜。", "瓦尔塔拉克的灵魂就封印在这枚护身符中。因我们的贪婪，愚蠢地将其分成了三块，却不知等待我们的将是可怕的诅咒。要阻止瓦尔塔拉克的法术，唯一的办法就是将这枚护符重新拼合。返回铁炉堡，告诉迪莉安娜，博德利是她寻回剩余碎片的唯一希望。跟她谈谈你们谈妥的奖励事宜。这一次，我终于能安息了。祝你们好运——你们会需要每一分运气的！", "小武哥儿"},
[26259] = {"安西昂的临终遗言", "将一套勇气肩甲带给奥格瑞玛的莫克瓦尔。", "瓦尔塔拉克的灵魂就封印在这枚护身符中。因我们的贪婪，愚蠢地将其分成了三块，却不知等待我们的将是可怕的诅咒。要阻止瓦尔塔拉克的法术，唯一的办法就是将这枚护符重新拼合。返回奥格瑞玛，告诉莫克瓦尔，博德利是他寻回剩余碎片的唯一希望。跟他谈谈你们谈妥的奖励事宜。这一次，我终于能安息了。祝你们好运——你们会需要每一分运气的！", "小武哥儿"},
[26260] = {"把最好的留到最后", "将你的勇气胸甲交给迪莉安娜。", "这真是个了不起的故事，！你让我和所有参与此事的人都深表感激。现在也许我能安心合眼了。至于你的奖励，我想我有几样东西你一定会喜欢。", "小武哥儿"},
[26261] = {"把最好的留到最后", "将你的勇气胸甲交给莫克瓦尔。", "你确实是个了不起的故事，！你让我和所有参与此事的人都深表感激，我可以保证。通过你的努力，我们从过去的错误中解脱了出来。至于你的奖励，我想我有几样你绝对应得且会非常喜欢的东西。", "小武哥儿"},
[26262] = {"安西昂的临终遗言", "将一条勇气腿甲带给铁炉堡的迪莉安娜。", "瓦尔塔拉克的灵魂就封印在这枚护身符中。因我们的贪婪，愚蠢地将其分成了三块，却不知等待我们的将是可怕的诅咒。要阻止瓦尔塔拉克的法术，唯一的办法就是将这枚护符重新拼合。返回铁炉堡，告诉迪莉安娜，博德利是她寻回剩余碎片的唯一希望。跟她谈谈你们谈妥的奖励事宜。这一次，我终于能安息了。祝你们好运——你们会需要每一分运气的！", "小武哥儿"},
[26263] = {"安西昂的临终遗言", "将一条勇气腿甲带给奥格瑞玛的莫克瓦尔。", "瓦尔塔拉克的灵魂就封印在这枚护身符中。因我们的贪婪，愚蠢地将其分成了三块，却不知等待我们的将是可怕的诅咒。要阻止瓦尔塔拉克的法术，唯一的办法就是将这枚护符重新拼合。返回奥格瑞玛，告诉莫克瓦尔，博德利是他寻回剩余碎片的唯一希望。跟他谈谈你们谈妥的奖励事宜。这一次，我终于能安息了。祝你们好运——你们会需要每一分运气的！", "小武哥儿"},
[26264] = {"契约#1010：魔法残留", "从巴拉丁监狱收集4瓶魔法残留。", "我需要愿意组队的承包商接活。是时候让节日魔法生效了！这是节日装饰部门的一个任务。契约#1010：从巴拉丁监狱内部获取魔法残留数量：四份样本", "小武哥儿"},
[26265] = {"奥术饮品", "向巴拉丁监狱中的某人学习如何召唤水晶水，然后将20瓶召唤的水晶水带给希利苏斯勇气之憩的纳莱瑟·卢纳布兰奇。", "你好！我需要你的帮助。沙漠的干热让人和野兽都口干舌燥。我听说托尔巴德的肯瑞托有一种召唤最清爽水晶水的特殊方法。你愿意去那里学学吗？这样我们就能补充补给了。", "小武哥儿"},
[26266] = {"黑暗文献", "从诅咒之地的邪教徒身上收集8本暗影誓约之书。", "你是部落的，对吧？我想加入一个阵营，在权衡所有因素后，我认为这是显而易见的选择……莫格里娅和她的商队在营地遇到了我。当我们各自说明来意后……简直像扭曲暗影中的天作之合——你敢信我们的目标完全一致？所以我们暂时达成协议：我提供费尔斯通堡垒的情报和解决当前诅咒的方法，换取部落公民身份。关于诅咒，我有个计划可能行也可能不行。这不是永久解决办法，但至少能让部落缓口气。不过——我需要只有能提供的帮助。我需要邪教徒的古籍，特别是那些施行魔法或仪式的。暴徒和执法者可不行。书越厚越好。等我拿到书再详细说。", "小武哥儿"},
[26267] = {"逆转诅咒", "从费尔斯通堡垒内的术士身上获取痛苦符文。", "伊扎尼尔弓着背，用他浑浊的眼睛长时间扫描着魔典的页面。最终，他抬头看向你。>你见过类似这样的东西吗？写在卷轴上，甚至石头上的？<伊扎尼尔给你看一页写满混乱文字、环绕着邪恶符文的页面。>术士们正用这些符文玩弄诅咒——那团邪火——的方式超乎我的想象。哈，这些蠢货甚至用它来炼金。<要继续的话，我需要一枚这样的符文，而除了费尔斯通的术士，没人会有这种东西。堡垒太危险，别一个人去。带朋友来。我会一直读到你回来。", "小武哥儿"},
[26268] = {"重写诅咒", "从费尔斯通堡垒周围收集5瓶库吉尔墨汁。", "看到这里的符文刻文了吗？这是用库吉尔墨汁写的：效力极强，连术士都很难弄到。墨水的主要成分是恶魔之血，泛着吞噬光线的黑色光泽。嗯……他们用的词典源自阿古斯觉醒的海外圈子。我能看懂足够修改内容，但我自己没有墨水。<伊扎尼尔期待地笑着看你。>你能帮我弄点吗？术士和他们的学徒有。我打赌你会在堡垒周围的术士帐篷里找到。小屋可能也有。", "小武哥儿"},
[26269] = {"灵魂燃料", "为伊扎尼尔从费尔斯通堡垒内邪教徒的尸体上找1块格罗姆博尔灵魂石。", "握住这块符文时你有什么感觉？恶心？难以忍受的瘙痒？<伊扎尼尔把手放在符文上闭上眼睛。>对我来说，是头部的跳动。像……有人在摇晃笼子。我听说强大的灵魂石被从费尔斯通后方洞穴走私出来……不难推测我们这里的符文就是用它充能的。堡垒里的兽人高人一等，不屑与其他人往来。不过，偶尔偷窃、交易或小失误会导致他们珍贵的灵魂石流落他处。也许你已经见过了？我需要至少一块让计划奏效。费尔斯通周围的术士可能有。<如果你够胆，也可以试试洞穴本身。它在费尔斯通中心西边，入口环绕着巨型骨头。我从没进去过，但听过传说……", "小武哥儿"},
[26270] = {"远程干扰", "在费尔斯通最南端上层露台的高祭坛仪式圈上使用改良的痛苦符文。", "是时候进行最后一步了。你们团队已经熟悉费尔斯通的危险，希望这次不难。<计划是这样的：带着修改后的符文去费尔斯通南部最高露台的高祭坛，用在仪式圈上。那是一个散发暗魔法的紫色符文。理论上，这个符文会把诅咒从目标身上剥离，回到仪式圈——如我所说，不是永久解决办法。<我不知道会有什么后果，做好万全准备。祝好运，。", "小武哥儿"},
[26271] = {"远古宝石加工", "星陨村的埃莉诺·月辉希望你从冬幕节更大的高等精灵遗迹中找回一件高等精灵工匠工具包。", "你好呀，希望你喜欢冬幕节！我喜欢这里的干燥空气，比起暗礁海岸的阴郁舒服多了。你是冒险者，对吧？我是珠宝专业的学生，来这里是为了周围漂亮的晶体。传闻说它们是从天上掉下来的——可能村子名字就由此而来！但我带的工具根本加工不了它们。真的，我试过了！我最棒的研磨机都坏了……！这些晶体不是什么新东西，古代高等精灵肯定有加工方法，对吧？找到的话我付钱！凯尔瑟里尔在南边，……泰莱斯阿兰在东北边，但去那儿的路上有个坏脾气的老太太。", "小武哥儿"},
[26272] = {"我们需要修理！", "把高等精灵工匠工具包交给埃弗洛克钢铁泉（永恒之望）。", "嗯……这工具包太旧了……我暂时不敢用。<埃莉诺皱着眉，用出人意料的专业目光检查工具包。>哦，我知道了！我在永恒之望遇到个地精，借了他些工具。他是工程师，欠我个人情！你要去那边吗？能帮我捎给他吗？就说是我让你来的，我会很感激他能修好它。", "小武哥儿"},
[26273] = {"坠落之星", "星陨村的埃莉诺·月辉希望你从冬幕节周围收集10颗星陨水晶。", "太让人兴奋了，！我等不及要做首饰了。我相信芬诺克是好工程师，但修复这么古老的遗物对任何人来说都是挑战。趁现在，我们尽可能多收集水晶吧！等一切结束，我给你做件首饰！怎么样？", "小武哥儿"},
[26274] = {"芬诺克的巧艺", "从永恒之望的芬诺克·钢铁泉那里取回修复后的工匠工具包，返回冬幕节的星陨村找埃莉诺·月辉。", "好吧，。我本来想陪你拿工具包，但不敢把这些宝石单独留下……万一被偷了呢？很抱歉总麻烦你。我保证会补偿你！不，我不是懒！", "小武哥儿"},
[26275] = {"给你的礼物！", "把埃莉诺箱子里的宝石底座袋从她屋后的箱子里带给埃莉诺。", "<埃莉诺小心翼翼地尝试加工一块晶体。>哼……或许我该让芬诺克来看看这些额外工具的用途。谢天谢地，工具能用，我现在就给你加工宝石！很快就好！我屋后的箱子里有一袋底座。能帮我最后一件事把袋子拿来吗？求你了！", "小武哥儿"},
[26276] = {"行动：方阵", "从黑石深渊的方阵那里为风暴之城的希欧妮·沉默者找回一个黑曜石核心。", "我们还在研究高效钻探铁炉堡并修复城市损伤的方法。我们需要更多能量！我有个表亲在黑石深渊的实验室工作。他们在那里制造由黑曜石核心驱动的魔像。我想研究其中一个核心是否能用。表亲提到有个叫方阵的老魔像用黑曜石核心，它即将退役——所以没人会惦记，你去拿了核心也不会有人发现！", "小武哥儿"},
[26277] = {"火焰萨满", "杀死黑石深渊的炎术师洛格雷因，然后返回乌努诺·火焰观察者（安戈洛环形山庇护所）。", "我作为大地之环的职责包括监督萨满对火元素的运用——以及滥用。最近我感受到远方（黑石山）传来强烈的火元素波动。我认为一位前大地之环成员加入了山内的暗炉氏族，正在尝试混合萨满使用的火元素能量和法师的奥术火焰魔法。这种元素的扭曲必须阻止。我需要留在这里继续研究原始魔法——但或许你和几位同伴能解决这个叛逆萨满。他叫托纳卡·洛格雷因。", "小武哥儿"},
[26278] = {"火焰领主的副官", "杀死黑石深渊的大领主罗科和火焰大使弗拉梅拉什，然后返回阿兹莎的杜克·海德里克斯那里。", "你已经证明能击败敌人并完成推进水领主事业的使命。但到目前为止，你只面对过小角色……是时候接受更艰难危险的任务了。黑石山深处，暗炉氏族正与火焰领主的仆从密谋。杀死他的两位首席使者：大领主罗科和火焰大使弗拉梅拉什。做到这些，就能向我证明你对事业的忠诚。", "小武哥儿"},
[26279] = {"更棒的东西", "杀死黑石深渊深处的玛格马斯，然后返回伯恩的岗哨找奥拉留斯（燃烧平原）。", "温基队长是个输不起的家伙。真的！温基说暗炉矮人有好东西，但我说不！肯定有更好的。我听说了，叫玛格……玛……玛格马斯！杀了他！或许别用火。", "小武哥儿"},
[26280] = {"迷途的学生", "杀死猎犬大师格雷bmar，为风暴之城的乌尔菲尔·铁须找回他的猎人学校文凭。", "真是没想到，！很抱歉需要像你这样的冒险者帮忙。我刚得知以前的学生被发现训练黑石深渊的恶魔猎犬。他应该杀恶魔，而不是和它们混在一起！我要收回授予他的文凭——他叫格雷bmar——但铁炉堡矮人在暗炉城不受欢迎。你能去送坏消息并找回文凭吗？", "小武哥儿"},
[26281] = {"永恒之焰", "把永恒余烬带给风暴之城的加金·暗缚者。", "检查余烬时，你感觉它有生命，在手中跳动。你记得加金·暗缚者有处理这类奇怪物品的经验，或许能进一步研究。他住在风暴之城法师区的屠宰羔羊酒馆。", "小武哥儿"},
[26282] = {"旧债", "在闪光沼泽矿找到主管格里姆加什并杀死他。", "你看起来是那种愿意接活不问太多的有为青年。正是我要找的人。在春溪定居前，我自己经营过货物运输。那时我有‘合伙人’帮忙……搞定海关和文书的麻烦。后来创业公司挖走了他们，整个生意垮了。我被困在这沙漠里！虽然现在好了，但地精不会忘这种仇。我得留在这照看生意，但如果你愿意去闪光沼泽矿找主管格里姆加什，我会好好报答你。", "小武哥儿"},
[26283] = {"阿佐坦遗物", "在铁炉堡找一个博学的历史学家。", "你面前有个古老破旧的偶像，大致像一个深不可测的远古人类。这对某位博学的历史学家可能有兴趣——最著名的在铁炉堡探险者大厅。", "小武哥儿"},
[26284] = {"阿佐坦遗物", "在闪光沼泽矿收集阿佐坦遗物。", "传说数千年前，巨魔曾与一个叫阿佐塔的族群交战。关于他们知之甚少，但我们这些更古怪的策展人（包括我）认为其中有更多秘密。如果你说的是真的，创业公司发现了他们的文物，必须带给我。它们属于博物馆！你愿意深入矿洞为我收集尽可能多的吗？", "小武哥儿"},
[26285] = {"迪格的丢失烟斗", "从闪光沼泽矿的默拉克尔那里找回迪格丢失的烟斗，带回藏宝海湾给他。", "生活没有一点小嗜好算什么，对吧？可惜自从在镇子东边的海滩弄丢最爱的烟斗后，我就抽不上了。当时我有点醉，醒来时看到一个大默拉格叼着它跑了！那默拉格在闪光沼泽矿安了家。你要是去那边有机会，帮我拿回烟斗，我会很感激。", "小武哥儿"},
[26286] = {"干掉工头", "杀死闪光沼泽矿的创业公司工头。", "创业公司在那搞了个该死的采矿场！难怪我搞不到歌唱水晶。这么大的工程会让丛林地基崩塌。得有人在他们失控前解决！帮个忙，干掉竞争对手，把矿场工头的脑袋给我。他死了，我不仅能在这赚点干净钱，丛林也不会被毁了！", "小武哥儿"},
[26287] = {"棱彩鳞片", "从闪光沼泽矿的蛇怪身上收集棱彩鳞片，带给藏宝海湾的德里兹利克。", "多亏你帮我完成‘卓越’系列靴子的订单，我觉得你应该帮我做实验新品。我要扩展鳄鱼皮之外的材料——但只要最好的。听说创业公司在闪光沼泽矿找到一只又大又亮、特别的蛇怪。就是我要的。去把它鳞片给我带来！", "小武哥儿"},
[26288] = {"夺回工具", "从闪光沼泽矿的创业公司那里回收20件工具。", "说白了——几个月前，我接了单给藏宝海湾的行动打造高品质工具。工头叫它‘闪光……’什么的。闪光沼泽！不知道他们在挖什么，但拼命往矿里塞人力，给矿工发工具的钱也大方。现在我在塔纳利斯接了个更赚钱的单子，需要所有能找回的工具来填单。要是保密，你可以去‘回收’我给闪光沼泽矿工做的工具，皆大欢喜。当然，除了闪光沼泽的笨蛋们，哈哈。怎么样？", "小武哥儿"},
[26289] = {"叛逆娜迦", "在闪光沼泽矿杀死5个潮汐预言家、5个潮汐战士和格拉什。", "作为女王的长期仆从，我憎恨背叛。但迷途的娜迦被深海堕落仆从引入歧途。你喜欢跑腿，对吧，凡人？这个任务怎么样：跨越大海去地精挖矿的地方。那在内陆深处，我们自己去太干燥。地精误入了一群迷途娜迦的巢穴，为首的叫格拉什。杀了格拉什的手下，再送他上路。我们不能容忍任何违抗女王的人活着。", "小武哥儿"},
[26290] = {"巨魔遗物", "在奥格瑞玛找一个博学的传说讲述者。", "你面前有个古老破旧的偶像，大致像一个深不可测的远古人类。这对某位博学的巨魔传说讲述者可能有兴趣——最著名的在奥格瑞玛灵魂谷。", "小武哥儿"},
[26291] = {"巨魔遗物", "在闪光沼泽矿收集巨魔遗物。", "传说数千年前，巨魔曾与一个叫阿佐塔的族群交战。除了战斗顽强，他们几乎不为人知。我认为其中有更多秘密。如果你说的是真的，创业公司发现了他们的文物，必须带给我。你愿意深入矿洞为我收集尽可能多的吗？", "小武哥儿"},
[26292] = {"隧道怪物", "在闪光沼泽矿寻找并消灭阿丽莎·潮觅者描述的怪物。", "我知道精灵不寻常，但我爱大海。我常在藏宝海湾东边的浅滩漂浮，和鱼鸟交朋友。从未害怕过……直到最近。那天我漂得比平时远，海底突然伸出巨大的触须抓住我的腿！那生物试图把我拖进海底隧道，我奋力反抗。最后它松开我，消失在隧道里……隧道随后坍塌了。我认为那生物可能住在村子上北边创业公司开的矿洞里。我警告过他们，但他们不理我。求你了，要是你进矿洞，小心这怪物！我可不想有人毫无防备地遇到它。", "小武哥儿"},
[26293] = {"王者之选", "从狂乱森林的林地行者的身上收集沃克树枝。", "你看起来不太忙……帮个小忙？我是蒸汽团伙派来打赌的。格鲁克说他总有一天会成为戈多克之王，像他父亲一样，但现任国王判他叛国，把他赶出了剃刀高地。我们认为格鲁克有当王的本事……有朋友帮忙的话。我打算给格鲁克打造一把神兵，参加即将到来的战斗，你得帮我找齐材料。成交？第一件要的是附近林地行者身上的特殊魔法木。它轻如鸿毛却坚比钢铁，是绝佳的剑柄材料。", "小武哥儿"},
[26294] = {"王者之选", "为格鲁克营地收集8捆湿地大麻给维戈。", "这一带有一种特殊的大麻，我可以用来做结实的绳子。这样就算国王手滑，也不会丢武器！食人魔很奇怪。传闻格鲁克的父亲（前任国王）抽了一捆这东西，就离开王座游荡去了。他一离开食人魔的视线，他们就立刻拥立新王，终结了格鲁克的王位。总之，大麻长在狂乱森林的河边，整片森林都有。", "小武哥儿"},
[26295] = {"王者之选", "从狂乱森林虚弱的野兽身上收集20瓶野兽血液。", "我计划的重要部分需要高度精炼的铁，后期再用你收集的特殊合金熔炼。但这里的铁很难搞！不过我有办法：不需要太多，我们可以直接从狂乱森林的野兽身上提取。这是我发明的‘血泵Max’。放虚弱野兽的血，直接抽取铁！够瓶数我就能开工了。可惜每瓶量太少，只能大规模‘狩猎’了。", "小武哥儿"},
[26296] = {"王者之选", "从狂乱森林深处的希利苏斯合金矿收集12块希利苏斯合金。", "现在轮到……不太愉快的部分了。我等你投入后才提这个是有原因的。东南方向有片‘扭曲深渊’，是被称为希利苏斯的爬虫的地盘。它们常把矿石当食物，分泌黏液包裹。你知道它们完全消化……排泄后会怎样吗？我们得到的就是一堆乱七八糟的矿石，莫名其妙融合成新合金。别问我原理，我可不想解剖它们。我只要你给格鲁克的新武器找这种合金。", "小武哥儿"},
[26297] = {"王者之选", "从灼热峡谷的土元素和火元素身上收集漩涡熔岩和炽烈火焰精华。", "我们离打造这把王者之剑不远了。现在的瓶颈很简单：加热和保温。这里的锻炉适合打造食人魔常用的劣质装备，但不够热，无法熔炼这些合金并与铁结合。不幸的是，热量得主动找我们。在遥远的东部王国，你会找到灼热峡谷。那是熔岩奔流、岩石融化、元素狂乱的地方。我需要你收集它们的火焰精华带给我。有了这些精华，我就能强化锻炉，满足需求。", "小武哥儿"},
[26298] = {"王者之选", "从狂乱森林海岸的水元素身上收集盐渍冷却精华。", "热量只是一半。我们还需要淬火控温，让合金慢慢熔化、融合，变成全新的东西。你运气好，不用跑远。<狂乱森林海岸的水元素吸收了大海的冷却精华。去收集尽可能多的，锻造时用来降温，避免整个营地被烧光！", "小武哥儿"},
[26299] = {"王者之选", "进入马鲁丹，杀死诺克西昂，收集他的精华带给狂乱森林的维戈。", "算了，别指望轻松了。我只听说一个地方可能有我们需要的东西：半人马的发源地——马鲁丹。在橙色洞穴深处，你会找到一个叫‘诺克西昂’的强大水元素，它的精华是打造这把神剑的绝佳材料。你愿意冒生命危险取他的精华吗？我保证，等格鲁克统治剃刀高地，一切都值得。", "小武哥儿"},
[26300] = {"王者之选", "冷却锻造中的迪和杜姆，帮他们打造格鲁克的新武器。", "我身后这两个笨家伙是迪和杜姆。他们不聪明，但抡大锤砸砧子是把好手，所以我觉得他们和普通铁匠一样聪明。他们锻造时，我需要你用诺克西昂的精华冷却火焰，别让食人魔过热，否则全白费了。", "小武哥儿"},
[26301] = {"王者之选", "将格鲁克的新武器送达。", "是时候将这把冠军之武器呈给格鲁克了。能帮我这个忙吗？他在附近的洞穴里。", "小武哥儿"},
[26302] = {"腐败之源", "在马鲁丹收集瑟莱德拉斯公主的样本，交给斯奎格科德哨站的塞尔雷·德莱特。", "传说这片土地曾郁郁葱葱，但瑟莱德拉斯公主在马鲁丹释放的半人马引发了灾难，造就了我们如今所见的景象。我和迪比、凯莉在此试图恢复这片土地。关键线索是公主本人的样本——斩杀她不仅能阻止进一步的腐败，深入研究或许还能逆转灾祸。请代我深入马鲁丹取回样本，我会重重酬谢。", "小武哥儿"},
[26303] = {"核心共鸣", "前往阿兹莎海岸外的一座岛屿，寻找杜克·海德里克斯。", "看啊，是……我之前常见你路过，却从未留意这地方的独特。我脚下两步之遥，是一道稳定的现实裂隙，直通黑石山深处——熔火之心。这里是极大的邪恶之地，也是像你这样的冒险者的荣耀之所。想看看吗？当然想，但对凡人来说独自涉险太危险了。幸好我来做你的引路人。去寻找居住在阿兹莎海岸的Hydraxian水领主吧，他们对你的成功至关重要。", "小武哥儿"},
[26304] = {"核心共鸣", "为阿兹莎海岸外的杜克·海德里克斯带来5朵火焰花、5株冬噬草、1份元素之火和1份元素之水。", "熔火之心是我们凡人宿敌——火元素的巢穴。若任其发展，它们的力量会蔓延至整个艾泽拉斯。火山中心的灼热连火领主的暗炉氏族盟友都难以承受。但若你帮我，我会赐予你抵御火山核心高温的祝福。首先需要元素材料用于仪式：收集元素之火、元素之水、火焰花和冬噬草。若你在野外找不到，相信凡人的交易枢纽会有售卖。", "小武哥儿"},
[26305] = {"核心共鸣", "将托里德的炽焰核心和基尼丝的冰霜核心带给阿兹莎海岸外的杜克·海德里克斯。", "接下来需要与火、冰元素共鸣的强大存在的精华。在燃烧平原的风暴祭坛附近，你会在熔岩瀑布中找到托里德——斩杀他能获得炽焰核心，是对世界的馈赠。至于霜元素，你需要去冬幕节杀死我的表亲基尼丝，他住在凯尔瑟里尔湖北侧的冰瀑旁。这虽不幸，但必要。", "小武哥儿"},
[26306] = {"核心共鸣", "用熔火之心入口附近的熔岩填满隔热瓶，并从附近岩壁收集核心碎片。", "现在需要收集与山体热度共鸣的材料——熔火之心本身的热量与共振样本（尽可能安全获取）。进入暗炉氏族的堡垒黑石深渊，前往最底层找到熔炉。用隔热瓶装满附近的沸腾熔岩，然后过桥走向核心，从岩壁收集碎片。凡人，这任务危险，切勿独自行动。若能生还，回来找我。", "小武哥儿"},
[26307] = {"核心共鸣", "站稳，让杜克·海德里克斯为你施加保护符文，助你安全进入熔火之心。", "我会用你收集的材料为你注入祝福，这符文仅在熔火之心有效——它与山体的独特共振共鸣。坚持住！这可能有点灼热，但若想深入黑石山核心，这是必要之险。", "小武哥儿"},
[26308] = {"自愿者的试炼", "与幽暗城的堕落骑士对话。", "幸会，……我最近去过幽暗城，有幸与堕落骑士交谈。<圣骑士轻笑>我总有一天想知道她的真名，总这么称呼太不专业了。不过她很看好你的潜力，让我送你去找她接受试炼。前往幽暗城，找到她吧。", "小武哥儿"},
[26309] = {"自愿者的试炼", "若想接受试炼，前往幽暗城与堕落骑士对话。", "我已非昔日的我，……曾是银手骑士团的高尚圣骑士，真理与正义的守护者。如今我躺在这暗无天日的幽暗城底，钓着这些病态的生物。但你——尽管灵魂中仍有黑暗，却仍愿与黑暗战斗。若你愿意，我想考验你。", "小武哥儿"},
[26310] = {"自愿者的试炼", "击败血色修道院东侧墓地的三位前圣骑士亡魂，安抚他们后返回幽暗城向堕落骑士复命。", "你的第一个试炼需要深入提里斯法林地东北部——血色修道院东侧，但别靠太近，你还不够强。沿着小石路找到墓地，那里有三位生前并肩作战、死后同葬的圣骑士亡魂。我感知到他们仍眷恋人间，去解放他们，让他们安息吧。", "小武哥儿"},
[26311] = {"光铸材料", "将信件与报酬交给奥格瑞玛荣誉谷的铁砧·阿图尔克。", "是时候打造一把配得上圣骑士的战锤了。我知道奥格瑞玛有位好铁匠——铁砧·阿图尔克。带这封规格信和报酬给他，他会给你列所需材料的清单。你能在荣誉谷的锻造训练师旁找到他。以我生前的经验，本想找铁炉堡打造，但如今他们怕是不会接这活了。", "小武哥儿"},
[26312] = {"光铸材料", "按阿图尔克的材料清单，找到祝福锭、泽莱玛之锤、银手徽章和科宝石，带回奥格瑞玛交给他。", "我平日磨练技艺，研究能用到的材料。旅途中我发现了几种对你战锤有用的资源。<阿图尔克朝牛喊了一声，让他记下需求>拿着这封信，去取吧！", "小武哥儿"},
[26313] = {"光铸之刃", "", "阿图尔克对自己作品很得意，这把武器不错，配得上一位强悍的部落勇士！好好为我们效力吧，……你的天赋值得肯定。当初怀疑你是好事，怀疑能激发你证明自己的动力！阿卡·马戈什！", "小武哥儿"},
[26314] = {"焕新仪式", "在通灵学院杀死詹迪斯·巴罗夫，取回高阶术士安德罗玛思的《奥术焕新笔记》。", "你好……能请你帮个私人忙吗？早在第三次大战前，我与詹迪斯·巴罗夫（一位才华横溢的召唤师）私交甚笃。巫妖军团入侵洛丹伦时，我的一些私人物品留在了她那里。考虑到我们分别时的情形，我不想再惹她动怒。但你对奥术的造诣与我不相上下，我相信你能从她手中取回笔记。若能成功，我很乐意与你分享笔记内容——《焕新仪式》能帮你省下不少时间！你和同伴可以在西瘟疫之地的通灵学院地下室找到詹迪斯·巴罗夫。", "小武哥儿"},
[26315] = {"焕新仪式", "与风暴之城的玛格·埃斯特对话。", "你好，……你在训练中成长迅速，我已没什么能教你的了。我猜你厌倦了为盟友召唤食物饮料吧？若猜得没错，你该去找风暴之城的玛格·埃斯特。我相信他知道更好的方法。", "小武哥儿"},
[26316] = {"洛丹伦的法律遗产", "在通灵学院和斯坦索姆为幽暗城的传说讲述者埃本洛克寻找洛丹伦法律实践的书籍。", "生前我是法律学者，死后也想继续研究，同时探索更广阔的领域。我没时间亲自去洛丹伦废墟搜集书籍，但我想你能行。从斯坦索姆废墟和通灵学院带回这些特定典籍，我就能平衡传说讲述者的职责与个人兴趣了。", "小武哥儿"},
[26317] = {"阿塔莱石板", "从阿塔哈卡神庙收集阿塔妮石板和贾卡里石板。", "据说在悲伤沼泽沉没的阿塔哈卡神庙中，阿塔莱巨魔祭司保存着两块我想研究的古老石板。考虑到他们会在我问之前就杀了我，需要冒险者去取回。有兴趣吗？", "小武哥儿"},
[26318] = {"血神之召", "从阿塔哈卡神庙的阿塔莱巫医和大祭司处收集4张阿塔莱卷轴。", "找活干吗？我需要勇敢的灵魂南下沼泽。在沉没神庙，你会见到大祭司和巫医，他们携带的卷轴记载着血神哈卡的疯狂预言。我一直在监视他的信徒，这些卷轴能帮我追踪。你觉得呢？", "小武哥儿"},
[26319] = {"知识传承", "前往托尔巴德岛的巴拉丁监狱，寻找凯尔德拉·晨风想修复的书籍。", "旅者，恕我打扰——你的名字已在贵族间传开，我正等待一位知名英雄来访。随着奎尔萨拉斯和达拉然陷落，我们族人的知识大多遗失。但肯瑞托在托尔巴德岛的巴拉丁监狱要塞设有图书馆，那里可能保存着我渴望保护的典籍。能请你协助吗？定有重谢。", "小武哥儿"},
[26320] = {"知识传承", "前往托尔巴德岛的巴拉丁监狱，寻找传说讲述者阿什曼想修复的书籍。", "旅者，恕我打扰——你的名字已在长老间传开，我正等待一位知名英雄来访。随着奎尔萨拉斯和达拉然陷落，高等精灵的知识大多遗失。但肯瑞托在托尔巴德岛的巴拉丁监狱要塞设有图书馆，那里可能保存着我渴望保护的典籍。能请你协助吗？定有重谢。", "小武哥儿"},
[26321] = {"未竟之事", "从托尔巴德岛找回丽贝卡·马丁遗失的家族传家宝。", "你——对，就是你！冒险者！或许你愿意听我说！我向暴风城要塞的权贵们求助数周，却无人理会。我的家族在第二次战争前居住在托尔巴德岛，大多葬身于此，但一位叔叔逃脱了。临终前他说家族传家宝藏在岛上某处。但现在有传言说海盗抵达了托尔巴德！他们肯定冲着宝藏来的。听着，……我急需有人去岛上寻回宝藏。拿着这把钥匙！它能打开藏宝的暗格。求你，替我找回家族的传承！", "小武哥儿"},
[26322] = {"未竟之事", "将遗失的传家宝归还给暴风城的丽贝卡·马丁。", "你拿到的钥匙似乎打不开暗格的小锁盒。你只能把锁盒带回给丽贝卡·马丁，希望里面正是她寻找的宝藏。", "小武哥儿"},
[26323] = {"未竟之事", "从托尔巴德岛找回乔治亚娜·马丁遗失的家族传家宝。", "你——对，就是你！冒险者！或许你愿意听我说！我向幽暗城的权贵们求助数周，却无人理会。我的家族在第二次战争前居住在托尔巴德岛，大多葬身于此，但一位叔叔逃脱了。临终前他说家族传家宝藏在岛上某处。但现在有传言说海盗抵达了托尔巴德！他们肯定冲着宝藏来的。听着，……我急需有人去岛上寻回宝藏。拿着这把钥匙！它能打开藏宝的暗格。求你，替我找回家族的传承！", "小武哥儿"},
[26324] = {"未竟之事", "将遗失的传家宝归还给幽暗城的乔治亚娜·马丁。", "你拿到的钥匙似乎打不开暗格的小锁盒。你只能把锁盒带回给乔治亚娜·马丁，希望里面正是她寻找的宝藏。", "小武哥儿"},
[26325] = {"埋藏的宝藏", "找到合适的工具挖掘你发现的土堆。", "这堆普通的土似乎没藏宝藏。你翻找松散的泥土时，手指触到了箱子的边缘，但感觉转瞬即逝。或许需要专用工具才能挖出箱子？", "小武哥儿"},
[26326] = {"地狱之路", "找人聊聊那个不祥的白球，了解更多信息。", "布莱克史东船长的宝箱里有个奇怪的乳白球体，泛着不祥的红光。你触摸它光滑的表面时，竟感到一丝安心。最好弄清楚这是什么。", "小武哥儿"},
[26328] = {"深入炼狱", "利用收集到的线索寻找布莱克斯通的宝藏。", "那三名船员说宝藏藏在菲拉斯的一个娜迦洞穴里？我对卡利姆多的情况一无所知，无法提供更多建议，但如果你搜索那片海岸线上的洞穴，我相信你会有所发现。另外，带上你在这里用来挖箱子的铲子，肯定用得上。再见了。但愿我们不必再见。", "小武哥儿"},
[26329] = {"另一段人生的梦想", "寻找布莱克斯通和他情妇的共同好友。或许布莱克斯通的日志会提供他朋友所在的线索？", "你没能找到宝藏和\"缚影者\"诅咒的起源，反而发现了一张字条，上面写着布莱克斯通为了保护船员把宝藏藏在了别处。这个高尚之举让你不得不继续承受帕雷斯之眼的诅咒。只有布莱克斯通的爱人知道宝藏的真正位置。找到她是解除诅咒的唯一希望。", "小武哥儿"},
[26330] = {"另一段人生的梦想", "保护帕拉·格里姆托特姆，让她带你前往宝藏地点。", "这座农场曾是我们的梦想。我想我一直都知道他最终回不来了。当私掠船员是危险的行当，后来他干脆做了海盗......我不知道布莱克斯通是怎么把宝藏运到这里的，但他把它藏在了附近的一个洞穴里。这大概是他给我的最后礼物，但我一直无法接近它——那里被来自帷幕另一侧的幽魂盘踞着。它们会阻挡我们。但既然你能在战斗中击败我的爱人，还能扛着诅咒找到这里，或许你也有能力解决它们。准备好出发就告诉我。", "小武哥儿"},
[26331] = {"掠夺海盗", "从霍金斯巢穴管理员处乘坐狮鹫调查海盗对托尔巴拉德的袭击。", "三个月前，我们的瞭望员在海平线上发现了帆船。他声称见过他们的旗帜，但恐惧使他无法回忆具体细节。不久后，炮声回荡在海面上。那个方向只有一座岛屿：托尔巴拉德，昔日的肯瑞托监狱所在。他们为何而来？是劫掠还是越狱？我充满好奇，而迷信的船员们惊恐不已。去找巢穴管理员霍金斯，请求飞往托尔巴拉德。我需要侦察兵查明岛上情况。", "小武哥儿"},
[26332] = {"掠夺海盗", "在阿拉希高地的法迪尔海湾找到钢肠船长。", "听好了！我从...某个盟友那里得知托尔巴拉德正在遭遇海袭。那座岛屿毫无价值，这份报告着实可疑。去法迪尔海湾找钢肠船长，告诉他是我派你来的。", "小武哥儿"},
[26333] = {"为船倾国", "收集温基要求的造船材料，送到塔纳利斯她所在的岛屿。", "我不会游泳，也懒得现在学！我需要材料造艘小船——不用太复杂。这是材料清单：西瘟疫伐木场的木材、随处可得的符文布、贸易商贩的线、海盗们的沥青罐。越快出发，你就能越早解除诅咒，我也能睡上正经床铺。", "小武哥儿"},
[26334] = {"为船倾国", "获取温基造船所需的工具。", "空手可造不了船！我需要工具组装材料，而你得帮我弄来——毕竟我没学游泳，光顾着做奶酪白日梦和晒日光浴了。需要：铁匠锤、电弧扳手、50把铜螺栓、侏儒尺寸的线锯。其中线锯只有诺莫瑞根出产！", "小武哥儿"},
[26335] = {"斯图尔的复仇", "确认洛琳·雷姆卡是死是活。", "我父亲为解救布莱克斯通和他的兽人船员而牺牲。那些兽人本是从收容所征召的，舰队覆灭后又被送了回去。父亲曾为他们请命，却被审判官塞尔格拉姆和监工洛琳·雷姆卡拒绝。塞尔格拉姆已死，但雷姆卡还活着。找到她的奴隶希腊克或随从沃里克，就能追查到她的下落。", "小武哥儿"},
[26336] = {"斯图尔的复仇", "杀死洛琳·雷姆卡。", "暴风城不会追究洛德瑞恩的陈年旧案，但我父亲的仇必须报。他让我立誓不向那些蠢货复仇，但我可以借你之手行事。杀死雷姆卡，血债血偿，我就告诉你想要的信息。", "小武哥儿"},
[26337] = {"死灵法师与后裔", "进入托尔巴拉德的巴拉丁监狱，击杀空心者阿斯蒂洛斯和纳兹拉萨什。", "听说巴拉丁监狱发生了小规模越狱。有两个囚犯绝不能放跑——他们都是可能危害幽暗城的强大法师。如果你愿意从阿拉希高地飞往托尔巴拉德解决他们，报酬不会少。", "小武哥儿"},
[26338] = {"巴拉丁监狱的陷落危机", "找军情七处成员获取巴拉丁监狱现状情报。", "作为暴风城海军上将，我收到了托尔巴拉德被海盗攻占的传闻。现在需要你前往核实——联盟需要你，冒险者。出发前先去军情七处打听消息。", "小武哥儿"},
[26339] = {"巴拉丁监狱的陷落危机", "调查托尔巴拉德岛上的巴拉丁监狱是否真遭海盗袭击。", "巴拉丁监狱关押着连科赞岛都关不住的恶徒！我们必须确认海盗是否控制了监狱。若情况属实，就由你现场决断应对方案。可从阿拉希高地的法迪尔海湾乘飞行坐骑前往。", "小武哥儿"},
[26340] = {"巴拉丁监狱的陷落危机", "击杀袭击巴拉丁监狱的海盗：格拉格特、卡吕普索、海盗领主布莱克斯通。", "最简单的方法就是消灭控制监狱的海盗。你需要杀穿整座监狱才能恢复秩序。", "小武哥儿"},
[26341] = {"巴拉丁监狱的陷落危机", "调查托尔巴拉德岛上的巴拉丁监狱是否真遭海盗袭击。", "部落的英雄！有传言说海盗占领了托尔巴拉德的监狱。我们需要查明真相。建议从阿拉希高地的法迪尔海湾乘坐飞行坐骑前往。", "小武哥儿"},
[26342] = {"巴拉丁监狱的陷落危机", "击杀袭击巴拉丁监狱的海盗：格鲁克、卡吕普索、海盗领主布莱克斯通。", "沃金指示你见机行事。直接剿灭控制监狱的海盗是最直接的解决方案。", "小武哥儿"},
[26343] = {"致我曾爱过的恶魔们", "进入托尔巴拉德的巴拉丁监狱，击杀莫鲁姆斯和达克玛尔。", "巴拉丁监狱有两名越狱囚犯可能会来暴风城找我麻烦。若你愿意从阿拉希高地飞往托尔巴拉德解决他们，必有重谢。", "小武哥儿"},
[26344] = {"投桃报李", "在荆棘谷找到奥格尔索普首领并消灭她。", "布莱克斯通将宝藏坐标分给了我和温基等人。但首先——黑水掠夺者的死对头奥格尔索普总在藏宝海湾外伏击我。除掉她，我就告诉你坐标线索。", "小武哥儿"},
[26345] = {"好消息", "前往棘齿城与卡蕾塔卡·冬颚讨论诺甘农圆盘。", "探险者协会破译了诺甘农圆盘上的部分符文！这些符文与牛头人古文相似。已联系到一位愿在棘齿城旅店与你见面的牛头人学者，这可能是开启奥丹姆的关键！", "小武哥儿"},
[26346] = {"激动人心的发现", "前往棘齿城与卡蕾塔卡·冬颚讨论诺甘农圆盘。", "我们需要精通牛头人语言的专家解读诺甘农圆盘。已安排卡蕾塔卡·冬颚在棘齿城断骨旅店与你接头——这些圆盘可能揭开奥丹姆的秘密！", "小武哥儿"},
[26347] = {"好消息", "在棘齿城通往费伍德森林的路上寻找卡蕾塔卡·冬颚。", "坦白说，和面对面让我紧张…但母亲认为有人跟踪我们，所以她提前出发去费伍德了。相信你能追上徒步的她。", "小武哥儿"},
[26348] = {"坏消息", "将噩耗带回给棘齿城的姆林·冬颚。", "卡蕾塔卡的尸体被洗劫一空。喉间一刀致命，附近泥地里的奇特蹄印证明她确实被跟踪了。", "小武哥儿"},
[26349] = {"坏消息", "将卡蕾塔卡的加密笔记带给铁炉堡的高级探险家麦格拉斯。", "母亲遇害前留给你这张加密字条，愿它能帮上忙。原谅我不想再见到任何了。", "小武哥儿"},
[26350] = {"又是好消息", "与铁炉堡探险者大厅的历史学家卡尼克交谈。", "我会解密字条，但其他人已破译出奥杜尔钢板的线索。想了解更多就去找历史学家卡尼克。", "小武哥儿"},
[26351] = {"又是好消息", "在冬泉谷的暗语峡谷搜寻奥杜尔钢板的线索。", "线索表明奥杜尔钢板藏在常年烟雾缭绕的峡谷或洞穴中。考虑到拉格纳罗斯降临前的历史，最可能的地点是冬泉谷的暗语峡谷。去那里搜寻吧。", "小武哥儿"},
[26352] = {"又是坏消息", "将大地召唤者的警告带给铁炉堡的历史学家卡尼克。", "你们追寻奥杜尔钢板的勇气令人敬佩…但连泰坦都没准备好面对门后的存在。停止吧，否则会释放难以言喻的灾祸。", "小武哥儿"},
[26353] = {"好消息", "前往藏宝海湾与海德里格·铁石讨论诺甘农圆盘。", "传承者破译了诺甘农圆盘上的矮人古文！已安排铁石在棘齿城旅店与你接头——这可能是开启奥丹姆的关键！", "小武哥儿"},
[26354] = {"激动人心的发现", "前往棘齿城与海德里格·铁石讨论诺甘农圆盘。", "我们需要矮人语专家解读诺甘农圆盘。已安排海德里格·铁石在棘齿城酒馆与你见面——这些圆盘可能揭开奥丹姆之谜！", "小武哥儿"},
[26355] = {"好消息", "在棘齿城通往费伍德森林的路上寻找海德里格·铁石。", "老爹觉得被人跟踪，所以独自去了费伍德。我相信他能自保，但希望你尽快追上他。", "小武哥儿"},
[26356] = {"坏消息", "将噩耗带回给棘齿城的奈莉·铁石。", "海德里格的尸体被洗劫一空。喉间一刀致命，附近的陌生脚印证明他确实被跟踪了。", "小武哥儿"},
[26357] = {"坏消息", "将海德里格的加密信息带给雷霆崖的智者寻真者。", "老爹留下的加密字条或许对你有用。原谅我不想再见到任何了。", "小武哥儿"},
[26358] = {"又是好消息", "与雷霆崖灵魂高地的智者纳莎交谈。", "其他传承者可能已破译出奥杜尔钢板的位置。想了解更多就去灵魂高地找智者纳莎。", "小武哥儿"},
[26359] = {"又是好消息", "在冬泉谷的暗语峡谷搜寻奥杜尔钢板的线索。", "线索指向常年烟雾缭绕的暗语峡谷——那里在拉格纳罗斯苏醒前就已存在。去搜索峡谷，任何发现都值得回报。", "小武哥儿"},
[26360] = {"又是坏消息", "将大地召唤者的警告带回给雷霆崖的智者纳莎。", "追寻奥杜尔钢板的代价远超你们的想象。连泰坦都选择将那些秘密永世封存。，就此收手吧。", "小武哥儿"},
[26361] = {"遭遇战召集：石爪山脉", "在石爪山脉击杀5名部落成员。", "用武力证明石爪山脉属于联盟！猎杀部落成员以提升军阶。", "小武哥儿"},
[26362] = {"遭遇战召集：石爪山脉", "在石爪山脉击杀5名联盟成员。", "用武力证明石爪山脉属于部落！猎杀联盟成员以提升军阶。", "小武哥儿"},
[26363] = {"遭遇战召集：灰谷", "在灰谷击杀5名部落成员。", "用鲜血捍卫灰谷的联盟主权！每杀一名部落成员都是向胜利迈进。", "小武哥儿"},
[26364] = {"遭遇战召集：灰谷", "在灰谷击杀5名联盟成员。", "用鲜血扞卫灰谷的部落主权！每杀一名联盟成员都是向荣耀迈进。", "小武哥儿"},
